'use client'

import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useEffect, useState } from 'react'
import Link from 'next/link'
import { ArrowLeft, Lock, Smartphone, _AlertCircle, CheckCircle, Eye, EyeOff } from 'lucide-react'

interface Session {
  id: string
  userAgent: string
  ipAddress: string
  lastActive: string
  isCurrent: boolean
}

interface SecuritySettings {
  twoFactorEnabled: boolean
  recoveryCodesCount: number
  passwordLastChanged: string
  activeSessions: Session[]
  loginAttempts: Array<{
    timestamp: string
    ipAddress: string
    status: 'success' | 'failed'
    device: string
  }>
}

export default function AccountSecurityPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [security, setSecurity] = useState<SecuritySettings | null>(null)
  const [loading, setLoading] = useState(true)

  // Password change form
  const [showPasswordForm, setShowPasswordForm] = useState(false)
  const [currentPassword, setCurrentPassword] = useState('')
  const [newPassword, setNewPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [showPasswords, setShowPasswords] = useState({ current: false, new: false, confirm: false })
  const [changingPassword, setChangingPassword] = useState(false)

  // 2FA states
  const [show2FASetup, setShow2FASetup] = useState(false)
  const [qrCode, setQrCode] = useState('')

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (status !== 'authenticated') return

    fetchSecuritySettings()
  }, [status, router])

  const fetchSecuritySettings = async () => {
    try {
      setLoading(true)
      const response = await fetch('/api/account/security')
      if (response.ok) {
        const data = await response.json()
        setSecurity(data.settings)
      }
    } catch (error) {
      console.error('Failed to fetch security settings:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleChangePassword = async () => {
    if (!currentPassword || !newPassword || !confirmPassword) {
      alert('Please fill in all password fields')
      return
    }

    if (newPassword !== confirmPassword) {
      alert('New passwords do not match')
      return
    }

    if (newPassword.length < 8) {
      alert('New password must be at least 8 characters')
      return
    }

    try {
      setChangingPassword(true)
      const response = await fetch('/api/account/security/password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          currentPassword,
          newPassword,
        }),
      })

      if (response.ok) {
        setShowPasswordForm(false)
        setCurrentPassword('')
        setNewPassword('')
        setConfirmPassword('')
        alert('Password changed successfully')
        await fetchSecuritySettings()
      } else {
        alert('Failed to change password')
      }
    } catch (error) {
      console.error('Failed to change password:', error)
    } finally {
      setChangingPassword(false)
    }
  }

  const handleEnable2FA = async () => {
    try {
      const response = await fetch('/api/account/security/2fa/setup', {
        method: 'POST',
      })
      if (response.ok) {
        const data = await response.json()
        setQrCode(data.qrCode)
        setShow2FASetup(true)
      }
    } catch (error) {
      console.error('Failed to setup 2FA:', error)
    }
  }

  const handleDisable2FA = async () => {
    if (!confirm('Disable two-factor authentication?')) return

    try {
      const response = await fetch('/api/account/security/2fa/disable', {
        method: 'POST',
      })
      if (response.ok) {
        alert('2FA disabled')
        await fetchSecuritySettings()
      }
    } catch (error) {
      console.error('Failed to disable 2FA:', error)
    }
  }

  const handleSignOutSession = async (sessionId: string) => {
    try {
      const response = await fetch(`/api/account/security/sessions/${sessionId}`, {
        method: 'DELETE',
      })
      if (response.ok) {
        await fetchSecuritySettings()
      }
    } catch (error) {
      console.error('Failed to sign out session:', error)
    }
  }

  if (loading) {
    return <div className="p-8 text-center">Loading security settings...</div>
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 md:p-8">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <Link href="/profile/settings" className="p-2 hover:bg-gray-200 rounded-lg transition">
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Security Settings</h1>
            <p className="text-gray-600 mt-1">Manage your account security and privacy</p>
          </div>
        </div>

        {/* Password Section */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <h2 className="text-xl font-semibold text-gray-900 mb-4 flex items-center gap-2">
            <Lock className="w-5 h-5" />
            Password
          </h2>

          <div className="flex items-center justify-between p-4 bg-gray-50 rounded-lg mb-4">
            <div>
              <p className="font-medium text-gray-900">Change Password</p>
              <p className="text-sm text-gray-600 mt-1">
                Last changed: {security ? new Date(security.passwordLastChanged).toLocaleDateString() : 'Unknown'}
              </p>
            </div>
            {!showPasswordForm && (
              <button
                onClick={() => setShowPasswordForm(true)}
                className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition text-sm"
              >
                Change
              </button>
            )}
          </div>

          {showPasswordForm && (
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-900 mb-2">Current Password *</label>
                <div className="relative">
                  <input
                    type={showPasswords.current ? 'text' : 'password'}
                    value={currentPassword}
                    onChange={(e) => setCurrentPassword(e.target.value)}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg text-black pr-10"
                  />
                  <button
                    onClick={() => setShowPasswords({ ...showPasswords, current: !showPasswords.current })}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500 hover:text-gray-700"
                  >
                    {showPasswords.current ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </button>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-900 mb-2">New Password *</label>
                <div className="relative">
                  <input
                    type={showPasswords.new ? 'text' : 'password'}
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg text-black pr-10"
                  />
                  <button
                    onClick={() => setShowPasswords({ ...showPasswords, new: !showPasswords.new })}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500 hover:text-gray-700"
                  >
                    {showPasswords.new ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </button>
                </div>
                <p className="text-xs text-gray-600 mt-1">At least 8 characters</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-900 mb-2">Confirm Password *</label>
                <div className="relative">
                  <input
                    type={showPasswords.confirm ? 'text' : 'password'}
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg text-black pr-10"
                  />
                  <button
                    onClick={() => setShowPasswords({ ...showPasswords, confirm: !showPasswords.confirm })}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500 hover:text-gray-700"
                  >
                    {showPasswords.confirm ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </button>
                </div>
              </div>

              <div className="flex gap-2 justify-end">
                <button
                  onClick={() => setShowPasswordForm(false)}
                  className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  onClick={handleChangePassword}
                  disabled={changingPassword}
                  className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition disabled:opacity-50"
                >
                  Update Password
                </button>
              </div>
            </div>
          )}
        </div>

        {/* 2FA Section */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <h2 className="text-xl font-semibold text-gray-900 mb-4 flex items-center gap-2">
            <Smartphone className="w-5 h-5" />
            Two-Factor Authentication
          </h2>

          <div className="flex items-center justify-between p-4 bg-gray-50 rounded-lg">
            <div>
              <p className="font-medium text-gray-900">Secure Your Account</p>
              <p className="text-sm text-gray-600 mt-1">
                {security?.twoFactorEnabled
                  ? 'Γ£ô Enabled - Your account is protected'
                  : 'Add an extra layer of security to your account'}
              </p>
            </div>
            {!security?.twoFactorEnabled ? (
              <button
                onClick={handleEnable2FA}
                className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition text-sm"
              >
                Enable
              </button>
            ) : (
              <button
                onClick={handleDisable2FA}
                className="px-4 py-2 border border-red-300 text-red-700 rounded-lg hover:bg-red-50 transition text-sm"
              >
                Disable
              </button>
            )}
          </div>

          {security?.twoFactorEnabled && security.recoveryCodesCount > 0 && (
            <div className="mt-4 p-4 bg-green-50 border border-green-200 rounded-lg">
              <p className="text-sm text-green-900 flex items-center gap-2">
                <CheckCircle className="w-4 h-4" />
                {security.recoveryCodesCount} recovery codes saved
              </p>
            </div>
          )}
        </div>

        {/* Active Sessions */}
        {security && security.activeSessions.length > 0 && (
          <div className="bg-white rounded-lg shadow-sm p-6">
            <h2 className="text-xl font-semibold text-gray-900 mb-4">Active Sessions</h2>
            <div className="space-y-3">
              {security.activeSessions.map((sess) => (
                <div key={sess.id} className="flex items-center justify-between p-4 bg-gray-50 rounded-lg">
                  <div className="flex-1">
                    <p className="font-medium text-gray-900">{sess.userAgent}</p>
                    <p className="text-sm text-gray-600 mt-1">{sess.ipAddress}</p>
                    <p className="text-xs text-gray-500 mt-1">
                      Last active: {new Date(sess.lastActive).toLocaleString()}
                      {sess.isCurrent && ' (Current)'}
                    </p>
                  </div>
                  {!sess.isCurrent && (
                    <button
                      onClick={() => handleSignOutSession(sess.id)}
                      className="px-3 py-2 border border-red-300 text-red-700 rounded-lg hover:bg-red-50 transition text-sm"
                    >
                      Sign Out
                    </button>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import {
  TrendingUp,
  TrendingDown,
  Users,
  ShoppingBag,
  DollarSign,
  Package,
  ArrowLeft,
  Loader2,
  AlertCircle,
  BarChart3,
  PieChart,
  Activity,
  RefreshCw,
  Store,
  CreditCard,
  ShoppingCart,
} from 'lucide-react'

interface AnalyticsData {
  overview: {
    totalRevenue: number
    platformEarnings: number
    totalOrders: number
    totalUsers: number
    totalSellers: number
    totalDesigns: number
    revenueChange: number
    ordersChange: number
    usersChange: number
  }
  daily: {
    date: string
    revenue: number
    orders: number
    signups: number
  }[]
  topDesigns: {
    id: string
    title: string
    sales: number
    revenue: number
    designer: string
  }[]
  topSellers: {
    id: string
    name: string
    email: string
    sales: number
    revenue: number
    designs: number
  }[]
  ordersByStatus: {
    status: string
    count: number
  }[]
  revenueByCategory: {
    category: string
    revenue: number
    count: number
  }[]
  userGrowth: {
    month: string
    users: number
    sellers: number
  }[]
}

export default function AdminAnalyticsPage() {
  const { data: session, status: authStatus } = useSession()
  const router = useRouter()
  const [loading, setLoading] = useState(true)
  const [data, setData] = useState<AnalyticsData | null>(null)
  const [dateRange, setDateRange] = useState('30')
  const [error, setError] = useState('')

  useEffect(() => {
    if (authStatus === 'loading') return
    if (!session || session.user?.role !== 'ADMIN') {
      router.push('/')
      return
    }
    fetchAnalytics()
  }, [session, authStatus, router, dateRange])

  const fetchAnalytics = async () => {
    setLoading(true)
    setError('')
    try {
      const response = await fetch(`/api/admin/analytics?days=${dateRange}`)
      if (response.ok) {
        const result = await response.json()
        setData(result)
      } else {
        // Fallback to stats endpoint if analytics doesn't exist
        const statsResponse = await fetch('/api/admin/stats')
        if (statsResponse.ok) {
          const statsData = await statsResponse.json()
          setData({
            overview: {
              totalRevenue: statsData.stats?.totalRevenue || 0,
              platformEarnings: statsData.stats?.platformEarnings || 0,
              totalOrders: statsData.stats?.totalOrders || 0,
              totalUsers: statsData.stats?.totalUsers || 0,
              totalSellers: statsData.stats?.activeUsers || 0,
              totalDesigns: statsData.stats?.totalDesigns || 0,
              revenueChange: 0,
              ordersChange: 0,
              usersChange: 0,
            },
            daily: [],
            topDesigns: [],
            topSellers: [],
            ordersByStatus: [],
            revenueByCategory: [],
            userGrowth: [],
          })
        } else {
          setError('Failed to load analytics data')
        }
      }
    } catch (error) {
      console.error('Failed to fetch analytics:', error)
      setError('Failed to load analytics data')
    } finally {
      setLoading(false)
    }
  }

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(amount)
  }

  const formatNumber = (num: number) => {
    if (num >= 1000000) {
      return (num / 1000000).toFixed(1) + 'M'
    }
    if (num >= 1000) {
      return (num / 1000).toFixed(1) + 'K'
    }
    return num.toString()
  }

  const getChangeIndicator = (change: number) => {
    if (change > 0) {
      return (
        <span className="inline-flex items-center text-sm text-green-600">
          <TrendingUp className="w-4 h-4 mr-1" />
          +{change.toFixed(1)}%
        </span>
      )
    } else if (change < 0) {
      return (
        <span className="inline-flex items-center text-sm text-red-600">
          <TrendingDown className="w-4 h-4 mr-1" />
          {change.toFixed(1)}%
        </span>
      )
    }
    return <span className="text-sm text-gray-500">No change</span>
  }

  if (authStatus === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-indigo-600" />
      </div>
    )
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <AlertCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-gray-900 mb-2">Error Loading Analytics</h1>
          <p className="text-gray-600 mb-6">{error}</p>
          <button
            onClick={fetchAnalytics}
            className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
          >
            <RefreshCw className="w-4 h-4" />
            Try Again
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 py-4 sm:py-8">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 sm:gap-4 mb-4 sm:mb-8">
          <div>
            <Link
              href="/admin"
              className="inline-flex items-center text-xs sm:text-sm text-gray-500 hover:text-gray-700 mb-1 sm:mb-2"
            >
              <ArrowLeft className="w-3 h-3 sm:w-4 sm:h-4 mr-1" />
              Back to Admin
            </Link>
            <h1 className="text-xl sm:text-2xl font-bold text-gray-900">Analytics</h1>
            <p className="text-xs sm:text-base text-gray-600 mt-0.5 sm:mt-1">Platform performance metrics</p>
          </div>
          <div className="flex items-center gap-2 sm:gap-3">
            <select
              value={dateRange}
              onChange={(e) => setDateRange(e.target.value)}
              className="text-xs sm:text-sm border border-gray-300 rounded-lg px-2 sm:px-3 py-1.5 sm:py-2 text-gray-900 focus:ring-indigo-500 focus:border-indigo-500"
              aria-label="Select date range"
            >
              <option value="7">7 days</option>
              <option value="30">30 days</option>
              <option value="90">3 months</option>
              <option value="365">1 year</option>
            </select>
            <button
              onClick={fetchAnalytics}
              className="inline-flex items-center gap-1 sm:gap-2 px-2 sm:px-3 py-1.5 sm:py-2 border border-gray-300 rounded-lg hover:bg-gray-50 text-xs sm:text-sm"
            >
              <RefreshCw className="w-3 h-3 sm:w-4 sm:h-4" />
              <span className="hidden xs:inline">Refresh</span>
            </button>
          </div>
        </div>

        {/* Overview Stats */}
        <div className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-6 mb-4 sm:mb-8">
          {/* Revenue */}
          <div className="bg-white rounded-xl shadow-sm p-3 sm:p-6">
            <div className="flex items-center justify-between mb-2 sm:mb-4">
              <div className="w-8 h-8 sm:w-12 sm:h-12 bg-green-100 rounded-lg flex items-center justify-center">
                <DollarSign className="w-4 h-4 sm:w-6 sm:h-6 text-green-600" />
              </div>
              <span className="text-xs">{getChangeIndicator(data?.overview.revenueChange || 0)}</span>
            </div>
            <p className="text-[10px] sm:text-sm text-gray-500">Total Revenue</p>
            <p className="text-lg sm:text-3xl font-bold text-gray-900">
              {formatCurrency(data?.overview.totalRevenue || 0)}
            </p>
            <p className="text-[10px] sm:text-sm text-gray-400 mt-0.5 sm:mt-1">
              Platform: {formatCurrency(data?.overview.platformEarnings || 0)}
            </p>
          </div>

          {/* Orders */}
          <div className="bg-white rounded-xl shadow-sm p-3 sm:p-6">
            <div className="flex items-center justify-between mb-2 sm:mb-4">
              <div className="w-8 h-8 sm:w-12 sm:h-12 bg-blue-100 rounded-lg flex items-center justify-center">
                <ShoppingBag className="w-4 h-4 sm:w-6 sm:h-6 text-blue-600" />
              </div>
              <span className="text-xs">{getChangeIndicator(data?.overview.ordersChange || 0)}</span>
            </div>
            <p className="text-[10px] sm:text-sm text-gray-500">Total Orders</p>
            <p className="text-lg sm:text-3xl font-bold text-gray-900">
              {formatNumber(data?.overview.totalOrders || 0)}
            </p>
          </div>

          {/* Users */}
          <div className="bg-white rounded-xl shadow-sm p-3 sm:p-6">
            <div className="flex items-center justify-between mb-2 sm:mb-4">
              <div className="w-8 h-8 sm:w-12 sm:h-12 bg-purple-100 rounded-lg flex items-center justify-center">
                <Users className="w-4 h-4 sm:w-6 sm:h-6 text-purple-600" />
              </div>
              <span className="text-xs">{getChangeIndicator(data?.overview.usersChange || 0)}</span>
            </div>
            <p className="text-[10px] sm:text-sm text-gray-500">Total Users</p>
            <p className="text-lg sm:text-3xl font-bold text-gray-900">
              {formatNumber(data?.overview.totalUsers || 0)}
            </p>
            <p className="text-[10px] sm:text-sm text-gray-400 mt-0.5 sm:mt-1">
              {formatNumber(data?.overview.totalSellers || 0)} sellers
            </p>
          </div>

          {/* Designs */}
          <div className="bg-white rounded-xl shadow-sm p-3 sm:p-6">
            <div className="flex items-center justify-between mb-2 sm:mb-4">
              <div className="w-8 h-8 sm:w-12 sm:h-12 bg-orange-100 rounded-lg flex items-center justify-center">
                <Package className="w-4 h-4 sm:w-6 sm:h-6 text-orange-600" />
              </div>
            </div>
            <p className="text-[10px] sm:text-sm text-gray-500">Total Designs</p>
            <p className="text-lg sm:text-3xl font-bold text-gray-900">
              {formatNumber(data?.overview.totalDesigns || 0)}
            </p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 sm:gap-8 mb-4 sm:mb-8">
          {/* Top Selling Designs */}
          <div className="bg-white rounded-xl shadow-sm">
            <div className="p-3 sm:p-6 border-b border-gray-200">
              <div className="flex items-center justify-between">
                <h2 className="text-sm sm:text-lg font-semibold text-gray-900">Top Selling Designs</h2>
                <BarChart3 className="w-4 h-4 sm:w-5 sm:h-5 text-gray-400" />
              </div>
            </div>
            <div className="p-3 sm:p-6">
              {data?.topDesigns && data.topDesigns.length > 0 ? (
                <div className="space-y-3 sm:space-y-4">
                  {data.topDesigns.slice(0, 5).map((design, index) => (
                    <div key={design.id} className="flex items-center gap-2 sm:gap-4">
                      <div className="w-6 h-6 sm:w-8 sm:h-8 bg-indigo-100 rounded-lg flex items-center justify-center text-xs sm:text-sm font-bold text-indigo-600">
                        {index + 1}
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-xs sm:text-base font-medium text-gray-900 truncate">{design.title}</p>
                        <p className="text-[10px] sm:text-sm text-gray-500">{design.designer}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-xs sm:text-base font-semibold text-gray-900">{formatCurrency(design.revenue)}</p>
                        <p className="text-[10px] sm:text-sm text-gray-500">{design.sales} sales</p>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-6 sm:py-8 text-gray-500">
                  <ShoppingCart className="w-8 h-8 sm:w-12 sm:h-12 mx-auto mb-2 sm:mb-3 text-gray-300" />
                  <p className="text-xs sm:text-base">No sales data available</p>
                </div>
              )}
            </div>
          </div>

          {/* Top Sellers */}
          <div className="bg-white rounded-xl shadow-sm">
            <div className="p-3 sm:p-6 border-b border-gray-200">
              <div className="flex items-center justify-between">
                <h2 className="text-sm sm:text-lg font-semibold text-gray-900">Top Sellers</h2>
                <Store className="w-4 h-4 sm:w-5 sm:h-5 text-gray-400" />
              </div>
            </div>
            <div className="p-3 sm:p-6">
              {data?.topSellers && data.topSellers.length > 0 ? (
                <div className="space-y-3 sm:space-y-4">
                  {data.topSellers.slice(0, 5).map((seller, index) => (
                    <div key={seller.id} className="flex items-center gap-2 sm:gap-4">
                      <div className="w-6 h-6 sm:w-8 sm:h-8 bg-green-100 rounded-lg flex items-center justify-center text-xs sm:text-sm font-bold text-green-600">
                        {index + 1}
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-xs sm:text-base font-medium text-gray-900 truncate">
                          {seller.name || 'Anonymous'}
                        </p>
                        <p className="text-[10px] sm:text-sm text-gray-500">{seller.designs} designs</p>
                      </div>
                      <div className="text-right">
                        <p className="text-xs sm:text-base font-semibold text-gray-900">{formatCurrency(seller.revenue)}</p>
                        <p className="text-[10px] sm:text-sm text-gray-500">{seller.sales} sales</p>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-6 sm:py-8 text-gray-500">
                  <Users className="w-8 h-8 sm:w-12 sm:h-12 mx-auto mb-2 sm:mb-3 text-gray-300" />
                  <p className="text-xs sm:text-base">No seller data available</p>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 sm:gap-8 mb-4 sm:mb-8">
          {/* Orders by Status */}
          <div className="bg-white rounded-xl shadow-sm">
            <div className="p-3 sm:p-6 border-b border-gray-200">
              <div className="flex items-center justify-between">
                <h2 className="text-sm sm:text-lg font-semibold text-gray-900">Orders by Status</h2>
                <PieChart className="w-4 h-4 sm:w-5 sm:h-5 text-gray-400" />
              </div>
            </div>
            <div className="p-3 sm:p-6">
              {data?.ordersByStatus && data.ordersByStatus.length > 0 ? (
                <div className="space-y-2 sm:space-y-3">
                  {data.ordersByStatus.map((item) => {
                    const total = data.ordersByStatus.reduce((sum, i) => sum + i.count, 0)
                    const percentage = total > 0 ? (item.count / total) * 100 : 0
                    const colors: Record<string, string> = {
                      PENDING: 'bg-yellow-500',
                      PAID: 'bg-green-500',
                      COMPLETED: 'bg-blue-500',
                      CANCELLED: 'bg-red-500',
                      REFUNDED: 'bg-gray-500',
                    }
                    return (
                      <div key={item.status}>
                        <div className="flex justify-between text-xs sm:text-sm mb-1">
                          <span className="text-gray-600 capitalize">{item.status.toLowerCase()}</span>
                          <span className="font-medium text-gray-900">{item.count}</span>
                        </div>
                        <div className="w-full bg-gray-100 rounded-full h-1.5 sm:h-2">
                          <div
                            className={`h-1.5 sm:h-2 rounded-full ${colors[item.status] || 'bg-gray-400'}`}
                            style={{ width: `${percentage}%` }}
                          />
                        </div>
                      </div>
                    )
                  })}
                </div>
              ) : (
                <div className="text-center py-6 sm:py-8 text-gray-500">
                  <Activity className="w-8 h-8 sm:w-12 sm:h-12 mx-auto mb-2 sm:mb-3 text-gray-300" />
                  <p className="text-xs sm:text-base">No order data available</p>
                </div>
              )}
            </div>
          </div>

          {/* Revenue by Category */}
          <div className="bg-white rounded-xl shadow-sm">
            <div className="p-3 sm:p-6 border-b border-gray-200">
              <div className="flex items-center justify-between">
                <h2 className="text-sm sm:text-lg font-semibold text-gray-900">Revenue by Category</h2>
                <BarChart3 className="w-4 h-4 sm:w-5 sm:h-5 text-gray-400" />
              </div>
            </div>
            <div className="p-3 sm:p-6">
              {data?.revenueByCategory && data.revenueByCategory.length > 0 ? (
                <div className="space-y-2 sm:space-y-3">
                  {data.revenueByCategory.map((item) => {
                    const maxRevenue = Math.max(...data.revenueByCategory.map((i) => i.revenue))
                    const percentage = maxRevenue > 0 ? (item.revenue / maxRevenue) * 100 : 0
                    return (
                      <div key={item.category}>
                        <div className="flex justify-between text-xs sm:text-sm mb-1">
                          <span className="text-gray-600">{item.category}</span>
                          <span className="font-medium text-gray-900">{formatCurrency(item.revenue)}</span>
                        </div>
                        <div className="w-full bg-gray-100 rounded-full h-1.5 sm:h-2">
                          <div
                            className="h-1.5 sm:h-2 rounded-full bg-indigo-500"
                            style={{ width: `${percentage}%` }}
                          />
                        </div>
                      </div>
                    )
                  })}
                </div>
              ) : (
                <div className="text-center py-6 sm:py-8 text-gray-500">
                  <CreditCard className="w-8 h-8 sm:w-12 sm:h-12 mx-auto mb-2 sm:mb-3 text-gray-300" />
                  <p className="text-xs sm:text-base">No category data available</p>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Quick Actions */}
        <div className="bg-white rounded-xl shadow-sm p-3 sm:p-6">
          <h2 className="text-sm sm:text-lg font-semibold text-gray-900 mb-3 sm:mb-4">Quick Actions</h2>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-2 sm:gap-4">
            <Link
              href="/admin?tab=users"
              className="flex flex-col items-center p-2 sm:p-4 border border-gray-200 rounded-lg hover:border-indigo-300 hover:bg-indigo-50 transition-colors"
            >
              <Users className="w-5 h-5 sm:w-8 sm:h-8 text-indigo-600 mb-1 sm:mb-2" />
              <span className="text-[10px] sm:text-sm font-medium text-gray-900 text-center">Manage Users</span>
            </Link>
            <Link
              href="/admin?tab=designs"
              className="flex flex-col items-center p-2 sm:p-4 border border-gray-200 rounded-lg hover:border-indigo-300 hover:bg-indigo-50 transition-colors"
            >
              <Package className="w-5 h-5 sm:w-8 sm:h-8 text-indigo-600 mb-1 sm:mb-2" />
              <span className="text-[10px] sm:text-sm font-medium text-gray-900 text-center">Review Designs</span>
            </Link>
            <Link
              href="/admin?tab=orders"
              className="flex flex-col items-center p-2 sm:p-4 border border-gray-200 rounded-lg hover:border-indigo-300 hover:bg-indigo-50 transition-colors"
            >
              <ShoppingBag className="w-5 h-5 sm:w-8 sm:h-8 text-indigo-600 mb-1 sm:mb-2" />
              <span className="text-[10px] sm:text-sm font-medium text-gray-900 text-center">View Orders</span>
            </Link>
            <Link
              href="/admin/boutique"
              className="flex flex-col items-center p-2 sm:p-4 border border-gray-200 rounded-lg hover:border-indigo-300 hover:bg-indigo-50 transition-colors"
            >
              <Store className="w-5 h-5 sm:w-8 sm:h-8 text-indigo-600 mb-1 sm:mb-2" />
              <span className="text-[10px] sm:text-sm font-medium text-gray-900 text-center">Boutique</span>
            </Link>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useEffect, useState } from 'react'
import toast from 'react-hot-toast'
import {
  ArrowLeft,
  Search,
  _Filter,
  _Calendar,
  ChevronDown,
  Loader,
  Download,
} from 'lucide-react'

interface AuditLogEntry {
  id: string
  action: string
  category: string
  actorType: string
  actorEmail: string | null
  targetType: string
  targetId: string
  success: boolean
  errorMessage: string | null
  metadata: any
  createdAt: string
}

type TimeRange = '24h' | '7d' | '30d' | 'all'

export default function AdminAuditLogsPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [logs, setLogs] = useState<AuditLogEntry[]>([])
  const [filteredLogs, setFilteredLogs] = useState<AuditLogEntry[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedCategory, setSelectedCategory] = useState<string>('all')
  const [selectedAction, setSelectedAction] = useState<string>('all')
  const [timeRange, setTimeRange] = useState<TimeRange>('7d')
  const [expandedId, setExpandedId] = useState<string | null>(null)
  const [categories, setCategories] = useState<string[]>([])
  const [actions, setActions] = useState<string[]>([])

  const CATEGORIES = [
    'PAYMENT',
    'PAYOUT',
    'REFUND',
    'DISPUTE',
    'STATUS_CHANGE',
    'USER_ACTION',
    'SYSTEM',
  ]

  useEffect(() => {
    if (status === 'loading') {
      return
    }
    if (status === 'unauthenticated') {
      router.push('/auth/signin')
      return
    }

    if (session?.user?.role !== 'ADMIN') {
      router.push('/admin')
      return
    }

    fetchLogs()
  }, [status, session, router])

  useEffect(() => {
    applyFilters()
  }, [logs, searchQuery, selectedCategory, selectedAction, timeRange])

  const fetchLogs = async () => {
    try {
      setLoading(true)
      const response = await fetch('/api/admin/audit-logs?limit=1000')

      if (!response.ok) {
        throw new Error('Failed to fetch audit logs')
      }

      const data = await response.json()
      setLogs(data.logs)

      // Extract unique categories and actions
      const uniqueCategories = Array.from(
        new Set(data.logs.map((log: AuditLogEntry) => log.category))
      ) as string[]
      const uniqueActions = Array.from(
        new Set(data.logs.map((log: AuditLogEntry) => log.action))
      ) as string[]

      setCategories(uniqueCategories)
      setActions(uniqueActions)
    } catch (error) {
      toast.error('Failed to load audit logs')
      console.error(error)
    } finally {
      setLoading(false)
    }
  }

  const applyFilters = () => {
    let filtered = [...logs]

    // Time range filter
    const now = new Date()
    const filterDate = new Date()

    switch (timeRange) {
      case '24h':
        filterDate.setHours(now.getHours() - 24)
        break
      case '7d':
        filterDate.setDate(now.getDate() - 7)
        break
      case '30d':
        filterDate.setDate(now.getDate() - 30)
        break
      default:
        filterDate.setFullYear(1970)
    }

    filtered = filtered.filter(
      (log) => new Date(log.createdAt) >= filterDate
    )

    // Category filter
    if (selectedCategory !== 'all') {
      filtered = filtered.filter((log) => log.category === selectedCategory)
    }

    // Action filter
    if (selectedAction !== 'all') {
      filtered = filtered.filter((log) => log.action === selectedAction)
    }

    // Search filter
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase()
      filtered = filtered.filter(
        (log) =>
          log.action.toLowerCase().includes(query) ||
          log.actorEmail?.toLowerCase().includes(query) ||
          log.targetId.toLowerCase().includes(query) ||
          (log.errorMessage || '').toLowerCase().includes(query)
      )
    }

    setFilteredLogs(filtered)
  }

  const downloadCSV = () => {
    if (filteredLogs.length === 0) {
      toast.error('No logs to download')
      return
    }

    const headers = ['Timestamp', 'Action', 'Category', 'Actor', 'Target', 'Status', 'Details']
    const rows = filteredLogs.map((log) => [
      new Date(log.createdAt).toLocaleString(),
      log.action,
      log.category,
      log.actorEmail || log.actorType,
      `${log.targetType}#${log.targetId}`,
      log.success ? 'SUCCESS' : 'FAILED',
      log.errorMessage || '',
    ])

    let csv = headers.join(',') + '\n'
    rows.forEach((row) => {
      csv += row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(',') + '\n'
    })

    const element = document.createElement('a')
    element.setAttribute(
      'href',
      'data:text/csv;charset=utf-8,' + encodeURIComponent(csv)
    )
    element.setAttribute('download', `audit-logs-${new Date().toISOString().split('T')[0]}.csv`)
    element.style.display = 'none'
    document.body.appendChild(element)
    element.click()
    document.body.removeChild(element)
    toast.success('Downloaded audit logs')
  }

  if (status !== 'authenticated' || session?.user?.role !== 'ADMIN') {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader className="animate-spin text-primary-600" size={32} />
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <button
            onClick={() => router.back()}
            className="flex items-center gap-2 text-primary-600 hover:text-primary-700 mb-4 transition"
          >
            <ArrowLeft size={20} />
            Back
          </button>

          <div className="flex justify-between items-start">
            <div>
              <h1 className="text-3xl font-bold text-gray-900">Audit Logs</h1>
              <p className="text-gray-600 mt-1">
                Track all administrative actions and system events
              </p>
            </div>
            <button
              onClick={downloadCSV}
              disabled={filteredLogs.length === 0}
              className="flex items-center gap-2 bg-primary-600 text-white px-4 py-2 rounded-lg hover:bg-primary-700 transition font-medium disabled:bg-gray-400"
            >
              <Download size={18} />
              Export CSV
            </button>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-sm p-4 md:p-6 mb-6">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {/* Search */}
            <div className="relative">
              <Search
                size={18}
                className="absolute left-3 top-3 text-gray-400"
              />
              <input
                type="text"
                placeholder="Search action, email, ID..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              />
            </div>

            {/* Category Filter */}
            <select
              value={selectedCategory}
              onChange={(e) => setSelectedCategory(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent bg-white cursor-pointer"
            >
              <option value="all">All Categories</option>
              {CATEGORIES.map((cat) => (
                <option key={cat} value={cat}>
                  {cat}
                </option>
              ))}
            </select>

            {/* Action Filter */}
            <select
              value={selectedAction}
              onChange={(e) => setSelectedAction(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent bg-white cursor-pointer"
            >
              <option value="all">All Actions</option>
              {actions.map((action) => (
                <option key={action} value={action}>
                  {action}
                </option>
              ))}
            </select>

            {/* Time Range */}
            <select
              value={timeRange}
              onChange={(e) => setTimeRange(e.target.value as TimeRange)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent bg-white cursor-pointer"
            >
              <option value="24h">Last 24 Hours</option>
              <option value="7d">Last 7 Days</option>
              <option value="30d">Last 30 Days</option>
              <option value="all">All Time</option>
            </select>
          </div>

          {/* Results count */}
          <div className="mt-4 text-sm text-gray-600">
            Showing {filteredLogs.length} of {logs.length} logs
          </div>
        </div>

        {/* Logs Table */}
        {loading ? (
          <div className="flex justify-center items-center h-64">
            <Loader className="animate-spin text-primary-600" size={32} />
          </div>
        ) : filteredLogs.length === 0 ? (
          <div className="bg-white rounded-lg shadow-sm p-12 text-center">
            <p className="text-gray-600 text-lg">No audit logs found</p>
          </div>
        ) : (
          <div className="bg-white rounded-lg shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-600 uppercase tracking-wider">
                      Timestamp
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-600 uppercase tracking-wider">
                      Action
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-600 uppercase tracking-wider">
                      Category
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-600 uppercase tracking-wider">
                      Actor
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-600 uppercase tracking-wider">
                      Target
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-600 uppercase tracking-wider">
                      Status
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-600 uppercase tracking-wider">
                      Details
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {filteredLogs.map((log) => (
                    <tr
                      key={log.id}
                      className="hover:bg-gray-50 transition"
                    >
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {new Date(log.createdAt).toLocaleString()}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                        {log.action}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className="px-3 py-1 inline-flex text-xs leading-5 font-semibold rounded-full bg-blue-100 text-blue-800">
                          {log.category}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {log.actorEmail || log.actorType}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        <div className="flex flex-col gap-0.5">
                          <span>{log.targetType}</span>
                          <span className="text-xs text-gray-500">
                            {log.targetId.substring(0, 20)}
                            {log.targetId.length > 20 ? '...' : ''}
                          </span>
                        </div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span
                          className={`px-3 py-1 inline-flex text-xs leading-5 font-semibold rounded-full ${
                            log.success
                              ? 'bg-green-100 text-green-800'
                              : 'bg-red-100 text-red-800'
                          }`}
                        >
                          {log.success ? 'SUCCESS' : 'FAILED'}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        <button
                          onClick={() =>
                            setExpandedId(expandedId === log.id ? null : log.id)
                          }
                          className="text-primary-600 hover:text-primary-700 font-medium flex items-center gap-1"
                        >
                          <ChevronDown
                            size={16}
                            className={`transition ${
                              expandedId === log.id ? 'rotate-180' : ''
                            }`}
                          />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Expanded Row Details */}
            {expandedId && filteredLogs.find((l) => l.id === expandedId) && (
              <div className="bg-gray-50 border-t border-gray-200 p-6">
                <div className="max-w-4xl">
                  <h3 className="font-bold text-gray-900 mb-4">
                    Details for {filteredLogs.find((l) => l.id === expandedId)?.action}
                  </h3>
                  <div className="bg-white rounded-lg p-4 font-mono text-sm text-gray-700 overflow-x-auto">
                    <pre>
                      {JSON.stringify(
                        filteredLogs.find((l) => l.id === expandedId),
                        null,
                        2
                      )}
                    </pre>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { ChevronLeft, _Filter, AlertTriangle } from 'lucide-react'
import toast from 'react-hot-toast'
import Link from 'next/link'

interface VariantDiscrepancy {
  id: string
  variantId: string
  shipmentId: string
  quantityExpected: number
  quantityReceived: number | null
  quantityDamaged: number | null
  quantityMissing: number | null
  acceptanceStatus: string
  createdAt: string
  variant: {
    id: string
    size: string | null
    color: string | null
    product: {
      id: string
      title: string
    }
  }
  shipment: {
    id: string
    seller: {
      id: string
      name: string
      email: string
    }
  }
}

export default function DiscrepanciesDashboard() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [discrepancies, setDiscrepancies] = useState<VariantDiscrepancy[]>([])
  const [loading, setLoading] = useState(true)
  const [statusFilter, setStatusFilter] = useState<string>('PENDING')
  const [ageFilter, setAgeFilter] = useState<string>('all') // all, 1-3, 4-6, 7+
  const [sortBy, setSortBy] = useState<string>('oldest') // oldest, newest

  useEffect(() => {
    if (status === 'loading') return
    if (!session || (session.user as any).role !== 'ADMIN') {
      router.push('/auth/signin')
      return
    }
    fetchDiscrepancies()
  }, [session, status, statusFilter, ageFilter, sortBy])

  const fetchDiscrepancies = async () => {
    setLoading(true)
    try {
      const queryParams = new URLSearchParams({
        status: statusFilter,
        age: ageFilter,
        sort: sortBy,
      })

      const res = await fetch(`/api/boutique/admin/discrepancies?${queryParams}`, {
        cache: 'no-store',
      })

      if (res.ok) {
        const data = await res.json()
        setDiscrepancies(data.discrepancies || [])
      } else {
        toast.error('Failed to load discrepancies')
      }
    } catch (error) {
      console.error('Error fetching discrepancies:', error)
      toast.error('Error loading discrepancies')
    } finally {
      setLoading(false)
    }
  }

  const getDaysOld = (createdAt: string) => {
    const days = Math.floor((Date.now() - new Date(createdAt).getTime()) / (24 * 60 * 60 * 1000))
    return days
  }

  const getUrgencyColor = (daysOld: number) => {
    if (daysOld >= 7) return 'bg-red-100 border-red-300 text-red-800'
    if (daysOld >= 5) return 'bg-yellow-100 border-yellow-300 text-yellow-800'
    if (daysOld >= 3) return 'bg-orange-100 border-orange-300 text-orange-800'
    return 'bg-blue-100 border-blue-300 text-blue-800'
  }

  const filteredAndSorted = discrepancies
    .filter(d => {
      const daysOld = getDaysOld(d.createdAt)
      if (ageFilter === '1-3' && (daysOld < 1 || daysOld > 3)) return false
      if (ageFilter === '4-6' && (daysOld < 4 || daysOld > 6)) return false
      if (ageFilter === '7+' && daysOld < 7) return false
      return true
    })
    .sort((a, b) => {
      if (sortBy === 'oldest') {
        return new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
      } else {
        return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
      }
    })

  if (!session) return null

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 to-slate-800 p-4 sm:p-6 lg:p-8">
      {/* Header */}
      <div className="mb-6 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <Link href="/admin/boutique/shipments" className="hover:opacity-75 transition">
            <ChevronLeft className="w-6 h-6 text-white" />
          </Link>
          <h1 className="text-2xl sm:text-3xl font-bold text-white">
            Variant Discrepancies {filteredAndSorted.length > 0 && `(${filteredAndSorted.length})`}
          </h1>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-slate-800 rounded-lg p-4 mb-6 border border-slate-700">
        <div className="flex flex-wrap gap-4 items-center">
          <div>
            <label className="block text-sm font-medium text-gray-300 mb-1">Status</label>
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="bg-slate-700 text-white border border-slate-600 rounded px-3 py-2 text-sm"
            >
              <option value="PENDING">Pending Only</option>
              <option value="ACCEPTED">Accepted</option>
              <option value="RETURNING">Returning</option>
              <option value="PARTIAL">Partial</option>
              <option value="all">All</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-1">Age</label>
            <select
              value={ageFilter}
              onChange={(e) => setAgeFilter(e.target.value)}
              className="bg-slate-700 text-white border border-slate-600 rounded px-3 py-2 text-sm"
            >
              <option value="all">All Ages</option>
              <option value="1-3">1-3 Days</option>
              <option value="4-6">4-6 Days</option>
              <option value="7+">7+ Days (Overdue)</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-1">Sort</label>
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
              className="bg-slate-700 text-white border border-slate-600 rounded px-3 py-2 text-sm"
            >
              <option value="oldest">Oldest First (Urgent)</option>
              <option value="newest">Newest First</option>
            </select>
          </div>
        </div>
      </div>

      {/* Discrepancies List */}
      {loading ? (
        <div className="text-center text-gray-400 py-12">Loading...</div>
      ) : filteredAndSorted.length === 0 ? (
        <div className="bg-slate-800 rounded-lg p-8 text-center border border-slate-700">
          <p className="text-gray-400">No discrepancies found</p>
        </div>
      ) : (
        <div className="space-y-3">
          {filteredAndSorted.map((discrepancy) => {
            const daysOld = getDaysOld(discrepancy.createdAt)
            const urgencyColor = getUrgencyColor(daysOld)
            const variantLabel = [
              discrepancy.variant.product.title,
              discrepancy.variant.size && `Size: ${discrepancy.variant.size}`,
              discrepancy.variant.color && `Color: ${discrepancy.variant.color}`,
            ]
              .filter(Boolean)
              .join(' ΓÇó ')

            return (
              <Link
                key={discrepancy.id}
                href={`/admin/boutique/shipments/${discrepancy.shipmentId}`}
                className={`block p-4 rounded-lg border transition hover:shadow-lg ${urgencyColor}`}
              >
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <p className="font-semibold text-sm sm:text-base truncate">{variantLabel}</p>
                    <p className="text-xs sm:text-sm opacity-75 mt-1">
                      Seller: {discrepancy.shipment.seller.name}
                    </p>
                    <p className="text-xs sm:text-sm opacity-75">
                      Expected: {discrepancy.quantityExpected} | Received: {discrepancy.quantityReceived ?? '?'}
                    </p>
                  </div>

                  <div className="flex flex-col items-end gap-2 flex-shrink-0">
                    <span className="px-2 py-1 bg-black bg-opacity-30 rounded text-xs font-medium whitespace-nowrap">
                      {daysOld}d old
                    </span>
                    {daysOld >= 7 && (
                      <span className="flex items-center gap-1 px-2 py-1 bg-red-600 rounded text-xs font-medium text-white">
                        <AlertTriangle className="w-3 h-3" />
                        OVERDUE
                      </span>
                    )}
                  </div>
                </div>
              </Link>
            )
          })}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter, useParams } from 'next/navigation'
import Link from 'next/link'
import Image from 'next/image'
import { 
  Package, ChevronLeft, Truck, AlertCircle,
  User, MapPin, Phone, Mail, Copy, ExternalLink,
  Banknote, Send
} from 'lucide-react'
import toast from 'react-hot-toast'
import { STATUS_DISPLAY, getValidTransitions, requiresOverrideReason as checkNeedsOverride, type BoutiqueOrderStatus, ALL_STATUSES } from '@/lib/boutique/statusMapping'
import { convertFromUSD } from '@/lib/currency'

interface OrderItem {
  id: string
  quantity: number
  price: number
  finalPrice: number
  variantSnapshot: { size?: string; color?: string } | null
  product: {
    id: string
    title: string
    thumbnailUrl: string | null
  }
}

interface Order {
  id: string
  orderNumber: string
  status: string
  fulfillmentMethod: string
  subtotal: number
  discount: number
  shippingCost: number
  platformFee: number
  sellerPayout: number | null
  total: number
  currency: string
  trackingNumber: string | null
  trackingUrl: string | null
  paymentReference: string | null
  adminNotes: string | null
  shippingAddress: {
    name: string
    phone: string
    street: string
    city: string
    state: string
    country?: string
  }
  createdAt: string
  paidAt: string | null
  shippedAt: string | null
  deliveredAt: string | null
  completedAt: string | null
  buyerConfirmedAt: string | null
  buyer: {
    id: string
    name: string | null
    email: string
    phone: string // Admin can contact for disputes/urgent updates
  }
  seller: {
    id: string
    name: string | null
    email: string
    phone: string // Admin can contact for disputes/urgent updates
    sellerAccount?: {
      bankName: string | null
      accountNumber: string | null
      accountName: string | null
    } | null
  } | null
  items: OrderItem[]
  auditLogs?: Array<{
    id: string
    action: string
    oldStatus: string | null
    newStatus: string | null
    changedFields: Record<string, any> | null
    isManualOverride: boolean
    overrideReason: string | null
    triggerType: string
    admin?: {
      id: string
      name: string | null
      email: string
    } | null
    createdAt: string
  }>
}

const ORDER_STATUSES = ALL_STATUSES.map(status => ({
  value: status,
  label: STATUS_DISPLAY[status as BoutiqueOrderStatus].label,
  color: STATUS_DISPLAY[status as BoutiqueOrderStatus].color,
}))

export default function AdminOrderDetailPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const params = useParams()
  const orderId = params.orderId as string

  const [order, setOrder] = useState<Order | null>(null)
  const [loading, setLoading] = useState(true)
  const [updating, setUpdating] = useState(false)
  const [newStatus, setNewStatus] = useState('')  // Starts empty, not set to current status
  const [trackingNumber, setTrackingNumber] = useState('')
  const [trackingUrl, setTrackingUrl] = useState('')
  const [adminNotes, setAdminNotes] = useState('')
  const [overrideReason, setOverrideReason] = useState('')
  const [statusWarning, setStatusWarning] = useState<string | null>(null)
  const [requiresOverrideReason, setRequiresOverrideReason] = useState(false)
  const [exchangeRates, setExchangeRates] = useState<Record<string, number>>({ NGN: 1200, USD: 1 })

  useEffect(() => {
    // Check authentication only once on mount
    if (status === 'loading') return
    if (!session) {
      router.push('/auth/signin')
      return
    }
    if ((session.user as any).role !== 'ADMIN') {
      router.push('/')
      return
    }
  }, [])

  useEffect(() => {
    // Fetch order when orderId changes
    if (!orderId) return
    fetchRates()
    fetchOrder()
  }, [orderId])

  const fetchRates = async () => {
    try {
      const res = await fetch('/api/currency/rates')
      if (res.ok) {
        const data = await res.json()
        setExchangeRates(data.rates)
      }
    } catch (error) {
      console.error('Failed to fetch exchange rates:', error)
      // Keep fallback rates
    }
  }

  const fetchOrder = async () => {
    setLoading(true)
    try {
      const res = await fetch(`/api/boutique/admin/orders/${orderId}`)
      if (res.ok) {
        const data = await res.json()
        console.log('[ORDER-FETCH] Loaded order:', { orderId, status: data.status, auditLogCount: data.auditLogs?.length || 0 })
        setOrder(data)
        setTrackingNumber(data.trackingNumber || '')
        setTrackingUrl(data.trackingUrl || '')
        setAdminNotes(data.adminNotes || '')
      } else {
        console.error('[ORDER-FETCH-ERROR] Status:', res.status)
        toast.error('Order not found')
        router.push('/admin/boutique/orders')
      }
    } catch (error) {
      console.error('[ORDER-FETCH-ERROR] Exception:', error)
      toast.error('Failed to load order')
    } finally {
      setLoading(false)
    }
  }

  const handleStatusChange = (selectedStatus: string) => {
    setNewStatus(selectedStatus)
    setStatusWarning(null)
    setRequiresOverrideReason(false)
    setOverrideReason('')

    if (!order) return

    try {
      const isUnusualChange = checkNeedsOverride(order.status as BoutiqueOrderStatus, selectedStatus as BoutiqueOrderStatus)

      if (isUnusualChange) {
        const fromLabel = STATUS_DISPLAY[order.status as BoutiqueOrderStatus]?.label || order.status
        const toLabel = STATUS_DISPLAY[selectedStatus as BoutiqueOrderStatus]?.label || selectedStatus
        setStatusWarning(`ΓÜá∩╕Å Unusual status change: ${fromLabel} ΓåÆ ${toLabel}. This requires an override reason.`)
        setRequiresOverrideReason(true)
      }
    } catch (error) {
      console.error('Error checking status transition:', error, { fromStatus: order.status, toStatus: selectedStatus })
    }
  }

  const updateOrder = async () => {
    if (!newStatus) {
      toast.error('Please select a status')
      setUpdating(false)
      return
    }

    // Check if override reason is required
    if (requiresOverrideReason && (!overrideReason || overrideReason.trim().length < 10)) {
      toast.error('Override reason required (minimum 10 characters) for this status change')
      setUpdating(false)
      return
    }

    setUpdating(true)
    try {
      const res = await fetch(`/api/boutique/admin/orders/${orderId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          status: newStatus,
          trackingNumber: trackingNumber || null,
          trackingUrl: trackingUrl || null,
          notes: adminNotes,
          overrideReason: overrideReason || null,
        }),
      })

      if (res.ok) {
        const data = await res.json()
        
        // Refetch the order to get updated status and audit logs
        const refreshRes = await fetch(`/api/boutique/admin/orders/${orderId}`)
        if (refreshRes.ok) {
          const refreshData = await refreshRes.json()
          console.log('[ORDER-UPDATE] Refreshed order after update:', { status: refreshData.status, auditLogCount: refreshData.auditLogs?.length || 0, latestAuditLog: refreshData.auditLogs?.[0] })
          setOrder(refreshData)
          // Reset dropdown to empty so user must select a new status for next change
          setNewStatus('')
          setTrackingNumber(refreshData.trackingNumber || '')
          setTrackingUrl(refreshData.trackingUrl || '')
          setAdminNotes(refreshData.adminNotes || '')
        } else {
          console.error('Failed to refresh order after update:', refreshRes.status)
          setOrder(data)
          setNewStatus('')
        }
        
        setOverrideReason('')
        setStatusWarning(null)
        setRequiresOverrideReason(false)
        toast.success('Order updated successfully')
      } else {
        const error = await res.json()
        console.error('Failed to update order:', error)
        if (error.requiresReason) {
          setRequiresOverrideReason(true)
          toast.error('ΓÜá∩╕Å ' + error.error)
        } else {
          toast.error(error.error || 'Failed to update order')
        }
      }
    } catch (error) {
      console.error('Error updating order:', error)
      toast.error('Failed to update order')
    } finally {
      setUpdating(false)
    }
  }

  const copyToClipboard = (text: string, label: string) => {
    navigator.clipboard.writeText(text)
    toast.success(`${label} copied!`)
  }

  const formatCurrency = (amountUSD: number) => {
    // Convert from USD to NGN
    const convertedAmount = convertFromUSD(amountUSD, 'NGN', exchangeRates)
    return new Intl.NumberFormat('en-NG', {
      style: 'currency',
      currency: 'NGN',
      minimumFractionDigits: 0,
    }).format(convertedAmount)
  }

  const formatDate = (date: string | null) => {
    if (!date) return '-'
    return new Date(date).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    })
  }

  const getStatusColor = (statusValue: string) => {
    return ORDER_STATUSES.find(s => s.value === statusValue)?.color || 'bg-gray-100 text-gray-800'
  }

  if (status === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600"></div>
      </div>
    )
  }

  if (!order) return null

  return (
    <div className="min-h-screen bg-gray-50 py-4 sm:py-8">
      <div className="max-w-6xl mx-auto px-3 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="mb-6">
          <Link href="/admin/boutique/orders" className="text-purple-600 hover:text-purple-700 flex items-center gap-1 mb-4 text-sm">
            <ChevronLeft className="w-4 h-4" />
            Back to Orders
          </Link>
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div>
              <h1 className="text-xl sm:text-2xl font-bold text-gray-900">Order #{order.orderNumber}</h1>
              <p className="text-sm text-gray-500">Created {formatDate(order.createdAt)}</p>
            </div>
            <span className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-medium ${getStatusColor(order.status)}`}>
              {order.status}
            </span>
          </div>
        </div>

        <div className="grid lg:grid-cols-3 gap-6">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-6">
            {/* Order Items */}
            <div className="bg-white rounded-lg shadow-sm p-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">Order Items</h2>
              <div className="space-y-4">
                {order.items.map((item) => (
                  <div key={item.id} className="flex gap-4 p-3 bg-gray-50 rounded-lg">
                    <div className="w-16 h-16 rounded-lg overflow-hidden bg-gray-100 shrink-0">
                      {item.product.thumbnailUrl ? (
                        <Image
                          src={item.product.thumbnailUrl}
                          alt={item.product.title}
                          width={64}
                          height={64}
                          className="object-cover w-full h-full"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center">
                          <Package className="w-8 h-8 text-gray-300" />
                        </div>
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="font-medium text-gray-900">{item.product.title}</p>
                      {item.variantSnapshot && (
                        <p className="text-sm text-gray-500">
                          {item.variantSnapshot.size && `Size: ${item.variantSnapshot.size}`}
                          {item.variantSnapshot.size && item.variantSnapshot.color && ' ΓÇó '}
                          {item.variantSnapshot.color && `Color: ${item.variantSnapshot.color}`}
                        </p>
                      )}
                      <p className="text-sm text-gray-500">Qty: {item.quantity}</p>
                    </div>
                    <div className="text-right">
                      <p className="font-medium text-gray-900">{formatCurrency(item.finalPrice)}</p>
                    </div>
                  </div>
                ))}
              </div>

              {/* Order Summary */}
              <div className="mt-6 pt-4 border-t space-y-2">
                <div className="flex justify-between text-sm">
                  <span className="text-gray-600">Subtotal</span>
                  <span className="text-black">{formatCurrency(order.subtotal)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-gray-600">Shipping</span>
                  <span className="text-black">{formatCurrency(order.shippingCost)}</span>
                </div>
                {order.discount > 0 && (
                  <div className="flex justify-between text-sm text-green-600">
                    <span>Discount</span>
                    <span>-{formatCurrency(order.discount)}</span>
                  </div>
                )}
                <div className="flex justify-between text-sm text-purple-600">
                  <span>Platform Fee</span>
                  <span>{formatCurrency(order.platformFee)}</span>
                </div>
                <div className="flex justify-between font-semibold text-lg pt-2 border-t">
                  <span>Total</span>
                  <span className="text-purple-600">{formatCurrency(order.total)}</span>
                </div>
              </div>
            </div>

            {/* Shipping Address */}
            <div className="bg-white rounded-lg shadow-sm p-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">Shipping Address</h2>
              <div className="space-y-2 text-sm">
                <div className="flex items-center gap-2">
                  <User className="w-4 h-4 text-gray-400" />
                  <span className="text-gray-900">{order.shippingAddress.name}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Phone className="w-4 h-4 text-gray-400" />
                  <span className="text-gray-900">{order.shippingAddress.phone}</span>
                </div>
                <div className="flex items-start gap-2">
                  <MapPin className="w-4 h-4 text-gray-400 mt-0.5" />
                  <span className="text-gray-900">
                    {order.shippingAddress.street}<br />
                    {order.shippingAddress.city}, {order.shippingAddress.state}
                    {order.shippingAddress.country && <><br />{order.shippingAddress.country}</>}
                  </span>
                </div>
              </div>
            </div>

            {/* Update Order Status */}
            <div className="bg-white rounded-lg shadow-sm p-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">Update Order</h2>
              
              <div className="space-y-4">
                <div>
                  <label htmlFor="orderStatus" className="block text-sm font-medium text-gray-700 mb-1">Status</label>
                  {order && (
                    <>
                      <p className="text-xs text-gray-500 mb-2">Current: <strong>{STATUS_DISPLAY[order.status as BoutiqueOrderStatus]?.label || order.status}</strong></p>
                      <select
                        id="orderStatus"
                        value={newStatus}
                        onChange={(e) => {
                          handleStatusChange(e.target.value)
                        }}
                        className="w-full border rounded-lg px-3 py-2 text-gray-900"
                      >
                        <option value="">Select a new status...</option>
                        {(() => {
                          const validTransitions = getValidTransitions(order.status as BoutiqueOrderStatus)
                          return validTransitions.map(status => {
                            const statusInfo = STATUS_DISPLAY[status];
                            return (
                              <option key={status} value={status} className="text-gray-900">
                                {statusInfo?.label || status}
                              </option>
                            );
                          });
                        })()}
                      </select>
                    </>
                  )}
                </div>

                {/* Status Change Warning */}
                {statusWarning && (
                  <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-3 text-sm text-yellow-800">
                    {statusWarning}
                  </div>
                )}

                {/* Override Reason (required for certain status changes) */}
                {requiresOverrideReason && (
                  <div>
                    <label className="block text-sm font-medium text-red-700 mb-1">
                      * Reason for Status Override
                    </label>
                    <textarea
                      value={overrideReason}
                      onChange={(e) => setOverrideReason(e.target.value)}
                      placeholder="Explain why this status change is necessary (minimum 10 characters)..."
                      rows={3}
                      className="w-full border border-red-300 rounded-lg px-3 py-2 text-gray-900 focus:border-red-500 focus:ring-1 focus:ring-red-500"
                    />
                    <p className="text-xs text-gray-500 mt-1">
                      {overrideReason.length}/10 characters minimum
                    </p>
                  </div>
                )}

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Tracking Number
                  </label>
                  <input
                    type="text"
                    value={trackingNumber}
                    onChange={(e) => setTrackingNumber(e.target.value)}
                    placeholder="Enter tracking number..."
                    className="w-full border rounded-lg px-3 py-2 text-gray-900"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Tracking URL
                  </label>
                  <input
                    type="url"
                    value={trackingUrl}
                    onChange={(e) => setTrackingUrl(e.target.value)}
                    placeholder="https://..."
                    className="w-full border rounded-lg px-3 py-2 text-gray-900"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Admin Notes
                  </label>
                  <textarea
                    value={adminNotes}
                    onChange={(e) => setAdminNotes(e.target.value)}
                    rows={3}
                    placeholder="Internal notes..."
                    className="w-full border rounded-lg px-3 py-2 text-gray-900"
                  />
                </div>

                <button
                  onClick={updateOrder}
                  disabled={updating}
                  className="w-full bg-purple-600 text-white py-2 rounded-lg hover:bg-purple-700 disabled:opacity-50 flex items-center justify-center gap-2"
                >
                  <Send className="w-4 h-4" />
                  {updating ? 'Updating...' : 'Update Order'}
                </button>
              </div>
            </div>

            {/* Audit Log History */}
            {order.auditLogs && order.auditLogs.length > 0 && (
              <div className="bg-white rounded-lg shadow-sm p-6">
                <h2 className="text-lg font-semibold text-gray-900 mb-4">Change History</h2>
                <div className="space-y-3">
                  {order.auditLogs.map((log) => (
                    <div key={log.id} className="border-l-4 border-purple-200 pl-4 py-2">
                      <div className="flex items-start justify-between gap-4">
                        <div className="flex-1">
                          <div className="font-medium text-gray-900">
                            {log.action === 'STATUS_CHANGE' ? `Status: ${log.oldStatus} ΓåÆ ${log.newStatus}` : log.action}
                          </div>
                          {log.isManualOverride && (
                            <div className="mt-1 px-2 py-1 bg-yellow-50 border border-yellow-200 rounded text-xs text-yellow-800">
                              ΓÜá∩╕Å Manual Override: {log.overrideReason}
                            </div>
                          )}
                          {log.changedFields && Object.keys(log.changedFields).length > 0 && (
                            <div className="mt-1 text-xs text-gray-600">
                              {Object.entries(log.changedFields)
                                .filter(([key]) => key !== 'status')
                                .filter(([, value]) => value !== null && value !== undefined)
                                .map(([key, value]) => (
                                  <div key={key}>
                                    {key}: {typeof value === 'string' ? value : JSON.stringify(value)}
                                  </div>
                                ))}
                            </div>
                          )}
                        </div>
                        <div className="text-right whitespace-nowrap">
                          <div className="text-xs text-gray-600">
                            {new Date(log.createdAt).toLocaleDateString('en-US', {
                              month: 'short',
                              day: 'numeric',
                              hour: '2-digit',
                              minute: '2-digit',
                            })}
                          </div>
                          {log.admin && (
                            <div className="text-xs font-medium text-gray-900 mt-1">
                              {log.admin.name || log.admin.email}
                            </div>
                          )}
                          {log.triggerType === 'SYSTEM' && (
                            <div className="text-xs text-blue-600">System</div>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Buyer Info */}
            <div className="bg-white rounded-lg shadow-sm p-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">Buyer</h2>
              <div className="space-y-2 text-sm">
                <div className="flex items-center gap-2">
                  <User className="w-4 h-4 text-gray-400" />
                  <span className="text-gray-900">{order.buyer.name || 'N/A'}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Mail className="w-4 h-4 text-gray-400" />
                  <span className="text-gray-900">{order.buyer.email}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Phone className="w-4 h-4 text-gray-400" />
                  <a href={`tel:${order.buyer.phone}`} className="text-primary-600 hover:underline">
                    {order.buyer.phone}
                  </a>
                </div>
              </div>
            </div>

            {/* Seller Info with Bank Details */}
            {order.seller && (
              <div className="bg-white rounded-lg shadow-sm p-6">
                <h2 className="text-lg font-semibold text-gray-900 mb-4">Seller</h2>
                <div className="space-y-2 text-sm">
                  <div className="flex items-center gap-2">
                    <User className="w-4 h-4 text-gray-400" />
                    <span className="text-gray-900">{order.seller.name || 'N/A'}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Mail className="w-4 h-4 text-gray-400" />
                    <span className="text-gray-900">{order.seller.email}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Phone className="w-4 h-4 text-gray-400" />
                    <a href={`tel:${order.seller.phone}`} className="text-primary-600 hover:underline">
                      {order.seller.phone}
                    </a>
                  </div>
                </div>

                {/* Bank Details for Payout */}
                {order.sellerPayout && order.sellerPayout > 0 && (
                  <div className="mt-4 pt-4 border-t">
                    <h3 className="font-medium text-gray-900 mb-3 flex items-center gap-2">
                      <Banknote className="w-4 h-4 text-green-600" />
                      Payout Details
                    </h3>
                    <div className="bg-green-50 rounded-lg p-3 space-y-2">
                      <div className="flex justify-between">
                        <span className="text-sm text-gray-600">Amount:</span>
                        <span className="font-semibold text-green-700">{formatCurrency(order.sellerPayout)}</span>
                      </div>
                      {order.seller.sellerAccount?.bankName ? (
                        <>
                          <div className="flex items-center justify-between">
                            <span className="text-sm text-gray-600">Bank:</span>
                            <span className="text-sm text-gray-900">{order.seller.sellerAccount.bankName}</span>
                          </div>
                          <div className="flex items-center justify-between">
                            <span className="text-sm text-gray-600">Account:</span>
                            <div className="flex items-center gap-1">
                              <span className="text-sm font-mono text-gray-900">{order.seller.sellerAccount.accountNumber}</span>
                              <button
                                onClick={() => copyToClipboard(order.seller!.sellerAccount!.accountNumber!, 'Account number')}
                                className="p-1 hover:bg-green-100 rounded"
                                aria-label="Copy account number"
                              >
                                <Copy className="w-3 h-3 text-gray-500" />
                              </button>
                            </div>
                          </div>
                          <div className="flex items-center justify-between">
                            <span className="text-sm text-gray-600">Name:</span>
                            <span className="text-sm text-gray-900">{order.seller.sellerAccount.accountName}</span>
                          </div>
                        </>
                      ) : (
                        <div className="flex items-center gap-2 text-amber-600">
                          <AlertCircle className="w-4 h-4" />
                          <span className="text-sm">No bank details on file</span>
                        </div>
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Payment Info */}
            <div className="bg-white rounded-lg shadow-sm p-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">Payment</h2>
              <div className="space-y-2 text-sm">
                {order.paymentReference && (
                  <div className="flex items-center justify-between">
                    <span className="text-gray-600">Reference:</span>
                    <div className="flex items-center gap-1">
                      <span className="font-mono text-gray-900 text-xs">{order.paymentReference.slice(0, 12)}...</span>
                      <button
                        onClick={() => copyToClipboard(order.paymentReference!, 'Payment reference')}
                        className="p-1 hover:bg-gray-100 rounded"
                        aria-label="Copy payment reference"
                      >
                        <Copy className="w-3 h-3 text-gray-500" />
                      </button>
                    </div>
                  </div>
                )}
                <div className="flex items-center justify-between">
                  <span className="text-gray-600">Fulfillment:</span>
                  <span className="text-gray-900">{order.fulfillmentMethod.replace(/_/g, ' ')}</span>
                </div>
              </div>
            </div>

            {/* Timeline */}
            <div className="bg-white rounded-lg shadow-sm p-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">Timeline</h2>
              <div className="space-y-3 text-sm">
                <div className="flex justify-between">
                  <span className="text-gray-600">Created</span>
                  <span className="text-gray-900">{formatDate(order.createdAt)}</span>
                </div>
                {order.paidAt && (
                  <div className="flex justify-between">
                    <span className="text-gray-600">Paid</span>
                    <span className="text-gray-900">{formatDate(order.paidAt)}</span>
                  </div>
                )}
                {order.shippedAt && (
                  <div className="flex justify-between">
                    <span className="text-gray-600">Shipped</span>
                    <span className="text-gray-900">{formatDate(order.shippedAt)}</span>
                  </div>
                )}
                {order.deliveredAt && (
                  <div className="flex justify-between">
                    <span className="text-gray-600">Delivered</span>
                    <span className="text-gray-900">{formatDate(order.deliveredAt)}</span>
                  </div>
                )}
                {order.buyerConfirmedAt && (
                  <div className="flex justify-between">
                    <span className="text-gray-600">Buyer Confirmed</span>
                    <span className="text-gray-900">{formatDate(order.buyerConfirmedAt)}</span>
                  </div>
                )}
                {order.completedAt && (
                  <div className="flex justify-between">
                    <span className="text-gray-600">Completed</span>
                    <span className="text-gray-900">{formatDate(order.completedAt)}</span>
                  </div>
                )}
              </div>
            </div>

            {/* Tracking Info */}
            {order.trackingNumber && (
              <div className="bg-purple-50 rounded-lg p-4">
                <div className="flex items-center gap-2 mb-2">
                  <Truck className="w-5 h-5 text-purple-600" />
                  <h3 className="font-medium text-purple-900">Tracking</h3>
                </div>
                <p className="font-mono text-purple-700 text-sm">{order.trackingNumber}</p>
                {order.trackingUrl && (
                  <a
                    href={order.trackingUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 mt-2 text-purple-600 hover:text-purple-700 text-sm"
                  >
                    Track Package <ExternalLink className="w-3 h-3" />
                  </a>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import Image from 'next/image'
import { Package, ChevronLeft, ChevronRight, Search, Filter, Eye, Truck, CheckCircle, XCircle, Clock } from 'lucide-react'

interface OrderItem {
  id: string
  quantity: number
  price: number
  product: {
    id: string
    title: string
    thumbnailUrl: string | null
    seller: {
      id: string
      name: string
      email: string
    }
  }
}

interface BoutiqueOrder {
  id: string
  orderNumber: string
  status: string
  total: number
  shippingCost: number
  shippingAddress: any
  paymentReference: string
  createdAt: string
  updatedAt: string
  buyer: {
    id: string
    name: string
    email: string
  }
  items: OrderItem[]
}

const ORDER_STATUSES = [
  { value: '', label: 'All Statuses' },
  { value: 'PENDING_PAYMENT', label: 'Pending Payment' },
  { value: 'PAID', label: 'Paid' },
  { value: 'PROCESSING', label: 'Processing' },
  { value: 'SHIPPED', label: 'Shipped' },
  { value: 'DELIVERED', label: 'Delivered' },
  { value: 'COMPLETED', label: 'Completed' },
  { value: 'RETURN_REQUESTED', label: 'Return Requested' },
  { value: 'RETURN_APPROVED', label: 'Return Approved' },
  { value: 'RETURN_SHIPPED', label: 'Return Shipped' },
  { value: 'RETURN_RECEIVED', label: 'Return Received' },
  { value: 'REFUNDED', label: 'Refunded' },
  { value: 'CANCELLED', label: 'Cancelled' },
  { value: 'DISPUTED', label: 'Disputed' },
]

function getStatusColor(status: string) {
  switch (status) {
    case 'PENDING_PAYMENT':
      return 'bg-yellow-100 text-yellow-800'
    case 'PAID':
      return 'bg-blue-100 text-blue-800'
    case 'PROCESSING':
      return 'bg-purple-100 text-purple-800'
    case 'SHIPPED':
      return 'bg-indigo-100 text-indigo-800'
    case 'DELIVERED':
      return 'bg-green-100 text-green-800'
    case 'COMPLETED':
      return 'bg-green-100 text-green-800'
    case 'RETURN_REQUESTED':
      return 'bg-amber-100 text-amber-800'
    case 'RETURN_APPROVED':
      return 'bg-orange-100 text-orange-800'
    case 'RETURN_SHIPPED':
      return 'bg-orange-100 text-orange-800'
    case 'RETURN_RECEIVED':
      return 'bg-emerald-100 text-emerald-800'
    case 'REFUNDED':
      return 'bg-gray-100 text-gray-800'
    case 'CANCELLED':
      return 'bg-red-100 text-red-800'
    case 'DISPUTED':
      return 'bg-red-100 text-red-800'
    default:
      return 'bg-gray-100 text-gray-800'
  }
}

function getStatusIcon(status: string) {
  switch (status) {
    case 'PENDING_PAYMENT':
      return <Clock className="w-4 h-4" />
    case 'PAID':
      return <CheckCircle className="w-4 h-4" />
    case 'PROCESSING':
      return <Package className="w-4 h-4" />
    case 'SHIPPED':
      return <Truck className="w-4 h-4" />
    case 'DELIVERED':
      return <CheckCircle className="w-4 h-4" />
    case 'COMPLETED':
      return <CheckCircle className="w-4 h-4" />
    case 'RETURN_REQUESTED':
      return <Clock className="w-4 h-4" />
    case 'RETURN_APPROVED':
      return <CheckCircle className="w-4 h-4" />
    case 'RETURN_SHIPPED':
      return <Truck className="w-4 h-4" />
    case 'RETURN_RECEIVED':
      return <CheckCircle className="w-4 h-4" />
    case 'REFUNDED':
      return <CheckCircle className="w-4 h-4" />
    case 'CANCELLED':
      return <XCircle className="w-4 h-4" />
    case 'DISPUTED':
      return <XCircle className="w-4 h-4" />
    default:
      return <Clock className="w-4 h-4" />
  }
}

export default function AdminBoutiqueOrdersPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [orders, setOrders] = useState<BoutiqueOrder[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [statusFilter, setStatusFilter] = useState('')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [totalOrders, setTotalOrders] = useState(0)
  const [updatingOrder, setUpdatingOrder] = useState<string | null>(null)

  useEffect(() => {
    if (status === 'loading') return
    if (!session || (session.user as any).role !== 'ADMIN') {
      router.push('/auth/signin')
      return
    }
    fetchOrders()
  }, [session, status, page, statusFilter])

  const fetchOrders = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        page: page.toString(),
        limit: '20',
      })
      if (statusFilter) params.append('status', statusFilter)
      if (searchQuery) params.append('search', searchQuery)

      const res = await fetch(`/api/boutique/admin/orders?${params}`)
      if (res.ok) {
        const data = await res.json()
        setOrders(data.orders || [])
        setTotalPages(data.totalPages || 1)
        setTotalOrders(data.total || 0)
      }
    } catch (error) {
      console.error('Failed to fetch orders:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault()
    setPage(1)
    fetchOrders()
  }

  const updateOrderStatus = async (orderId: string, newStatus: string) => {
    setUpdatingOrder(orderId)
    try {
      const res = await fetch(`/api/boutique/admin/orders/${orderId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      })
      if (res.ok) {
        setOrders(orders.map(o => o.id === orderId ? { ...o, status: newStatus } : o))
      }
    } catch (error) {
      console.error('Failed to update order:', error)
    } finally {
      setUpdatingOrder(null)
    }
  }

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-NG', {
      style: 'currency',
      currency: 'NGN',
      minimumFractionDigits: 0,
    }).format(amount)
  }

  const formatDate = (date: string) => {
    return new Date(date).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    })
  }

  if (status === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600"></div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 py-4 sm:py-8">
      <div className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="mb-4 sm:mb-8">
          <Link href="/admin" className="text-purple-600 hover:text-purple-700 flex items-center gap-1 mb-3 sm:mb-4 text-xs sm:text-sm">
            <ChevronLeft className="w-3 h-3 sm:w-4 sm:h-4" />
            Back to Admin
          </Link>
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 sm:gap-4">
            <div>
              <h1 className="text-xl sm:text-3xl font-bold text-gray-900">Boutique Orders</h1>
              <p className="text-xs sm:text-base text-gray-600 mt-0.5 sm:mt-1">{totalOrders} total orders</p>
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-sm p-3 sm:p-4 mb-4 sm:mb-6">
          <div className="flex flex-col md:flex-row gap-2 sm:gap-4">
            <form onSubmit={handleSearch} className="flex-1">
              <div className="relative">
                <Search className="absolute left-2.5 sm:left-3 top-1/2 -translate-y-1/2 w-4 h-4 sm:w-5 sm:h-5 text-gray-400" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search orders..."
                  className="w-full pl-8 sm:pl-10 pr-3 sm:pr-4 py-2 border rounded-lg text-gray-900 focus:ring-2 focus:ring-purple-500 focus:border-transparent text-sm"
                />
              </div>
            </form>
            <div className="flex items-center gap-2">
              <Filter className="w-4 h-4 sm:w-5 sm:h-5 text-gray-400" />
              <select
                value={statusFilter}
                onChange={(e) => {
                  setStatusFilter(e.target.value)
                  setPage(1)
                }}
                className="border rounded-lg px-2 sm:px-3 py-2 text-gray-900 focus:ring-2 focus:ring-purple-500 focus:border-transparent text-xs sm:text-sm"
                aria-label="Filter by order status"
              >
                {ORDER_STATUSES.map(s => (
                  <option key={s.value} value={s.value}>{s.label}</option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {/* Orders Table */}
        <div className="bg-white rounded-lg shadow-sm overflow-hidden">
          {orders.length === 0 ? (
            <div className="p-8 sm:p-12 text-center">
              <Package className="w-12 h-12 sm:w-16 sm:h-16 text-gray-300 mx-auto mb-3 sm:mb-4" />
              <h3 className="text-base sm:text-lg font-medium text-gray-900 mb-1 sm:mb-2">No orders found</h3>
              <p className="text-xs sm:text-base text-gray-500">
                {statusFilter || searchQuery
                  ? 'Try adjusting your filters'
                  : 'Orders will appear here'}
              </p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-3 sm:px-6 py-2 sm:py-3 text-left text-[10px] sm:text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Order
                    </th>
                    <th className="px-3 sm:px-6 py-2 sm:py-3 text-left text-[10px] sm:text-xs font-medium text-gray-500 uppercase tracking-wider hidden sm:table-cell">
                      Customer
                    </th>
                    <th className="px-3 sm:px-6 py-2 sm:py-3 text-left text-[10px] sm:text-xs font-medium text-gray-500 uppercase tracking-wider hidden md:table-cell">
                      Items
                    </th>
                    <th className="px-3 sm:px-6 py-2 sm:py-3 text-left text-[10px] sm:text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Total
                    </th>
                    <th className="px-3 sm:px-6 py-2 sm:py-3 text-left text-[10px] sm:text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Status
                    </th>
                    <th className="px-3 sm:px-6 py-2 sm:py-3 text-left text-[10px] sm:text-xs font-medium text-gray-500 uppercase tracking-wider hidden lg:table-cell">
                      Date
                    </th>
                    <th className="px-3 sm:px-6 py-2 sm:py-3 text-left text-[10px] sm:text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <span className="sr-only">Actions</span>
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {orders.map((order) => (
                    <tr key={order.id} className="hover:bg-gray-50">
                      <td className="px-3 sm:px-6 py-3 sm:py-4 whitespace-nowrap">
                        <div className="text-xs sm:text-sm font-medium text-gray-900">
                          {order.orderNumber}
                        </div>
                        <div className="text-[10px] sm:text-xs text-gray-500 hidden sm:block">
                          {order.paymentReference}
                        </div>
                      </td>
                      <td className="px-3 sm:px-6 py-3 sm:py-4 whitespace-nowrap hidden sm:table-cell">
                        <div className="text-xs sm:text-sm text-gray-900">{order.buyer?.name || 'N/A'}</div>
                        <div className="text-[10px] sm:text-xs text-gray-500">{order.buyer?.email}</div>
                      </td>
                      <td className="px-3 sm:px-6 py-3 sm:py-4 hidden md:table-cell">
                        <div className="flex -space-x-2">
                          {order.items?.slice(0, 3).map((item, idx) => (
                            <div key={idx} className="w-8 h-8 sm:w-10 sm:h-10 rounded-lg overflow-hidden border-2 border-white">
                              <Image
                                src={item.product?.thumbnailUrl || '/images/placeholder.png'}
                                alt={item.product?.title || 'Product'}
                                width={40}
                                height={40}
                                className="w-full h-full object-cover"
                              />
                            </div>
                          ))}
                          {order.items?.length > 3 && (
                            <div className="w-8 h-8 sm:w-10 sm:h-10 rounded-lg bg-gray-100 border-2 border-white flex items-center justify-center">
                              <span className="text-[10px] sm:text-xs text-gray-600">+{order.items.length - 3}</span>
                            </div>
                          )}
                        </div>
                        <div className="text-[10px] sm:text-xs text-gray-500 mt-1">
                          {order.items?.length || 0} item{(order.items?.length || 0) !== 1 ? 's' : ''}
                        </div>
                      </td>
                      <td className="px-3 sm:px-6 py-3 sm:py-4 whitespace-nowrap">
                        <div className="text-xs sm:text-sm font-medium text-gray-900">
                          {formatCurrency(order.total)}
                        </div>
                        {order.shippingCost > 0 && (
                          <div className="text-[10px] sm:text-xs text-gray-500 hidden sm:block">
                            +{formatCurrency(order.shippingCost)} ship
                          </div>
                        )}
                      </td>
                      <td className="px-3 sm:px-6 py-3 sm:py-4 whitespace-nowrap">
                        <span className={`inline-flex items-center gap-0.5 sm:gap-1 px-1.5 sm:px-2.5 py-0.5 rounded-full text-[10px] sm:text-xs font-medium ${getStatusColor(order.status)}`}>
                          {getStatusIcon(order.status)}
                          <span className="hidden xs:inline">{order.status}</span>
                        </span>
                      </td>
                      <td className="px-3 sm:px-6 py-3 sm:py-4 whitespace-nowrap text-xs sm:text-sm text-gray-500 hidden lg:table-cell">
                        {formatDate(order.createdAt)}
                      </td>
                      <td className="px-3 sm:px-6 py-3 sm:py-4 whitespace-nowrap">
                        <div className="flex items-center gap-1 sm:gap-2">
                          <Link
                            href={`/admin/boutique/orders/${order.id}`}
                            className="text-purple-600 hover:text-purple-700"
                            title="View Details"
                          >
                            <Eye className="w-4 h-4 sm:w-5 sm:h-5" />
                          </Link>
                          {order.status === 'PAID' && (
                            <button
                              onClick={() => updateOrderStatus(order.id, 'PROCESSING')}
                              disabled={updatingOrder === order.id}
                              className="text-blue-600 hover:text-blue-700 disabled:opacity-50"
                              title="Mark as Processing"
                            >
                              <Package className="w-4 h-4 sm:w-5 sm:h-5" />
                            </button>
                          )}
                          {order.status === 'PROCESSING' && (
                            <button
                              onClick={() => updateOrderStatus(order.id, 'SHIPPED')}
                              disabled={updatingOrder === order.id}
                              className="text-indigo-600 hover:text-indigo-700 disabled:opacity-50"
                              title="Mark as Shipped"
                            >
                              <Truck className="w-4 h-4 sm:w-5 sm:h-5" />
                            </button>
                          )}
                          {order.status === 'SHIPPED' && (
                            <button
                              onClick={() => updateOrderStatus(order.id, 'DELIVERED')}
                              disabled={updatingOrder === order.id}
                              className="text-green-600 hover:text-green-700 disabled:opacity-50"
                              title="Mark as Delivered"
                            >
                              <CheckCircle className="w-4 h-4 sm:w-5 sm:h-5" />
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="bg-white px-3 sm:px-4 py-2 sm:py-3 flex items-center justify-between border-t">
              <div className="text-xs sm:text-sm text-gray-700">
                Page {page} of {totalPages}
              </div>
              <div className="flex gap-1 sm:gap-2">
                <button
                  onClick={() => setPage(p => Math.max(1, p - 1))}
                  disabled={page === 1}
                  className="px-2 sm:px-3 py-1 border rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                  aria-label="Previous page"
                >
                  <ChevronLeft className="w-4 h-4 sm:w-5 sm:h-5" />
                </button>
                <button
                  onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                  disabled={page === totalPages}
                  className="px-2 sm:px-3 py-1 border rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                  aria-label="Next page"
                >
                  <ChevronRight className="w-4 h-4 sm:w-5 sm:h-5" />
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState, useEffect } from 'react';
import { useSession } from 'next-auth/react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import Image from 'next/image';
import { Package, Calendar, TrendingDown, ArrowLeft, Filter, ChevronDown } from 'lucide-react';

interface Variant {
  id: string;
  size: string | null;
  color: string | null;
  quantity: number;
  soldOutAt: string | null;
}

interface MediaFile {
  id: string;
  url: string;
  type: 'IMAGE' | 'VIDEO';
  isPrimary: boolean;
}

interface Seller {
  id: string;
  name: string;
  email: string;
}

interface OutOfStockProduct {
  id: string;
  title: string;
  slug: string;
  basePrice: number;
  salePrice: number | null;
  originalQuantity: number;
  currentStock: number;
  outOfStockAt: string;
  createdAt: string;
  imageUrl: string | null;
  media: MediaFile[];
  totalOrders: number;
  fulfillmentMethod: string;
  seller: Seller;
  variants: Variant[];
}

export default function AdminOutOfStockPage() {
  const { data: session, status } = useSession();
  const router = useRouter();
  const [products, setProducts] = useState<OutOfStockProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [sellerId, setSellerId] = useState('');
  const [sellers, setSellers] = useState<Seller[]>([]);
  const [expandedProducts, setExpandedProducts] = useState<Set<string>>(new Set());

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/auth/signin');
    } else if (status === 'authenticated' && session?.user?.role !== 'ADMIN') {
      router.push('/');
    }
  }, [status, session, router]);

  useEffect(() => {
    if (status === 'authenticated' && session?.user?.role === 'ADMIN') {
      fetchProducts();
    }
  }, [page, sellerId, status, session]);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      setError(null);
      let url = `/api/boutique/admin/out-of-stock?page=${page}&limit=20`;
      if (sellerId) {
        url += `&sellerId=${sellerId}`;
      }

      const response = await fetch(url);

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.message || 'Failed to fetch out-of-stock products');
      }

      const data = await response.json();
      setProducts(data.products);
      setTotalPages(data.pagination.totalPages);

      // Extract unique sellers for filter
      if (page === 1) {
        const uniqueSellers = Array.from(
          new Map(data.products.map((p: OutOfStockProduct) => [p.seller.id, p.seller])).values()
        );
        setSellers(uniqueSellers as Seller[]);
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to fetch products';
      setError(message);
      setProducts([]);
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString: string | null) => {
    if (!dateString) return 'Not recorded';
    const date = new Date(dateString);
    // Check if it's epoch time (Jan 1, 1970)
    if (date.getFullYear() === 1970) return 'Not recorded';
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  };

  const getDaysSinceLaunch = (createdAt: string) => {
    const launch = new Date(createdAt);
    const today = new Date();
    const diff = today.getTime() - launch.getTime();
    return Math.floor(diff / (1000 * 60 * 60 * 24));
  };

  const toggleExpanded = (productId: string) => {
    const newExpanded = new Set(expandedProducts);
    if (newExpanded.has(productId)) {
      newExpanded.delete(productId);
    } else {
      newExpanded.add(productId);
    }
    setExpandedProducts(newExpanded);
  };

  if (loading && products.length === 0) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="w-12 h-12 border-4 border-purple-200 border-t-purple-600 rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-gray-600">Loading sold-out products...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-4xl mx-auto px-4 py-8">
        {/* Header */}
        <div className="mb-8">
          <Link href="/admin" className="flex items-center gap-2 text-purple-600 hover:text-purple-700 mb-4">
            <ArrowLeft className="w-4 h-4" />
            Back to Admin
          </Link>
          <h1 className="text-3xl font-bold text-gray-900 mb-2">Out-of-Stock Products</h1>
          <p className="text-gray-600">Monitor all products that have sold out across the marketplace</p>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow p-4 mb-6">
          <div className="flex items-center gap-2 mb-4">
            <Filter className="w-5 h-5 text-gray-600" />
            <h3 className="font-semibold text-gray-900">Filters</h3>
          </div>
          <div className="flex flex-col sm:flex-row gap-4">
            <div className="flex-1">
              <label className="block text-sm font-medium text-gray-700 mb-1">Filter by Seller</label>
              <select
                value={sellerId}
                onChange={(e) => {
                  setSellerId(e.target.value);
                  setPage(1);
                }}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
              >
                <option value="">All Sellers</option>
                {sellers.map((seller) => (
                  <option key={seller.id} value={seller.id}>
                    {seller.name} ({seller.email})
                  </option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {error && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6 text-red-700">
            {error}
          </div>
        )}

        {products.length === 0 ? (
          <div className="bg-white rounded-lg shadow p-12 text-center">
            <TrendingDown className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <h3 className="text-xl font-semibold text-gray-900 mb-2">No Sold Out Products</h3>
            <p className="text-gray-600">There are currently no out-of-stock products in the marketplace.</p>
          </div>
        ) : (
          <div className="space-y-4">
            {products.map((product) => (
              <div key={product.id} className="bg-white rounded-lg shadow hover:shadow-lg transition-shadow">
                <div className="p-6 flex flex-col sm:flex-row gap-4">
                  {/* Image */}
                  <div className="w-full sm:w-24 h-24 bg-gray-100 rounded-lg flex-shrink-0 overflow-hidden">
                    {product.imageUrl ? (
                      <Image
                        src={product.imageUrl}
                        alt={product.title}
                        width={96}
                        height={96}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center">
                        <Package className="w-8 h-8 text-gray-300" />
                      </div>
                    )}
                  </div>

                  {/* Content */}
                  <div className="flex-1">
                    <div className="flex items-start justify-between mb-3">
                      <div>
                        <h3 className="font-semibold text-gray-900 text-lg">{product.title}</h3>
                        <p className="text-sm text-gray-500">Γéª{product.basePrice.toLocaleString()}</p>
                      </div>
                      <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full bg-red-100 text-red-700 text-sm font-medium">
                        <TrendingDown className="w-4 h-4" />
                        Sold Out
                      </span>
                    </div>

                    {/* Seller Info */}
                    <div className="mb-3 pb-3 border-b border-gray-200">
                      <p className="text-sm">
                        <span className="text-gray-600">Seller: </span>
                        <span className="font-medium text-gray-900">{product.seller.name}</span>
                        <span className="text-gray-500 ml-2">({product.seller.email})</span>
                      </p>
                      <p className="text-sm text-gray-600 mt-1">
                        Fulfillment: <span className="font-medium">{product.fulfillmentMethod}</span>
                      </p>
                    </div>

                    {/* Summary Stats */}
                    <div className="grid grid-cols-3 gap-3 mb-4">
                      <div className="bg-gray-50 p-2 rounded-lg">
                        <p className="text-xs text-gray-600">Original Stock</p>
                        <p className="text-lg font-bold text-gray-900">{product.originalQuantity || 'N/A'}</p>
                      </div>
                      <div className="bg-gray-50 p-2 rounded-lg">
                        <p className="text-xs text-gray-600">Total Orders</p>
                        <p className="text-lg font-bold text-gray-900">{product.totalOrders}</p>
                      </div>
                      <div className="bg-gray-50 p-2 rounded-lg">
                        <p className="text-xs text-gray-600">Days to Sell</p>
                        <p className="text-lg font-bold text-gray-900">{getDaysSinceLaunch(product.createdAt)}</p>
                      </div>
                    </div>

                    {/* Expand Details Button */}
                    <button
                      onClick={() => toggleExpanded(product.id)}
                      className="flex items-center gap-2 text-purple-600 hover:text-purple-700 font-medium text-sm"
                    >
                      {expandedProducts.has(product.id) ? (
                        <>
                          <ChevronDown className="w-4 h-4 rotate-180" />
                          Hide Details
                        </>
                      ) : (
                        <>
                          <ChevronDown className="w-4 h-4" />
                          View Details
                        </>
                      )}
                    </button>

                    {/* Expanded Details */}
                    {expandedProducts.has(product.id) && (
                      <div className="mt-4 pt-4 border-t border-gray-200 space-y-4">
                        {/* Dates Section */}
                        <div className="bg-gradient-to-r from-blue-50 to-indigo-50 p-3 rounded-lg">
                          <p className="text-sm font-semibold text-gray-900 mb-2 flex items-center gap-2">
                            <Calendar className="w-4 h-4" />
                            Timeline
                          </p>
                          <div className="space-y-2 text-sm">
                            <div className="flex justify-between">
                              <span className="text-gray-600">Listed:</span>
                              <span className="font-medium text-gray-900">{formatDate(product.createdAt)}</span>
                            </div>
                            <div className="flex justify-between">
                              <span className="text-gray-600">Sold Out:</span>
                              <span className="font-medium text-gray-900">{formatDate(product.outOfStockAt)}</span>
                            </div>
                          </div>
                        </div>

                        {/* Variants Section */}
                        {product.variants.length > 0 && (
                          <div className="bg-gradient-to-r from-amber-50 to-orange-50 p-3 rounded-lg">
                            <p className="text-sm font-semibold text-gray-900 mb-3">Variants Sold Out ({product.variants.length})</p>
                            <div className="space-y-2">
                              {product.variants.map((variant) => (
                                <div
                                  key={variant.id}
                                  className="bg-white p-2 rounded border border-gray-200 flex justify-between items-start text-sm"
                                >
                                  <div>
                                    <span className="font-medium text-gray-900">
                                      {variant.size && <span>{variant.size}</span>}
                                      {variant.size && variant.color && <span> ΓÇó </span>}
                                      {variant.color && <span>{variant.color}</span>}
                                      {!variant.size && !variant.color && <span>No variant info</span>}
                                    </span>
                                    {variant.quantity !== undefined && (
                                      <p className="text-xs text-gray-500 mt-0.5">Qty: {variant.quantity}</p>
                                    )}
                                  </div>
                                  <span className="text-xs text-gray-500 whitespace-nowrap ml-2">
                                    {formatDate(variant.soldOutAt)}
                                  </span>
                                </div>
                              ))}
                            </div>
                          </div>
                        )}

                        {/* Media Files Section */}
                        {product.media.length > 0 && (
                          <div className="bg-gradient-to-r from-purple-50 to-pink-50 p-3 rounded-lg">
                            <p className="text-sm font-semibold text-gray-900 mb-3">Product Files ({product.media.length})</p>
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                              {product.media.map((file) => (
                                <a
                                  key={file.id}
                                  href={file.url}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  className="bg-white p-2 rounded border border-gray-200 hover:border-purple-400 hover:bg-purple-50 transition text-sm flex items-center gap-2"
                                >
                                  <div className="flex-1 min-w-0">
                                    {file.type === 'VIDEO' ? (
                                      <div className="text-xs">
                                        <p className="font-medium text-gray-900 truncate">≡ƒÄÑ Video</p>
                                        <p className="text-gray-500 truncate">{file.url.split('/').pop()}</p>
                                      </div>
                                    ) : (
                                      <div className="text-xs">
                                        <p className="font-medium text-gray-900 truncate">≡ƒû╝∩╕Å Image</p>
                                        <p className="text-gray-500 truncate">{file.url.split('/').pop()}</p>
                                      </div>
                                    )}
                                  </div>
                                  {file.isPrimary && (
                                    <span className="text-xs bg-purple-100 text-purple-700 px-2 py-0.5 rounded-full whitespace-nowrap">Primary</span>
                                  )}
                                </a>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="mt-8 flex justify-center items-center gap-4">
            <button
              onClick={() => setPage(p => Math.max(1, p - 1))}
              disabled={page === 1}
              className="px-4 py-2 rounded-lg border border-gray-300 text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Previous
            </button>
            <span className="text-gray-600">
              Page {page} of {totalPages}
            </span>
            <button
              onClick={() => setPage(p => Math.min(totalPages, p + 1))}
              disabled={page === totalPages}
              className="px-4 py-2 rounded-lg bg-purple-600 text-white hover:bg-purple-700 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Next
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useSession } from 'next-auth/react';
import { useRouter } from 'next/navigation';
import toast from 'react-hot-toast';
import Image from 'next/image';
import {
  Package,
  Search,
  Check,
  X,
  Truck,
  Clock,
  CheckCircle,
  XCircle,
  ChevronLeft,
  ChevronRight,
  Play,
  ImageIcon,
  User,
  Rocket,
  Warehouse,
  ShoppingBag,
  RotateCcw,
  TrendingDown,
  AlertCircle,
} from 'lucide-react';
import Link from 'next/link';
import { FULFILLMENT_METHOD, SELLER_TIER_CONFIG, type SellerTier } from '@/lib/boutique/constants';

interface ProductMedia {
  id: string;
  url: string;
  type: 'IMAGE' | 'VIDEO';
  isPrimary: boolean;
}

interface Variant {
  id: string;
  size: string;
  color: string;
  colorHex: string;
  quantity: number;
}

interface Product {
  id: string;
  title: string;
  description: string;
  basePrice: number;
  status: string;
  thumbnailUrl: string;
  createdAt: string;
  submittedAt: string;
  fulfillmentMethod: string;
  sellerShippingLocations?: string[];
  sellerShippingTime?: string;
  category: {
    name: string;
  };
  seller: {
    id: string;
    name: string;
    email: string;
    designerTier?: string;
  };
  media: ProductMedia[];
  variants: Variant[];
  brand: string;
  material: string;
  condition: string;
  shipment?: {
    id: string;
    carrier: string;
    trackingNumber: string;
    status: string;
    estimatedArrival: string;
  };
}

interface VariantVerification {
  variantId: string;
  size: string;
  color: string;
  expected: number;
  received: number;
  damaged: number;
  passed: number;
}

interface StatusCounts {
  pendingContentReview: number;
  contentApproved: number;
  shippedToAdmin: number;
  receivedByAdmin: number;
  verificationPassed: number;
  live: number;
  rejected: number;
  // Seller Direct specific
  sellerDirectPending: number;
  sellerDirectLive: number;
}

const STATUS_CONFIG: Record<string, { label: string; color: string; bgColor: string; icon: React.ElementType }> = {
  PENDING_CONTENT_REVIEW: { label: 'Pending Review', color: 'text-yellow-700', bgColor: 'bg-yellow-50', icon: Clock },
  CONTENT_APPROVED: { label: 'Content Approved', color: 'text-blue-700', bgColor: 'bg-blue-50', icon: Check },
  SHIPPED_TO_ADMIN: { label: 'In Transit', color: 'text-purple-700', bgColor: 'bg-purple-50', icon: Truck },
  RECEIVED_BY_ADMIN: { label: 'At Warehouse', color: 'text-indigo-700', bgColor: 'bg-indigo-50', icon: Package },
  VERIFICATION_PASSED: { label: 'Verified', color: 'text-green-700', bgColor: 'bg-green-50', icon: CheckCircle },
  LIVE: { label: 'Live', color: 'text-emerald-700', bgColor: 'bg-emerald-50', icon: CheckCircle },
  REJECTED: { label: 'Rejected', color: 'text-red-700', bgColor: 'bg-red-50', icon: XCircle },
};

// Tabs for Admin Stock products
const ADMIN_STOCK_TABS = [
  { key: 'content', label: 'Content Review', status: 'PENDING_CONTENT_REVIEW' },
  { key: 'awaiting', label: 'Awaiting Shipment', status: 'CONTENT_APPROVED' },
  { key: 'transit', label: 'In Transit', status: 'SHIPPED_TO_ADMIN' },
  { key: 'warehouse', label: 'At Warehouse', status: 'RECEIVED_BY_ADMIN' },
  { key: 'verified', label: 'Ready to Go Live', status: 'VERIFICATION_PASSED' },
  { key: 'live', label: 'Live Products', status: 'LIVE' },
];

// Tabs for Seller Direct products
const SELLER_DIRECT_TABS = [
  { key: 'direct_content', label: 'Review', status: 'PENDING_CONTENT_REVIEW' },
  { key: 'direct_approved', label: 'Approved', status: 'CONTENT_APPROVED' },
  { key: 'direct_live', label: 'Live', status: 'LIVE' },
];

export default function AdminBoutiquePage() {
  const { data: session, status: authStatus } = useSession();
  const router = useRouter();

  const [loading, setLoading] = useState(true);
  const [products, setProducts] = useState<Product[]>([]);
  const [statusCounts, setStatusCounts] = useState<StatusCounts | null>(null);
  const [activeTab, setActiveTab] = useState('content');
  const [fulfillmentFilter, setFulfillmentFilter] = useState<'ALL' | 'ADMIN_STOCK' | 'SELLER_DIRECT'>('ALL');
  const [searchQuery, setSearchQuery] = useState('');
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [actionLoading, setActionLoading] = useState(false);
  const [rejectReason, setRejectReason] = useState('');
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [actionType, setActionType] = useState<'content' | 'physical'>('content');
  const [selectedMedia, setSelectedMedia] = useState<ProductMedia | null>(null);
  
  // Verification modal state
  const [showVerificationModal, setShowVerificationModal] = useState(false);
  const [variantVerifications, setVariantVerifications] = useState<VariantVerification[]>([]);
  const [verificationNotes, setVerificationNotes] = useState('');

  // Determine which tabs to show based on fulfillment filter
  const activeTabs = fulfillmentFilter === 'SELLER_DIRECT' ? SELLER_DIRECT_TABS : ADMIN_STOCK_TABS;
  const currentTabConfig = activeTabs.find(t => t.key === activeTab);
  const currentTabStatus = currentTabConfig?.status || 'PENDING_CONTENT_REVIEW';

  useEffect(() => {
    if (authStatus === 'unauthenticated') {
      router.push('/auth/signin');
    } else if (authStatus === 'authenticated' && session?.user?.role !== 'ADMIN') {
      router.push('/');
    }
  }, [authStatus, session, router]);

  useEffect(() => {
    if (session?.user?.role === 'ADMIN') {
      fetchProducts();
    }
  }, [session, activeTab, page, fulfillmentFilter]);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const fulfillmentParam = fulfillmentFilter !== 'ALL' ? `&fulfillmentMethod=${fulfillmentFilter}` : '';
      const response = await fetch(
        `/api/boutique/admin/products?status=${currentTabStatus}&page=${page}&search=${searchQuery}${fulfillmentParam}`
      );
      const data = await response.json();

      if (data.success) {
        setProducts(data.products);
        setStatusCounts(data.statusCounts);
        setTotalPages(data.pagination.totalPages);
      }
    } catch (error) {
      console.error('Failed to fetch products:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleAction = async (productId: string, action: string, reason?: string) => {
    setActionLoading(true);
    try {
      const response = await fetch(`/api/boutique/admin/products`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          productId,
          action,
          reason,
        }),
      });

      const data = await response.json();

      if (data.success) {
        // Show success message before closing
        toast.success(data.message || 'Action completed');
        setSelectedProduct(null);
        setShowRejectModal(false);
        setRejectReason('');
        fetchProducts();
      } else {
        toast.error(data.message || 'Action failed');
      }
    } catch (error) {
      console.error('Action failed:', error);
      toast.error('Action failed. Please try again.');
    } finally {
      setActionLoading(false);
    }
  };

  const openRejectModal = (type: 'content' | 'physical') => {
    setActionType(type);
    setShowRejectModal(true);
  };

  const submitRejection = () => {
    if (!rejectReason.trim()) {
      toast.error('Please provide a reason for rejection');
      return;
    }
    const action = actionType === 'content' ? 'reject_content' : 'reject_physical';
    handleAction(selectedProduct!.id, action, rejectReason);
  };

  // Open verification modal and initialize variant verifications
  const openVerificationModal = () => {
    if (!selectedProduct) return;
    
    const initialVerifications: VariantVerification[] = selectedProduct.variants.map(v => ({
      variantId: v.id,
      size: v.size,
      color: v.color,
      expected: v.quantity,
      received: v.quantity,
      damaged: 0,
      passed: v.quantity,
    }));
    
    setVariantVerifications(initialVerifications);
    setVerificationNotes('');
    setShowVerificationModal(true);
  };

  // Update a specific variant's verification data
  const updateVariantVerification = (variantId: string, field: 'received' | 'damaged' | 'passed', value: number) => {
    setVariantVerifications(prev => prev.map(v => {
      if (v.variantId !== variantId) return v;
      
      const updated = { ...v, [field]: Math.max(0, value) };
      
      // Auto-calculate passed if received or damaged changes
      if (field === 'received' || field === 'damaged') {
        updated.passed = Math.max(0, updated.received - updated.damaged);
      }
      // Ensure passed doesn't exceed received - damaged
      if (field === 'passed') {
        updated.passed = Math.min(value, updated.received - updated.damaged);
      }
      
      return updated;
    }));
  };

  // Submit verification with variant-level data
  const submitVerification = async (allPassed: boolean) => {
    if (!selectedProduct) return;
    
    setActionLoading(true);
    try {
      // Calculate totals
      const totalExpected = variantVerifications.reduce((sum, v) => sum + v.expected, 0);
      const totalReceived = variantVerifications.reduce((sum, v) => sum + v.received, 0);
      const totalDamaged = variantVerifications.reduce((sum, v) => sum + v.damaged, 0);
      const totalPassed = variantVerifications.reduce((sum, v) => sum + v.passed, 0);
      const totalMissing = totalExpected - totalReceived;
      
      const hasDiscrepancy = totalMissing > 0 || totalDamaged > 0 || totalPassed < totalExpected;
      
      const response = await fetch(`/api/boutique/admin/products`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          productId: selectedProduct.id,
          action: allPassed ? 'verify_physical' : 'reject_physical',
          reason: !allPassed ? verificationNotes : undefined,
          verification: {
            variantVerifications,
            totalExpected,
            totalReceived,
            totalDamaged,
            totalPassed,
            totalMissing,
            hasDiscrepancy,
            notes: verificationNotes,
          },
        }),
      });

      const data = await response.json();

      if (data.success) {
        toast.success(data.message || 'Verification completed');
        setShowVerificationModal(false);
        setSelectedProduct(null);
        fetchProducts();
      } else {
        toast.error(data.message || 'Verification failed');
      }
    } catch (error) {
      console.error('Verification failed:', error);
      toast.error('Verification failed. Please try again.');
    } finally {
      setActionLoading(false);
    }
  };

  if (authStatus === 'loading' || (authStatus === 'authenticated' && !session)) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600"></div>
      </div>
    );
  }

  if (session?.user?.role !== 'ADMIN') {
    return null;
  }

  const getTabCount = (key: string): number => {
    if (!statusCounts) return 0;
    switch (key) {
      // Admin Stock tabs
      case 'content': return statusCounts.pendingContentReview;
      case 'awaiting': return statusCounts.contentApproved;
      case 'transit': return statusCounts.shippedToAdmin;
      case 'warehouse': return statusCounts.receivedByAdmin;
      case 'verified': return statusCounts.verificationPassed;
      case 'live': return statusCounts.live;
      // Seller Direct tabs
      case 'direct_content': return statusCounts.sellerDirectPending || 0;
      case 'direct_approved': return statusCounts.contentApproved || 0;
      case 'direct_live': return statusCounts.sellerDirectLive || 0;
      default: return 0;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="bg-white border-b">
        <div className="max-w-7xl mx-auto px-3 sm:px-4 py-4 sm:py-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div>
              <h1 className="text-xl sm:text-2xl font-bold text-gray-900">Boutique Verification</h1>
              <p className="text-xs sm:text-base text-gray-500 mt-0.5 sm:mt-1">Review and verify products from sellers</p>
            </div>
            {/* Quick Navigation Links */}
            <div className="flex flex-wrap gap-2">
              <Link
                href="/admin/boutique/repost-approvals"
                className="inline-flex items-center gap-1.5 px-3 py-2 bg-green-100 text-green-700 rounded-lg hover:bg-green-200 text-sm font-medium transition"
                title="Approve or reject seller repost requests"
              >
                <CheckCircle className="w-4 h-4" />
                Repost Queue
              </Link>
              <Link
                href="/admin/boutique/orders"
                className="inline-flex items-center gap-1.5 px-3 py-2 bg-purple-100 text-purple-700 rounded-lg hover:bg-purple-200 text-sm font-medium transition"
              >
                <ShoppingBag className="w-4 h-4" />
                Orders
              </Link>
              <Link
                href="/admin/boutique/returns"
                className="inline-flex items-center gap-1.5 px-3 py-2 bg-amber-100 text-amber-700 rounded-lg hover:bg-amber-200 text-sm font-medium transition"
              >
                <RotateCcw className="w-4 h-4" />
                Returns
              </Link>
              <Link
                href="/admin/boutique/rejected"
                className="inline-flex items-center gap-1.5 px-3 py-2 bg-red-100 text-red-700 rounded-lg hover:bg-red-200 text-sm font-medium transition"
              >
                <XCircle className="w-4 h-4" />
                Rejected
              </Link>
              <Link
                href="/admin/boutique/shipments"
                className="inline-flex items-center gap-1.5 px-3 py-2 bg-blue-100 text-blue-700 rounded-lg hover:bg-blue-200 text-sm font-medium transition"
              >
                <Truck className="w-4 h-4" />
                Shipments
              </Link>
              <Link
                href="/admin/boutique/appeals"
                className="inline-flex items-center gap-1.5 px-3 py-2 bg-indigo-100 text-indigo-700 rounded-lg hover:bg-indigo-200 text-sm font-medium transition"
              >
                <AlertCircle className="w-4 h-4" />
                Appeals
              </Link>
              <Link
                href="/admin/boutique/out-of-stock"
                className="inline-flex items-center gap-1.5 px-3 py-2 bg-orange-100 text-orange-700 rounded-lg hover:bg-orange-200 text-sm font-medium transition"
              >
                <TrendingDown className="w-4 h-4" />
                Sold Out
              </Link>
            </div>
          </div>
        </div>
      </div>

      {/* Fulfillment Type Filter */}
      <div className="bg-gradient-to-r from-purple-50 to-blue-50 border-b">
        <div className="max-w-7xl mx-auto px-3 sm:px-4 py-2 sm:py-3">
          <div className="flex items-center gap-2 sm:gap-4">
            <span className="text-[10px] sm:text-sm font-medium text-gray-700 hidden xs:inline">View:</span>
            <div className="flex bg-white rounded-lg p-0.5 sm:p-1 shadow-sm overflow-x-auto">
              <button
                onClick={() => { setFulfillmentFilter('ALL'); setActiveTab('content'); setPage(1); }}
                className={`px-2 sm:px-4 py-1.5 sm:py-2 rounded-md text-[10px] sm:text-sm font-medium transition-all whitespace-nowrap ${
                  fulfillmentFilter === 'ALL'
                    ? 'bg-purple-600 text-white shadow'
                    : 'text-gray-600 hover:bg-gray-100'
                }`}
              >
                All
              </button>
              <button
                onClick={() => { setFulfillmentFilter('ADMIN_STOCK'); setActiveTab('content'); setPage(1); }}
                className={`px-2 sm:px-4 py-1.5 sm:py-2 rounded-md text-[10px] sm:text-sm font-medium transition-all flex items-center gap-1 sm:gap-2 whitespace-nowrap ${
                  fulfillmentFilter === 'ADMIN_STOCK'
                    ? 'bg-blue-600 text-white shadow'
                    : 'text-gray-600 hover:bg-gray-100'
                }`}
              >
                <Warehouse className="w-3 h-3 sm:w-4 sm:h-4" />
                <span className="hidden xs:inline">Admin </span>Stock
              </button>
              <button
                onClick={() => { setFulfillmentFilter('SELLER_DIRECT'); setActiveTab('direct_content'); setPage(1); }}
                className={`px-2 sm:px-4 py-1.5 sm:py-2 rounded-md text-[10px] sm:text-sm font-medium transition-all flex items-center gap-1 sm:gap-2 whitespace-nowrap ${
                  fulfillmentFilter === 'SELLER_DIRECT'
                    ? 'bg-purple-600 text-white shadow'
                    : 'text-gray-600 hover:bg-gray-100'
                }`}
              >
                <Rocket className="w-3 h-3 sm:w-4 sm:h-4" />
                <span className="hidden xs:inline">Seller </span>Direct
              </button>
            </div>
            {fulfillmentFilter !== 'ALL' && (
              <div className={`px-2 sm:px-3 py-0.5 sm:py-1 rounded-full text-[10px] sm:text-xs font-medium hidden sm:block ${
                fulfillmentFilter === 'SELLER_DIRECT' 
                  ? 'bg-purple-100 text-purple-700' 
                  : 'bg-blue-100 text-blue-700'
              }`}>
                {fulfillmentFilter === 'SELLER_DIRECT' 
                  ? '≡ƒÜÇ Seller ships to buyers directly' 
                  : '≡ƒÅó Products in your warehouse'
                }
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="bg-white border-b sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-3 sm:px-4">
          <div className="flex overflow-x-auto gap-1 py-1.5 sm:py-2 -mx-1 px-1">
            {activeTabs.map(tab => (
              <button
                key={tab.key}
                onClick={() => { setActiveTab(tab.key); setPage(1); }}
                className={`px-2 sm:px-4 py-1.5 sm:py-2 rounded-lg whitespace-nowrap text-[10px] sm:text-sm font-medium flex items-center gap-1 sm:gap-2 transition-colors ${
                  activeTab === tab.key
                    ? 'bg-purple-100 text-purple-700'
                    : 'text-gray-600 hover:bg-gray-100'
                }`}
              >
                <span className="hidden xs:inline">{tab.label}</span>
                <span className="xs:hidden">{tab.label.split(' ')[0]}</span>
                <span className={`px-1.5 sm:px-2 py-0.5 rounded-full text-[9px] sm:text-xs ${
                  activeTab === tab.key ? 'bg-purple-200' : 'bg-gray-200'
                }`}>
                  {getTabCount(tab.key)}
                </span>
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-3 sm:px-4 py-4 sm:py-6">
        {/* Search */}
        <div className="flex items-center gap-2 sm:gap-4 mb-4 sm:mb-6">
          <div className="flex-1 relative">
            <Search className="absolute left-2.5 sm:left-3 top-1/2 -translate-y-1/2 w-4 h-4 sm:w-5 sm:h-5 text-gray-400" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && fetchProducts()}
              placeholder="Search..."
              className="w-full pl-8 sm:pl-10 pr-3 sm:pr-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-500 text-sm"
            />
          </div>
          <button
            onClick={fetchProducts}
            className="px-3 sm:px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 text-xs sm:text-sm"
          >
            Search
          </button>
        </div>

        {/* Loading */}
        {loading ? (
          <div className="flex items-center justify-center py-12 sm:py-20">
            <div className="animate-spin rounded-full h-8 w-8 sm:h-12 sm:w-12 border-b-2 border-purple-600"></div>
          </div>
        ) : products.length === 0 ? (
          <div className="bg-white rounded-xl p-8 sm:p-12 text-center">
            <Package className="w-12 h-12 sm:w-16 sm:h-16 text-gray-300 mx-auto mb-3 sm:mb-4" />
            <h3 className="text-base sm:text-lg font-semibold text-gray-900">No Products</h3>
            <p className="text-xs sm:text-base text-gray-500 mt-1">No products in this queue</p>
          </div>
        ) : (
          <>
            {/* Product Grid */}
            <div className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-3 gap-3 sm:gap-6">
              {products.map(product => {
                const status = STATUS_CONFIG[product.status] || STATUS_CONFIG.PENDING_CONTENT_REVIEW;
                const StatusIcon = status.icon;
                const isSellerDirect = product.fulfillmentMethod === FULFILLMENT_METHOD.SELLER_DIRECT;
                const sellerTier = product.seller?.designerTier as SellerTier | undefined;
                
                return (
                  <div
                    key={product.id}
                    className="bg-white rounded-xl overflow-hidden shadow-sm hover:shadow-md transition-shadow cursor-pointer"
                    onClick={() => setSelectedProduct(product)}
                  >
                    {/* Thumbnail */}
                    <div className="aspect-[4/3] bg-gray-100 relative">
                      {product.thumbnailUrl || (product.media && product.media[0]?.url) ? (
                        <Image
                          src={product.thumbnailUrl || product.media[0]?.url || ''}
                          alt={product.title}
                          fill
                          className="object-cover"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center">
                          <ImageIcon className="w-8 h-8 sm:w-12 sm:h-12 text-gray-300" />
                        </div>
                      )}
                      {/* Status Badge */}
                      <div className={`absolute top-2 sm:top-3 left-2 sm:left-3 px-1.5 sm:px-2 py-0.5 sm:py-1 rounded-full text-[9px] sm:text-xs font-medium flex items-center gap-0.5 sm:gap-1 ${status.bgColor} ${status.color}`}>
                        <StatusIcon className="w-2.5 h-2.5 sm:w-3 sm:h-3" />
                        <span className="hidden xs:inline">{status.label}</span>
                      </div>
                      {/* Fulfillment Badge */}
                      <div className={`absolute top-2 sm:top-3 right-2 sm:right-3 px-1.5 sm:px-2 py-0.5 sm:py-1 rounded-full text-[9px] sm:text-xs font-medium flex items-center gap-0.5 sm:gap-1 ${
                        isSellerDirect 
                          ? 'bg-purple-600 text-white' 
                          : 'bg-blue-100 text-blue-700'
                      }`}>
                        {isSellerDirect ? (
                          <>
                            <Rocket className="w-2.5 h-2.5 sm:w-3 sm:h-3" />
                            <span className="hidden xs:inline">Direct</span>
                          </>
                        ) : (
                          <>
                            <Warehouse className="w-2.5 h-2.5 sm:w-3 sm:h-3" />
                            <span className="hidden xs:inline">Stock</span>
                          </>
                        )}
                      </div>
                    </div>

                    {/* Info */}
                    <div className="p-2 sm:p-4">
                      <h3 className="font-semibold text-gray-900 line-clamp-1 text-xs sm:text-base">{product.title}</h3>
                      <p className="text-[10px] sm:text-sm text-gray-500">{product.category.name}</p>
                      
                      {/* Seller Tier Badge */}
                      {sellerTier && SELLER_TIER_CONFIG[sellerTier] && (
                        <div className={`inline-flex items-center gap-0.5 sm:gap-1 mt-1.5 sm:mt-2 px-1.5 sm:px-2 py-0.5 rounded-full text-[9px] sm:text-xs ${SELLER_TIER_CONFIG[sellerTier].bgColor} ${SELLER_TIER_CONFIG[sellerTier].color}`}>
                          <span>{SELLER_TIER_CONFIG[sellerTier].badge}</span>
                          <span className="hidden xs:inline">{SELLER_TIER_CONFIG[sellerTier].label}</span>
                        </div>
                      )}
                      
                      <div className="flex items-center justify-between mt-2 sm:mt-3">
                        <span className="text-purple-600 font-semibold text-xs sm:text-base">
                          Γéª{product.basePrice.toLocaleString()}
                        </span>
                        <span className="text-[9px] sm:text-xs text-gray-500">
                          {new Date(product.submittedAt || product.createdAt).toLocaleDateString()}
                        </span>
                      </div>

                      <div className="flex items-center gap-1.5 sm:gap-2 mt-2 sm:mt-3 pt-2 sm:pt-3 border-t">
                        <div className="w-5 h-5 sm:w-6 sm:h-6 bg-gray-200 rounded-full flex items-center justify-center">
                          <User className="w-3 h-3 sm:w-4 sm:h-4 text-gray-500" />
                        </div>
                        <span className="text-[10px] sm:text-sm text-gray-600 truncate">{product.seller.name}</span>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>

            {/* Pagination */}
            {totalPages > 1 && (
              <div className="flex items-center justify-center gap-3 sm:gap-4 mt-6 sm:mt-8">
                <button
                  onClick={() => setPage(p => Math.max(1, p - 1))}
                  disabled={page === 1}
                  className="p-1.5 sm:p-2 rounded-lg border hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                  aria-label="Previous page"
                >
                  <ChevronLeft className="w-4 h-4 sm:w-5 sm:h-5" />
                </button>
                <span className="text-xs sm:text-sm text-gray-600">
                  Page {page} of {totalPages}
                </span>
                <button
                  onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                  disabled={page === totalPages}
                  className="p-1.5 sm:p-2 rounded-lg border hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                  aria-label="Next page"
                >
                  <ChevronRight className="w-4 h-4 sm:w-5 sm:h-5" />
                </button>
              </div>
            )}
          </>
        )}
      </div>

      {/* Product Detail Modal */}
      {selectedProduct && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-2 sm:p-4">
          <div className="bg-white rounded-xl sm:rounded-2xl max-w-4xl w-full max-h-[95vh] sm:max-h-[90vh] overflow-y-auto">
            {/* Modal Header */}
            <div className="sticky top-0 bg-white border-b px-3 sm:px-6 py-3 sm:py-4 flex items-center justify-between">
              <h2 className="text-base sm:text-xl font-bold text-gray-900">Review Product</h2>
              <button
                onClick={() => setSelectedProduct(null)}
                className="p-1.5 sm:p-2 hover:bg-gray-100 rounded-lg"
                aria-label="Close modal"
              >
                <X className="w-4 h-4 sm:w-5 sm:h-5" />
              </button>
            </div>

            <div className="p-3 sm:p-6">
              {/* Media Gallery */}
              <div className="mb-4 sm:mb-6">
                <h3 className="font-semibold text-gray-900 mb-2 sm:mb-3 flex items-center gap-1.5 sm:gap-2 text-sm sm:text-base">
                  <ImageIcon className="w-4 h-4 sm:w-5 sm:h-5" />
                  Media ({selectedProduct.media.length})
                </h3>
                <div className="grid grid-cols-3 sm:grid-cols-4 gap-2 sm:gap-3">
                  {selectedProduct.media.map((m, i) => (
                    <button
                      key={m.id}
                      onClick={() => setSelectedMedia(m)}
                      className="aspect-square bg-gray-100 rounded-lg overflow-hidden relative group hover:opacity-80 transition-opacity cursor-pointer"
                    >
                      {m.type === 'IMAGE' ? (
                        <Image
                          src={m.url}
                          alt={`Media ${i + 1}`}
                          fill
                          className="object-cover"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center bg-gray-900 group-hover:bg-gray-800 transition-colors">
                          <Play className="w-6 h-6 sm:w-8 sm:h-8 text-white" />
                        </div>
                      )}
                      {m.isPrimary && (
                        <div className="absolute top-0.5 sm:top-1 left-0.5 sm:left-1 bg-purple-600 text-white text-[8px] sm:text-xs px-1 sm:px-1.5 py-0.5 rounded">
                          1st
                        </div>
                      )}
                      <div className="absolute bottom-0.5 sm:bottom-1 right-0.5 sm:right-1 bg-black/70 text-white text-[8px] sm:text-xs px-1 sm:px-1.5 py-0.5 rounded">
                        {m.type}
                      </div>
                    </button>
                  ))}
                </div>
              </div>

              {/* Product Info */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 sm:gap-6 mb-4 sm:mb-6">
                <div>
                  <h3 className="font-semibold text-gray-900 mb-2 sm:mb-3 text-sm sm:text-base">Product Details</h3>
                  <div className="space-y-1.5 sm:space-y-2 text-xs sm:text-sm text-black">
                    <p><strong>Title:</strong> {selectedProduct.title}</p>
                    <p><strong>Category:</strong> {selectedProduct.category.name}</p>
                    <p><strong>Price:</strong> Γéª{selectedProduct.basePrice.toLocaleString()}</p>
                    <p><strong>Brand:</strong> {selectedProduct.brand || 'N/A'}</p>
                    <p><strong>Material:</strong> {selectedProduct.material || 'N/A'}</p>
                    <p><strong>Condition:</strong> {selectedProduct.condition}</p>
                  </div>
                  
                  <div className="mt-3 sm:mt-4">
                    <strong className="text-xs sm:text-sm text-black">Description:</strong>
                    <p className="text-xs sm:text-sm text-black mt-1 whitespace-pre-wrap break-words leading-relaxed">{selectedProduct.description}</p>
                  </div>
                </div>

                <div>
                  <h3 className="font-semibold text-gray-900 mb-2 sm:mb-3 text-sm sm:text-base">Seller Info</h3>
                  <div className="space-y-1.5 sm:space-y-2 text-xs sm:text-sm text-black">
                    <p><strong>Name:</strong> {selectedProduct.seller.name}</p>
                    <p><strong>Email:</strong> {selectedProduct.seller.email}</p>
                  </div>

                  {/* Variants */}
                  <h3 className="font-semibold text-gray-900 mt-3 sm:mt-4 mb-2 sm:mb-3 text-sm sm:text-base">Variants</h3>
                  <div className="space-y-1.5 sm:space-y-2">
                    {selectedProduct.variants.map((v, _i) => (
                      <div key={v.id} className="flex items-center gap-1.5 sm:gap-2 text-[10px] sm:text-sm p-1.5 sm:p-2 bg-gray-50 rounded text-black">
                        {v.colorHex && (
                          <div
                            className="w-3 h-3 sm:w-4 sm:h-4 rounded-full border"
                            style={{ backgroundColor: v.colorHex }}
                          />
                        )}
                        <span>{v.color || 'No color'}</span>
                        <span>ΓÇó</span>
                        <span>{v.size || 'No size'}</span>
                        <span>ΓÇó</span>
                        <span>Qty: {v.quantity}</span>
                      </div>
                    ))}
                  </div>

                  {/* Shipment Info */}
                  {selectedProduct.shipment && (
                    <>
                      <h3 className="font-semibold text-gray-900 mt-3 sm:mt-4 mb-2 sm:mb-3 flex items-center gap-1.5 sm:gap-2 text-sm sm:text-base">
                        <Truck className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                        Shipment Details
                      </h3>
                      <div className="space-y-1.5 sm:space-y-2 text-xs sm:text-sm p-2 sm:p-3 bg-blue-50 rounded-lg text-black">
                        <p><strong>Courier:</strong> {selectedProduct.shipment.carrier || 'N/A'}</p>
                        <p><strong>Tracking Number:</strong> {selectedProduct.shipment.trackingNumber || 'N/A'}</p>
                        <p><strong>Status:</strong> {selectedProduct.shipment.status || 'N/A'}</p>
                        {selectedProduct.shipment.estimatedArrival && (
                          <p><strong>Estimated Arrival:</strong> {new Date(selectedProduct.shipment.estimatedArrival).toLocaleDateString()}</p>
                        )}
                      </div>
                    </>
                  )}
                </div>
              </div>

              {/* Action Buttons */}
              <div className="border-t pt-4 sm:pt-6">
                {selectedProduct.status === 'PENDING_CONTENT_REVIEW' && (
                  <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2 sm:gap-4">
                    <button
                      type="button"
                      onClick={() => handleAction(selectedProduct.id, 'approve_content')}
                      disabled={actionLoading}
                      className="flex-1 py-2.5 sm:py-3 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-700 disabled:opacity-50 flex items-center justify-center gap-1.5 sm:gap-2 text-sm sm:text-base"
                    >
                      <CheckCircle className="w-4 h-4 sm:w-5 sm:h-5" />
                      Approve
                    </button>
                    <button
                      type="button"
                      onClick={() => openRejectModal('content')}
                      disabled={actionLoading}
                      className="flex-1 py-2.5 sm:py-3 bg-red-600 text-white font-semibold rounded-lg hover:bg-red-700 disabled:opacity-50 flex items-center justify-center gap-1.5 sm:gap-2 text-sm sm:text-base"
                    >
                      <XCircle className="w-4 h-4 sm:w-5 sm:h-5" />
                      Reject
                    </button>
                  </div>
                )}

                {selectedProduct.status === 'SHIPPED_TO_ADMIN' && (
                  <button
                    type="button"
                    onClick={() => handleAction(selectedProduct.id, 'mark_received')}
                    disabled={actionLoading}
                    className="w-full py-2.5 sm:py-3 bg-indigo-600 text-white font-semibold rounded-lg hover:bg-indigo-700 disabled:opacity-50 flex items-center justify-center gap-1.5 sm:gap-2 text-sm sm:text-base"
                  >
                    <Package className="w-4 h-4 sm:w-5 sm:h-5" />
                    <span className="hidden xs:inline">Mark as </span>Received
                  </button>
                )}

                {selectedProduct.status === 'RECEIVED_BY_ADMIN' && (
                  <button
                    type="button"
                    onClick={openVerificationModal}
                    disabled={actionLoading}
                    className="w-full py-2.5 sm:py-3 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-700 disabled:opacity-50 flex items-center justify-center gap-1.5 sm:gap-2 text-sm sm:text-base"
                  >
                    <Package className="w-4 h-4 sm:w-5 sm:h-5" />
                    Verify Items Received
                  </button>
                )}

                {selectedProduct.status === 'VERIFICATION_PASSED' && (
                  <button
                    type="button"
                    onClick={() => handleAction(selectedProduct.id, 'go_live')}
                    disabled={actionLoading}
                    className="w-full py-2.5 sm:py-3 bg-purple-600 text-white font-semibold rounded-lg hover:bg-purple-700 disabled:opacity-50 flex items-center justify-center gap-1.5 sm:gap-2 text-sm sm:text-base"
                  >
                    <CheckCircle className="w-4 h-4 sm:w-5 sm:h-5" />
                    Go Live
                  </button>
                )}

                {selectedProduct.status === 'LIVE' && (
                  <div className="text-center text-green-600">
                    <CheckCircle className="w-6 h-6 sm:w-8 sm:h-8 mx-auto mb-1.5 sm:mb-2" />
                    <p className="font-semibold text-sm sm:text-base">Product is live</p>
                  </div>
                )}

                {selectedProduct.status === 'CONTENT_APPROVED' && (
                  <div className="text-center text-blue-600">
                    <Clock className="w-6 h-6 sm:w-8 sm:h-8 mx-auto mb-1.5 sm:mb-2" />
                    <p className="font-semibold text-sm sm:text-base">Awaiting seller shipment</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Media Viewer Modal */}
      {selectedMedia && (
        <div
          className="fixed inset-0 bg-black/70 z-[70] flex items-center justify-center p-2 sm:p-4"
          onClick={() => setSelectedMedia(null)}
        >
          <div
            className="relative bg-white rounded-xl max-w-4xl w-full max-h-[90vh] flex flex-col"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header */}
            <div className="flex items-center justify-between p-3 sm:p-4 border-b border-gray-200">
              <h3 className="text-sm sm:text-lg font-semibold text-gray-900 flex items-center gap-2">
                {selectedMedia.type === 'IMAGE' ? (
                  <>
                    <ImageIcon className="w-4 h-4 sm:w-5 sm:h-5" />
                    Image Viewer
                  </>
                ) : (
                  <>
                    <Play className="w-4 h-4 sm:w-5 sm:h-5" />
                    Video Player
                  </>
                )}
              </h3>
              <button
                onClick={() => setSelectedMedia(null)}
                className="p-1 hover:bg-gray-100 rounded-lg transition-colors"
                title="Close media viewer"
                aria-label="Close media viewer"
              >
                <X className="w-5 h-5 sm:w-6 sm:h-6 text-gray-600" />
              </button>
            </div>

            {/* Content */}
            <div className="flex-1 overflow-auto flex items-center justify-center bg-gray-50">
              {selectedMedia.type === 'IMAGE' ? (
                <div className="relative w-full h-full min-h-[300px] sm:min-h-[500px]">
                  <Image
                    src={selectedMedia.url}
                    alt="Full size"
                    fill
                    className="object-contain p-2 sm:p-4"
                  />
                </div>
              ) : (
                <video
                  src={selectedMedia.url}
                  controls
                  autoPlay
                  className="w-full h-full object-contain"
                />
              )}
            </div>

            {/* Footer with info */}
            <div className="p-3 sm:p-4 border-t border-gray-200 bg-gray-50">
              <p className="text-xs sm:text-sm text-gray-600">
                {selectedMedia.type === 'IMAGE' ? 'Click the X button or outside to close' : 'Use player controls to play/pause and adjust volume'}
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Rejection Modal */}
      {showRejectModal && (
        <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-3 sm:p-4">
          <div className="bg-white rounded-xl max-w-md w-full p-4 sm:p-6">
            <h3 className="text-base sm:text-lg font-bold text-gray-900 mb-3 sm:mb-4">
              Reject {actionType === 'content' ? 'Content' : 'Product'}
            </h3>
            <p className="text-xs sm:text-sm text-gray-600 mb-3 sm:mb-4">
              Provide a reason for rejection. This will be sent to the seller.
            </p>
            <textarea
              value={rejectReason}
              onChange={(e) => setRejectReason(e.target.value)}
              rows={4}
              placeholder="Enter rejection reason..."
              className="w-full px-3 sm:px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-red-500 resize-none text-sm"
            />
            <div className="flex items-center gap-2 sm:gap-4 mt-3 sm:mt-4">
              <button
                onClick={() => { setShowRejectModal(false); setRejectReason(''); }}
                className="flex-1 py-2 border border-gray-200 rounded-lg hover:bg-gray-50 text-sm"
              >
                Cancel
              </button>
              <button
                onClick={submitRejection}
                disabled={actionLoading}
                className="flex-1 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 disabled:opacity-50 text-sm"
              >
                {actionLoading ? 'Rejecting...' : 'Confirm'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Verification Modal */}
      {showVerificationModal && selectedProduct && (
        <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-3 sm:p-4 overflow-y-auto">
          <div className="bg-white rounded-xl max-w-2xl w-full p-4 sm:p-6 my-4">
            <h3 className="text-base sm:text-lg font-bold text-gray-900 mb-1">
              Verify Items Received
            </h3>
            <p className="text-xs sm:text-sm text-gray-600 mb-4">
              Update the quantity received for each variant. Items that didn&apos;t pass will be recorded as discrepancies.
            </p>

            {/* Variant Verification Table */}
            <div className="space-y-3 mb-4 max-h-[50vh] overflow-y-auto">
              {variantVerifications.map((v, index) => {
                const hasIssue = v.received < v.expected || v.damaged > 0 || v.passed < v.expected;
                return (
                  <div 
                    key={v.variantId} 
                    className={`p-3 rounded-lg border ${hasIssue ? 'border-orange-300 bg-orange-50' : 'border-gray-200 bg-gray-50'}`}
                  >
                    {/* Variant Info */}
                    <div className="flex items-center gap-2 mb-3">
                      <div 
                        className="w-4 h-4 rounded-full border border-gray-300" 
                        style={{ backgroundColor: selectedProduct.variants[index]?.colorHex || '#888' }}
                      />
                      <span className="font-medium text-gray-900 text-sm">
                        {v.color} ΓÇó {v.size}
                      </span>
                      <span className="text-gray-500 text-xs">
                        Expected: {v.expected}
                      </span>
                    </div>

                    {/* Input Fields */}
                    <div className="grid grid-cols-3 gap-2 text-xs">
                      <div>
                        <label htmlFor={`received-${v.variantId}`} className="block text-gray-600 mb-1">Received</label>
                        <input
                          id={`received-${v.variantId}`}
                          type="number"
                          min="0"
                          max={v.expected}
                          value={v.received}
                          onChange={(e) => updateVariantVerification(v.variantId, 'received', parseInt(e.target.value) || 0)}
                          className="w-full px-2 py-1.5 border border-gray-300 rounded text-sm text-center text-gray-900"
                        />
                      </div>
                      <div>
                        <label htmlFor={`damaged-${v.variantId}`} className="block text-gray-600 mb-1">Damaged</label>
                        <input
                          id={`damaged-${v.variantId}`}
                          type="number"
                          min="0"
                          max={v.received}
                          value={v.damaged}
                          onChange={(e) => updateVariantVerification(v.variantId, 'damaged', parseInt(e.target.value) || 0)}
                          className="w-full px-2 py-1.5 border border-gray-300 rounded text-sm text-center text-gray-900"
                        />
                      </div>
                      <div>
                        <label htmlFor={`passed-${v.variantId}`} className="block text-gray-600 mb-1">Passed</label>
                        <input
                          id={`passed-${v.variantId}`}
                          type="number"
                          min="0"
                          max={v.received - v.damaged}
                          value={v.passed}
                          onChange={(e) => updateVariantVerification(v.variantId, 'passed', parseInt(e.target.value) || 0)}
                          className="w-full px-2 py-1.5 border border-green-300 bg-green-50 rounded text-sm text-center font-medium text-green-700"
                        />
                      </div>
                    </div>

                    {/* Discrepancy Warning */}
                    {hasIssue && (
                      <div className="mt-2 text-xs text-orange-700 flex items-center gap-1">
                        <XCircle className="w-3 h-3" />
                        {v.expected - v.received > 0 && <span>{v.expected - v.received} missing. </span>}
                        {v.damaged > 0 && <span>{v.damaged} damaged. </span>}
                        {v.passed < v.received - v.damaged && <span>{v.received - v.damaged - v.passed} failed verification.</span>}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            {/* Summary */}
            <div className="bg-gray-100 rounded-lg p-3 mb-4 text-sm">
              <div className="grid grid-cols-4 gap-2 text-center">
                <div>
                  <p className="text-gray-500 text-xs">Expected</p>
                  <p className="font-bold text-gray-900">{variantVerifications.reduce((s, v) => s + v.expected, 0)}</p>
                </div>
                <div>
                  <p className="text-gray-500 text-xs">Received</p>
                  <p className="font-bold text-blue-600">{variantVerifications.reduce((s, v) => s + v.received, 0)}</p>
                </div>
                <div>
                  <p className="text-gray-500 text-xs">Damaged</p>
                  <p className="font-bold text-red-600">{variantVerifications.reduce((s, v) => s + v.damaged, 0)}</p>
                </div>
                <div>
                  <p className="text-gray-500 text-xs">Passed</p>
                  <p className="font-bold text-green-600">{variantVerifications.reduce((s, v) => s + v.passed, 0)}</p>
                </div>
              </div>
            </div>

            {/* Notes */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">Notes (optional)</label>
              <textarea
                value={verificationNotes}
                onChange={(e) => setVerificationNotes(e.target.value)}
                rows={2}
                placeholder="Add notes about discrepancies, condition, etc..."
                className="w-full px-3 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 resize-none text-sm text-gray-900"
              />
            </div>

            {/* Action Buttons */}
            <div className="flex items-center gap-3">
              <button
                onClick={() => setShowVerificationModal(false)}
                className="flex-1 py-2.5 border border-gray-300 rounded-lg hover:bg-gray-50 text-sm font-medium text-gray-700"
              >
                Cancel
              </button>
              {variantVerifications.reduce((s, v) => s + v.passed, 0) < variantVerifications.reduce((s, v) => s + v.expected, 0) ? (
                <button
                  onClick={() => submitVerification(false)}
                  disabled={actionLoading}
                  className="flex-1 py-2.5 bg-orange-600 text-white rounded-lg hover:bg-orange-700 disabled:opacity-50 text-sm font-medium flex items-center justify-center gap-1.5"
                >
                  <XCircle className="w-4 h-4" />
                  {actionLoading ? 'Saving...' : 'Record Discrepancy'}
                </button>
              ) : (
                <button
                  onClick={() => submitVerification(true)}
                  disabled={actionLoading}
                  className="flex-1 py-2.5 bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:opacity-50 text-sm font-medium flex items-center justify-center gap-1.5"
                >
                  <CheckCircle className="w-4 h-4" />
                  {actionLoading ? 'Saving...' : 'Pass Verification'}
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { 
  Package, 
  Search, 
  ChevronLeft, 
  ChevronRight,
  ChevronDown,
  _AlertCircle,
  CheckCircle,
  Clock,
  User,
} from 'lucide-react'
import toast from 'react-hot-toast'
import { ProductImage } from '@/components/ProductImage'

interface Seller {
  id: string
  name: string
  email: string
}

interface ReturnProduct {
  id: string
  title: string
  status: string
  thumbnailUrl: string | null
  basePrice: number
  rejectionReason: string | null
  createdAt: string
  seller: Seller
  shipment?: {
    id: string
    status: string
    createdAt: string
    itemsExpected?: number
    itemsReceived?: number
    disputeNotes?: string | null
  }
}

export default function AdminRejectedReturnsPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [products, setProducts] = useState<ReturnProduct[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [expandedProductId, setExpandedProductId] = useState<string | null>(null)

  useEffect(() => {
    if (status === 'loading') return
    if (!session || (session.user as { role?: string }).role !== 'ADMIN') {
      router.push('/auth/signin')
      return
    }
    fetchReturnsInProgress()
  }, [session, status, router])

  const fetchReturnsInProgress = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        page: page.toString(),
        limit: '20',
      })
      if (searchQuery) params.append('search', searchQuery)

      const res = await fetch(`/api/boutique/admin/rejected-returns?${params}`)
      if (res.ok) {
        const data = await res.json()
        setProducts(data.products || [])
        setTotalPages(data.totalPages || 1)
      } else if (res.status === 404) {
        // Endpoint not yet implemented - will show empty state
        setProducts([])
        setTotalPages(1)
      }
    } catch (error) {
      console.error('Failed to fetch returns:', error)
      toast.error('Failed to load returns')
    } finally {
      setLoading(false)
    }
  }

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault()
    setPage(1)
    fetchReturnsInProgress()
  }

  const getStatusConfig = (status: string) => {
    const configs: Record<string, { color: string; icon: any; label: string }> = {
      'RETURN_IN_PROGRESS': {
        color: 'bg-yellow-100 text-yellow-700',
        icon: Clock,
        label: 'In Progress',
      },
      'SELLER_RECEIVED': {
        color: 'bg-blue-100 text-blue-700',
        icon: Package,
        label: 'Seller Received',
      },
      'ADMIN_CONFIRMED': {
        color: 'bg-purple-100 text-purple-700',
        icon: CheckCircle,
        label: 'Verified',
      },
      'RETURNED_SUCCESSFUL': {
        color: 'bg-green-100 text-green-700',
        icon: CheckCircle,
        label: 'Completed',
      },
    }
    return configs[status] || configs['RETURN_IN_PROGRESS']
  }

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-NG', {
      style: 'currency',
      currency: 'NGN',
      minimumFractionDigits: 0,
    }).format(amount)
  }

  const formatDate = (date: string) => {
    return new Date(date).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    })
  }

  if (status === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600"></div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 py-3 sm:py-8">
      <div className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="mb-3 sm:mb-8">
          <Link href="/admin/boutique" className="text-purple-600 hover:text-purple-700 flex items-center gap-1 mb-2 sm:mb-4 text-[10px] sm:text-sm">
            <ChevronLeft className="w-3 h-3 sm:w-4 sm:h-4" />
            Back to Admin
          </Link>
          <div className="flex items-center gap-2 sm:gap-3">
            <Package className="w-5 h-5 sm:w-8 sm:h-8 text-purple-600" />
            <div>
              <h1 className="text-lg sm:text-3xl font-bold text-black">Rejected Products - Return Tracking</h1>
              <p className="text-[10px] sm:text-base text-black">
                {products.length} products in return workflow
              </p>
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-xl shadow-sm p-2.5 sm:p-4 mb-3 sm:mb-6">
          <form onSubmit={handleSearch}>
            <div className="relative">
              <Search className="absolute left-2.5 sm:left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 sm:w-5 sm:h-5 text-gray-400" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search by product title, seller name, or ID..."
                className="w-full pl-7 sm:pl-10 pr-2.5 sm:pr-4 py-1.5 sm:py-2 border rounded-lg text-black bg-white focus:ring-2 focus:ring-purple-500 text-[11px] sm:text-sm placeholder-gray-500"
              />
            </div>
          </form>
        </div>

        {/* Products List */}
        {products.length === 0 ? (
          <div className="bg-white rounded-2xl shadow-sm p-6 sm:p-12 text-center">
            <Package className="w-10 h-10 sm:w-16 sm:h-16 text-gray-300 mx-auto mb-2 sm:mb-4" />
            <h3 className="text-base sm:text-lg font-medium text-black mb-1 sm:mb-2">No Returns In Progress</h3>
            <p className="text-[11px] sm:text-base text-black">
              {searchQuery ? 'Try adjusting your filters' : 'No rejected products are being returned'}
            </p>
          </div>
        ) : (
          <div className="space-y-1.5 sm:space-y-4">
            {products.map((product) => {
              const statusConfig = getStatusConfig(product.status)
              const StatusIcon = statusConfig.icon
              return (
                <div
                  key={product.id}
                  className="bg-white rounded-lg shadow-sm overflow-hidden hover:shadow-md transition-shadow"
                >
                  {/* Collapsible Header */}
                  <button
                    onClick={() => setExpandedProductId(expandedProductId === product.id ? null : product.id)}
                    className="w-full p-1.5 sm:p-4 md:p-6 flex items-center justify-between hover:bg-gray-50 transition"
                  >
                    <div className="flex items-center gap-1.5 sm:gap-4 flex-1 min-w-0">
                      {/* Product Image */}
                      <div className="w-12 h-12 sm:w-20 sm:h-20 rounded-lg overflow-hidden bg-gray-200 flex-shrink-0 flex items-center justify-center">
                        <ProductImage
                          src={product.thumbnailUrl}
                          alt={product.title}
                          containerClassName="w-full h-full rounded-lg overflow-hidden bg-gray-200 flex items-center justify-center"
                          className="w-full h-full object-cover"
                          fallbackClassName="w-7 h-7 sm:w-8 sm:h-8 text-gray-400"
                        />
                      </div>

                      {/* Product Summary */}
                      <div className="flex-1 min-w-0 text-left">
                        <div className="flex items-start justify-between gap-1 mb-0.5 sm:mb-1">
                          <h3 className="font-semibold text-black text-[10px] sm:text-base leading-tight truncate">
                            {product.title}
                          </h3>
                          <span className={`inline-flex items-center gap-1 px-1.5 sm:px-2.5 py-0.5 sm:py-1 rounded-full text-[9px] sm:text-xs font-medium ${statusConfig.color} flex-shrink-0`}>
                            <StatusIcon className="w-2.5 h-2.5 sm:w-3 sm:h-3" />
                            {statusConfig.label}
                          </span>
                        </div>
                        <p className="text-[9px] sm:text-sm text-black">
                          {formatCurrency(product.basePrice)} ΓÇó {product.seller.name}
                        </p>
                      </div>
                    </div>

                    {/* Expand/Collapse Chevron */}
                    <ChevronDown
                      className={`w-4 h-4 sm:w-5 sm:h-5 text-gray-400 flex-shrink-0 ml-2 transition-transform ${
                        expandedProductId === product.id ? 'rotate-180' : ''
                      }`}
                    />
                  </button>

                  {/* Expanded Details */}
                  {expandedProductId === product.id && (
                    <div className="border-t px-1.5 sm:px-4 md:px-6 py-2 sm:py-4 bg-gray-50 space-y-2 sm:space-y-3">
                      {/* Details Grid */}
                      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-3 text-[8px] sm:text-sm">
                        <div>
                          <p className="text-black font-semibold text-[7px] sm:text-xs">Seller</p>
                          <p className="text-black flex items-center gap-0.5 truncate mt-1 text-[7.5px] sm:text-xs">
                            <User className="w-3 h-3 flex-shrink-0" />
                            <span className="truncate">{product.seller.name}</span>
                          </p>
                        </div>
                        <div>
                          <p className="text-black font-semibold text-[7px] sm:text-xs">Email</p>
                          <p className="text-black text-[7.5px] sm:text-xs mt-1 truncate">{product.seller.email}</p>
                        </div>
                        <div>
                          <p className="text-black font-semibold text-[7px] sm:text-xs">Rejected Date</p>
                          <p className="text-black text-[7.5px] sm:text-xs mt-1">{formatDate(product.createdAt)}</p>
                        </div>
                        <div>
                          <p className="text-black font-semibold text-[7px] sm:text-xs">Status</p>
                          <p className="text-black text-[7.5px] sm:text-xs mt-1">{statusConfig.label}</p>
                        </div>
                      </div>

                      {/* Rejection Reason */}
                      {product.rejectionReason && (
                        <div className="p-0.5 sm:p-3 bg-red-50 rounded-lg border border-red-200">
                          <p className="text-[7.5px] sm:text-sm text-red-800 font-medium">
                            Rejection Reason:
                          </p>
                          <p className="text-[7.5px] sm:text-sm text-red-700 mt-1">{product.rejectionReason}</p>
                        </div>
                      )}

                      {/* Shipment Info */}
                      {product.shipment && (
                        <div className="p-0.5 sm:p-3 bg-blue-50 rounded-lg border border-blue-200">
                          <p className="text-[7.5px] sm:text-sm text-blue-800 font-medium">
                            Shipment Status
                          </p>
                          <div className="mt-2 space-y-1 text-[7.5px] sm:text-sm text-blue-700">
                            <p><strong>ID:</strong> {product.shipment.id.substring(0, 12)}...</p>
                            <p><strong>Status:</strong> {product.shipment.status}</p>
                            <p><strong>Created:</strong> {formatDate(product.shipment.createdAt)}</p>
                            {product.shipment.itemsExpected && (
                              <p><strong>Items Expected:</strong> {product.shipment.itemsExpected}</p>
                            )}
                            {product.shipment.itemsReceived !== undefined && (
                              <p><strong>Items Received:</strong> {product.shipment.itemsReceived}</p>
                            )}
                            {product.shipment.disputeNotes && (
                              <p><strong>Notes:</strong> {product.shipment.disputeNotes}</p>
                            )}
                          </div>
                        </div>
                      )}

                      {/* Status Flow Indicator */}
                      <div className="p-2 sm:p-3 bg-purple-50 rounded-lg border border-purple-200">
                        <p className="text-[7.5px] sm:text-sm text-purple-800 font-medium mb-2">
                          Return Flow
                        </p>
                        <div className="flex items-center gap-1 sm:gap-2 text-[7px] sm:text-xs">
                          <div className={`flex items-center justify-center w-5 h-5 sm:w-6 sm:h-6 rounded-full ${product.status === 'RETURN_IN_PROGRESS' || ['SELLER_RECEIVED', 'ADMIN_CONFIRMED', 'RETURNED_SUCCESSFUL'].includes(product.status) ? 'bg-purple-600 text-white' : 'bg-gray-200'}`}>
                            1
                          </div>
                          <span className="text-gray-400">ΓåÆ</span>
                          <div className={`flex items-center justify-center w-5 h-5 sm:w-6 sm:h-6 rounded-full ${['SELLER_RECEIVED', 'ADMIN_CONFIRMED', 'RETURNED_SUCCESSFUL'].includes(product.status) ? 'bg-purple-600 text-white' : 'bg-gray-200'}`}>
                            2
                          </div>
                          <span className="text-gray-400">ΓåÆ</span>
                          <div className={`flex items-center justify-center w-5 h-5 sm:w-6 sm:h-6 rounded-full ${['ADMIN_CONFIRMED', 'RETURNED_SUCCESSFUL'].includes(product.status) ? 'bg-purple-600 text-white' : 'bg-gray-200'}`}>
                            3
                          </div>
                          <span className="text-gray-400">ΓåÆ</span>
                          <div className={`flex items-center justify-center w-5 h-5 sm:w-6 sm:h-6 rounded-full ${product.status === 'RETURNED_SUCCESSFUL' ? 'bg-purple-600 text-white' : 'bg-gray-200'}`}>
                            4
                          </div>
                        </div>
                        <p className="text-[7px] sm:text-xs text-gray-600 mt-2">
                          1: In Progress ΓåÆ 2: Seller Received ΓåÆ 3: Verified ΓåÆ 4: Complete
                        </p>
                      </div>
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="flex items-center justify-between mt-6 sm:mt-8">
            <button
              onClick={() => setPage(Math.max(1, page - 1))}
              disabled={page === 1}
              className="flex items-center gap-1 px-3 sm:px-4 py-1.5 sm:py-2 border border-gray-200 rounded-lg text-[10px] sm:text-sm font-medium text-black hover:bg-gray-50 disabled:opacity-50"
            >
              <ChevronLeft className="w-4 h-4" />
              Previous
            </button>
            <span className="text-[10px] sm:text-sm text-black">
              Page {page} of {totalPages}
            </span>
            <button
              onClick={() => setPage(Math.min(totalPages, page + 1))}
              disabled={page === totalPages}
              className="flex items-center gap-1 px-3 sm:px-4 py-1.5 sm:py-2 border border-gray-200 rounded-lg text-[10px] sm:text-sm font-medium text-black hover:bg-gray-50 disabled:opacity-50"
            >
              Next
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { 
  _Package, 
  Search, 
  ChevronLeft, 
  ChevronRight,
  ChevronDown,
  AlertTriangle,
  Mail,
  User,
  Play,
} from 'lucide-react'
import toast from 'react-hot-toast'
import { ProductImage } from '@/components/ProductImage'

interface Seller {
  id: string
  name: string
  email: string
  boutique_returnAddress?: {
    name: string
    phone: string
    address: string
    city: string
    state: string
    country: string
    postalCode: string
  } | null
}

interface RejectedProduct {
  id: string
  title: string
  status: string
  thumbnailUrl: string | null
  basePrice: number
  rejectionReason: string | null
  createdAt: string
  description?: string
  originalStock: number | null
  currentStock: number | null
  totalRejectedQty?: number
  variants?: Array<{
    id: string
    quantity: number
    size?: string | null
    color?: string | null
  }>
  media?: Array<{
    id: string
    url: string
    type: string
    sortOrder: number
  }>
  seller: Seller
  shipment?: {
    id: string
    itemsMissing: number | null
    itemsDamaged: number | null
    disputeNotes: string | null
    status?: string
  }
  returnStatus?: 'none' | 'in_progress' | 'completed'
}

export default function RejectedProductsPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [products, setProducts] = useState<RejectedProduct[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [selectedProduct, setSelectedProduct] = useState<RejectedProduct | null>(null)
  const [showEmailModal, setShowEmailModal] = useState(false)
  const [selectedMediaUrl, setSelectedMediaUrl] = useState<string | null>(null)
  const [expandedProductId, setExpandedProductId] = useState<string | null>(null)
  const [emailLoading, setEmailLoading] = useState(false)
  const [returnDate, setReturnDate] = useState('')

  useEffect(() => {
    if (status === 'loading') return
    if (!session || (session.user as { role?: string }).role !== 'ADMIN') {
      router.push('/auth/signin')
      return
    }
    fetchRejectedProducts()
  }, [session, status, router, page, searchQuery])

  const fetchRejectedProducts = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        page: page.toString(),
        limit: '20',
      })
      if (searchQuery) params.append('search', searchQuery)

      const res = await fetch(`/api/boutique/admin/rejected?${params}`)
      if (res.ok) {
        const data = await res.json()
        setProducts(data.products || [])
        setTotalPages(data.pagination?.totalPages || data.totalPages || 1)
      } else {
        toast.error('Failed to load rejected products')
      }
    } catch (error) {
      console.error('Failed to fetch rejected products:', error)
      toast.error('Failed to load rejected products')
    } finally {
      setLoading(false)
    }
  }

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault()
    setPage(1)
    fetchRejectedProducts()
  }

  const sendReturnEmail = async () => {
    if (!selectedProduct) return
    if (!returnDate) {
      toast.error('Please select a return date')
      return
    }

    setEmailLoading(true)
    try {
      const res = await fetch(`/api/boutique/admin/rejected/send-email`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          productId: selectedProduct.id,
          sellerId: selectedProduct.seller.id,
          sellerEmail: selectedProduct.seller.email,
          returnDate,
          rejectionReason: selectedProduct.rejectionReason,
        }),
      })

      if (res.ok) {
        toast.success('Email sent to seller!')
        setShowEmailModal(false)
        setReturnDate('')
        fetchRejectedProducts()
      } else {
        const data = await res.json()
        toast.error(data.message || 'Failed to send email')
      }
    } catch (error) {
      console.error('Error sending email:', error)
      toast.error('Failed to send email')
    } finally {
      setEmailLoading(false)
    }
  }

  const handleReturnItem = async (product: RejectedProduct) => {
    try {
      const res = await fetch(`/api/boutique/admin/rejected/${product.id}/create-return`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      })

      const data = await res.json()

      if (res.ok) {
        toast.success('Return shipment created! Seller will be notified.')
        fetchRejectedProducts()
      } else if (res.status === 409) {
        // Conflict: Return shipment already exists
        toast.error(data.message || 'Return shipment already exists')
        // Update product status immediately to disable button
        setProducts(prevProducts =>
          prevProducts.map(p =>
            p.id === product.id
              ? { ...p, returnStatus: 'in_progress' }
              : p
          )
        )
      } else {
        toast.error(data.message || 'Failed to create return shipment')
      }
    } catch (error) {
      console.error('Error creating return:', error)
      toast.error('Failed to create return shipment')
    }
  }

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-NG', {
      style: 'currency',
      currency: 'NGN',
      minimumFractionDigits: 0,
    }).format(amount)
  }

  const formatDate = (date: string) => {
    return new Date(date).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    })
  }

  const getMinReturnDate = () => {
    const today = new Date()
    return today.toISOString().split('T')[0]
  }

  const getMaxReturnDate = () => {
    const today = new Date()
    today.setDate(today.getDate() + 7)
    return today.toISOString().split('T')[0]
  }

  if (status === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600"></div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 py-3 sm:py-8">
      <div className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="mb-3 sm:mb-8">
          <Link href="/admin/boutique" className="text-purple-600 hover:text-purple-700 flex items-center gap-1 mb-2 sm:mb-4 text-[10px] sm:text-sm">
            <ChevronLeft className="w-3 h-3 sm:w-4 sm:h-4" />
            Back to Admin
          </Link>
          <div className="flex items-center gap-2 sm:gap-3">
            <AlertTriangle className="w-5 h-5 sm:w-8 sm:h-8 text-red-600" />
            <div>
              <h1 className="text-lg sm:text-3xl font-bold text-black">Rejected Products</h1>
              <p className="text-[10px] sm:text-base text-black">
                {products.length} rejected products awaiting pickup
              </p>
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-xl shadow-sm p-2.5 sm:p-4 mb-3 sm:mb-6">
          <div className="flex flex-col gap-2 sm:gap-3">
            <form onSubmit={handleSearch} className="flex-1">
              <div className="relative">
                <Search className="absolute left-2.5 sm:left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 sm:w-5 sm:h-5 text-gray-400" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search by product title, seller name, or ID..."
                  className="w-full pl-7 sm:pl-10 pr-2.5 sm:pr-4 py-1.5 sm:py-2 border rounded-lg text-black bg-white focus:ring-2 focus:ring-red-500 text-[11px] sm:text-sm placeholder-gray-500"
                />
              </div>
            </form>
          </div>
        </div>

        {/* Products List */}
        {products.length === 0 ? (
          <div className="bg-white rounded-2xl shadow-sm p-6 sm:p-12 text-center">
            <AlertTriangle className="w-10 h-10 sm:w-16 sm:h-16 text-gray-300 mx-auto mb-2 sm:mb-4" />
            <h3 className="text-base sm:text-lg font-medium text-black mb-1 sm:mb-2">No Rejected Products</h3>
            <p className="text-[11px] sm:text-base text-black">
              {searchQuery ? 'Try adjusting your filters' : 'No products have been rejected'}
            </p>
          </div>
        ) : (
          <div className="space-y-1.5 sm:space-y-4">
            {products.map((product) => (
              <div
                key={product.id}
                className="bg-white rounded-lg shadow-sm overflow-hidden hover:shadow-md transition-shadow"
              >
                {/* Collapsible Header */}
                <button
                  onClick={() => {
                    if (expandedProductId === product.id) {
                      // Collapse and reset media
                      setExpandedProductId(null)
                      setSelectedMediaUrl(null)
                    } else {
                      // Expand and initialize first media
                      setExpandedProductId(product.id)
                      if (product.media && product.media.length > 0) {
                        setSelectedMediaUrl(product.media[0].url)
                      } else if (product.thumbnailUrl) {
                        setSelectedMediaUrl(product.thumbnailUrl)
                      }
                    }
                  }}
                  className="w-full p-1.5 sm:p-4 md:p-6 flex items-center justify-between hover:bg-gray-50 transition"
                >
                  <div className="flex items-center gap-1.5 sm:gap-4 flex-1 min-w-0">
                    {/* Product Image */}
                    <div className="w-12 h-12 sm:w-20 sm:h-20 rounded-lg overflow-hidden bg-gray-200 flex-shrink-0 flex items-center justify-center">
                      <ProductImage
                        src={product.thumbnailUrl}
                        alt={product.title}
                        containerClassName="w-full h-full rounded-lg overflow-hidden bg-gray-200 flex items-center justify-center"
                        className="w-full h-full object-cover"
                        fallbackClassName="w-7 h-7 sm:w-8 sm:h-8 text-gray-400"
                      />
                    </div>

                    {/* Product Summary */}
                    <div className="flex-1 min-w-0 text-left">
                      <div className="flex items-start justify-between gap-1 mb-0.5 sm:mb-1">
                        <h3 className="font-semibold text-black text-[10px] sm:text-base leading-tight truncate">
                          {product.title}
                        </h3>
                        <span className="inline-flex items-center gap-1 px-1.5 sm:px-2.5 py-0.5 sm:py-1 rounded-full text-[9px] sm:text-xs font-medium bg-red-100 text-red-700 flex-shrink-0">
                          <AlertTriangle className="w-2.5 h-2.5 sm:w-3 sm:h-3" />
                          Rejected
                        </span>
                      </div>
                      <p className="text-[9px] sm:text-sm text-black">
                        {formatCurrency(product.basePrice)} ΓÇó {product.seller.name}
                      </p>
                    </div>
                  </div>

                  {/* Expand/Collapse Chevron */}
                  <ChevronDown
                    className={`w-4 h-4 sm:w-5 sm:h-5 text-gray-400 flex-shrink-0 ml-2 transition-transform ${
                      expandedProductId === product.id ? 'rotate-180' : ''
                    }`}
                  />
                </button>

                {/* Expanded Details */}
                {expandedProductId === product.id && (
                  <div className="border-t px-1.5 sm:px-4 md:px-6 py-2 sm:py-4 bg-gray-50 space-y-2 sm:space-y-3">
                    {/* Media Gallery */}
                    {product.media && product.media.length > 0 && (
                      <div className="bg-white rounded-lg p-2 sm:p-3 border border-gray-200">
                        <p className="text-black font-semibold text-[7px] sm:text-xs mb-2">Product Media</p>
                        
                        {/* Main Display */}
                        <div className="mb-2 relative w-full aspect-square bg-gray-100 rounded-lg overflow-hidden">
                          {selectedMediaUrl ? (
                            product.media.find(m => m.url === selectedMediaUrl)?.type === 'VIDEO' ? (
                              <video
                                src={selectedMediaUrl}
                                controls
                                className="w-full h-full object-cover"
                              />
                            ) : (
                              <img
                                src={selectedMediaUrl}
                                alt="Product"
                                className="w-full h-full object-cover"
                              />
                            )
                          ) : product.thumbnailUrl ? (
                            <img
                              src={product.thumbnailUrl}
                              alt="Product"
                              className="w-full h-full object-cover"
                            />
                          ) : (
                            <div className="w-full h-full flex items-center justify-center text-gray-400">
                              No image
                            </div>
                          )}
                        </div>

                        {/* Thumbnails */}
                        {product.media.length > 1 && (
                          <div className="grid grid-cols-4 sm:grid-cols-5 gap-1">
                            {product.media.map((media) => (
                              <button
                                key={media.id}
                                onClick={() => setSelectedMediaUrl(media.url)}
                                className={`relative aspect-square rounded border-2 overflow-hidden transition ${
                                  selectedMediaUrl === media.url
                                    ? 'border-blue-500'
                                    : 'border-gray-300 hover:border-gray-400'
                                }`}
                              >
                                <img
                                  src={media.url}
                                  alt="Thumbnail"
                                  className="w-full h-full object-cover"
                                />
                                {media.type === 'VIDEO' && (
                                  <div className="absolute inset-0 flex items-center justify-center bg-black/30">
                                    <Play className="w-3 h-3 text-white" />
                                  </div>
                                )}
                              </button>
                            ))}
                          </div>
                        )}
                      </div>
                    )}

                    {/* Description */}
                    {product.description && (
                      <div className="p-0.5 sm:p-3 bg-white rounded-lg border border-gray-200">
                        <p className="text-[7.5px] sm:text-sm text-gray-800 font-medium mb-1">Description</p>
                        <p className="text-[7.5px] sm:text-sm text-gray-700 line-clamp-3">{product.description}</p>
                      </div>
                    )}

                    {/* Details Grid */}
                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-3 text-[8px] sm:text-sm">
                      <div>
                        <p className="text-black font-semibold text-[7px] sm:text-xs">Rejected Qty</p>
                        <p className="text-black text-[7.5px] sm:text-xs mt-1 font-medium text-red-600">
                          {product.totalRejectedQty || 0} units
                        </p>
                      </div>
                      <div>
                        <p className="text-black font-semibold text-[7px] sm:text-xs">Seller</p>
                        <p className="text-black flex items-center gap-0.5 truncate mt-1 text-[7.5px] sm:text-xs">
                          <User className="w-3 h-3 flex-shrink-0" />
                          <span className="truncate">{product.seller.name}</span>
                        </p>
                      </div>
                      <div>
                        <p className="text-black font-semibold text-[7px] sm:text-xs">Email</p>
                        <p className="text-black text-[7.5px] sm:text-xs mt-1 truncate">{product.seller.email}</p>
                      </div>
                      <div>
                        <p className="text-black font-semibold text-[7px] sm:text-xs">Rejected Date</p>
                        <p className="text-black text-[7.5px] sm:text-xs mt-1">{formatDate(product.createdAt)}</p>
                      </div>
                    </div>

                    {/* Rejection Reason */}
                    {product.rejectionReason && (
                      <div className="p-0.5 sm:p-3 bg-red-50 rounded-lg border border-red-200">
                        <p className="text-[7.5px] sm:text-sm text-red-800 font-medium">
                          Rejection Reason:
                        </p>
                        <p className="text-[7.5px] sm:text-sm text-red-700 mt-1">{product.rejectionReason}</p>
                      </div>
                    )}

                    {/* Return Address */}
                    {false && product.seller.boutique_returnAddress ? (
                      <div className="p-0.5 sm:p-3 bg-blue-50 rounded-lg border border-blue-200">
                        <p className="text-[7.5px] sm:text-sm text-blue-800 font-medium">
                          Return Address (Seller):
                        </p>
                        <p className="text-[7.5px] sm:text-sm text-blue-700 mt-1">
                          {product.seller.boutique_returnAddress?.name}<br />
                          {product.seller.boutique_returnAddress?.address}<br />
                          {product.seller.boutique_returnAddress?.city}, {product.seller.boutique_returnAddress?.state} {product.seller.boutique_returnAddress?.postalCode}<br />
                          {product.seller.boutique_returnAddress?.country}<br />
                          Phone: {product.seller.boutique_returnAddress?.phone}
                        </p>
                      </div>
                    ) : (
                      <div className="p-0.5 sm:p-3 bg-yellow-50 rounded-lg border border-yellow-200">
                        <p className="text-[7.5px] sm:text-sm text-yellow-800 font-medium">
                          ΓÜá∩╕Å Return Address Feature
                        </p>
                        <p className="text-[7.5px] sm:text-sm text-yellow-700 mt-1">
                          Return address system requires database migration. Run: npx prisma db push
                        </p>
                      </div>
                    )}

                    {/* Discrepancy Info */}
                    {product.shipment && (product.shipment.itemsMissing || product.shipment.itemsDamaged) && (
                      <div className="p-0.5 sm:p-3 bg-orange-50 rounded-lg border border-orange-200">
                        <p className="text-[7.5px] sm:text-sm text-orange-800 font-medium">
                          Discrepancies Reported:
                        </p>
                        <p className="text-[7.5px] sm:text-sm text-orange-700 mt-1">
                          Missing: {product.shipment.itemsMissing || 0}, 
                          Damaged: {product.shipment.itemsDamaged || 0}
                        </p>
                      </div>
                    )}

                    {/* Actions */}
                    <div className="flex gap-1 sm:gap-2 flex-wrap pt-2 sm:pt-3 border-t border-gray-200">
                      {/* Send Email Button */}
                      <button
                        onClick={() => {
                          setSelectedProduct(product)
                          setShowEmailModal(true)
                        }}
                        className="flex items-center gap-1 sm:gap-2 bg-blue-600 text-white px-2 sm:px-4 py-0.5 sm:py-1.5 rounded-lg text-[8px] sm:text-sm font-medium hover:bg-blue-700 transition"
                      >
                        <Mail className="w-3 h-3" />
                        <span>Send Email</span>
                      </button>

                      {/* Return Item Button */}
                      <button
                        onClick={() => handleReturnItem(product)}
                        disabled={product.returnStatus !== 'none'}
                        title={
                          product.returnStatus === 'in_progress'
                            ? 'Return already in progress'
                            : product.returnStatus === 'completed'
                            ? 'Return completed'
                            : 'Create return shipment'
                        }
                        className={`flex items-center gap-1 sm:gap-2 px-2 sm:px-4 py-0.5 sm:py-1.5 rounded-lg text-[8px] sm:text-sm font-medium transition ${
                          product.returnStatus === 'completed'
                            ? 'bg-gray-400 text-white cursor-not-allowed'
                            : product.returnStatus === 'in_progress'
                            ? 'bg-yellow-500 text-white cursor-not-allowed'
                            : 'bg-green-600 text-white hover:bg-green-700'
                        }`}
                      >
                        <span>
                          {product.returnStatus === 'completed'
                            ? 'Return Complete'
                            : product.returnStatus === 'in_progress'
                            ? 'Return Already in Progress'
                            : 'Return Item'}
                        </span>
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="flex items-center justify-between mt-6 sm:mt-8">
            <button
              onClick={() => setPage(Math.max(1, page - 1))}
              disabled={page === 1}
              className="flex items-center gap-1 px-3 sm:px-4 py-1.5 sm:py-2 border border-gray-200 rounded-lg text-[10px] sm:text-sm font-medium text-black hover:bg-gray-50 disabled:opacity-50"
            >
              <ChevronLeft className="w-4 h-4" />
              Previous
            </button>
            <span className="text-[10px] sm:text-sm text-black">
              Page {page} of {totalPages}
            </span>
            <button
              onClick={() => setPage(Math.min(totalPages, page + 1))}
              disabled={page === totalPages}
              className="flex items-center gap-1 px-3 sm:px-4 py-1.5 sm:py-2 border border-gray-200 rounded-lg text-[10px] sm:text-sm font-medium text-black hover:bg-gray-50 disabled:opacity-50"
            >
              Next
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        )}
      </div>

      {/* Email Modal */}
      {showEmailModal && selectedProduct && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-3 sm:p-4">
          <div className="bg-white rounded-xl shadow-lg max-w-sm w-full p-4 sm:p-6">
            <div className="flex items-start gap-3 sm:gap-4 mb-4 sm:mb-6">
              <Mail className="w-6 h-6 sm:w-8 sm:h-8 text-red-600 flex-shrink-0 mt-1" />
              <div>
                <h3 className="text-base sm:text-lg font-bold text-black">Send Return Email</h3>
                <p className="text-[10px] sm:text-sm text-black mt-1">
                  Notify {selectedProduct.seller.name} about the return and schedule a pickup date
                </p>
              </div>
            </div>

            <div className="mb-4 sm:mb-6">
              <label className="block text-[10px] sm:text-sm font-medium text-black mb-2">
                Pickup Date (within 7 days)
              </label>
              <input
                type="date"
                value={returnDate}
                onChange={(e) => setReturnDate(e.target.value)}
                min={getMinReturnDate()}
                max={getMaxReturnDate()}
                aria-label="Pickup Date"
                className="w-full px-3 sm:px-4 py-2 border border-gray-200 rounded-lg text-black text-[10px] sm:text-sm focus:ring-2 focus:ring-red-500"
              />
              <p className="text-[9px] sm:text-xs text-gray-500 mt-1">
                Seller must pick up within 7 days from today
              </p>
            </div>

            <div className="flex gap-2 sm:gap-3">
              <button
                onClick={sendReturnEmail}
                disabled={emailLoading || !returnDate}
                className="flex-1 bg-red-600 text-white px-3 sm:px-4 py-2 sm:py-2.5 rounded-lg text-[10px] sm:text-sm font-medium hover:bg-red-700 disabled:opacity-50"
              >
                Send Email
              </button>
              <button
                onClick={() => {
                  setShowEmailModal(false)
                  setReturnDate('')
                }}
                className="flex-1 border border-gray-200 text-black px-3 sm:px-4 py-2 sm:py-2.5 rounded-lg text-[10px] sm:text-sm font-medium hover:bg-gray-50"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import Image from 'next/image'
import { 
  RotateCcw, ChevronLeft, Search, Filter, Eye, CheckCircle, 
  XCircle, Clock, Package, RefreshCw
} from 'lucide-react'
import toast from 'react-hot-toast'

interface ReturnRequest {
  id: string
  returnNumber: string
  reason: string
  description: string | null
  status: string
  refundAmount: number
  adminNotes: string | null
  imageUrls: string[]
  createdAt: string
  resolvedAt: string | null
  order: {
    id: string
    orderNumber: string
    total: number
  }
  orderItem: {
    id: string
    quantity: number
    price: number
    product: {
      id: string
      title: string
      thumbnailUrl: string | null
    }
  }
  user: {
    id: string
    name: string | null
    email: string
  }
}

const RETURN_STATUSES = [
  { value: '', label: 'All Statuses' },
  { value: 'PENDING', label: 'Pending Review' },
  { value: 'APPROVED', label: 'Approved' },
  { value: 'REJECTED', label: 'Rejected' },
  { value: 'ITEM_SHIPPED', label: 'Item Shipped' },
  { value: 'ITEM_RECEIVED', label: 'Item Received' },
  { value: 'REFUNDED', label: 'Refunded' },
]

function getStatusBadge(status: string) {
  switch (status) {
    case 'PENDING':
      return { bg: 'bg-yellow-100 text-yellow-800', icon: Clock }
    case 'APPROVED':
      return { bg: 'bg-blue-100 text-blue-800', icon: CheckCircle }
    case 'REJECTED':
      return { bg: 'bg-red-100 text-red-800', icon: XCircle }
    case 'ITEM_SHIPPED':
      return { bg: 'bg-indigo-100 text-indigo-800', icon: Package }
    case 'ITEM_RECEIVED':
      return { bg: 'bg-purple-100 text-purple-800', icon: Package }
    case 'REFUNDED':
      return { bg: 'bg-green-100 text-green-800', icon: CheckCircle }
    default:
      return { bg: 'bg-gray-100 text-gray-800', icon: Clock }
  }
}

export default function AdminReturnsPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [returns, setReturns] = useState<ReturnRequest[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [statusFilter, setStatusFilter] = useState('')
  const [selectedReturn, setSelectedReturn] = useState<ReturnRequest | null>(null)
  const [processing, setProcessing] = useState(false)
  const [adminNotes, setAdminNotes] = useState('')

  useEffect(() => {
    if (status === 'loading') return
    if (!session || (session.user as any).role !== 'ADMIN') {
      router.push('/auth/signin')
      return
    }
    fetchReturns()
  }, [session, status, statusFilter])

  const fetchReturns = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams()
      if (statusFilter) params.append('status', statusFilter)
      if (searchQuery) params.append('search', searchQuery)

      const res = await fetch(`/api/boutique/returns?admin=true&${params}`)
      if (res.ok) {
        const data = await res.json()
        setReturns(data.returns || [])
      }
    } catch (error) {
      console.error('Failed to fetch returns:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleAction = async (returnId: string, action: string, notes?: string) => {
    setProcessing(true)
    try {
      const res = await fetch('/api/boutique/returns', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          returnId, 
          action,
          adminNotes: notes || adminNotes 
        }),
      })

      if (res.ok) {
        toast.success(`Return ${action}d successfully`)
        fetchReturns()
        setSelectedReturn(null)
        setAdminNotes('')
      } else {
        const data = await res.json()
        toast.error(data.message || 'Failed to update return')
      }
    } catch (_error) {
      toast.error('Failed to update return')
    } finally {
      setProcessing(false)
    }
  }

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-NG', {
      style: 'currency',
      currency: 'NGN',
      minimumFractionDigits: 0,
    }).format(amount)
  }

  const formatDate = (date: string) => {
    return new Date(date).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    })
  }

  if (status === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600"></div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 py-2 sm:py-8">
      <div className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="mb-2 sm:mb-8">
          <Link href="/admin/boutique" className="text-purple-600 hover:text-purple-700 flex items-center gap-1 mb-2 sm:mb-3 text-[10px] sm:text-sm">
            <ChevronLeft className="w-3 h-3 sm:w-4 sm:h-4" />
            Back to Boutique Admin
          </Link>
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-lg sm:text-3xl font-bold text-black">Return Requests</h1>
              <p className="text-[9px] sm:text-sm text-black mt-0.5 sm:mt-1">Manage buyer return requests</p>
            </div>
            <button
              onClick={() => fetchReturns()}
              className="p-1.5 sm:p-2 hover:bg-gray-100 rounded-lg"
              aria-label="Refresh returns list"
            >
              <RefreshCw className="w-4 h-4 sm:w-5 sm:h-5 text-black" />
            </button>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 mb-2 sm:mb-6">
          <div className="flex flex-col sm:flex-row gap-2 sm:gap-4">
            <form onSubmit={(e) => { e.preventDefault(); fetchReturns(); }} className="flex-1">
              <div className="relative">
                <Search className="absolute left-2 sm:left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 sm:w-5 sm:h-5 text-gray-400" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search by return or order..."
                  className="w-full pl-7 sm:pl-10 pr-2.5 sm:pr-4 py-1.5 sm:py-2 border rounded-lg text-black bg-white focus:ring-2 focus:ring-purple-500 text-[11px] sm:text-sm"
                />
              </div>
            </form>
            <div className="flex items-center gap-1.5 sm:gap-2">
              <Filter className="w-3.5 h-3.5 sm:w-5 sm:h-5 text-gray-400" />
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="border rounded-lg px-2 sm:px-3 py-1.5 sm:py-2 text-black bg-white focus:ring-2 focus:ring-purple-500 text-[11px] sm:text-sm"
                aria-label="Filter by return status"
              >
                {RETURN_STATUSES.map(s => (
                  <option key={s.value} value={s.value} className="text-black">{s.label}</option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {/* Returns List */}
        <div className="bg-white rounded-lg shadow-sm overflow-hidden">
          {returns.length === 0 ? (
            <div className="p-6 sm:p-12 text-center">
              <RotateCcw className="w-10 h-10 sm:w-16 sm:h-16 text-gray-300 mx-auto mb-2 sm:mb-4" />
              <h3 className="text-base sm:text-lg font-medium text-black mb-1 sm:mb-2">No return requests</h3>
              <p className="text-[9px] sm:text-sm text-black">
                {statusFilter ? 'Try adjusting your filters' : 'Return requests will appear here'}
              </p>
            </div>
          ) : (
            <div className="divide-y divide-gray-200">
              {returns.map((ret) => {
                const statusInfo = getStatusBadge(ret.status)
                const StatusIcon = statusInfo.icon
                return (
                  <div key={ret.id} className="p-2 sm:p-4 hover:bg-gray-50">
                    <div className="flex items-start gap-2 sm:gap-4">
                      {/* Product Image */}
                      <div className="w-10 h-10 sm:w-16 sm:h-16 rounded-lg overflow-hidden bg-gray-100 shrink-0">
                        {ret.orderItem?.product?.thumbnailUrl ? (
                          <Image
                            src={ret.orderItem?.product?.thumbnailUrl || ''}
                            alt={ret.orderItem?.product?.title || 'Product'}
                            width={64}
                            height={64}
                            className="object-cover w-full h-full"
                          />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center">
                            <Package className="w-5 h-5 sm:w-8 sm:h-8 text-gray-300" />
                          </div>
                        )}
                      </div>

                      {/* Details */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center justify-between gap-2 mb-0.5 sm:mb-1">
                          <div>
                            <p className="font-semibold text-black text-[10px] sm:text-base">{ret.returnNumber}</p>
                            <p className="text-[8px] sm:text-sm text-black">Order: {ret.order?.orderNumber || 'N/A'}</p>
                          </div>
                          <span className={`inline-flex items-center gap-0.5 px-1.5 sm:px-2 py-0.5 sm:py-1 rounded-full text-[7px] sm:text-xs font-medium ${statusInfo.bg}`}>
                            <StatusIcon className="w-2.5 h-2.5 sm:w-3 sm:h-3" />
                            <span className="hidden xs:inline">{ret.status.replace(/_/g, ' ')}</span>
                          </span>
                        </div>
                        <p className="text-[9px] sm:text-sm text-black font-medium line-clamp-1">{ret.orderItem?.product?.title || 'Product'}</p>
                        <p className="text-[8px] sm:text-sm text-black">
                          {ret.user?.name || ret.user?.email || 'Unknown'} ΓÇó Qty: {ret.orderItem?.quantity || 0}
                        </p>
                        <p className="text-[8px] sm:text-sm text-black">
                          Reason: <span className="font-medium">{ret.reason?.replace(/_/g, ' ')}</span>
                        </p>
                        {ret.description && (
                          <p className="text-[8px] sm:text-sm text-black mt-0.5">&ldquo;{ret.description}&rdquo;</p>
                        )}
                        <div className="flex items-center justify-between mt-1 sm:mt-2">
                          <p className="text-[8px] sm:text-sm font-semibold text-purple-600">
                            Refund: {formatCurrency(ret.refundAmount)}
                          </p>
                          <p className="text-[7px] sm:text-xs text-black">{formatDate(ret.createdAt)}</p>
                        </div>
                      </div>

                      {/* Actions */}
                      <div className="flex flex-col gap-1 sm:gap-2">
                        <button
                          onClick={() => setSelectedReturn(ret)}
                          className="p-1 sm:p-2 text-black hover:text-purple-600 hover:bg-purple-50 rounded-lg"
                          aria-label="View return details"
                        >
                          <Eye className="w-4 h-4 sm:w-5 sm:h-5" />
                        </button>
                        {ret.status === 'PENDING' && (
                          <>
                            <button
                              onClick={() => handleAction(ret.id, 'approve')}
                              disabled={processing}
                              className="p-1 sm:p-2 text-green-600 hover:bg-green-50 rounded-lg"
                              title="Approve"
                            >
                              <CheckCircle className="w-4 h-4 sm:w-5 sm:h-5" />
                            </button>
                            <button
                              onClick={() => setSelectedReturn(ret)}
                              className="p-1 sm:p-2 text-red-600 hover:bg-red-50 rounded-lg"
                              title="Reject"
                            >
                              <XCircle className="w-4 h-4 sm:w-5 sm:h-5" />
                            </button>
                          </>
                        )}
                      </div>
                    </div>
                  </div>
                )
              })}
            </div>
          )}
        </div>

        {/* Return Detail Modal */}
        {selectedReturn && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto">
              <div className="p-6">
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-xl font-bold text-gray-900">Return Details</h2>
                  <button
                    onClick={() => setSelectedReturn(null)}
                    className="p-2 hover:bg-gray-100 rounded-lg"
                    aria-label="Close modal"
                  >
                    <XCircle className="w-5 h-5" />
                  </button>
                </div>

                <div className="space-y-4">
                  <div className="grid grid-cols-2 gap-4 text-sm">
                    <div>
                      <p className="text-gray-500">Return Number</p>
                      <p className="font-medium text-gray-900">{selectedReturn.returnNumber}</p>
                    </div>
                    <div>
                      <p className="text-gray-500">Order Number</p>
                      <Link href={`/admin/boutique/orders/${selectedReturn.order?.id || ''}`} className="font-medium text-purple-600 hover:underline">
                        {selectedReturn.order?.orderNumber || 'N/A'}
                      </Link>
                    </div>
                    <div>
                      <p className="text-gray-500">Buyer</p>
                      <p className="font-medium text-gray-900">{selectedReturn.user?.name || selectedReturn.user?.email || 'Unknown'}</p>
                    </div>
                    <div>
                      <p className="text-gray-500">Refund Amount</p>
                      <p className="font-medium text-gray-900">{formatCurrency(selectedReturn.refundAmount)}</p>
                    </div>
                    <div>
                      <p className="text-gray-500">Reason</p>
                      <p className="font-medium text-gray-900">{selectedReturn.reason?.replace(/_/g, ' ') || 'Unknown'}</p>
                    </div>
                    <div>
                      <p className="text-gray-500">Status</p>
                      <p className="font-medium text-gray-900">{selectedReturn.status?.replace(/_/g, ' ') || 'Unknown'}</p>
                    </div>
                  </div>

                  {selectedReturn.description && (
                    <div>
                      <p className="text-gray-500 text-sm">Description</p>
                      <p className="text-gray-900 mt-1">{selectedReturn.description}</p>
                    </div>
                  )}

                  {selectedReturn.imageUrls.length > 0 && (
                    <div>
                      <p className="text-gray-500 text-sm mb-2">Evidence Images</p>
                      <div className="flex gap-2 flex-wrap">
                        {selectedReturn.imageUrls.map((url, idx) => (
                          <a 
                            key={idx} 
                            href={url} 
                            target="_blank" 
                            rel="noopener noreferrer"
                            aria-label={`View evidence image ${idx + 1}`}
                          >
                            <Image
                              src={url}
                              alt={`Evidence ${idx + 1}`}
                              width={100}
                              height={100}
                              className="rounded-lg object-cover"
                            />
                          </a>
                        ))}
                      </div>
                    </div>
                  )}

                  {selectedReturn.adminNotes && (
                    <div className="bg-gray-50 p-3 rounded-lg">
                      <p className="text-gray-500 text-sm">Admin Notes</p>
                      <p className="text-gray-900 mt-1">{selectedReturn.adminNotes}</p>
                    </div>
                  )}

                  {/* Action Buttons */}
                  {selectedReturn.status === 'PENDING' && (
                    <div className="border-t pt-4 mt-4">
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        Admin Notes (required for rejection)
                      </label>
                      <textarea
                        value={adminNotes}
                        onChange={(e) => setAdminNotes(e.target.value)}
                        rows={3}
                        className="w-full border rounded-lg px-3 py-2 text-gray-900"
                        placeholder="Enter notes..."
                      />
                      <div className="flex gap-3 mt-4">
                        <button
                          onClick={() => handleAction(selectedReturn.id, 'approve')}
                          disabled={processing}
                          className="flex-1 bg-green-600 text-white py-2 rounded-lg hover:bg-green-700 disabled:opacity-50"
                        >
                          Approve Return
                        </button>
                        <button
                          onClick={() => {
                            if (!adminNotes.trim()) {
                              toast.error('Please enter a rejection reason')
                              return
                            }
                            handleAction(selectedReturn.id, 'reject', adminNotes)
                          }}
                          disabled={processing}
                          className="flex-1 bg-red-600 text-white py-2 rounded-lg hover:bg-red-700 disabled:opacity-50"
                        >
                          Reject Return
                        </button>
                      </div>
                    </div>
                  )}

                  {selectedReturn.status === 'ITEM_RECEIVED' && (
                    <div className="border-t pt-4 mt-4">
                      <button
                        onClick={() => handleAction(selectedReturn.id, 'complete_refund')}
                        disabled={processing}
                        className="w-full bg-purple-600 text-white py-2 rounded-lg hover:bg-purple-700 disabled:opacity-50"
                      >
                        Complete Refund ({formatCurrency(selectedReturn.refundAmount)})
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useParams } from 'next/navigation'
import Link from 'next/link'
import {
  ChevronLeft,
  Package,
  _Truck,
  User,
  Calendar,
  AlertTriangle,
  CheckCircle,
  _ImageIcon,
  _Trash2,
  XCircle,
} from 'lucide-react'
import toast from 'react-hot-toast'

interface Product {
  id: string
  title: string
  thumbnailUrl: string | null
  basePrice: number
  variants?: Array<{
    id: string
    size: string | null
    color: string | null
    colorHex: string | null
    quantity: number
    priceAdjustment: number
    sku: string | null
  }>
}

interface VariantDiscrepancy {
  id: string
  shipmentId: string
  variantId: string
  quantityExpected: number
  quantityReceived: number | null
  quantityDamaged: number | null
  quantityMissing: number | null
  condition: string | null
  notes: string | null
  acceptanceStatus: string
  unitsAccepted: number | null
  unitsReturning: number | null
  createdAt: string
  updatedAt: string
  variant: {
    id: string
    size: string | null
    color: string | null
    colorHex: string | null
    quantity: number
    priceAdjustment: number
    sku: string | null
    product: {
      id: string
      title: string
      thumbnailUrl: string | null
    }
  }
}

interface Shipment {
  id: string
  status: string
  carrier: string
  trackingNumber: string
  estimatedArrival: string | null
  shippedAt: string | null
  receiptVerifiedAt: string | null
  createdAt: string
  notes: string | null
  itemsExpected: number
  itemsReceived: number | null
  itemsMissing: number | null
  itemsDamaged: number | null
  hasDiscrepancy: boolean
  disputeStatus: string | null
  disputeNotes: string | null
  receiptPhotos: string[]
  productIds: string[]
  seller: {
    id: string
    name: string
    email: string
  }
  products?: Product[]
  product?: Product
  variantDiscrepancies?: VariantDiscrepancy[]
}

function formatCurrency(price: number) {
  return new Intl.NumberFormat('en-NG', {
    style: 'currency',
    currency: 'NGN',
  }).format(price)
}

function formatDate(date: string) {
  return new Date(date).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  })
}

export default function ShipmentDetailPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const params = useParams()
  const shipmentId = params.id as string

  const [shipment, setShipment] = useState<Shipment | null>(null)
  const [loading, setLoading] = useState(true)
  const [actionLoading, setActionLoading] = useState(false)
  const [showDiscrepancyModal, setShowDiscrepancyModal] = useState(false)
  const [discrepancyType, setDiscrepancyType] = useState<'damaged' | 'incomplete' | 'wrong'>('damaged')
  const [discrepancyForm, setDiscrepancyForm] = useState({
    itemsReceived: 0,
    itemsDamaged: 0,
    damagedItemName: '',
    damagedItemLocation: '',
    damagedItemNotes: '',
    damagedItems: [] as Array<{ name: string; location: string; notes: string }>,
    photos: [] as string[],
    video: '',
    otherNotes: '',
  })
  
  // Confirmation modals
  const [showApproveConfirm, setShowApproveConfirm] = useState(false)
  const [showRejectConfirm, setShowRejectConfirm] = useState(false)
  const [rejectReason, setRejectReason] = useState('')

  // Variant discrepancy decision states
  const [variantDecisions, setVariantDecisions] = useState<Record<string, {
    status: 'ACCEPTED' | 'RETURNING' | 'PARTIAL' | null
    unitsAccepted?: number
    unitsReturning?: number
    notes?: string
    rejectionCategory?: string
    loading?: boolean
  }>>({})
  const [showPartialModal, setShowPartialModal] = useState<string | null>(null)
  const [partialForm, setPartialForm] = useState({ unitsAccepted: 0, unitsReturning: 0, notes: '', rejectionCategory: '' })

  useEffect(() => {
    if (status === 'loading') return
    if (!session || (session.user as any).role !== 'ADMIN') {
      router.push('/auth/signin')
      return
    }
    fetchShipment()
  }, [session, status, shipmentId])

  const fetchShipment = async () => {
    setLoading(true)
    try {
      const res = await fetch(`/api/boutique/admin/shipments/${shipmentId}`, {
        cache: 'no-store',
      })
      if (res.ok) {
        const data = await res.json()
        console.log('Fetched shipment:', data.shipment)
        setShipment(data.shipment)
      } else {
        toast.error('Failed to load shipment')
        router.back()
      }
    } catch (error) {
      console.error('Error fetching shipment:', error)
      toast.error('Error loading shipment')
    } finally {
      setLoading(false)
    }
  }

  const handleAction = async (action: string, data: any = {}) => {
    setActionLoading(true)
    try {
      const res = await fetch(`/api/boutique/admin/shipments/${shipmentId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action, ...data }),
      })

      const result = await res.json()
      if (res.ok) {
        toast.success(result.message || 'Action completed')
        fetchShipment()
      } else {
        toast.error(result.message || 'Action failed')
      }
    } catch (error) {
      console.error('Error:', error)
      toast.error('An error occurred')
    } finally {
      setActionLoading(false)
    }
  }

  const handleVariantDecision = async (variantId: string, acceptanceStatus: 'ACCEPTED' | 'RETURNING' | 'PARTIAL') => {
    const decision = variantDecisions[variantId]
    if (!decision) return

    setVariantDecisions(prev => ({
      ...prev,
      [variantId]: { ...decision, loading: true }
    }))

    try {
      const payload: any = { 
        acceptanceStatus,
        notes: decision.notes || undefined,
        rejectionCategory: decision.rejectionCategory || undefined
      }
      
      if (acceptanceStatus === 'PARTIAL') {
        if (!decision.unitsAccepted || !decision.unitsReturning) {
          toast.error('Please specify accepted and returning units')
          setVariantDecisions(prev => ({
            ...prev,
            [variantId]: { ...decision, loading: false }
          }))
          return
        }
        payload.unitsAccepted = decision.unitsAccepted
        payload.unitsReturning = decision.unitsReturning
      }

      const res = await fetch(`/api/boutique/admin/shipments/${shipmentId}/variant-discrepancies/${variantId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      const result = await res.json()
      if (res.ok) {
        toast.success(`Variant marked as ${acceptanceStatus}`)
        setVariantDecisions(prev => ({
          ...prev,
          [variantId]: { status: null, loading: false }
        }))
        setShowPartialModal(null)
        fetchShipment()
      } else {
        toast.error(result.message || 'Failed to update variant')
        setVariantDecisions(prev => ({
          ...prev,
          [variantId]: { ...decision, loading: false }
        }))
      }
    } catch (error) {
      console.error('Error:', error)
      toast.error('An error occurred')
      setVariantDecisions(prev => ({
        ...prev,
        [variantId]: { ...decision, loading: false }
      }))
    }
  }


  if (status === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600"></div>
      </div>
    )
  }

  if (!shipment) {
    return (
      <div className="min-h-screen bg-gray-50">
        <div className="max-w-4xl mx-auto px-3 sm:px-6 py-6 sm:py-8">
          <Link href="/admin/boutique/shipments" className="text-purple-600 hover:text-purple-700 flex items-center gap-1 text-[10px] sm:text-sm mb-4">
            <ChevronLeft className="w-3 h-3 sm:w-4 sm:h-4" />
            Back to Shipments
          </Link>
          <div className="bg-white rounded-lg shadow p-6 sm:p-8 text-center">
            <h2 className="text-lg sm:text-2xl font-bold text-black mb-2">Shipment Not Found</h2>
            <p className="text-[10px] sm:text-base text-black">The shipment you're looking for doesn't exist.</p>
          </div>
        </div>
      </div>
    )
  }

  const products = shipment.products || (shipment.product ? [shipment.product] : [])

  return (
    <div className="min-h-screen bg-gray-50 py-3 sm:py-8">
      <div className="max-w-4xl mx-auto px-3 sm:px-6">
        {/* Header */}
        <Link href="/admin/boutique/shipments" className="text-purple-600 hover:text-purple-700 flex items-center gap-1 mb-3 sm:mb-4 text-[10px] sm:text-sm">
          <ChevronLeft className="w-3 h-3 sm:w-4 sm:h-4" />
          Back to Shipments
        </Link>

        <div className="bg-white rounded-xl shadow-sm p-3 sm:p-6 mb-4 sm:mb-6">
          <div className="flex items-start justify-between gap-2 sm:gap-4 mb-4 sm:mb-6 pb-4 sm:pb-6 border-b">
            <div>
              <h1 className="text-lg sm:text-2xl font-bold text-black">Shipment Details</h1>
              <p className="text-[10px] sm:text-sm text-black mt-1">ID: {shipmentId}</p>
            </div>
            <span className={`px-2 sm:px-3 py-1 sm:py-2 rounded-full text-[9px] sm:text-xs font-medium ${
              shipment.status === 'RECEIVED' ? 'bg-green-100 text-green-800' :
              shipment.status === 'DISCREPANCY' ? 'bg-orange-100 text-orange-800' :
              'bg-blue-100 text-blue-800'
            }`}>
              {shipment.status}
            </span>
          </div>

          {/* Seller Info */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 mb-4 sm:mb-6 pb-4 sm:pb-6 border-b">
            <div>
              <p className="text-[10px] sm:text-sm text-black font-medium mb-0.5 sm:mb-1">Seller</p>
              <p className="text-[11px] sm:text-base text-black flex items-center gap-1">
                <User className="w-3 h-3 sm:w-4 sm:h-4" />
                {shipment.seller.name}
              </p>
              <p className="text-[10px] sm:text-sm text-black mt-0.5">{shipment.seller.email}</p>
            </div>
            <div>
              <p className="text-[10px] sm:text-sm text-black font-medium mb-0.5 sm:mb-1">Shipped Date</p>
              <p className="text-[11px] sm:text-base text-black flex items-center gap-1">
                <Calendar className="w-3 h-3 sm:w-4 sm:h-4" />
                {shipment.shippedAt ? formatDate(shipment.shippedAt) : 'N/A'}
              </p>
            </div>
          </div>

          {/* Shipping Info */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 mb-4 sm:mb-6 pb-4 sm:pb-6 border-b">
            <div>
              <p className="text-[10px] sm:text-sm text-black font-medium mb-0.5 sm:mb-1">Courier</p>
              <p className="text-[11px] sm:text-base text-black">{shipment.carrier}</p>
            </div>
            <div>
              <p className="text-[10px] sm:text-sm text-black font-medium mb-0.5 sm:mb-1">Tracking Number</p>
              <p className="text-[11px] sm:text-base font-mono text-black">{shipment.trackingNumber}</p>
            </div>
            <div>
              <p className="text-[10px] sm:text-sm text-black font-medium mb-0.5 sm:mb-1">Estimated Arrival</p>
              <p className="text-[11px] sm:text-base text-black">
                {shipment.shippedAt ? formatDate(new Date(new Date(shipment.shippedAt).getTime() + 7 * 24 * 60 * 60 * 1000).toISOString()) : 'N/A'}
              </p>
            </div>
            <div>
              <p className="text-[10px] sm:text-sm text-black font-medium mb-0.5 sm:mb-1">Received Date</p>
              <p className="text-[11px] sm:text-base text-black">{shipment.receiptVerifiedAt ? formatDate(shipment.receiptVerifiedAt) : 'Pending'}</p>
            </div>
          </div>

          {/* Items Info */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-4 mb-4 sm:mb-6 pb-4 sm:pb-6 border-b">
            <div className="bg-gray-50 p-2 sm:p-3 rounded-lg">
              <p className="text-[9px] sm:text-xs text-black font-medium">Expected</p>
              <p className="text-sm sm:text-lg font-bold text-black">{shipment.itemsExpected || products.length}</p>
            </div>
            <div className="bg-gray-50 p-2 sm:p-3 rounded-lg">
              <p className="text-[9px] sm:text-xs text-black font-medium">Received</p>
              <p className="text-sm sm:text-lg font-bold text-black">{shipment.itemsReceived ?? 'ΓÇö'}</p>
            </div>
            <div className="bg-orange-50 p-2 sm:p-3 rounded-lg">
              <p className="text-[9px] sm:text-xs text-orange-800 font-medium">Missing</p>
              <p className="text-sm sm:text-lg font-bold text-orange-800">{shipment.itemsMissing ?? 'ΓÇö'}</p>
            </div>
            <div className="bg-red-50 p-2 sm:p-3 rounded-lg">
              <p className="text-[9px] sm:text-xs text-red-800 font-medium">Damaged</p>
              <p className="text-sm sm:text-lg font-bold text-red-800">{shipment.itemsDamaged ?? 'ΓÇö'}</p>
            </div>
          </div>

          {/* Products */}
          <div className="mb-4 sm:mb-6">
            <p className="text-[10px] sm:text-sm text-black font-medium mb-2 sm:mb-3">Products in Shipment</p>
            <div className="space-y-2">
              {products.map((product) => (
                <div key={product.id} className="flex gap-2 sm:gap-3 p-2 sm:p-3 bg-gray-50 rounded-lg">
                  <div className="w-12 h-12 sm:w-16 sm:h-16 rounded bg-gray-200 flex-shrink-0 flex items-center justify-center overflow-hidden">
                    {product.thumbnailUrl ? (
                      <img
                        src={product.thumbnailUrl}
                        alt={product.title}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <Package className="w-5 h-5 sm:w-6 sm:h-6 text-gray-400" />
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <h3 className="text-[10px] sm:text-sm font-semibold text-black">{product.title}</h3>
                    <p className="text-[9px] sm:text-xs text-black mt-0.5">{formatCurrency(product.basePrice)}</p>
                    {(product as any).variants && (product as any).variants.length > 0 && (
                      <p className="text-[9px] sm:text-xs text-gray-600 mt-1">{(product as any).variants.length} variant(s)</p>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Variant Discrepancies */}
          {shipment.variantDiscrepancies && shipment.variantDiscrepancies.length > 0 && (
            <div className="mb-4 sm:mb-6 p-2 sm:p-4 bg-blue-50 rounded-lg border border-blue-200">
              <p className="text-[10px] sm:text-sm text-blue-800 font-medium mb-2 sm:mb-3">Variant-Level Discrepancies</p>
              <div className="space-y-2">
                {shipment.variantDiscrepancies.map((discrepancy: any) => (
                  <div key={discrepancy.id} className="p-2 sm:p-3 bg-white rounded border border-blue-100">
                    <div className="flex items-start justify-between gap-2 mb-1">
                      <div className="flex-1">
                        <p className="text-[9px] sm:text-xs font-semibold text-black">
                          {discrepancy.variant.product.title}
                          {discrepancy.variant.size && ` - Size: ${discrepancy.variant.size}`}
                          {discrepancy.variant.color && ` - Color: ${discrepancy.variant.color}`}
                        </p>
                      </div>
                      <span className={`px-2 py-0.5 rounded text-[8px] sm:text-xs font-medium flex-shrink-0 ${
                        discrepancy.acceptanceStatus === 'ACCEPTED' ? 'bg-green-100 text-green-800' :
                        discrepancy.acceptanceStatus === 'RETURNING' ? 'bg-red-100 text-red-800' :
                        discrepancy.acceptanceStatus === 'PARTIAL' ? 'bg-yellow-100 text-yellow-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                        {discrepancy.acceptanceStatus}
                      </span>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-1 text-[9px] sm:text-xs text-black mt-2">
                      <div>Expected: <span className="font-semibold">{discrepancy.quantityExpected}</span></div>
                      {discrepancy.quantityReceived !== null && <div>Received: <span className="font-semibold">{discrepancy.quantityReceived}</span></div>}
                      {discrepancy.quantityDamaged !== null && <div>Damaged: <span className="font-semibold text-red-600">{discrepancy.quantityDamaged}</span></div>}
                      {discrepancy.quantityMissing !== null && <div>Missing: <span className="font-semibold text-orange-600">{discrepancy.quantityMissing}</span></div>}
                    </div>
                    {discrepancy.acceptanceStatus === 'PARTIAL' && (
                      <div className="grid grid-cols-2 gap-1 text-[9px] sm:text-xs text-black mt-1">
                        {discrepancy.unitsAccepted !== null && <div>Accepting: <span className="font-semibold text-green-600">{discrepancy.unitsAccepted}</span></div>}
                        {discrepancy.unitsReturning !== null && <div>Returning: <span className="font-semibold text-red-600">{discrepancy.unitsReturning}</span></div>}
                      </div>
                    )}
                    {discrepancy.notes && (
                      <p className="text-[9px] sm:text-xs text-gray-600 mt-1 italic">{discrepancy.notes}</p>
                    )}
                    
                    {/* Decision Controls */}
                    {discrepancy.acceptanceStatus === 'PENDING' && (
                      <div className="mt-3 pt-3 border-t border-blue-100">
                        <div className="mb-3">
                          <label className="text-[8px] sm:text-xs text-black font-medium block mb-1">Decision Notes (optional)</label>
                          <textarea
                            value={variantDecisions[discrepancy.id]?.notes || ''}
                            onChange={(e) => {
                              setVariantDecisions(prev => ({
                                ...prev,
                                [discrepancy.id]: { 
                                  ...prev[discrepancy.id], 
                                  notes: e.target.value 
                                }
                              }))
                            }}
                            placeholder="e.g., 'Items damaged in transit', 'Quality below standard'"
                            rows={2}
                            aria-label="Decision Notes"
                            className="w-full border border-gray-300 rounded px-2 sm:px-3 py-1 sm:py-2 text-xs sm:text-sm"
                          />
                          <p className="text-[8px] sm:text-xs text-gray-600 mt-1">Seller will receive this explanation in their notification</p>
                        </div>

                        <div className="mb-3">
                          <label className="text-[8px] sm:text-xs text-black font-medium block mb-1">Rejection Category (if rejecting)</label>
                          <select
                            value={variantDecisions[discrepancy.id]?.rejectionCategory || ''}
                            onChange={(e) => {
                              setVariantDecisions(prev => ({
                                ...prev,
                                [discrepancy.id]: { 
                                  ...prev[discrepancy.id], 
                                  rejectionCategory: e.target.value
                                }
                              }))
                            }}
                            className="w-full border border-gray-300 rounded px-2 sm:px-3 py-1 sm:py-2 text-xs sm:text-sm"
                          >
                            <option value="">Select reason (optional)</option>
                            <option value="DAMAGED">Damaged/Defective</option>
                            <option value="QUANTITY_MISMATCH">Quantity Mismatch</option>
                            <option value="QUALITY">Quality Below Standard</option>
                            <option value="WRONG_PRODUCT">Wrong Product</option>
                            <option value="MISSING">Missing Items</option>
                          </select>
                        </div>

                        <p className="text-[8px] sm:text-xs text-gray-600 mb-2">Decision:</p>
                        <div className="flex flex-wrap gap-1 items-center">
                          <button
                            onClick={() => {
                              setVariantDecisions(prev => ({
                                ...prev,
                                [discrepancy.id]: { status: 'ACCEPTED', loading: false }
                              }))
                              handleVariantDecision(discrepancy.id, 'ACCEPTED')
                            }}
                            disabled={variantDecisions[discrepancy.id]?.loading}
                            className="px-2 sm:px-3 py-1 text-[8px] sm:text-xs bg-green-500 hover:bg-green-600 disabled:bg-gray-400 text-white rounded font-medium transition"
                          >
                            {variantDecisions[discrepancy.id]?.loading ? 'Processing...' : 'Accept All'}
                          </button>
                          <button
                            onClick={() => {
                              setVariantDecisions(prev => ({
                                ...prev,
                                [discrepancy.id]: { status: 'RETURNING', loading: false }
                              }))
                              handleVariantDecision(discrepancy.id, 'RETURNING')
                            }}
                            disabled={variantDecisions[discrepancy.id]?.loading}
                            className="px-2 sm:px-3 py-1 text-[8px] sm:text-xs bg-red-500 hover:bg-red-600 disabled:bg-gray-400 text-white rounded font-medium transition"
                          >
                            {variantDecisions[discrepancy.id]?.loading ? 'Processing...' : 'Return All'}
                          </button>
                          <button
                            onClick={() => {
                              setShowPartialModal(discrepancy.id)
                              setPartialForm({
                                unitsAccepted: Math.max(0, discrepancy.quantityReceived || 0),
                                unitsReturning: 0,
                                notes: '',
                                rejectionCategory: ''
                              })
                              setVariantDecisions(prev => ({
                                ...prev,
                                [discrepancy.id]: { 
                                  status: 'PARTIAL',
                                  unitsAccepted: discrepancy.quantityReceived || 0,
                                  unitsReturning: 0
                                }
                              }))
                            }}
                            disabled={variantDecisions[discrepancy.id]?.loading}
                            className="px-2 sm:px-3 py-1 text-[8px] sm:text-xs bg-yellow-500 hover:bg-yellow-600 disabled:bg-gray-400 text-white rounded font-medium transition"
                          >
                            Partial Split
                          </button>
                        </div>
                      </div>
                    )}

                    {/* Edit Decision Button for Decided Variants */}
                    {discrepancy.acceptanceStatus !== 'PENDING' && (
                      <div className="mt-3 pt-3 border-t border-blue-100">
                        <button
                          onClick={() => {
                            setVariantDecisions(prev => ({
                              ...prev,
                              [discrepancy.id]: { 
                                status: 'PENDING', 
                                loading: false,
                                notes: '' 
                              }
                            }))
                          }}
                          className="px-2 sm:px-3 py-1 text-[8px] sm:text-xs bg-blue-500 hover:bg-blue-600 text-white rounded font-medium transition"
                        >
                          Γ£Ä Edit Decision
                        </button>
                        <p className="text-[8px] sm:text-xs text-gray-600 mt-2">Current: <span className="font-semibold">{discrepancy.acceptanceStatus}</span></p>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Partial Decision Modal */}
          {showPartialModal && (
            <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-3 z-50">
              <div className="bg-white rounded-lg p-4 sm:p-6 max-w-sm w-full">
                <h3 className="text-sm sm:text-lg font-bold text-black mb-3 sm:mb-4">Partial Acceptance Decision</h3>
                
                {(() => {
                  const discrepancy = shipment?.variantDiscrepancies?.find((d: any) => d.id === showPartialModal)
                  const received = discrepancy?.quantityReceived || 0
                  return (
                    <div className="space-y-3 sm:space-y-4">
                      <p className="text-[9px] sm:text-xs text-gray-600">
                        Total received: <span className="font-semibold text-black">{received} units</span>
                      </p>
                      
                      <div>
                        <label className="text-[9px] sm:text-xs text-black font-medium block mb-1">Units to Accept</label>
                        <input
                          type="number"
                          min="0"
                          max={received}
                          value={partialForm.unitsAccepted}
                          onChange={(e) => {
                            const val = Math.min(parseInt(e.target.value) || 0, received)
                            setPartialForm(prev => ({ ...prev, unitsAccepted: val }))
                            setVariantDecisions(prev => ({
                              ...prev,
                              [showPartialModal]: { status: 'PARTIAL', unitsAccepted: val, unitsReturning: received - val }
                            }))
                          }}
                          aria-label="Units to Accept"
                          className="w-full border border-gray-300 rounded px-2 sm:px-3 py-1 sm:py-2 text-xs sm:text-sm"
                        />
                      </div>

                      <div>
                        <label className="text-[9px] sm:text-xs text-black font-medium block mb-1">Units to Return</label>
                        <input
                          type="number"
                          min="0"
                          value={received - partialForm.unitsAccepted}
                          disabled
                          aria-label="Units to Return"
                          className="w-full border border-gray-300 rounded px-2 sm:px-3 py-1 sm:py-2 text-xs sm:text-sm bg-gray-50"
                        />
                        <p className="text-[8px] sm:text-xs text-gray-600 mt-1">Auto-calculated: {received} - {partialForm.unitsAccepted} = {received - partialForm.unitsAccepted}</p>
                      </div>

                      {partialForm.unitsAccepted + (received - partialForm.unitsAccepted) !== received && (
                        <p className="text-[9px] sm:text-xs text-red-600">ΓÜá∩╕Å Total must equal {received}</p>
                      )}

                      <div>
                        <label className="text-[9px] sm:text-xs text-black font-medium block mb-1">Decision Notes (optional)</label>
                        <textarea
                          value={partialForm.notes}
                          onChange={(e) => {
                            setPartialForm(prev => ({ ...prev, notes: e.target.value }))
                            if (showPartialModal) {
                              setVariantDecisions(prev => ({
                                ...prev,
                                [showPartialModal]: { 
                                  ...prev[showPartialModal], 
                                  notes: e.target.value 
                                }
                              }))
                            }
                          }}
                          placeholder="e.g., '10 units have water damage, 10 units are intact'"
                          rows={3}
                          aria-label="Decision Notes"
                          className="w-full border border-gray-300 rounded px-2 sm:px-3 py-1 sm:py-2 text-xs sm:text-sm"
                        />
                        <p className="text-[8px] sm:text-xs text-gray-600 mt-1">Seller will receive this in their notification email</p>
                      </div>

                      <div className="flex gap-2 pt-2">
                        <button
                          onClick={() => {
                            setShowPartialModal(null)
                            setVariantDecisions(prev => {
                              const newDecisions = { ...prev }
                              delete newDecisions[showPartialModal]
                              return newDecisions
                            })
                          }}
                          className="flex-1 px-3 py-2 text-[9px] sm:text-xs bg-gray-300 hover:bg-gray-400 text-black rounded font-medium transition"
                        >
                          Cancel
                        </button>
                        <button
                          onClick={() => {
                            handleVariantDecision(showPartialModal, 'PARTIAL')
                          }}
                          disabled={variantDecisions[showPartialModal]?.loading}
                          className="flex-1 px-3 py-2 text-[9px] sm:text-xs bg-yellow-500 hover:bg-yellow-600 disabled:bg-gray-400 text-white rounded font-medium transition"
                        >
                          {variantDecisions[showPartialModal]?.loading ? 'Processing...' : 'Confirm'}
                        </button>
                      </div>
                    </div>
                  )
                })()}
              </div>
            </div>
          )}


          {/* Discrepancy Info */}
          {shipment.hasDiscrepancy && (
            <div className="mb-4 sm:mb-6 p-2 sm:p-4 bg-orange-50 rounded-lg border border-orange-200">
              <p className="text-[10px] sm:text-sm text-orange-800 font-medium flex items-center gap-1 mb-2 sm:mb-3">
                <AlertTriangle className="w-4 h-4" />
                Discrepancy Detected
              </p>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 text-[9px] sm:text-xs text-orange-800 mb-2 sm:mb-3">
                {shipment.itemsMissing !== undefined && <p>Missing: {shipment.itemsMissing}</p>}
                {shipment.itemsDamaged !== undefined && <p>Damaged: {shipment.itemsDamaged}</p>}
                {shipment.itemsReceived !== undefined && <p>Received: {shipment.itemsReceived}</p>}
              </div>
              {shipment.disputeStatus && (
                <p className="text-[9px] sm:text-xs text-orange-700 mb-1">
                  <span className="font-semibold">Status:</span> {shipment.disputeStatus}
                </p>
              )}
              {shipment.disputeNotes && (
                <div className="mt-2 p-2 bg-white rounded text-[9px] sm:text-xs text-orange-800">
                  <p className="font-semibold mb-1">Issue Details:</p>
                  <p>{shipment.disputeNotes}</p>
                </div>
              )}
            </div>
          )}

          {/* Receipt Photos */}
          {shipment.receiptPhotos && shipment.receiptPhotos.length > 0 && (
            <div className="mb-4 sm:mb-6">
              <p className="text-[10px] sm:text-sm text-black font-medium mb-2 sm:mb-3">Receipt Photos</p>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 sm:gap-3">
                {shipment.receiptPhotos.map((photo, index) => (
                  <img
                    key={index}
                    src={photo}
                    alt={`Receipt ${index + 1}`}
                    className="w-full h-24 sm:h-32 object-cover rounded-lg"
                  />
                ))}
              </div>
            </div>
          )}

          {/* Notes */}
          {shipment.notes && (
            <div className="mb-4 sm:mb-6 p-2 sm:p-3 bg-blue-50 rounded-lg">
              <p className="text-[10px] sm:text-sm text-black font-medium mb-1">Notes</p>
              <p className="text-[10px] sm:text-sm text-black">{shipment.notes}</p>
            </div>
          )}

          {/* Actions */}
          <div className="flex flex-wrap gap-2 pt-4 sm:pt-6 border-t">
            {(shipment.status === 'IN_TRANSIT' || shipment.status === 'DELIVERED' || shipment.status === 'SHIPPED') && !shipment.hasDiscrepancy ? (
              <button
                onClick={() => setShowApproveConfirm(true)}
                disabled={actionLoading}
                className="flex items-center gap-1 sm:gap-2 bg-green-600 text-white px-2 sm:px-4 py-1.5 sm:py-2 rounded-lg text-[10px] sm:text-sm font-medium hover:bg-green-700 disabled:opacity-50"
              >
                <CheckCircle className="w-3 h-3 sm:w-4 sm:h-4" />
                Confirm Receipt
              </button>
            ) : null}
            {shipment.hasDiscrepancy && shipment.status !== 'RECEIVED' && (
              <>
                <button
                  onClick={() => setShowApproveConfirm(true)}
                  disabled={actionLoading}
                  className="flex items-center gap-1 sm:gap-2 bg-green-600 text-white px-2 sm:px-4 py-1.5 sm:py-2 rounded-lg text-[10px] sm:text-sm font-medium hover:bg-green-700 disabled:opacity-50"
                >
                  <CheckCircle className="w-3 h-3 sm:w-4 sm:h-4" />
                  Approve & Go Live
                </button>
                <button
                  onClick={() => setShowRejectConfirm(true)}
                  disabled={actionLoading}
                  className="flex items-center gap-1 sm:gap-2 bg-red-600 text-white px-2 sm:px-4 py-1.5 sm:py-2 rounded-lg text-[10px] sm:text-sm font-medium hover:bg-red-700 disabled:opacity-50"
                >
                  <XCircle className="w-3 h-3 sm:w-4 sm:h-4" />
                  Reject
                </button>
              </>
            )}
            <button
              onClick={() => {
                setDiscrepancyForm({
                  itemsReceived: shipment.itemsReceived || shipment.itemsExpected,
                  itemsDamaged: 0,
                  damagedItemName: '',
                  damagedItemLocation: '',
                  damagedItemNotes: '',
                  damagedItems: [],
                  photos: [],
                  video: '',
                  otherNotes: '',
                })
                setShowDiscrepancyModal(true)
              }}
              disabled={actionLoading}
              className="flex items-center gap-1 sm:gap-2 bg-orange-600 text-white px-2 sm:px-4 py-1.5 sm:py-2 rounded-lg text-[10px] sm:text-sm font-medium hover:bg-orange-700 disabled:opacity-50"
            >
              <AlertTriangle className="w-3 h-3 sm:w-4 sm:h-4" />
              Report Issue
            </button>
            <button
              onClick={() => router.back()}
              className="flex items-center gap-1 sm:gap-2 border border-gray-200 text-black px-2 sm:px-4 py-1.5 sm:py-2 rounded-lg text-[10px] sm:text-sm font-medium hover:bg-gray-50"
            >
              Close
            </button>
          </div>
        </div>

        {/* Discrepancy Modal */}
        {showDiscrepancyModal && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-3 z-50 overflow-hidden">
            <div className="bg-white rounded-xl shadow-lg max-w-2xl w-full h-auto max-h-[85vh] flex flex-col">
              <div className="p-4 sm:p-6 border-b flex-shrink-0 bg-white">
                <h2 className="text-lg sm:text-2xl font-bold text-black">Report Discrepancy</h2>
              </div>

              <div className="p-4 sm:p-6 space-y-4 sm:space-y-6 flex-1 overflow-y-auto">
                {/* Discrepancy Type Selection */}
                <div>
                  <p className="text-sm font-medium text-black mb-2 sm:mb-3">Issue Type</p>
                  <div className="grid grid-cols-3 gap-2 sm:gap-3">
                    <button
                      onClick={() => setDiscrepancyType('incomplete')}
                      className={`p-2 sm:p-3 rounded-lg border-2 text-center transition ${
                        discrepancyType === 'incomplete'
                          ? 'border-purple-600 bg-purple-50'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <p className="text-[10px] sm:text-xs font-medium text-black">Incomplete</p>
                      <p className="text-[8px] sm:text-[10px] text-gray-600 mt-0.5">Missing items</p>
                    </button>
                    <button
                      onClick={() => setDiscrepancyType('damaged')}
                      className={`p-2 sm:p-3 rounded-lg border-2 text-center transition ${
                        discrepancyType === 'damaged'
                          ? 'border-purple-600 bg-purple-50'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <p className="text-[10px] sm:text-xs font-medium text-black">Damaged</p>
                      <p className="text-[8px] sm:text-[10px] text-gray-600 mt-0.5">Damaged items</p>
                    </button>
                    <button
                      onClick={() => setDiscrepancyType('wrong')}
                      className={`p-2 sm:p-3 rounded-lg border-2 text-center transition ${
                        discrepancyType === 'wrong'
                          ? 'border-purple-600 bg-purple-50'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <p className="text-[10px] sm:text-xs font-medium text-black">Wrong Item</p>
                      <p className="text-[8px] sm:text-[10px] text-gray-600 mt-0.5">Color, size, etc</p>
                    </button>
                  </div>
                </div>

                {/* Incomplete Form */}
                {discrepancyType === 'incomplete' && (
                  <div className="space-y-3 sm:space-y-4 p-3 sm:p-4 bg-blue-50 rounded-lg">
                    <div>
                      <label className="text-[10px] sm:text-sm font-medium text-black block mb-1.5">
                        Items Received (Expected: {shipment?.itemsExpected})
                      </label>
                      <input
                        type="number"
                        placeholder="Enter number of items received"
                        value={discrepancyForm.itemsReceived}
                        onChange={(e) =>
                          setDiscrepancyForm({
                            ...discrepancyForm,
                            itemsReceived: parseInt(e.target.value) || 0,
                          })
                        }
                        min="0"
                        max={shipment?.itemsExpected}
                        className="w-full px-2 sm:px-3 py-1.5 sm:py-2 border rounded-lg text-black bg-white text-[10px] sm:text-sm"
                      />
                      <p className="text-[9px] sm:text-xs text-blue-700 mt-1">
                        Missing: {Math.max(0, (shipment?.itemsExpected || 0) - discrepancyForm.itemsReceived)}
                      </p>
                    </div>
                  </div>
                )}

                {/* Damaged Form */}
                {discrepancyType === 'damaged' && (
                  <div className="space-y-3 sm:space-y-4 p-3 sm:p-4 bg-orange-50 rounded-lg">
                    <div>
                      <label className="text-[10px] sm:text-sm font-medium text-black block mb-1.5">
                        Number of Damaged Items
                      </label>
                      <input
                        type="number"
                        placeholder="Enter number of damaged items"
                        value={discrepancyForm.itemsDamaged}
                        onChange={(e) =>
                          setDiscrepancyForm({
                            ...discrepancyForm,
                            itemsDamaged: parseInt(e.target.value) || 0,
                          })
                        }
                        min="0"
                        className="w-full px-2 sm:px-3 py-1.5 sm:py-2 border rounded-lg text-black bg-white text-[10px] sm:text-sm"
                      />
                    </div>
                    <div>
                      <label className="text-[10px] sm:text-sm font-medium text-black block mb-1.5">
                        Damaged Item Name
                      </label>
                      <input
                        type="text"
                        placeholder="e.g., Blue T-Shirt"
                        value={discrepancyForm.damagedItemName}
                        onChange={(e) =>
                          setDiscrepancyForm({
                            ...discrepancyForm,
                            damagedItemName: e.target.value,
                          })
                        }
                        className="w-full px-2 sm:px-3 py-1.5 sm:py-2 border rounded-lg text-black bg-white text-[10px] sm:text-sm"
                      />
                    </div>
                    <div>
                      <label className="text-[10px] sm:text-sm font-medium text-black block mb-1.5">
                        Damage Location
                      </label>
                      <input
                        type="text"
                        placeholder="e.g., Right sleeve, seam"
                        value={discrepancyForm.damagedItemLocation}
                        onChange={(e) =>
                          setDiscrepancyForm({
                            ...discrepancyForm,
                            damagedItemLocation: e.target.value,
                          })
                        }
                        className="w-full px-2 sm:px-3 py-1.5 sm:py-2 border rounded-lg text-black bg-white text-[10px] sm:text-sm"
                      />
                    </div>
                    <div>
                      <label className="text-[10px] sm:text-sm font-medium text-black block mb-1.5">
                        Damage Notes
                      </label>
                      <textarea
                        placeholder="Describe the damage..."
                        value={discrepancyForm.damagedItemNotes}
                        onChange={(e) =>
                          setDiscrepancyForm({
                            ...discrepancyForm,
                            damagedItemNotes: e.target.value,
                          })
                        }
                        className="w-full px-2 sm:px-3 py-1.5 sm:py-2 border rounded-lg text-black bg-white text-[10px] sm:text-sm h-16 sm:h-20"
                      />
                    </div>
                  </div>
                )}

                {/* Wrong Item Form */}
                {discrepancyType === 'wrong' && (
                  <div className="space-y-3 sm:space-y-4 p-3 sm:p-4 bg-red-50 rounded-lg">
                    <div>
                      <label className="text-[10px] sm:text-sm font-medium text-black block mb-1.5">
                        Issue Details
                      </label>
                      <textarea
                        placeholder="Describe the issue (e.g., Wrong color sent - ordered blue, received red. Wrong size - ordered M, received S. etc.)"
                        className="w-full px-2 sm:px-3 py-1.5 sm:py-2 border rounded-lg text-black bg-white text-[10px] sm:text-sm h-20 sm:h-24"
                        value={discrepancyForm.otherNotes}
                        onChange={(e) =>
                          setDiscrepancyForm({
                            ...discrepancyForm,
                            otherNotes: e.target.value,
                          })
                        }
                      />
                    </div>
                  </div>
                )}

                {/* Notes for all types */}
                <div>
                  <label className="text-[10px] sm:text-sm font-medium text-black block mb-1.5">
                    Additional Notes
                  </label>
                  <textarea
                    placeholder="Any other information..."
                    className="w-full px-2 sm:px-3 py-1.5 sm:py-2 border rounded-lg text-black bg-white text-[10px] sm:text-sm h-16 sm:h-20"
                    value={discrepancyForm.otherNotes}
                    onChange={(e) =>
                      setDiscrepancyForm({
                        ...discrepancyForm,
                        otherNotes: e.target.value,
                      })
                    }
                  />
                </div>
              </div>

              {/* Action Buttons - Outside scroll area */}
              <div className="p-4 sm:p-6 border-t flex-shrink-0 bg-white flex gap-2">
                  <button
                    onClick={() => {
                      const submitData: any = {
                        type: discrepancyType,
                      }
                      
                      // Include itemsReceived for incomplete type
                      if (discrepancyType === 'incomplete' && discrepancyForm.itemsReceived > 0) {
                        submitData.itemsReceived = discrepancyForm.itemsReceived
                      }
                      
                      // Include itemsDamaged for damaged type with details
                      if (discrepancyType === 'damaged' && discrepancyForm.itemsDamaged > 0) {
                        submitData.itemsDamaged = discrepancyForm.itemsDamaged
                        
                        // Include detailed damage information
                        if (discrepancyForm.damagedItemName.trim() || discrepancyForm.damagedItemLocation.trim() || discrepancyForm.damagedItemNotes.trim()) {
                          submitData.damageDetails = {
                            name: discrepancyForm.damagedItemName,
                            location: discrepancyForm.damagedItemLocation,
                            notes: discrepancyForm.damagedItemNotes,
                          }
                        }
                      }
                      
                      // Include any additional notes
                      if (discrepancyForm.otherNotes.trim()) {
                        submitData.notes = discrepancyForm.otherNotes
                      }
                      
                      handleAction('markDiscrepancy', submitData)
                      setShowDiscrepancyModal(false)
                    }}
                    disabled={actionLoading}
                    className="flex-1 bg-orange-600 text-white px-3 sm:px-4 py-1.5 sm:py-2 rounded-lg text-[10px] sm:text-sm font-medium hover:bg-orange-700 disabled:opacity-50"
                  >
                    Report Issue
                  </button>
                  <button
                    onClick={() => setShowDiscrepancyModal(false)}
                    className="flex-1 border border-gray-200 text-black px-3 sm:px-4 py-1.5 sm:py-2 rounded-lg text-[10px] sm:text-sm font-medium hover:bg-gray-50"
                  >
                    Cancel
                  </button>
              </div>
            </div>
          </div>
        )}

        {/* Approve Confirmation Modal */}
        {showApproveConfirm && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-3 sm:p-4">
            <div className="bg-white rounded-xl shadow-lg max-w-sm w-full p-4 sm:p-6">
              <div className="flex items-start gap-3 sm:gap-4 mb-4 sm:mb-6">
                <CheckCircle className="w-6 h-6 sm:w-8 sm:h-8 text-green-600 flex-shrink-0 mt-1" />
                <div>
                  <h3 className="text-base sm:text-lg font-bold text-black">Confirm Approval</h3>
                  <p className="text-[10px] sm:text-sm text-black mt-1">Are you sure you want to approve this shipment and mark products as ready for live? This action cannot be undone.</p>
                </div>
              </div>
              
              {shipment?.hasDiscrepancy && (
                <div className="mb-4 p-3 bg-yellow-50 rounded-lg border border-yellow-200">
                  <p className="text-[10px] sm:text-xs font-medium text-yellow-800">ΓÜá∩╕Å Note: This shipment has discrepancies:</p>
                  <p className="text-[10px] sm:text-xs text-yellow-700 mt-1">
                    Missing: {shipment.itemsMissing}, Damaged: {shipment.itemsDamaged}
                  </p>
                </div>
              )}

              <div className="flex gap-2 sm:gap-3">
                <button
                  onClick={() => {
                    handleAction('confirmReceiptWithDiscrepancy')
                    setShowApproveConfirm(false)
                  }}
                  disabled={actionLoading}
                  className="flex-1 bg-green-600 text-white px-3 sm:px-4 py-2 sm:py-2.5 rounded-lg text-[10px] sm:text-sm font-medium hover:bg-green-700 disabled:opacity-50"
                >
                  Approve & Go Live
                </button>
                <button
                  onClick={() => setShowApproveConfirm(false)}
                  className="flex-1 border border-gray-200 text-black px-3 sm:px-4 py-2 sm:py-2.5 rounded-lg text-[10px] sm:text-sm font-medium hover:bg-gray-50"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Reject Confirmation Modal */}
        {showRejectConfirm && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-3 sm:p-4">
            <div className="bg-white rounded-xl shadow-lg max-w-sm w-full p-4 sm:p-6">
              <div className="flex items-start gap-3 sm:gap-4 mb-4 sm:mb-6">
                <XCircle className="w-6 h-6 sm:w-8 sm:h-8 text-red-600 flex-shrink-0 mt-1" />
                <div>
                  <h3 className="text-base sm:text-lg font-bold text-black">Reject Shipment</h3>
                  <p className="text-[10px] sm:text-sm text-black mt-1">Please provide a reason for rejection. The seller will be notified and can schedule a pickup within 7 days.</p>
                </div>
              </div>

              {shipment?.hasDiscrepancy && (
                <div className="mb-4 p-3 bg-orange-50 rounded-lg border border-orange-200">
                  <p className="text-[10px] sm:text-xs font-medium text-orange-800">Discrepancies reported:</p>
                  <p className="text-[10px] sm:text-xs text-orange-700 mt-1">
                    Missing: {shipment.itemsMissing}, Damaged: {shipment.itemsDamaged}
                  </p>
                </div>
              )}
              
              <textarea
                value={rejectReason}
                onChange={(e) => setRejectReason(e.target.value)}
                placeholder="Enter rejection reason..."
                className="w-full px-3 sm:px-4 py-2 sm:py-3 border border-gray-200 rounded-lg text-[10px] sm:text-sm text-black placeholder-gray-400 focus:ring-2 focus:ring-red-500 mb-4 sm:mb-6 min-h-24"
              />

              <div className="flex gap-2 sm:gap-3">
                <button
                  onClick={() => {
                    if (!rejectReason.trim()) {
                      toast.error('Please provide a rejection reason')
                      return
                    }
                    handleAction('rejectShipment', { reason: rejectReason })
                    setShowRejectConfirm(false)
                    setRejectReason('')
                  }}
                  disabled={actionLoading || !rejectReason.trim()}
                  className="flex-1 bg-red-600 text-white px-3 sm:px-4 py-2 sm:py-2.5 rounded-lg text-[10px] sm:text-sm font-medium hover:bg-red-700 disabled:opacity-50"
                >
                  Reject & Notify Seller
                </button>
                <button
                  onClick={() => {
                    setShowRejectConfirm(false)
                    setRejectReason('')
                  }}
                  className="flex-1 border border-gray-200 text-black px-3 sm:px-4 py-2 sm:py-2.5 rounded-lg text-[10px] sm:text-sm font-medium hover:bg-gray-50"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import _Image from 'next/image'
import Link from 'next/link'
import { 
  Package, Truck, Search, Filter, ChevronLeft, ChevronRight,
  Clock, CheckCircle, XCircle, AlertTriangle, Eye,
  User, Calendar
} from 'lucide-react'
import toast from 'react-hot-toast'

interface Seller {
  id: string
  name: string
  email: string
}

interface Product {
  id: string
  title: string
  thumbnailUrl: string | null
  basePrice: number
}

interface Shipment {
  id: string
  status: string
  courier: string
  trackingNumber: string
  estimatedArrival: string | null
  shippedAt: string | null
  receivedAt: string | null
  createdAt: string
  notes: string | null
  itemsExpected: number
  itemsReceived: number | null
  itemsMissing: number | null
  itemsDamaged: number | null
  hasDiscrepancy: boolean
  receiptPhotos: string[]
  seller: Seller
  products?: Product[]
  product?: Product
}

const STATUS_CONFIG: Record<string, { label: string; color: string; bgColor: string; icon: React.ElementType }> = {
  PENDING: { label: 'Pending', color: 'text-yellow-700', bgColor: 'bg-yellow-50', icon: Clock },
  IN_TRANSIT: { label: 'In Transit', color: 'text-blue-700', bgColor: 'bg-blue-50', icon: Truck },
  DELIVERED: { label: 'Delivered', color: 'text-indigo-700', bgColor: 'bg-indigo-50', icon: Package },
  RECEIVED: { label: 'Received', color: 'text-green-700', bgColor: 'bg-green-50', icon: CheckCircle },
  DISCREPANCY: { label: 'Discrepancy', color: 'text-orange-700', bgColor: 'bg-orange-50', icon: AlertTriangle },
  CANCELLED: { label: 'Cancelled', color: 'text-red-700', bgColor: 'bg-red-50', icon: XCircle },
}

export default function AdminShipmentsPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [shipments, setShipments] = useState<Shipment[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [statusFilter, setStatusFilter] = useState('')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [selectedShipment, setSelectedShipment] = useState<Shipment | null>(null)
  const [showReceiveModal, setShowReceiveModal] = useState(false)
  
  // Receive form state
  const [receiveForm, setReceiveForm] = useState({
    itemsReceived: 1,
    itemsMissing: 0,
    itemsDamaged: 0,
    notes: '',
  })

  useEffect(() => {
    if (status === 'loading') return
    if (!session || (session.user as any).role !== 'ADMIN') {
      router.push('/auth/signin')
      return
    }
    fetchShipments()
  }, [session, status, page, statusFilter])

  const fetchShipments = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        page: page.toString(),
        limit: '20',
      })
      if (statusFilter) params.append('status', statusFilter)
      if (searchQuery) params.append('search', searchQuery)

      const res = await fetch(`/api/boutique/admin/shipments?${params}`)
      if (res.ok) {
        const data = await res.json()
        setShipments(data.shipments || [])
        setTotalPages(data.totalPages || 1)
      }
    } catch (error) {
      console.error('Failed to fetch shipments:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault()
    setPage(1)
    fetchShipments()
  }

  const openReceiveModal = (shipment: Shipment) => {
    setSelectedShipment(shipment)
    setReceiveForm({
      itemsReceived: shipment.itemsExpected,
      itemsMissing: 0,
      itemsDamaged: 0,
      notes: '',
    })
    setShowReceiveModal(true)
  }

  const confirmReceipt = async () => {
    if (!selectedShipment) return

    try {
      const res = await fetch(`/api/boutique/admin/shipments/${selectedShipment.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'receive',
          ...receiveForm,
        }),
      })

      if (res.ok) {
        toast.success('Shipment received!')
        setShowReceiveModal(false)
        fetchShipments()
      } else {
        const data = await res.json()
        toast.error(data.message || 'Failed to confirm receipt')
      }
    } catch (_error) {
      toast.error('Failed to confirm receipt')
    }
  }

  const confirmReceiptWithDiscrepancy = async (shipmentId: string) => {
    try {
      const res = await fetch(`/api/boutique/admin/shipments/${shipmentId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'confirmReceiptWithDiscrepancy',
        }),
      })

      if (res.ok) {
        toast.success('Shipment received with noted discrepancy!')
        fetchShipments()
      } else {
        const data = await res.json()
        toast.error(data.message || 'Failed to confirm receipt')
      }
    } catch (_error) {
      toast.error('Failed to confirm receipt')
    }
  }

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-NG', {
      style: 'currency',
      currency: 'NGN',
      minimumFractionDigits: 0,
    }).format(amount)
  }

  const formatDate = (date: string) => {
    return new Date(date).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    })
  }

  // Count by status - include discrepancy shipments that still need confirmation
  const pendingCount = shipments.filter(s => 
    s.status === 'IN_TRANSIT' || 
    s.status === 'DELIVERED' || 
    (s.status === 'DISCREPANCY' && s.hasDiscrepancy)
  ).length

  if (status === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600"></div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 py-3 sm:py-8">
      <div className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="mb-3 sm:mb-8">
          <Link href="/admin/boutique" className="text-purple-600 hover:text-purple-700 flex items-center gap-1 mb-2 sm:mb-4 text-[10px] sm:text-sm">
            <ChevronLeft className="w-3 h-3 sm:w-4 sm:h-4" />
            Back to Admin
          </Link>
          <div className="flex items-center gap-2 sm:gap-3">
            <Truck className="w-5 h-5 sm:w-8 sm:h-8 text-purple-600" />
            <div>
              <h1 className="text-lg sm:text-3xl font-bold text-black">Incoming Shipments</h1>
              <p className="text-[10px] sm:text-base text-black">
                {pendingCount} awaiting receipt
              </p>
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-xl shadow-sm p-2.5 sm:p-4 mb-3 sm:mb-6">
          <div className="flex flex-col gap-2 sm:gap-3">
            <form onSubmit={handleSearch} className="flex-1">
              <div className="relative">
                <Search className="absolute left-2.5 sm:left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 sm:w-5 sm:h-5 text-gray-400" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search by Shipment ID, Tracking #, Seller, or Product ID..."
                  className="w-full pl-7 sm:pl-10 pr-2.5 sm:pr-4 py-1.5 sm:py-2 border rounded-lg text-black bg-white focus:ring-2 focus:ring-purple-500 text-[11px] sm:text-sm placeholder-gray-500"
                />
              </div>
            </form>
            <div className="flex items-center gap-1.5 sm:gap-2">
              <Filter className="w-3.5 h-3.5 sm:w-5 sm:h-5 text-gray-400" />
              <select
                value={statusFilter}
                onChange={(e) => {
                  setStatusFilter(e.target.value)
                  setPage(1)
                }}
                className="border rounded-lg px-2 sm:px-3 py-1.5 sm:py-2 text-black bg-white focus:ring-2 focus:ring-purple-500 text-[11px] sm:text-sm"
                aria-label="Filter by shipment status"
              >
                <option value="">All</option>
                <option value="PENDING">Pending</option>
                <option value="IN_TRANSIT">In Transit</option>
                <option value="DELIVERED">Awaiting Receipt</option>
                <option value="RECEIVED">Received</option>
                <option value="DISCREPANCY">Discrepancy</option>
              </select>
            </div>
          </div>
        </div>

        {/* Shipments List */}
        {shipments.length === 0 ? (
          <div className="bg-white rounded-2xl shadow-sm p-6 sm:p-12 text-center">
            <Truck className="w-10 h-10 sm:w-16 sm:h-16 text-gray-300 mx-auto mb-2 sm:mb-4" />
            <h3 className="text-base sm:text-lg font-medium text-black mb-1 sm:mb-2">No shipments found</h3>
            <p className="text-[11px] sm:text-base text-black">
              {statusFilter || searchQuery
                ? 'Try adjusting your filters'
                : 'Shipments will appear here'}
            </p>
          </div>
        ) : (
          <div className="space-y-1.5 sm:space-y-4">
            {shipments.map((shipment) => {
              const statusConfig = STATUS_CONFIG[shipment.status] || STATUS_CONFIG.PENDING
              const StatusIcon = statusConfig.icon
              const needsAction = shipment.status === 'DELIVERED' || shipment.status === 'IN_TRANSIT' || (shipment.status === 'DISCREPANCY' && shipment.hasDiscrepancy)
              const product = shipment.products?.[0] || shipment.product
              
              if (!product) return null
              
              return (
                <div
                  key={shipment.id}
                  className={`bg-white rounded-lg shadow-sm overflow-hidden ${needsAction ? 'ring-2 ring-purple-200' : ''}`}
                >
                  <div className="p-1.5 sm:p-4 md:p-6">
                    <div className="flex flex-col sm:flex-row gap-1.5 sm:gap-4">
                      {/* Product Image */}
                      <div className="w-12 h-12 sm:w-20 sm:h-20 rounded-lg overflow-hidden bg-gray-200 flex-shrink-0 flex items-center justify-center">
                        {product.thumbnailUrl && product.thumbnailUrl.trim() ? (
                          <img
                            src={product.thumbnailUrl}
                            alt={product.title}
                            className="w-full h-full object-cover"
                            onError={(e) => {
                              (e.target as HTMLImageElement).style.display = 'none';
                            }}
                          />
                        ) : (
                          <Package className="w-7 h-7 sm:w-8 sm:h-8 text-gray-400" />
                        )}
                      </div>

                      {/* Shipment Info */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between gap-1 mb-0.5 sm:mb-2">
                          <div>
                            <h3 className="font-semibold text-black text-[10px] sm:text-base leading-tight">
                              {product.title}
                            </h3>
                            <p className="text-[9px] sm:text-sm text-black mt-0">
                              {formatCurrency(product.basePrice)}
                            </p>
                          </div>
                          <span className={`inline-flex items-center gap-0.5 px-1.5 sm:px-2.5 py-0.5 sm:py-1 rounded-full text-[9px] sm:text-xs font-medium ${statusConfig.bgColor} ${statusConfig.color} flex-shrink-0`}>
                            <StatusIcon className="w-2.5 h-2.5 sm:w-3 sm:h-3" />
                            <span className="hidden xs:inline">{statusConfig.label}</span>
                          </span>
                        </div>

                        <div className="grid grid-cols-2 sm:grid-cols-4 gap-0.5 sm:gap-3 text-[8px] sm:text-sm">
                          <div>
                            <p className="text-black font-semibold text-[7px] sm:text-xs">Seller</p>
                            <p className="text-black flex items-center gap-0.5 truncate mt-0 text-[7.5px] sm:text-xs">
                              <User className="w-3 h-3 flex-shrink-0" />
                              <span className="truncate text-[7.5px] sm:text-xs">{shipment.seller.name}</span>
                            </p>
                          </div>
                          <div>
                            <p className="text-black font-semibold text-[7px] sm:text-xs">Courier</p>
                            <p className="text-black text-[7.5px] sm:text-xs mt-0">{shipment.courier}</p>
                          </div>
                          <div>
                            <p className="text-black font-semibold text-[7px] sm:text-xs">Tracking</p>
                            <p className="font-mono text-black text-[7px] sm:text-xs mt-0">{shipment.trackingNumber}</p>
                          </div>
                          <div>
                            <p className="text-black font-semibold text-[7px] sm:text-xs">ETA</p>
                            <p className="text-black flex items-center gap-0.5 mt-0 text-[7.5px] sm:text-xs">
                              <Calendar className="w-2.5 h-2.5 sm:w-3 sm:h-3" />
                              {shipment.shippedAt ? formatDate(new Date(new Date(shipment.shippedAt).getTime() + 7 * 24 * 60 * 60 * 1000).toISOString()) : 'N/A'}
                            </p>
                          </div>
                        </div>

                        {/* Discrepancy Info */}
                        {shipment.hasDiscrepancy && (
                          <div className="mt-0.5 sm:mt-2 p-0.5 sm:p-3 bg-orange-50 rounded-lg">
                            <p className="text-[7.5px] sm:text-sm text-black font-medium">
                              <AlertTriangle className="w-3 h-3 inline mr-0.5" />
                              Discrepancy: {shipment.itemsMissing} missing, {shipment.itemsDamaged} damaged
                            </p>
                          </div>
                        )}

                        {/* Actions */}
                        <div className="mt-1 sm:mt-3 flex gap-1 sm:gap-2 flex-wrap">
                          {(shipment.status === 'IN_TRANSIT' || shipment.status === 'DELIVERED') && !shipment.hasDiscrepancy && (
                            <button
                              onClick={() => openReceiveModal(shipment)}
                              className="flex items-center gap-1 sm:gap-2 bg-purple-600 text-white px-2 sm:px-4 py-0.5 sm:py-1.5 rounded-lg text-[8px] sm:text-sm font-medium hover:bg-purple-700 transition"
                            >
                              <CheckCircle className="w-3 h-3" />
                              <span>Confirm</span>
                            </button>
                          )}
                          {shipment.hasDiscrepancy && shipment.status !== 'RECEIVED' && (
                            <button
                              onClick={() => confirmReceiptWithDiscrepancy(shipment.id)}
                              className="flex items-center gap-1 sm:gap-2 bg-green-600 text-white px-2 sm:px-4 py-0.5 sm:py-1.5 rounded-lg text-[8px] sm:text-sm font-medium hover:bg-green-700 transition"
                            >
                              <CheckCircle className="w-3 h-3" />
                              <span>Confirm (with discrepancy)</span>
                            </button>
                          )}
                          <Link
                            href={`/admin/boutique/shipments/${shipment.id}`}
                            className="flex items-center gap-1 sm:gap-2 border border-gray-200 px-2 sm:px-4 py-0.5 sm:py-1.5 rounded-lg text-[8px] sm:text-sm font-medium text-black hover:bg-gray-50 transition"
                          >
                            <Eye className="w-3 h-3" />
                            <span>Details</span>
                          </Link>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="mt-6 sm:mt-8 flex items-center justify-center gap-3 sm:gap-4">
            <button
              onClick={() => setPage(p => Math.max(1, p - 1))}
              disabled={page === 1}
              className="px-3 sm:px-4 py-2 border rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
              aria-label="Previous page"
            >
              <ChevronLeft className="w-4 h-4 sm:w-5 sm:h-5" />
            </button>
            <span className="text-xs sm:text-base text-gray-600">Page {page} of {totalPages}</span>
            <button
              onClick={() => setPage(p => Math.min(totalPages, p + 1))}
              disabled={page === totalPages}
              className="px-3 sm:px-4 py-2 border rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
              aria-label="Next page"
            >
              <ChevronRight className="w-4 h-4 sm:w-5 sm:h-5" />
            </button>
          </div>
        )}
      </div>

      {/* Receive Modal */}
      {showReceiveModal && selectedShipment && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-3 sm:p-4">
          <div className="bg-white rounded-xl sm:rounded-2xl shadow-xl max-w-lg w-full max-h-[90vh] overflow-y-auto">
            <div className="p-4 sm:p-6 border-b">
              <h2 className="text-base sm:text-xl font-bold text-gray-900">Confirm Receipt</h2>
              <p className="text-xs sm:text-base text-gray-600 mt-0.5 sm:mt-1 truncate">
                {selectedShipment.product?.title || 'Product'}
              </p>
            </div>
            
            <div className="p-4 sm:p-6 space-y-3 sm:space-y-4">
              <div className="bg-gray-50 p-3 sm:p-4 rounded-lg">
                <p className="text-[10px] sm:text-sm text-gray-600">Expected Items</p>
                <p className="text-xl sm:text-2xl font-bold text-gray-900">{selectedShipment.itemsExpected}</p>
              </div>

              <div className="grid grid-cols-3 gap-2 sm:gap-4">
                <div>
                  <label htmlFor="itemsReceived" className="block text-[10px] sm:text-sm font-medium text-gray-700 mb-1">
                    Received
                  </label>
                  <input
                    id="itemsReceived"
                    type="number"
                    value={receiveForm.itemsReceived}
                    onChange={(e) => setReceiveForm({ ...receiveForm, itemsReceived: parseInt(e.target.value) || 0 })}
                    min={0}
                    className="w-full px-2 sm:px-3 py-2 border rounded-lg text-gray-900 focus:ring-2 focus:ring-purple-500 text-sm"
                  />
                </div>
                <div>
                  <label htmlFor="itemsMissing" className="block text-[10px] sm:text-sm font-medium text-gray-700 mb-1">
                    Missing
                  </label>
                  <input
                    id="itemsMissing"
                    type="number"
                    value={receiveForm.itemsMissing}
                    onChange={(e) => setReceiveForm({ ...receiveForm, itemsMissing: parseInt(e.target.value) || 0 })}
                    min={0}
                    className="w-full px-2 sm:px-3 py-2 border rounded-lg text-gray-900 focus:ring-2 focus:ring-purple-500 text-sm"
                  />
                </div>
                <div>
                  <label htmlFor="itemsDamaged" className="block text-[10px] sm:text-sm font-medium text-gray-700 mb-1">
                    Damaged
                  </label>
                  <input
                    id="itemsDamaged"
                    type="number"
                    value={receiveForm.itemsDamaged}
                    onChange={(e) => setReceiveForm({ ...receiveForm, itemsDamaged: parseInt(e.target.value) || 0 })}
                    min={0}
                    className="w-full px-2 sm:px-3 py-2 border rounded-lg text-gray-900 focus:ring-2 focus:ring-purple-500 text-sm"
                  />
                </div>
              </div>

              {(receiveForm.itemsMissing > 0 || receiveForm.itemsDamaged > 0) && (
                <div className="p-2 sm:p-3 bg-orange-50 rounded-lg">
                  <p className="text-[10px] sm:text-sm text-orange-800 flex items-center gap-1 sm:gap-2">
                    <AlertTriangle className="w-3 h-3 sm:w-4 sm:h-4" />
                    This will flag as discrepancy
                  </p>
                </div>
              )}

              <div>
                <label className="block text-[10px] sm:text-sm font-medium text-gray-700 mb-1">
                  Notes
                </label>
                <textarea
                  value={receiveForm.notes}
                  onChange={(e) => setReceiveForm({ ...receiveForm, notes: e.target.value })}
                  rows={3}
                  placeholder="Notes about condition..."
                  className="w-full px-2 sm:px-3 py-2 border rounded-lg text-gray-900 focus:ring-2 focus:ring-purple-500 text-sm"
                />
              </div>

              <div className="flex gap-2 sm:gap-3 pt-2 sm:pt-4">
                <button
                  onClick={() => setShowReceiveModal(false)}
                  className="flex-1 px-3 sm:px-4 py-2 border rounded-lg text-gray-700 hover:bg-gray-50 transition text-sm"
                >
                  Cancel
                </button>
                <button
                  onClick={confirmReceipt}
                  className="flex-1 px-3 sm:px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition text-sm"
                >
                  Confirm
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useCallback, useEffect, useState } from 'react'
import { toast } from 'react-hot-toast'
import { Check, X, Truck } from 'lucide-react'

interface ShipmentProduct {
  id: string
  title: string
  warehouseReceivedAt: string | null
}

interface Seller {
  id: string
  email: string
  name: string | null
}

interface Shipment {
  id: string
  productIds: string[]
  status: string
  createdAt: string
  itemsExpected: number
  products: ShipmentProduct[]
  seller: Seller
}

interface ReturnRequest {
  shipment: Shipment
  daysInWarehouse: number
  adminFeePerVariant: number
  isAutoReturn: boolean
}

export default function WarehouseReturnsPage() {
  const [requests, setRequests] = useState<ReturnRequest[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [filterStatus, setFilterStatus] = useState('PENDING_ADMIN_REVIEW')

  const [approvingProductId, setApprovingProductId] = useState<string | null>(null)
  const [approveNotes, setApproveNotes] = useState('')
  const [approving, setApproving] = useState(false)

  const [rejectingProductId, setRejectingProductId] = useState<string | null>(null)
  const [rejectReason, setRejectReason] = useState('')
  const [rejecting, setRejecting] = useState(false)

  const [shippingProductId, setShippingProductId] = useState<string | null>(null)
  const [trackingNumber, setTrackingNumber] = useState('')
  const [carrier, setCarrier] = useState('')
  const [estimatedDelivery, setEstimatedDelivery] = useState('')
  const [shipping, setShipping] = useState(false)
  const [confirming, setConfirming] = useState(false)
  const [confirmingProductId, setConfirmingProductId] = useState<string | null>(null)

  // Store product IDs array for batch operations
  const [currentShipmentProductIds, setCurrentShipmentProductIds] = useState<string[]>([])

  const fetchRequests = useCallback(async () => {
    try {
      setIsLoading(true)
      const res = await fetch('/api/boutique/admin/warehouse-returns-pending')
      if (!res.ok) throw new Error('Failed to fetch returns')
      const data = await res.json()
      setRequests(data.requests || [])
    } catch (error) {
      console.error('Fetch error:', error)
      toast.error('Failed to load warehouse returns')
    } finally {
      setIsLoading(false)
    }
  }, [])

  useEffect(() => {
    fetchRequests()
  }, [fetchRequests])

  const handleApprove = async (productIds: string[]) => {
    try {
      setApproving(true)
      
      // Approve all products in shipment
      const results = await Promise.allSettled(
        productIds.map(productId =>
          fetch('/api/boutique/admin/approve-return', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ productId, notes: approveNotes })
          })
        )
      )

      // Check for failures
      const failures: string[] = []
      for (let i = 0; i < results.length; i++) {
        const result = results[i]
        if (result.status === 'rejected') {
          failures.push(`Product ${i + 1}: ${result.reason}`)
        } else {
          const res = result.value
          if (!res.ok) {
            const err = await res.json()
            failures.push(`Product ${i + 1}: ${err.error || 'Failed to approve'}`)
          }
        }
      }

      if (failures.length > 0) {
        throw new Error(failures.join('; '))
      }

      toast.success('Return approved. Seller notified.')
      setApprovingProductId(null)
      setApproveNotes('')
      await fetchRequests()
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Failed to approve')
    } finally {
      setApproving(false)
    }
  }

  const handleReject = async (productIds: string[]) => {
    if (!rejectReason.trim()) {
      toast.error('Please provide a rejection reason')
      return
    }

    try {
      setRejecting(true)
      
      // Reject all products in shipment
      const results = await Promise.allSettled(
        productIds.map(productId =>
          fetch('/api/boutique/admin/reject-return', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ productId, reason: rejectReason })
          })
        )
      )

      // Check for failures
      const failures: string[] = []
      for (let i = 0; i < results.length; i++) {
        const result = results[i]
        if (result.status === 'rejected') {
          failures.push(`Product ${i + 1}: ${result.reason}`)
        } else {
          const res = result.value
          if (!res.ok) {
            const err = await res.json()
            failures.push(`Product ${i + 1}: ${err.error || 'Failed to reject'}`)
          }
        }
      }

      if (failures.length > 0) {
        throw new Error(failures.join('; '))
      }

      toast.success('Return rejected. Seller notified.')
      setRejectingProductId(null)
      setRejectReason('')
      await fetchRequests()
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Failed to reject')
    } finally {
      setRejecting(false)
    }
  }

  const handleShip = async (productIds: string[]) => {
    try {
      setShipping(true)
      
      // Ship all products in shipment
      const results = await Promise.allSettled(
        productIds.map(productId =>
          fetch('/api/boutique/admin/ship-return', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              productId,
              trackingNumber: trackingNumber || undefined,
              carrier: carrier || undefined,
              estimatedDelivery: estimatedDelivery || undefined
            })
          })
        )
      )

      // Check for failures
      const failures: string[] = []
      for (let i = 0; i < results.length; i++) {
        const result = results[i]
        if (result.status === 'rejected') {
          failures.push(`Product ${i + 1}: ${result.reason}`)
        } else {
          const res = result.value
          if (!res.ok) {
            const err = await res.json()
            failures.push(`Product ${i + 1}: ${err.error || 'Failed to ship'}`)
          }
        }
      }

      if (failures.length > 0) {
        throw new Error(failures.join('; '))
      }

      toast.success('Return shipped. Seller notified.')
      setShippingProductId(null)
      setTrackingNumber('')
      setCarrier('')
      setEstimatedDelivery('')
      await fetchRequests()
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Failed to ship')
    } finally {
      setShipping(false)
    }
  }

  const handleConfirm = async (productIds: string[]) => {
    try {
      setConfirming(true)
      
      // Confirm all products in shipment
      const results = await Promise.allSettled(
        productIds.map(productId =>
          fetch(`/api/boutique/admin/returned/${productId}/confirm`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({})
          })
        )
      )

      // Check for failures
      const failures: string[] = []
      for (let i = 0; i < results.length; i++) {
        const result = results[i]
        if (result.status === 'rejected') {
          failures.push(`Product ${i + 1}: ${result.reason}`)
        } else {
          const res = result.value
          if (!res.ok) {
            const err = await res.json()
            failures.push(`Product ${i + 1}: ${err.message || 'Failed to confirm'}`)
          }
        }
      }

      if (failures.length > 0) {
        throw new Error(failures.join('; '))
      }

      toast.success('Return completed and confirmed.')
      setConfirmingProductId(null)
      await fetchRequests()
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Failed to confirm')
    } finally {
      setConfirming(false)
    }
  }

  const getStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      'PENDING_ADMIN_REVIEW': 'bg-yellow-100 text-yellow-800',
      'APPROVED_BY_ADMIN': 'bg-blue-100 text-blue-800',
      'SHIPPED_BY_ADMIN': 'bg-green-100 text-green-800',
      'RECEIVED_BY_SELLER': 'bg-purple-100 text-purple-800',
      'COMPLETED': 'bg-gray-100 text-gray-800',
      'CANCELLED': 'bg-red-100 text-red-800'
    }
    return colors[status] || 'bg-gray-100 text-gray-800'
  }

  const getStatusLabel = (status: string) =>
    status
      .split('_')
      .map(word => word.charAt(0) + word.slice(1).toLowerCase())
      .join(' ')

  const filtered = requests.filter(r => r.shipment.status === filterStatus)

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="mb-6">
        <h1 className="text-3xl font-bold text-black">Warehouse Returns</h1>
        <p className="text-gray-800 mt-2">Manage seller warehouse return requests and shipments</p>
      </div>

      {/* Status Filter */}
      <div className="flex gap-2 flex-wrap mb-6">
        {['PENDING_ADMIN_REVIEW', 'APPROVED_BY_ADMIN', 'SHIPPED_BY_ADMIN', 'RECEIVED_BY_SELLER', 'COMPLETED'].map(
          status => (
            <button
              key={status}
              onClick={() => setFilterStatus(status)}
              className={`px-4 py-2 rounded font-medium text-sm transition ${
                filterStatus === status
                  ? 'bg-blue-600 text-white'
                  : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
              }`}
            >
              {getStatusLabel(status)}
            </button>
          )
        )}
      </div>

      {/* Returns List */}
      <div className="space-y-4">
        {isLoading ? (
          <div className="bg-white rounded-lg p-6 text-center text-gray-800">
            Loading...
          </div>
        ) : filtered.length === 0 ? (
          <div className="bg-white rounded-lg p-6 text-center text-gray-800">
            No returns found for this status
          </div>
        ) : (
          filtered.map(request => (
            <div key={request.shipment.id} className="bg-white rounded-lg border border-gray-200 p-6">
              <div className="flex items-start justify-between gap-4 mb-4">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-2">
                    <div className="flex-1">
                      <h3 className="text-lg font-semibold text-black">{request.shipment.products.length} Item{request.shipment.products.length !== 1 ? 's' : ''} in Shipment</h3>
                      <div className="mt-1 text-sm text-gray-800">
                        {request.shipment.products.map(p => p.title).join(', ')}
                      </div>
                    </div>
                    <div className="flex flex-col items-end gap-2">
                      <span className={`px-3 py-1 rounded-full text-sm font-medium ${getStatusColor(request.shipment.status)}`}>
                        {getStatusLabel(request.shipment.status)}
                      </span>
                      {request.isAutoReturn && (
                        <span className="px-3 py-1 rounded-full text-sm font-medium bg-red-100 text-red-700 border border-red-300 flex items-center gap-1">
                          ≡ƒÅ¡ Warehouse Expiration
                        </span>
                      )}
                    </div>
                  </div>
                  <p className="text-sm text-gray-800 mt-2">
                    Seller: {request.shipment.seller.name || 'Unknown'} ({request.shipment.seller.email})
                  </p>
                </div>
              </div>

              {/* Fee Info */}
              <div className="bg-gradient-to-r from-amber-50 to-orange-50 p-4 rounded-lg border border-amber-200 mb-4">
                <div className="grid grid-cols-3 gap-4">
                  <div>
                    <p className="text-sm text-gray-800">Days in Warehouse</p>
                    <p className="text-2xl font-bold text-orange-600">{request.daysInWarehouse}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-800">Admin Fee</p>
                    <p className="text-2xl font-bold text-orange-600">{request.adminFeePerVariant} units</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-800">Items Expected</p>
                    <p className="text-2xl font-bold text-orange-600">{request.shipment.itemsExpected}</p>
                  </div>
                </div>
                <p className="text-xs text-gray-700 mt-3">
                  Fee: {request.daysInWarehouse <= 119 ? '2 units (Days 0-119)' : '1 unit (Days 120-180)'}
                </p>
              </div>

              {/* Actions */}
              <div className="space-y-3">
                {request.shipment.status === 'PENDING_ADMIN_REVIEW' && (
                  <>
                    {approvingProductId === request.shipment.productIds[0] && (
                      <div className="bg-gray-50 p-4 rounded-lg border border-gray-200">
                        <label className="block text-sm font-medium mb-2 text-gray-900">Optional Notes</label>
                        <textarea
                          placeholder="Add any notes about this approval..."
                          value={approveNotes}
                          onChange={e => setApproveNotes(e.target.value)}
                          className="w-full p-2 border rounded text-sm mb-3"
                          rows={3}
                        />
                        <div className="flex gap-2">
                          <button
                            onClick={() => {
                              setApprovingProductId(null)
                              setApproveNotes('')
                            }}
                            className="flex-1 px-3 py-2 bg-gray-200 hover:bg-gray-300 text-gray-800 font-medium rounded text-sm"
                          >
                            Cancel
                          </button>
                          <button
                            onClick={() => handleApprove(currentShipmentProductIds)}
                            disabled={approving}
                            className="flex-1 px-3 py-2 bg-green-600 hover:bg-green-700 disabled:bg-gray-400 text-white font-medium rounded text-sm flex items-center justify-center gap-2"
                          >
                            <Check size={14} />
                            {approving ? 'Approving...' : 'Confirm'}
                          </button>
                        </div>
                      </div>
                    )}

                    {rejectingProductId === request.shipment.productIds[0] && (
                      <div className="bg-gray-50 p-4 rounded-lg border border-gray-200">
                        <label className="block text-sm font-medium mb-2 text-gray-900">Rejection Reason *</label>
                        <textarea
                          placeholder="Why are you rejecting this return?"
                          value={rejectReason}
                          onChange={e => setRejectReason(e.target.value)}
                          className="w-full p-2 border rounded text-sm mb-3"
                          rows={3}
                        />
                        <div className="flex gap-2">
                          <button
                            onClick={() => {
                              setRejectingProductId(null)
                              setRejectReason('')
                            }}
                            className="flex-1 px-3 py-2 bg-gray-200 hover:bg-gray-300 text-gray-800 font-medium rounded text-sm"
                          >
                            Cancel
                          </button>
                          <button
                            onClick={() => handleReject(currentShipmentProductIds)}
                            disabled={rejecting || !rejectReason.trim()}
                            className="flex-1 px-3 py-2 bg-red-600 hover:bg-red-700 disabled:bg-gray-400 text-white font-medium rounded text-sm flex items-center justify-center gap-2"
                          >
                            <X size={14} />
                            {rejecting ? 'Rejecting...' : 'Confirm'}
                          </button>
                        </div>
                      </div>
                    )}

                    {approvingProductId !== request.shipment.productIds[0] && rejectingProductId !== request.shipment.productIds[0] && (
                      <div className="flex gap-2">
                        <button
                          onClick={() => {
                            setCurrentShipmentProductIds(request.shipment.productIds)
                            setApprovingProductId(request.shipment.productIds[0])
                          }}
                          className="flex-1 px-4 py-2 bg-green-600 hover:bg-green-700 text-white font-medium rounded flex items-center justify-center gap-2"
                          disabled={approving}
                        >
                          <Check size={16} />
                          Approve
                        </button>
                        <button
                          onClick={() => {
                            setCurrentShipmentProductIds(request.shipment.productIds)
                            setRejectingProductId(request.shipment.productIds[0])
                          }}
                          className="flex-1 px-4 py-2 bg-red-600 hover:bg-red-700 text-white font-medium rounded flex items-center justify-center gap-2"
                          disabled={rejecting}
                        >
                          <X size={16} />
                          Reject
                        </button>
                      </div>
                    )}
                  </>
                )}

                {request.shipment.status === 'APPROVED_BY_ADMIN' && (
                  <>
                    {shippingProductId === request.shipment.productIds[0] && (
                      <div className="bg-gray-50 p-4 rounded-lg border border-gray-200">
                        <label className="block text-sm font-medium mb-2 text-gray-900">Carrier (Optional)</label>
                        <input
                          type="text"
                          placeholder="e.g., DHL, FedEx, UPS"
                          value={carrier}
                          onChange={e => setCarrier(e.target.value)}
                          className="w-full p-2 border rounded text-sm mb-3"
                        />
                        <label className="block text-sm font-medium mb-2 text-gray-900">Tracking Number (Optional)</label>
                        <input
                          type="text"
                          placeholder="e.g., 1234567890"
                          value={trackingNumber}
                          onChange={e => setTrackingNumber(e.target.value)}
                          className="w-full p-2 border rounded text-sm mb-3"
                        />
                        <label className="block text-sm font-medium mb-2 text-gray-900">Estimated Delivery (Optional)</label>
                        <input
                          type="date"
                          value={estimatedDelivery}
                          onChange={e => setEstimatedDelivery(e.target.value)}
                          className="w-full p-2 border rounded text-sm mb-3"
                        />
                        <div className="flex gap-2">
                          <button
                            onClick={() => {
                              setShippingProductId(null)
                              setTrackingNumber('')
                              setCarrier('')
                              setEstimatedDelivery('')
                            }}
                            className="flex-1 px-3 py-2 bg-gray-200 hover:bg-gray-300 text-gray-800 font-medium rounded text-sm"
                          >
                            Cancel
                          </button>
                          <button
                            onClick={() => handleShip(currentShipmentProductIds)}
                            disabled={shipping}
                            className="flex-1 px-3 py-2 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white font-medium rounded text-sm flex items-center justify-center gap-2"
                          >
                            <Truck size={14} />
                            {shipping ? 'Shipping...' : 'Confirm'}
                          </button>
                        </div>
                      </div>
                    )}

                    {shippingProductId !== request.shipment.productIds[0] && (
                      <button
                        onClick={() => {
                          setCurrentShipmentProductIds(request.shipment.productIds)
                          setShippingProductId(request.shipment.productIds[0])
                        }}
                        className="w-full px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded flex items-center justify-center gap-2"
                        disabled={shipping}
                      >
                        <Truck size={16} />
                        Ship Return
                      </button>
                    )}
                  </>
                )}

                {request.shipment.status === 'RECEIVED_BY_SELLER' && (
                  <button
                    onClick={() => handleConfirm(request.shipment.productIds)}
                    disabled={confirming}
                    className="w-full px-4 py-2 bg-purple-600 hover:bg-purple-700 disabled:bg-gray-400 text-white font-medium rounded flex items-center justify-center gap-2"
                  >
                    <Check size={16} />
                    {confirming ? 'Confirming...' : 'Confirm Complete'}
                  </button>
                )}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import toast from 'react-hot-toast'
import { AlertCircle, Check, X } from 'lucide-react'

interface ContentViolation {
  id: string
  userId: string
  user: {
    id: string
    name: string | null
    email: string
  }
  violationType: string
  description: string
  severity: 'low' | 'medium' | 'high' | 'critical'
  reviewed: boolean
  action: string | null
  reviewedAt: string | null
  reviewedBy: string | null
  createdAt: string
}

export default function AdminContentViolationsPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [violations, setViolations] = useState<ContentViolation[]>([])
  const [loading, setLoading] = useState(true)
  const [statusFilter, setStatusFilter] = useState<'all' | 'pending' | 'reviewed'>('pending')

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/api/auth/signin')
      return
    }
    if (session?.user?.role !== 'ADMIN') {
      router.push('/')
      return
    }
    fetchViolations()
  }, [session, status, statusFilter])

  const fetchViolations = async () => {
    try {
      setLoading(true)
      const res = await fetch(`/api/admin/content-violations?status=${statusFilter}`)
      if (!res.ok) throw new Error('Failed to fetch violations')
      const data = await res.json()
      setViolations(data.violations || [])
    } catch (error) {
      console.error('Fetch error:', error)
      toast.error('Failed to load violations')
    } finally {
      setLoading(false)
    }
  }

  const handleReview = async (violationId: string, action: string) => {
    try {
      const res = await fetch(`/api/admin/content-violations/${violationId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action })
      })
      if (!res.ok) throw new Error('Failed to update violation')
      toast.success('Violation reviewed')
      fetchViolations()
    } catch (error) {
      console.error('Error:', error)
      toast.error('Failed to review violation')
    }
  }

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'critical':
        return 'bg-red-100 border-red-300 text-red-900'
      case 'high':
        return 'bg-orange-100 border-orange-300 text-orange-900'
      case 'medium':
        return 'bg-yellow-100 border-yellow-300 text-yellow-900'
      case 'low':
        return 'bg-blue-100 border-blue-300 text-blue-900'
      default:
        return 'bg-gray-100 border-gray-300 text-gray-900'
    }
  }

  if (status === 'loading' || loading) {
    return <div className="p-6 text-center">Loading...</div>
  }

  return (
    <div className="min-h-screen bg-gray-50 py-6 px-4 sm:px-6 lg:px-8">
      <div className="max-w-6xl mx-auto">
        <div className="bg-white rounded-lg shadow-sm">
          <div className="px-4 sm:px-6 py-4 sm:py-6 border-b border-gray-200">
            <div className="flex items-center gap-3 mb-4">
              <AlertCircle className="h-6 w-6 text-red-600" />
              <h1 className="text-2xl font-bold text-gray-900">Content Violations</h1>
            </div>
            <p className="text-sm text-gray-600">Review and manage user content violations</p>
          </div>

          {/* Filter */}
          <div className="px-4 sm:px-6 py-4 border-b border-gray-200">
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value as 'all' | 'pending' | 'reviewed')}
              className="px-3 py-2 border border-gray-300 rounded-lg text-sm text-gray-900"
            >
              <option value="pending">Pending Review</option>
              <option value="reviewed">Reviewed</option>
              <option value="all">All</option>
            </select>
          </div>

          {/* Violations List */}
          <div className="overflow-x-auto">
            {violations.length === 0 ? (
              <div className="text-center py-12">
                <p className="text-gray-500">No violations found</p>
              </div>
            ) : (
              <table className="w-full">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="px-4 sm:px-6 py-3 text-left text-xs font-medium text-gray-700">User</th>
                    <th className="px-4 sm:px-6 py-3 text-left text-xs font-medium text-gray-700">Violation Type</th>
                    <th className="px-4 sm:px-6 py-3 text-left text-xs font-medium text-gray-700">Severity</th>
                    <th className="px-4 sm:px-6 py-3 text-left text-xs font-medium text-gray-700">Status</th>
                    <th className="px-4 sm:px-6 py-3 text-left text-xs font-medium text-gray-700">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {violations.map((violation) => (
                    <tr key={violation.id} className="hover:bg-gray-50">
                      <td className="px-4 sm:px-6 py-4 text-sm text-gray-900">
                        <p className="font-medium">{violation.user?.name || 'Unknown User'}</p>
                        <p className="text-xs text-gray-500">{violation.user?.email || 'No email'}</p>
                      </td>
                      <td className="px-4 sm:px-6 py-4 text-sm text-gray-900">
                        <div>
                          <p className="font-medium">{violation.violationType}</p>
                          <p className="text-xs text-gray-500 mt-1">{violation.description}</p>
                        </div>
                      </td>
                      <td className="px-4 sm:px-6 py-4 text-sm">
                        <span className={`px-2 py-1 rounded text-xs font-medium border ${getSeverityColor(violation.severity || 'MEDIUM')}`}>
                          {(violation.severity || 'MEDIUM').toUpperCase()}
                        </span>
                      </td>
                      <td className="px-4 sm:px-6 py-4 text-sm">
                        <span className={`px-2 py-1 rounded text-xs font-medium border ${
                          violation.reviewed
                            ? 'bg-green-100 border-green-300 text-green-900'
                            : 'bg-yellow-100 border-yellow-300 text-yellow-900'
                        }`}>
                          {violation.reviewed ? 'REVIEWED' : 'PENDING'}
                        </span>
                      </td>
                      <td className="px-4 sm:px-6 py-4 text-sm">
                        {!violation.reviewed && (
                          <div className="flex gap-2">
                            <button
                              onClick={() => handleReview(violation.id, 'WARNED')}
                              className="p-1 text-yellow-600 hover:bg-yellow-50 rounded"
                              title="Issue warning"
                            >
                              <AlertCircle className="h-4 w-4" />
                            </button>
                            <button
                              onClick={() => handleReview(violation.id, 'SUSPENDED')}
                              className="p-1 text-red-600 hover:bg-red-50 rounded"
                              title="Suspend user"
                            >
                              <X className="h-4 w-4" />
                            </button>
                            <button
                              onClick={() => handleReview(violation.id, 'RESOLVED')}
                              className="p-1 text-green-600 hover:bg-green-50 rounded"
                              title="Mark resolved"
                            >
                              <Check className="h-4 w-4" />
                            </button>
                          </div>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import _Link from 'next/link'
import { Download, FileText, Eye, Copy, Check, Plus, _Trash2, Archive, CheckCircle } from 'lucide-react'
import toast from 'react-hot-toast'

interface DocumentInfo {
  id: 'moa' | 'aoa' | 'shareholder_agreement' | 'employment_contract'
  title: string
  description: string
  longDescription: string
  icon: React.ReactNode
  importance: 'critical' | 'important' | 'reference'
}

interface DocumentVersion {
  id: string
  documentType: string
  documentName: string
  versionNumber: number
  status: string
  approvalStatus: string
  createdAt: string
  createdBy: { id: string; email: string; name: string | null }
  approvedAt?: string | null
  downloads: number
  lastAccessedAt?: string | null
}

const DOCUMENTS: DocumentInfo[] = [
  {
    id: 'moa',
    title: 'Memorandum of Association',
    description: 'Defines the company\'s name, objects, and authorized capital',
    longDescription: 'The Memorandum of Association (MOA) is the founding document of your company. It specifies your company\'s name, primary objectives, authorized share capital, and liability of members. This document is essential for company registration and defines the external constitution of your company.',
    icon: <FileText className="w-6 h-6" />,
    importance: 'critical'
  },
  {
    id: 'aoa',
    title: 'Articles of Association',
    description: 'Governs internal management, shares, and operations',
    longDescription: 'The Articles of Association (AOA) is the internal constitution of your company. It covers share capital, member rights, general meetings, board of directors, staff employment, financial management, and operational procedures. This document provides the framework for how your company operates.',
    icon: <FileText className="w-6 h-6" />,
    importance: 'critical'
  },
  {
    id: 'shareholder_agreement',
    title: 'Shareholder Agreement',
    description: 'Governs share transfers, investor protections, and dispute resolution',
    longDescription: 'The Shareholder Agreement is a comprehensive contract between shareholders covering share transfers, voting rights, drag-along/tag-along rights, deadlock resolution, valuation mechanisms, and future partnerships. Essential for protecting shareholder interests and managing ownership transitions.',
    icon: <FileText className="w-6 h-6" />,
    importance: 'important'
  },
  {
    id: 'employment_contract',
    title: 'Employment Contract Template',
    description: 'Template for employment agreements with all legal requirements',
    longDescription: 'Professional employment contract template covering compensation, benefits, working hours, leave entitlements, confidentiality, intellectual property, termination procedures, and statutory compliance. Customizable for different employee roles and requirements.',
    icon: <FileText className="w-6 h-6" />,
    importance: 'important'
  }
]

export default function DocumentsPage() {
  const [copied, setCopied] = useState<string | null>(null)
  const [downloading, setDownloading] = useState<string | null>(null)
  const [versions, setVersions] = useState<DocumentVersion[]>([])
  const [loadingVersions, setLoadingVersions] = useState(false)
  const [selectedDocType, setSelectedDocType] = useState<string | null>(null)

  // Fetch document versions on component mount
  useEffect(() => {
    fetchVersions()
  }, [])

  const fetchVersions = async () => {
    setLoadingVersions(true)
    try {
      const response = await fetch('/api/admin/documents')
      if (response.ok) {
        const data = await response.json()
        setVersions(data.versions || [])
      }
    } catch (error) {
      console.error('Error fetching versions:', error)
    } finally {
      setLoadingVersions(false)
    }
  }

  const createNewVersion = async (docType: string) => {
    try {
      const response = await fetch('/api/admin/documents', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          documentType: docType,
          notes: `Created new version of ${docType}`
        })
      })
      if (response.ok) {
        const data = await response.json()
        toast.success(data.message)
        fetchVersions()
      } else {
        toast.error('Failed to create version')
      }
    } catch (error) {
      console.error('Error creating version:', error)
      toast.error('Error creating version')
    }
  }

  const approveVersion = async (versionId: string) => {
    try {
      const response = await fetch('/api/admin/documents', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          versionId,
          action: 'approve'
        })
      })
      if (response.ok) {
        toast.success('Version approved')
        fetchVersions()
      } else {
        toast.error('Failed to approve version')
      }
    } catch (error) {
      console.error('Error approving version:', error)
      toast.error('Error approving version')
    }
  }

  const archiveVersion = async (versionId: string) => {
    try {
      const response = await fetch('/api/admin/documents', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: versionId })
      })
      if (response.ok) {
        toast.success('Version archived')
        fetchVersions()
      } else {
        toast.error('Failed to archive version')
      }
    } catch (error) {
      console.error('Error archiving version:', error)
      toast.error('Error archiving version')
    }
  }

  const handleDownload = async (type: 'moa' | 'aoa' | 'shareholder_agreement' | 'employment_contract', format: 'txt' | 'json' | 'html') => {
    setDownloading(`${type}-${format}`)
    try {
      const response = await fetch(`/api/documents/download?type=${type}&format=${format}`)
      
      if (!response.ok) {
        throw new Error('Download failed')
      }

      const blob = await response.blob()
      const url = window.URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      
      const fileNames: Record<string, string> = {
        'moa': 'Memorandum_of_Association',
        'aoa': 'Articles_of_Association',
        'shareholder_agreement': 'Shareholder_Agreement',
        'employment_contract': 'Employment_Contract'
      }
      
      const fileName = fileNames[type] || 'Document'
      a.download = `${fileName}_${new Date().toISOString().split('T')[0]}.${format}`
      document.body.appendChild(a)
      a.click()
      window.URL.revokeObjectURL(url)
      document.body.removeChild(a)
      
      toast.success(`Downloaded as ${format.toUpperCase()}`)
    } catch (error) {
      console.error('Download error:', error)
      toast.error('Failed to download document')
    } finally {
      setDownloading(null)
    }
  }

  const handleView = (type: 'moa' | 'aoa' | 'shareholder_agreement' | 'employment_contract') => {
    window.open(`/api/documents/download?type=${type}&format=html`, '_blank')
  }

  const handleCopyInfo = (text: string) => {
    navigator.clipboard.writeText(text)
    setCopied(text)
    toast.success('Copied to clipboard!')
    setTimeout(() => setCopied(null), 2000)
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-white to-indigo-50">
      {/* Header */}
      <div className="bg-gradient-to-r from-indigo-600 via-purple-600 to-pink-600 text-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
          <div className="flex items-center gap-3 mb-4">
            <FileText className="w-8 h-8" />
            <h1 className="text-3xl sm:text-4xl font-bold">Company Documents</h1>
          </div>
          <p className="text-indigo-100 text-lg">
            Download and manage your company's foundational legal documents
          </p>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        {/* Important Notice */}
        <div className="mb-8 p-6 bg-amber-50 border-l-4 border-amber-500 rounded-lg">
          <h3 className="text-lg font-semibold text-amber-900 mb-2">ΓÜá∩╕Å Important Notice</h3>
          <p className="text-amber-800 mb-3">
            These documents are templates that must be customized with your specific information:
          </p>
          <ul className="text-amber-800 space-y-2 ml-4 list-disc">
            <li>Replace all [INSERT ...] placeholders with your actual company details</li>
            <li>Have all documents reviewed by a qualified attorney in your jurisdiction</li>
            <li>Ensure compliance with local company law and regulations</li>
            <li>Register the approved documents with your corporate authority</li>
            <li>Keep certified copies for your company records</li>
          </ul>
        </div>

        {/* Documents Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-12">
          {DOCUMENTS.map((doc) => (
            <div key={doc.id} className="bg-white rounded-xl shadow-lg hover:shadow-xl transition-shadow overflow-hidden">
              {/* Card Header */}
              <div className={`p-6 bg-gradient-to-r ${
                doc.importance === 'critical' 
                  ? 'from-red-500 to-pink-500' 
                  : 'from-blue-500 to-indigo-500'
              } text-white`}>
                <div className="flex items-center gap-3 mb-3">
                  {doc.icon}
                  <span className="px-2 py-1 bg-white/20 rounded text-xs font-semibold">
                    {doc.importance.toUpperCase()}
                  </span>
                </div>
                <h2 className="text-2xl font-bold mb-2">{doc.title}</h2>
                <p className="text-white/90">{doc.description}</p>
              </div>

              {/* Card Body */}
              <div className="p-6">
                <p className="text-gray-700 mb-6 leading-relaxed">
                  {doc.longDescription}
                </p>

                {/* Download Options */}
                <div className="mb-6">
                  <h4 className="font-semibold text-gray-900 mb-3">Download Options:</h4>
                  <div className="grid grid-cols-3 gap-2">
                    {['txt', 'json', 'html'].map((format) => (
                      <button
                        key={format}
                        onClick={() => handleDownload(doc.id, format as 'txt' | 'json' | 'html')}
                        disabled={downloading === `${doc.id}-${format}`}
                        className="flex items-center justify-center gap-1 px-3 py-2 bg-indigo-100 hover:bg-indigo-200 text-indigo-700 rounded-lg font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        <Download className="w-4 h-4" />
                        <span className="text-xs">{format.toUpperCase()}</span>
                      </button>
                    ))}
                  </div>
                </div>

                {/* Action Buttons */}
                <div className="flex gap-2">
                  <button
                    onClick={() => handleView(doc.id)}
                    className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-lg font-medium transition-colors"
                  >
                    <Eye className="w-4 h-4" />
                    View
                  </button>
                  <button
                    onClick={() => handleCopyInfo(doc.id)}
                    className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-lg font-medium transition-colors"
                  >
                    {copied === doc.id ? (
                      <>
                        <Check className="w-4 h-4" />
                        Copied
                      </>
                    ) : (
                      <>
                        <Copy className="w-4 h-4" />
                        Copy Link
                      </>
                    )}
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Instructions Section */}
        <div className="bg-white rounded-xl shadow-lg p-8">
          <h3 className="text-2xl font-bold text-gray-900 mb-6">How to Use These Documents</h3>
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div>
              <h4 className="text-lg font-semibold text-gray-900 mb-4">Step-by-Step Guide</h4>
              <ol className="space-y-4">
                {[
                  {
                    title: 'Download the Template',
                    desc: 'Download both the MOA and AOA in your preferred format (TXT, JSON, or HTML)'
                  },
                  {
                    title: 'Customize the Documents',
                    desc: 'Replace all [INSERT ...] placeholders with your actual company information'
                  },
                  {
                    title: 'Legal Review',
                    desc: 'Have the customized documents reviewed by a qualified attorney in your jurisdiction'
                  },
                  {
                    title: 'Board Approval',
                    desc: 'Get the documents approved by your board of directors or as an initial subscriber'
                  },
                  {
                    title: 'Registration',
                    desc: 'Submit the documents to your corporate authority for official registration'
                  },
                  {
                    title: 'Maintain Records',
                    desc: 'Keep certified copies in your company\'s official records'
                  }
                ].map((step, idx) => (
                  <div key={idx} className="flex gap-4">
                    <div className="flex-shrink-0">
                      <div className="flex items-center justify-center h-8 w-8 rounded-full bg-indigo-600 text-white font-bold text-sm">
                        {idx + 1}
                      </div>
                    </div>
                    <div>
                      <h5 className="font-semibold text-gray-900">{step.title}</h5>
                      <p className="text-gray-600 text-sm mt-1">{step.desc}</p>
                    </div>
                  </div>
                ))}
              </ol>
            </div>

            <div>
              <h4 className="text-lg font-semibold text-gray-900 mb-4">Key Sections Included</h4>
              <ul className="space-y-3">
                {[
                  { title: 'Company Details', items: ['Name, registered office, business objects'] },
                  { title: 'Share Capital', items: ['Authorized capital, share types, restrictions'] },
                  { title: 'Membership', items: ['Member rights, transfers, pre-emption rights'] },
                  { title: 'Governance', items: ['Directors, general meetings, voting rights'] },
                  { title: 'Staff Management', items: ['Employment authority, compensation policy'] },
                  { title: 'Financial Controls', items: ['Accounts, dividends, borrowing authority'] },
                  { title: 'Future Flexibility', items: ['Partnership terms, share valuation framework'] }
                ].map((section, idx) => (
                  <div key={idx} className="border-l-2 border-indigo-200 pl-4">
                    <h5 className="font-semibold text-gray-900">{section.title}</h5>
                    {section.items.map((item, i) => (
                      <p key={i} className="text-sm text-gray-600">{item}</p>
                    ))}
                  </div>
                ))}
              </ul>
            </div>
          </div>

          {/* Contact Info */}
          <div className="mt-8 p-6 bg-indigo-50 rounded-lg border border-indigo-200">
            <h4 className="font-semibold text-gray-900 mb-3">Professional Recommendation</h4>
            <p className="text-gray-700 mb-4">
              While these templates provide a solid foundation, it is <strong>strongly recommended</strong> that you consult 
              with a qualified corporate attorney in your jurisdiction to ensure these documents fully comply with local laws 
              and regulations specific to your business.
            </p>
            <p className="text-sm text-gray-600">
              The documents are customizable and include provisions for:
            </p>
            <ul className="text-sm text-gray-600 mt-2 ml-4 space-y-1 list-disc">
              <li>Current sole proprietorship management</li>
              <li>Future partnership or multi-shareholder scenarios</li>
              <li>Staff hiring and compensation frameworks</li>
              <li>Share transfer and valuation mechanisms</li>
              <li>Shareholder agreement provisions</li>
            </ul>
          </div>
        </div>

        {/* Document Versioning Section */}
        <div className="mt-12">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-2xl font-semibold text-gray-900">Document Versions & Management</h3>
            <div className="flex gap-2">
              {['MOA', 'AOA', 'SHAREHOLDER_AGREEMENT', 'EMPLOYMENT_CONTRACT'].map((type) => (
                <button
                  key={type}
                  onClick={() => createNewVersion(type)}
                  className="inline-flex items-center gap-1 px-3 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 text-sm font-medium"
                >
                  <Plus className="w-4 h-4" />
                  {type.replace(/_/g, ' ')}
                </button>
              ))}
            </div>
          </div>

          {loadingVersions ? (
            <div className="text-center py-8 text-gray-500">
              Loading versions...
            </div>
          ) : versions.length === 0 ? (
            <div className="bg-white rounded-lg border border-gray-200 p-8 text-center">
              <FileText className="w-12 h-12 mx-auto text-gray-400 mb-3" />
              <p className="text-gray-600">No document versions yet. Create one to get started.</p>
            </div>
          ) : (
            <div className="space-y-4">
              {versions.map((version) => (
                <div key={version.id} className="bg-white rounded-lg border border-gray-200 p-4">
                  <div className="flex items-center justify-between mb-3">
                    <div>
                      <h4 className="font-semibold text-gray-900">{version.documentName}</h4>
                      <p className="text-sm text-gray-600">Version {version.versionNumber} ΓÇó Created {new Date(version.createdAt).toLocaleDateString()}</p>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className={`inline-flex px-2 py-1 rounded-full text-xs font-medium ${
                        version.status === 'ACTIVE' ? 'bg-green-100 text-green-800' :
                        version.status === 'DRAFT' ? 'bg-yellow-100 text-yellow-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                        {version.status}
                      </span>
                      <span className={`inline-flex px-2 py-1 rounded-full text-xs font-medium ${
                        version.approvalStatus === 'APPROVED' ? 'bg-green-100 text-green-800' :
                        version.approvalStatus === 'PENDING' ? 'bg-blue-100 text-blue-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                        {version.approvalStatus}
                      </span>
                    </div>
                  </div>

                  <div className="text-sm text-gray-600 mb-4">
                    <p>Created by: {version.createdBy.name || version.createdBy.email}</p>
                    {version.approvedAt && <p>Approved: {new Date(version.approvedAt).toLocaleDateString()}</p>}
                    <p>Downloads: {version.downloads} ΓÇó Last accessed: {version.lastAccessedAt ? new Date(version.lastAccessedAt).toLocaleDateString() : 'Never'}</p>
                  </div>

                  <div className="flex gap-2">
                    {version.approvalStatus === 'PENDING' && (
                      <button
                        onClick={() => approveVersion(version.id)}
                        className="inline-flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 text-sm font-medium"
                      >
                        <CheckCircle className="w-4 h-4" />
                        Approve
                      </button>
                    )}
                    <button
                      onClick={() => archiveVersion(version.id)}
                      className="inline-flex items-center gap-1 px-3 py-1.5 bg-gray-600 text-white rounded hover:bg-gray-700 text-sm font-medium"
                    >
                      <Archive className="w-4 h-4" />
                      Archive
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Additional Resources */}
        <div className="mt-12 p-6 bg-blue-50 border border-blue-200 rounded-lg">
          <h3 className="text-lg font-semibold text-blue-900 mb-4">Additional Resources</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <h4 className="font-semibold text-blue-900 mb-2">What You'll Need to Prepare</h4>
              <ul className="text-sm text-blue-800 space-y-2 ml-4 list-disc">
                <li>Company registration number</li>
                <li>Registered office address</li>
                <li>Current ownership and shareholding details</li>
                <li>Director/officer information</li>
                <li>Business activities description</li>
              </ul>
            </div>
            <div>
              <h4 className="font-semibold text-blue-900 mb-2">File Format Guide</h4>
              <ul className="text-sm text-blue-800 space-y-2 ml-4 list-disc">
                <li><strong>TXT:</strong> Plain text, easy to edit in any editor</li>
                <li><strong>JSON:</strong> Structured data format, good for systems</li>
                <li><strong>HTML:</strong> Formatted for web viewing and printing</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import Image from 'next/image'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import toast from 'react-hot-toast'
import { useCurrency } from '@/components/CurrencyProvider'
import {
  Star,
  Trash2,
  Filter,
  Search,
  ChevronLeft,
  ChevronRight,
  Image as ImageIcon,
  ShoppingBag,
  DollarSign,
} from 'lucide-react'

interface FeaturedItem {
  id: string
  itemType: 'DESIGN' | 'BOUTIQUE_PRODUCT'
  itemId: string
  title: string
  imageUrl?: string
  price: number
  slug?: string
  seller: {
    id: string
    name?: string
    email: string
    subscriptionTier?: string
  }
  position: number
  addedAt: string
  addedByAdmin?: boolean
}

export default function AdminFeaturedItemsPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const { formatPrice } = useCurrency()

  const [items, setItems] = useState<FeaturedItem[]>([])
  const [loading, setLoading] = useState(true)
  const [pagination, setPagination] = useState({ page: 1, limit: 20, total: 0, pages: 0 })
  const [filters, setFilters] = useState({
    itemType: '',
    search: '',
    sort: 'addedAt',
    sortOrder: 'desc',
    priceSort: '',
    ownership: '',
    addedByAdmin: ''
  })
  const [showFilters, setShowFilters] = useState(true)
  const [deletingId, setDeletingId] = useState<string | null>(null)
  const [showAddModal, setShowAddModal] = useState(false)
  const [addingToFeatured, setAddingToFeatured] = useState(false)
  const [addSearchType, setAddSearchType] = useState<'DESIGN' | 'BOUTIQUE_PRODUCT'>('BOUTIQUE_PRODUCT')
  const [addSearchQuery, setAddSearchQuery] = useState('')
  const [addSearchResults, setAddSearchResults] = useState<any[]>([])
  const [addSearching, setAddSearching] = useState(false)
  const [addAllItems, setAddAllItems] = useState<any[]>([])
  const [addTopItems, setAddTopItems] = useState<any[]>([])
  const [addLoadingAll, setAddLoadingAll] = useState(false)

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/auth/signin')
    } else if (session?.user?.role !== 'ADMIN') {
      router.push('/')
    }
  }, [status, session?.user?.role, router])

  const fetchItems = useCallback(async () => {
    try {
      setLoading(true)
      const params = new URLSearchParams({
        page: pagination.page.toString(),
        limit: pagination.limit.toString(),
        sort: filters.sort,
        sortOrder: filters.sortOrder,
        ...(filters.itemType && { itemType: filters.itemType }),
        ...(filters.search && { search: filters.search }),
        ...(filters.priceSort && { priceSort: filters.priceSort }),
        ...(filters.ownership && { ownership: filters.ownership }),
        ...(filters.addedByAdmin && { addedByAdmin: filters.addedByAdmin }),
      })

      const res = await fetch(`/api/admin/featured-items?${params}`)
      if (!res.ok) throw new Error('Failed to fetch')

      const data = await res.json()
      setItems(data.items)
      setPagination(data.pagination)
    } catch (error) {
      console.error('Error fetching items:', error)
      toast.error('Failed to load featured items')
    } finally {
      setLoading(false)
    }
  }, [filters, pagination.page, pagination.limit])

  useEffect(() => {
    fetchItems()
  }, [fetchItems])

  const handleDelete = async (itemId: string, itemType: 'DESIGN' | 'BOUTIQUE_PRODUCT', addedByAdmin?: boolean) => {
    setDeletingId(itemId)
    
    try {
      const source = addedByAdmin ? 'ADMIN_FEATURED' : itemType
      const res = await fetch(`/api/admin/featured-items?id=${itemId}&itemType=${itemType}&source=${source}`, {
        method: 'DELETE'
      })

      if (!res.ok) throw new Error('Failed to delete')

      toast.success('Item removed from featured')
      fetchItems()
    } catch (error) {
      console.error('Error deleting item:', error)
      toast.error('Failed to remove item from featured')
    } finally {
      setDeletingId(null)
    }
  }

  const loadAllItemsToAdd = async (searchType: string = addSearchType) => {
    try {
      setAddLoadingAll(true)
      let results: any[] = []
      
      if (searchType === 'BOUTIQUE_PRODUCT') {
        // Fetch all live boutique products
        const productRes = await fetch(`/api/boutique/admin/products?status=LIVE&limit=100`)
        if (productRes.ok) {
          const data = await productRes.json()
          results = (data.products || []).map((item: any) => ({
            id: item.id,
            slug: item.slug,
            title: item.title,
            imageUrl: item.thumbnailUrl,
            price: item.basePrice || item.salePrice || 0,
            seller: {
              id: item.seller?.id || '',
              name: item.seller?.name || 'Unknown',
              email: item.seller?.email || '',
              subscriptionTier: item.seller?.subscriptionTier || 'Free'
            },
            itemType: 'BOUTIQUE_PRODUCT',
            sales: item.totalSales || 0,
            revenue: item.totalRevenue || 0
          }))
        }
      } else {
        // Fetch all designs
        const designRes = await fetch(`/api/admin/designs?limit=100`)
        if (designRes.ok) {
          const data = await designRes.json()
          results = (data.designs || []).map((item: any) => ({
            id: item.id,
            title: item.title,
            imageUrl: item.imageUrl,
            price: item.price || 0,
            seller: {
              id: item.designer?.id || '',
              name: item.designer?.name || 'Unknown',
              email: item.designer?.email || '',
              subscriptionTier: item.designer?.subscriptionTier || 'Free'
            },
            itemType: 'DESIGN',
            sales: item.sales || 0,
            rating: item.avgRating || 0,
            totalSales: item.totalSales || 0
          }))
        }
      }
      
      // Filter out items that are already featured
      const featuredIds = new Set(items
        .filter(item => item.itemType === addSearchType)
        .map(item => item.itemId))
      
      const filteredResults = results.filter(result => !featuredIds.has(result.id))
      setAddAllItems(filteredResults)
      setAddTopItems(filteredResults.slice(0, 5)) // Top 5
    } catch (error) {
      console.error('Error loading items:', error)
    } finally {
      setAddLoadingAll(false)
    }
  }

  const searchItemsToAdd = async (query: string, searchType: string = addSearchType) => {
    if (!query.trim()) {
      setAddSearchResults([])
      return
    }

    try {
      setAddSearching(true)
      let results: any[] = []

      if (searchType === 'BOUTIQUE_PRODUCT') {
        // Search live boutique products
        const res = await fetch(`/api/boutique/admin/products?search=${encodeURIComponent(query)}&status=LIVE&limit=50`)
        if (res.ok) {
          const data = await res.json()
          results = (data.products || []).map((item: any) => ({
            id: item.id,
            slug: item.slug,
            title: item.title,
            imageUrl: item.thumbnailUrl,
            price: item.basePrice || item.salePrice || 0,
            seller: {
              id: item.seller?.id || '',
              name: item.seller?.name || 'Unknown',
              email: item.seller?.email || '',
              subscriptionTier: item.seller?.subscriptionTier || 'Free'
            },
            itemType: 'BOUTIQUE_PRODUCT',
            sales: item.totalSales || 0,
            revenue: item.totalRevenue || 0
          }))
        }
      } else {
        // Search all designs
        const res = await fetch(`/api/admin/designs?search=${encodeURIComponent(query)}&limit=50`)
        if (res.ok) {
          const data = await res.json()
          results = (data.designs || []).map((item: any) => ({
            id: item.id,
            title: item.title,
            imageUrl: item.imageUrl,
            price: item.price || 0,
            seller: {
              id: item.designer?.id || '',
              name: item.designer?.name || 'Unknown',
              email: item.designer?.email || '',
              subscriptionTier: item.designer?.subscriptionTier || 'Free'
            },
            itemType: 'DESIGN',
            sales: item.sales || 0,
            rating: item.avgRating || 0,
            totalSales: item.totalSales || 0
          }))
        }
      }
      
      // Filter out items that are already featured
      const featuredIds = new Set(items
        .filter(item => item.itemType === addSearchType)
        .map(item => item.itemId))
      
      const filteredResults = results.filter(result => !featuredIds.has(result.id))
      setAddSearchResults(filteredResults)
    } catch (error) {
      console.error('Search error:', error)
      // Silently fail - user will see "No items found"
    } finally {
      setAddSearching(false)
    }
  }

  const addItemToFeatured = async (itemId: string) => {
    try {
      setAddingToFeatured(true)
      console.log('≡ƒƒí Adding to featured:', { itemType: addSearchType, itemId })
      
      const payload = {
        itemType: addSearchType === 'BOUTIQUE_PRODUCT' ? 'BOUTIQUE_PRODUCT' : 'DESIGN',
        itemId,
        reason: 'Admin curation'
      }
      console.log('Sending payload:', payload)
      
      const res = await fetch('/api/admin/featured-items', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      })

      console.log('Response status:', res.status)
      const resData = await res.json()
      console.log('Response data:', resData)

      if (!res.ok) {
        throw new Error(resData.error || 'Failed to add')
      }

      toast.success(`${addSearchType === 'DESIGN' ? 'Design' : 'Product'} added to featured`)
      setAddSearchResults(addSearchResults.filter(r => r.id !== itemId))
      setAddTopItems(addTopItems.filter(r => r.id !== itemId))
      setAddSearchQuery('')
      fetchItems()
    } catch (error) {
      console.error('Γ¥î Error adding to featured:', error)
      const errorMsg = error instanceof Error ? error.message : 'Failed to add item'
      toast.error(errorMsg)
      // Remove from results if it's a conflict
      if (errorMsg.includes('already featured')) {
        setAddSearchResults(addSearchResults.filter(r => r.id !== itemId))
        setAddTopItems(addTopItems.filter(r => r.id !== itemId))
      }
    } finally {
      setAddingToFeatured(false)
    }
  }

  const getTierBadge = (tier?: string) => {
    switch (tier) {
      case 'STARTER':
        return 'bg-blue-100 text-blue-800'
      case 'PRO':
        return 'bg-purple-100 text-purple-800'
      case 'VIP':
        return 'bg-amber-100 text-amber-800'
      default:
        return 'bg-gray-100 text-gray-800'
    }
  }

  if (status === 'loading') return <div className="p-8">Loading...</div>
  if (status === 'unauthenticated' || session?.user?.role !== 'ADMIN') return null

  return (
    <div className="min-h-screen bg-gray-50 p-2 sm:p-3 md:p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-2 sm:mb-3">
          <div className="flex items-center justify-between gap-2 sm:gap-3 mb-1.5 sm:mb-2">
            <div className="min-w-0">
              <h1 className="text-base sm:text-xl md:text-2xl font-bold text-gray-900">Featured Items</h1>
              <p className="text-[11px] sm:text-xs text-gray-600 mt-0.5">Manage promoted items</p>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={() => {
                  setShowAddModal(true)
                  loadAllItemsToAdd()
                }}
                className="px-3 py-1.5 sm:px-4 sm:py-2 bg-purple-600 hover:bg-purple-700 text-white text-[10px] sm:text-sm font-medium rounded-lg transition-colors"
                title="Add item to featured"
              >
                + Add Item
              </button>
              <div className="text-right flex-shrink-0">
                <div className="text-lg sm:text-2xl font-bold text-gray-900">{pagination.total}</div>
                <div className="text-[9px] sm:text-xs text-gray-600">items</div>
              </div>
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow mb-2 sm:mb-3 p-2 sm:p-3">
