                        addSearchType === 'BOUTIQUE_PRODUCT'
                          ? 'bg-purple-600 text-white'
                          : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                      }`}
                    >
                      ≡ƒæù Products
                    </button>
                    <button
                      onClick={() => {
                        setAddSearchType('DESIGN')
                        setAddSearchResults([])
                        setAddSearchQuery('')
                        loadAllItemsToAdd('DESIGN')
