                                  onClick={() => {
                                    if (item.itemType === 'BOUTIQUE_PRODUCT') {
                                      window.open(`/boutique/${item.slug}`, '_blank')
                                    } else {
                                      window.open(`/design/${item.id}`, '_blank')
                                    }
                                  }}
                                  className="w-full text-left p-3 hover:bg-gray-50 flex items-start gap-3"
