                                  <button
                                    onClick={() => addItemToFeatured(item.id)}
                                    disabled={addingToFeatured}
                                    className="w-full px-3 py-1.5 bg-purple-600 hover:bg-purple-700 text-white text-sm font-medium rounded-lg transition-colors disabled:opacity-50"
                                  >
                                    Add to Featured
                                  </button>
                                </div>
                              </div>
                            ))}
                          </div>
                          {addAllItems.length > 5 && (
                            <p className="text-xs text-gray-600 mt-3 text-center">Showing top 5 of {addAllItems.length} {addSearchType === 'BOUTIQUE_PRODUCT' ? 'products' : 'designs'} ΓÇó Use search to find more</p>
                          )}
                        </div>
                      ) : null}
                    </>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { _getServerSession } from 'next-auth'
import toast from 'react-hot-toast'

interface OwnershipDoc {
  id: string
  status: string
  designId: string
  designTitle: string
  designImage: string
  seller: {
    id: string
    name: string
    email: string
  }
  createdAt: string
  previewFileUrl?: string
  previewFileType?: string
  previewFileName?: string
  previewDescription?: string
  sellerFullName: string
  sellerUsername?: string
  sellerSignature: string
  documentContent?: string
  documentVersion?: number
  legallyBinding: boolean
  verifiedAt?: string
  rejectionReason?: string
}

export default function AdminOwnershipPage() {
  const [documents, setDocuments] = useState<OwnershipDoc[]>([])
  const [status, setStatus] = useState('PENDING')
  const [page, setPage] = useState(1)
  const [loading, setLoading] = useState(false)
  const [selectedDoc, setSelectedDoc] = useState<OwnershipDoc | null>(null)
  const [viewingDoc, setViewingDoc] = useState<OwnershipDoc | null>(null)
  const [rejectionReason, setRejectionReason] = useState('')
  const [actionInProgress, setActionInProgress] = useState(false)
  const [confirmModal, setConfirmModal] = useState<{ action: 'approve' | 'reject'; docId: string; step: 1 | 2 } | null>(null)

  const fetchDocuments = async () => {
    setLoading(true)
    try {
      const res = await fetch(
        `/api/ownership-documents/admin?status=${status}&page=${page}&limit=10`
      )
      if (!res.ok) throw new Error('Failed to fetch documents')
      const data = await res.json()
      setDocuments(data.documents)
    } catch (error) {
      console.error('Fetch error:', error)
      toast.error('Failed to load documents')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchDocuments()
  }, [status, page])

  const handleApprove = (docId: string) => {
    setConfirmModal({ action: 'approve', docId, step: 1 })
  }

  const handleReject = (docId: string) => {
    if (!rejectionReason.trim()) {
      toast.error('Please provide a rejection reason')
      return
    }
    setConfirmModal({ action: 'reject', docId, step: 1 })
  }

  const executeAction = async () => {
    if (!confirmModal) return

    setActionInProgress(true)
    try {
      const res = await fetch(
        `/api/ownership-documents/admin?action=${confirmModal.action}`,
        {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 
            id: confirmModal.docId,
            ...(confirmModal.action === 'reject' && { reason: rejectionReason })
          })
        }
      )

      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}))
        throw new Error(errorData.message || `Failed to ${confirmModal.action} document`)
      }
      
      toast.success(`Document ${confirmModal.action === 'approve' ? 'approved' : 'rejected'}`)
      setConfirmModal(null)
      setRejectionReason('')
      setSelectedDoc(null)
      setViewingDoc(null)
      fetchDocuments()
    } catch (error) {
      console.error('Action error:', error)
      toast.error(`Failed to ${confirmModal.action} document`)
    } finally {
      setActionInProgress(false)
    }
  }

  return (
    <div className="min-h-screen bg-gray-50 p-2 sm:p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        <h1 className="text-lg sm:text-xl md:text-3xl font-bold mb-2 sm:mb-4 text-black">Ownership Document Review</h1>

        {/* Status Filter */}
        <div className="mb-2 sm:mb-4 flex gap-1 sm:gap-2 flex-wrap">
          {['PENDING', 'APPROVED', 'REJECTED'].map(s => (
            <button
              key={s}
              onClick={() => {
                setStatus(s)
                setPage(1)
              }}
              className={`px-1.5 sm:px-3 py-0.5 sm:py-1 rounded text-[10px] sm:text-xs font-medium ${status === s ? 'bg-blue-600 text-white' : 'bg-gray-200 text-black'}`}
            >
              {s}
            </button>
          ))}
        </div>

        {/* Documents Table */}
        {loading ? (
          <div className="text-center py-4 text-black text-sm">Loading...</div>
        ) : documents.length === 0 ? (
          <div className="text-center py-4 text-gray-500 text-sm">No documents found</div>
        ) : (
          <div className="bg-white rounded-lg shadow overflow-x-auto">
            <table className="w-full text-xs sm:text-sm">
              <thead className="bg-gray-100">
                <tr>
                  <th className="px-2 sm:px-3 py-2 text-left text-black font-semibold text-[10px] sm:text-xs">Design</th>
                  <th className="px-2 sm:px-3 py-2 text-left text-black font-semibold text-[10px] sm:text-xs">Seller</th>
                  <th className="px-2 sm:px-3 py-2 text-left text-black font-semibold text-[10px] sm:text-xs">Preview</th>
                  <th className="px-2 sm:px-3 py-2 text-left text-black font-semibold text-[10px] sm:text-xs">Binding</th>
                  <th className="px-2 sm:px-3 py-2 text-left text-black font-semibold text-[10px] sm:text-xs">Created</th>
                  <th className="px-2 sm:px-3 py-2 text-left text-black font-semibold text-[10px] sm:text-xs">Actions</th>
                </tr>
              </thead>
              <tbody>
                {documents.map(doc => (
                  <tr key={doc.id} className="border-t hover:bg-gray-50 cursor-pointer" onClick={() => setViewingDoc(doc)}>
                    <td className="px-2 sm:px-3 py-2">
                      <div className="flex items-center gap-2">
                        {doc.designImage && (
                          <img
                            src={doc.designImage}
                            alt={doc.designTitle}
                            className="w-8 h-8 object-cover rounded"
                          />
                        )}
                        <div className="min-w-0">
                          <div className="font-medium text-black text-[10px] sm:text-xs truncate">{doc.designTitle}</div>
                          <div className="text-[8px] sm:text-[10px] text-gray-500 truncate">{doc.designId}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-2 sm:px-3 py-2">
                      <div className="font-medium text-[10px] sm:text-xs">{doc.seller.name}</div>
                      <div className="text-[8px] sm:text-[10px] text-gray-500">{doc.seller.email}</div>
                    </td>
                    <td className="px-2 sm:px-3 py-2">
                      {doc.previewFileUrl ? (
                        <div>
                          <p className="text-[8px] sm:text-[10px] font-medium">
                            {doc.previewFileType === 'video' ? '≡ƒÄÑ Video' : '≡ƒû╝∩╕Å Image'}
                          </p>
                          <a
                            href={doc.previewFileUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="text-blue-600 hover:underline text-[8px] sm:text-[10px]"
                          >
                            View Preview
                          </a>
                          {doc.previewDescription && (
                            <p className="text-[7px] sm:text-[8px] text-gray-600 mt-0.5">
                              "{doc.previewDescription}"
                            </p>
                          )}
                        </div>
                      ) : (
                        <span className="text-[8px] sm:text-[10px] text-gray-500">No preview</span>
                      )}
                    </td>
                    <td className="px-4 py-3">
                      {doc.legallyBinding ? (
                        <span className="px-2 py-1 bg-green-100 text-green-800 rounded text-sm">
                          Yes
                        </span>
                      ) : (
                        <span className="px-2 py-1 bg-yellow-100 text-yellow-800 rounded text-sm">
                          No
                        </span>
                      )}
                    </td>
                    <td className="px-2 sm:px-3 py-2 text-[8px] sm:text-[10px] text-black font-medium">
                      {new Date(doc.createdAt).toLocaleDateString()}
                    </td>
                    <td className="px-2 sm:px-3 py-2">
                      {status === 'PENDING' && (
                        <div className="flex gap-1">
                          <button
                            onClick={(e) => {
                              e.stopPropagation()
                              handleApprove(doc.id)
                            }}
                            disabled={actionInProgress}
                            className="px-1.5 sm:px-2 py-0.5 bg-green-600 text-white rounded text-[8px] sm:text-[10px] hover:bg-green-700 disabled:opacity-50 whitespace-nowrap"
                          >
                            Approve
                          </button>
                          <button
                            onClick={(e) => {
                              e.stopPropagation()
                              setSelectedDoc(doc)
                            }}
                            className="px-1.5 sm:px-2 py-0.5 bg-red-600 text-white rounded text-[8px] sm:text-[10px] hover:bg-red-700 whitespace-nowrap"
                          >
                            Reject
                          </button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Detail View Modal */}
        {viewingDoc && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-2 sm:p-4 z-50">
            <div className="bg-white rounded-lg max-w-3xl w-full p-3 sm:p-4 max-h-[90vh] overflow-y-auto">
              <div className="flex items-center justify-between mb-3 sm:mb-4">
                <h2 className="text-lg sm:text-2xl font-bold text-black truncate">{viewingDoc.designTitle}</h2>
                <button
                  onClick={() => setViewingDoc(null)}
                  className="text-gray-500 hover:text-gray-700 text-xl sm:text-2xl ml-2 flex-shrink-0"
                >
                  ├ù
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-3 sm:gap-4 mb-3 sm:mb-4">
                {/* Design Info */}
                <div className="border rounded-lg p-2 sm:p-3">
                  <h3 className="text-sm sm:text-lg font-semibold text-black mb-2 sm:mb-3">Design Information</h3>
                  {viewingDoc.designImage && (
                    <img
                      src={viewingDoc.designImage}
                      alt={viewingDoc.designTitle}
                      className="w-full h-32 sm:h-48 object-cover rounded mb-2 sm:mb-3"
                    />
                  )}
                  <div className="space-y-1 text-xs sm:text-sm">
                    <p><span className="font-medium text-black">Title:</span> <span className="text-black break-all">{viewingDoc.designTitle}</span></p>
                    <p><span className="font-medium text-black">Design ID:</span> <span className="text-black break-all text-[10px] sm:text-xs">{viewingDoc.designId}</span></p>
                    <p><span className="font-medium text-black">Status:</span> <span className="text-black">{viewingDoc.status}</span></p>
                  </div>
                </div>

                {/* Seller Info */}
                <div className="border rounded-lg p-2 sm:p-3">
                  <h3 className="text-sm sm:text-lg font-semibold text-black mb-2 sm:mb-3">Seller Information</h3>
                  <div className="space-y-1 text-xs sm:text-sm">
                    <p><span className="font-medium text-black">Name:</span> <span className="text-black break-all">{viewingDoc.seller.name}</span></p>
                    <p><span className="font-medium text-black">Email:</span> <span className="text-black break-all text-[10px] sm:text-xs">{viewingDoc.seller.email}</span></p>
                    <p><span className="font-medium text-black">ID:</span> <span className="text-black">{viewingDoc.seller.id}</span></p>
                  </div>
                </div>
              </div>

              {/* Preview Files */}
              {viewingDoc.previewFileUrl && (
                <div className="border rounded-lg p-2 sm:p-3 mb-3 sm:mb-4">
                  <h3 className="text-sm sm:text-lg font-semibold text-black mb-2 sm:mb-3">Preview Files</h3>
                  <div className="space-y-1 sm:space-y-2">
                    {viewingDoc.previewFileType?.startsWith('image') ? (
                      <img src={viewingDoc.previewFileUrl} alt="Preview" className="w-full h-24 sm:h-40 object-cover rounded" />
                    ) : viewingDoc.previewFileType?.startsWith('video') ? (
                      <video src={viewingDoc.previewFileUrl} className="w-full h-24 sm:h-40 rounded" controls />
                    ) : null}
                    <p className="text-xs sm:text-sm"><span className="font-medium text-black">File:</span> <span className="text-black break-all text-[10px] sm:text-xs">{viewingDoc.previewFileName}</span></p>
                    {viewingDoc.previewDescription && (
                      <p className="text-xs sm:text-sm"><span className="font-medium text-black">Desc:</span> <span className="text-black break-all text-[10px] sm:text-xs">{viewingDoc.previewDescription}</span></p>
                    )}
                  </div>
                </div>
              )}

              {/* Legal Document */}
              {viewingDoc.documentContent && (
                <div className="border rounded-lg p-2 sm:p-3 mb-3 sm:mb-4 bg-blue-50">
                  <div className="flex items-center justify-between mb-2 sm:mb-3 gap-2">
                    <h3 className="text-sm sm:text-lg font-semibold text-black">Legal Document (v{viewingDoc.documentVersion})</h3>
                    <button
                      onClick={() => {
                        const printWindow = window.open('', '', 'height=600,width=800')
                        if (printWindow) {
                          const content = document.querySelector('.legal-document-content')
                          printWindow.document.write('<html><head><title>Legal Document</title><style>body { font-family: Arial, sans-serif; line-height: 1.6; } </style></head><body>')
                          printWindow.document.write(content?.innerHTML || '')
                          printWindow.document.write('</body></html>')
                          printWindow.document.close()
                          setTimeout(() => printWindow.print(), 250)
                        }
                      }}
                      className="bg-blue-600 hover:bg-blue-700 text-white px-2 py-1 rounded text-[8px] sm:text-xs font-medium whitespace-nowrap"
                    >
                      Print
                    </button>
                  </div>
                  <div 
                    className="legal-document-content max-w-none text-black bg-white p-2 sm:p-3 rounded border border-gray-200 max-h-64 overflow-y-auto text-[8px] sm:text-[10px]"
                    dangerouslySetInnerHTML={{ __html: `<style>
                      [dangerously-set-inner-html] { color: black !important; font-size: 8px; }
                      span { color: black !important; font-size: 8px; }
                      div { color: black !important; font-size: 8px; }
                      p { color: black !important; font-size: 8px; margin: 2px 0; }
                    </style>` + viewingDoc.documentContent
                      .replace(/\[Designer Full Name\]/g, viewingDoc.sellerFullName)
                      .replace(/\[Seller Full Name\]/g, viewingDoc.sellerFullName)
                      .replace(/\[Buyer Full Name\]/g, '[Buyer Full Name]')
                      .replace(/\[Contract #\]/g, `FM-${viewingDoc.id.substring(0, 8).toUpperCase()}`)
                      .replace(/Design Intellectual Property Transfer & Rights Assignment[\s\S]*?Date:\s*[\s\n]*/g, (match) => {
                        return match.replace(/Date:\s*[\s\n]*$/, `Date: ${new Date(viewingDoc.createdAt).toLocaleString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' })}\n`)
                      })
                      .replace(/Designer\/Seller Signature Name/g, `<span style="font-family: cursive; font-size: 16px; font-weight: bold; color: #000; display: block; text-align: left; position: relative; top: -25px; line-height: 0;">${viewingDoc.sellerSignature}</span>`)
                      .replace(/Designer Full Name/g, viewingDoc.sellerFullName)
                      .replace(/Admin Verification Date:[\s\n]*/g, `Admin Verification Date: ${viewingDoc.verifiedAt ? new Date(viewingDoc.verifiedAt).toLocaleString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '[Pending Admin Approval]'}\n`)
                      .replace(/BUYER \(NEW OWNER\):[\s\S]*?Platform: Fashion Marketplace(?=\n)/g, () => {
                        return `<div style="color: black !important;"><strong>BUYER (NEW OWNER):</strong><br>Full Name: <strong style="color: black !important;">[Buyer Full Name]</strong><br><br>Username: <strong style="color: black !important;">[Username]</strong><br><br>Platform: Fashion Marketplace</div>`
                      })
                      .replace(/ORIGINAL DESIGNER \(SELLER\):[\s\S]*?Platform: Fashion Marketplace(?=\n)/g, () => {
                        return `<div style="color: black !important;"><strong>ORIGINAL DESIGNER (SELLER):</strong><br>Full Name: <strong style="color: black !important;">${viewingDoc.sellerFullName}.</strong><br><br>Username: <strong style="color: black !important;">${viewingDoc.sellerUsername || '[Username]'}</strong><br><br>Platform: Fashion Marketplace</div>`
                      })
                      .replace(/ORIGINAL DESIGNER \(SELLER\)([\s\S]*?)Date:[\s\n]*/g, (match) => {
                        return match.replace(/Date:[\s\n]*$/, `Date: ${new Date(viewingDoc.createdAt).toLocaleString('en-US', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' })}\n`)
                      })
                    }}
                  />
                </div>
              )}

              {/* Signatures */}
              <div className="border rounded-lg p-2 sm:p-3 mb-3 sm:mb-4">
                <h3 className="text-sm sm:text-lg font-semibold text-black mb-2 sm:mb-3">Seller Signature</h3>
                <div className="space-y-1 text-xs sm:text-sm">
                  <p><span className="font-medium text-black">Full Name:</span> <span className="text-black break-all text-[10px] sm:text-xs">{viewingDoc.sellerFullName}</span></p>
                  <p><span className="font-medium text-black">Signature:</span> <span className="text-black text-[10px] sm:text-xs">{viewingDoc.sellerSignature}</span></p>
                </div>
              </div>

              {/* Document Info */}
              <div className="border rounded-lg p-2 sm:p-3 mb-3 sm:mb-4">
                <h3 className="text-sm sm:text-lg font-semibold text-black mb-2 sm:mb-3">Document Status</h3>
                <div className="space-y-1 text-xs sm:text-sm">
                  <p>
                    <span className="font-medium text-black">Binding:</span>{' '}
                    <span className={`px-1.5 py-0.5 rounded text-white text-[9px] sm:text-xs ${viewingDoc.legallyBinding ? 'bg-green-600' : 'bg-red-600'}`}>
                      {viewingDoc.legallyBinding ? 'Yes' : 'No'}
                    </span>
                  </p>
                  <p><span className="font-medium text-black">Created:</span> <span className="text-black text-[10px] sm:text-xs">{new Date(viewingDoc.createdAt).toLocaleDateString()}</span></p>
                  {viewingDoc.verifiedAt && (
                    <p><span className="font-medium text-black">Verified:</span> <span className="text-black text-[10px] sm:text-xs">{new Date(viewingDoc.verifiedAt).toLocaleDateString()}</span></p>
                  )}
                </div>
              </div>

              {viewingDoc.rejectionReason && (
                <div className="border rounded-lg p-2 sm:p-3 mb-3 sm:mb-4 bg-red-50">
                  <h3 className="text-sm sm:text-lg font-semibold text-red-900 mb-1 sm:mb-2">Rejection Reason</h3>
                  <p className="text-red-800 text-xs sm:text-sm">{viewingDoc.rejectionReason}</p>
                </div>
              )}

              {/* Action Buttons */}
              <div className="grid grid-cols-2 gap-2 sm:gap-3 mt-3 sm:mt-4">
                <button
                  onClick={() => {
                    handleApprove(viewingDoc.id)
                    setViewingDoc(null)
                  }}
                  disabled={actionInProgress || viewingDoc.status === 'APPROVED'}
                  className="bg-green-600 hover:bg-green-700 disabled:bg-gray-400 text-white py-1.5 sm:py-2 px-2 sm:px-4 rounded text-[10px] sm:text-sm font-medium"
                >
                  {actionInProgress ? 'Approving...' : 'Approve'}
                </button>
                <button
                  onClick={() => setSelectedDoc(viewingDoc)}
                  disabled={viewingDoc.status === 'REJECTED'}
                  className="bg-red-600 hover:bg-red-700 disabled:bg-gray-400 text-white py-1.5 sm:py-2 px-2 sm:px-4 rounded text-[10px] sm:text-sm font-medium"
                >
                  Reject
                </button>
                <button
                  onClick={() => window.print()}
                  className="bg-blue-600 hover:bg-blue-700 text-white py-1.5 sm:py-2 px-2 sm:px-4 rounded text-[10px] sm:text-sm font-medium"
                >
                  Print
                </button>
                <button
                  onClick={() => setViewingDoc(null)}
                  className="bg-gray-600 hover:bg-gray-700 text-white py-1.5 sm:py-2 px-2 sm:px-4 rounded text-[10px] sm:text-sm font-medium"
                >
                  Close
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Rejection Modal */}
        {selectedDoc && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-2 sm:p-4 z-50">
            <div className="bg-white rounded-lg max-w-sm w-full p-3 sm:p-4">
              <h2 className="text-lg sm:text-xl font-bold mb-2 sm:mb-3 text-black truncate">
                Reject: {selectedDoc.designTitle}
              </h2>
              <textarea
                value={rejectionReason}
                onChange={e => setRejectionReason(e.target.value)}
                placeholder="Provide a reason for rejection..."
                className="w-full border rounded p-2 sm:p-3 mb-3 sm:mb-4 h-20 sm:h-24 text-xs sm:text-sm focus:outline-none focus:ring-2 focus:ring-red-500"
              />
              <div className="flex gap-2 sm:gap-3">
                <button
                  onClick={() => {
                    setSelectedDoc(null)
                    setRejectionReason('')
                  }}
                  className="flex-1 px-2 sm:px-4 py-1.5 sm:py-2 border rounded hover:bg-gray-50 text-xs sm:text-sm font-medium"
                >
                  Cancel
                </button>
                <button
                  onClick={() => handleReject(selectedDoc.id)}
                  disabled={actionInProgress}
                  className="flex-1 px-2 sm:px-4 py-1.5 sm:py-2 bg-red-600 text-white rounded hover:bg-red-700 disabled:opacity-50 text-xs sm:text-sm font-medium"
                >
                  {actionInProgress ? 'Rejecting...' : 'Reject'}
                </button>
              </div>
            </div>
          </div>
        )}

        {confirmModal && confirmModal.step === 1 && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-2 sm:p-4 z-50">
            <div className="bg-white rounded-lg max-w-sm w-full p-4 sm:p-6">
              <h2 className="text-lg sm:text-xl font-bold text-black mb-4">
                {confirmModal.action === 'approve' ? 'Approve this ownership document?' : 'Reject this ownership document?'}
              </h2>
              <div className="flex gap-3 mt-6">
                <button onClick={() => setConfirmModal(null)} className="flex-1 px-4 py-2 border rounded hover:bg-gray-50 text-sm font-medium">
                  Cancel
                </button>
                <button 
                  onClick={() => setConfirmModal({...confirmModal, step: 2})} 
                  disabled={actionInProgress}
                  className={`flex-1 px-4 py-2 text-white rounded text-sm font-medium disabled:opacity-50 ${confirmModal.action === 'approve' ? 'bg-green-600 hover:bg-green-700' : 'bg-red-600 hover:bg-red-700'}`}
                >
                  {confirmModal.action === 'approve' ? 'Approve' : 'Reject'}
                </button>
              </div>
            </div>
          </div>
        )}

        {confirmModal && confirmModal.step === 2 && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-2 sm:p-4 z-50">
            <div className="bg-white rounded-lg max-w-sm w-full p-4 sm:p-6">
              <h2 className="text-lg sm:text-xl font-bold text-black mb-4">
                Are you sure? This action cannot be undone.
              </h2>
              <div className="flex gap-3 mt-6">
                <button onClick={() => setConfirmModal(null)} className="flex-1 px-4 py-2 border rounded hover:bg-gray-50 text-sm font-medium">
                  Cancel
                </button>
                <button 
                  onClick={() => executeAction()} 
                  disabled={actionInProgress}
                  className={`flex-1 px-4 py-2 text-white rounded text-sm font-medium disabled:opacity-50 ${confirmModal.action === 'approve' ? 'bg-green-600 hover:bg-green-700' : 'bg-red-600 hover:bg-red-700'}`}
                >
                  {actionInProgress ? 'Processing...' : confirmModal.action === 'approve' ? 'Approve' : 'Reject'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useEffect, useState } from 'react'
import Link from 'next/link'
import { ArrowLeft, Package, Truck, CheckCircle, AlertCircle, RefreshCw, _Download } from 'lucide-react'

interface PODOrder {
  id: string
  orderNumber: string
  status: 'PENDING' | 'CREATED' | 'ACKNOWLEDGED' | 'CANCELED' | 'IN_PRODUCTION' | 'READY_TO_SHIP' | 'SHIPPED' | 'DELIVERED' | 'RETURNED' | 'FAILED'
  seller: {
    id: string
    name: string
  }
  buyer: {
    id: string
    name: string
    email: string
  }
  items: Array<{
    id: string
    title: string
    sku: string
    quantity: number
  }>
  total: number
  podOrderId: string
  createdAt: string
  updatedAt: string
  shippingAddress: {
    name: string
    street: string
    city: string
    state: string
    zipCode: string
  }
  tracking: {
    number: string | null
    carrier: string | null
    status: string | null
  } | null
}

export default function AdminPODManagementPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [orders, setOrders] = useState<PODOrder[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<string>('all')
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedOrder, setSelectedOrder] = useState<PODOrder | null>(null)

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (session?.user?.role !== 'ADMIN') {
      router.push('/admin')
      return
    }
    if (status !== 'authenticated') return

    fetchPODOrders()
  }, [status, session, router, filter])

  const fetchPODOrders = async () => {
    try {
      setLoading(true)
      const response = await fetch(`/api/admin/pod-management?status=${filter}`)
      if (response.ok) {
        const data = await response.json()
        setOrders(data.orders || [])
      }
    } catch (error) {
      console.error('Failed to fetch POD orders:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleSyncOrder = async (orderId: string) => {
    try {
      const response = await fetch(`/api/admin/pod-management/${orderId}/sync`, {
        method: 'POST',
      })
      if (response.ok) {
        await fetchPODOrders()
      }
    } catch (error) {
      console.error('Failed to sync order:', error)
    }
  }

  const handleCancelOrder = async (orderId: string) => {
    if (!confirm('Cancel this POD order?')) return

    try {
      const response = await fetch(`/api/admin/pod-management/${orderId}/cancel`, {
        method: 'POST',
      })
      if (response.ok) {
        await fetchPODOrders()
      }
    } catch (error) {
      console.error('Failed to cancel order:', error)
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'PENDING': return 'bg-gray-100 text-gray-800'
      case 'CREATED': return 'bg-yellow-100 text-yellow-800'
      case 'ACKNOWLEDGED': return 'bg-blue-100 text-blue-800'
      case 'IN_PRODUCTION': return 'bg-indigo-100 text-indigo-800'
      case 'READY_TO_SHIP': return 'bg-purple-100 text-purple-800'
      case 'SHIPPED': return 'bg-green-100 text-green-800'
      case 'DELIVERED': return 'bg-green-100 text-green-800'
      case 'CANCELED': return 'bg-red-100 text-red-800'
      case 'FAILED': return 'bg-red-100 text-red-800'
      default: return 'bg-gray-100 text-gray-800'
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'SHIPPED':
      case 'DELIVERED':
        return <Truck className="w-4 h-4" />
      case 'READY_TO_SHIP':
      case 'IN_PRODUCTION':
        return <Package className="w-4 h-4" />
      case 'DELIVERED':
        return <CheckCircle className="w-4 h-4" />
      default:
        return <AlertCircle className="w-4 h-4" />
    }
  }

  const filteredOrders = orders.filter((o) => {
    const statusMatch = filter === 'all' || o.status === filter
    const searchMatch =
      o.orderNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
      o.buyer.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      o.seller.name.toLowerCase().includes(searchQuery.toLowerCase())
    return statusMatch && searchMatch
  })

  if (loading) {
    return <div className="p-8 text-center">Loading POD orders...</div>
  }

  if (session?.user?.role !== 'ADMIN') {
    return <div className="p-8 text-center text-red-600">Access Denied</div>
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 md:p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <Link href="/admin" className="p-2 hover:bg-gray-200 rounded-lg transition">
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">POD Order Management</h1>
            <p className="text-gray-600 mt-1">Track and manage print-on-demand orders</p>
          </div>
        </div>

        {/* Search & Filter */}
        <div className="bg-white rounded-lg shadow-sm p-4 mb-6">
          <div className="flex flex-col sm:flex-row gap-4">
            <input
              type="text"
              placeholder="Search by order #, seller, or buyer..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="flex-1 px-4 py-2 border border-gray-300 rounded-lg text-black"
            />
            <select
              value={filter}
              onChange={(e) => setFilter(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg text-black bg-white"
            >
              <option value="all">All Status</option>
              <option value="PENDING">Pending</option>
              <option value="CREATED">Created</option>
              <option value="IN_PRODUCTION">In Production</option>
              <option value="READY_TO_SHIP">Ready to Ship</option>
              <option value="SHIPPED">Shipped</option>
              <option value="DELIVERED">Delivered</option>
              <option value="CANCELED">Canceled</option>
            </select>
          </div>
        </div>

        {/* Orders List */}
        {filteredOrders.length === 0 ? (
          <div className="bg-white rounded-lg shadow-sm p-12 text-center">
            <Package className="w-12 h-12 text-gray-300 mx-auto mb-4" />
            <p className="text-gray-500">No POD orders found</p>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredOrders.map((order) => (
              <div key={order.id} className="bg-white rounded-lg shadow-sm p-4 sm:p-6 hover:shadow-md transition">
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-4">
                  <div className="flex-1 min-w-0">
                    <h3 className="text-lg font-semibold text-gray-900">Order {order.orderNumber}</h3>
                    <p className="text-sm text-gray-600 mt-1">
                      {order.seller.name} ΓåÆ {order.buyer.name}
                    </p>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className={`inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(order.status)}`}>
                      {getStatusIcon(order.status)}
                      {order.status}
                    </span>
                  </div>
                </div>

                <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-4 pb-4 border-b border-gray-200">
                  <div>
                    <p className="text-xs text-gray-600 mb-1">Order Total</p>
                    <p className="font-semibold text-gray-900">${order.total.toFixed(2)}</p>
                  </div>
                  <div>
                    <p className="text-xs text-gray-600 mb-1">Items</p>
                    <p className="font-semibold text-gray-900">{order.items.length}</p>
                  </div>
                  <div>
                    <p className="text-xs text-gray-600 mb-1">Created</p>
                    <p className="font-semibold text-gray-900 text-sm">{new Date(order.createdAt).toLocaleDateString()}</p>
                  </div>
                  <div>
                    <p className="text-xs text-gray-600 mb-1">POD Order ID</p>
                    <p className="font-semibold text-gray-900 text-sm truncate">{order.podOrderId}</p>
                  </div>
                </div>

                {order.tracking && (
                  <div className="mb-4 p-3 bg-blue-50 border border-blue-200 rounded-lg">
                    <p className="text-sm font-medium text-blue-900 mb-1">Tracking</p>
                    <p className="text-sm text-blue-800">
                      {order.tracking.carrier}: {order.tracking.number || 'Pending'}
                    </p>
                  </div>
                )}

                <div className="flex gap-2">
                  <button
                    onClick={() => setSelectedOrder(order)}
                    className="px-3 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition text-sm"
                  >
                    View Details
                  </button>
                  <button
                    onClick={() => handleSyncOrder(order.id)}
                    className="px-3 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition text-sm flex items-center gap-1"
                  >
                    <RefreshCw className="w-3 h-3" />
                    Sync
                  </button>
                  {order.status === 'PENDING' && (
                    <button
                      onClick={() => handleCancelOrder(order.id)}
                      className="px-3 py-2 border border-red-300 text-red-700 rounded-lg hover:bg-red-50 transition text-sm"
                    >
                      Cancel
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Stats */}
        {orders.length > 0 && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-8">
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-indigo-600">{orders.length}</p>
              <p className="text-xs text-gray-600 mt-1">Total Orders</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-yellow-600">{orders.filter(o => o.status === 'PENDING' || o.status === 'CREATED').length}</p>
              <p className="text-xs text-gray-600 mt-1">Processing</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-blue-600">{orders.filter(o => o.status === 'SHIPPED').length}</p>
              <p className="text-xs text-gray-600 mt-1">Shipped</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-green-600">${orders.reduce((sum, o) => sum + o.total, 0).toFixed(2)}</p>
              <p className="text-xs text-gray-600 mt-1">Total Revenue</p>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import toast from 'react-hot-toast'
import { Star, Shield, _TrendingUp, Lightbulb } from 'lucide-react'

interface SellerBadge {
  id: string
  name: string
  email: string
  image: string | null
  isVerified: boolean
  verificationBadge: string | null
  totalSales: number
  avgRating: number
  suggestedBadge?: string | null
  achievements?: {
    totalSales: number
    avgRating: number
    reviewCount: number
    designCount: number
    accountAgeDays: number
    trustScore: number
  }
}

export default function AdminSellerBadgesPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [sellers, setSellers] = useState<SellerBadge[]>([])
  const [loading, setLoading] = useState(true)
  const [badgeFilter, setBadgeFilter] = useState<string>('')

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/api/auth/signin')
      return
    }
    if (session?.user?.role !== 'ADMIN') {
      router.push('/')
      return
    }
    fetchSellers()
  }, [session, status, badgeFilter])

  const fetchSellers = async () => {
    try {
      setLoading(true)
      let url = '/api/admin/seller-badges'
      if (badgeFilter) {
        url += `?badge=${badgeFilter}`
      }
      const res = await fetch(url)
      if (!res.ok) throw new Error('Failed to fetch sellers')
      const data = await res.json()
      setSellers(data.sellers || [])
    } catch (error) {
      console.error('Fetch error:', error)
      toast.error('Failed to load sellers')
    } finally {
      setLoading(false)
    }
  }

  const handleBadgeChange = async (sellerId: string, badge: string | null) => {
    try {
      const res = await fetch(`/api/admin/seller-badges/${sellerId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ badge })
      })
      if (!res.ok) throw new Error('Failed to update badge')
      toast.success('Seller badge updated')
      fetchSellers()
    } catch (error) {
      console.error('Error:', error)
      toast.error('Failed to update badge')
    }
  }

  const getBadgeColor = (badge: string | null) => {
    switch (badge) {
      case 'VERIFIED_SELLER':
        return 'bg-blue-100 text-blue-900 border-blue-300'
      case 'TOP_SELLER':
        return 'bg-purple-100 text-purple-900 border-purple-300'
      case 'BESTSELLER':
        return 'bg-yellow-100 text-yellow-900 border-yellow-300'
      case 'TRENDING':
        return 'bg-pink-100 text-pink-900 border-pink-300'
      case 'RISING_STAR':
        return 'bg-green-100 text-green-900 border-green-300'
      case 'VERIFIED_PRO':
        return 'bg-indigo-100 text-indigo-900 border-indigo-300'
      default:
        return 'bg-gray-100 text-gray-900 border-gray-300'
    }
  }

  if (status === 'loading' || loading) {
    return <div className="p-6 text-center">Loading...</div>
  }

  return (
    <div className="min-h-screen bg-gray-50 py-6 px-4 sm:px-6 lg:px-8">
      <div className="max-w-6xl mx-auto">
        <div className="bg-white rounded-lg shadow-sm">
          <div className="px-4 sm:px-6 py-4 sm:py-6 border-b border-gray-200">
            <div className="flex items-center gap-3 mb-4">
              <Shield className="h-6 w-6 text-indigo-600" />
              <h1 className="text-2xl font-bold text-gray-900">Seller Badges</h1>
            </div>
            <p className="text-sm text-gray-600">Manage seller verification and achievement badges</p>
          </div>

          {/* Filter */}
          <div className="px-4 sm:px-6 py-4 border-b border-gray-200">
            <select
              aria-label="Filter sellers by badge"
              value={badgeFilter}
              onChange={(e) => setBadgeFilter(e.target.value)}
              className="px-3 py-2 border border-gray-300 rounded-lg text-sm text-gray-900"
            >
              <option value="">All Sellers</option>
              <option value="VERIFIED_SELLER">Verified Sellers</option>
              <option value="TOP_SELLER">Top Sellers</option>
              <option value="BESTSELLER">Bestsellers</option>
              <option value="TRENDING">Trending</option>
              <option value="RISING_STAR">Rising Stars</option>
              <option value="VERIFIED_PRO">Verified Pros</option>
            </select>
          </div>

          {/* Sellers Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 p-4 sm:p-6">
            {sellers.length === 0 ? (
              <div className="col-span-full text-center py-12">
                <p className="text-gray-500">No sellers found</p>
              </div>
            ) : (
              sellers.map((seller) => (
                <SellerBadgeCard
                  key={seller.id}
                  seller={seller}
                  onBadgeChange={handleBadgeChange}
                  getBadgeColor={getBadgeColor}
                  fetchSellers={fetchSellers}
                />
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

/**
 * SellerBadgeCard Component - Displays individual seller with badge suggestion
 */
interface SellerBadgeCardProps {
  seller: SellerBadge
  onBadgeChange: (sellerId: string, badge: string | null) => Promise<void>
  getBadgeColor: (badge: string | null) => string
  fetchSellers: () => Promise<void>
}

function SellerBadgeCard({
  seller,
  onBadgeChange,
  getBadgeColor,
  fetchSellers
}: SellerBadgeCardProps) {
  const [loading, setLoading] = useState(false)
  const [suggestion, setSuggestion] = useState<string | null>(null)
  const [achievements, setAchievements] = useState<SellerBadge['achievements'] | undefined>(undefined)

  useEffect(() => {
    // Fetch suggestion on mount or when seller changes
    const fetchSuggestion = async () => {
      try {
        setLoading(true)
        const res = await fetch(`/api/admin/seller-badges/${seller.id}`)
        if (res.ok) {
          const data = await res.json()
          setSuggestion(data.suggestedBadge)
          setAchievements(data.achievements)
        }
      } catch (error) {
        console.error('Failed to fetch suggestion:', error)
      } finally {
        setLoading(false)
      }
    }

    fetchSuggestion()
  }, [seller.id])

  const showSuggestion = suggestion && suggestion !== seller.verificationBadge

  return (
    <div className="border border-gray-200 rounded-lg p-4 hover:shadow-md transition">
      <div className="flex items-start gap-3 mb-3">
        {seller.image ? (
          <img
            src={seller.image}
            alt={seller.name || 'Seller'}
            className="h-10 w-10 rounded-full object-cover"
          />
        ) : (
          <div className="h-10 w-10 rounded-full bg-gray-300 flex items-center justify-center text-xs font-bold">
            {(seller.name || 'U')[0].toUpperCase()}
          </div>
        )}
        <div className="flex-1 min-w-0">
          <p className="font-semibold text-gray-900 truncate">{seller.name}</p>
          <p className="text-xs text-gray-500 truncate">{seller.email}</p>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 gap-2 mb-3">
        <div className="bg-gray-50 p-2 rounded">
          <p className="text-xs text-gray-600">Sales</p>
          <p className="text-sm font-semibold text-gray-900">{achievements?.totalSales ?? seller.totalSales}</p>
        </div>
        <div className="bg-gray-50 p-2 rounded">
          <div className="flex items-center gap-1">
            <Star className="h-3 w-3 text-yellow-500" />
            <p className="text-sm font-semibold text-gray-900">{achievements?.avgRating?.toFixed(1) ?? seller.avgRating.toFixed(1)}</p>
          </div>
        </div>
      </div>

      {/* Suggested Badge */}
      {showSuggestion && (
        <div className="mb-3 p-3 bg-blue-50 border border-blue-200 rounded-lg">
          <div className="flex items-start gap-2">
            <Lightbulb className="h-4 w-4 text-blue-600 mt-0.5 flex-shrink-0" />
            <div className="flex-1">
              <p className="text-xs font-medium text-blue-900 mb-2">Auto-Recommended Badge</p>
              <button
                onClick={() => onBadgeChange(seller.id, suggestion)}
                className={`w-full px-2 py-1 text-xs font-medium rounded border transition ${getBadgeColor(suggestion)}`}
              >
                Apply: {suggestion.replace(/_/g, ' ')}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Badge Selector */}
      <div className="border-t pt-3">
        <p className="text-xs font-medium text-gray-700 mb-2">Current Badge</p>
        <select
          aria-label={`Change badge for ${seller.name}`}
          value={seller.verificationBadge || ''}
          onChange={(e) => onBadgeChange(seller.id, e.target.value || null)}
          className={`w-full px-2 py-1 text-xs rounded border ${getBadgeColor(seller.verificationBadge)}`}
        >
          <option value="">None</option>
          <option value="RISING_STAR">Rising Star</option>
          <option value="TOP_SELLER">Top Seller</option>
          <option value="VERIFIED_PRO">Verified Pro</option>
          <option value="VERIFIED_SELLER">Verified Seller</option>
          <option value="BESTSELLER">Bestseller</option>
          <option value="TRENDING">Trending</option>
        </select>
      </div>

      {/* Current Badge Display */}
      {seller.verificationBadge && (
        <div className="mt-3 pt-3 border-t">
          <span className={`inline-block px-2 py-1 text-xs font-medium rounded border ${getBadgeColor(seller.verificationBadge)}`}>
            Γ£ô {seller.verificationBadge.replace(/_/g, ' ')}
          </span>
        </div>
      )}

      {/* Achievement Summary */}
      {achievements && (
        <div className="mt-3 pt-3 border-t space-y-1">
          <p className="text-xs text-gray-600">
            <span className="font-medium">{achievements.reviewCount}</span> reviews
          </p>
          <p className="text-xs text-gray-600">
            <span className="font-medium">{achievements.designCount}</span> designs
          </p>
        </div>
      )}
    </div>
  )
}

'use client'

import { useSession } from 'next-auth/react'
import { useRouter, useParams } from 'next/navigation'
import { useEffect, useState } from 'react'
import Link from 'next/link'
import { ArrowLeft, Save, _X, Plus, Trash2 } from 'lucide-react'

interface ShippingZone {
  id: string
  name: string
  countries: string[]
  baseRate: number
  perItemRate: number
  processingDays: number
  isActive: boolean
  rates: Array<{
    id: string
    weightMin: number
    weightMax: number
    rate: number
    estimatedDays: number
  }>
}

export default function ShippingZoneDetailPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const params = useParams()
  const zoneId = params.id as string

  const [zone, setZone] = useState<ShippingZone | null>(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [editMode, setEditMode] = useState(false)

  // Form states
  const [name, setName] = useState('')
  const [countries, setCountries] = useState('')
  const [baseRate, setBaseRate] = useState('')
  const [perItemRate, setPerItemRate] = useState('')
  const [processingDays, setProcessingDays] = useState('')
  const [isActive, setIsActive] = useState(false)

  // Rate form
  const [showRateForm, setShowRateForm] = useState(false)
  const [rateWeightMin, setRateWeightMin] = useState('')
  const [rateWeightMax, setRateWeightMax] = useState('')
  const [ratePrice, setRatePrice] = useState('')
  const [rateEstDays, setRateEstDays] = useState('')
  const [rates, setRates] = useState<ShippingZone['rates']>([])

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (session?.user?.role !== 'ADMIN') {
      router.push('/admin')
      return
    }
    if (status !== 'authenticated') return

    fetchZoneDetail()
  }, [status, session, router])

  const fetchZoneDetail = async () => {
    try {
      setLoading(true)
      const response = await fetch(`/api/admin/shipping/zones/${zoneId}`)
      if (response.ok) {
        const data = await response.json()
        const z = data.zone
        setZone(z)
        setName(z.name)
        setCountries(z.countries.join(', '))
        setBaseRate(z.baseRate.toString())
        setPerItemRate(z.perItemRate.toString())
        setProcessingDays(z.processingDays.toString())
        setIsActive(z.isActive)
        setRates(z.rates)
      }
    } catch (error) {
      console.error('Failed to fetch zone:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleSave = async () => {
    if (!name || !countries || !baseRate) {
      alert('Please fill in all required fields')
      return
    }

    try {
      setSaving(true)
      const response = await fetch(`/api/admin/shipping/zones/${zoneId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name,
          countries: countries.split(',').map(c => c.trim()),
          baseRate: parseFloat(baseRate),
          perItemRate: parseFloat(perItemRate || '0'),
          processingDays: parseInt(processingDays || '5'),
          isActive,
        }),
      })

      if (response.ok) {
        await fetchZoneDetail()
        setEditMode(false)
      }
    } catch (error) {
      console.error('Failed to save zone:', error)
    } finally {
      setSaving(false)
    }
  }

  const handleAddRate = async () => {
    if (!rateWeightMin || !rateWeightMax || !ratePrice) {
      alert('Please fill in all rate fields')
      return
    }

    try {
      const response = await fetch(`/api/admin/shipping/zones/${zoneId}/rates`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          weightMin: parseFloat(rateWeightMin),
          weightMax: parseFloat(rateWeightMax),
          rate: parseFloat(ratePrice),
          estimatedDays: parseInt(rateEstDays || '5'),
        }),
      })

      if (response.ok) {
        setRateWeightMin('')
        setRateWeightMax('')
        setRatePrice('')
        setRateEstDays('')
        setShowRateForm(false)
        await fetchZoneDetail()
      }
    } catch (error) {
      console.error('Failed to add rate:', error)
    }
  }

  const handleDeleteRate = async (rateId: string) => {
    if (!confirm('Delete this rate?')) return

    try {
      const response = await fetch(`/api/admin/shipping/zones/${zoneId}/rates/${rateId}`, {
        method: 'DELETE',
      })

      if (response.ok) {
        await fetchZoneDetail()
      }
    } catch (error) {
      console.error('Failed to delete rate:', error)
    }
  }

  if (loading) {
    return <div className="p-8 text-center">Loading zone details...</div>
  }

  if (!zone) {
    return <div className="p-8 text-center text-red-600">Zone not found</div>
  }

  return (
    <div className="min-h-screen bg-gray-50 p-3 sm:p-4 md:p-6">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center gap-3 sm:gap-4 mb-6 sm:mb-8">
          <Link href="/admin/shipping" className="p-2 hover:bg-gray-200 rounded-lg transition">
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div className="flex-1 min-w-0">
            <h1 className="text-2xl sm:text-3xl font-bold text-gray-900 truncate">Shipping Zone</h1>
            <p className="text-xs sm:text-sm text-gray-600 mt-1 truncate">{zone.name}</p>
          </div>
        </div>

        {/* Zone Details */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-semibold text-gray-900">Zone Configuration</h2>
            {!editMode ? (
              <button
                onClick={() => setEditMode(true)}
                className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition text-sm"
              >
                Edit
              </button>
            ) : (
              <div className="flex gap-2">
                <button
                  onClick={() => setEditMode(false)}
                  className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSave}
                  disabled={saving}
                  className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition disabled:opacity-50 flex items-center gap-2"
                >
                  <Save className="w-4 h-4" />
                  Save
                </button>
              </div>
            )}
          </div>

          <div className="space-y-4">
            {editMode ? (
              <>
                <div>
                  <label className="block text-xs font-medium text-gray-900 mb-1">Zone Name *</label>
                  <input
                    type="text"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    aria-label="Zone name"
                    className="w-full px-3 py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                  />
                </div>

                <div>
                  <label className="block text-xs font-medium text-gray-900 mb-1">Countries (comma-separated) *</label>
                  <input
                    type="text"
                    value={countries}
                    onChange={(e) => setCountries(e.target.value)}
                    aria-label="Countries list"
                    className="w-full px-3 py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                    placeholder="US, CA, MX"
                  />
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-2 sm:gap-3">
                  <div>
                    <label className="block text-xs font-medium text-gray-900 mb-1">Base Rate ($) *</label>
                    <input
                      type="number"
                      step="0.01"
                      value={baseRate}
                      onChange={(e) => setBaseRate(e.target.value)}
                      aria-label="Base rate"
                      className="w-full px-3 py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-900 mb-1">Per Item ($)</label>
                    <input
                      type="number"
                      step="0.01"
                      value={perItemRate}
                      onChange={(e) => setPerItemRate(e.target.value)}
                      aria-label="Per item rate"
                      className="w-full px-3 py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-900 mb-1">Processing Days</label>
                    <input
                      type="number"
                      value={processingDays}
                      onChange={(e) => setProcessingDays(e.target.value)}
                      aria-label="Processing days"
                      className="w-full px-3 py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                    />
                  </div>
                </div>

                <div className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    id="isActive"
                    checked={isActive}
                    onChange={(e) => setIsActive(e.target.checked)}
                    className="w-4 h-4"
                  />
                  <label htmlFor="isActive" className="text-sm font-medium text-gray-900">
                    Active Zone
                  </label>
                </div>
              </>
            ) : (
              <>
                <div>
                  <p className="text-sm text-gray-600">Zone Name</p>
                  <p className="text-lg font-semibold text-gray-900">{zone.name}</p>
                </div>

                <div>
                  <p className="text-sm text-gray-600">Countries</p>
                  <p className="text-lg font-semibold text-gray-900">{zone.countries.join(', ')}</p>
                </div>

                <div className="grid grid-cols-3 gap-4">
                  <div>
                    <p className="text-sm text-gray-600">Base Rate</p>
                    <p className="text-lg font-semibold text-gray-900">${zone.baseRate.toFixed(2)}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-600">Per Item</p>
                    <p className="text-lg font-semibold text-gray-900">${zone.perItemRate.toFixed(2)}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-600">Processing Days</p>
                    <p className="text-lg font-semibold text-gray-900">{zone.processingDays}</p>
                  </div>
                </div>

                <div>
                  <p className="text-sm text-gray-600">Status</p>
                  <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium ${
                    zone.isActive ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'
                  }`}>
                    {zone.isActive ? 'Active' : 'Inactive'}
                  </span>
                </div>
              </>
            )}
          </div>
        </div>

        {/* Weight-Based Rates */}
        <div className="bg-white rounded-lg shadow-sm p-6">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-semibold text-gray-900">Weight-Based Rates</h2>
            {!showRateForm && (
              <button
                onClick={() => setShowRateForm(true)}
                className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition text-sm"
              >
                <Plus className="w-4 h-4" />
                Add Rate
              </button>
            )}
          </div>

          {showRateForm && (
            <div className="mb-6 p-4 bg-gray-50 border border-gray-200 rounded-lg space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-900 mb-2">Min Weight (lbs)</label>
                  <input
                    type="number"
                    step="0.1"
                    value={rateWeightMin}
                    onChange={(e) => setRateWeightMin(e.target.value)}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg text-black"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-900 mb-2">Max Weight (lbs)</label>
                  <input
                    type="number"
                    step="0.1"
                    value={rateWeightMax}
                    onChange={(e) => setRateWeightMax(e.target.value)}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg text-black"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-900 mb-2">Rate ($)</label>
                  <input
                    type="number"
                    step="0.01"
                    value={ratePrice}
                    onChange={(e) => setRatePrice(e.target.value)}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg text-black"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-900 mb-2">Est. Days</label>
                  <input
                    type="number"
                    value={rateEstDays}
                    onChange={(e) => setRateEstDays(e.target.value)}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg text-black"
                  />
                </div>
              </div>

              <div className="flex gap-2">
                <button
                  onClick={() => setShowRateForm(false)}
                  className="flex-1 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  onClick={handleAddRate}
                  className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
                >
                  Add Rate
                </button>
              </div>
            </div>
          )}

          {/* Rates Table */}
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b border-gray-200">
                <tr>
                  <th className="px-4 py-3 text-left font-semibold text-gray-900">Weight Range</th>
                  <th className="px-4 py-3 text-left font-semibold text-gray-900">Rate</th>
                  <th className="px-4 py-3 text-left font-semibold text-gray-900">Est. Days</th>
                  <th className="px-4 py-3 text-left font-semibold text-gray-900">Actions</th>
                </tr>
              </thead>
              <tbody>
                {rates.length === 0 ? (
                  <tr>
                    <td colSpan={4} className="px-4 py-8 text-center text-gray-500">
                      No rates configured
                    </td>
                  </tr>
                ) : (
                  rates.map((rate) => (
                    <tr key={rate.id} className="border-b border-gray-200 hover:bg-gray-50">
                      <td className="px-4 py-3 text-gray-900 font-medium">
                        {rate.weightMin} - {rate.weightMax} lbs
                      </td>
                      <td className="px-4 py-3 text-gray-900 font-semibold">${rate.rate.toFixed(2)}</td>
                      <td className="px-4 py-3 text-gray-600">{rate.estimatedDays} days</td>
                      <td className="px-4 py-3">
                        <button
                          onClick={() => handleDeleteRate(rate.id)}
                          className="p-1 hover:bg-red-50 rounded transition"
                        >
                          <Trash2 className="w-4 h-4 text-red-600" />
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useEffect, useState } from 'react'
import { ArrowLeft, Plus, Edit, Trash2, AlertCircle, _CheckCircle, _X } from 'lucide-react'

interface ShippingZone {
  id: string
  name: string
  countries: string[]
  baseRate: number
  perItemRate: number
  processingDays: number
  isActive: boolean
}

interface Carrier {
  id: string
  name: string
  apiKey: string
  baseURL: string
  isActive: boolean
  supportedCountries: string[]
}

interface ShippingRate {
  id: string
  zoneId: string
  weightMin: number
  weightMax: number
  rate: number
  estimatedDays: number
}

export default function AdminShippingPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [zones, setZones] = useState<ShippingZone[]>([])
  const [carriers, setCarriers] = useState<Carrier[]>([])
  const [rates, setRates] = useState<ShippingRate[]>([])
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState<'zones' | 'carriers' | 'rates'>('zones')
  const [showZoneForm, setShowZoneForm] = useState(false)
  const [showCarrierForm, setShowCarrierForm] = useState(false)
  const [editingZone, setEditingZone] = useState<ShippingZone | null>(null)
  const [editingCarrier, setEditingCarrier] = useState<Carrier | null>(null)

  // Form states
  const [zoneName, setZoneName] = useState('')
  const [zoneCountries, setZoneCountries] = useState('')
  const [baseRate, setBaseRate] = useState('')
  const [perItemRate, setPerItemRate] = useState('')
  const [processingDays, setProcessingDays] = useState('')

  const [carrierName, setCarrierName] = useState('')
  const [carrierApiKey, setCarrierApiKey] = useState('')
  const [carrierBaseURL, setCarrierBaseURL] = useState('')

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (session?.user?.role !== 'ADMIN') {
      router.push('/admin')
      return
    }
    if (status !== 'authenticated') return

    fetchShippingData()
  }, [status, session, router])

  const fetchShippingData = async () => {
    try {
      setLoading(true)
      const [zonesRes, carriersRes, ratesRes] = await Promise.all([
        fetch('/api/admin/shipping/zones'),
        fetch('/api/admin/shipping/carriers'),
        fetch('/api/admin/shipping/rates'),
      ])

      if (zonesRes.ok) {
        const data = await zonesRes.json()
        setZones(data.zones || [])
      }
      if (carriersRes.ok) {
        const data = await carriersRes.json()
        setCarriers(data.carriers || [])
      }
      if (ratesRes.ok) {
        const data = await ratesRes.json()
        setRates(data.rates || [])
      }
    } catch (error) {
      console.error('Failed to fetch shipping data:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleCreateZone = async () => {
    if (!zoneName || !zoneCountries || !baseRate) {
      alert('Please fill in all required fields')
      return
    }

    try {
      const response = await fetch('/api/admin/shipping/zones', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: zoneName,
          countries: zoneCountries.split(',').map(c => c.trim()),
          baseRate: parseFloat(baseRate),
          perItemRate: parseFloat(perItemRate || '0'),
          processingDays: parseInt(processingDays || '5'),
        }),
      })

      if (response.ok) {
        await fetchShippingData()
        setShowZoneForm(false)
        setZoneName('')
        setZoneCountries('')
        setBaseRate('')
        setPerItemRate('')
        setProcessingDays('')
      }
    } catch (error) {
      console.error('Failed to create zone:', error)
    }
  }

  const handleCreateCarrier = async () => {
    if (!carrierName || !carrierApiKey) {
      alert('Please fill in all required fields')
      return
    }

    try {
      const response = await fetch('/api/admin/shipping/carriers', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: carrierName,
          apiKey: carrierApiKey,
          baseURL: carrierBaseURL,
        }),
      })

      if (response.ok) {
        await fetchShippingData()
        setShowCarrierForm(false)
        setCarrierName('')
        setCarrierApiKey('')
        setCarrierBaseURL('')
      }
    } catch (error) {
      console.error('Failed to create carrier:', error)
    }
  }

  const handleDeleteZone = async (id: string) => {
    if (!confirm('Are you sure you want to delete this shipping zone?')) return

    try {
      const response = await fetch(`/api/admin/shipping/zones/${id}`, {
        method: 'DELETE',
      })

      if (response.ok) {
        await fetchShippingData()
      }
    } catch (error) {
      console.error('Failed to delete zone:', error)
    }
  }

  const handleDeleteCarrier = async (id: string) => {
    if (!confirm('Are you sure you want to delete this carrier?')) return

    try {
      const response = await fetch(`/api/admin/shipping/carriers/${id}`, {
        method: 'DELETE',
      })

      if (response.ok) {
        await fetchShippingData()
      }
    } catch (error) {
      console.error('Failed to delete carrier:', error)
    }
  }

  if (status === 'loading' || loading) {
    return <div className="p-8 text-center">Loading shipping configuration...</div>
  }

  if (session?.user?.role !== 'ADMIN') {
    return <div className="p-8 text-center text-red-600">Access Denied</div>
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 md:p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <button
            onClick={() => router.back()}
            className="p-2 hover:bg-gray-200 rounded-lg transition"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Shipping Configuration</h1>
            <p className="text-gray-600">Manage shipping zones, rates, and carriers</p>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-4 mb-8 border-b border-gray-200">
          <button
            onClick={() => setActiveTab('zones')}
            className={`px-4 py-2 border-b-2 font-medium transition ${
              activeTab === 'zones'
                ? 'border-indigo-600 text-indigo-600'
                : 'border-transparent text-gray-600 hover:text-gray-900'
            }`}
          >
            Zones ({zones.length})
          </button>
          <button
            onClick={() => setActiveTab('carriers')}
            className={`px-4 py-2 border-b-2 font-medium transition ${
              activeTab === 'carriers'
                ? 'border-indigo-600 text-indigo-600'
                : 'border-transparent text-gray-600 hover:text-gray-900'
            }`}
          >
            Carriers ({carriers.length})
          </button>
          <button
            onClick={() => setActiveTab('rates')}
            className={`px-4 py-2 border-b-2 font-medium transition ${
              activeTab === 'rates'
                ? 'border-indigo-600 text-indigo-600'
                : 'border-transparent text-gray-600 hover:text-gray-900'
            }`}
          >
            Rates ({rates.length})
          </button>
        </div>

        {/* Zones Tab */}
        {activeTab === 'zones' && (
          <div>
            <div className="mb-6 flex justify-between items-center">
              <h2 className="text-xl font-semibold text-gray-900">Shipping Zones</h2>
              <button
                onClick={() => setShowZoneForm(!showZoneForm)}
                className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition text-sm"
              >
                <Plus className="w-4 h-4" />
                Add Zone
              </button>
            </div>

            {showZoneForm && (
              <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
                <h3 className="text-lg font-semibold mb-4">Create New Zone</h3>
                <div className="space-y-4">
                  <input
                    type="text"
                    placeholder="Zone Name (e.g., 'USA - Continental')"
                    value={zoneName}
                    onChange={(e) => setZoneName(e.target.value)}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg text-black"
                  />
                  <input
                    type="text"
                    placeholder="Countries (comma-separated, e.g., 'US, CA, MX')"
                    value={zoneCountries}
                    onChange={(e) => setZoneCountries(e.target.value)}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg text-black"
                  />
                  <div className="grid grid-cols-2 gap-4">
                    <input
                      type="number"
                      placeholder="Base Rate ($)"
                      value={baseRate}
                      onChange={(e) => setBaseRate(e.target.value)}
                      className="px-4 py-2 border border-gray-300 rounded-lg text-black"
                    />
                    <input
                      type="number"
                      placeholder="Per Item Rate ($)"
                      value={perItemRate}
                      onChange={(e) => setPerItemRate(e.target.value)}
                      className="px-4 py-2 border border-gray-300 rounded-lg text-black"
                    />
                  </div>
                  <input
                    type="number"
                    placeholder="Processing Days"
                    value={processingDays}
                    onChange={(e) => setProcessingDays(e.target.value)}
                    className="px-4 py-2 border border-gray-300 rounded-lg text-black"
                  />
                  <div className="flex gap-2 justify-end">
                    <button
                      onClick={() => setShowZoneForm(false)}
                      className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button
                      onClick={handleCreateZone}
                      className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
                    >
                      Create Zone
                    </button>
                  </div>
                </div>
              </div>
            )}

            <div className="space-y-4">
              {zones.length === 0 ? (
                <div className="bg-white rounded-lg shadow-sm p-12 text-center">
                  <AlertCircle className="w-12 h-12 text-gray-300 mx-auto mb-4" />
                  <p className="text-gray-500">No shipping zones configured</p>
                </div>
              ) : (
                zones.map((zone) => (
                  <div key={zone.id} className="bg-white rounded-lg shadow-sm p-4 sm:p-6">
                    <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
                      <div>
                        <h3 className="font-semibold text-gray-900">{zone.name}</h3>
                        <p className="text-sm text-gray-600 mt-1">
                          Countries: {zone.countries.join(', ')}
                        </p>
                        <div className="flex gap-4 mt-3">
                          <div>
                            <p className="text-xs text-gray-600">Base Rate</p>
                            <p className="font-semibold text-indigo-600">${zone.baseRate.toFixed(2)}</p>
                          </div>
                          <div>
                            <p className="text-xs text-gray-600">Per Item</p>
                            <p className="font-semibold text-indigo-600">${zone.perItemRate.toFixed(2)}</p>
                          </div>
                          <div>
                            <p className="text-xs text-gray-600">Processing Days</p>
                            <p className="font-semibold">{zone.processingDays}</p>
                          </div>
                        </div>
                      </div>
                      <div className="flex gap-2">
                        <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium ${
                          zone.isActive ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'
                        }`}>
                          {zone.isActive ? 'Active' : 'Inactive'}
                        </span>
                        <button className="p-2 hover:bg-gray-100 rounded-lg transition">
                          <Edit className="w-4 h-4 text-gray-600" />
                        </button>
                        <button
                          onClick={() => handleDeleteZone(zone.id)}
                          className="p-2 hover:bg-red-50 rounded-lg transition"
                        >
                          <Trash2 className="w-4 h-4 text-red-600" />
                        </button>
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {/* Carriers Tab */}
        {activeTab === 'carriers' && (
          <div>
            <div className="mb-6 flex justify-between items-center">
              <h2 className="text-xl font-semibold text-gray-900">Shipping Carriers</h2>
              <button
                onClick={() => setShowCarrierForm(!showCarrierForm)}
                className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition text-sm"
              >
                <Plus className="w-4 h-4" />
                Add Carrier
              </button>
            </div>

            {showCarrierForm && (
              <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
                <h3 className="text-lg font-semibold mb-4">Add Shipping Carrier</h3>
                <div className="space-y-4">
                  <input
                    type="text"
                    placeholder="Carrier Name (e.g., 'FedEx', 'DHL')"
                    value={carrierName}
                    onChange={(e) => setCarrierName(e.target.value)}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg text-black"
                  />
                  <input
                    type="text"
                    placeholder="API Key"
                    value={carrierApiKey}
                    onChange={(e) => setCarrierApiKey(e.target.value)}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg text-black"
                  />
                  <input
                    type="text"
                    placeholder="Base URL"
                    value={carrierBaseURL}
                    onChange={(e) => setCarrierBaseURL(e.target.value)}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg text-black"
                  />
                  <div className="flex gap-2 justify-end">
                    <button
                      onClick={() => setShowCarrierForm(false)}
                      className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button
                      onClick={handleCreateCarrier}
                      className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
                    >
                      Add Carrier
                    </button>
                  </div>
                </div>
              </div>
            )}

            <div className="space-y-4">
              {carriers.length === 0 ? (
                <div className="bg-white rounded-lg shadow-sm p-12 text-center">
                  <AlertCircle className="w-12 h-12 text-gray-300 mx-auto mb-4" />
                  <p className="text-gray-500">No carriers configured</p>
                </div>
              ) : (
                carriers.map((carrier) => (
                  <div key={carrier.id} className="bg-white rounded-lg shadow-sm p-4 sm:p-6">
                    <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
                      <div>
                        <h3 className="font-semibold text-gray-900">{carrier.name}</h3>
                        <p className="text-sm text-gray-600 mt-1">
                          Supported Countries: {carrier.supportedCountries.join(', ') || 'All'}
                        </p>
                        <p className="text-xs text-gray-500 mt-2">API Key: {carrier.apiKey.substring(0, 10)}...</p>
                      </div>
                      <div className="flex gap-2">
                        <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium ${
                          carrier.isActive ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'
                        }`}>
                          {carrier.isActive ? 'Active' : 'Inactive'}
                        </span>
                        <button className="p-2 hover:bg-gray-100 rounded-lg transition">
                          <Edit className="w-4 h-4 text-gray-600" />
                        </button>
                        <button
                          onClick={() => handleDeleteCarrier(carrier.id)}
                          className="p-2 hover:bg-red-50 rounded-lg transition"
                        >
                          <Trash2 className="w-4 h-4 text-red-600" />
                        </button>
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {/* Rates Tab */}
        {activeTab === 'rates' && (
          <div>
            <h2 className="text-xl font-semibold text-gray-900 mb-6">Shipping Rates</h2>
            <div className="bg-white rounded-lg shadow-sm overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-gray-50 border-b border-gray-200">
                    <tr>
                      <th className="px-4 py-3 text-left font-semibold text-gray-900">Zone</th>
                      <th className="px-4 py-3 text-left font-semibold text-gray-900">Weight Range</th>
                      <th className="px-4 py-3 text-left font-semibold text-gray-900">Rate</th>
                      <th className="px-4 py-3 text-left font-semibold text-gray-900">Est. Days</th>
                      <th className="px-4 py-3 text-left font-semibold text-gray-900">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {rates.length === 0 ? (
                      <tr>
                        <td colSpan={5} className="px-4 py-8 text-center text-gray-500">
                          No shipping rates configured
                        </td>
                      </tr>
                    ) : (
                      rates.map((rate) => {
                        const zone = zones.find(z => z.id === rate.zoneId)
                        return (
                          <tr key={rate.id} className="border-b border-gray-200 hover:bg-gray-50">
                            <td className="px-4 py-3 text-gray-900 font-medium">{zone?.name}</td>
                            <td className="px-4 py-3 text-gray-600">
                              {rate.weightMin} - {rate.weightMax} lbs
                            </td>
                            <td className="px-4 py-3 text-gray-900 font-semibold">${rate.rate.toFixed(2)}</td>
                            <td className="px-4 py-3 text-gray-600">{rate.estimatedDays} days</td>
                            <td className="px-4 py-3">
                              <div className="flex gap-2">
                                <button className="p-1 hover:bg-gray-200 rounded transition">
                                  <Edit className="w-4 h-4 text-gray-600" />
                                </button>
                                <button className="p-1 hover:bg-red-50 rounded transition">
                                  <Trash2 className="w-4 h-4 text-red-600" />
                                </button>
                              </div>
                            </td>
                          </tr>
                        )
                      })
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter, useSearchParams } from 'next/navigation'
import toast from 'react-hot-toast'
import {
  Users,
  Filter,
  Search,
  Clock,
  DollarSign,
  _Crown,
  ChevronLeft,
  ChevronRight,
  _MoreVertical,
  X,
  Zap,
} from 'lucide-react'

interface Subscription {
  id: string
  email: string
  name: string
  tier: string
  price: number
  billingCycle: string
  subscriptionType: 'PAID' | 'TRIAL' | null
  expiresAt: string
  daysRemaining: number
  status: string
  startedAt: string
  totalEarnings: number
  joinedAt: string
}

interface Pagination {
  page: number
  limit: number
  total: number
  pages: number
  hasMore: boolean
}

export default function AdminSubscriptionsPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const searchParams = useSearchParams()

  const [subscriptions, setSubscriptions] = useState<Subscription[]>([])
  const [loading, setLoading] = useState(true)
  const [pagination, setPagination] = useState<Pagination>({ page: 1, limit: 20, total: 0, pages: 0, hasMore: false })
  const [filters, setFilters] = useState({
    tier: searchParams.get('tier') || '',
    status: searchParams.get('status') || 'ACTIVE',
    search: searchParams.get('search') || '',
  })
  const [sort, setSort] = useState<string>(searchParams.get('sort') || 'expiresAt')
  const [showFilters, setShowFilters] = useState(false)
  const [cancelingId, setCancelingId] = useState<string | null>(null)

  // Redirect non-admins
  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/auth/signin')
    } else if (session?.user?.role !== 'ADMIN') {
      router.push('/')
    }
  }, [status, session?.user?.role, router])

  // Fetch subscriptions
  useEffect(() => {
    fetchSubscriptions()
  }, [filters, sort, pagination.page])

  const fetchSubscriptions = async () => {
    try {
      setLoading(true)
      const params = new URLSearchParams({
        page: pagination.page.toString(),
        limit: pagination.limit.toString(),
        sort,
        ...(filters.tier && { tier: filters.tier }),
        ...(filters.status && { status: filters.status }),
        ...(filters.search && { search: filters.search }),
      })

      const res = await fetch(`/api/admin/subscriptions?${params}`)
      if (!res.ok) throw new Error('Failed to fetch')

      const data = await res.json()
      setSubscriptions(data.subscriptions)
      setPagination(data.pagination)
    } catch (error) {
      console.error('Error fetching subscriptions:', error)
      toast.error('Failed to load subscriptions')
    } finally {
      setLoading(false)
    }
  }

  const handleCancel = async (userId: string) => {
    if (!window.confirm('Cancel this subscription? This cannot be undone.')) return

    try {
      setCancelingId(userId)
      const res = await fetch('/api/admin/subscriptions/cancel', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, reason: 'Admin cancellation' })
      })

      if (!res.ok) throw new Error('Failed to cancel')

      toast.success('Subscription cancelled')
      fetchSubscriptions()
    } catch (error) {
      console.error('Error cancelling subscription:', error)
      toast.error('Failed to cancel subscription')
    } finally {
      setCancelingId(null)
    }
  }

  const getTierColor = (tier: string) => {
    switch (tier) {
      case 'STARTER':
        return 'bg-blue-100 text-blue-800'
      case 'PRO':
        return 'bg-purple-100 text-purple-800'
      case 'VIP':
        return 'bg-amber-100 text-amber-800'
      default:
        return 'bg-gray-100 text-gray-800'
    }
  }

  const getStatusColor = (status: string, type: string) => {
    if (status === 'EXPIRED') return 'bg-red-100 text-red-800'
    if (type === 'TRIAL') return 'bg-green-100 text-green-800'
    if (type === 'PAID') return 'bg-blue-100 text-blue-800'
    return 'bg-gray-100 text-gray-800'
  }

  if (status === 'loading') return <div className="p-8">Loading...</div>
  if (status === 'unauthenticated' || session?.user?.role !== 'ADMIN') return null

  return (
    <div className="min-h-screen bg-gray-50 p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-3xl font-bold text-gray-900">Subscriptions</h1>
              <p className="text-gray-600 mt-1">Manage all seller subscriptions</p>
            </div>
            <div className="text-right">
              <div className="text-3xl font-bold text-gray-900">{pagination.total}</div>
              <div className="text-sm text-gray-600">Active subscriptions</div>
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow mb-6 p-4">
          <div className="flex items-center gap-4 mb-4">
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
              <input
                type="text"
                placeholder="Search by email or name..."
                value={filters.search}
                onChange={(e) => {
                  setFilters({ ...filters, search: e.target.value })
                  setPagination({ ...pagination, page: 1 })
                }}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
              />
            </div>
            <button
              onClick={() => setShowFilters(!showFilters)}
              className="p-2 border border-gray-300 rounded-lg hover:bg-gray-50"
            >
              <Filter className="h-5 w-5" />
            </button>
          </div>

          {showFilters && (
            <div className="grid grid-cols-3 gap-4 pt-4 border-t border-gray-200">
              {/* Tier Filter */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Subscription Tier</label>
                <select
                  value={filters.tier}
                  onChange={(e) => {
                    setFilters({ ...filters, tier: e.target.value })
                    setPagination({ ...pagination, page: 1 })
                  }}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                >
                  <option value="">All Tiers</option>
                  <option value="STARTER">Starter</option>
                  <option value="PRO">Pro</option>
                  <option value="VIP">VIP</option>
                </select>
              </div>

              {/* Status Filter */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Status</label>
                <select
                  value={filters.status}
                  onChange={(e) => {
                    setFilters({ ...filters, status: e.target.value })
                    setPagination({ ...pagination, page: 1 })
                  }}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                >
                  <option value="ACTIVE">Active</option>
                  <option value="TRIAL">Trial Only</option>
                  <option value="EXPIRED">Expired</option>
                </select>
              </div>

              {/* Sort */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Sort By</label>
                <select
                  value={sort}
                  onChange={(e) => {
                    setSort(e.target.value)
                    setPagination({ ...pagination, page: 1 })
                  }}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                >
                  <option value="expiresAt">Expiry Date</option>
                  <option value="subscriptionTier">Tier</option>
                  <option value="createdAt">Newest</option>
                </select>
              </div>
            </div>
          )}
        </div>

        {/* Table */}
        <div className="bg-white rounded-lg shadow overflow-hidden">
          {loading ? (
            <div className="p-8 text-center text-gray-500">Loading...</div>
          ) : subscriptions.length === 0 ? (
            <div className="p-8 text-center text-gray-500">
              <Users className="h-12 w-12 mx-auto mb-3 opacity-50" />
              <p>No subscriptions found</p>
            </div>
          ) : (
            <>
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead className="bg-gray-50 border-b border-gray-200">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-700 uppercase">Seller</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-700 uppercase">Tier</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-700 uppercase">Type</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-700 uppercase">Price</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-700 uppercase">Expires</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-700 uppercase">Days Left</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-700 uppercase">Earnings</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-700 uppercase">Action</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200">
                    {subscriptions.map((sub) => (
                      <tr key={sub.id} className="hover:bg-gray-50">
                        <td className="px-6 py-4">
                          <div>
                            <div className="font-medium text-gray-900">{sub.name}</div>
                            <div className="text-sm text-gray-600">{sub.email}</div>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <span className={`px-3 py-1 rounded-full text-sm font-medium ${getTierColor(sub.tier)}`}>
                            {sub.tier || 'None'}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                          <span className={`px-3 py-1 rounded-full text-sm font-medium ${getStatusColor(sub.status || 'EXPIRED', sub.subscriptionType || 'PAID')}`}>
                            {sub.subscriptionType === 'PAID' ? '≡ƒÆ│ Paid' : sub.subscriptionType === 'TRIAL' ? '≡ƒÄü Trial' : 'Inactive'}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-1">
                            <DollarSign className="h-4 w-4 text-gray-400" />
                            <span className="font-medium">${sub.price || 0}</span>
                            {sub.billingCycle && <span className="text-xs text-gray-500">/{sub.billingCycle}</span>}
                          </div>
                        </td>
                        <td className="px-6 py-4 text-sm">
                          {sub.expiresAt ? new Date(sub.expiresAt).toLocaleDateString() : 'N/A'}
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-2">
                            <Clock className="h-4 w-4 text-gray-400" />
                            <span className={sub.daysRemaining <= 7 ? 'text-red-600 font-medium' : 'text-gray-900'}>
                              {sub.daysRemaining} days
                            </span>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-1">
                            <Zap className="h-4 w-4 text-yellow-500" />
                            <span className="font-medium">${sub.totalEarnings.toFixed(2)}</span>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <button
                            onClick={() => handleCancel(sub.id)}
                            disabled={cancelingId === sub.id}
                            className="p-2 hover:bg-red-50 rounded-lg text-red-600 disabled:opacity-50"
                            title="Cancel subscription"
                          >
                            <X className="h-5 w-5" />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {/* Pagination */}
              <div className="px-6 py-4 border-t border-gray-200 flex items-center justify-between">
                <div className="text-sm text-gray-600">
                  Showing {(pagination.page - 1) * pagination.limit + 1} to {Math.min(pagination.page * pagination.limit, pagination.total)} of {pagination.total}
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={() => setPagination({ ...pagination, page: pagination.page - 1 })}
                    disabled={pagination.page === 1}
                    className="p-2 border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50"
                  >
                    <ChevronLeft className="h-5 w-5" />
                  </button>
                  <div className="flex items-center gap-2">
                    {Array.from({ length: Math.min(5, pagination.pages) }, (_, i) => {
                      const pageNum = Math.max(1, pagination.page - 2) + i
                      if (pageNum > pagination.pages) return null
                      return (
                        <button
                          key={pageNum}
                          onClick={() => setPagination({ ...pagination, page: pageNum })}
                          className={`px-3 py-1 rounded-lg ${
                            pageNum === pagination.page
                              ? 'bg-purple-600 text-white'
                              : 'border border-gray-300 hover:bg-gray-50'
                          }`}
                        >
                          {pageNum}
                        </button>
                      )
                    })}
                  </div>
                  <button
                    onClick={() => setPagination({ ...pagination, page: pagination.page + 1 })}
                    disabled={!pagination.hasMore}
                    className="p-2 border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50"
                  >
                    <ChevronRight className="h-5 w-5" />
                  </button>
                </div>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback, use } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import Link from 'next/link'
import { 
  ArrowLeft, 
  Mail, 
  Phone, 
  MapPin, 
  Calendar, 
  BadgeCheck,
  Package,
  ShoppingBag,
  Palette,
  MessageSquare,
  Send,
  DollarSign,
  Star,
  Globe,
  Pencil,
  Trash2,
  X
} from 'lucide-react'
import toast from 'react-hot-toast'

interface UserDetails {
  id: string
  name: string | null
  displayName: string | null
  email: string
  phone: string
  image: string | null
  role: string
  isVerified: boolean
  verificationStatus: string
  designerTier: string | null
  totalSales: number
  totalEarnings: number
  avgRating: number
  trustScore: number
  bio: string | null
  location: string | null
  website: string | null
  createdAt: string
  acceptsCommissions: boolean
  commissionStatus: string
  sellerAccount: {
    bankName: string
    accountName: string
    accountNumber: string
    paystackSubaccountCode: string | null
    createdAt: string
  } | null
}

interface OrderItem {
  id: string
  price: number
  design?: {
    id: string
    title: string
  }
}

interface DesignOrder {
  id: string
  orderNumber: string
  status: string
  totalAmount: number
  orderType: string
  paymentMethod: string | null
  createdAt: string
  paidAt: string | null
  customer: {
    id: string
    name: string | null
    email: string
  }
  items: OrderItem[]
}

interface BoutiqueOrder {
  id: string
  orderNumber: string
  status: string
  total: number
  currency: string
  fulfillmentMethod: string
  paymentMethod: string | null
  trackingNumber: string | null
  createdAt: string
  paidAt: string | null
  shippedAt: string | null
  deliveredAt: string | null
  buyer: {
    id: string
    name: string | null
    email: string
  }
  product: {
    id: string
    title: string
  }
}

interface Commission {
  id: string
  status: string
  isPaid: boolean
  designerQuote: number | null
  title: string
  description: string
  createdAt: string
  completedAt: string | null
  requesterId: string
  requesterName: string
  requesterEmail: string
}

interface Message {
  id: string
  content: string
  createdAt: string
  readAt: string | null
  sender: {
    id: string
    name: string | null
    role: string
    image: string | null
  }
}

interface PageProps {
  params: Promise<{ id: string }>
}

export default function AdminUserDetailPage({ params }: PageProps) {
  const { id } = use(params)
  const router = useRouter()
  const searchParams = useSearchParams()
  const initialTab = searchParams.get('tab') || 'overview'
  
  const [user, setUser] = useState<UserDetails | null>(null)
  const [stats, setStats] = useState<Record<string, number>>({})
  const [orders, setOrders] = useState<{
    designs: DesignOrder[]
    pod: DesignOrder[]
    boutique: BoutiqueOrder[]
    commissions: Commission[]
  }>({ designs: [], pod: [], boutique: [], commissions: [] })
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState(initialTab)
  
  // Messaging state
  const [messages, setMessages] = useState<Message[]>([])
  const [newMessage, setNewMessage] = useState('')
  const [sendingMessage, setSendingMessage] = useState(false)
  const [editingMessage, setEditingMessage] = useState<Message | null>(null)
  const [editContent, setEditContent] = useState('')
  const [savingEdit, setSavingEdit] = useState(false)
  const [deletingMessage, setDeletingMessage] = useState<string | null>(null)

  const fetchUserDetails = useCallback(async () => {
    setLoading(true)
    try {
      const response = await fetch(`/api/admin/users/${id}`)
      const data = await response.json()

      if (response.ok) {
        setUser(data.user)
        setStats(data.stats)
        setOrders(data.orders)
      } else {
        toast.error(data.error || 'Failed to fetch user details')
        if (response.status === 404) {
          router.push('/admin/users')
        }
      }
    } catch (error) {
      console.error('Error fetching user details:', error)
      toast.error('Failed to fetch user details')
    } finally {
      setLoading(false)
    }
  }, [id, router])

  const fetchMessages = useCallback(async () => {
    try {
      const response = await fetch(`/api/admin/users/${id}/message`)
      const data = await response.json()

      if (response.ok) {
        setMessages(data.messages)
      }
    } catch (error) {
      console.error('Error fetching messages:', error)
    }
  }, [id])

  useEffect(() => {
    fetchUserDetails()
  }, [fetchUserDetails])

  useEffect(() => {
    if (activeTab === 'message') {
      fetchMessages()
    }
  }, [activeTab, fetchMessages])

  const sendMessage = async () => {
    if (!newMessage.trim()) return

    setSendingMessage(true)
    try {
      const response = await fetch(`/api/admin/users/${id}/message`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ content: newMessage }),
      })

      const data = await response.json()

      if (response.ok) {
        setMessages([...messages, data.message])
        setNewMessage('')
        toast.success('Message sent')
      } else {
        toast.error(data.error || 'Failed to send message')
      }
    } catch (error) {
      console.error('Error sending message:', error)
      toast.error('Failed to send message')
    } finally {
      setSendingMessage(false)
    }
  }

  const handleEditMessage = (msg: Message) => {
    setEditingMessage(msg)
    setEditContent(msg.content)
  }

  const saveMessageEdit = async () => {
    if (!editingMessage || !editContent.trim()) return

    setSavingEdit(true)
    try {
      const response = await fetch(`/api/admin/users/${id}/message`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          messageId: editingMessage.id,
          content: editContent 
        }),
      })

      const data = await response.json()

      if (response.ok) {
        setMessages(messages.map(m => 
          m.id === editingMessage.id ? { ...m, content: editContent } : m
        ))
        setEditingMessage(null)
        toast.success('Message updated')
      } else {
        toast.error(data.error || 'Failed to update message')
      }
    } catch (error) {
      console.error('Error updating message:', error)
      toast.error('Failed to update message')
    } finally {
      setSavingEdit(false)
    }
  }

  const deleteMessage = async (messageId: string) => {
    if (!confirm('Are you sure you want to delete this message?')) return

    setDeletingMessage(messageId)
    try {
      const response = await fetch(`/api/admin/users/${id}/message?messageId=${messageId}`, {
        method: 'DELETE',
      })

      const data = await response.json()

      if (response.ok) {
        setMessages(messages.filter(m => m.id !== messageId))
        toast.success('Message deleted')
      } else {
        toast.error(data.error || 'Failed to delete message')
      }
    } catch (error) {
      console.error('Error deleting message:', error)
      toast.error('Failed to delete message')
    } finally {
      setDeletingMessage(null)
    }
  }

  const getTierBadge = (tier: string | null) => {
    if (!tier) return null
    const colors: Record<string, string> = {
      'DESIGNER': 'bg-gray-100 text-gray-800',
      'GOLD_DESIGNER': 'bg-yellow-100 text-yellow-800',
      'VIP_DESIGNER': 'bg-purple-100 text-purple-800',
      'VVIP_DESIGNER': 'bg-indigo-100 text-indigo-800',
    }
    const labels: Record<string, string> = {
      'DESIGNER': 'Designer',
      'GOLD_DESIGNER': 'Gold Designer',
      'VIP_DESIGNER': 'VIP Designer',
      'VVIP_DESIGNER': 'VVIP Designer',
    }
    return (
      <span className={`inline-flex items-center px-2 py-0.5 rounded text-sm font-medium ${colors[tier] || 'bg-gray-100'}`}>
        {labels[tier] || tier}
      </span>
    )
  }

  const getStatusBadge = (status: string) => {
    const colors: Record<string, string> = {
      'PENDING': 'bg-yellow-100 text-yellow-800',
      'PAID': 'bg-green-100 text-green-800',
      'PROCESSING': 'bg-blue-100 text-blue-800',
      'SHIPPED': 'bg-purple-100 text-purple-800',
      'DELIVERED': 'bg-green-100 text-green-800',
      'COMPLETED': 'bg-green-100 text-green-800',
      'CANCELLED': 'bg-red-100 text-red-800',
      'REFUNDED': 'bg-gray-100 text-gray-800',
      'IN_PROGRESS': 'bg-blue-100 text-blue-800',
      'REVISION': 'bg-orange-100 text-orange-800',
      'ACCEPTED': 'bg-green-100 text-green-800',
    }
    return (
      <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${colors[status] || 'bg-gray-100 text-gray-800'}`}>
        {status.replace(/_/g, ' ')}
      </span>
    )
  }

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto px-3 py-4 sm:p-6">
        <div className="animate-pulse">
          <div className="h-6 sm:h-8 bg-gray-200 rounded w-1/4 mb-4 sm:mb-6"></div>
          <div className="h-48 sm:h-64 bg-gray-200 rounded"></div>
        </div>
      </div>
    )
  }

  if (!user) {
    return (
      <div className="max-w-7xl mx-auto px-3 py-4 sm:p-6">
        <div className="text-center py-8 sm:py-12">
          <p className="text-sm sm:text-base text-gray-900">User not found</p>
          <Link href="/admin/users" className="text-sm sm:text-base text-indigo-600 hover:underline mt-2 inline-block">
            Back to Users
          </Link>
        </div>
      </div>
    )
  }

  const tabs = [
    { id: 'overview', label: 'Overview' },
    { id: 'designs', label: `Design Orders (${stats.totalDesignOrders || 0})` },
    { id: 'pod', label: `POD Orders (${stats.totalPodOrders || 0})` },
    { id: 'boutique', label: `Boutique (${stats.totalBoutiqueOrders || 0})` },
    { id: 'commissions', label: `Commissions (${stats.totalCommissions || 0})` },
    { id: 'message', label: 'Message' },
  ]

  return (
    <div className="max-w-7xl mx-auto px-3 py-4 sm:p-6">
      {/* Header */}
      <div className="mb-4 sm:mb-6">
        <button
          onClick={() => router.push('/admin/users')}
          className="flex items-center gap-1.5 sm:gap-2 text-xs sm:text-sm text-gray-900 hover:text-indigo-600 mb-3 sm:mb-4"
        >
          <ArrowLeft className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
          Back to Users
        </button>

        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-3 sm:p-6">
          <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-3 sm:gap-4">
            <div className="flex items-center gap-3 sm:gap-4">
              <div className="w-12 h-12 sm:w-16 sm:h-16 bg-indigo-100 rounded-full flex items-center justify-center flex-shrink-0">
                {user.image ? (
                  <img src={user.image} alt="" className="w-12 h-12 sm:w-16 sm:h-16 rounded-full object-cover" />
                ) : (
                  <span className="text-lg sm:text-2xl font-bold text-indigo-600">
                    {(user.name || user.email)[0].toUpperCase()}
                  </span>
                )}
              </div>
              <div className="min-w-0">
                <div className="flex items-center gap-1.5 sm:gap-2 flex-wrap">
                  <h1 className="text-base sm:text-2xl font-bold text-gray-900 truncate">
                    {user.name || user.displayName || 'Unknown User'}
                  </h1>
                  {user.isVerified && <BadgeCheck className="w-4 h-4 sm:w-5 sm:h-5 text-blue-500 flex-shrink-0" />}
                  {user.role === 'ADMIN' && (
                    <span className="text-[10px] sm:text-xs bg-red-100 text-red-800 px-1.5 sm:px-2 py-0.5 rounded">Admin</span>
                  )}
                </div>
                <div className="flex items-center gap-2 sm:gap-4 mt-1 flex-wrap">
                  {getTierBadge(user.designerTier)}
                  {user.acceptsCommissions && (
                    <span className={`text-[10px] sm:text-xs ${user.commissionStatus === 'OPEN' ? 'text-green-600' : 'text-gray-900'}`}>
                      Commissions: {user.commissionStatus}
                    </span>
                  )}
                </div>
              </div>
            </div>

            <div className="text-left sm:text-right flex sm:block items-center gap-3 sm:gap-0 border-t sm:border-t-0 pt-2 sm:pt-0 mt-1 sm:mt-0">
              <div className="text-lg sm:text-2xl font-bold text-gray-900">Γéª{user.totalEarnings.toLocaleString()}</div>
              <div className="text-xs sm:text-sm text-gray-900">{user.totalSales} total sales</div>
              {user.avgRating > 0 && (
                <div className="flex items-center sm:justify-end gap-1 mt-0.5 sm:mt-1">
                  <Star className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-yellow-500 fill-yellow-500" />
                  <span className="text-xs sm:text-sm text-gray-900">{user.avgRating.toFixed(1)}</span>
                </div>
              )}
            </div>
          </div>

          {/* Contact Info */}
          <div className="mt-3 sm:mt-6 grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-2 sm:gap-4">
            <div className="flex items-center gap-1.5 sm:gap-2 text-gray-900">
              <Mail className="w-3.5 h-3.5 sm:w-4 sm:h-4 flex-shrink-0" />
              <span className="text-xs sm:text-sm truncate">{user.email}</span>
            </div>
            <div className="flex items-center gap-1.5 sm:gap-2 text-gray-900">
              <Phone className="w-3.5 h-3.5 sm:w-4 sm:h-4 flex-shrink-0" />
              <span className="text-xs sm:text-sm">{user.phone}</span>
            </div>
            {user.location && (
              <div className="flex items-center gap-1.5 sm:gap-2 text-gray-900">
                <MapPin className="w-3.5 h-3.5 sm:w-4 sm:h-4 flex-shrink-0" />
                <span className="text-xs sm:text-sm truncate">{user.location}</span>
              </div>
            )}
            <div className="flex items-center gap-1.5 sm:gap-2 text-gray-900">
              <Calendar className="w-3.5 h-3.5 sm:w-4 sm:h-4 flex-shrink-0" />
              <span className="text-xs sm:text-sm">Joined {new Date(user.createdAt).toLocaleDateString()}</span>
            </div>
            {user.website && (
              <div className="flex items-center gap-1.5 sm:gap-2 text-gray-900">
                <Globe className="w-3.5 h-3.5 sm:w-4 sm:h-4 flex-shrink-0" />
                <a href={user.website} target="_blank" rel="noopener noreferrer" className="text-xs sm:text-sm text-indigo-600 hover:underline truncate">
                  {user.website}
                </a>
              </div>
            )}
          </div>

          {/* Bank Details (if seller) */}
          {user.sellerAccount && (
            <div className="mt-3 sm:mt-4 p-2.5 sm:p-4 bg-gray-50 rounded-lg">
              <h3 className="text-xs sm:text-sm font-medium text-gray-900 mb-1.5 sm:mb-2">Bank Details</h3>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-1.5 sm:gap-4 text-xs sm:text-sm">
                <div className="text-gray-900">
                  <span className="text-gray-600">Bank:</span> {user.sellerAccount.bankName}
                </div>
                <div className="text-gray-900">
                  <span className="text-gray-600">Account:</span> {user.sellerAccount.accountNumber}
                </div>
                <div className="text-gray-900">
                  <span className="text-gray-600">Name:</span> {user.sellerAccount.accountName}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-200 mb-4 sm:mb-6">
        <nav className="flex gap-1 sm:gap-4 overflow-x-auto pb-0.5">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`px-2 sm:px-4 py-1.5 sm:py-2 text-xs sm:text-sm font-medium border-b-2 whitespace-nowrap ${
                activeTab === tab.id
                  ? 'border-indigo-600 text-indigo-600'
                  : 'border-transparent text-gray-900 hover:text-indigo-600'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </nav>
      </div>

      {/* Tab Content */}
      <div className="bg-white rounded-lg shadow-sm border border-gray-200">
        {/* Overview Tab */}
        {activeTab === 'overview' && (
          <div className="p-3 sm:p-6">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-2 sm:gap-6">
              <div className="bg-indigo-50 rounded-lg p-2.5 sm:p-4 text-center">
                <Palette className="w-6 h-6 sm:w-8 sm:h-8 mx-auto text-indigo-600" />
                <div className="text-lg sm:text-2xl font-bold text-gray-900 mt-1 sm:mt-2">{stats.totalDesigns}</div>
                <div className="text-xs sm:text-sm text-gray-900">Designs</div>
              </div>
              <div className="bg-green-50 rounded-lg p-2.5 sm:p-4 text-center">
                <Package className="w-6 h-6 sm:w-8 sm:h-8 mx-auto text-green-600" />
                <div className="text-lg sm:text-2xl font-bold text-gray-900 mt-1 sm:mt-2">{stats.totalBoutiqueProducts}</div>
                <div className="text-xs sm:text-sm text-gray-900">Boutique</div>
              </div>
              <div className="bg-blue-50 rounded-lg p-2.5 sm:p-4 text-center">
                <ShoppingBag className="w-6 h-6 sm:w-8 sm:h-8 mx-auto text-blue-600" />
                <div className="text-lg sm:text-2xl font-bold text-gray-900 mt-1 sm:mt-2">
                  {(stats.totalDesignOrders || 0) + (stats.totalPodOrders || 0) + (stats.totalBoutiqueOrders || 0)}
                </div>
                <div className="text-xs sm:text-sm text-gray-900">Orders</div>
              </div>
              <div className="bg-purple-50 rounded-lg p-2.5 sm:p-4 text-center">
                <DollarSign className="w-6 h-6 sm:w-8 sm:h-8 mx-auto text-purple-600" />
                <div className="text-lg sm:text-2xl font-bold text-gray-900 mt-1 sm:mt-2">Γéª{user.totalEarnings.toLocaleString()}</div>
                <div className="text-xs sm:text-sm text-gray-900">Earnings</div>
              </div>
            </div>

            {user.bio && (
              <div className="mt-4 sm:mt-6">
                <h3 className="text-xs sm:text-sm font-medium text-gray-900 mb-1.5 sm:mb-2">Bio</h3>
                <p className="text-xs sm:text-sm text-gray-900">{user.bio}</p>
              </div>
            )}
          </div>
        )}

        {/* Design Orders Tab */}
        {activeTab === 'designs' && (
          <div className="overflow-x-auto">
            {orders.designs.length === 0 ? (
              <div className="p-6 sm:p-8 text-center text-xs sm:text-sm text-gray-900">No design orders yet</div>
            ) : (
              <table className="w-full">
                <thead className="bg-gray-50 text-left text-xs sm:text-sm text-gray-900">
                  <tr>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Order #</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Customer</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3 hidden sm:table-cell">Items</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Amount</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Status</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3 hidden md:table-cell">Date</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {orders.designs.map(order => (
                    <tr key={order.id} className="hover:bg-gray-50">
                      <td className="px-2 sm:px-4 py-2 sm:py-3">
                        <span className="font-mono text-[10px] sm:text-sm text-gray-900">{order.orderNumber}</span>
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3">
                        <div className="text-xs sm:text-sm font-medium text-gray-900">{order.customer.name || 'Unknown'}</div>
                        <div className="text-[10px] sm:text-xs text-gray-600 truncate max-w-[100px] sm:max-w-none">{order.customer.email}</div>
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3 text-xs sm:text-sm text-gray-900 hidden sm:table-cell">
                        <span className="truncate block max-w-[150px]">{order.items.map(item => item.design?.title).join(', ')}</span>
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3 font-medium text-xs sm:text-sm text-gray-900">Γéª{order.totalAmount.toLocaleString()}</td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3">{getStatusBadge(order.status)}</td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3 text-xs sm:text-sm text-gray-900 hidden md:table-cell">
                        {new Date(order.createdAt).toLocaleDateString()}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        )}

        {/* POD Orders Tab */}
        {activeTab === 'pod' && (
          <div className="overflow-x-auto">
            {orders.pod.length === 0 ? (
              <div className="p-6 sm:p-8 text-center text-xs sm:text-sm text-gray-900">No POD orders yet</div>
            ) : (
              <table className="w-full">
                <thead className="bg-gray-50 text-left text-xs sm:text-sm text-gray-900">
                  <tr>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Order #</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Customer</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3 hidden sm:table-cell">Product</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Amount</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Status</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3 hidden md:table-cell">Date</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {orders.pod.map(order => (
                    <tr key={order.id} className="hover:bg-gray-50">
                      <td className="px-2 sm:px-4 py-2 sm:py-3">
                        <span className="font-mono text-[10px] sm:text-sm text-gray-900">{order.orderNumber}</span>
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3">
                        <div className="text-xs sm:text-sm font-medium text-gray-900">{order.customer.name || 'Unknown'}</div>
                        <div className="text-[10px] sm:text-xs text-gray-600 truncate max-w-[100px] sm:max-w-none">{order.customer.email}</div>
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3 text-xs sm:text-sm text-gray-900 hidden sm:table-cell">
                        <span className="truncate block max-w-[150px]">{order.items.map(item => item.design?.title).join(', ')}</span>
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3 font-medium text-xs sm:text-sm text-gray-900">Γéª{order.totalAmount.toLocaleString()}</td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3">{getStatusBadge(order.status)}</td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3 text-xs sm:text-sm text-gray-900 hidden md:table-cell">
                        {new Date(order.createdAt).toLocaleDateString()}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        )}

        {/* Boutique Orders Tab */}
        {activeTab === 'boutique' && (
          <div className="overflow-x-auto">
            {orders.boutique.length === 0 ? (
              <div className="p-6 sm:p-8 text-center text-xs sm:text-sm text-gray-900">No boutique orders yet</div>
            ) : (
              <table className="w-full">
                <thead className="bg-gray-50 text-left text-xs sm:text-sm text-gray-900">
                  <tr>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Order #</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Buyer</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3 hidden sm:table-cell">Product</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Amount</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Status</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3 hidden lg:table-cell">Tracking</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3 hidden md:table-cell">Date</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {orders.boutique.map(order => (
                    <tr key={order.id} className="hover:bg-gray-50">
                      <td className="px-2 sm:px-4 py-2 sm:py-3">
                        <span className="font-mono text-[10px] sm:text-sm text-gray-900">{order.orderNumber}</span>
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3">
                        <div className="text-xs sm:text-sm font-medium text-gray-900">{order.buyer.name || 'Unknown'}</div>
                        <div className="text-[10px] sm:text-xs text-gray-600 truncate max-w-[100px] sm:max-w-none">{order.buyer.email}</div>
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3 text-xs sm:text-sm text-gray-900 hidden sm:table-cell">
                        <span className="truncate block max-w-[150px]">{order.product.title}</span>
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3 font-medium text-xs sm:text-sm text-gray-900">
                        {order.currency === 'NGN' ? 'Γéª' : '$'}{order.total.toLocaleString()}
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3">{getStatusBadge(order.status)}</td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3 text-xs sm:text-sm text-gray-900 hidden lg:table-cell">
                        {order.trackingNumber || '-'}
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3 text-xs sm:text-sm text-gray-900 hidden md:table-cell">
                        {new Date(order.createdAt).toLocaleDateString()}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        )}

        {/* Commissions Tab */}
        {activeTab === 'commissions' && (
          <div className="overflow-x-auto">
            {orders.commissions.length === 0 ? (
              <div className="p-6 sm:p-8 text-center text-xs sm:text-sm text-gray-900">No commissions yet</div>
            ) : (
              <table className="w-full">
                <thead className="bg-gray-50 text-left text-xs sm:text-sm text-gray-900">
                  <tr>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">ID</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Client</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3 hidden sm:table-cell">Title</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Quote</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3">Status</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3 hidden md:table-cell">Paid</th>
                    <th className="px-2 sm:px-4 py-2 sm:py-3 hidden lg:table-cell">Date</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {orders.commissions.map(commission => (
                    <tr key={commission.id} className="hover:bg-gray-50">
                      <td className="px-2 sm:px-4 py-2 sm:py-3">
                        <span className="font-mono text-[10px] sm:text-sm text-gray-900">{commission.id.slice(-8)}</span>
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3">
                        <div className="text-xs sm:text-sm font-medium text-gray-900">{commission.requesterName || 'Unknown'}</div>
                        <div className="text-[10px] sm:text-xs text-gray-600 truncate max-w-[100px] sm:max-w-none">{commission.requesterEmail}</div>
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3 text-xs sm:text-sm text-gray-900 max-w-xs truncate hidden sm:table-cell">{commission.title}</td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3 font-medium text-xs sm:text-sm text-gray-900">
                        {commission.designerQuote ? `Γéª${commission.designerQuote.toLocaleString()}` : '-'}
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3">{getStatusBadge(commission.status)}</td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3 hidden md:table-cell">
                        {commission.isPaid ? (
                          <span className="text-green-600 text-[10px] sm:text-sm">Γ£ô Paid</span>
                        ) : (
                          <span className="text-gray-400 text-[10px] sm:text-sm">Unpaid</span>
                        )}
                      </td>
                      <td className="px-2 sm:px-4 py-2 sm:py-3 text-xs sm:text-sm text-gray-900 hidden lg:table-cell">
                        {new Date(commission.createdAt).toLocaleDateString()}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        )}

        {/* Message Tab */}
        {activeTab === 'message' && (
          <div className="flex flex-col h-[350px] sm:h-[500px]">
            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-3 sm:p-4 space-y-3 sm:space-y-4">
              {messages.length === 0 ? (
                <div className="text-center text-gray-900 py-8 sm:py-12">
                  <MessageSquare className="w-8 h-8 sm:w-12 sm:h-12 mx-auto text-gray-300 mb-3 sm:mb-4" />
                  <p className="text-xs sm:text-sm">No messages yet. Start a conversation with this user.</p>
                </div>
              ) : (
                messages.map(msg => (
                  <div
                    key={msg.id}
                    className={`flex ${msg.sender.role === 'ADMIN' ? 'justify-end' : 'justify-start'}`}
                  >
                    <div className="group relative">
                      <div
                        className={`max-w-[85%] sm:max-w-[70%] rounded-lg p-2 sm:p-3 ${
                          msg.sender.role === 'ADMIN'
                            ? 'bg-indigo-600 text-white'
                            : 'bg-gray-100 text-gray-900'
                        }`}
                      >
                        <p className="text-xs sm:text-sm">{msg.content}</p>
                        <p className={`text-[10px] sm:text-xs mt-1 ${msg.sender.role === 'ADMIN' ? 'text-indigo-200' : 'text-gray-500'}`}>
                          {new Date(msg.createdAt).toLocaleString()}
                        </p>
                      </div>
                      {/* Edit/Delete buttons for admin messages */}
                      {msg.sender.role === 'ADMIN' && (
                        <div className="absolute -top-2 -right-2 opacity-0 group-hover:opacity-100 transition-opacity flex gap-1">
                          <button
                            onClick={() => handleEditMessage(msg)}
                            className="p-1 bg-white rounded-full shadow-md text-gray-600 hover:text-indigo-600"
                            title="Edit message"
                          >
                            <Pencil className="w-3 h-3" />
                          </button>
                          <button
                            onClick={() => deleteMessage(msg.id)}
                            disabled={deletingMessage === msg.id}
                            className="p-1 bg-white rounded-full shadow-md text-gray-600 hover:text-red-600 disabled:opacity-50"
                            title="Delete message"
                          >
                            {deletingMessage === msg.id ? (
                              <div className="w-3 h-3 border border-red-500 border-t-transparent rounded-full animate-spin" />
                            ) : (
                              <Trash2 className="w-3 h-3" />
                            )}
                          </button>
                        </div>
                      )}
                    </div>
                  </div>
                ))
              )}
            </div>

            {/* Message Input */}
            <div className="border-t border-gray-200 p-3 sm:p-4">
              <div className="flex gap-2">
                <input
                  type="text"
                  value={newMessage}
                  onChange={(e) => setNewMessage(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && sendMessage()}
                  placeholder="Type a message..."
                  className="flex-1 px-3 sm:px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-xs sm:text-sm text-gray-900"
                />
                <button
                  onClick={sendMessage}
                  disabled={sendingMessage || !newMessage.trim()}
                  className="px-3 sm:px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-1 sm:gap-2 text-xs sm:text-sm"
                >
                  <Send className="w-3 h-3 sm:w-4 sm:h-4" />
                  <span className="hidden sm:inline">{sendingMessage ? 'Sending...' : 'Send'}</span>
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Edit Message Modal */}
        {editingMessage && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-3 sm:p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-md">
              <div className="p-3 sm:p-4 border-b border-gray-200 flex items-center justify-between">
                <h3 className="font-semibold text-sm sm:text-base text-gray-900">Edit Message</h3>
                <button
                  onClick={() => setEditingMessage(null)}
                  className="text-gray-400 hover:text-gray-600"
                  aria-label="Close modal"
                >
                  <X className="w-4 h-4 sm:w-5 sm:h-5" />
                </button>
              </div>
              <div className="p-3 sm:p-4">
                <textarea
                  value={editContent}
                  onChange={(e) => setEditContent(e.target.value)}
                  rows={4}
                  className="w-full px-3 sm:px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 resize-none text-xs sm:text-sm text-gray-900"
                  placeholder="Enter message..."
                />
              </div>
              <div className="p-3 sm:p-4 border-t border-gray-200 flex gap-2 sm:gap-3">
                <button
                  onClick={() => setEditingMessage(null)}
                  className="flex-1 py-2 bg-gray-200 text-gray-800 rounded-lg hover:bg-gray-300 transition font-medium text-xs sm:text-sm"
                >
                  Cancel
                </button>
                <button
                  onClick={saveMessageEdit}
                  disabled={savingEdit || !editContent.trim()}
                  className="flex-1 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition font-medium disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 text-xs sm:text-sm"
                >
                  {savingEdit ? (
                    <>
                      <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                      Saving...
                    </>
                  ) : (
                    'Save Changes'
                  )}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { 
  Search, 
  Filter, 
  Users, 
  User as UserIcon, 
  Mail, 
  MessageSquare, 
  ChevronDown, 
  ChevronLeft, 
  ChevronRight,
  Megaphone,
  BadgeCheck,
  Phone,
  ShoppingBag,
  Package
} from 'lucide-react'
import toast from 'react-hot-toast'

interface User {
  id: string
  name: string | null
  email: string
  phone: string
  displayName: string | null
  image: string | null
  role: string
  isVerified: boolean
  designerTier: string | null
  totalSales: number
  totalEarnings: number
  createdAt: string
  isSeller: boolean
  designCount: number
  orderCount: number
  boutiqueProductCount: number
  boutiqueOrderCount: number
}

interface Pagination {
  page: number
  limit: number
  total: number
  pages: number
}

const USER_TYPES = [
  { value: 'all', label: 'All Users' },
  { value: 'users', label: 'Buyers Only' },
  { value: 'sellers', label: 'All Sellers' },
  { value: 'designers', label: 'Design Sellers' },
  { value: 'boutique_sellers', label: 'Boutique Sellers' },
]

const DESIGNER_TIERS = [
  { value: '', label: 'All Tiers' },
  { value: 'DESIGNER', label: 'Designer' },
  { value: 'GOLD_DESIGNER', label: 'Gold Designer' },
  { value: 'VIP_DESIGNER', label: 'VIP Designer' },
  { value: 'VVIP_DESIGNER', label: 'VVIP Designer' },
]

const VERIFICATION_STATUS = [
  { value: '', label: 'All Status' },
  { value: 'verified', label: 'Verified' },
  { value: 'unverified', label: 'Unverified' },
]

export default function AdminUsersPage() {
  const router = useRouter()
  const [users, setUsers] = useState<User[]>([])
  const [pagination, setPagination] = useState<Pagination>({ page: 1, limit: 20, total: 0, pages: 0 })
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [orderSearch, setOrderSearch] = useState('')
  const [type, setType] = useState('all')
  const [tier, setTier] = useState('')
  const [status, setStatus] = useState('')
  const [showFilters, setShowFilters] = useState(false)
  const [showBroadcast, setShowBroadcast] = useState(false)

  const fetchUsers = useCallback(async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        page: pagination.page.toString(),
        limit: pagination.limit.toString(),
        search,
        orderId: orderSearch,
        type,
        tier,
        status,
      })

      const response = await fetch(`/api/admin/users?${params}`)
      const data = await response.json()

      if (response.ok) {
        setUsers(data.users)
        setPagination(prev => ({ ...prev, ...data.pagination }))
      } else {
        toast.error(data.error || 'Failed to fetch users')
      }
    } catch (error) {
      console.error('Error fetching users:', error)
      toast.error('Failed to fetch users')
    } finally {
      setLoading(false)
    }
  }, [pagination.page, pagination.limit, search, orderSearch, type, tier, status])

  useEffect(() => {
    fetchUsers()
  }, [fetchUsers])

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault()
    setPagination(prev => ({ ...prev, page: 1 }))
    fetchUsers()
  }

  const getTierBadge = (tier: string | null) => {
    if (!tier) return null
    const colors: Record<string, string> = {
      'DESIGNER': 'bg-gray-100 text-gray-800',
      'GOLD_DESIGNER': 'bg-yellow-100 text-yellow-800',
      'VIP_DESIGNER': 'bg-purple-100 text-purple-800',
      'VVIP_DESIGNER': 'bg-indigo-100 text-indigo-800',
    }
    const labels: Record<string, string> = {
      'DESIGNER': 'Designer',
      'GOLD_DESIGNER': 'Gold',
      'VIP_DESIGNER': 'VIP',
      'VVIP_DESIGNER': 'VVIP',
    }
    return (
      <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${colors[tier] || 'bg-gray-100'}`}>
        {labels[tier] || tier}
      </span>
    )
  }

  return (
    <div className="max-w-7xl mx-auto px-3 py-4 sm:p-6">
      <div className="flex justify-between items-start gap-3 mb-4 sm:mb-6">
        <div>
          <h1 className="text-lg sm:text-2xl font-bold text-gray-900">User Management</h1>
          <p className="text-xs sm:text-sm text-gray-600 mt-0.5 sm:mt-1">Manage users, search by name or order ID, and send messages</p>
        </div>
        <button
          onClick={() => setShowBroadcast(true)}
          className="flex items-center gap-1.5 sm:gap-2 bg-indigo-600 text-white px-3 py-1.5 sm:px-4 sm:py-2 rounded-lg hover:bg-indigo-700 transition text-xs sm:text-sm whitespace-nowrap"
        >
          <Megaphone className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
          <span className="hidden xs:inline">Broadcast</span> Message
        </button>
      </div>

      {/* Search and Filters */}
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-3 sm:p-4 mb-4 sm:mb-6">
        <form onSubmit={handleSearch} className="space-y-3 sm:space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3 sm:gap-4">
            {/* Name/Email Search */}
            <div className="relative">
              <Search className="absolute left-2.5 sm:left-3 top-1/2 -translate-y-1/2 w-4 h-4 sm:w-5 sm:h-5 text-gray-400" />
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search by name, email, or username..."
                className="w-full pl-8 sm:pl-10 pr-3 py-2 text-sm text-gray-900 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>

            {/* Order ID Search */}
            <div className="relative">
              <ShoppingBag className="absolute left-2.5 sm:left-3 top-1/2 -translate-y-1/2 w-4 h-4 sm:w-5 sm:h-5 text-gray-400" />
              <input
                type="text"
                value={orderSearch}
                onChange={(e) => setOrderSearch(e.target.value)}
                placeholder="Search by order ID..."
                className="w-full pl-8 sm:pl-10 pr-3 py-2 text-sm text-gray-900 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>
          </div>

          <div className="flex items-center justify-between">
            <button
              type="button"
              onClick={() => setShowFilters(!showFilters)}
              className="flex items-center gap-1.5 text-xs sm:text-sm text-gray-600 hover:text-gray-900"
            >
              <Filter className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
              Filters
              <ChevronDown className={`w-3.5 h-3.5 sm:w-4 sm:h-4 transition ${showFilters ? 'rotate-180' : ''}`} />
            </button>

            <button
              type="submit"
              className="bg-indigo-600 text-white px-3 py-1.5 sm:px-4 sm:py-2 rounded-lg hover:bg-indigo-700 transition text-xs sm:text-sm"
            >
              Search
            </button>
          </div>

          {showFilters && (
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 sm:gap-4 pt-3 sm:pt-4 border-t border-gray-200">
              <div>
                <label htmlFor="userTypeFilter" className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">User Type</label>
                <select
                  id="userTypeFilter"
                  value={type}
                  onChange={(e) => setType(e.target.value)}
                  className="w-full px-2.5 py-1.5 sm:px-3 sm:py-2 text-sm text-gray-900 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 bg-white"
                >
                  {USER_TYPES.map(t => (
                    <option key={t.value} value={t.value} className="text-gray-900">{t.label}</option>
                  ))}
                </select>
              </div>

              <div>
                <label htmlFor="designerTierFilter" className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">Designer Tier</label>
                <select
                  id="designerTierFilter"
                  value={tier}
                  onChange={(e) => setTier(e.target.value)}
                  className="w-full px-2.5 py-1.5 sm:px-3 sm:py-2 text-sm text-gray-900 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 bg-white"
                >
                  {DESIGNER_TIERS.map(t => (
                    <option key={t.value} value={t.value} className="text-gray-900">{t.label}</option>
                  ))}
                </select>
              </div>

              <div>
                <label htmlFor="verificationFilter" className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">Verification</label>
                <select
                  id="verificationFilter"
                  value={status}
                  onChange={(e) => setStatus(e.target.value)}
                  className="w-full px-2.5 py-1.5 sm:px-3 sm:py-2 text-sm text-gray-900 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 bg-white"
                >
                  {VERIFICATION_STATUS.map(s => (
                    <option key={s.value} value={s.value} className="text-gray-900">{s.label}</option>
                  ))}
                </select>
              </div>
            </div>
          )}
        </form>
      </div>

      {/* Users List */}
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
        <div className="px-3 py-2 sm:px-4 sm:py-3 border-b border-gray-200 bg-gray-50 flex items-center justify-between">
          <div className="flex items-center gap-1.5 sm:gap-2">
            <Users className="w-4 h-4 sm:w-5 sm:h-5 text-gray-600" />
            <span className="text-sm sm:text-base font-medium text-gray-900">{pagination.total} Users</span>
          </div>
        </div>

        {loading ? (
          <div className="p-6 sm:p-8 text-center text-sm text-gray-500">Loading users...</div>
        ) : users.length === 0 ? (
          <div className="p-6 sm:p-8 text-center text-sm text-gray-500">No users found</div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 text-left text-xs sm:text-sm text-gray-600">
                <tr>
                  <th className="px-3 py-2 sm:px-4 sm:py-3">User</th>
                  <th className="px-3 py-2 sm:px-4 sm:py-3">Contact</th>
                  <th className="px-3 py-2 sm:px-4 sm:py-3 hidden sm:table-cell">Type</th>
                  <th className="px-3 py-2 sm:px-4 sm:py-3 hidden md:table-cell">Stats</th>
                  <th className="px-3 py-2 sm:px-4 sm:py-3 hidden lg:table-cell">Joined</th>
                  <th className="px-3 py-2 sm:px-4 sm:py-3">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {users.map(user => (
                  <tr key={user.id} className="hover:bg-gray-50">
                    <td className="px-3 py-2 sm:px-4 sm:py-3">
                      <div className="flex items-center gap-2 sm:gap-3">
                        <div className="w-8 h-8 sm:w-10 sm:h-10 bg-indigo-100 rounded-full flex items-center justify-center flex-shrink-0">
                          {user.image ? (
                            <img src={user.image} alt="" className="w-8 h-8 sm:w-10 sm:h-10 rounded-full object-cover" />
                          ) : (
                            <UserIcon className="w-4 h-4 sm:w-5 sm:h-5 text-indigo-600" />
                          )}
                        </div>
                        <div className="min-w-0">
                          <div className="flex items-center gap-1 sm:gap-2">
                            <span className="text-xs sm:text-sm font-medium text-gray-900 truncate">
                              {user.name || user.displayName || 'Unknown'}
                            </span>
                            {user.isVerified && <BadgeCheck className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-blue-500 flex-shrink-0" />}
                          </div>
                          <div className="flex items-center gap-1 sm:gap-2 mt-0.5">
                            {getTierBadge(user.designerTier)}
                            {user.role === 'ADMIN' && (
                              <span className="text-[10px] sm:text-xs bg-red-100 text-red-800 px-1.5 py-0.5 rounded">Admin</span>
                            )}
                          </div>
                        </div>
                      </div>
                    </td>
                    <td className="px-3 py-2 sm:px-4 sm:py-3">
                      <div className="text-xs sm:text-sm">
                        <div className="flex items-center gap-1 text-gray-600 truncate">
                          <Mail className="w-3 h-3 flex-shrink-0" />
                          <span className="truncate">{user.email}</span>
                        </div>
                        <div className="flex items-center gap-1 text-gray-500 mt-0.5">
                          <Phone className="w-3 h-3 flex-shrink-0" />
                          {user.phone}
                        </div>
                      </div>
                    </td>
                    <td className="px-3 py-2 sm:px-4 sm:py-3 hidden sm:table-cell">
                      <div className="text-xs sm:text-sm">
                        {user.isSeller ? (
                          <div className="flex items-center gap-1 text-green-600">
                            <Package className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                            Seller
                          </div>
                        ) : (
                          <span className="text-gray-500">Buyer</span>
                        )}
                        <div className="text-[10px] sm:text-xs text-gray-500 mt-0.5">
                          {user.designCount > 0 && `${user.designCount} designs`}
                          {user.designCount > 0 && user.boutiqueProductCount > 0 && ', '}
                          {user.boutiqueProductCount > 0 && `${user.boutiqueProductCount} products`}
                        </div>
                      </div>
                    </td>
                    <td className="px-3 py-2 sm:px-4 sm:py-3 hidden md:table-cell">
                      <div className="text-xs sm:text-sm">
                        <div className="text-gray-900">Γéª{user.totalEarnings.toLocaleString()}</div>
                        <div className="text-[10px] sm:text-xs text-gray-500">{user.totalSales} sales</div>
                      </div>
                    </td>
                    <td className="px-3 py-2 sm:px-4 sm:py-3 text-xs sm:text-sm text-gray-500 hidden lg:table-cell">
                      {new Date(user.createdAt).toLocaleDateString()}
                    </td>
                    <td className="px-3 py-2 sm:px-4 sm:py-3">
                      <div className="flex items-center gap-1 sm:gap-2">
                        <button
                          onClick={() => router.push(`/admin/users/${user.id}`)}
                          className="p-1.5 sm:p-2 text-gray-600 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition"
                          title="View Details"
                        >
                          <UserIcon className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                        </button>
                        <button
                          onClick={() => router.push(`/admin/users/${user.id}?tab=message`)}
                          className="p-1.5 sm:p-2 text-gray-600 hover:text-green-600 hover:bg-green-50 rounded-lg transition"
                          title="Send Message"
                        >
                          <MessageSquare className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Pagination */}
        {pagination.pages > 1 && (
          <div className="px-3 py-2 sm:px-4 sm:py-3 border-t border-gray-200 flex items-center justify-between">
            <div className="text-xs sm:text-sm text-gray-600">
              Page {pagination.page} of {pagination.pages}
            </div>
            <div className="flex items-center gap-1.5 sm:gap-2">
              <button
                onClick={() => setPagination(prev => ({ ...prev, page: prev.page - 1 }))}
                disabled={pagination.page === 1}
                className="p-1.5 sm:p-2 rounded-lg border border-gray-300 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                aria-label="Previous page"
              >
                <ChevronLeft className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
              </button>
              <button
                onClick={() => setPagination(prev => ({ ...prev, page: prev.page + 1 }))}
                disabled={pagination.page === pagination.pages}
                className="p-1.5 sm:p-2 rounded-lg border border-gray-300 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                aria-label="Next page"
              >
                <ChevronRight className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Broadcast Modal */}
      {showBroadcast && (
        <BroadcastModal onClose={() => setShowBroadcast(false)} />
      )}
    </div>
  )
}

// Broadcast Modal Component
function BroadcastModal({ onClose }: { onClose: () => void }) {
  const [subject, setSubject] = useState('')
  const [content, setContent] = useState('')
  const [targetType, setTargetType] = useState('ALL')
  const [targetTier, setTargetTier] = useState('')
  const [sendViaEmail, setSendViaEmail] = useState(true)
  const [sendViaInApp, setSendViaInApp] = useState(true)
  const [loading, setLoading] = useState(false)
  const [preview, setPreview] = useState<{ count: number; sampleUsers: { name: string; email: string }[] } | null>(null)

  const TARGET_TYPES = [
    { value: 'ALL', label: 'All Users' },
    { value: 'USERS', label: 'Buyers Only (No uploads)' },
    { value: 'SELLERS', label: 'All Sellers' },
    { value: 'DESIGNERS', label: 'Design Sellers' },
    { value: 'TIER_SPECIFIC', label: 'Specific Tier' },
    { value: 'VERIFIED_ONLY', label: 'Verified Users Only' },
  ]

  useEffect(() => {
    const fetchPreview = async () => {
      try {
        const response = await fetch('/api/admin/users', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ targetType, targetTier }),
        })
        const data = await response.json()
        if (response.ok) {
          setPreview({ count: data.count, sampleUsers: data.sampleUsers })
        }
      } catch (error) {
        console.error('Error fetching preview:', error)
      }
    }
    fetchPreview()
  }, [targetType, targetTier])

  const handleSend = async () => {
    if (!subject || !content) {
      toast.error('Subject and content are required')
      return
    }

    setLoading(true)
    try {
      const response = await fetch('/api/admin/broadcast', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          subject,
          content,
          targetType,
          targetTier: targetType === 'TIER_SPECIFIC' ? targetTier : null,
          sendViaEmail,
          sendViaInApp,
        }),
      })

      const data = await response.json()

      if (response.ok) {
        toast.success(data.message)
        onClose()
      } else {
        toast.error(data.error || 'Failed to send broadcast')
      }
    } catch (error) {
      console.error('Error sending broadcast:', error)
      toast.error('Failed to send broadcast')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
        <div className="p-6 border-b border-gray-200">
          <div className="flex items-center justify-between">
            <h2 className="text-xl font-bold text-gray-900">Broadcast Message</h2>
            <button onClick={onClose} className="text-gray-500 hover:text-gray-700">Γ£ò</button>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {/* Target Selection */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label htmlFor="targetAudience" className="block text-sm font-medium text-gray-700 mb-1">Target Audience</label>
              <select
                id="targetAudience"
                value={targetType}
                onChange={(e) => setTargetType(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 text-gray-900 bg-white"
              >
                {TARGET_TYPES.map(t => (
                  <option key={t.value} value={t.value} className="text-gray-900">{t.label}</option>
                ))}
              </select>
            </div>

            {targetType === 'TIER_SPECIFIC' && (
              <div>
                <label htmlFor="targetTier" className="block text-sm font-medium text-gray-700 mb-1">Designer Tier</label>
                <select
                  id="targetTier"
                  value={targetTier}
                  onChange={(e) => setTargetTier(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 text-gray-900 bg-white"
                >
                  <option value="" className="text-gray-900">Select tier...</option>
                  <option value="DESIGNER" className="text-gray-900">Designer</option>
                  <option value="GOLD_DESIGNER" className="text-gray-900">Gold Designer</option>
                  <option value="VIP_DESIGNER" className="text-gray-900">VIP Designer</option>
                  <option value="VVIP_DESIGNER" className="text-gray-900">VVIP Designer</option>
                </select>
              </div>
            )}
          </div>

          {/* Preview */}
          {preview && (
            <div className="bg-indigo-50 rounded-lg p-4">
              <p className="text-sm text-indigo-800">
                <strong>{preview.count}</strong> users will receive this message
              </p>
              {preview.sampleUsers.length > 0 && (
                <p className="text-xs text-indigo-600 mt-1">
                  Including: {preview.sampleUsers.map(u => u.name || u.email).join(', ')}
                  {preview.count > 5 && ` and ${preview.count - 5} more...`}
                </p>
              )}
            </div>
          )}

          {/* Subject */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Subject</label>
            <input
              type="text"
              value={subject}
              onChange={(e) => setSubject(e.target.value)}
              placeholder="Enter message subject..."
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
            />
          </div>

          {/* Content */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Message</label>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Enter your message..."
              rows={6}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
            />
          </div>

          {/* Delivery Options */}
          <div className="flex items-center gap-6">
            <label className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={sendViaInApp}
                onChange={(e) => setSendViaInApp(e.target.checked)}
                className="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
              />
              <span className="text-sm text-gray-700">In-App Notification</span>
            </label>
            <label className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={sendViaEmail}
                onChange={(e) => setSendViaEmail(e.target.checked)}
                className="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
              />
              <span className="text-sm text-gray-700">Email</span>
            </label>
          </div>
        </div>

        <div className="p-6 border-t border-gray-200 flex justify-end gap-3">
          <button
            onClick={onClose}
            className="px-4 py-2 text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50"
          >
            Cancel
          </button>
          <button
            onClick={handleSend}
            disabled={loading || !subject || !content}
            className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
          >
            {loading ? 'Sending...' : (
              <>
                <Megaphone className="w-4 h-4" />
                Send Broadcast
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState, useCallback } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import toast from 'react-hot-toast'
import {
  Search,
  Package,
  _TrendingDown,
  Filter,
  Calendar,
  Loader,
  Eye,
  ArrowLeft,
} from 'lucide-react'
import Image from 'next/image'
import Link from 'next/link'

interface Product {
  id: string
  title: string
  slug: string
  basePrice: number
  salePrice: number | null
  displayPrice: number
  currency: string
  currentStock: number
  originalStock: number | null
  thumbnailUrl: string | null
  status: string
  warehouseReceivedAt: string | null
  warehouseLocation: string | null
  warehouseExpiresAt: string | null
  shipmentWarehouseAddress: any
  daysInWarehouse: number
  daysInCurrentCycle: number
  storageCycle: number
  daysUntilExpiry: number
  condition: string
  isLowStock: boolean
  isInMonth5: boolean
  totalSold: number
  salesHistory: Array<{
    quantity: number
    variantInfo: string
    soldAt: string
    price: number
  }>
  seller: {
    id: string
    name: string | null
    email: string
    displayName: string | null
  }
}

export default function AdminWarehouseInventoryPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [products, setProducts] = useState<Product[]>([])
  const [filteredProducts, setFilteredProducts] = useState<Product[]>([])
  const [loading, setLoading] = useState(true)
  const [expandedId, setExpandedId] = useState<string | null>(null)
  const [salesHistoryPage, setSalesHistoryPage] = useState(0)
  const SALES_HISTORY_PAGE_SIZE = 10

  // Filters
  const [searchTerm, setSearchTerm] = useState('')
  const [productStatus, setProductStatus] = useState<'all' | 'LIVE' | 'OUT_OF_STOCK' | 'IN_RETURN' | 'RETURN_REQUESTED' | 'RETURN_SHIPPED' | 'RETURNED_TO_SELLER'>('all')
  const [stockStatus, setStockStatus] = useState<'all' | 'in_stock' | 'out_of_stock'>('all')
  const [dateFrom, setDateFrom] = useState('')
  const [dateTo, setDateTo] = useState('')

  const fetchProducts = useCallback(async () => {
    try {
      setLoading(true)
      const params = new URLSearchParams()

      if (searchTerm) params.append('search', searchTerm)
      if (productStatus !== 'all') params.append('status', productStatus)
      if (stockStatus !== 'all') params.append('stockStatus', stockStatus)
      if (dateFrom) params.append('dateFrom', dateFrom)
      if (dateTo) params.append('dateTo', dateTo)

      const response = await fetch(`/api/admin/warehouse-inventory?${params}`)

      if (!response.ok) throw new Error('Failed to fetch')

      const data = await response.json()
      setProducts(data.products || [])
    } catch (error) {
      console.error('Error fetching products:', error)
      toast.error('Failed to load warehouse inventory')
    } finally {
      setLoading(false)
    }
  }, [searchTerm, productStatus, stockStatus, dateFrom, dateTo])

  useEffect(() => {
    if (status === 'loading') {
      return
    }
    if (status === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (session?.user?.role !== 'ADMIN') {
      router.push('/admin')
      return
    }
    if (status === 'authenticated') {
      fetchProducts()
    }
  }, [status, router, session, fetchProducts])

  // Apply client-side filtering
  useEffect(() => {
    let filtered = products

    if (searchTerm) {
      filtered = filtered.filter(
        (p) =>
          p.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
          p.id.includes(searchTerm) ||
          p.seller.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
          (p.seller.name?.toLowerCase().includes(searchTerm.toLowerCase()) ?? false)
      )
    }

    setFilteredProducts(filtered)
  }, [products, searchTerm])

  if (status === 'loading' || loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader className="animate-spin text-primary-600" size={32} />
      </div>
    )
  }

  if (session?.user?.role !== 'ADMIN') {
    return null
  }

  const lowStockCount = products.filter((p) => p.isLowStock).length
  const inMonth5Count = products.filter((p) => p.isInMonth5).length
  const outOfStockCount = products.filter((p) => p.currentStock === 0).length
  const totalValue = products.reduce(
    (sum, p) => sum + p.displayPrice * (p.currentStock || 0),
    0
  )

  return (
    <div className="min-h-screen bg-gray-50 p-3 sm:p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <Link
            href="/admin"
            className="flex items-center gap-2 text-primary-600 hover:text-primary-700 mb-4"
          >
            <ArrowLeft size={20} />
            Back to Admin
          </Link>
          <h1 className="text-3xl font-bold text-gray-900">Warehouse Inventory</h1>
          <p className="text-gray-800 mt-2">
            Monitor all products in warehouse across all sellers
          </p>
        </div>

        {/* Quick Stats */}
        <div className="grid grid-cols-1 md:grid-cols-5 gap-4 mb-8">
          <div className="bg-white rounded-lg shadow-sm p-4 border-l-4 border-blue-500">
            <p className="text-gray-800 text-sm">Total Products</p>
            <p className="text-3xl font-bold text-gray-900 mt-2">
              {products.length}
            </p>
          </div>

          <div className="bg-white rounded-lg shadow-sm p-4 border-l-4 border-purple-500">
            <p className="text-gray-800 text-sm">Inventory Value</p>
            <p className="text-2xl font-bold text-gray-900 mt-2">
              Γéª{(totalValue / 1000000).toFixed(1)}M
            </p>
          </div>

          <div className="bg-white rounded-lg shadow-sm p-4 border-l-4 border-yellow-500">
            <p className="text-gray-800 text-sm">Low Stock (&le;5)</p>
            <p className="text-3xl font-bold text-yellow-600 mt-2">
              {lowStockCount}
            </p>
          </div>

          <div className="bg-white rounded-lg shadow-sm p-4 border-l-4 border-orange-500">
            <p className="text-gray-800 text-sm">In Month 5</p>
            <p className="text-3xl font-bold text-orange-600 mt-2">
              {inMonth5Count}
            </p>
          </div>

          <div className="bg-white rounded-lg shadow-sm p-4 border-l-4 border-red-500">
            <p className="text-gray-800 text-sm">Out of Stock</p>
            <p className="text-3xl font-bold text-red-600 mt-2">
              {outOfStockCount}
            </p>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-sm p-4 md:p-6 mb-6">
          <h2 className="font-bold text-gray-900 mb-4 flex items-center justify-between gap-2">
            <span className="flex items-center gap-2">
              <Filter size={18} />
              Filters
            </span>
            {(searchTerm || productStatus !== 'all' || stockStatus !== 'all' || dateFrom || dateTo) && (
              <button
                onClick={() => {
                  setSearchTerm('')
                  setProductStatus('all')
                  setStockStatus('all')
                  setDateFrom('')
                  setDateTo('')
                }}
                className="text-xs text-primary hover:text-primary-dark font-medium"
              >
                Reset
              </button>
            )}
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-3 text-gray-400" size={18} />
              <input
                type="text"
                placeholder="Search product, seller..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              />
            </div>

            {/* Product Status */}
            <select
              value={productStatus}
              onChange={(e) =>
                setProductStatus(
                  e.target.value as 'all' | 'LIVE' | 'OUT_OF_STOCK' | 'IN_RETURN' | 'RETURN_REQUESTED' | 'RETURN_SHIPPED' | 'RETURNED_TO_SELLER'
                )
              }
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent bg-white cursor-pointer"
            >
              <option value="all">All Status</option>
              <option value="LIVE">Live</option>
              <option value="OUT_OF_STOCK">Out of Stock</option>
              <option value="IN_RETURN">In Return</option>
              <option value="RETURN_REQUESTED">Return Requested</option>
              <option value="RETURN_SHIPPED">Return Shipped</option>
              <option value="RETURNED_TO_SELLER">Returned to Seller</option>
            </select>

            {/* Stock Status */}
            <select
              value={stockStatus}
              onChange={(e) =>
                setStockStatus(
                  e.target.value as 'all' | 'in_stock' | 'out_of_stock'
                )
              }
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent bg-white cursor-pointer"
            >
              <option value="all">All Stock Levels</option>
              <option value="in_stock">In Stock</option>
              <option value="out_of_stock">Out of Stock</option>
            </select>

            {/* Date From */}
            <div className="relative">
              <Calendar className="absolute left-3 top-3 text-gray-400" size={18} />
              <input
                type="date"
                value={dateFrom}
                onChange={(e) => setDateFrom(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              />
            </div>

            {/* Date To */}
            <div className="relative">
              <Calendar className="absolute left-3 top-3 text-gray-400" size={18} />
              <input
                type="date"
                value={dateTo}
                onChange={(e) => setDateTo(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              />
            </div>
          </div>
        </div>

        {/* Products Table */}
        {filteredProducts.length === 0 ? (
          <div className="bg-white rounded-lg shadow-sm p-12 text-center">
            <Package className="mx-auto text-gray-400 mb-4" size={48} />
            <p className="text-gray-800 text-lg">
              {products.length === 0
                ? 'No products in warehouse yet'
                : 'No products match your filters'}
            </p>
          </div>
        ) : (
          <div className="bg-white rounded-lg shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-800 uppercase">
                      Product
                    </th>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-800 uppercase hidden sm:table-cell">
                      Seller
                    </th>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-800 uppercase">
                      Stock
                    </th>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-800 uppercase">
                      Days In
                    </th>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-800 uppercase">
                      Until
                    </th>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-800 uppercase hidden md:table-cell">
                      Bin
                    </th>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-800 uppercase">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {filteredProducts.map((product) => (
                    <tr
                      key={product.id}
                      className={`hover:bg-gray-50 transition text-[9px] sm:text-xs ${
                        product.isInMonth5 ? 'bg-orange-50' : ''
                      }`}
                    >
                      <td className="px-2 sm:px-3 py-2 sm:py-3">
                        <div className="flex items-center gap-2">
                          {product.thumbnailUrl && (
                            <div className="relative w-8 h-8 flex-shrink-0">
                              <Image
                                src={product.thumbnailUrl}
                                alt={product.title}
                                fill
                                className="object-cover rounded"
                              />
                            </div>
                          )}
                          <div className="min-w-0">
                            <p className="font-medium text-gray-900 text-[9px] sm:text-xs truncate">
                              {product.title}
                            </p>
                          </div>
                        </div>
                      </td>
                      <td className="px-2 sm:px-3 py-2 sm:py-3 hidden sm:table-cell">
                        <div>
                          <p className="font-medium text-gray-900 text-[9px] sm:text-xs">
                            {product.seller.displayName || product.seller.name || 'Unknown'}
                          </p>
                          <p className="text-[8px] text-gray-700 hidden md:block">{product.seller.email.split('@')[0]}</p>
                        </div>
                      </td>
                      <td className="px-2 sm:px-3 py-2 sm:py-3">
                        <div className="flex items-center gap-2">
                          {product.currentStock === 0 ? (
                            <span className="px-2 py-1 bg-red-100 text-red-700 text-[9px] rounded font-medium">
                              Out
                            </span>
                          ) : product.isLowStock ? (
                            <span className="px-2 py-1 bg-yellow-100 text-yellow-700 text-[9px] rounded font-medium">
                              {product.currentStock}
                            </span>
                          ) : (
                            <span className="text-gray-900 font-medium text-[9px] sm:text-xs">
                              {product.currentStock}/{product.originalStock || '?'}
                            </span>
                          )}
                        </div>
                      </td>
                      <td className="px-2 sm:px-3 py-2 sm:py-3">
                        <span className="text-[9px] sm:text-xs text-gray-700">
                          {product.warehouseReceivedAt ? (
                            <>
                              {product.daysInCurrentCycle}/{181}
                              {product.storageCycle > 1 && <span className="ml-1 text-gray-700">(C{product.storageCycle})</span>}
                            </>
                          ) : (
                            'ΓÇö'
                          )}
                        </span>
                      </td>
                      <td className="px-2 sm:px-3 py-2 sm:py-3">
                        <span
                          className={`font-medium text-[9px] sm:text-xs ${
                            product.warehouseExpiresAt && product.daysUntilExpiry <= 30
                              ? 'text-red-600'
                              : product.warehouseExpiresAt && product.daysUntilExpiry <= 60
                              ? 'text-orange-600'
                              : 'text-green-600'
                          }`}
                        >
                          {product.warehouseExpiresAt ? `${product.daysUntilExpiry}d` : 'ΓÇö'}
                        </span>
                      </td>
                      <td className="px-2 sm:px-3 py-2 sm:py-3 hidden md:table-cell">
