        )}
      </div>
    </div>
  )
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'
import { prismaErrorResponse } from '@/lib/prismaError'

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)

    // Verify admin
    if (!session?.user?.email) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const user = await prisma.user.findUnique({
      where: { email: session.user.email },
    })

    if (user?.role !== 'ADMIN') {
      return NextResponse.json(
        { error: 'Forbidden' },
        { status: 403 }
      )
    }

    // Get query params
    const searchParams = request.nextUrl.searchParams
    const limit = Math.min(parseInt(searchParams.get('limit') || '100'), 1000)
    const category = searchParams.get('category')
    const action = searchParams.get('action')
    const status = searchParams.get('status') // 'success' or 'failed'

    // Build where clause
    const where: any = {}
    if (category) where.category = category
    if (action) where.action = action
    if (status === 'success') where.success = true
    if (status === 'failed') where.success = false

    // Fetch logs
    const logs = await prisma.auditLog.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: limit,
    })

    // Get total count for pagination info
    const total = await prisma.auditLog.count({ where })

    return NextResponse.json({
      logs,
      total,
      limit,
    })
  } catch (error) {
    console.error('Audit log fetch error:', error)

    const prismaResp = prismaErrorResponse(
      error,
      'Database temporarily unavailable'
    )
    if (prismaResp) return prismaResp

    return NextResponse.json(
      { error: 'Failed to fetch logs' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import prisma from "@/lib/prisma";

/**
 * GET /api/admin/content-violations - Get all content violations
 * 
 * Query params:
 * - status: "all" | "pending" | "reviewed" (default: "pending")
 * - userId: Filter by specific user
 * - page: Page number (default: 1)
 * - limit: Items per page (default: 20, max: 100)
 */
export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    
    if (!session?.user?.id || session.user.role !== "ADMIN") {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
    
    const { searchParams } = new URL(request.url);
    const status = searchParams.get("status") || "pending";
    const userId = searchParams.get("userId");
    const pageParam = parseInt(searchParams.get("page") || "1");
    const limitParam = parseInt(searchParams.get("limit") || "20");
    const page = Number.isNaN(pageParam) || pageParam < 1 ? 1 : pageParam;
    const limit = Number.isNaN(limitParam) || limitParam < 1 ? 20 : Math.min(limitParam, 100);
    
    // Build where clause
    const where: Record<string, unknown> = {};
    
    if (status === "pending") {
      where.reviewed = false;
    } else if (status === "reviewed") {
      where.reviewed = true;
    }
    // "all" = no filter
    
    if (userId) {
      where.userId = userId;
    }
    
    // Get total count
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const total = await (prisma as any).contentViolation.count({ where });
    
    // Get violations
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const violations = await (prisma as any).contentViolation.findMany({
      where,
      skip: (page - 1) * limit,
      take: limit,
      orderBy: { createdAt: "desc" },
    });

    // Fetch user data separately for each violation
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const violationsWithUsers = await Promise.all(
      violations.map(async (violation: any) => {
        try {
          const user = await (prisma as any).user.findUnique({
            where: { id: violation.userId },
            select: {
              id: true,
              name: true,
              email: true,
            },
          });
          return { ...violation, user: user || { id: violation.userId, name: "Unknown", email: violation.userEmail } };
        } catch (_err) {
          return { ...violation, user: { id: violation.userId, name: "Unknown", email: violation.userEmail } };
        }
      })
    );
    
    // Get stats
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const stats = await (prisma as any).contentViolation.groupBy({
      by: ["violationType"],
      _count: { violationType: true },
    });
    
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const pendingCount = await (prisma as any).contentViolation.count({
      where: { reviewed: false },
    });
    
    return NextResponse.json({
      violations: violationsWithUsers,
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
      stats: {
        pending: pendingCount,
        byType: stats.reduce((acc: Record<string, number>, item: { violationType: string; _count: { violationType: number } }) => {
          acc[item.violationType] = item._count.violationType;
          return acc;
        }, {}),
      },
    });
  } catch (error) {
    console.error("Error fetching content violations:", error);
    
    // Log more details if it's a Prisma error
    if (error instanceof Error) {
      console.error("Error message:", error.message);
      console.error("Error stack:", error.stack);
    }
    
    return NextResponse.json(
      { error: "Failed to fetch violations", details: error instanceof Error ? error.message : String(error) },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'

// Maximum page size to prevent memory exhaustion
const MAX_PAGE_SIZE = 100
const DEFAULT_PAGE_SIZE = 20

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    
    if (!session || session.user.role !== 'ADMIN') {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      )
    }

    // Parse pagination parameters
    const { searchParams } = new URL(request.url)
    const pageParam = parseInt(searchParams.get('page') || '1', 10)
    const limitParam = parseInt(searchParams.get('limit') || String(DEFAULT_PAGE_SIZE), 10)
    const page = Number.isNaN(pageParam) || pageParam < 1 ? 1 : pageParam
    const limit = Number.isNaN(limitParam) || limitParam < 1 ? DEFAULT_PAGE_SIZE : Math.min(limitParam, MAX_PAGE_SIZE)
    const skip = (page - 1) * limit
    const search = searchParams.get('search') || ''
    const onlyNotFeatured = searchParams.get('onlyNotFeatured') === 'true'

    // Build filter
    const where: any = {}
    if (search) {
      where.OR = [
        { title: { contains: search, mode: 'insensitive' } },
        { designer: { name: { contains: search, mode: 'insensitive' } } },
        { designer: { email: { contains: search, mode: 'insensitive' } } }
      ]
    }

    // Parallel fetch: designs and total count
    const [designs, total] = await Promise.all([
      prisma.design.findMany({
        skip,
        take: limit,
        where,
        orderBy: {
          createdAt: 'desc'
        },
        include: {
          designer: {
            select: {
              id: true,
              name: true,
              email: true,
              displayName: true
            }
          },
          featuredInList: {
            select: {
              id: true
            },
            take: 1
          }
        }
      }),
      prisma.design.count({ where })
    ])

    // Map designs to include isFeatured flag and filter if needed
    let designsWithFeatured = designs.map(design => ({
      ...design,
      isFeatured: design.featuredInList.length > 0
    }))

    if (onlyNotFeatured) {
      designsWithFeatured = designsWithFeatured.filter(d => !d.isFeatured)
    }

    return NextResponse.json({ 
      designs: designsWithFeatured.map(d => {
        const { featuredInList, ...rest } = d
        return rest
      }),
      items: designsWithFeatured.map(d => {
        const { featuredInList, ...rest } = d
        return rest
      }),
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit)
      }
    })
  } catch (error) {
    console.error('Error fetching designs:', error)

    if (error instanceof Error && error.message.includes('prisma')) {
      return NextResponse.json(
        { error: 'Database temporarily unavailable. Please try again later.' },
        { status: 503 }
      )
    }

    return NextResponse.json(
      { error: 'Failed to fetch designs. Please try again later.' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'
import crypto from 'crypto'
import { MOA_TEMPLATE } from '@/lib/documents/moa-template'
import { AOA_TEMPLATE } from '@/lib/documents/aoa-template'
import { SHAREHOLDER_AGREEMENT_TEMPLATE } from '@/lib/documents/shareholder-agreement-template'
import { EMPLOYMENT_CONTRACT_TEMPLATE } from '@/lib/documents/employment-contract-template'

// Document information mapping
const DOCUMENT_INFO: Record<string, { name: string; content: string }> = {
  MOA: { name: 'Memorandum of Association', content: MOA_TEMPLATE },
  AOA: { name: 'Articles of Association', content: AOA_TEMPLATE },
  SHAREHOLDER_AGREEMENT: { name: 'Shareholder Agreement', content: SHAREHOLDER_AGREEMENT_TEMPLATE },
  EMPLOYMENT_CONTRACT: { name: 'Employment Contract Template', content: EMPLOYMENT_CONTRACT_TEMPLATE },
}

// Calculate SHA256 checksum of content
function calculateChecksum(content: string): string {
  return crypto.createHash('sha256').update(content).digest('hex')
}

// POST: Create a new document version
export async function POST(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.role || session.user.role !== 'ADMIN') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const body = await req.json()
    const { documentType, notes } = body

    // Validate document type
    if (!DOCUMENT_INFO[documentType]) {
      return NextResponse.json({ error: 'Invalid document type' }, { status: 400 })
    }

    const docInfo = DOCUMENT_INFO[documentType]
    const checksum = calculateChecksum(docInfo.content)

    // Check if this content already exists
    const _existingVersion = await prisma.documentVersion.findFirst({
      where: { checksum },
      orderBy: { versionNumber: 'desc' },
    })

    // Get next version number
    const lastVersion = await prisma.documentVersion.findFirst({
      where: { documentType },
      orderBy: { versionNumber: 'desc' },
    })
    const nextVersionNumber = (lastVersion?.versionNumber || 0) + 1

    // Create new version
    const newVersion = await prisma.documentVersion.create({
      data: {
        documentType,
        documentName: docInfo.name,
        versionNumber: nextVersionNumber,
        content: docInfo.content,
        checksum,
        status: 'DRAFT',
        approvalStatus: 'PENDING',
        notes,
        createdBy: session.user.id!,
        previousVersionId: lastVersion?.id,
      },
      include: {
        creator: { select: { id: true, email: true, name: true } },
      },
    })

    return NextResponse.json({
      success: true,
      version: newVersion,
      message: `${docInfo.name} version ${nextVersionNumber} created`,
    })
  } catch (error) {
    console.error('Error creating document version:', error)
    return NextResponse.json({ error: 'Failed to create version' }, { status: 500 })
  }
}

// GET: List document versions
export async function GET(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.role || session.user.role !== 'ADMIN') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const searchParams = req.nextUrl.searchParams
    const documentType = searchParams.get('documentType')
    const status = searchParams.get('status')
    const limit = parseInt(searchParams.get('limit') || '50', 10)
    const skip = parseInt(searchParams.get('skip') || '0', 10)

    // Build filter
    const filter: any = {}
    if (documentType) filter.documentType = documentType
    if (status) filter.status = status

    // Get versions
    const [versions, total] = await Promise.all([
      prisma.documentVersion.findMany({
        where: filter,
        include: {
          creator: { select: { id: true, email: true, name: true } },
          approver: { select: { id: true, email: true, name: true } },
          usageRecords: { select: { usageType: true, accessedAt: true } },
        },
        orderBy: { createdAt: 'desc' },
        take: limit,
        skip,
      }),
      prisma.documentVersion.count({ where: filter }),
    ])

    // Aggregate usage stats per version
    const versionsWithStats = versions.map((v) => ({
      ...v,
      stats: {
        totalAccesses: v.usageRecords.length,
        views: v.usageRecords.filter((u) => u.usageType === 'VIEWED').length,
        downloads: v.usageRecords.filter((u) => u.usageType === 'DOWNLOADED').length,
        prints: v.usageRecords.filter((u) => u.usageType === 'PRINTED').length,
        signatures: v.usageRecords.filter((u) => u.usageType === 'SIGNED').length,
        lastAccessed: v.usageRecords[0]?.accessedAt || null,
      },
    }))

    return NextResponse.json({
      versions: versionsWithStats,
      pagination: { total, skip, limit, pages: Math.ceil(total / limit) },
    })
  } catch (error) {
    console.error('Error fetching versions:', error)
    return NextResponse.json({ error: 'Failed to fetch versions' }, { status: 500 })
  }
}

// PATCH: Update version status or approve
export async function PATCH(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.role || session.user.role !== 'ADMIN') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const body = await req.json()
    const { versionId, action, status, approvalStatus } = body

    if (!versionId) {
      return NextResponse.json({ error: 'Version ID required' }, { status: 400 })
    }

    const version = await prisma.documentVersion.findUnique({
      where: { id: versionId },
    })

    if (!version) {
      return NextResponse.json({ error: 'Version not found' }, { status: 404 })
    }

    let updateData: any = {}

    if (action === 'approve') {
      updateData = {
        approvalStatus: 'APPROVED',
        status: 'ACTIVE',
        approvedBy: session.user.id!,
        approvedAt: new Date(),
        publishedAt: new Date(),
      }
    } else if (action === 'reject') {
      updateData = {
        approvalStatus: 'REJECTED',
        status: 'ARCHIVED',
        approvedBy: session.user.id!,
        approvedAt: new Date(),
      }
    } else if (action === 'archive') {
      updateData = {
        status: 'ARCHIVED',
      }
    } else if (action === 'supersede') {
      updateData = {
        status: 'SUPERSEDED',
      }
    } else if (status) {
      updateData = { status, approvalStatus }
    }

    const updated = await prisma.documentVersion.update({
      where: { id: versionId },
      data: updateData,
      include: {
        creator: { select: { id: true, email: true, name: true } },
        approver: { select: { id: true, email: true, name: true } },
      },
    })

    return NextResponse.json({
      success: true,
      version: updated,
      message: `Document version ${action || 'updated'} successfully`,
    })
  } catch (error) {
    console.error('Error updating version:', error)
    return NextResponse.json({ error: 'Failed to update version' }, { status: 500 })
  }
}

// DELETE: Archive a version (soft delete)
export async function DELETE(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.role || session.user.role !== 'ADMIN') {
