  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'

// POST: Record document usage
export async function POST(req: NextRequest) {
  try {
    const body = await req.json()
    const { versionId, usageType, format } = body

    // Validate required fields
    if (!versionId || !usageType) {
      return NextResponse.json(
        { error: 'versionId and usageType required' },
        { status: 400 }
      )
    }

    // Verify version exists
    const version = await prisma.documentVersion.findUnique({
      where: { id: versionId },
    })

    if (!version) {
      return NextResponse.json({ error: 'Version not found' }, { status: 404 })
    }

    // Get session if available (optional for tracking)
    const session = await getServerSession(authOptions)

    // Record usage
    const usage = await prisma.documentUsage.create({
      data: {
        versionId,
        usageType,
        format: format || 'HTML',
        userId: session?.user?.id || null,
        userAgent: req.headers.get('user-agent') || null,
        // Extract IP from headers (works with proxies)
        ipAddress:
          req.headers.get('x-forwarded-for')?.split(',')[0].trim() ||
          req.headers.get('x-real-ip') ||
          null,
      },
    })

    // Update version download/access count
    if (usageType === 'DOWNLOADED') {
      await prisma.documentVersion.update({
        where: { id: versionId },
        data: {
          downloads: { increment: 1 },
          lastAccessedAt: new Date(),
        },
      })
    } else {
      await prisma.documentVersion.update({
        where: { id: versionId },
        data: { lastAccessedAt: new Date() },
      })
    }

    return NextResponse.json({
      success: true,
      usage,
    })
  } catch (error) {
    console.error('Error recording usage:', error)
    return NextResponse.json(
      { error: 'Failed to record usage' },
      { status: 500 }
    )
  }
}

// GET: Get usage statistics for a version
export async function GET(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.role || session.user.role !== 'ADMIN') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const searchParams = req.nextUrl.searchParams
    const versionId = searchParams.get('versionId')
    const startDate = searchParams.get('startDate')
    const endDate = searchParams.get('endDate')

    if (!versionId) {
      return NextResponse.json(
        { error: 'versionId query parameter required' },
        { status: 400 }
      )
    }

    // Build filter
    const filter: any = { versionId }
    if (startDate || endDate) {
      filter.accessedAt = {}
      if (startDate) filter.accessedAt.gte = new Date(startDate)
      if (endDate) filter.accessedAt.lte = new Date(endDate)
    }

    // Get usage records
    const usageRecords = await prisma.documentUsage.findMany({
      where: filter,
      include: {
        user: { select: { id: true, email: true, name: true } },
      },
      orderBy: { accessedAt: 'desc' },
    })

    // Aggregate statistics
    const stats = {
      total: usageRecords.length,
      byType: usageRecords.reduce(
        (acc, u) => {
          acc[u.usageType] = (acc[u.usageType] || 0) + 1
          return acc
        },
        {} as Record<string, number>
      ),
      byFormat: usageRecords.reduce(
        (acc, u) => {
          acc[u.format] = (acc[u.format] || 0) + 1
          return acc
        },
        {} as Record<string, number>
      ),
      uniqueUsers: new Set(usageRecords.map((u) => u.userId).filter(Boolean)).size,
      lastAccessed: usageRecords[0]?.accessedAt || null,
    }

    return NextResponse.json({
      stats,
      records: usageRecords,
    })
  } catch (error) {
    console.error('Error fetching usage stats:', error)
    return NextResponse.json(
      { error: 'Failed to fetch usage statistics' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'
import { prismaErrorResponse } from '@/lib/prismaError'

/**
 * GET /api/admin/featured-items
 * Get all featured items (both designs and boutique products) - admin only
 * 
 * Query params:
 * - itemType: 'DESIGN' | 'BOUTIQUE_PRODUCT' (filter)
 * - search: search by seller name/email or item title
 * - sort: 'addedAt' | 'position' (default: addedAt)
 * - page: pagination (default 1)
 * - limit: items per page (default 20, max 100)
 */
export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const admin = await prisma.user.findUnique({
      where: { id: session.user.id },
      select: { role: true }
    })

    if (admin?.role !== 'ADMIN') {
      return NextResponse.json({ error: 'Admin access required' }, { status: 403 })
    }

    const { searchParams } = new URL(request.url)
    const itemType = searchParams.get('itemType')
    const search = searchParams.get('search') || ''
    const sort = searchParams.get('sort') || 'addedAt'
    const sortOrder = searchParams.get('sortOrder') || 'desc'
    const priceSort = searchParams.get('priceSort') || ''
    const ownership = searchParams.get('ownership') || ''
    const addedByAdmin = searchParams.get('addedByAdmin') || ''
    const page = Math.max(1, parseInt(searchParams.get('page') || '1'))
    const limit = Math.min(100, Math.max(1, parseInt(searchParams.get('limit') || '20')))
    const skip = (page - 1) * limit

    // Get featured designs
    let designFeatures: any[] = []
    let designCount = 0

    // Get featured boutique products
    let boutiqueFeatures: any[] = []
    let boutiqueCount = 0

    // Get admin featured items
    let adminFeatures: any[] = []
    let adminCount = 0

    if (!itemType || itemType === 'DESIGN') {
      const designs = await prisma.featuredDesign.findMany({
        include: {
          seller: {
            select: {
              id: true,
              name: true,
              email: true,
              displayName: true,
              subscriptionTier: true,
              totalEarnings: true,
              createdAt: true
            }
          },
          design: {
            select: {
              id: true,
              title: true,
              imageUrl: true,
              price: true,
              totalSales: true,
              totalRevenue: true,
              createdAt: true
            }
          }
        },
        orderBy: sort === 'position' ? { position: 'asc' } : { addedAt: 'desc' }
      })

      // Client-side search filtering for designs
      const filtered = designs
        .filter(f => {
          if (!search) return true
          const searchLower = search.toLowerCase()
          return (
            f.design.title.toLowerCase().includes(searchLower) ||
            (f.seller.email && f.seller.email.toLowerCase().includes(searchLower)) ||
            (f.seller.name && f.seller.name.toLowerCase().includes(searchLower))
          )
        })
      
      designCount = filtered.length

      designFeatures = filtered
        .slice(itemType ? skip : 0, itemType ? skip + limit : undefined)
        .map(f => ({
          id: f.id,
          itemType: 'DESIGN',
          itemId: f.design.id,
          title: f.design.title,
          imageUrl: f.design.imageUrl,
          price: f.design.price,
          totalSales: f.design.totalSales,
          totalRevenue: f.design.totalRevenue,
          seller: {
            ...f.seller,
            createdAt: f.seller.createdAt.toISOString()
          },
          position: f.position,
          addedAt: f.addedAt.toISOString(),
          addedByAdmin: f.addedByAdmin ?? false,
          itemCreatedAt: f.design.createdAt.toISOString()
        }))
    }

    if (!itemType || itemType === 'BOUTIQUE_PRODUCT') {
      const boutiques = await prisma.featuredBoutiqueProduct.findMany({
        include: {
          seller: {
            select: {
              id: true,
              name: true,
              email: true,
              displayName: true,
              subscriptionTier: true,
              totalEarnings: true,
              createdAt: true
            }
          },
          product: {
            select: {
              id: true,
              slug: true,
              title: true,
              thumbnailUrl: true,
              basePrice: true,
              salePrice: true,
              status: true,
              createdAt: true
            }
          }
        },
        orderBy: sort === 'position' ? { position: 'asc' } : { addedAt: 'desc' }
      })

      // Client-side search filtering for boutique products
      const filtered = boutiques
        .filter(f => {
          if (!search) return true
          const searchLower = search.toLowerCase()
          return (
            f.product.title.toLowerCase().includes(searchLower) ||
            (f.seller.email && f.seller.email.toLowerCase().includes(searchLower)) ||
            (f.seller.name && f.seller.name.toLowerCase().includes(searchLower))
          )
        })
      
      boutiqueCount = filtered.length

      boutiqueFeatures = filtered
        .slice(!itemType ? 0 : skip, !itemType ? undefined : skip + limit)
        .map(f => ({
          id: f.id,
          itemType: 'BOUTIQUE_PRODUCT',
          itemId: f.product.id,
          slug: f.product.slug,
          title: f.product.title,
          imageUrl: f.product.thumbnailUrl,
          price: f.product.salePrice || f.product.basePrice,
          status: f.product.status,
          seller: {
            ...f.seller,
            createdAt: f.seller.createdAt.toISOString()
          },
          position: f.position,
          addedAt: f.addedAt.toISOString(),
          addedByAdmin: f.addedByAdmin ?? false,
          itemCreatedAt: f.product.createdAt.toISOString()
        }))
    }

    if (!itemType || itemType === 'DESIGN' || itemType === 'BOUTIQUE_PRODUCT') {
      const adminItems = await prisma.adminFeaturedItem.findMany({
        orderBy: { addedAt: 'desc' }
      })

      // OPTIMIZATION: Batch fetch designs and products in one query each (eliminates N+1)
      const designIds = adminItems.filter(i => i.itemType === 'DESIGN').map(i => i.itemId)
      const productIds = adminItems.filter(i => i.itemType === 'BOUTIQUE_PRODUCT').map(i => i.itemId)

      // Fetch all designs at once
      const designsByIdMap = new Map<string, any>()
      if (designIds.length > 0) {
        const designs = await prisma.design.findMany({
          where: { id: { in: designIds } },
          select: {
            id: true,
            title: true,
            imageUrl: true,
            price: true,
            createdAt: true,
            designerId: true,
            designer: { select: { id: true, name: true, email: true } }
          }
        })
        designs.forEach(d => designsByIdMap.set(d.id, d))
      }

      // Fetch all products at once
      const productsByIdMap = new Map<string, any>()
      if (productIds.length > 0) {
        const products = await prisma.boutiqueProduct.findMany({
          where: { id: { in: productIds } },
          select: {
            id: true,
            slug: true,
            title: true,
            thumbnailUrl: true,
            basePrice: true,
            salePrice: true,
            status: true,
            createdAt: true,
            sellerId: true,
            seller: { select: { id: true, name: true, email: true } }
          }
        })
        products.forEach(p => productsByIdMap.set(p.id, p))
      }

      // Map admin items to their details
      const adminWithDetails = adminItems
        .map(item => {
          if (item.itemType === 'DESIGN') {
            const design = designsByIdMap.get(item.itemId)
            if (design) {
              return {
                id: item.id,
                itemType: 'DESIGN',
                itemId: design.id,
                title: design.title,
                imageUrl: design.imageUrl,
                price: design.price,
                seller: {
                  id: design.designer.id,
                  name: design.designer.name,
                  email: design.designer.email
                },
                position: 0,
                addedAt: item.addedAt.toISOString(),
                addedByAdmin: true,
                itemCreatedAt: design.createdAt.toISOString()
              }
            }
          } else if (item.itemType === 'BOUTIQUE_PRODUCT') {
            const product = productsByIdMap.get(item.itemId)
            if (product) {
              return {
                id: item.id,
                itemType: 'BOUTIQUE_PRODUCT',
                itemId: product.id,
                slug: product.slug,
                title: product.title,
                imageUrl: product.thumbnailUrl,
                price: product.salePrice || product.basePrice,
                status: product.status,
                seller: {
                  id: product.seller.id,
                  name: product.seller.name,
                  email: product.seller.email
                },
                position: 0,
                addedAt: item.addedAt.toISOString(),
                addedByAdmin: true,
                itemCreatedAt: product.createdAt.toISOString()
              }
            }
          }
          return null
        })
        .filter((item): item is any => item !== null)

      adminFeatures = adminWithDetails
      if (itemType) {
        adminFeatures = adminFeatures.filter(f => f.itemType === itemType)
      }
      adminCount = adminFeatures.length
    }

    // Combine and sort
    let allFeatures = [...designFeatures, ...boutiqueFeatures, ...adminFeatures]
    
    // Apply ownership filter
    if (ownership) {
      allFeatures = allFeatures.filter(f => f.itemType === ownership)
    }

    // Apply addedByAdmin filter
    if (addedByAdmin) {
      const isAdminOnly = addedByAdmin === 'admin'
      allFeatures = allFeatures.filter(f => f.addedByAdmin === isAdminOnly)
    }

    // Sort by selected criteria
    allFeatures.sort((a, b) => {
      let compareValue = 0

      if (priceSort === 'highest') {
        compareValue = b.price - a.price
      } else if (priceSort === 'lowest') {
        compareValue = a.price - b.price
      } else if (sort === 'position') {
        compareValue = a.position - b.position
      } else if (sort === 'sales') {
        compareValue = (b.totalSales || 0) - (a.totalSales || 0)
      } else {
        // Default: sort by date published
        compareValue = new Date(b.itemCreatedAt).getTime() - new Date(a.itemCreatedAt).getTime()
      }

      // Apply sort order
      return sortOrder === 'asc' ? -compareValue : compareValue
    })

    const totalCount = designCount + boutiqueCount + adminCount
    const totalPages = Math.ceil(totalCount / limit)
    const pageItems = allFeatures.slice((itemType ? 0 : (page - 1) * limit), (itemType ? undefined : page * limit))

    return NextResponse.json({
      items: pageItems,
      pagination: {
        page,
        limit,
        total: totalCount,
        pages: totalPages,
        hasMore: page < totalPages
      },
      filters: {
        itemType,
        search,
        sort
      }
    })
  } catch (error) {
    console.error('[GET /api/admin/featured-items]', error)
    const prismaResp = prismaErrorResponse(error, 'Failed to fetch featured items')
    if (prismaResp) return prismaResp
    return NextResponse.json({ error: 'Failed to fetch featured items' }, { status: 500 })
  }
}

/**
 * POST /api/admin/featured-items
 * Admin add item to featured (no limit)
 * 
 * Body: {
 *   itemType: 'DESIGN' | 'BOUTIQUE_PRODUCT',
 *   itemId: string,
 *   position?: number,
 *   reason?: string
 * }
 */
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const admin = await prisma.user.findUnique({
      where: { id: session.user.id },
      select: { role: true }
    })

    if (admin?.role !== 'ADMIN') {
      return NextResponse.json({ error: 'Admin access required' }, { status: 403 })
    }

    const body = await request.json()
    const { itemType, itemId, position = 0, reason } = body
    console.log('[POST /api/admin/featured-items] Body received:', { itemType, itemId, position, reason })

    if (!itemType || !itemId) {
      return NextResponse.json({ error: 'itemType and itemId required' }, { status: 400 })
    }

    if (!['DESIGN', 'BOUTIQUE_PRODUCT'].includes(itemType)) {
      return NextResponse.json({ error: 'Invalid itemType' }, { status: 400 })
    }

    // Verify item exists
    if (itemType === 'DESIGN') {
      const design = await prisma.design.findUnique({ where: { id: itemId } })
      if (!design) {
        return NextResponse.json({ error: 'Design not found' }, { status: 404 })
      }
    } else {
      const product = await prisma.boutiqueProduct.findUnique({ where: { id: itemId } })
      if (!product) {
        return NextResponse.json({ error: 'Product not found' }, { status: 404 })
      }
    }

    // Create admin featured item
    const featured = await prisma.adminFeaturedItem.create({
      data: {
        itemType,
        itemId,
        position,
        reason,
        addedBy: session.user.id
      }
    })

    console.log('[POST /api/admin/featured-items] Successfully created:', featured.id)
    return NextResponse.json({
      success: true,
      featured,
      message: `${itemType === 'DESIGN' ? 'Design' : 'Product'} added to featured`
    }, { status: 201 })
  } catch (error: any) {
    if (error.code === 'P2002') {
      return NextResponse.json({ error: 'Item already featured' }, { status: 409 })
    }
    console.error('[POST /api/admin/featured-items]', error)
    const prismaResp = prismaErrorResponse(error, 'Failed to add featured item')
    if (prismaResp) return prismaResp
    return NextResponse.json({ error: 'Failed to add featured item' }, { status: 500 })
  }
}

/**
 * DELETE /api/admin/featured-items/:id
 * Admin remove item from featured
 */
export async function DELETE(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const admin = await prisma.user.findUnique({
      where: { id: session.user.id },
      select: { role: true }
    })

    if (admin?.role !== 'ADMIN') {
      return NextResponse.json({ error: 'Admin access required' }, { status: 403 })
    }

    const { searchParams } = new URL(request.url)
    const id = searchParams.get('id')
    const itemType = searchParams.get('itemType')
    const source = searchParams.get('source')

    if (!id) {
      return NextResponse.json({ error: 'ID required' }, { status: 400 })
    }

    if (!itemType) {
      return NextResponse.json({ error: 'Item type required' }, { status: 400 })
    }

    // Delete from the appropriate table based on source
    if (source === 'ADMIN_FEATURED') {
      await prisma.adminFeaturedItem.delete({
        where: { id }
      })
    } else if (itemType === 'DESIGN') {
      await prisma.featuredDesign.delete({
        where: { id }
      })
    } else if (itemType === 'BOUTIQUE_PRODUCT') {
      await prisma.featuredBoutiqueProduct.delete({
        where: { id }
      })
    } else {
      return NextResponse.json({ error: 'Invalid item type' }, { status: 400 })
    }

    return NextResponse.json({ success: true, message: 'Item removed from featured' })
  } catch (error: any) {
    if (error.code === 'P2025') {
      return NextResponse.json({ error: 'Featured item not found' }, { status: 404 })
    }
    console.error('[DELETE /api/admin/featured-items]', error)
    const prismaResp = prismaErrorResponse(error, 'Failed to remove featured item')
    if (prismaResp) return prismaResp
    return NextResponse.json({ error: 'Failed to remove featured item' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'

/**
 * GET /api/admin/payment-reconciliation
 * Admin dashboard for payment reconciliation across all processors
 * Returns processor balances, transaction summary, discrepancies
 */
export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)

    if (!session?.user || session.user.role !== 'ADMIN') {
      return NextResponse.json(
        { success: false, message: 'Admin access required' },
        { status: 403 }
      )
    }

    const { searchParams } = new URL(request.url)
    const processor = searchParams.get('processor') // Filter by processor
    const startDate = searchParams.get('startDate')
    const endDate = searchParams.get('endDate')
    const page = parseInt(searchParams.get('page') || '1')
    const limit = parseInt(searchParams.get('limit') || '20')

    const skip = (page - 1) * limit

    // Build date filter
    const dateFilter: any = {}
    if (startDate) dateFilter.gte = new Date(startDate)
    if (endDate) dateFilter.lte = new Date(endDate)

    const where: any = dateFilter.gte || dateFilter.lte ? { completedAt: dateFilter } : {}
    if (processor) where.processor = processor

    // Get all transactions for the period
    const transactions = await prisma.paymentTransaction.findMany({
      where,
      select: {
        id: true,
        processor: true,
        currency: true,
        buyerAmount: true,
        processorFee: true,
        platformFee: true,
        sellerPayout: true,
        processorStatus: true,
        payoutStatus: true,
        completedAt: true,
        payoutCompletedAt: true,
        reconciliationStatus: true,
        reconciliationNotes: true,
        failureReason: true,
        buyer: {
          select: { email: true, name: true },
        },
        seller: {
          select: { email: true, name: true },
        },
      },
      orderBy: { completedAt: 'desc' },
      skip,
      take: limit,
    })

    const total = await prisma.paymentTransaction.count({ where })

    // Calculate processor-specific summaries
    const processorSummaries = await prisma.paymentTransaction.groupBy({
      by: ['processor'],
      where,
      _sum: {
        buyerAmount: true,
        processorFee: true,
        platformFee: true,
        sellerPayout: true,
      },
      _count: true,
    })

    // Calculate status breakdown
    const statusBreakdown = await prisma.paymentTransaction.groupBy({
      by: ['payoutStatus'],
      where,
      _count: true,
      _sum: {
        sellerPayout: true,
      },
    })

    // Get reconciliation reports
    const reports = await prisma.paymentReconciliationReport.findMany({
      where: processor ? { processor } : {},
      orderBy: { reportDate: 'desc' },
      take: 10,
    })

    // Calculate overall metrics
    const totalProcessed = await prisma.paymentTransaction.aggregate({
      where,
      _sum: {
        buyerAmount: true,
        processorFee: true,
        platformFee: true,
        sellerPayout: true,
      },
      _count: true,
    })

    // Calculate pending payouts
    const pendingPayouts = await prisma.paymentTransaction.aggregate({
      where: {
        ...where,
        payoutStatus: 'PENDING',
      },
      _sum: {
        sellerPayout: true,
      },
    })

    return NextResponse.json({
      success: true,
      transactions,
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
      overview: {
        totalTransactions: totalProcessed._count,
        totalRevenue: totalProcessed._sum.buyerAmount || 0,
        totalProcessorFees: totalProcessed._sum.processorFee || 0,
        totalPlatformFees: totalProcessed._sum.platformFee || 0,
        totalPayouts: totalProcessed._sum.sellerPayout || 0,
        pendingPayouts: pendingPayouts._sum.sellerPayout || 0,
      },
      processorSummaries: Object.fromEntries(
        processorSummaries.map((ps) => [
          ps.processor,
          {
            count: ps._count,
            revenue: ps._sum.buyerAmount || 0,
            fees: ps._sum.processorFee || 0,
            platformFees: ps._sum.platformFee || 0,
            payouts: ps._sum.sellerPayout || 0,
          },
        ])
      ),
      statusBreakdown: Object.fromEntries(
        statusBreakdown.map((sb) => [
          sb.payoutStatus,
          { count: sb._count, total: sb._sum.sellerPayout || 0 },
        ])
      ),
      reconciliationReports: reports,
    })
  } catch (error) {
    console.error('Error fetching payment reconciliation:', error)
    return NextResponse.json(
      { success: false, message: 'Failed to fetch reconciliation data' },
      { status: 500 }
    )
  }
}

/**
 * POST /api/admin/payment-reconciliation
 * Create a new reconciliation report for a processor
 */
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)

    if (!session?.user || session.user.role !== 'ADMIN') {
      return NextResponse.json(
        { success: false, message: 'Admin access required' },
        { status: 403 }
      )
    }

    const body = await request.json()
    const { processor, periodStart, periodEnd, expectedBalance, actualBalance } = body

    if (!processor || !periodStart || !periodEnd) {
      return NextResponse.json(
        { success: false, message: 'Missing required fields' },
        { status: 400 }
      )
    }

    // Calculate summary from transactions in this period
    const summary = await prisma.paymentTransaction.aggregate({
      where: {
        processor,
        completedAt: {
          gte: new Date(periodStart),
          lte: new Date(periodEnd),
        },
      },
      _sum: {
        sellerPayout: true,
      },
      _count: {
        _all: true,
      },
    })

    const statusSummary = await prisma.paymentTransaction.groupBy({
      by: ['payoutStatus'],
      where: {
        processor,
        completedAt: {
          gte: new Date(periodStart),
          lte: new Date(periodEnd),
        },
      },
      _sum: {
        sellerPayout: true,
      },
      _count: true,
    })

    // Create the report
    const report = await prisma.paymentReconciliationReport.create({
      data: {
        processor,
        reportDate: new Date(),
        periodStart: new Date(periodStart),
        periodEnd: new Date(periodEnd),
        expectedBalance: expectedBalance || 0,
        actualBalance: actualBalance || 0,
        discrepancy: (actualBalance || 0) - (expectedBalance || 0),
        completedTxnCount: statusSummary.find((s) => s.payoutStatus === 'COMPLETED')?._count || 0,
        pendingTxnCount: statusSummary.find((s) => s.payoutStatus === 'PENDING')?._count || 0,
        failedTxnCount: statusSummary.find((s) => s.payoutStatus === 'FAILED')?._count || 0,
        totalProcessed: summary._sum.sellerPayout || 0,
        payoutCount: summary._count._all || 0,
        payoutTotal: summary._sum.sellerPayout || 0,
        avgPayoutTime: 0, // Default value
        failedPayouts: 0, // Default value
      },
    })

    return NextResponse.json({
      success: true,
      report,
    })
  } catch (error) {
    console.error('Error creating reconciliation report:', error)
    return NextResponse.json(
      { success: false, message: 'Failed to create report' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'
import { prismaErrorResponse } from '@/lib/prismaError'

/**
 * GET /api/admin/subscriptions
 * Get all active subscriptions with user details
 * 
 * Query params:
 * - tier: 'STARTER' | 'PRO' | 'VIP' (filter)
 * - search: search by email or name
 * - sort: 'expiresAt' | 'subscriptionTier' | 'createdAt'
 * - status: 'ACTIVE' | 'EXPIRED' | 'TRIAL'
 * - page: pagination (default 1)
 * - limit: items per page (default 20, max 100)
 */
export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    // Check admin role
    const admin = await prisma.user.findUnique({
      where: { id: session.user.id },
      select: { role: true }
    })

    if (admin?.role !== 'ADMIN') {
      return NextResponse.json({ error: 'Admin access required' }, { status: 403 })
    }

    // Parse query params
    const { searchParams } = new URL(request.url)
    const tier = searchParams.get('tier')
    const search = searchParams.get('search') || ''
    const sort = searchParams.get('sort') || 'expiresAt'
    const status = searchParams.get('status') || 'ACTIVE'
    const page = Math.max(1, parseInt(searchParams.get('page') || '1'))
    const limit = Math.min(100, Math.max(1, parseInt(searchParams.get('limit') || '20')))
    const skip = (page - 1) * limit

    // Build filter
    const whereFilter: any = {}

    // Subscription tier filter
    if (tier && ['STARTER', 'PRO', 'VIP'].includes(tier)) {
      whereFilter.subscriptionTier = tier
    }

    // Status filter
    if (status === 'TRIAL') {
      whereFilter.AND = [
        { proTrialActivated: true },
        { proTrialExpiresAt: { gt: new Date() } }
      ]
    } else if (status === 'ACTIVE') {
      whereFilter.AND = [
        {
          OR: [
            { // Paid subscription active
              AND: [
                { proSubscriptionActive: true },
                { proSubscriptionExpiresAt: { gt: new Date() } }
              ]
            },
            { // Or trial still active
              AND: [
                { proTrialActivated: true },
                { proTrialExpiresAt: { gt: new Date() } }
              ]
            }
          ]
        }
      ]
    } else if (status === 'EXPIRED') {
      whereFilter.AND = [
        {
          OR: [
            { proSubscriptionExpiresAt: { lte: new Date() } },
            { proTrialExpiresAt: { lte: new Date() } }
          ]
        }
      ]
    }

    // Search filter
    if (search) {
      whereFilter.AND = (whereFilter.AND || [])
      whereFilter.AND.push({
        OR: [
          { email: { contains: search, mode: 'insensitive' } },
          { name: { contains: search, mode: 'insensitive' } },
          { displayName: { contains: search, mode: 'insensitive' } }
        ]
      })
    }

    // Get total count
    const total = await prisma.user.count({ where: whereFilter })

    // Get subscriptions
    const users = await prisma.user.findMany({
      where: whereFilter,
      select: {
        id: true,
        email: true,
        name: true,
        displayName: true,
        subscriptionTier: true,
        subscriptionPrice: true,
        billingCycle: true,
        proSubscriptionActive: true,
        proSubscriptionExpiresAt: true,
        proSubscriptionStartedAt: true,
        proTrialActivated: true,
        proTrialExpiresAt: true,
        totalEarnings: true,
        createdAt: true,
        role: true,
      },
      orderBy: sort === 'subscriptionTier' 
        ? { subscriptionTier: 'asc' }
        : sort === 'createdAt'
        ? { createdAt: 'desc' }
        : { proSubscriptionExpiresAt: 'asc' },
      skip,
      take: limit
    })

    const now = new Date()

    // Format response
    const subscriptions = users.map(user => {
      const isPaidActive = user.proSubscriptionActive && user.proSubscriptionExpiresAt && user.proSubscriptionExpiresAt > now
      const isTrialActive = user.proTrialActivated && user.proTrialExpiresAt && user.proTrialExpiresAt > now

      let daysRemaining = null
      let expiresAt = null
      let subscriptionType = null

      if (isPaidActive) {
        subscriptionType = 'PAID'
        expiresAt = user.proSubscriptionExpiresAt
        daysRemaining = Math.ceil((user.proSubscriptionExpiresAt!.getTime() - now.getTime()) / (1000 * 60 * 60 * 24))
      } else if (isTrialActive) {
        subscriptionType = 'TRIAL'
        expiresAt = user.proTrialExpiresAt
        daysRemaining = Math.ceil((user.proTrialExpiresAt!.getTime() - now.getTime()) / (1000 * 60 * 60 * 24))
      }

      return {
        id: user.id,
        email: user.email,
        name: user.name || user.displayName,
        tier: user.subscriptionTier,
        price: user.subscriptionPrice,
        billingCycle: user.billingCycle,
        subscriptionType, // 'PAID', 'TRIAL', null
        expiresAt,
        daysRemaining,
        status: isTrialActive || isPaidActive ? 'ACTIVE' : 'EXPIRED',
        startedAt: user.proSubscriptionStartedAt,
        trialActivatedAt: null,
        paidStartedAt: user.proSubscriptionStartedAt,
        totalEarnings: user.totalEarnings,
        joinedAt: user.createdAt,
        isAdmin: user.role === 'ADMIN',
      }
    })

    const totalPages = Math.ceil(total / limit)
    return NextResponse.json({
      subscriptions,
      pagination: {
        page,
        limit,
        total,
        pages: totalPages,
        hasMore: page < totalPages
      },
      filters: {
        tier,
        status,
        search
      }
    })
  } catch (error) {
    console.error('[GET /api/admin/subscriptions]', error)
    const prismaResp = prismaErrorResponse(error, 'Failed to fetch subscriptions')
    if (prismaResp) return prismaResp
    return NextResponse.json({ error: 'Failed to fetch subscriptions' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'
import { prismaErrorResponse } from '@/lib/prismaError'
import { checkAndUpdateSellerTier } from '@/lib/tier-management'

/**
 * Admin endpoint for managing user pro trials
 * 
 * PATCH - Reset, extend, or revoke trials
 * GET - Fetch trial information
 * 
 * Protected: Admin only
 */

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ userId: string }> }
) {
  const session = await getServerSession(authOptions)

  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // Check admin role
  const admin = await prisma.user.findUnique({
    where: { id: session.user.id },
    select: { role: true }
  })

  if (admin?.role !== 'ADMIN') {
    return NextResponse.json({ error: 'Admin access required' }, { status: 403 })
  }

  const { userId } = await params

  try {
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        name: true,
        email: true,
        proTrialActivated: true,
        proTrialActivatedAt: true,
        proTrialExpiresAt: true,
        totalEarnings: true,
        createdAt: true,
      }
    })

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const now = new Date()
    const isActive = user.proTrialActivated && 
      user.proTrialExpiresAt && 
      user.proTrialExpiresAt > now

    const daysRemaining = user.proTrialExpiresAt && user.proTrialExpiresAt > now
      ? Math.ceil((user.proTrialExpiresAt.getTime() - now.getTime()) / (1000 * 60 * 60 * 24))
      : 0

    return NextResponse.json({
      success: true,
      user: {
        id: user.id,
        name: user.name,
        email: user.email,
        totalEarnings: user.totalEarnings,
        createdAt: user.createdAt,
      },
      trial: {
        isActive,
        activated: user.proTrialActivated,
        activatedAt: user.proTrialActivatedAt,
        expiresAt: user.proTrialExpiresAt,
        daysRemaining,
      }
    })
  } catch (error) {
    console.error('[Admin Trial GET] Error:', error)
    return NextResponse.json({ error: 'Failed to fetch trial info' }, { status: 500 })
  }
}

export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ userId: string }> }
) {
  const session = await getServerSession(authOptions)

  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // Check admin role
  const admin = await prisma.user.findUnique({
    where: { id: session.user.id },
    select: { role: true }
  })

  if (admin?.role !== 'ADMIN') {
    return NextResponse.json({ error: 'Admin access required' }, { status: 403 })
  }

  const { userId } = await params

  try {
    const body = await req.json()
    const { action, reason } = body

    if (!action || !['reset', 'extend', 'revoke'].includes(action)) {
      return NextResponse.json(
        { error: 'Invalid action. Must be: reset, extend, or revoke' },
        { status: 400 }
      )
    }

    if (!reason) {
      return NextResponse.json(
        { error: 'Reason is required for audit trail' },
        { status: 400 }
      )
    }

    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { id: true, email: true, name: true }
    })

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    let updateData: any = {}
    let logMessage = ''

    switch (action) {
      case 'reset':
        // Deactivate and re-activate trial (resetting the 30-day clock)
        updateData = {
          proTrialActivated: true,
          proTrialActivatedAt: new Date(),
          proTrialExpiresAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000), // 30 days
        }
        logMessage = `[Admin] Reset trial for ${user.email} - Reason: ${reason}`
        break

      case 'extend':
        // Add 30 more days to current expiry
        const currentExpiry = await prisma.user.findUnique({
          where: { id: userId },
          select: { proTrialExpiresAt: true }
        })

        const baseDate = currentExpiry?.proTrialExpiresAt || new Date()
        updateData = {
          proTrialActivated: true,
          proTrialExpiresAt: new Date(baseDate.getTime() + 30 * 24 * 60 * 60 * 1000),
        }
        logMessage = `[Admin] Extended trial for ${user.email} by 30 days - Reason: ${reason}`
        break

      case 'revoke':
        // Immediately deactivate trial
        updateData = {
          proTrialActivated: false,
          proTrialExpiresAt: new Date(), // Set to now (expired)
          proTrialActivatedAt: null,
        }
        logMessage = `[Admin] Revoked trial for ${user.email} - Reason: ${reason}`
        break
    }

    // Update user
    const updatedUser = await prisma.user.update({
      where: { id: userId },
      data: updateData,
      select: {
        proTrialActivated: true,
        proTrialActivatedAt: true,
        proTrialExpiresAt: true,
      }
    })

    // If revoked, recalculate tier
    if (action === 'revoke') {
      await checkAndUpdateSellerTier(userId)
    }

    // Log admin action
    console.log(logMessage)

    // TODO: Store audit log in database
    // Requires AdminAuditLog model in schema:
    // - adminId (who made the change)
    // - action (trial_management)
    // - targetUserId (affected user)
    // - details (JSON: action, reason, trial info)
    // - timestamp
    // 
    // Example implementation:
    // if (prisma.adminAuditLog) {
    //   await prisma.adminAuditLog.create({
    //     data: {
    //       adminId: session.user.id,
    //       action: 'trial_management',
    //       targetUserId: userId,
    //       details: { action, reason },
    //       createdAt: new Date(),
    //     }
    //   })
    // }

    return NextResponse.json({
      success: true,
      message: `Trial ${action} successful`,
      trial: updatedUser,
    })
  } catch (error) {
    console.error('[Admin Trial PATCH] Error:', error)
    const prismaResp = prismaErrorResponse(error, 'Database operation failed')
    if (prismaResp) return prismaResp

    return NextResponse.json({ error: 'Failed to update trial' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'
import { prismaErrorResponse } from '@/lib/prismaError'

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)

    if (!session?.user?.email) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    // Verify admin
    const admin = await prisma.user.findUnique({
      where: { email: session.user.email },
    })

    if (admin?.role !== 'ADMIN') {
      return NextResponse.json(
        { error: 'Forbidden' },
        { status: 403 }
      )
    }

    // Get query params
    const searchParams = request.nextUrl.searchParams
    const status = searchParams.get('status')
    const stockStatus = searchParams.get('stockStatus') // 'in_stock' or 'out_of_stock'
    const sellerId = searchParams.get('sellerId')
    const dateFrom = searchParams.get('dateFrom')
    const dateTo = searchParams.get('dateTo')
    const searchQuery = searchParams.get('search')

    // Build where clause
    const where: any = {}

    // Always exclude products that never made it to warehouse
    // Only show products that reached warehouse: LIVE, OUT_OF_STOCK, IN_RETURN, RETURN_REQUESTED, RETURN_SHIPPED, RETURNED_TO_SELLER, VERIFICATION_PASSED, RECEIVED_BY_ADMIN
    const warehouseStatuses = [
      'LIVE',
      'OUT_OF_STOCK',
      'IN_RETURN',
      'RETURN_REQUESTED',
      'RETURN_SHIPPED',
      'RETURNED_TO_SELLER',
      'VERIFICATION_PASSED',
      'RECEIVED_BY_ADMIN'
    ]
    where.status = { in: warehouseStatuses }

    // Only filter by specific status if explicitly provided
    if (status && warehouseStatuses.includes(status)) {
      where.status = status
    }

    if (sellerId) {
      where.sellerId = sellerId
    }

    if (stockStatus === 'in_stock') {
      where.currentStock = { gt: 0 }
    } else if (stockStatus === 'out_of_stock') {
      where.currentStock = 0
    }

    if (dateFrom) {
      where.warehouseReceivedAt = {
        ...where.warehouseReceivedAt,
        gte: new Date(dateFrom),
      }
    }

    if (dateTo) {
      where.warehouseReceivedAt = {
        ...where.warehouseReceivedAt,
        lte: new Date(dateTo),
      }
    }

    if (searchQuery) {
      // Combine search with status filter using AND
      where.AND = [
        {
          OR: [
            { title: { contains: searchQuery, mode: 'insensitive' } },
            { id: { contains: searchQuery } },
            { seller: { name: { contains: searchQuery, mode: 'insensitive' } } },
            { seller: { email: { contains: searchQuery, mode: 'insensitive' } } },
          ]
        }
      ]
    }

    // Fetch products with seller info
    const products = await prisma.boutiqueProduct.findMany({
      where,
      select: {
        id: true,
        title: true,
        slug: true,
        basePrice: true,
        salePrice: true,
        currency: true,
        currentStock: true,
        originalStock: true,
        thumbnailUrl: true,
        status: true,
        warehouseReceivedAt: true,
        warehouseLocation: true,
        warehouseExpiresAt: true,
        month5NotificationSent: true,
        condition: true,
        shipmentId: true,
        seller: {
          select: {
            id: true,
            name: true,
            email: true,
            displayName: true,
          },
        },
      },
      orderBy: { warehouseReceivedAt: 'desc' },
    })

    // Fetch shipment info for each product
    const productsWithShipment = await Promise.all(
      products.map(async (product) => {
        let shipmentWarehouseAddress = null
        if (product.shipmentId) {
          const shipment = await prisma.sellerToAdminShipment.findUnique({
            where: { id: product.shipmentId },
            select: { warehouseAddress: true }
          })
          shipmentWarehouseAddress = shipment?.warehouseAddress
        }
        return { ...product, shipmentWarehouseAddress }
      })
    )

    // Enrich with calculated data and sales history
    const enrichedProducts = await Promise.all(
      productsWithShipment.map(async (product) => {
        const STORAGE_CYCLE_DAYS = 181
        
        const daysInWarehouse = product.warehouseReceivedAt
          ? Math.floor(
              (Date.now() - new Date(product.warehouseReceivedAt).getTime()) /
                (1000 * 60 * 60 * 24)
            )
          : 0

        const storageCycle = Math.floor(daysInWarehouse / STORAGE_CYCLE_DAYS) + 1
        const daysInCurrentCycle = daysInWarehouse % STORAGE_CYCLE_DAYS

        const daysUntilExpiry = product.warehouseExpiresAt
          ? Math.ceil(
              (new Date(product.warehouseExpiresAt).getTime() - Date.now()) /
                (1000 * 60 * 60 * 24)
            )
          : 0

        const isLowStock = (product.currentStock || 0) <= 5
        const isInMonth5 = daysInCurrentCycle >= 119 && daysInCurrentCycle < 180

        // Fetch sales history for this product
        const salesHistory = await prisma.boutiqueOrderItem.findMany({
          where: {
            productId: product.id,
            order: {
              status: { in: ['PAID', 'PROCESSING', 'SHIPPED', 'DELIVERED', 'COMPLETED'] }
            }
          },
          select: {
            id: true,
            quantity: true,
            price: true,
            variantSnapshot: true,
            createdAt: true,
            variant: {
              select: { size: true, color: true }
            }
          },
          orderBy: { createdAt: 'desc' }
        })

        const totalSold = salesHistory.reduce((sum, item) => sum + item.quantity, 0)

        return {
          ...product,
          daysInWarehouse,
          daysInCurrentCycle,
          storageCycle,
          daysUntilExpiry,
          isLowStock,
          isInMonth5,
          displayPrice: product.salePrice || product.basePrice,
          totalSold,
          shipmentWarehouseAddress: product.shipmentWarehouseAddress,
          salesHistory: salesHistory.map(item => ({
            quantity: item.quantity,
            variantInfo: item.variant ? `${item.variant.color || ''} ${item.variant.size || ''}`.trim() : (item.variantSnapshot ? `${(item.variantSnapshot as any).color || ''} ${(item.variantSnapshot as any).size || ''}`.trim() : 'Standard'),
            soldAt: item.createdAt,
            price: item.price
          }))
        }
      })
    )

    return NextResponse.json({
      products: enrichedProducts,
      total: enrichedProducts.length,
    })
  } catch (error) {
    console.error('Admin warehouse inventory fetch error:', error)

    const prismaResp = prismaErrorResponse(
      error,
      'Database temporarily unavailable'
    )
    if (prismaResp) return prismaResp

    return NextResponse.json(
      { error: 'Failed to fetch warehouse inventory' },
      { status: 500 }
    )
  }
}

// Admin resolves a seller appeal
// PUT - Update appeal status and resolution

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import prisma from '@/lib/prisma';
import { sendEmail } from '@/lib/email';

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ appealId: string }> }
) {
  try {
    const { appealId } = await params;
    const session = await getServerSession(authOptions);

    if (!session?.user || session.user.role !== 'ADMIN') {
      return NextResponse.json(
        { success: false, message: 'Admin access required' },
        { status: 403 }
      );
    }

    const body = await request.json();
    const { appealStatus, resolutionAction, resolutionNotes } = body;

    const validStatuses = ['PENDING', 'APPROVED', 'REJECTED', 'RESOLVED'];
    // Resolution action meanings:
    // - OVERTURN_DECISION: Reverse the original decision (flip denial to approval or vice versa)
    // - UPHOLD_DECISION: Keep the original decision as is (support admin's original ruling)
    // - COMPENSATE_SELLER: Give seller compensation without changing the decision
    const validActions = ['OVERTURN_DECISION', 'UPHOLD_DECISION', 'COMPENSATE_SELLER'];

    if (!appealStatus || !validStatuses.includes(appealStatus)) {
      return NextResponse.json(
        { success: false, message: `Invalid status. Must be one of: ${validStatuses.join(', ')}` },
        { status: 400 }
      );
    }

    // Prevent downgrading from a resolved state back to PENDING
    // First, check current status to prevent backtracking
    let currentAppeal: any = null;
    try {
      currentAppeal = await prisma.variantDiscrepancyAppeal.findUnique({
        where: { id: appealId },
        select: { appealStatus: true }
      });
    } catch (_e) {
      // Try dispute appeal if variant not found
      try {
        currentAppeal = await prisma.disputeAppeal.findUnique({
          where: { id: appealId },
          select: { status: true }
        });
        if (currentAppeal) {
          currentAppeal.appealStatus = currentAppeal.status;
        }
      } catch (_e2) {
        // Will be caught by update operations below
      }
    }

    if (currentAppeal && currentAppeal.appealStatus !== 'PENDING' && appealStatus === 'PENDING') {
      return NextResponse.json(
        { success: false, message: 'Cannot change a resolved appeal back to pending' },
        { status: 400 }
      );
    }

    if (appealStatus !== 'PENDING' && (!resolutionAction || !validActions.includes(resolutionAction))) {
      return NextResponse.json(
        { success: false, message: `Invalid action. Must be one of: ${validActions.join(', ')}` },
        { status: 400 }
      );
    }

    if (resolutionNotes && resolutionNotes.length > 1000) {
      return NextResponse.json(
        { success: false, message: 'Resolution notes must be under 1000 characters' },
        { status: 400 }
      );
    }

    // Try to update variant discrepancy appeal first
    let appeal: any = null;
    let isVariantAppeal = false;
    
    try {
      appeal = await prisma.variantDiscrepancyAppeal.update({
        where: { id: appealId },
        data: {
          appealStatus,
          resolutionAction: appealStatus !== 'PENDING' ? resolutionAction : null,
          resolutionNotes: resolutionNotes ? resolutionNotes.substring(0, 1000) : null,
          resolvedBy: appealStatus !== 'PENDING' ? session.user.id : null,
          resolvedAt: appealStatus !== 'PENDING' ? new Date() : null,
        },
        include: {
          decision: {
            include: {
              discrepancy: {
                include: {
                  shipment: {
                    select: { id: true, sellerId: true, seller: { select: { name: true, email: true } } },
                  },
                  variant: {
                    include: {
                      product: { select: { title: true } },
                    },
                  },
                },
              },
            },
          },
          seller: { select: { name: true, email: true } },
        },
      });
      isVariantAppeal = true;
    } catch (variantError: any) {
      // If not found, try dispute appeal
      if (variantError?.code === 'P2025') {
        appeal = await prisma.disputeAppeal.update({
          where: { id: appealId },
          data: {
            status: appealStatus,
            adminResponse: resolutionNotes ? resolutionNotes.substring(0, 1000) : null,
            reviewedBy: appealStatus !== 'PENDING' ? session.user.id : null,
            reviewedAt: appealStatus !== 'PENDING' ? new Date() : null,
          },
          include: {
            seller: { select: { id: true, name: true, email: true } },
          },
        });
        isVariantAppeal = false;
      } else {
        throw variantError;
      }
    }

    // Notify seller of resolution
    if (appealStatus !== 'PENDING') {
      try {
        const statusMap: Record<string, string> = {
          APPROVED: 'Γ£à Appeal Approved',
          REJECTED: 'Γ¥î Appeal Rejected',
          RESOLVED: 'Γ£ô Appeal Resolved',
        };
        const statusText = statusMap[appealStatus] || 'Appeal Updated';

        const actionMap: Record<string, string> = {
          OVERTURN_DECISION: 'Your appeal has been approved. The original decision has been overturned.',
          UPHOLD_DECISION: 'Your appeal has been reviewed. The original decision has been upheld.',
          COMPENSATE_SELLER: 'Your appeal has been approved for compensation review.',
        };
        const actionText = actionMap[resolutionAction] || 'Your appeal has been reviewed.';

        let emailSubject = statusText;
        let emailHtml = '';

        if (isVariantAppeal) {
          const productTitle = appeal.decision?.discrepancy?.variant?.product?.title || 'Unknown Product';
          emailSubject = `${statusText}: ${productTitle}`;
          emailHtml = `
            <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
              <div style="background-color: ${appealStatus === 'APPROVED' ? '#D1FAE5' : '#FEE2E2'}; border-left: 4px solid ${appealStatus === 'APPROVED' ? '#059669' : '#DC2626'}; padding: 20px; border-radius: 4px;">
                <p style="margin: 0; color: ${appealStatus === 'APPROVED' ? '#065F46' : '#7F1D1D'}; font-weight: bold;">${statusText}</p>
                <p style="color: ${appealStatus === 'APPROVED' ? '#065F46' : '#7F1D1D'}; margin: 10px 0 0 0;">
                  ${actionText}
                </p>
                <p style="color: ${appealStatus === 'APPROVED' ? '#065F46' : '#7F1D1D'}; margin: 10px 0 0 0;">
                  <strong>Product:</strong> ${productTitle}
                </p>
                ${resolutionNotes ? `
                  <p style="color: ${appealStatus === 'APPROVED' ? '#065F46' : '#7F1D1D'}; margin: 10px 0 0 0;">
                    <strong>Admin Notes:</strong><br/>
                    ${resolutionNotes.replace(/\n/g, '<br/>')}
                  </p>
                ` : ''}
              </div>
            </div>
          `;
        } else {
          // Dispute appeal
          emailSubject = `${statusText}: Dispute Appeal`;
          emailHtml = `
            <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
              <div style="background-color: ${appealStatus === 'APPROVED' ? '#D1FAE5' : '#FEE2E2'}; border-left: 4px solid ${appealStatus === 'APPROVED' ? '#059669' : '#DC2626'}; padding: 20px; border-radius: 4px;">
                <p style="margin: 0; color: ${appealStatus === 'APPROVED' ? '#065F46' : '#7F1D1D'}; font-weight: bold;">${statusText}</p>
                <p style="color: ${appealStatus === 'APPROVED' ? '#065F46' : '#7F1D1D'}; margin: 10px 0 0 0;">
                  ${actionText}
                </p>
                ${resolutionNotes ? `
                  <p style="color: ${appealStatus === 'APPROVED' ? '#065F46' : '#7F1D1D'}; margin: 10px 0 0 0;">
                    <strong>Admin Response:</strong><br/>
                    ${resolutionNotes.replace(/\n/g, '<br/>')}
                  </p>
                ` : ''}
              </div>
            </div>
          `;
        }

        await sendEmail({
          to: appeal.seller.email,
          subject: emailSubject,
          text: `Your appeal has been updated. Status: ${statusText}`,
          html: emailHtml,
        });
      } catch (emailError) {
        console.error('Failed to notify seller of appeal resolution:', emailError);
      }
    }

    return NextResponse.json({
      success: true,
      message: 'Appeal updated',
      appeal,
    });
  } catch (error) {
    console.error('Error updating appeal:', error);
    return NextResponse.json(
      { success: false, message: 'Failed to update appeal', error: (error as Error).message },
      { status: 500 }
    );
  }
}

// Admin lists all seller appeals (both variant discrepancy and dispute appeals)
// GET - List appeals with filtering

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import prisma from '@/lib/prisma';
import { prismaErrorResponse } from '@/lib/prismaError';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user || session.user.role !== 'ADMIN') {
      return NextResponse.json(
        { success: false, message: 'Admin access required' },
        { status: 403 }
      );
    }

    const { searchParams } = new URL(request.url);
    const status = searchParams.get('status') || 'PENDING';
    const sort = searchParams.get('sort') || 'newest';
    const appealType = searchParams.get('type') || 'all'; // 'all', 'discrepancy', 'dispute'

    // Fetch both appeal types in parallel
    const [variantAppeals, disputeAppeals] = await Promise.all([
      // Fetch variant discrepancy appeals - minimal data for list view
      (appealType === 'all' || appealType === 'discrepancy')
        ? prisma.variantDiscrepancyAppeal.findMany({
            where: status === 'all' ? {} : { appealStatus: status },
            select: {
              id: true,
              appealStatus: true,
              reason: true,
              resolutionNotes: true,
              createdAt: true,
              seller: { select: { id: true, name: true, email: true } },
            },
            take: 100,
            orderBy: { createdAt: sort === 'oldest' ? 'asc' : 'desc' },
          }).then(appeals =>
            appeals.map(a => ({
              ...a,
              type: 'discrepancy',
              appealTitle: 'Warehouse Discrepancy Appeal',
              sellerName: a.seller?.name || 'Unknown Seller',
              sellerEmail: a.seller?.email || '',
            }))
          )
        : [],
      
      // Fetch dispute appeals - minimal data for list view
      (appealType === 'all' || appealType === 'dispute')
        ? (() => {
            let whereCondition: any = {};
            if (status !== 'all') {
              if (status === 'PENDING') {
                whereCondition = { status: { in: ['SUBMITTED', 'UNDER_REVIEW'] } };
              } else if (status === 'APPROVED') {
                whereCondition = { status: 'APPROVED' };
              } else if (status === 'REJECTED') {
                whereCondition = { status: 'DENIED' };              } else if (status === 'RESOLVED') {
                // RESOLVED disputes are marked as APPROVED or DENIED with reviewedAt timestamp
                whereCondition = { reviewedAt: { not: null }, status: { in: ['APPROVED', 'DENIED'] } }              }
            }
            return prisma.disputeAppeal.findMany({
              where: whereCondition,
              include: {
                seller: { select: { id: true, name: true, email: true } },
              },
              take: 100,
              orderBy: { submittedAt: sort === 'oldest' ? 'asc' : 'desc' },
            }).then(appeals =>
              appeals.map(a => ({
                id: a.id,
                status: a.status,
                originalDisputeNumber: a.originalDisputeNumber,
                reason: a.reason,
                notes: a.notes,
                submittedAt: a.submittedAt,
                type: 'dispute',
                appealTitle: `Dispute ${a.originalDisputeNumber}`,
                sellerName: a.seller?.name || 'Unknown Seller',
                sellerEmail: a.seller?.email || '',
                appealStatus: a.status,
                createdAt: a.submittedAt,
                resolutionNotes: a.adminResponse || '', // Map adminResponse to resolutionNotes for UI consistency
              }))
            );
          })()
        : [],
    ]);

    // Combine appeals (already sorted by database)
    const allAppeals = [...variantAppeals, ...disputeAppeals];
    
    // If fetching both types, sort by createdAt since parallel queries don't guarantee order
    if (appealType === 'all') {
      if (sort === 'oldest') {
        allAppeals.sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
      } else {
        allAppeals.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
      }
    }

    const response = NextResponse.json({ success: true, appeals: allAppeals });
    // Cache for 30 seconds to reduce database load while keeping data relatively fresh
    response.headers.set('Cache-Control', 'private, max-age=30');
    return response;
  } catch (error) {
    console.error('Error fetching appeals:', error);
    const prismaResp = prismaErrorResponse(error, 'Failed to fetch appeals');
    if (prismaResp) return prismaResp;

    return NextResponse.json(
      { success: false, message: 'Failed to fetch appeals' },
      { status: 500 }
    );
  }
}

// Get variant discrepancies with filtering and sorting
// GET - Retrieve discrepancies for admin dashboard

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import prisma from '@/lib/prisma';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user || session.user.role !== 'ADMIN') {
      return NextResponse.json(
        { success: false, message: 'Admin access required' },
        { status: 403 }
      );
    }

    const { searchParams } = new URL(request.url);
    const statusFilter = searchParams.get('status') || 'PENDING';
    const ageFilter = searchParams.get('age') || 'all';
    const sortBy = searchParams.get('sort') || 'oldest';

    // Build filter
    const where: any = {};

    if (statusFilter !== 'all') {
      where.acceptanceStatus = statusFilter;
    }

    // Get discrepancies with their shipment and variant info
    let discrepancies = await prisma.variantDiscrepancy.findMany({
      where,
      include: {
        variant: {
          include: {
            product: {
              select: {
                id: true,
                title: true,
              },
            },
          },
        },
        shipment: {
          select: {
            id: true,
            seller: {
              select: {
                id: true,
                name: true,
                email: true,
              },
            },
          },
        },
      },
      orderBy: { createdAt: 'asc' },
      take: 500, // Limit to 500 for performance
    });

    // Apply age filter on client side since we need to calculate days
    if (ageFilter !== 'all') {
      const now = Date.now();
      discrepancies = discrepancies.filter(d => {
        const daysOld = Math.floor((now - new Date(d.createdAt).getTime()) / (24 * 60 * 60 * 1000));
        if (ageFilter === '1-3') return daysOld >= 1 && daysOld <= 3;
        if (ageFilter === '4-6') return daysOld >= 4 && daysOld <= 6;
        if (ageFilter === '7+') return daysOld >= 7;
        return true;
      });
    }

    // Apply sorting
    if (sortBy === 'newest') {
      discrepancies = discrepancies.reverse();
    }

    return NextResponse.json({
      success: true,
      discrepancies,
      total: discrepancies.length,
    });
  } catch (error) {
    console.error('Error fetching discrepancies:', error);
    return NextResponse.json(
      { success: false, message: 'Failed to fetch discrepancies', error: (error as Error).message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'
import { sendEmail } from '@/lib/email'
import { requiresOverrideReason, type BoutiqueOrderStatus } from '@/lib/boutique/statusMapping'

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ orderId: string }> }
) {
  try {
    const session = await getServerSession(authOptions)
    if (!session || (session.user as any).role !== 'ADMIN') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { orderId } = await params

    const order = await prisma.boutiqueOrder.findUnique({
      where: { id: orderId },
      include: {
        buyer: {
          select: {
            id: true,
            name: true,
            email: true,
            phone: true, // Admin only - for disputes/urgent contact
          },
        },
        seller: {
          select: {
            id: true,
            name: true,
            email: true,
            phone: true, // Admin only - for disputes/urgent contact
            sellerAccount: {
              select: {
                bankName: true,
                accountNumber: true,
                accountName: true,
              },
            },
          },
        },
        items: {
          include: {
            product: {
              include: {
                seller: {
                  select: {
                    id: true,
                    name: true,
                    email: true,
                  },
                },
                category: true,
              },
            },
          },
        },
      },
    })

    if (!order) {
      return NextResponse.json({ error: 'Order not found' }, { status: 404 })
    }

    // Fetch audit logs separately to avoid 500 error if table doesn't exist yet
    const auditLogs: any[] = []
    try {
      const logs = await prisma.boutiqueOrderAuditLog.findMany({
        where: { orderId },
        include: {
          admin: {
            select: {
              id: true,
              name: true,
              email: true,
            },
          },
        },
        orderBy: {
          createdAt: 'desc',
        },
      })
      console.log(`[GET-ORDER] Fetched ${logs.length} audit logs for order ${orderId}`)
      auditLogs.push(...logs)
    } catch (error) {
      // Table doesn't exist yet or error occurred, continue without audit logs
      console.warn('Could not fetch audit logs:', error)
    }

    return NextResponse.json({ ...order, auditLogs })
  } catch (error) {
    console.error('Admin order detail error:', error)
    return NextResponse.json({ error: 'Failed to fetch order' }, { status: 500 })
  }
}

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ orderId: string }> }
) {
  try {
    const session = await getServerSession(authOptions)
    if (!session || (session.user as any).role !== 'ADMIN') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const adminId = (session.user as any).id
    const { orderId } = await params
    const body = await request.json()
    const { status, trackingNumber, trackingUrl, notes, overrideReason } = body

    console.log(`[PATCH-ORDER-V2] NEW VERSION - Received: orderId=${orderId}, status="${status}"`)
    console.log(`[PATCH-ORDER] Received: orderId=${orderId}, status="${status}" (type: ${typeof status}, empty: ${!status}), hasNotes=${!!notes}, adminId=${adminId}`)

    // Validate status if provided - all statuses that exist in the database
    // Note: Frontend shows simplified names (PENDING, PAID, etc.) but database has full names
    const validStatuses = [
      // Checkout/Payment statuses
      'PENDING_PAYMENT', 'PAYMENT_FAILED',
      // Core statuses
      'AWAITING_SELLER_CONFIRMATION', 'PAID', 'PROCESSING', 'SHIPPED', 'DELIVERED', 'COMPLETED',
      // Return/Refund statuses
      'RETURN_REQUESTED', 'RETURN_APPROVED', 'RETURN_SHIPPED', 'RETURN_RECEIVED',
      // Terminal statuses
      'CANCELLED', 'REFUNDED', 'DISPUTED'
    ]
    if (status && !validStatuses.includes(status)) {
      console.error('Invalid status attempted:', status, 'Valid statuses:', validStatuses)
      return NextResponse.json({ error: `Invalid status: ${status}. Valid options: ${validStatuses.join(', ')}` }, { status: 400 })
    }

    const existingOrder = await prisma.boutiqueOrder.findUnique({
      where: { id: orderId },
      include: {
        seller: { select: { id: true, name: true, email: true } },
      },
    })

    if (!existingOrder) {
      return NextResponse.json({ error: 'Order not found' }, { status: 404 })
    }

    console.log(`Updating order ${orderId}. Current status: "${existingOrder.status}", New status: "${status}", adminId: ${adminId}`)

    // Ensure we have valid status values
    if (!existingOrder.status) {
      console.error(`Order ${orderId} has no status value. Cannot update.`)
      return NextResponse.json({ error: 'Order has invalid status. Contact support.' }, { status: 400 })
    }

    // Check if status change is being made
    const isStatusChange = status && status !== existingOrder.status
    
    // Validate status transitions - certain changes require override reason
    if (isStatusChange) {
      const needsOverride = requiresOverrideReason(existingOrder.status as BoutiqueOrderStatus, status as BoutiqueOrderStatus)

      console.log(`Status change check: ${existingOrder.status} ΓåÆ ${status}, needsOverride=${needsOverride}, overrideReason="${overrideReason}"`)

      // If transition requires override reason, validate it
      if (needsOverride) {
        const reasonLength = overrideReason?.trim().length || 0
        if (!overrideReason || reasonLength < 10) {
          console.warn(`Status change blocked: ${existingOrder.status} ΓåÆ ${status}, override reason too short (${reasonLength} chars, need 10+)`)
          return NextResponse.json(
            { error: 'Override reason required for this status change (minimum 10 characters)', requiresReason: true },
            { status: 400 }
          )
        }
      }
    }

    // Build update data with status-specific timestamps
    const updateData: Record<string, unknown> = {}
    const changedFields: Record<string, unknown> = {}

    if (status) {
      updateData.status = status
      // Note: Don't add status to changedFields - it's tracked separately as oldStatus/newStatus in audit log
      // Set timestamps based on status change
      if (status === 'SHIPPED' && !existingOrder.shippedAt) {
        updateData.shippedAt = new Date()
      }
      if (status === 'DELIVERED' && !existingOrder.deliveredAt) {
        updateData.deliveredAt = new Date()
      }
      if (status === 'COMPLETED' && !existingOrder.completedAt) {
        updateData.completedAt = new Date()
      }
      if (status === 'REFUNDED' && !existingOrder.refundedAt) {
        updateData.refundedAt = new Date()
      }
    }
    if (trackingNumber !== undefined) {
      updateData.trackingNumber = trackingNumber
      changedFields.trackingNumber = trackingNumber
    }
    if (trackingUrl !== undefined) {
      updateData.trackingUrl = trackingUrl
      changedFields.trackingUrl = trackingUrl
    }
    if (notes !== undefined) {
      updateData.adminNotes = notes
      changedFields.adminNotes = notes
    }

    console.log(`[PATCH-ORDER] UpdateData keys: ${Object.keys(updateData).join(',')}, Values:`, updateData)

    const order = await prisma.boutiqueOrder.update({
      where: { id: orderId },
      data: updateData,
      include: {
        buyer: {
          select: {
            id: true,
            name: true,
            email: true,
            phone: true,
          },
        },
        seller: {
          select: {
            id: true,
            name: true,
            email: true,
            phone: true,
            sellerAccount: {
              select: {
                bankName: true,
                accountNumber: true,
                accountName: true,
              },
            },
          },
        },
        items: {
          include: {
            product: {
              select: {
                id: true,
                title: true,
                thumbnailUrl: true,
              },
            },
          },
        },
      },
    })

    console.log(`[PATCH-ORDER-UPDATED] Order ${orderId} updated successfully. New status: "${order.status}", Old status: "${existingOrder.status}", Updated fields: ${Object.keys(updateData).join(',')}`)

    // Handle stock restoration if order is being cancelled
    if (status === 'CANCELLED' && existingOrder.status !== 'CANCELLED') {
      const productsToCheck = new Set<string>();
      
      for (const item of order.items) {
        if (item.variantId) {
          // Restore stock to variant
          await prisma.boutiqueProductVariant.update({
            where: { id: item.variantId },
            data: { quantity: { increment: item.quantity } },
          });
        }
        if (item.productId) {
          productsToCheck.add(item.productId);
        }
      }
      
      // Check if any OUT_OF_STOCK products now have stock and restore them to LIVE
      for (const productId of productsToCheck) {
        const variants = await prisma.boutiqueProductVariant.findMany({
          where: { productId },
          select: { quantity: true },
        });
        const totalStock = variants.reduce((sum, v) => sum + v.quantity, 0);
        
        const product = await prisma.boutiqueProduct.findUnique({
          where: { id: productId },
          select: { status: true },
        });
        
        // If product is OUT_OF_STOCK and now has stock, restore to LIVE
        if (product?.status === 'OUT_OF_STOCK' && totalStock > 0) {
          await prisma.boutiqueProduct.update({
            where: { id: productId },
            data: { 
              status: 'LIVE',
              currentStock: totalStock,
            },
          });
          console.log(`[Admin Cancel] Product ${productId} restored to LIVE status (stock: ${totalStock})`);
        } else {
          // Sync currentStock field
          await prisma.boutiqueProduct.update({
            where: { id: productId },
            data: { currentStock: totalStock },
          });
        }
      }
    }
    const orderUrl = `${process.env.NEXTAUTH_URL}/boutique/orders/${order.id}`

    // Create audit log for this change
    // Always create audit log if there's a status change or other field updates
    const hasStatusChange = status && status !== existingOrder.status
    const hasOtherChanges = Object.keys(changedFields).length > 0
    const hasChanges = hasStatusChange || hasOtherChanges
    
    console.log(`[AUDIT-CHECK] hasStatusChange=${hasStatusChange}, hasOtherChanges=${hasOtherChanges}, hasChanges=${hasChanges}`)
    console.log(`[AUDIT-CHECK] status param="${status}", existingOrder.status="${existingOrder.status}", order.status="${order.status}"`)
    console.log(`[AUDIT-CHECK] updateData keys:`, Object.keys(updateData))
    console.log(`[AUDIT-CHECK] changedFields:`, changedFields)
    
    if (hasChanges) {
      const isManualStatusOverride = !!(status && status !== existingOrder.status && overrideReason)
      
      // Use the updated order status (what was actually applied), not the request status
      const auditNewStatus = order.status
      
      console.log(`[AUDIT-LOG-CREATE] Creating audit log - hasChanges=true`)
      console.log(`  - orderId: ${orderId}`)
      console.log(`  - oldStatus: ${existingOrder.status}`)
      console.log(`  - newStatus: ${auditNewStatus}`)
      console.log(`  - action: ${status ? 'STATUS_CHANGE' : 'NOTES_UPDATE'}`)
      console.log(`  - adminId: ${adminId}`)
      console.log(`  - changedFields:`, changedFields)
      
      try {
        console.log(`[AUDIT-LOG-DATA] About to create audit log`)
        console.log(`[AUDIT-LOG-DATA] orderId: "${orderId}" (${typeof orderId})`)
        console.log(`[AUDIT-LOG-DATA] adminId: "${adminId}" (${typeof adminId})`)
        console.log(`[AUDIT-LOG-DATA] isManualOverride: ${isManualStatusOverride}`)
        
        const auditLogEntry = await prisma.boutiqueOrderAuditLog.create({
          data: {
            order: { connect: { id: orderId } },
            action: status ? 'STATUS_CHANGE' : 'NOTES_UPDATE',
            oldStatus: existingOrder.status,
            newStatus: auditNewStatus || undefined,
            changedFields: hasOtherChanges ? (changedFields as any) : null,
            isManualOverride: isManualStatusOverride,
            overrideReason: overrideReason || undefined,
            triggerType: 'ADMIN',
            admin: adminId ? { connect: { id: adminId } } : undefined,
          },
        })
        console.log(`[AUDIT-SUCCESS] Audit log created with ID: ${auditLogEntry.id}`)
      } catch (auditError) {
        console.error('[AUDIT-FAILED] Audit log creation failed!')
        console.error('[AUDIT-ERROR-MESSAGE]', auditError instanceof Error ? auditError.message : String(auditError))
        if (auditError instanceof Error && auditError.stack) {
          console.error('[AUDIT-ERROR-STACK]', auditError.stack.split('\n').slice(0, 5).join('\n'))
        }
        // Don't throw - continue even if audit log fails
      }
    } else {
      console.log(`[AUDIT-SKIPPED] No changes detected - not creating audit log`)
      console.log(`  - status param: "${status}"`)
      console.log(`  - existingOrder.status: "${existingOrder.status}"`)
      console.log(`  - changedFields keys: ${Object.keys(changedFields).join(',')}`)
    }

    // Send notification emails based on status change
    if (status && status !== existingOrder.status) {
      const productTitle = order.items?.[0]?.product?.title || 'Your Product'
      
      // Email to buyer
      if (order.buyer?.email) {
