          })
        }
      }
    }

    // Fetch audit logs to include in response (so frontend doesn't need separate call)
    const auditLogs: any[] = []
    try {
      const logs = await prisma.boutiqueOrderAuditLog.findMany({
        where: { orderId },
        include: {
          admin: {
            select: {
              id: true,
              name: true,
              email: true,
            },
          },
        },
        orderBy: {
          createdAt: 'desc',
        },
      })
