export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)

    if (!session?.user || session.user.role !== 'ADMIN') {
      return NextResponse.json(
        { success: false, message: 'Admin access required' },
        { status: 403 }
      )
    }

    const body = await request.json()
    const { productId, sellerId, sellerEmail, sellerName, returnDate, rejectionReason } = body

    if (!productId || !sellerEmail || !returnDate) {
      return NextResponse.json(
        { success: false, message: 'Missing required fields' },
        { status: 400 }
      )
    }

    // Send the email
    const product = await prisma.boutiqueProduct.findUnique({
      where: { id: productId },
      select: { title: true, rejectionEmailSentCount: true },
    })

    const productTitle = product?.title || 'Your Product'

    const emailSent = await sendReturnEmail(
      sellerEmail,
      sellerName,
      productTitle,
      returnDate,
      rejectionReason || 'Quality check failed'
    )

    if (!emailSent) {
      console.warn('Email notification could not be sent (email service not configured), but return scheduled')
    }

    // Update product with email sent count
    await prisma.boutiqueProduct.update({
      where: { id: productId },
      data: {
        rejectionEmailSentCount: (product?.rejectionEmailSentCount || 0) + 1,
        rejectionEmailLastSentAt: new Date(),
      },
    })

    return NextResponse.json({
      success: true,
      message: 'Rejection email sent to seller',
      emailSent,
    })
  } catch (error) {
    console.error('Error scheduling return:', error)
    return NextResponse.json(
      { success: false, message: 'Failed to schedule return' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { approveRepostRequest, rejectRepostRequest } from '@/lib/boutique/warehouse'
import prisma from '@/lib/prisma'

// Simple in-memory cache for PENDING requests (5 second TTL)
const cache = {
  data: null as any,
  timestamp: 0,
  TTL: 5000 // 5 seconds
}

function isCacheValid() {
  return cache.data && Date.now() - cache.timestamp < cache.TTL
}

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (session?.user?.role !== 'ADMIN') {
      return NextResponse.json({ error: 'Admin only' }, { status: 403 })
    }

    const { searchParams } = new URL(request.url)
    const status = searchParams.get('status') || 'PENDING'
    const limit = Math.min(parseInt(searchParams.get('limit') || '50'), 100) // Cap at 100
    const page = Math.max(parseInt(searchParams.get('page') || '1'), 1)
    const skip = (page - 1) * limit

    // Check cache for PENDING requests on page 1
    if (status === 'PENDING' && page === 1 && isCacheValid()) {
      return NextResponse.json(
        { success: true, requests: cache.data, cached: true },
        { headers: { 'Cache-Control': 'private, max-age=5' } }
      )
    }

    // Optimized query with pagination
    const requests = await prisma.boutiqueRepostRequest.findMany({
      where: {
        status: status as any,
      },
      select: {
        id: true,
        productId: true,
        sellerId: true,
        reason: true,
        notes: true,
        originalStock: true,
        requestedStock: true,
        approvedStock: true,
        status: true,
        adminNotes: true,
        reviewedAt: true,
        daysInWarehouse: true,
        createdAt: true,
        product: {
          select: {
            id: true,
            title: true,
            basePrice: true,
            thumbnailUrl: true,
            receivedByAdminAt: true,
          },
        },
        seller: {
          select: {
            id: true,
            name: true,
            email: true,
          },
        },
      },
      orderBy: { createdAt: 'desc' },
      take: limit,
      skip: skip,
    })

    // Update cache for PENDING status
    if (status === 'PENDING' && page === 1) {
      cache.data = requests
      cache.timestamp = Date.now()
    }

    return NextResponse.json(
      { success: true, requests, page, limit },
      { headers: { 'Cache-Control': 'private, max-age=5' } }
    )
  } catch (error) {
    console.error('Error fetching repost requests:', error)
    return NextResponse.json({ error: 'Failed to fetch requests' }, { status: 500 })
  }
}

export async function PATCH(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (session?.user?.role !== 'ADMIN') {
      return NextResponse.json({ error: 'Admin only' }, { status: 403 })
    }

    const { requestId, action, adminNotes } = await request.json()

    if (!requestId || !action) {
      return NextResponse.json(
        { error: 'requestId and action required' },
        { status: 400 }
      )
    }

    if (action === 'APPROVE') {
      await approveRepostRequest(requestId, session.user.id, adminNotes)
      // Invalidate cache after approval
      cache.data = null
      cache.timestamp = 0
      return NextResponse.json({ success: true, message: 'Repost approved' })
    } else if (action === 'REJECT') {
      await rejectRepostRequest(requestId, session.user.id, adminNotes)
      // Invalidate cache after rejection
      cache.data = null
      cache.timestamp = 0
      return NextResponse.json({ success: true, message: 'Repost rejected' })
    }

    return NextResponse.json({ error: 'Invalid action' }, { status: 400 })
  } catch (error) {
    console.error('Error processing repost:', error)
    const message = error instanceof Error ? error.message : 'Failed to process request'
    return NextResponse.json({ error: message }, { status: 400 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'

// GET /api/boutique/products/[id]/reviews - Get reviews for a product
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id: productId } = await params
    const searchParams = request.nextUrl.searchParams
    const page = parseInt(searchParams.get('page') || '1')
    const limit = parseInt(searchParams.get('limit') || '10')
    const skip = (page - 1) * limit

    const [reviews, total, avgRating] = await Promise.all([
      prisma.boutiqueReview.findMany({
        where: { productId },
        include: {
          user: {
            select: {
              id: true,
              name: true,
              image: true,
            },
          },
        },
        orderBy: { createdAt: 'desc' },
        skip,
        take: limit,
      }),
      prisma.boutiqueReview.count({ where: { productId } }),
      prisma.boutiqueReview.aggregate({
        where: { productId },
        _avg: { rating: true },
      }),
    ])

    // Rating distribution
    const ratingDistribution = await prisma.boutiqueReview.groupBy({
      by: ['rating'],
      where: { productId },
      _count: true,
    })

    const distribution: Record<number, number> = { 5: 0, 4: 0, 3: 0, 2: 0, 1: 0 }
    ratingDistribution.forEach(r => {
      distribution[r.rating] = r._count
    })

    return NextResponse.json({
      success: true,
      reviews,
      total,
      page,
      totalPages: Math.ceil(total / limit),
      avgRating: avgRating._avg.rating || 0,
      distribution,
    })
  } catch (error) {
    console.error('Error fetching reviews:', error)
    return NextResponse.json(
      { success: false, message: 'Failed to fetch reviews' },
      { status: 500 }
    )
  }
}

// POST /api/boutique/products/[id]/reviews - Create a review (must have purchased)
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json(
        { success: false, message: 'Authentication required' },
        { status: 401 }
      )
    }

    const { id: productId } = await params
    const { rating, title, comment, fitRating } = await request.json()

    // Validate rating
    if (!rating || rating < 1 || rating > 5) {
      return NextResponse.json(
        { success: false, message: 'Rating must be between 1 and 5' },
        { status: 400 }
      )
    }

    // Check if product exists
    const product = await prisma.boutiqueProduct.findUnique({
      where: { id: productId },
      select: { id: true, sellerId: true },
    })

    if (!product) {
      return NextResponse.json(
        { success: false, message: 'Product not found' },
        { status: 404 }
      )
    }

    // Check if user has purchased this product (delivered orders only)
    const hasPurchased = await prisma.boutiqueOrder.findFirst({
      where: {
        buyerId: session.user.id,
        productId,
        status: { in: ['DELIVERED', 'COMPLETED'] },
      },
    })

    if (!hasPurchased) {
      return NextResponse.json(
        { success: false, message: 'You must purchase this product before reviewing' },
        { status: 403 }
      )
    }

    // Check if already reviewed
    const existingReview = await prisma.boutiqueReview.findFirst({
      where: {
        userId: session.user.id,
        productId,
      },
    })

    if (existingReview) {
      return NextResponse.json(
        { success: false, message: 'You have already reviewed this product' },
        { status: 400 }
      )
    }

    // Create review
    const review = await prisma.boutiqueReview.create({
      data: {
        userId: session.user.id,
        productId,
        rating,
        title: title || null,
        comment: comment || null,
        fitRating: fitRating || null,
      },
      include: {
        user: {
          select: {
            id: true,
            name: true,
            image: true,
          },
        },
      },
    })

    // Update product average rating
    const avgRating = await prisma.boutiqueReview.aggregate({
      where: { productId },
      _avg: { rating: true },
    })

    await prisma.boutiqueProduct.update({
      where: { id: productId },
      data: { avgRating: avgRating._avg.rating || 0 },
    })

    return NextResponse.json({
      success: true,
      message: 'Review submitted',
      review,
    })
  } catch (error) {
    console.error('Error creating review:', error)
    return NextResponse.json(
      { success: false, message: 'Failed to submit review' },
      { status: 500 }
    )
  }
}

// DELETE /api/boutique/products/[id]/reviews - Delete own review
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json(
        { success: false, message: 'Authentication required' },
        { status: 401 }
      )
    }

    const { id: productId } = await params
    const searchParams = request.nextUrl.searchParams
    const reviewId = searchParams.get('reviewId')

    if (!reviewId) {
      return NextResponse.json(
        { success: false, message: 'Review ID required' },
        { status: 400 }
      )
    }

    // Find the review
    const review = await prisma.boutiqueReview.findUnique({
      where: { id: reviewId },
    })

    if (!review) {
      return NextResponse.json(
        { success: false, message: 'Review not found' },
        { status: 404 }
      )
    }

    // Only allow owner or admin to delete
    const isAdmin = (session.user as any).role === 'ADMIN'
    if (review.userId !== session.user.id && !isAdmin) {
      return NextResponse.json(
        { success: false, message: 'Not authorized' },
        { status: 403 }
      )
    }

    // Delete review
    await prisma.boutiqueReview.delete({
      where: { id: reviewId },
    })

    // Update product average rating
    const avgRating = await prisma.boutiqueReview.aggregate({
      where: { productId },
      _avg: { rating: true },
    })

    await prisma.boutiqueProduct.update({
      where: { id: productId },
      data: { avgRating: avgRating._avg.rating || null },
    })

    return NextResponse.json({
      success: true,
      message: 'Review deleted',
    })
  } catch (error) {
    console.error('Error deleting review:', error)
    return NextResponse.json(
      { success: false, message: 'Failed to delete review' },
      { status: 500 }
    )
  }
}

// GET /api/boutique/products - Get boutique products (public listing)
// POST /api/boutique/products - Create new product (seller only)

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import prisma from '@/lib/prisma';
import { 
  PRODUCT_STATUS, 
  FULFILLMENT_METHOD, 
  needsSampleVerification,
  type FulfillmentMethod
} from '@/lib/boutique/constants';

// GET - List products (public)
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '20');
    const category = searchParams.get('category');
    const gender = searchParams.get('gender');
    const minPrice = searchParams.get('minPrice');
    const maxPrice = searchParams.get('maxPrice');
    const sort = searchParams.get('sort') || 'newest';
    const search = searchParams.get('search');
    const sellerId = searchParams.get('sellerId');

    const skip = (page - 1) * limit;

    // Build where clause - only show LIVE products (not in any return workflow)
    const where: Record<string, unknown> = {
      status: 'LIVE', // Product status must be exactly LIVE
    };

    if (category) {
      // Check if it's a parent or child category
      const categoryRecord = await prisma.boutiqueCategory.findUnique({
        where: { slug: category },
        include: { children: true },
      });

      if (categoryRecord) {
        if (categoryRecord.children.length > 0) {
          // Parent category - include all children
          where.OR = [
            { categoryId: categoryRecord.id },
            { categoryId: { in: categoryRecord.children.map(c => c.id) } },
          ];
        } else {
          where.categoryId = categoryRecord.id;
        }
      }
    }

    if (gender) {
      where.gender = gender;
    }

    if (minPrice || maxPrice) {
      where.basePrice = {};
      if (minPrice) (where.basePrice as Record<string, number>).gte = parseFloat(minPrice);
      if (maxPrice) (where.basePrice as Record<string, number>).lte = parseFloat(maxPrice);
    }

    if (search) {
      where.OR = [
        { title: { contains: search, mode: 'insensitive' } },
        { description: { contains: search, mode: 'insensitive' } },
        { tags: { has: search } },
      ];
    }

    if (sellerId) {
      where.sellerId = sellerId;
    }

    // Build orderBy
    let orderBy: Record<string, string> = { createdAt: 'desc' };
    switch (sort) {
      case 'price-low':
        orderBy = { basePrice: 'asc' };
        break;
      case 'price-high':
        orderBy = { basePrice: 'desc' };
        break;
      case 'popular':
        orderBy = { viewCount: 'desc' };
        break;
      case 'newest':
      default:
        orderBy = { approvedAt: 'desc' };
    }

    const [products, total] = await Promise.all([
      prisma.boutiqueProduct.findMany({
        where,
        include: {
          category: {
            select: { id: true, name: true, slug: true, parentId: true },
          },
          seller: {
            select: { id: true, name: true, image: true },
          },
          media: {
            where: { isApproved: true },
            orderBy: { sortOrder: 'asc' },
            take: 4,
          },
          variants: {
            where: { isActive: true, quantity: { gt: 0 } },
          },
          _count: {
            select: { reviews: true, favorites: true },
          },
        },
        orderBy,
        skip,
        take: limit,
      }),
      prisma.boutiqueProduct.count({ where }),
    ]);

    // Filter out products with no stock - check both variants AND currentStock
    const productsWithStock = await Promise.all(
      products.map(async (product) => {
        // For products with variants, sum variant quantities
        const allVariants = await prisma.boutiqueProductVariant.findMany({
          where: { 
            productId: product.id,
            isActive: true,
          },
          select: { quantity: true },
        });
        const variantStock = allVariants.reduce((sum, v) => sum + v.quantity, 0);
        
        // Use currentStock if no variants (ADMIN_STOCK products), otherwise use variant stock
        const totalStock = allVariants.length > 0 ? variantStock : (product.currentStock || 0);
        return { product, totalStock };
      })
    );

    const filteredProducts = productsWithStock
      .filter(({ totalStock }) => {
        return totalStock > 0;
      })
      .map(({ product }) => product);

    // Add promotion data to products
    const now = new Date();
    const productsWithPromotions = await Promise.all(
      filteredProducts.map(async (product) => {
        // Get active promotions for this product
        const promotions = await prisma.promotion.findMany({
          where: {
            sellerId: product.sellerId,
            isActive: true,
            startDate: { lte: now },
            endDate: { gte: now },
            productIds: { hasSome: [product.id] },
            OR: [
              { maxUsage: null },
              { maxUsage: { gt: 0 } }
            ]
          },
          select: { id: true, type: true, discountType: true, discountValue: true, bundlePrice: true, usageCount: true, maxUsage: true }
        });

        // Calculate best discount
        let promotionPrice = product.basePrice;
        let promotionType = null;
        let promotionId = null;
        let discountAmount = 0;

        if (promotions.length > 0) {
          let bestDiscount = 0;
          for (const promo of promotions) {
            if (promo.maxUsage !== null && promo.usageCount >= promo.maxUsage) continue;
            
            let currentDiscount = 0;
            let currentPrice = product.basePrice;
            if (promo.type === 'BUNDLE') {
              currentDiscount = product.basePrice - (promo.bundlePrice || product.basePrice);
              currentPrice = promo.bundlePrice || product.basePrice;
            } else if (promo.discountValue) {
              // DISCOUNT/FLASH_SALE logic
              if (promo.discountType === 'PERCENTAGE') {
                currentDiscount = (product.basePrice * promo.discountValue) / 100;
                currentPrice = product.basePrice - currentDiscount;
              } else if (promo.discountType === 'FIXED') {
                currentDiscount = promo.discountValue;
                currentPrice = Math.max(0, product.basePrice - currentDiscount);
              }
            }

            if (currentDiscount > bestDiscount) {
              bestDiscount = currentDiscount;
              promotionPrice = currentPrice;
              promotionType = promo.type;
              promotionId = promo.id;
              discountAmount = currentDiscount;
            }
          }
        }

        return {
          id: product.id,
          slug: product.slug,
          title: product.title,
          basePrice: product.basePrice,
          salePrice: product.salePrice,
          promotionPrice: promotionType ? promotionPrice : undefined,
          promotionType,
          promotionId,
          discountAmount: discountAmount > 0 ? discountAmount : undefined,
          imageUrl: product.thumbnailUrl,
          category: product.category,
          seller: product.seller,
          averageRating: product.avgRating,
          _count: product._count,
          media: product.media,
          variants: product.variants,
        };
      })
    );

    return NextResponse.json({
      success: true,
      products: productsWithPromotions,
      pagination: {
        page,
        limit,
        total: filteredProducts.length,
        totalPages: Math.ceil(filteredProducts.length / limit),
      },
    });
  } catch (error) {
    console.error('Error fetching boutique products:', error);
    return NextResponse.json(
      { success: false, message: 'Failed to fetch products' },
      { status: 500 }
    );
  }
}

// POST - Create new product (seller only)
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user) {
      return NextResponse.json(
        { success: false, message: 'Authentication required' },
        { status: 401 }
      );
    }

    const body = await request.json();
    const {
      title,
      description,
      categoryId,
      subcategory,
      basePrice,
      salePrice,
      brand,
      material,
      careInstructions,
      tags,
      style,
      occasion,
      gender,
      condition,
      weight,
      dimensions,
      variants,
      isDraft,
      fulfillmentMethod, // NEW: ADMIN_STOCK or SELLER_DIRECT
      sellerShippingLocations, // For seller direct
      sellerShippingTime,
      sellerReturnPolicy,
      // NEW: Custom attributes (category-specific data)
      customAttributes,
    } = body;

    // Validation
    if (!title || !description || !categoryId || !basePrice) {
      return NextResponse.json(
        { success: false, message: 'Title, description, category, and price are required' },
        { status: 400 }
      );
    }

    // Validate title length
    if (title.trim().length < 5 || title.trim().length > 200) {
      return NextResponse.json(
        { success: false, message: 'Title must be between 5 and 200 characters' },
        { status: 400 }
      );
    }

    // Validate description length
    if (description.trim().length < 20 || description.trim().length > 5000) {
      return NextResponse.json(
        { success: false, message: 'Description must be between 20 and 5000 characters' },
        { status: 400 }
      );
    }

    // Validate prices
    const parsedBasePrice = parseFloat(basePrice);
    const parsedSalePrice = salePrice ? parseFloat(salePrice) : null;

    if (isNaN(parsedBasePrice) || parsedBasePrice <= 0) {
      return NextResponse.json(
        { success: false, message: 'Base price must be a positive number' },
        { status: 400 }
      );
    }

    if (parsedBasePrice > 1000000) {
      return NextResponse.json(
        { success: false, message: 'Base price cannot exceed 1,000,000' },
        { status: 400 }
      );
    }

    if (parsedSalePrice !== null) {
      if (isNaN(parsedSalePrice) || parsedSalePrice <= 0) {
        return NextResponse.json(
          { success: false, message: 'Sale price must be a positive number' },
          { status: 400 }
        );
      }

      if (parsedSalePrice >= parsedBasePrice) {
        return NextResponse.json(
          { success: false, message: 'Sale price must be lower than base price' },
          { status: 400 }
        );
      }
    }

    // Validate fulfillment method
    let validatedFulfillmentMethod: FulfillmentMethod = FULFILLMENT_METHOD.ADMIN_STOCK;
    let requiresSampleVerification = false;
    
    if (fulfillmentMethod === FULFILLMENT_METHOD.SELLER_DIRECT) {
      validatedFulfillmentMethod = FULFILLMENT_METHOD.SELLER_DIRECT;
      
      // Check if this seller needs sample verification for first few direct products
      const directProductCount = await prisma.boutiqueProduct.count({
        where: {
          sellerId: session.user.id,
          fulfillmentMethod: FULFILLMENT_METHOD.SELLER_DIRECT,
          status: { in: [PRODUCT_STATUS.LIVE, PRODUCT_STATUS.SOLD] },
        },
      });
      
      requiresSampleVerification = needsSampleVerification(directProductCount);
      
      // Validate required fields for seller direct
      if (!sellerShippingLocations || sellerShippingLocations.length === 0) {
        return NextResponse.json(
          { success: false, message: 'Please specify shipping locations for Seller Direct products' },
          { status: 400 }
        );
      }
    }

    // Verify category exists
    const category = await prisma.boutiqueCategory.findUnique({
      where: { id: categoryId },
    });

    if (!category) {
      return NextResponse.json(
        { success: false, message: 'Invalid category' },
        { status: 400 }
      );
    }

    // Generate unique slug from title
    const baseSlug = title
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-|-$/g, '');
    
    // Check for existing slugs and add suffix if needed
    let slug = baseSlug;
    let suffix = 0;
    while (true) {
      const existingProduct = await prisma.boutiqueProduct.findFirst({
        where: { slug },
      });
      if (!existingProduct) break;
      suffix++;
      slug = `${baseSlug}-${suffix}`;
    }

    // Calculate initial stock from variants
    const initialStock = variants && variants.length > 0
      ? variants.reduce((sum: number, v: { quantity?: number }) => sum + (v.quantity || 1), 0)
      : 0;

    // Create the product with variants in one transaction
    const product = await prisma.boutiqueProduct.create({
      data: {
        title,
        slug,
        description,
        categoryId,
        subcategory,
        basePrice: parseFloat(basePrice),
        salePrice: salePrice ? parseFloat(salePrice) : null,
        submittedPrice: parseFloat(basePrice),
        submittedCurrency: 'NGN',
        submittedSalePrice: salePrice ? parseFloat(salePrice) : null,
        brand,
        material,
        careInstructions,
        tags: tags || [],
        style,
        occasion,
        gender,
        condition: condition || 'NEW',
        weight: weight ? parseFloat(weight) : null,
        dimensions: dimensions || null,
        sellerId: session.user.id,
        status: isDraft ? PRODUCT_STATUS.DRAFT : PRODUCT_STATUS.DRAFT,
        // Initialize currentStock to sum of variant quantities
        currentStock: initialStock,
        // Track original quantity when first created
        originalQuantity: initialStock,
        // Fulfillment method fields
        fulfillmentMethod: validatedFulfillmentMethod,
        shipsFrom: validatedFulfillmentMethod === FULFILLMENT_METHOD.SELLER_DIRECT ? 'SELLER_LOCATION' : 'ADMIN_WAREHOUSE',
        sellerShippingLocations: validatedFulfillmentMethod === FULFILLMENT_METHOD.SELLER_DIRECT ? sellerShippingLocations : [],
        sellerShippingTime: validatedFulfillmentMethod === FULFILLMENT_METHOD.SELLER_DIRECT ? sellerShippingTime : null,
        sellerReturnPolicy: validatedFulfillmentMethod === FULFILLMENT_METHOD.SELLER_DIRECT ? sellerReturnPolicy : null,
        // Custom attributes (category-specific data)
        customAttributes: customAttributes || null,
        // Create variants at the same time
        variants: variants && variants.length > 0 ? {
          create: variants.map((v: { size?: string; color?: string; colorHex?: string; priceAdjustment?: number; quantity?: number; sku?: string }) => ({
            size: v.size,
            color: v.color,
            colorHex: v.colorHex,
            priceAdjustment: v.priceAdjustment || 0,
            quantity: v.quantity || 1,
            sku: v.sku,
          }))
        } : undefined,
      },
      include: { variants: true },
    });

    // Fetch the complete product with relations
    const completeProduct = await prisma.boutiqueProduct.findUnique({
      where: { id: product.id },
      include: {
        category: true,
        variants: true,
        media: true,
      },
    });

    return NextResponse.json({
      success: true,
      message: 'Product created successfully',
      product: completeProduct,
      fulfillmentInfo: {
        method: validatedFulfillmentMethod,
        requiresSampleVerification,
        workflow: validatedFulfillmentMethod === FULFILLMENT_METHOD.SELLER_DIRECT
          ? 'Content Review ΓåÆ Approved ΓåÆ Live'
          : 'Content Review ΓåÆ Ship to Admin ΓåÆ Verification ΓåÆ Live',
      },
    });
  } catch (error) {
    console.error('Error creating boutique product:', error);
    return NextResponse.json(
      { success: false, message: 'Failed to create product' },
      { status: 500 }
    );
  }
}

// GET /api/boutique/seller/products - Get seller's own boutique products

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import prisma from '@/lib/prisma';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user) {
      return NextResponse.json(
        { success: false, message: 'Authentication required' },
        { status: 401 }
      );
    }

    const { searchParams } = new URL(request.url);
    const status = searchParams.get('status');
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '20');

    const skip = (page - 1) * limit;

    const where: Record<string, unknown> = {
      sellerId: session.user.id,
    };

    if (status) {
      where.status = status;
    }

    const [products, total, statusCounts] = await Promise.all([
      prisma.boutiqueProduct.findMany({
        where,
        select: {
          id: true,
          slug: true,
          title: true,
          description: true,
          basePrice: true,
          brand: true,
          material: true,
          condition: true,
          status: true,
          createdAt: true,
          shipmentId: true,
          currentStock: true,
          fulfillmentMethod: true,
          category: {
            select: { id: true, name: true, slug: true },
          },
          media: {
            orderBy: { sortOrder: 'asc' },
          },
          variants: {
            select: { id: true, size: true, color: true, quantity: true },
          },
          _count: {
            select: { orders: true, favorites: true },
          },
        },
        orderBy: { createdAt: 'desc' },
        skip,
        take: limit,
      }),
      prisma.boutiqueProduct.count({ where }),
      prisma.boutiqueProduct.groupBy({
        by: ['status'],
        where: { sellerId: session.user.id },
        _count: true,
      }),
    ]);

    // Fetch shipment status for each product to determine display status
    const productsWithShipmentStatus = await Promise.all(
      products.map(async (product: any) => {
        let displayStatus = product.status;

        // If product is in return workflow, check the MOST RECENT shipment status
        if (product.shipmentId || product.status === 'IN_RETURN') {
          const shipment = await prisma.sellerToAdminShipment.findFirst({
            where: {
              sellerId: session.user.id,
              productIds: { has: product.id },
            },
            select: { status: true, createdAt: true },
            orderBy: { createdAt: 'desc' }, // Get the most recent shipment
          });

          if (shipment) {
            // Map shipment status to display status
            if (shipment.status === 'PENDING_ADMIN_REVIEW') {
              displayStatus = 'RETURN_REQUESTED';
            } else if (shipment.status === 'SHIPPED') {
              displayStatus = 'RETURN_SHIPPED';
            } else if (shipment.status === 'DELIVERED') {
              displayStatus = 'RETURNED_TO_SELLER';
            } else if (shipment.status === 'APPROVED_BY_ADMIN') {
              displayStatus = 'IN_RETURN';
            }
          }
        }

        return {
          ...product,
          displayStatus,
        };
      })
    );

    // Format status counts
    const counts: Record<string, number> = {};
    statusCounts.forEach(sc => {
      counts[sc.status] = sc._count;
    });

    return NextResponse.json({
      success: true,
      products: productsWithShipmentStatus,
      statusCounts: counts,
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
      },
    });
  } catch (error) {
    console.error('Error fetching seller boutique products:', error);
    return NextResponse.json(
      { success: false, message: 'Failed to fetch products' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'
import { prismaErrorResponse } from '@/lib/prismaError'

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)

    if (!session?.user?.email) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    // Get seller
    const seller = await prisma.user.findUnique({
      where: { email: session.user.email },
    })

    if (!seller) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      )
    }

    // Get query params
    const searchParams = request.nextUrl.searchParams
    const statusFilter = searchParams.get('status') // Can be 'LIVE', 'OUT_OF_STOCK', 'RETURNED', or null for all
    const stockStatus = searchParams.get('stockStatus') // 'in_stock' or 'out_of_stock'
    const dateFromStr = searchParams.get('dateFrom')
    const dateToStr = searchParams.get('dateTo')
    const searchQueryRaw = searchParams.get('search')
    
    // Sanitize search query - limit length to prevent DoS
    const MAX_SEARCH_LENGTH = 100
    const searchQuery = searchQueryRaw?.trim() && searchQueryRaw.trim().length > 0 && searchQueryRaw.trim().length <= MAX_SEARCH_LENGTH ? searchQueryRaw.trim() : null

    // Validate and parse dates with max bounds
    let dateFrom: Date | null = null
    let dateTo: Date | null = null
    const MAX_DATE_RANGE_DAYS = 365 * 2 // 2 years
    
    if (dateFromStr) {
      const parsed = new Date(dateFromStr)
      if (!isNaN(parsed.getTime())) {
        dateFrom = parsed
      }
    }
    
    if (dateToStr) {
      const parsed = new Date(dateToStr)
      if (!isNaN(parsed.getTime())) {
        dateTo = parsed
      }
    }

    // Validate date range - swap if needed and enforce max range
    if (dateFrom && dateTo && dateFrom > dateTo) {
      // Swap dates if they're in wrong order
      const temp = dateFrom
      dateFrom = dateTo
      dateTo = temp
    }
    
    // Enforce max range to prevent expensive queries
    if (dateFrom && dateTo) {
      const rangeMs = dateTo.getTime() - dateFrom.getTime()
      const rangeDays = rangeMs / (1000 * 60 * 60 * 24)
      if (rangeDays > MAX_DATE_RANGE_DAYS) {
        dateTo = new Date(dateFrom.getTime() + MAX_DATE_RANGE_DAYS * 24 * 60 * 60 * 1000)
      }
    }

    // Validate statusFilter - trim first, then validate
    const validStatuses = ['LIVE', 'OUT_OF_STOCK', 'RETURNED', 'IN_RETURN', 'SHIPPED_BACK']
    const trimmedStatus = statusFilter?.trim() || null
    const sanitizedStatusFilter = trimmedStatus && validStatuses.includes(trimmedStatus) ? trimmedStatus : null

    // Validate stockStatus
    const validStockStatuses = ['in_stock', 'out_of_stock']
    const sanitizedStockStatus = stockStatus && validStockStatuses.includes(stockStatus) ? stockStatus : null
    
    // Validate limit - max 100 results to prevent performance issues
    const RESULT_LIMIT = 100

    // Build where clause - show all warehouse products (LIVE, OUT_OF_STOCK, RETURNED, IN_RETURN, SHIPPED_BACK)
    const whereConditions: any[] = [
      { sellerId: seller.id },
      { warehouseReceivedAt: { not: null } }, // Must have been received in warehouse
      { 
        status: {
          in: sanitizedStatusFilter ? [sanitizedStatusFilter] : ['LIVE', 'OUT_OF_STOCK', 'RETURNED', 'IN_RETURN', 'SHIPPED_BACK']
        }
      }
    ]

    // Add stock status filter
    if (sanitizedStockStatus === 'in_stock') {
      whereConditions.push({ currentStock: { gt: 0 } })
    } else if (sanitizedStockStatus === 'out_of_stock') {
      whereConditions.push({
        OR: [
          { currentStock: 0 },
          { currentStock: null }
        ]
      })
    }

    // Add date range filters with validated dates
    if (dateFrom && dateTo) {
      whereConditions.push({ 
        warehouseReceivedAt: {
          gte: dateFrom,
          lte: dateTo
        }
      })
    } else if (dateFrom) {
      whereConditions.push({ warehouseReceivedAt: { gte: dateFrom } })
    } else if (dateTo) {
      whereConditions.push({ warehouseReceivedAt: { lte: dateTo } })
    }

    // Build the final where clause with AND logic
    const where: any = {
      AND: whereConditions
    }

    // Add search query as OR condition (optional)
    if (searchQuery) {
      where.AND.push({
        OR: [
          { title: { contains: searchQuery, mode: 'insensitive' } },
          // Don't search by ID with contains - IDs are UUIDs and contains is inefficient
        ]
      })
    }

    console.log('[DEBUG WAREHOUSE-INVENTORY] Query where clause:', JSON.stringify(where, null, 2))

    // Fetch products - all warehouse products with their current status
    // Limit to 100 products per request to prevent performance issues
    const products = await prisma.boutiqueProduct.findMany({
      where,
      select: {
        id: true,
        title: true,
        slug: true,
        basePrice: true,
        salePrice: true,
        currency: true,
        currentStock: true,
        originalStock: true,
        thumbnailUrl: true,
        status: true,
        fullReturnEnabled: true,
        warehouseReceivedAt: true,
        warehouseExpiresAt: true,
        outOfStockAt: true,
        returnedToSellerAt: true,
        month5NotificationSent: true,
        condition: true,
        shipmentId: true,
      },
      orderBy: { warehouseReceivedAt: 'desc' },
      take: RESULT_LIMIT,
    })

    console.log('[DEBUG WAREHOUSE-INVENTORY] Database query returned:', products.length, 'products')
    if (products.length > 0) {
      console.log('[DEBUG WAREHOUSE-INVENTORY] First product:', {
        id: products[0].id,
        title: products[0].title,
        status: products[0].status,
        warehouseReceivedAt: products[0].warehouseReceivedAt,
        sellerId: 'HIDDEN'
      })
    }

    // Fetch all shipments in one query to avoid N+1
    const shipmentIds = products.map(p => p.shipmentId).filter(Boolean) as string[]
    const shipments = shipmentIds.length > 0 
      ? await prisma.sellerToAdminShipment.findMany({
          where: { id: { in: shipmentIds } },
          select: { id: true, warehouseAddress: true }
        })
      : []
    const shipmentMap = new Map(shipments.map(s => [s.id, s.warehouseAddress]))

    // Fetch all sales history at once to avoid N+1 (limit to last 50 sales per product)
    const productIds = products.map(p => p.id)
    const allSalesHistory = productIds.length > 0
      ? await prisma.boutiqueOrderItem.findMany({
          where: {
            productId: { in: productIds },
            order: {
              status: { in: ['PAID', 'PROCESSING', 'SHIPPED', 'DELIVERED', 'COMPLETED'] }
            }
          },
          select: {
            id: true,
            productId: true,
            quantity: true,
            price: true,
            variantSnapshot: true,
            createdAt: true,
            variant: {
              select: { size: true, color: true }
            }
          },
          orderBy: { createdAt: 'desc' },
          take: 500, // Limit total sales history to prevent slow queries
        })
      : []

    // Fetch all return requests for these products at once
    const allReturns = productIds.length > 0
      ? await prisma.boutiqueReturn.findMany({
          where: {
            orderItem: {
              productId: { in: productIds }
            },
            status: { in: ['PENDING', 'APPROVED', 'ITEM_SHIPPED', 'ITEM_RECEIVED'] }
          },
          select: {
            id: true,
            status: true,
            orderItem: {
              select: { productId: true }
            }
          }
        })
      : []
    
    // Group sales by product ID for quick lookup
    const salesByProductId = new Map<string, typeof allSalesHistory>()
    for (const sale of allSalesHistory) {
      if (!salesByProductId.has(sale.productId)) {
        salesByProductId.set(sale.productId, [])
      }
      salesByProductId.get(sale.productId)!.push(sale)
    }

    // Group returns by product ID for quick lookup
    const returnsByProductId = new Map<string, typeof allReturns>()
    for (const ret of allReturns) {
      const productId = ret.orderItem?.productId
      if (productId) {
        if (!returnsByProductId.has(productId)) {
          returnsByProductId.set(productId, [])
        }
        returnsByProductId.get(productId)!.push(ret)
      }
    }

    // Enrich products with shipment info
    const productsWithShipment = products.map(product => ({
      ...product,
      shipmentWarehouseAddress: product.shipmentId ? (shipmentMap.get(product.shipmentId) || null) : null
    }))

    // Enrich with calculated data (no async sales fetch needed - already have data)
    console.log('[DEBUG WAREHOUSE-INVENTORY] Starting enrichment of', productsWithShipment.length, 'products')
    const enrichedProducts = productsWithShipment.map((product) => {
        const STORAGE_CYCLE_DAYS = 181
        
        // Validate warehouse received date is valid timestamp
        let warehouseReceivedTime = 0
        if (product.warehouseReceivedAt) {
          const parsed = new Date(product.warehouseReceivedAt)
          warehouseReceivedTime = !isNaN(parsed.getTime()) ? parsed.getTime() : 0
        }
        
        const daysInWarehouse = warehouseReceivedTime > 0
          ? Math.max(
              0,
              Math.floor(
                (Date.now() - warehouseReceivedTime) /
                  (1000 * 60 * 60 * 24)
              )
            )
          : 0

        const storageCycle = Math.max(1, Math.floor(daysInWarehouse / (STORAGE_CYCLE_DAYS || 1)) + 1)
        const daysInCurrentCycle = STORAGE_CYCLE_DAYS > 0 ? daysInWarehouse % STORAGE_CYCLE_DAYS : 0

        // Validate warehouse expiry date is valid timestamp
        let daysUntilExpiry: number | null = null
        if (product.warehouseExpiresAt) {
          const parsed = new Date(product.warehouseExpiresAt)
          if (!isNaN(parsed.getTime())) {
            daysUntilExpiry = Math.ceil(
              (parsed.getTime() - Date.now()) /
                (1000 * 60 * 60 * 24)
            )
          }
        }

        const isLowStock = (product.currentStock || 0) <= 5
        // Only calculate isInMonth5 if product hasn't expired and has valid expiry date
        const isInMonth5 = product.warehouseExpiresAt && daysUntilExpiry !== null && daysUntilExpiry >= 0 && daysInCurrentCycle >= 119 && daysInCurrentCycle < 180

        // Get return requests for this product (but only if product is not OUT_OF_STOCK)
        // Out of stock products cannot have returns
        let returnStatus: string | null = null
        if (product.status !== 'OUT_OF_STOCK') {
          const productReturns = returnsByProductId.get(product.id) || []
          const pendingReturns = productReturns.filter(r => r.status === 'PENDING')
          const approvedReturns = productReturns.filter(r => r.status === 'APPROVED')
          const shippedReturns = productReturns.filter(r => r.status === 'ITEM_SHIPPED')
          const receivedReturns = productReturns.filter(r => r.status === 'ITEM_RECEIVED')
          
          if (pendingReturns.length > 0) {
            returnStatus = 'AWAITING_ADMIN_APPROVAL'
          } else if (approvedReturns.length > 0) {
            returnStatus = 'RETURN_APPROVED'
          } else if (shippedReturns.length > 0) {
            returnStatus = 'RETURN_IN_TRANSIT'
          } else if (receivedReturns.length > 0) {
            returnStatus = 'RETURN_RECEIVED'
          }
        }

        // Get sales history for this product from batch-fetched data
        const productSalesHistory = salesByProductId.get(product.id) || []
        const totalSold = productSalesHistory.reduce((sum, item) => sum + (item.quantity || 0), 0)

        // Debug log for each enriched product
        if (product.title.includes('ADMIN TEST INVENTORY')) {
          console.log('[DEBUG WAREHOUSE-INVENTORY] Enriched product:', {
            title: product.title,
            daysInWarehouse,
            daysInCurrentCycle,
            storageCycle,
            isInMonth5,
            warehouseReceivedAt: product.warehouseReceivedAt,
            warehouseExpiresAt: product.warehouseExpiresAt
          })
        }

        return {
          ...product,
          daysInWarehouse,
          daysInCurrentCycle,
          storageCycle,
          daysUntilExpiry,
          isLowStock,
          isInMonth5,
          displayPrice: product.salePrice ?? product.basePrice ?? null,
          totalSold,
          returnStatus,
          shipmentWarehouseAddress: product.shipmentWarehouseAddress,
          salesHistory: productSalesHistory.map(item => {
            let variantInfo = 'Standard'
            if (item.variant && (item.variant.color || item.variant.size)) {
              variantInfo = `${item.variant.color || ''} ${item.variant.size || ''}`.trim()
            } else if (item.variantSnapshot && typeof item.variantSnapshot === 'object') {
              const snapshot = item.variantSnapshot as Record<string, any>
              if (snapshot.color || snapshot.size) {
                variantInfo = `${snapshot.color || ''} ${snapshot.size || ''}`.trim()
              }
            }
            return {
              quantity: item.quantity || 0,
              variantInfo,
              soldAt: item.createdAt,
              price: item.price || 0
            }
          })
        }
      })
    console.log('[DEBUG WAREHOUSE-INVENTORY] Final enrichedProducts count:', enrichedProducts.length)
    const adminTestProducts = enrichedProducts.filter(p => p.title.includes('ADMIN TEST INVENTORY'))
    if (adminTestProducts.length > 0) {
      console.log('[DEBUG WAREHOUSE-INVENTORY] Found ADMIN TEST INVENTORY products:', adminTestProducts.map(p => ({ title: p.title, id: p.id })))
    } else {
      console.log('[DEBUG WAREHOUSE-INVENTORY] No ADMIN TEST INVENTORY products in final results')
    }
    return NextResponse.json({
      products: enrichedProducts,
    })
  } catch (error) {
    console.error('Warehouse inventory fetch error:', error)

    const prismaResp = prismaErrorResponse(
      error,
      'Database temporarily unavailable'
    )
    if (prismaResp) return prismaResp

    // Log unexpected errors for debugging
    if (error instanceof Error) {
      console.error('Error details:', error.message, error.stack)
    }

    return NextResponse.json(
      { error: 'Failed to fetch warehouse inventory' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'
import { getCachedData, invalidateCache, CACHE_TTL } from '@/lib/cache'

export async function GET() {
  try {
    const session = await getServerSession(authOptions)
    
    if (!session?.user?.id) {
      return NextResponse.json(
        { message: 'Authentication required' },
        { status: 401 }
      )
    }

    // Cache key for this user's cart
    const cacheKey = `cart:${session.user.id}`

    const fetchCart = async () => {
      // Optimized query: only fetch needed fields to reduce response time
      const cartItems = await prisma.cartItem.findMany({
        where: {
          userId: session.user.id
        },
        select: {
          id: true,
          userId: true,
          designId: true,
          purchaseType: true,
          quantity: true,
          priceTestVariant: true,
          priceTestPrice: true,
          createdAt: true,
          design: {
            select: {
              id: true,
              title: true,
              price: true,
              ownershipPrice: true,
              designerId: true,
              imageUrl: true,
              thumbnailUrl: true,
              designer: {
                select: {
                  id: true,
                  name: true,
                  image: true
                }
              }
            }
          }
        },
        orderBy: {
          createdAt: 'desc'
        }
      })

      return cartItems
    }

    const cartItems = await getCachedData(cacheKey, CACHE_TTL.CART, fetchCart)
    type CartItemWithDesign = {
      id: string
      designId: string
      purchaseType?: string | null
      quantity: number
      priceTestVariant?: string | null
      priceTestPrice?: number | null
      design: { 
        id: string
        ownershipPrice?: number | null
        price: number
        designerId: string
      }
    }

    const typedCartItems = cartItems as unknown as CartItemWithDesign[]
    
    // Get all design IDs for promotion checking
    const allDesignIds = cartItems.map(item => item.designId)
    
    // OPTIMIZATION: Fetch all promotions once per unique seller (eliminates N+1 queries)
    const uniqueSellerIds = [...new Set(typedCartItems.map(item => item.design.designerId))]
    const now = new Date()
    
    const allPromotions = uniqueSellerIds.length > 0 ? await prisma.promotion.findMany({
      where: {
        sellerId: { in: uniqueSellerIds },
        isActive: true,
        startDate: { lte: now },
        endDate: { gte: now },
      },
    }) : []
    
    // Group promotions by seller ID for O(1) lookup
    const promotionsBySeller = new Map<string, typeof allPromotions>()
    allPromotions.forEach(promo => {
      if (!promotionsBySeller.has(promo.sellerId)) {
        promotionsBySeller.set(promo.sellerId, [])
      }
      promotionsBySeller.get(promo.sellerId)!.push(promo)
    })
    
    // Apply promotions to cart items - no async needed anymore
    let total = 0
    const itemsWithPromotions = typedCartItems.map((item) => {
      let price: number
      let promotionId: string | null = null
      let promotionType: string | null = null
      let promotionPrice: number | undefined = undefined
      let discountAmount = 0
      
      if (item.purchaseType === 'OWNERSHIP' && item.design.ownershipPrice) {
        price = item.design.ownershipPrice
      } else if (item.priceTestVariant && item.priceTestPrice) {
        // Use the A/B test price that was shown to the user
        price = item.priceTestPrice
      } else {
        price = item.design.price
        
        // Check for promotions (only for regular digital items) using pre-fetched data
        const sellerPromotions = promotionsBySeller.get(item.design.designerId) || []
        let bestMatch: any = null
        let bestDiscount = 0
        
        for (const promo of sellerPromotions) {
          // Skip if promotion usage limit reached
          if (promo.maxUsage !== null && promo.usageCount >= promo.maxUsage) {
            continue
          }
          
          // Check if design matches this promotion
          let designMatches = false
          if (promo.type === 'BUNDLE') {
            designMatches = (promo.designIds as string[]).includes(item.design.id)
          } else {
            designMatches = (promo.designIds as string[]).length === 0 || (promo.designIds as string[]).includes(item.design.id)
          }
          
          if (!designMatches) continue
          
          let discount = 0
          let discountedPriceCalc = price
          
          if (promo.type === 'BUNDLE') {
            // Bundle: All bundle designs must be in cart
            const allBundleDesignInCart = (promo.designIds as string[]).every((id) => allDesignIds.includes(id))
            if (!allBundleDesignInCart) continue
            
            const cartBundleDesigns = (promo.designIds as string[]).filter((id) => allDesignIds.includes(id))
            const isFirstBundleDesign = cartBundleDesigns[0] === item.design.id
            
            if (isFirstBundleDesign) {
              discountedPriceCalc = (promo.bundlePrice || price) as number
              discount = price - discountedPriceCalc
            }
          } else {
            // DISCOUNT or FLASH_SALE: Calculate discount from discountValue and discountType
            if (promo.discountType === 'PERCENTAGE' && promo.discountValue) {
              discount = price * (promo.discountValue / 100)
            } else if (promo.discountType === 'FIXED' && promo.discountValue) {
              discount = promo.discountValue
            }
            discountedPriceCalc = Math.max(price - discount, 0)
          }
          
          if (discount > bestDiscount) {
            bestDiscount = discount
            bestMatch = {
              promotionId: promo.id,
              type: promo.type,
              discountAmount: discount,
              discountedPrice: discountedPriceCalc,
            }
          }
        }
        
        if (bestMatch) {
          promotionId = bestMatch.promotionId
          promotionType = bestMatch.type
          promotionPrice = bestMatch.discountedPrice as number
          discountAmount = bestMatch.discountAmount
          price = promotionPrice
        }
      }
      
      total += price * item.quantity
      
      return {
        ...item,
        promotionId,
        promotionType,
        promotionPrice,
        discountAmount
      }
    })

    return NextResponse.json({
      items: itemsWithPromotions,
      total,
      count: cartItems.length
    })

  } catch (error) {
    console.error('Get cart error:', error)
    return NextResponse.json(
      { message: 'Internal server error' },
      { status: 500 }
    )
  }
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    
    if (!session?.user?.id) {
      return NextResponse.json(
        { message: 'Authentication required' },
        { status: 401 }
      )
    }

    const { 
      designId, 
      quantity = 1, 
      purchaseType = 'REGULAR',
      // POD-specific fields
      podProductId,
      podProductName,
      podProvider,
      price: podPrice,
      // A/B Price Test fields
      variant,
      testPrice,
    } = await request.json()

    if (!designId) {
      return NextResponse.json(
        { message: 'Design ID is required' },
        { status: 400 }
      )
    }

    if (!['REGULAR', 'OWNERSHIP', 'POD'].includes(purchaseType)) {
      return NextResponse.json(
        { message: 'Invalid purchase type' },
        { status: 400 }
      )
    }

    // POD items require additional fields
    if (purchaseType === 'POD' && (!podProductId || !podProductName)) {
      return NextResponse.json(
        { message: 'POD product details are required' },
        { status: 400 }
      )
    }

    // Γ£à Parallelize design existence and cart item checks for 30-50% faster response
    const [design, existingItem] = await Promise.all([
      prisma.design.findUnique({
        where: { 
          id: designId
        },
        select: {
          id: true,
          designerId: true,
          isActive: true,
          isOwned: true,
          buyingTypes: true,
          price: true,
          ownershipPrice: true
        }
      }),
      prisma.cartItem.findFirst({
        where: {
          userId: session.user.id,
          designId,
          purchaseType,
          ...(purchaseType === 'POD' ? { podProductId } : {})
        }
      })
    ])

    if (!design) {
      return NextResponse.json(
        { message: 'Design not found or not available' },
        { status: 404 }
      )
    }

    // Check if design is inactive (but allow pending approval for testing)
    if (!design.isActive) {
      return NextResponse.json(
        { message: 'Design is not available' },
        { status: 404 }
      )
    }

    // Check if user is trying to buy their own design
    if (design.designerId === session.user.id) {
      return NextResponse.json(
        { message: 'Cannot add your own design to cart' },
        { status: 400 }
      )
    }

    // Check ownership availability
    if (purchaseType === 'OWNERSHIP' && design.isOwned) {
      return NextResponse.json(
        { message: 'This design is already exclusively owned' },
        { status: 400 }
      )
    }

    // Check if design supports the requested purchase type
    if (purchaseType === 'OWNERSHIP' && design.buyingTypes === 'REGULAR') {
      return NextResponse.json(
        { message: 'This design does not support ownership purchase' },
        { status: 400 }
      )
    }

    if (purchaseType === 'REGULAR' && design.buyingTypes === 'OWNERSHIP') {
      return NextResponse.json(
        { message: 'This design only supports ownership purchase' },
        { status: 400 }
      )
    }

    // Check if ownership price is set for ownership purchases
    if (purchaseType === 'OWNERSHIP' && !design.ownershipPrice) {
      return NextResponse.json(
        { message: 'Ownership price not set for this design' },
        { status: 400 }
      )
    }

    if (existingItem) {
      // For ownership, quantity should always be 1
      if (purchaseType === 'OWNERSHIP') {
        return NextResponse.json(
          { message: 'Ownership item already in cart' },
          { status: 400 }
        )
      }
      
      // Γ£à Just update without re-fetching relations (20-30% faster)
      await prisma.cartItem.update({
        where: { id: existingItem.id },
        data: { quantity: existingItem.quantity + quantity }
      })

      await invalidateCache(`cart:${session.user.id}`)
      return NextResponse.json({
        message: 'Cart updated successfully',
        itemId: existingItem.id,
        newQuantity: existingItem.quantity + quantity
      })
    }

    // Γ£à Create new cart item without re-fetching relations (20-30% faster)
    const cartItem = await prisma.cartItem.create({
      data: {
        userId: session.user.id,
        designId,
        quantity: purchaseType === 'OWNERSHIP' ? 1 : quantity,
        purchaseType,
        // POD-specific fields
        ...(purchaseType === 'POD' ? {
          podProductId,
          podProductName,
          podProvider,
          podPrice
        } : {}),
        // A/B Price Test fields (only for non-POD items)
        ...(variant && purchaseType !== 'POD' ? {
          priceTestVariant: variant,
          priceTestPrice: testPrice
        } : {})
      }
    })

    await invalidateCache(`cart:${session.user.id}`)
    return NextResponse.json({
      message: 'Item added to cart successfully',
      itemId: cartItem.id
    })

  } catch (error) {
    console.error('Add to cart error:', error)
    return NextResponse.json(
      { message: 'Internal server error' },
      { status: 500 }
    )
  }
}

export async function DELETE(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    
    if (!session?.user?.id) {
      return NextResponse.json(
        { message: 'Authentication required' },
        { status: 401 }
      )
    }

    const { searchParams } = new URL(request.url)
    const itemId = searchParams.get('itemId')

    // If no itemId provided, clear entire cart
    if (!itemId) {
      await prisma.cartItem.deleteMany({
        where: {
          userId: session.user.id
        }
      })
      
      await invalidateCache(`cart:${session.user.id}`)
      return NextResponse.json({
        message: 'Cart cleared successfully'
      })
    }

    // Γ£à Delete with ownership check in single query (40% faster)
    const deleted = await prisma.cartItem.deleteMany({
      where: {
        id: itemId,
        userId: session.user.id
      }
    })

    if (deleted.count === 0) {
      return NextResponse.json(
        { message: 'Cart item not found' },
        { status: 404 }
      )
    }

    await invalidateCache(`cart:${session.user.id}`)
    return NextResponse.json({
      message: 'Item removed from cart successfully'
    })

  } catch (error) {
    console.error('Remove from cart error:', error)
    return NextResponse.json(
      { message: 'Internal server error' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { getStripe, isStripeConfigured } from '@/lib/stripe'
import type Stripe from 'stripe'
import { paystack, isPaystackConfigured, convertUSDToNGN } from '@/lib/paystack'
import { initializePayment as initFlutterwavePayment, isFlutterwaveConfigured, getSupportedCountries } from '@/lib/flutterwave'
import prisma from '@/lib/prisma'
import { getCommissionRate } from '@/lib/commission-tiers'
import { fetchExchangeRates, convertFromUSD } from '@/lib/currency'
import { getPromotionForDesign, _incrementPromotionUsage } from '@/lib/promotion-engine'
import { getIdempotencyKey, checkIdempotencyKey, storeIdempotentResponse } from '@/lib/idempotency'

/**
 * Get the effective price for a design, considering A/B price tests
 * 
 * @param design - The design object with price test fields
 * @param variant - The variant the user was assigned ('A' = original, 'B' = test price)
 * @returns The price to charge and variant info
 */
function getEffectivePrice(
  design: {
    price: number
    priceTestActive: boolean
    priceTestVariant: number | null
    priceTestEndsAt: Date | null
  },
  variant?: 'A' | 'B'
): { price: number; variant: 'A' | 'B'; isTestPrice: boolean } {
  // Check if test is still active
  const isTestActive = design.priceTestActive && 
    design.priceTestVariant !== null && 
    design.priceTestEndsAt && 
    new Date(design.priceTestEndsAt) > new Date()
  
  if (!isTestActive || !variant || variant === 'A') {
    return { price: design.price, variant: 'A', isTestPrice: false }
  }
  
  // User saw variant B (test price)
  return { 
    price: design.priceTestVariant!, 
    variant: 'B', 
    isTestPrice: true 
  }
}

async function convertCurrencyLive(amountUSD: number, targetCurrency: string): Promise<number> {
  if (targetCurrency === 'USD') return amountUSD
  
  // For NGN, use the paystack live rate (more reliable for payments)
  if (targetCurrency === 'NGN') {
    return await convertUSDToNGN(amountUSD)
  }
  
  // For other currencies, use the currency lib which fetches from API
  const rates = await fetchExchangeRates()
  return Math.round(convertFromUSD(amountUSD, targetCurrency, rates) * 100) / 100
}

