    // Only seller can view their own preview status, admins can view all
    if (document.sellerId !== session.user.id && session.user.role !== 'ADMIN') {
      return NextResponse.json(
        { message: 'Unauthorized - not your document' },
        { status: 403 }
      )
    }

    return NextResponse.json(
      {
        document: {
          id: document.id,
          hasPreview: !!document.previewFileUrl,
          previewFileUrl: document.previewFileUrl,
          previewFileType: document.previewFileType,
          previewFileName: document.previewFileName,
          previewDescription: document.previewDescription,
          status: document.status,
          designId: document.designId
        }
      },
      { status: 200 }
    )
  } catch (error) {
    console.error('Preview status error:', error)

    return NextResponse.json(
      { message: 'Failed to get preview status' },
      { status: 500 }
    )
  }
}

/**
 * GET /api/payments/audit-trail
 * Fetch payment transaction history with filtering
 * 
 * Query Parameters:
 * - orderId: Filter by order (buyer, seller, or admin)
 * - processor: Filter by processor (PAYSTACK, STRIPE, FLUTTERWAVE)
 * - status: Filter by payment status
 * - payoutStatus: Filter by payout status
 * - startDate: Filter by date range start
 * - endDate: Filter by date range end
 * - limit: Results per page (default 50)
 * - page: Page number (default 1)
 */

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { searchParams } = new URL(request.url)
    const orderId = searchParams.get('orderId')
    const processor = searchParams.get('processor')
    const payoutStatus = searchParams.get('payoutStatus')
    const startDate = searchParams.get('startDate')
    const endDate = searchParams.get('endDate')
    const limit = Math.min(parseInt(searchParams.get('limit') || '50'), 100)
    const page = Math.max(1, parseInt(searchParams.get('page') || '1'))
    const skip = (page - 1) * limit

    // Build where filter based on user role
    const isAdmin = (session.user as any).role === 'ADMIN'
    const where: any = {}

    // Restrict to user's own data if not admin
    if (!isAdmin) {
      where.OR = [
        { buyerId: session.user.id },
        { sellerId: session.user.id },
      ]
    }

    // Apply optional filters
    if (orderId) where.orderId = orderId
    if (processor) where.processor = processor
    if (payoutStatus) where.payoutStatus = payoutStatus

    // Date range filtering
    if (startDate || endDate) {
      where.initiatedAt = {}
      if (startDate) where.initiatedAt.gte = new Date(startDate)
      if (endDate) {
        const end = new Date(endDate)
        end.setHours(23, 59, 59, 999)
        where.initiatedAt.lte = end
      }
    }

    // Fetch transactions with related data
    const [transactions, total] = await Promise.all([
      prisma.paymentTransaction.findMany({
        where,
        include: {
          order: {
            select: {
              orderNumber: true,
              status: true,
              total: true,
            },
          },
          buyer: {
            select: {
              id: true,
              name: true,
              email: true,
            },
          },
          seller: {
            select: {
              id: true,
              name: true,
              email: true,
            },
          },
        },
        orderBy: { initiatedAt: 'desc' },
        skip,
        take: limit,
      }),
      prisma.paymentTransaction.count({ where }),
    ])

    // Calculate summary statistics
    const summary = {
      totalTransactions: total,
      totalAmount: 0,
      totalPlatformFee: 0,
      totalProcessorFee: 0,
      totalSellerPayout: 0,
      successRate: 0,
      avgPayoutTime: 0,
    }

    if (transactions.length > 0) {
      summary.totalAmount = transactions.reduce((sum, t) => sum + t.buyerAmount, 0)
      summary.totalPlatformFee = transactions.reduce((sum, t) => sum + t.platformFee, 0)
      summary.totalProcessorFee = transactions.reduce((sum, t) => sum + t.processorFee, 0)
      summary.totalSellerPayout = transactions.reduce((sum, t) => sum + t.sellerPayout, 0)

      const completed = transactions.filter(t => t.completedAt).length
      summary.successRate = (completed / transactions.length) * 100

      const payoutTimes = transactions
        .filter(t => t.payoutScheduledAt && t.payoutCompletedAt)
        .map(t => (t.payoutCompletedAt!.getTime() - t.payoutScheduledAt!.getTime()) / (1000 * 60 * 60))
      
      if (payoutTimes.length > 0) {
        summary.avgPayoutTime = Math.round(
          payoutTimes.reduce((a, b) => a + b, 0) / payoutTimes.length
        )
      }
    }

    return NextResponse.json({
      success: true,
      data: {
        transactions: transactions.map(t => ({
          id: t.id,
          orderNumber: t.order.orderNumber,
          buyer: t.buyer.name || t.buyer.email,
          seller: t.seller.name || t.seller.email,
          amount: {
            buyer: t.buyerAmount,
            platform: t.platformFee,
            processor: t.processorFee,
            seller: t.sellerPayout,
          },
          processor: t.processor,
          processorRef: t.processorRefId,
          status: {
            payment: t.processorStatus,
            payout: t.payoutStatus,
            reconciliation: t.reconciliationStatus,
          },
          timeline: {
            initiated: t.initiatedAt,
            authorized: t.authorizedAt,
            completed: t.completedAt,
            settled: t.settledAt,
            payoutScheduled: t.payoutScheduledAt,
            payoutInitiated: t.payoutInitiatedAt,
            payoutCompleted: t.payoutCompletedAt,
          },
          metadata: t.metadata,
        })),
        pagination: {
          page,
          limit,
          total,
          pages: Math.ceil(total / limit),
        },
        summary,
      },
    })
  } catch (error) {
    console.error('Error fetching payment audit trail:', error)
    return NextResponse.json(
      { error: 'Failed to fetch payment history' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import prisma from "@/lib/prisma";

/**
 * POST /api/search/advanced - Advanced search with filters
 */
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    const body = await request.json();

    const {
      query,
      category,
      style,
      colorPalette,
      garmentType,
      season,
      occasion,
      targetAudience,
      priceMin,
      priceMax,
      sortBy = 'relevance',
      page = 1,
      limit = 12,
    } = body;

    const skip = (page - 1) * limit;

    // Build where clause
    const where: Record<string, unknown> = {
      isActive: true,
      approvalStatus: 'APPROVED',
    };

    // Text search
    if (query && query.trim().length >= 2) {
      const searchTerm = query.trim();
      where.OR = [
        { title: { contains: searchTerm, mode: 'insensitive' } },
        { description: { contains: searchTerm, mode: 'insensitive' } },
        { category: { contains: searchTerm, mode: 'insensitive' } },
        { designer: { name: { contains: searchTerm, mode: 'insensitive' } } },
      ];
    }

    // Category filter
    if (category && category !== 'all') {
      where.category = category;
    }

    // Style filter
    if (style && style.length > 0) {
      where.style = { in: style };
    }

    // Color palette filter (array contains)
    if (colorPalette && colorPalette.length > 0) {
      where.colorPalette = { hasSome: colorPalette };
    }

    // Garment type filter
    if (garmentType && garmentType !== 'all') {
      where.garmentType = garmentType;
    }

    // Season filter
    if (season && season !== 'all') {
      where.season = season;
    }

    // Occasion filter
    if (occasion && occasion !== 'all') {
      where.occasion = occasion;
    }

    // Target audience filter
    if (targetAudience && targetAudience !== 'all') {
      where.targetAudience = targetAudience;
    }

    // Price range filter
    if (priceMin !== undefined || priceMax !== undefined) {
      where.price = {};
      if (priceMin !== undefined) {
        (where.price as Record<string, number>).gte = priceMin;
      }
      if (priceMax !== undefined) {
        (where.price as Record<string, number>).lte = priceMax;
      }
    }

    // Sort order
    let orderBy: Record<string, string>[] = [];
    switch (sortBy) {
      case 'price_low':
        orderBy = [{ price: 'asc' }];
        break;
      case 'price_high':
        orderBy = [{ price: 'desc' }];
        break;
      case 'newest':
        orderBy = [{ createdAt: 'desc' }];
        break;
      case 'popular':
        orderBy = [{ totalSales: 'desc' }];
        break;
      case 'trending':
        orderBy = [{ trendingScore: 'desc' }, { weeklyViews: 'desc' }];
        break;
      default: // relevance
        orderBy = [{ totalSales: 'desc' }, { viewCount: 'desc' }];
    }

    const [designs, total] = await Promise.all([
      prisma.design.findMany({
        where: where as any,
        skip,
        take: limit,
        orderBy: orderBy as any,
        include: {
          designer: {
            select: {
              id: true,
              name: true,
              displayName: true,
              image: true,
              isVerified: true,
              verificationBadge: true,
            },
          },
          _count: {
            select: {
              reviews: true,
              favorites: true,
            },
          },
        },
      }),
      prisma.design.count({ where: where as any }),
    ]);

    // Record search history if user is logged in
    if (session?.user?.id && query) {
      await prisma.searchHistory.create({
        data: {
          query,
          filters: {
            category,
            style,
            colorPalette,
            garmentType,
            season,
            occasion,
            targetAudience,
            priceMin,
            priceMax,
          },
          results: total,
          userId: session.user.id,
        },
      });
    }

    return NextResponse.json({
      designs,
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
      filters: {
        query,
        category,
        style,
        colorPalette,
        garmentType,
        season,
        occasion,
        targetAudience,
        priceMin,
        priceMax,
        sortBy,
      },
    });
  } catch (error) {
    console.error("Advanced search error:", error);
    return NextResponse.json(
      { error: "Search failed" },
      { status: 500 }
    );
  }
}

/**
 * GET /api/search/advanced - Get filter options
 */
export async function GET() {
  try {
    // Get unique values for filter dropdowns
    const [categories, styles, garmentTypes, seasons, occasions, audiences] = await Promise.all([
      prisma.design.findMany({
        where: { isActive: true, approvalStatus: 'APPROVED' },
        select: { category: true },
        distinct: ['category'],
      }),
      prisma.design.findMany({
        where: { isActive: true, approvalStatus: 'APPROVED', style: { not: null } },
        select: { style: true },
        distinct: ['style'],
      }),
      prisma.design.findMany({
        where: { isActive: true, approvalStatus: 'APPROVED', garmentType: { not: null } },
        select: { garmentType: true },
        distinct: ['garmentType'],
      }),
      prisma.design.findMany({
        where: { isActive: true, approvalStatus: 'APPROVED', season: { not: null } },
        select: { season: true },
        distinct: ['season'],
      }),
      prisma.design.findMany({
        where: { isActive: true, approvalStatus: 'APPROVED', occasion: { not: null } },
        select: { occasion: true },
        distinct: ['occasion'],
      }),
      prisma.design.findMany({
        where: { isActive: true, approvalStatus: 'APPROVED', targetAudience: { not: null } },
        select: { targetAudience: true },
        distinct: ['targetAudience'],
      }),
    ]);

    const colorOptions = [
      'Red', 'Blue', 'Green', 'Yellow', 'Orange', 'Purple', 'Pink',
      'Black', 'White', 'Gray', 'Brown', 'Beige', 'Navy', 'Teal',
      'Gold', 'Silver', 'Coral', 'Mint', 'Lavender', 'Burgundy'
    ];

    return NextResponse.json({
      filterOptions: {
        categories: categories.map(c => c.category),
        styles: styles.map(s => s.style).filter(Boolean),
        garmentTypes: garmentTypes.map(g => g.garmentType).filter(Boolean),
        seasons: seasons.map(s => s.season).filter(Boolean),
        occasions: occasions.map(o => o.occasion).filter(Boolean),
        targetAudiences: audiences.map(a => a.targetAudience).filter(Boolean),
        colors: colorOptions,
        sortOptions: [
          { value: 'relevance', label: 'Relevance' },
          { value: 'trending', label: 'Trending' },
          { value: 'newest', label: 'Newest First' },
          { value: 'popular', label: 'Most Popular' },
          { value: 'price_low', label: 'Price: Low to High' },
          { value: 'price_high', label: 'Price: High to Low' },
        ],
      },
    });
  } catch (error) {
    console.error("Get filter options error:", error);
    return NextResponse.json(
      { error: "Failed to get filter options" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
