    console.error('Error saving boutique settings:', error)
    return NextResponse.json(
      { success: false, message: 'Failed to save settings' },
      { status: 500 }
    )
  }
}

import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'
import { prismaErrorResponse } from '@/lib/prismaError'

export async function GET() {
  try {
    if (!process.env.DATABASE_URL) {
      return NextResponse.json(
        { error: 'Database not configured' },
        { status: 500 }
      )
    }

    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    // Check seller role
    if (session?.user?.role && !['SELLER', 'ADMIN'].includes(session.user.role)) {
      return NextResponse.json({ error: 'Forbidden - Only sellers can access this' }, { status: 403 })
    }

    const userId = session.user.id

    // Get total earnings from SellerEarning model (uses sellerAmount field)
    const totalEarningsResult = await prisma.sellerEarning.aggregate({
      where: { sellerId: userId },
      _sum: { sellerAmount: true },
    })

    // Get this month's earnings
    const startOfMonth = new Date()
    startOfMonth.setDate(1)
    startOfMonth.setHours(0, 0, 0, 0)

    const thisMonthResult = await prisma.sellerEarning.aggregate({
      where: {
        sellerId: userId,
        createdAt: { gte: startOfMonth },
      },
      _sum: { sellerAmount: true },
    })

    // Get last month's earnings
    const startOfLastMonth = new Date()
    startOfLastMonth.setMonth(startOfLastMonth.getMonth() - 1)
    startOfLastMonth.setDate(1)
    startOfLastMonth.setHours(0, 0, 0, 0)

    const endOfLastMonth = new Date(startOfMonth)
    endOfLastMonth.setMilliseconds(-1)

    const lastMonthResult = await prisma.sellerEarning.aggregate({
      where: {
        sellerId: userId,
        createdAt: {
          gte: startOfLastMonth,
          lte: endOfLastMonth,
        },
      },
      _sum: { sellerAmount: true },
    })

    const totalEarnings = totalEarningsResult._sum?.sellerAmount ?? 0
    const thisMonthEarnings = thisMonthResult._sum?.sellerAmount ?? 0
    const lastMonthEarnings = lastMonthResult._sum?.sellerAmount ?? 0

    // Get transfer data to calculate accurate balance
    const transfers = await prisma.paystackTransfer.findMany({
      where: { sellerId: userId }
    })
    const totalWithdrawn = transfers
      .filter((t: any) => t.paystackStatus === 'SUCCESS')
      .reduce((sum: number, t: any) => sum + (t.amountUSD || 0), 0)
    const pendingPayout = transfers
      .filter((t: any) => ['PENDING', 'INITIATED'].includes(t.paystackStatus))
      .reduce((sum: number, t: any) => sum + (t.amountUSD || 0), 0)
    const availableBalance = Math.max(totalEarnings - totalWithdrawn - pendingPayout, 0)

    return NextResponse.json({
      totalEarnings,
      pendingPayout,
      availableBalance,
      totalWithdrawn,
      thisMonthEarnings,
      lastMonthEarnings,
    })
  } catch (error) {
    console.error('Failed to fetch earnings stats:', error)
    const prismaResp = prismaErrorResponse(error, 'Database temporarily unavailable')
    if (prismaResp) return prismaResp
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use server'

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'
import { prismaErrorResponse } from '@/lib/prismaError'
import { getMaxFeaturedListings } from '@/lib/commission-tiers'
import {
  checkRateLimit,
  logAuditEntry,
  isItemAlreadyFeatured,
  _validateItemForFeaturing,
  getIpAddress
} from '@/lib/featured-validation'

/**
 * GET /api/seller/featured-designs
 * Get seller's featured designs with subscription tier limit
 * Query params:
 *   - designId: Check if a specific design is featured (returns { isFeatured: boolean })
 */
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const designId = searchParams.get('designId')

    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      )
    }

    // If checking if a design is featured
    if (designId) {
      const featured = await prisma.featuredDesign.findFirst({
        where: {
          designId,
          sellerId: session.user.id
        }
      })
      return NextResponse.json({ isFeatured: !!featured })
    }

    // Get seller's subscription tier
    const seller = await prisma.user.findUnique({
      where: { id: session.user.id },
      select: { subscriptionTier: true, proTrialActivated: true, proTrialExpiresAt: true }
    })

    if (!seller) {
      return NextResponse.json({ error: 'Seller not found' }, { status: 404 })
    }

    // Check if seller has an active pro trial
    const now = new Date()
    const hasActiveTrial = seller.proTrialActivated && seller.proTrialExpiresAt && seller.proTrialExpiresAt > now
    
    // If user has active trial, they get PRO tier benefits
    const effectiveSubscriptionTier = hasActiveTrial ? 'PRO' : seller.subscriptionTier
    const maxFeatured = getMaxFeaturedListings(effectiveSubscriptionTier)

    // Use raw query to handle addedByAdmin field that might not exist in all docs
    let featuredDesigns: any[] = []
    try {
      const designs = await prisma.featuredDesign.findMany({
        where: { sellerId: session.user.id },
        select: {
          id: true,
          position: true,
          addedAt: true,
          addedByAdmin: true,
          design: {
            select: {
              id: true,
              title: true,
              imageUrl: true,
              thumbnailUrl: true,
              price: true,
              totalSales: true,
              totalRevenue: true,
            }
          }
        },
        orderBy: { position: 'asc' }
      })
      
      featuredDesigns = designs.map(d => ({
        ...d,
        addedByAdmin: d.addedByAdmin ?? false
      }))
    } catch (error) {
      // If the query fails due to missing field, try without it
      console.warn('[GET /api/seller/featured-designs] Retrying without addedByAdmin:', error)
      const designs = await prisma.featuredDesign.findMany({
        where: { sellerId: session.user.id },
        select: {
          id: true,
          position: true,
          addedAt: true,
          design: {
            select: {
              id: true,
              title: true,
              imageUrl: true,
              thumbnailUrl: true,
              price: true,
              totalSales: true,
              totalRevenue: true,
            }
          }
        },
        orderBy: { position: 'asc' }
      })
      
      featuredDesigns = designs.map((d: any) => ({
        ...d,
        addedByAdmin: false
      }))
    }

    // Get total available designs to feature
    const availableDesigns = await prisma.design.findMany({
      where: {
        designerId: session.user.id,
        isActive: true,
        approvalStatus: 'APPROVED'
      },
      select: {
        id: true,
        title: true,
        imageUrl: true,
        thumbnailUrl: true,
        price: true,
        totalSales: true,
      },
      take: 100
    })

    return NextResponse.json({
      items: featuredDesigns.map(f => ({
        id: f.id,
        itemId: f.design.id,
        title: f.design.title,
        imageUrl: f.design.imageUrl || f.design.thumbnailUrl,
        price: f.design.price,
        totalSales: f.design.totalSales,
        position: f.position,
        addedAt: f.addedAt.toISOString(),
        addedByAdmin: f.addedByAdmin ?? false
      })),
      availableDesigns,
      currentFeaturedCount: featuredDesigns.length,
      subscriptionTier: seller.subscriptionTier,
      proTrialActive: hasActiveTrial,
      proTrialExpiresAt: seller.proTrialExpiresAt ? seller.proTrialExpiresAt.toISOString() : null,
      maxFeatured,
      remainingSlots: Math.max(0, maxFeatured - featuredDesigns.length)
    })
  } catch (error) {
    console.error('[GET /api/seller/featured-designs] Error:', {
      message: error instanceof Error ? error.message : String(error),
      stack: error instanceof Error ? error.stack : undefined
    })
    const prismaResp = prismaErrorResponse(error, 'Failed to fetch featured designs')
    if (prismaResp) return prismaResp
    return NextResponse.json({ error: 'Failed to fetch featured designs', details: error instanceof Error ? error.message : String(error) }, { status: 500 })
  }
}

/**
 * POST /api/seller/featured-designs
 * Add a design to featured (max 6)
 * 
 * Body: {
 *   designId: string,
 *   position?: number (1-6)
 * }
 */
export async function POST(request: NextRequest) {
  const ipAddress = getIpAddress(request)
  
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      )
    }

    // Check rate limit
    const rateLimit = checkRateLimit(session.user.id, 'featured-designs', 'POST')
    if (!rateLimit.allowed) {
      return NextResponse.json(
        { 
          error: 'Too many requests. Please wait before trying again.',
          errorCode: 'RATE_LIMIT_EXCEEDED',
          resetTime: rateLimit.resetTime
        },
        { status: 429 }
      )
    }

    const body = await request.json()
    const { designId, position } = body

    if (!designId) {
      return NextResponse.json(
        { error: 'Design ID is required' },
        { status: 400 }
      )
    }

    // Verify design belongs to seller and is approved
    const design = await prisma.design.findUnique({
      where: { id: designId },
      select: { designerId: true, approvalStatus: true, isActive: true }
    })

    if (!design) {
      logAuditEntry({
        userId: session.user.id,
        action: 'FEATURED_ADDED',
        itemType: 'DESIGN',
        itemId: designId,
        timestamp: new Date(),
        ipAddress,
        success: false,
        errorCode: 'DESIGN_NOT_FOUND'
      })
      return NextResponse.json({ error: 'Design not found' }, { status: 404 })
    }

    // Check user role
    const user = await prisma.user.findUnique({
      where: { id: session.user.id },
      select: { role: true }
    })

    const isAdmin = user?.role === 'ADMIN'

    // Only allow if user is the designer OR is an admin
    if (!isAdmin && design.designerId !== session.user.id) {
      logAuditEntry({
        userId: session.user.id,
        action: 'FEATURED_ADDED',
        itemType: 'DESIGN',
        itemId: designId,
        timestamp: new Date(),
        ipAddress,
        success: false,
        errorCode: 'UNAUTHORIZED'
      })
      return NextResponse.json({ error: 'Unauthorized' }, { status: 403 })
    }

    if (design.approvalStatus !== 'APPROVED' || !design.isActive) {
      logAuditEntry({
        userId: session.user.id,
        action: 'FEATURED_ADDED',
        itemType: 'DESIGN',
        itemId: designId,
        timestamp: new Date(),
        ipAddress,
        success: false,
        errorCode: 'DESIGN_NOT_APPROVED'
      })
      return NextResponse.json(
        { error: 'Design must be active and approved to feature' },
        { status: 400 }
      )
    }

    // Get the seller (either the designer or if admin, the designer of this design)
    const sellerId = isAdmin ? design.designerId : session.user.id

    // Check current featured count and verify subscription tier
    const seller = await prisma.user.findUnique({
      where: { id: sellerId },
      select: { subscriptionTier: true, proTrialActivated: true, proTrialExpiresAt: true }
    })

    if (!seller) {
      return NextResponse.json({ error: 'Seller not found' }, { status: 404 })
    }

    // Check if seller has an active pro trial
    const now = new Date()
    const hasActiveTrial = seller.proTrialActivated && seller.proTrialExpiresAt && seller.proTrialExpiresAt > now
    
    // Ensure subscriptionTier is properly handled (null, undefined, empty string -> treat as no subscription)
    let normalizedTier: string | null = seller.subscriptionTier ?? null
    if (normalizedTier === '' || normalizedTier === 'null') {
      normalizedTier = null
    }
    
    // If user has active trial, they get PRO tier benefits
    const effectiveSubscriptionTier = hasActiveTrial ? 'PRO' : normalizedTier
    const maxFeatured = getMaxFeaturedListings(effectiveSubscriptionTier)

    console.log('[POST /api/seller/featured-designs] Subscription check:', {
      userId: session.user.id,
      sellerId,
      subscriptionTier: seller.subscriptionTier,
      subscriptionTierType: typeof seller.subscriptionTier,
      subscriptionTierLength: typeof seller.subscriptionTier === 'string' ? seller.subscriptionTier.length : 'N/A',
      normalizedTier,
      hasActiveTrial,
      effectiveSubscriptionTier,
      maxFeatured,
      isAdmin
    })

    // Check if seller is allowed to feature at all (admins can bypass)
    // Be explicit: if maxFeatured is 0 AND they're not admin, BLOCK them
    if (!isAdmin && (maxFeatured === 0 || !normalizedTier)) {
      console.warn('[POST /api/seller/featured-designs] BLOCKED - No subscription tier or max is 0', {
        userId: session.user.id,
        sellerId,
        tier: seller.subscriptionTier,
        normalizedTier,
        maxFeatured,
        isAdmin
      })
      return NextResponse.json(
        { 
          error: 'Your subscription is not active. Featured listings are only available with an active subscription.',
          errorCode: 'NO_FEATURED_ACCESS',
          currentTier: normalizedTier || 'FREE',
          maxAllowed: maxFeatured,
          requiredTier: 'STARTER',
          upgradeMessage: 'Upgrade to STARTER (2 featured), PRO (6 featured), or VIP (10 featured) to feature designs'
        },
        { status: 403 }
      )
    }

    const currentFeaturedDesigns = await prisma.featuredDesign.count({
      where: { sellerId }
    })

    const currentFeaturedBoutique = await prisma.featuredBoutiqueProduct.count({
      where: { sellerId }
    })

    const totalFeatured = currentFeaturedDesigns + currentFeaturedBoutique

    if (!isAdmin && totalFeatured >= maxFeatured) {
      return NextResponse.json(
        { 
          error: `You have reached your featured items limit (${totalFeatured}/${maxFeatured}).`,
          errorCode: 'TIER_LIMIT_REACHED',
          currentTier: seller.subscriptionTier,
          current: totalFeatured,
          max: maxFeatured,
          upgradeMessage: 'Upgrade to a higher tier to feature more items'
        },
        { status: 409 }
      )
    }

    // Check if already featured (prevent duplicates)
    const existing = await isItemAlreadyFeatured(designId, 'DESIGN', session.user.id, prisma)
    if (existing) {
      logAuditEntry({
        userId: session.user.id,
        action: 'FEATURED_ADDED',
        itemType: 'DESIGN',
        itemId: designId,
        timestamp: new Date(),
        ipAddress,
        success: false,
        errorCode: 'ALREADY_FEATURED'
      })
      return NextResponse.json(
        { error: 'This design is already featured' },
        { status: 409 }
      )
    }

    // Create featured design
    const nextPosition = position || (totalFeatured + 1)

    const featured = await prisma.featuredDesign.create({
      data: {
        designId,
        sellerId,
        position: nextPosition,
        addedByAdmin: isAdmin
      },
      include: {
        design: {
          select: {
            id: true,
            title: true,
            imageUrl: true,
            price: true,
          }
        }
      }
    })

    // Log successful audit entry
    logAuditEntry({
      userId: session.user.id,
      action: 'FEATURED_ADDED',
      itemType: 'DESIGN',
      itemId: designId,
      timestamp: new Date(),
      ipAddress,
      success: true
    })

    return NextResponse.json({
      success: true,
      featured: {
        ...featured,
        addedAt: featured.addedAt.toISOString()
      },
      message: 'Design added to featured'
    })
  } catch (error) {
    console.error('[POST /api/seller/featured-designs]', error)
    const prismaResp = prismaErrorResponse(error, 'Failed to add featured design')
    if (prismaResp) return prismaResp
    return NextResponse.json({ error: 'Failed to add featured design' }, { status: 500 })
  }
}

/**
 * DELETE /api/seller/featured-designs?id=<featuredId> OR ?designId=<designId>
 * Remove a design from featured
 * Accepts either featured record ID or design ID
 */
export async function DELETE(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      )
    }

    // Extract ID from query parameter
    const { searchParams } = new URL(request.url)
    const featuredId = searchParams.get('id')
    const designId = searchParams.get('designId')

    if (!featuredId && !designId) {
      return NextResponse.json(
        { error: 'Featured design ID or design ID is required' },
        { status: 400 }
      )
    }

    // Check user role
    const user = await prisma.user.findUnique({
      where: { id: session.user.id },
      select: { role: true }
    })

    const isAdmin = user?.role === 'ADMIN'

    // If designId provided, find the featured record first
    let idToDelete = featuredId
    if (designId) {
      const featured = await prisma.featuredDesign.findUnique({
        where: { sellerId_designId: { sellerId: session.user.id, designId } },
        select: { id: true }
      })
      if (!featured && !isAdmin) {
        return NextResponse.json({ error: 'Featured design not found' }, { status: 404 })
      }
      if (featured) {
        idToDelete = featured.id
      } else if (isAdmin) {
        // For admins, find the featured design regardless of seller
        const adminFeatured = await prisma.featuredDesign.findFirst({
          where: { designId },
          select: { id: true }
        })
        if (!adminFeatured) {
          return NextResponse.json({ error: 'Featured design not found' }, { status: 404 })
        }
        idToDelete = adminFeatured.id
      }
    }

    if (!idToDelete) {
      return NextResponse.json(
        { error: 'Invalid featured design ID' },
        { status: 400 }
      )
    }

    // Verify ownership (or admin status)
    const featured = await prisma.featuredDesign.findUnique({
      where: { id: idToDelete }
    })

    if (!featured) {
      return NextResponse.json({ error: 'Featured design not found' }, { status: 404 })
    }

    if (!isAdmin && featured.sellerId !== session.user.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 403 })
    }

    // Delete featured design
    await prisma.featuredDesign.delete({
      where: { id: idToDelete }
    })

    // Log successful audit entry
    logAuditEntry({
      userId: session.user.id,
      action: 'FEATURED_REMOVED',
      itemType: 'DESIGN',
      itemId: featured.designId,
      timestamp: new Date(),
      ipAddress: getIpAddress(request),
      success: true
    })

    return NextResponse.json({
      success: true,
      message: 'Design removed from featured'
    })
  } catch (error) {
    console.error('[DELETE /api/seller/featured-designs]', error)
    const prismaResp = prismaErrorResponse(error, 'Failed to remove featured design')
    if (prismaResp) return prismaResp
    return NextResponse.json({ error: 'Failed to remove featured design' }, { status: 500 })
  }
}

/**
 * PATCH /api/seller/featured-designs?id=<featuredId>&position=<newPosition>
 * Update position of a featured design
 */
export async function PATCH(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      )
    }

    const { searchParams } = new URL(request.url)
    const featuredId = searchParams.get('id')
    const positionStr = searchParams.get('position')

    if (!featuredId || !positionStr) {
      return NextResponse.json(
        { error: 'Missing id or position parameter' },
        { status: 400 }
      )
    }

    const newPosition = parseInt(positionStr, 10)
    if (isNaN(newPosition) || newPosition < 1) {
      return NextResponse.json(
        { error: 'Position must be a positive integer' },
        { status: 400 }
      )
    }

    // Verify ownership
    const featured = await prisma.featuredDesign.findUnique({
      where: { id: featuredId },
      select: { sellerId: true }
    })

    if (!featured) {
      return NextResponse.json({ error: 'Featured design not found' }, { status: 404 })
    }

    if (featured.sellerId !== session.user.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 403 })
    }

    // Update position
    await prisma.featuredDesign.update({
      where: { id: featuredId },
      data: { position: newPosition }
    })

    return NextResponse.json({
      success: true,
      message: 'Position updated'
    })
  } catch (error) {
    console.error('[PATCH /api/seller/featured-designs]', error)
    const prismaResp = prismaErrorResponse(error, 'Failed to update position')
    if (prismaResp) return prismaResp
    return NextResponse.json({ error: 'Failed to update position' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth/next'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'
import { prismaErrorResponse } from '@/lib/prismaError'

export async function GET(_req: NextRequest) {
  try {
    if (!process.env.DATABASE_URL) {
      return NextResponse.json(
        { error: 'Database not configured' },
        { status: 500 }
      )
    }

    const session = await getServerSession(authOptions)
    
    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      )
    }

    // Check seller role
    if (session?.user?.role && !['SELLER', 'ADMIN'].includes(session.user.role)) {
      return NextResponse.json(
        { error: 'Forbidden - Only sellers can access this' },
        { status: 403 }
      )
    }

    const userId = session.user.id

    // Get user's seller earnings
    const sellerEarnings = await prisma.sellerEarning.aggregate({
      where: { sellerId: userId },
      _sum: {
        sellerAmount: true,
      }
    })

    // Get current month earnings
    const now = new Date()
    const monthStart = new Date(now.getFullYear(), now.getMonth(), 1)
    monthStart.setHours(0, 0, 0, 0)
    const monthEarnings = await prisma.sellerEarning.aggregate({
      where: {
        sellerId: userId,
        createdAt: { gte: monthStart }
      },
      _sum: { sellerAmount: true }
    })

    // Get transfer stats
    const transfers = await prisma.paystackTransfer.findMany({
      where: { sellerId: userId }
    })

    const successfulTransfers = transfers.filter((t: any) => t.paystackStatus === 'SUCCESS').length
    const pendingTransfers = transfers.filter((t: any) => t.paystackStatus === 'PENDING').length
    const failedTransfers = transfers.filter((t: any) => t.paystackStatus === 'FAILED').length
    const totalAmountTransferred = transfers
      .filter((t: any) => t.paystackStatus === 'SUCCESS')
      .reduce((sum: number, t: any) => sum + (t.amountUSD || 0), 0)

    // Get recent earnings (last 7 days)
    const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000)
    const recentEarnings = await prisma.sellerEarning.aggregate({
      where: {
        sellerId: userId,
        createdAt: { gte: sevenDaysAgo }
      },
      _sum: { sellerAmount: true }
    })

    const totalEarnings = sellerEarnings._sum.sellerAmount ?? 0
    const totalWithdrawn = totalAmountTransferred
    
    // Get pending payout (transfers in progress - PENDING and INITIATED)
    const pendingAmount = transfers
      .filter((t: any) => ['PENDING', 'INITIATED'].includes(t.paystackStatus))
      .reduce((sum: number, t: any) => sum + (t.amountUSD || 0), 0)
    
    // Available balance = Total - (Withdrawn + Pending + Failed that user hasn't cancelled)
    // For now: Total - Withdrawn - Pending
    const availableBalance = Math.max(totalEarnings - totalWithdrawn - pendingAmount, 0)

    return NextResponse.json({
      totalEarnings,
      availableBalance,
      pendingPayout: pendingAmount,
      totalWithdrawn,
      thisMonthEarnings: monthEarnings._sum.sellerAmount ?? 0,
      totalTransfers: transfers.length,
      successfulTransfers,
      pendingTransfers,
      failedTransfers,
      totalAmountTransferred,
      recentEarnings: recentEarnings._sum.sellerAmount ?? 0,
    })
  } catch (error) {
    console.error('Error fetching finances summary:', error)
    const prismaResp = prismaErrorResponse(error, 'Database temporarily unavailable')
    if (prismaResp) return prismaResp
    return NextResponse.json(
      { error: 'Failed to fetch summary' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'

export async function GET() {
  try {
    const session = await getServerSession(authOptions)

    if (!session || !session.user?.email) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const user = await prisma.user.findUnique({
      where: { email: session.user.email },
      select: { id: true }
    })

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    // Get unread notifications
    const unreadCount = await (prisma as any).transferNotification.count({
      where: {
        sellerId: user.id,
        isRead: false
      }
    })

    // Get recent notifications (last 20)
    const notifications = await (prisma as any).transferNotification.findMany({
      where: { sellerId: user.id },
      orderBy: { createdAt: 'desc' },
      take: 20
    })

    return NextResponse.json({
      success: true,
      notifications,
      unreadCount
    })
  } catch (error) {
    console.error('Fetch notifications error:', error)
    return NextResponse.json(
      { error: 'Failed to fetch notifications' },
      { status: 500 }
    )
  }
}

export async function PATCH(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)

    if (!session || !session.user?.email) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const user = await prisma.user.findUnique({
      where: { email: session.user.email },
      select: { id: true }
    })

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const body = await request.json()
    const { notificationId, markAsRead } = body

    if (!notificationId) {
      return NextResponse.json({ error: 'notificationId required' }, { status: 400 })
    }

    // Verify notification belongs to this seller
    const notification = await (prisma as any).transferNotification.findUnique({
      where: { id: notificationId }
    })

    if (!notification || notification.sellerId !== user.id) {
      return NextResponse.json({ error: 'Notification not found' }, { status: 404 })
    }

    // Update notification
    const updated = await prisma.transferNotification.update({
      where: { id: notificationId },
      data: {
        isRead: markAsRead,
        readAt: markAsRead ? new Date() : null
      }
    })

    return NextResponse.json({
      success: true,
      notification: updated
    })
  } catch (error) {
    console.error('Update notification error:', error)
    return NextResponse.json(
      { error: 'Failed to update notification' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'
import { prismaErrorResponse } from '@/lib/prismaError'

/**
 * GET /api/seller/payments
 * Returns all payment transactions for the authenticated seller
 * Includes: order details, processor info, commission breakdown, payout status
 */
export async function GET(request: NextRequest) {
  try {
    if (!process.env.DATABASE_URL) {
      return NextResponse.json(
        { error: 'Database not configured' },
        { status: 500 }
      )
    }

    const session = await getServerSession(authOptions)

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      )
    }

    // Check seller role
    if (session?.user?.role && !['SELLER', 'ADMIN'].includes(session.user.role)) {
      return NextResponse.json(
        { error: 'Forbidden - Only sellers can access this' },
        { status: 403 }
      )
    }

    const { searchParams } = new URL(request.url)
    
    const pageParsed = parseInt(searchParams.get('page') || '1', 10)
    const limitParsed = parseInt(searchParams.get('limit') || '20', 10)
    
    if (isNaN(pageParsed) || isNaN(limitParsed)) {
      return NextResponse.json(
        { error: 'Invalid pagination parameters' },
        { status: 400 }
      )
    }
    
    const page = Math.max(1, pageParsed)
    const limit = Math.min(100, Math.max(1, limitParsed))
    const status = searchParams.get('status') // PENDING, COMPLETED, FAILED
    const processor = searchParams.get('processor') // PAYSTACK, STRIPE, FLUTTERWAVE
    const startDate = searchParams.get('startDate')
    const endDate = searchParams.get('endDate')

    const skip = (page - 1) * limit

    // Build filters
    const where: any = {
      sellerId: session.user.id,
    }

    if (status) {
      where.payoutStatus = status
    }

    if (processor) {
      where.processor = processor
    }

    if (startDate) {
      const startDateObj = new Date(startDate)
      if (!isNaN(startDateObj.getTime())) {
        where.completedAt = { gte: startDateObj }
      }
    }

    if (endDate) {
      const endDateObj = new Date(endDate)
      if (!isNaN(endDateObj.getTime())) {
        if (where.completedAt) {
          where.completedAt.lte = endDateObj
        } else {
          // If only endDate is provided, only filter by endDate
          where.completedAt = { lte: endDateObj }
        }
      }
    }

    const [transactions, total] = await Promise.all([
      prisma.paymentTransaction.findMany({
        where,
        select: {
          id: true,
          orderId: true,
          processor: true,
          currency: true,
          buyerAmount: true,
          platformFee: true,
          sellerPayout: true,
          processorFee: true,
          initiatedAt: true,
          completedAt: true,
          payoutStatus: true,
          payoutScheduledAt: true,
          payoutCompletedAt: true,
          processorStatus: true,
          failureReason: true,
          order: {
            select: {
              id: true,
              orderNumber: true,
              status: true,
              total: true,
              items: {
                select: {
                  id: true,
                  product: {
                    select: { title: true },
                  },
                  quantity: true,
                  price: true,
                },
              },
            },
          },
        },
        orderBy: { completedAt: 'desc' },
        skip,
        take: limit,
      }),
      prisma.paymentTransaction.count({ where }),
    ])

    // Calculate summary statistics
    const summary = await prisma.paymentTransaction.aggregate({
      where,
      _sum: {
        buyerAmount: true,
        sellerPayout: true,
        platformFee: true,
        processorFee: true,
      },
      _count: true,
    })

    const statusBreakdown = await prisma.paymentTransaction.groupBy({
      by: ['payoutStatus'],
      where,
      _count: true,
      _sum: {
        sellerPayout: true,
      },
    })

    return NextResponse.json({
      transactions,
      pagination: {
        page,
        limit,
        total,
        pages: limit > 0 ? Math.ceil(total / limit) : 0,
      },
      summary: {
        totalTransactions: summary._count,
        totalRevenue: summary._sum.buyerAmount || 0,
        totalPayout: summary._sum.sellerPayout || 0,
        totalPlatformFee: summary._sum.platformFee || 0,
        totalProcessorFee: summary._sum.processorFee || 0,
      },
      statusBreakdown: Object.fromEntries(
        statusBreakdown.map((sb) => [
          sb.payoutStatus,
          { count: sb._count, total: sb._sum.sellerPayout || 0 },
        ])
      ),
    })
  } catch (error) {
    console.error('Error fetching seller payments:', error)
    const prismaResp = prismaErrorResponse(error, 'Database temporarily unavailable')
    if (prismaResp) return prismaResp
    return NextResponse.json(
      { error: 'Failed to fetch payments' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import prisma from "@/lib/prisma";

/**
 * POST /api/seller/promotions - Create a promotion
 */
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await request.json();
    const {
      type,
      name,
      description,
      discountType,
      discountValue,
      designIds: rawDesignIds,
      productIds: rawProductIds,
      bundlePrice,
      startDate,
      endDate,
      maxUsage,
    } = body;

    // Sanitize designIds and productIds - filter out empty or null values
    const designIds = (rawDesignIds || [])
      .filter((id: any): id is string => typeof id === 'string' && id.trim().length > 0)
      .map((id: string) => id.trim());
    
    const productIds = (rawProductIds || [])
      .filter((id: any): id is string => typeof id === 'string' && id.trim().length > 0)
      .map((id: string) => id.trim());

    // Check what type of items this promotion applies to
    const hasDesigns = designIds && designIds.length > 0;
    const hasProducts = productIds && productIds.length > 0;

    // Validate that promotion applies to EITHER designs OR products, but not both
    if (hasDesigns && hasProducts) {
      return NextResponse.json(
        { error: "A promotion must apply to either Designs or Boutique Products, not both. Please choose one type." },
        { status: 400 }
      );
    }

    if (!hasDesigns && !hasProducts) {
      return NextResponse.json(
        { error: "A promotion must include at least one Design or Boutique Product" },
        { status: 400 }
      );
    }

    // Validate required fields
    if (!name || name.trim().length === 0) {
      return NextResponse.json(
        { error: "Promotion name is required" },
        { status: 400 }
      );
    }

    if (!type || !['DISCOUNT', 'BUNDLE', 'FLASH_SALE'].includes(type)) {
      return NextResponse.json(
        { error: "Invalid promotion type" },
        { status: 400 }
      );
    }

    // For DISCOUNT and FLASH_SALE, discount type and value are required
    if (type === 'DISCOUNT' || type === 'FLASH_SALE') {
      if (!discountType || !['PERCENTAGE', 'FIXED'].includes(discountType)) {
        return NextResponse.json(
          { error: "Invalid discount type" },
          { status: 400 }
        );
      }

      if (typeof discountValue !== 'number' || discountValue <= 0) {
        return NextResponse.json(
          { error: "Discount value must be greater than 0" },
          { status: 400 }
        );
      }

      // Validate percentage not over 100%
      if (discountType === 'PERCENTAGE' && discountValue > 100) {
        return NextResponse.json(
          { error: "Percentage discount cannot exceed 100%" },
          { status: 400 }
        );
      }
    } else if (type === 'BUNDLE') {
      // For BUNDLE, discountType and discountValue should not be provided
      if (discountType || discountValue) {
        return NextResponse.json(
          { error: "BUNDLE promotions use bundlePrice, not discountType/discountValue" },
          { status: 400 }
        );
      }
    }

    // Validate bundle-specific requirements
    if (type === 'BUNDLE') {
      if (typeof bundlePrice !== 'number' || bundlePrice <= 0) {
        return NextResponse.json(
          { error: "Bundle price must be greater than 0" },
          { status: 400 }
        );
      }

      // Validate bundle price is less than sum of individual prices
      let totalPrice = 0;

      if (hasDesigns) {
        const bundleDesigns = await prisma.design.findMany({
          where: { id: { in: designIds } },
          select: { price: true }
        });
        totalPrice = bundleDesigns.reduce((sum, design) => sum + design.price, 0);
      }

      if (hasProducts) {
        const bundleProducts = await prisma.boutiqueProduct.findMany({
          where: { id: { in: productIds } },
          select: { basePrice: true }
        });
        totalPrice = bundleProducts.reduce((sum, product) => sum + product.basePrice, 0);
      }

      if (bundlePrice >= totalPrice) {
        return NextResponse.json(
          { error: `Bundle price must be less than the combined price of items ($${totalPrice.toFixed(2)})` },
          { status: 400 }
        );
      }
    }

    const start = new Date(startDate);
    const end = new Date(endDate);

    if (isNaN(start.getTime()) || isNaN(end.getTime())) {
      return NextResponse.json(
        { error: "Invalid date format" },
        { status: 400 }
      );
    }

    if (end <= start) {
      return NextResponse.json(
        { error: "End date must be after start date" },
        { status: 400 }
      );
    }

    // Validate maxUsage if provided
    if (maxUsage !== null && maxUsage !== undefined) {
      if (typeof maxUsage !== 'number' || maxUsage < 1) {
        return NextResponse.json(
          { error: "Maximum usage must be at least 1" },
          { status: 400 }
        );
      }
    }

    // Validate designs belong to seller
    if (designIds && designIds.length > 0) {
      const designs = await prisma.design.findMany({
        where: {
          id: { in: designIds },
          designerId: session.user.id,
        },
      });

      if (designs.length !== designIds.length) {
        return NextResponse.json(
          { error: "Some designs do not belong to you" },
          { status: 400 }
        );
      }

      // Check for overlapping active promotions on designs
      const overlappingDesignPromotions = await prisma.promotion.findMany({
        where: {
          designIds: {
            hasSome: designIds
          },
          isActive: true,
          endDate: {
            gt: new Date()
          }
        },
        select: {
          id: true,
          name: true,
          type: true,
          designIds: true
        }
      });

      if (overlappingDesignPromotions.length > 0) {
        const conflictingDesigns = new Map<string, string>();
        for (const promo of overlappingDesignPromotions) {
          for (const designId of designIds) {
            if ((promo.designIds as string[]).includes(designId)) {
              conflictingDesigns.set(designId, `${promo.name} (${promo.type})`);
            }
          }
        }

        return NextResponse.json(
          {
            error: `These designs already have active promotions and cannot be added to another promotion`,
            conflictingDesigns: Object.fromEntries(conflictingDesigns),
            existingPromotions: overlappingDesignPromotions.map(p => ({
              id: p.id,
              name: p.name,
              type: p.type,
              conflictingCount: (p.designIds as string[]).filter(id => designIds.includes(id)).length
            }))
          },
          { status: 409 }
        );
      }
    }

    // Validate products belong to seller
    if (productIds && productIds.length > 0) {
      const products = await prisma.boutiqueProduct.findMany({
        where: {
          id: { in: productIds },
          sellerId: session.user.id,
        },
      });

      if (products.length !== productIds.length) {
        return NextResponse.json(
          { error: "Some products do not belong to you" },
          { status: 400 }
        );
      }

      // Check for overlapping active promotions on products
      const overlappingProductPromotions = await prisma.promotion.findMany({
        where: {
          productIds: {
            hasSome: productIds
          },
          isActive: true,
          endDate: {
            gt: new Date()
          }
        },
        select: {
          id: true,
          name: true,
          type: true,
          productIds: true
        }
      });

      if (overlappingProductPromotions.length > 0) {
        const conflictingProducts = new Map<string, string>();
        for (const promo of overlappingProductPromotions) {
          for (const productId of productIds) {
            if ((promo.productIds as string[]).includes(productId)) {
              conflictingProducts.set(productId, `${promo.name} (${promo.type})`);
            }
          }
        }

        return NextResponse.json(
          {
            error: `These products already have active promotions and cannot be added to another promotion`,
            conflictingProducts: Object.fromEntries(conflictingProducts),
            existingPromotions: overlappingProductPromotions.map(p => ({
              id: p.id,
              name: p.name,
              type: p.type,
              conflictingCount: (p.productIds as string[]).filter(id => productIds.includes(id)).length
            }))
          },
          { status: 409 }
        );
      }
    }

    const promotion = await prisma.promotion.create({
      data: {
        sellerId: session.user.id,
        type,
        name,
        description,
        discountType,
        discountValue,
        designIds: designIds || [],
        productIds: productIds || [],
        bundlePrice,
        startDate: new Date(startDate),
        endDate: new Date(endDate),
        maxUsage,
        isActive: true,
      },
    });

    return NextResponse.json({ promotion }, { status: 201 });
  } catch (error) {
    console.error("Create promotion error:", error);
    return NextResponse.json(
      { error: "Failed to create promotion" },
      { status: 500 }
    );
  }
}

/**
 * GET /api/seller/promotions - Get seller's promotions
 */
export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const status = searchParams.get("status"); // active, expired, all

    const where: Record<string, unknown> = {
      sellerId: session.user.id,
    };

    if (status === "active") {
      where.isActive = true;
      where.endDate = { gte: new Date() };
    } else if (status === "expired") {
      where.OR = [
        { isActive: false },
        { endDate: { lt: new Date() } },
      ];
    }

    const promotions = await prisma.promotion.findMany({
      where: where as any,
      orderBy: { createdAt: 'desc' },
    });

    // Enrich with design and product info
    const enrichedPromotions = await Promise.all(
      promotions.map(async (promo) => {
        try {
          const designIds = Array.isArray(promo.designIds) ? promo.designIds : [];
          const productIds = Array.isArray((promo as any).productIds) ? (promo as any).productIds : [];

          const designs = designIds.length > 0 
            ? await prisma.design.findMany({
                where: { id: { in: designIds } },
                select: {
                  id: true,
                  title: true,
                  thumbnailUrl: true,
                  price: true,
                },
              })
            : [];
          
          const products = productIds.length > 0
            ? await prisma.boutiqueProduct.findMany({
                where: { id: { in: productIds } },
                select: {
                  id: true,
                  title: true,
                  thumbnailUrl: true,
                  basePrice: true,
                },
              })
            : [];

          return { ...promo, designs, products };
        } catch (err) {
          console.error(`Error enriching promotion ${promo.id}:`, err);
          return { ...promo, designs: [], products: [] };
        }
      })
    );

    return NextResponse.json({ promotions: enrichedPromotions });
  } catch (error) {
    console.error("Get promotions error:", error);
    if (error instanceof Error) {
      console.error("Error message:", error.message);
      console.error("Error stack:", error.stack);
    }
    return NextResponse.json(
      { error: "Failed to get promotions" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import prisma from '@/lib/prisma'
import { prismaErrorResponse } from '@/lib/prismaError'

export async function GET(_request: NextRequest) {
  try {
    if (!process.env.DATABASE_URL) {
      return NextResponse.json(
        { error: 'Database not configured' },
        { status: 500 }
      )
    }

    const session = await getServerSession(authOptions)

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      )
    }

    // Check seller role
    if (session?.user?.role && !['SELLER', 'ADMIN'].includes(session.user.role)) {
      return NextResponse.json(
        { error: 'Forbidden - Only sellers can access this' },
        { status: 403 }
      )
    }

    const sellerId = session.user.id

    // Get all transfers for this user
    const transfers = await (prisma as any).paystackTransfer.findMany({
      where: { sellerId },
      orderBy: { createdAt: 'desc' }
    })

    // Summary stats
    const stats = {
      totalTransfers: transfers.length,
      successfulTransfers: transfers.filter((t: any) => t.paystackStatus === 'SUCCESS').length,
      failedTransfers: transfers.filter((t: any) => ['FAILED', 'CANCELLED'].includes(t.paystackStatus || '')).length,
      pendingTransfers: transfers.filter((t: any) => ['PENDING', 'INITIATED'].includes(t.paystackStatus || '')).length,
      totalAmountUSD: transfers
        .filter((t: any) => t.paystackStatus === 'SUCCESS')
        .reduce((sum: number, t: any) => sum + (t.amountUSD || 0), 0),
      totalAmountNGN: transfers
        .filter((t: any) => t.paystackStatus === 'SUCCESS')
        .reduce((sum: number, t: any) => sum + (t.amountNGN || 0), 0)
    }

    return NextResponse.json({
      transfers,
      stats
    })
  } catch (error) {
    console.error('Fetch transfers error:', error)
    const prismaResp = prismaErrorResponse(error, 'Database temporarily unavailable')
    if (prismaResp) return prismaResp
    return NextResponse.json(
      { error: 'Failed to fetch transfers' },
      { status: 500 }
    )
  }
}

/**
 * Socket.IO Route Handler for Next.js App Router
 * Initializes the Socket.IO server on first request
 */

import { NextRequest, NextResponse } from 'next/server'
import { Server as NetServer } from 'http'
import { Server as SocketIOServer } from 'socket.io'
import { initializeSocketServer } from '@/lib/socket-server'

// Extend NodeJS global to store the Socket.IO server
declare global {
  let __socketio_server: SocketIOServer | undefined
}

export async function GET(req: NextRequest) {
  // For Socket.IO, we need to upgrade the HTTP connection
  // This is handled differently in production vs development
  
  if (!global.__socketio_server) {
    console.log('[Socket.IO API] Initializing Socket.IO server...')
    
    // Get the HTTP server instance from Next.js
    const httpServer = (req as any).socket?.server || new NetServer()
    
    // Initialize Socket.IO server
    global.__socketio_server = initializeSocketServer(httpServer)
  }

  return NextResponse.json({ 
    success: true, 
    message: 'Socket.IO server is running',
    timestamp: new Date().toISOString()
  })
}

// Handle Socket.IO upgrade for WebSocket connections
export async function POST(req: NextRequest) {
  return GET(req)
}

import { NextRequest, NextResponse } from "next/server";
import prisma from "@/lib/prisma";

// Maximum limit to prevent memory exhaustion
const MAX_LIMIT = 50;

/**
 * GET /api/trending - Get trending designs
 */
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const period = searchParams.get("period") || "WEEKLY";
    const limit = Math.min(parseInt(searchParams.get("limit") || "12", 10), MAX_LIMIT);
    const category = searchParams.get("category");

    const where: Record<string, unknown> = {
      isActive: true,
      approvalStatus: 'APPROVED',
    };

    if (category && category !== 'all') {
      where.category = category;
    }

    // Get designs sorted by trending score
    const designs = await prisma.design.findMany({
      where: where as any,
      take: limit,
      orderBy: [
        { trendingScore: 'desc' },
        { weeklyViews: 'desc' },
        { totalSales: 'desc' },
      ],
      include: {
        designer: {
          select: {
            id: true,
            name: true,
            displayName: true,
            image: true,
            isVerified: true,
            verificationBadge: true,
          },
        },
        _count: {
          select: {
            reviews: true,
            favorites: true,
          },
        },
      },
    });

    // Also get rising stars (new designs with high engagement)
    const risingStars = await prisma.design.findMany({
      where: {
        ...where as any,
        createdAt: {
          gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000), // Last 7 days
        },
      },
      take: 6,
      orderBy: [
        { viewCount: 'desc' },
        { totalSales: 'desc' },
      ],
      include: {
        designer: {
          select: {
            id: true,
            name: true,
            displayName: true,
            image: true,
            isVerified: true,
          },
        },
        _count: {
          select: {
            reviews: true,
            favorites: true,
          },
        },
      },
    });

    return NextResponse.json({
      trending: designs,
      risingStars,
      period,
    });
  } catch (error) {
    console.error("Get trending error:", error);
    return NextResponse.json(
      { error: "Failed to get trending designs" },
      { status: 500 }
    );
  }
}

/**
 * POST /api/trending/calculate - Calculate trending scores (cron job)
 */
export async function POST(request: NextRequest) {
  try {
    // Verify this is a cron job or admin request
    const authHeader = request.headers.get("authorization");
    const cronSecret = process.env.CRON_SECRET;
    
    if (cronSecret && authHeader !== `Bearer ${cronSecret}`) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Get all active designs with their stats
    const designs = await prisma.design.findMany({
      where: { isActive: true, approvalStatus: 'APPROVED' },
      select: {
        id: true,
        viewCount: true,
        weeklyViews: true,
        monthlyViews: true,
        totalSales: true,
        createdAt: true,
        _count: {
          select: {
            favorites: true,
            reviews: true,
          },
        },
      },
    });

    // Calculate trending score for each design
    const updates = designs.map((design) => {
      // Factors:
      // - Recent views (weekly) - higher weight
      // - Total sales
      // - Favorites
      // - Recency (newer designs get a boost)
      
      const ageInDays = (Date.now() - new Date(design.createdAt).getTime()) / (1000 * 60 * 60 * 24);
      const recencyBoost = Math.max(0, 1 - (ageInDays / 30)); // Boost for designs < 30 days old
      
      const trendingScore = 
        (design.weeklyViews * 3) + // Weekly views weighted heavily
        (design.totalSales * 10) + // Sales are important
        (design._count.favorites * 2) + // Favorites show interest
        (design._count.reviews * 5) + // Reviews indicate engagement
        (recencyBoost * 50); // Recency boost

      return prisma.design.update({
        where: { id: design.id },
        data: {
          trendingScore,
          lastTrendingCalc: new Date(),
        },
      });
    });

    await Promise.all(updates);

    return NextResponse.json({
      success: true,
      designsUpdated: designs.length,
    });
  } catch (error) {
    console.error("Calculate trending error:", error);
    return NextResponse.json(
      { error: "Failed to calculate trending" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getStripe } from '@/lib/stripe'
import prisma from '@/lib/prisma'
import { checkAndPromoteDesigners } from '@/lib/seller-promotion'
import { sendPaymentReceivedToDesigner, sendAdminPODAlert, sendSaleNotificationEmail, sendEmail } from '@/lib/email'
import { getCommissionRate, getCommissionTier } from '@/lib/commission-tiers'
import { checkAndUpdateSellerTier, activateProSubscription } from '@/lib/tier-management'
import { fulfillPODOrder } from '@/lib/pod-service'
import { queueFailedNotification } from '@/lib/notification-queue'
import { createOwnershipContract } from '@/lib/ownership-documents'
import { validateDesignOwnershipState } from '@/lib/ownership-validation'
import { _incrementPromotionUsage } from '@/lib/promotion-engine'

const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET!

// Minimal local types for Stripe webhook payloads (keep narrow and safe)
type StripeOrderItem = {
  designId: string
  quantity: number
  price: number
  purchaseType?: 'REGULAR' | 'OWNERSHIP' | 'POD'
  designerId?: string
  designTitle?: string
  podProductId?: string
  podVariantId?: string
  podProductName?: string
  // Promotion tracking
  promotionId?: string | null
  promotionType?: string | null
  discountAmount?: number
}

type StripeCheckoutSession = {
  // Stripe's SDK can set metadata to null ΓÇö allow null to match runtime shapes
  metadata?: { 
    userId?: string
    platformFee?: string
    orderItems?: string
    shippingAddress?: string
    // Commission-specific fields
    type?: string
    commissionRequestId?: string
    designerId?: string
    requesterId?: string
    designerEarnings?: string
    quotedCommissionRate?: string
    quotedDesignerTier?: string
  } | null
  amount_total?: number | null
  payment_intent?: string | null
}

type StripePaymentIntent = {
  id: string
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.text()
    const signature = request.headers.get('stripe-signature')!
    const stripe = getStripe()

    let event

    try {
      event = stripe.webhooks.constructEvent(body, signature, webhookSecret)
    } catch (err) {
      console.error('Webhook signature verification failed:', err)
      return NextResponse.json(
        { message: 'Webhook signature verification failed' },
        { status: 400 }
      )
    }

    // IDEMPOTENCY: Check if we've already processed this event
    const existingEvent = await prisma.processedWebhookEvent.findUnique({
      where: { eventId: event.id }
    })
    
    if (existingEvent) {
      console.log(`Duplicate Stripe event ${event.id}, skipping`)
      return NextResponse.json({ received: true, duplicate: true })
    }

    // Record this event as being processed
    await prisma.processedWebhookEvent.create({
      data: {
        eventId: event.id,
        provider: 'stripe',
        eventType: event.type
      }
    })

    switch (event.type) {
      case 'checkout.session.completed':
        await handleCheckoutCompleted(event.data.object)
        break
      case 'payment_intent.succeeded':
        await handlePaymentSucceeded(event.data.object)
        break
      case 'charge.refunded':
        await handleChargeRefunded(event.data.object)
        break
      case 'customer.subscription.created':
        await handleSubscriptionCreated(event.data.object, stripe)
        break
      case 'customer.subscription.updated':
        await handleSubscriptionUpdated(event.data.object)
        break
      case 'customer.subscription.deleted':
        await handleSubscriptionDeleted(event.data.object)
        break
      case 'invoice.payment_succeeded':
        await handleInvoicePaymentSucceeded(event.data.object)
        break
      default:
        console.log(`Unhandled event type: ${event.type}`)
    }

    return NextResponse.json({ received: true })
  } catch (error) {
    console.error('Webhook error:', error instanceof Error ? error.message : 'Unknown error')
    // SECURITY: Do NOT log full error or request body which may contain sensitive data
    
    // Handle JSON parsing errors
    if (error instanceof SyntaxError) {
      return NextResponse.json(
        { message: 'Invalid JSON in webhook body' },
        { status: 400 }
      )
    }

    // Handle database errors (transient) 
    if (error instanceof Error && error.message.includes('prisma')) {
      return NextResponse.json(
        { message: 'Database temporarily unavailable' },
        { status: 503 }
      )
    }

    // Generic server error (still return 200-ish for webhook, but log for debugging)
    // Webhooks should generally return 200 to prevent retries, but we return 500 for internal errors
    return NextResponse.json(
      { message: 'Webhook processing error' },
      { status: 500 }
    )
  }
}

async function handleCheckoutCompleted(session: unknown) {
  try {
    // Coerce the incoming runtime object to our narrow local shape
    const s = session as StripeCheckoutSession

    // Check if this is a commission payment
    if (s?.metadata?.type === 'commission') {
      await handleCommissionPaymentCompleted(s)
      return
    }

    const userId = s?.metadata?.userId
    if (!userId) {
      console.error('Stripe checkout.session completed webhook missing metadata.userId, skipping order creation')
      return
    }

    const platformFee = parseFloat(s?.metadata?.platformFee || '0')
    let orderItems: StripeOrderItem[] = []
    try {
      orderItems = JSON.parse(s?.metadata?.orderItems || '[]')
    } catch (err) {
      console.error('Failed to parse orderItems from session metadata:', err)
      orderItems = []
    }

    // Generate unique order number
    const orderNumber = `FM-${Date.now()}-${Math.random().toString(36).substr(2, 9).toUpperCase()}`

    // Determine a stable stripe payment intent id (payment_intent can be string or object)
    let stripePaymentIntentId: string | undefined = undefined
    if (s.payment_intent) {
      if (typeof s.payment_intent === 'string') stripePaymentIntentId = s.payment_intent
      else if (typeof s.payment_intent === 'object' && 'id' in (s.payment_intent as { id?: string })) stripePaymentIntentId = (s.payment_intent as { id?: string }).id
      else stripePaymentIntentId = String(s.payment_intent)
    }

    // Create order
    const order = await prisma.order.create({
      data: {
        orderNumber,
        status: 'COMPLETED',
  totalAmount: (s.amount_total ?? 0) / 100, // Convert from cents
  platformFee: platformFee / 100, // Convert from cents
        customerId: userId,
  stripePaymentIntentId: stripePaymentIntentId,
        items: {
          create: orderItems.map((item: StripeOrderItem) => ({
              designId: item.designId,
              quantity: item.quantity,
              price: item.price,
              purchaseType: item.purchaseType || 'REGULAR',
              // Store promotion data for tracking
              promotionId: item.promotionId || null,
              promotionType: item.promotionType || null,
              discountAmount: item.discountAmount || 0,
            }))
        }
      },
      include: {
        items: {
          include: {
            design: {
              include: {
                designer: true
              }
            }
          }
        }
      }
    })

    // Update design sales statistics, create seller earnings, and handle purchases
    for (const item of orderItems) {
      const saleAmount = item.price * item.quantity
      const sellerId = (item.designerId ?? '') as string
      
      // Get seller's current tier and calculate dynamic commission
      const seller = await prisma.user.findUnique({
        where: { id: sellerId },
        select: { totalEarnings: true, designerTier: true }
      })
      
      const totalEarnings = seller?.totalEarnings ?? 0
      const isProSubscriber = seller?.designerTier === 'VIP_DESIGNER' || seller?.designerTier === 'VVIP_DESIGNER'
      const commissionRate = getCommissionRate(totalEarnings, isProSubscriber)
      const tier = getCommissionTier(totalEarnings)
      
      const platformCommission = saleAmount * commissionRate
      const sellerEarning = saleAmount - platformCommission
      
      console.log(`[Stripe Tiered Commission] Seller ${sellerId}: Tier=${tier}, Rate=${(commissionRate * 100).toFixed(1)}%, Commission=$${platformCommission.toFixed(2)}`)

      // For ownership purchases, use atomic conditional update to prevent race conditions
      if (item.purchaseType === 'OWNERSHIP') {
        // Only set ownership if not already owned (atomic check)
        const updateResult = await prisma.design.updateMany({
          where: { 
            id: item.designId,
            isOwned: false // Atomic condition - only update if not already owned
          },
          data: {
            totalSales: { increment: item.quantity },
            totalRevenue: { increment: saleAmount },
            isOwned: true,
            ownedBy: userId,
            isActive: false
          }
        })
        
        if (updateResult.count === 0) {
          // Design was already owned - this shouldn't happen but log for debugging
          console.error(`Race condition detected: Design ${item.designId} was purchased for ownership but is already owned`)
          // Continue processing other items - the customer will need a refund for this item
          continue
        }
      } else {
        // Regular purchase - just update stats
        await prisma.design.update({
          where: { id: item.designId },
          data: {
            totalSales: { increment: item.quantity },
            totalRevenue: { increment: saleAmount }
          }
        })
      }

      // Create seller earning record
      await prisma.sellerEarning.create({
        data: {
          sellerId: sellerId,
          orderId: order.id,
          designId: item.designId,
          saleAmount: saleAmount,
          platformCommission: platformCommission,
          sellerAmount: sellerEarning,
          quantity: item.quantity
        }
      })

      // Send sale notification email to seller
      const sellerUser = await prisma.user.findUnique({
        where: { id: sellerId },
        select: { email: true, name: true, displayName: true }
      })
      
      if (sellerUser?.email) {
        sendSaleNotificationEmail(
          sellerUser.email,
          sellerUser.displayName || sellerUser.name || 'Designer',
          item.designTitle || 'Design',
          saleAmount,
          sellerEarning,
          item.purchaseType || 'REGULAR'
        ).catch(err => console.error('Failed to send sale notification:', err))
      }

      // Create purchase record for access control
      const purchase = await prisma.purchase.create({
        data: {
          userId: userId,
          designId: item.designId,
          orderId: order.id,
          purchaseType: item.purchaseType || 'REGULAR',
          purchasePrice: item.price,
          accessGranted: true
        }
      })

      // For OWNERSHIP purchases, create the ownership contract (with idempotency check)
      if (item.purchaseType === 'OWNERSHIP') {
        try {
          // Check if contract already exists (idempotency)
          const existingContract = await prisma.ownershipContract.findUnique({
            where: { purchaseId: purchase.id }
          })

          if (existingContract) {
            console.log(`[Ownership] Contract already exists for purchase ${purchase.id}, skipping creation`)
          } else {
            // Get the approved ownership document for this design
            const ownershipDoc = await prisma.ownershipDocument.findFirst({
              where: {
                designId: item.designId,
                status: 'APPROVED'
              },
              select: {
                id: true,
                sellerFullName: true,
                sellerSignature: true
              }
            })

            if (ownershipDoc) {
              // Get buyer info
              const buyer = await prisma.user.findUnique({
                where: { id: userId },
                select: {
                  name: true,
                  displayName: true
                }
              })

              // Create the ownership contract
              await createOwnershipContract(
                purchase.id,
                userId,
                sellerId,
                buyer?.name || 'Buyer',
                buyer?.displayName || undefined,
                buyer?.name || 'Buyer',
                item.designId,
                item.designTitle || 'Design',
                ownershipDoc.id,
                ownershipDoc.sellerFullName,
                ownershipDoc.sellerSignature
              )

              // FLAW FIX #14: Validate ownership state after contract creation
              try {
                const validation = await validateDesignOwnershipState(item.designId)
                if (!validation.isValid) {
                  console.error(
                    `[Ownership] CRITICAL: State validation failed for design ${item.designId}: ${validation.error}`,
                    { validation }
                  )
                  // Alert admin but don't block the transaction
                  try {
                    await sendEmail({
                      to: process.env.ADMIN_EMAIL || 'admin@example.com',
                      subject: 'CRITICAL: Design Ownership State Inconsistency',
                      html: `
                        <h2>Design Ownership State Validation Failed</h2>
                        <p>Design ID: ${item.designId}</p>
                        <p>Validation Error: ${validation.error}</p>
                        <p>Active Contracts: ${validation.activeContracts}</p>
                        <p>Design isOwned: ${validation.actualOwned}</p>
                        <p>Please investigate immediately and run repair script if needed.</p>
                      `
                    })
                  } catch (emailErr) {
                    console.error('Failed to send state validation alert email', emailErr)
                  }
                }
              } catch (validationErr) {
                console.error(
                  `[Ownership] Error validating design state after contract creation:`,
                  validationErr
                )
              }

              console.log(`[Ownership] Contract created for purchase ${purchase.id}`)
            } else {
              console.warn(`[Ownership] No approved document found for design ${item.designId}`)
            }
          }
        } catch (contractError) {
          console.error(`[Ownership] Failed to create ownership contract:`, contractError)
          // Don't fail the payment - ownership contract creation is async
        }
      }
      
      // Store previous earnings before updating (for tier change detection)
      const previousEarnings = totalEarnings
      
      // Update seller's total earnings
      await prisma.user.update({
        where: { id: sellerId },
        data: {
          totalEarnings: { increment: sellerEarning },
          totalSales: { increment: item.quantity }
        }
      })
      
      // Check if seller crossed a tier threshold (for future Paystack payments)
      const tierResult = await checkAndUpdateSellerTier(sellerId, previousEarnings)
      if (tierResult.tierChanged) {
        console.log(`[Stripe Tier Change] ${tierResult.message}`)
      }
    }

    // Clear user's cart - need to account for purchase type
    for (const item of orderItems) {
      await prisma.cartItem.deleteMany({
        where: {
          userId,
          designId: item.designId,
          purchaseType: item.purchaseType || 'REGULAR'
        }
      })
    }

    // Handle POD fulfillment if this order has POD items
    const podItems = orderItems.filter((item: StripeOrderItem) => item.purchaseType === 'POD')
    if (podItems.length > 0) {
      // Parse shipping address from metadata
      let rawShippingAddress: {
        fullName?: string
        name?: string
        address?: string
        address1?: string
        address2?: string
        city: string
        state?: string
        country: string
        postalCode?: string
        zip?: string
        phone?: string
      } | undefined
      
      try {
        if (s?.metadata?.shippingAddress) {
          rawShippingAddress = JSON.parse(s.metadata.shippingAddress)
        }
      } catch (e) {
        console.error('[POD] Failed to parse shipping address:', e)
      }

      if (rawShippingAddress) {
        // Normalize shipping address fields (checkout sends different field names)
        const shippingAddress = {
          name: rawShippingAddress.fullName || rawShippingAddress.name || '',
          address1: rawShippingAddress.address || rawShippingAddress.address1 || '',
          address2: rawShippingAddress.address2 || '',
          city: rawShippingAddress.city,
          state: rawShippingAddress.state,
          country: rawShippingAddress.country,
          zip: rawShippingAddress.postalCode || rawShippingAddress.zip || '',
          phone: rawShippingAddress.phone
        }
        
        console.log(`[POD] Fulfilling ${podItems.length} POD items for order ${order.id}`)
        
        // Get design image URLs for POD fulfillment
        const podFulfillmentItems = await Promise.all(
          podItems.map(async (item: StripeOrderItem) => {
            const design = await prisma.design.findUnique({
              where: { id: item.designId },
              select: { imageUrl: true }
            })
            return {
              productId: item.podProductId || '',
              variantId: item.podVariantId || '',
              quantity: item.quantity,
              designImageUrl: design?.imageUrl || ''
            }
          })
        )

        const fulfillResult = await fulfillPODOrder(order.id, podFulfillmentItems, shippingAddress)
        
        if (fulfillResult.success) {
          // Update order with POD provider info
          await prisma.order.update({
            where: { id: order.id },
            data: {
              orderType: 'POD',
              podProvider: fulfillResult.provider,
              podOrderId: fulfillResult.podOrderId,
              podStatus: 'pending',
              shippingName: shippingAddress.name,
              shippingAddress1: shippingAddress.address1,
              shippingAddress2: shippingAddress.address2,
              shippingCity: shippingAddress.city,
              shippingState: shippingAddress.state,
              shippingCountry: shippingAddress.country,
              shippingZip: shippingAddress.zip,
              shippingPhone: shippingAddress.phone
            }
          })
          console.log(`[POD] Order fulfilled via ${fulfillResult.provider}: ${fulfillResult.podOrderId}`)
        } else {
          console.error(`[POD] Fulfillment failed for order ${order.id}:`, fulfillResult.error)
          
          // Update order status to indicate POD failure
          await prisma.order.update({
            where: { id: order.id },
            data: {
              orderType: 'POD',
              podStatus: 'fulfillment_failed',
            }
          })
          
          // Alert admin about POD fulfillment failure
          const alertSent = await sendAdminPODAlert({
            orderNumber: orderNumber,
            orderId: order.id,
            status: 'fulfillment_failed',
            provider: 'Unknown',
            reason: fulfillResult.error || 'POD provider order creation failed',
            customerEmail: undefined,
            totalAmount: (s.amount_total ?? 0) / 100
          })
          
          // Queue for retry if alert failed
          if (!alertSent) {
            await queueFailedNotification('email', {
              emailType: 'admin_alert',
              orderId: orderNumber,
              reason: fulfillResult.error || 'POD fulfillment failed',
              to: process.env.ADMIN_EMAIL || '',
            }, 'Admin alert failed to send')
          }
        }
      } else {
        console.error(`[POD] Missing shipping address for POD order ${order.id}`)
      }
    }

    // Check if any designers should be auto-promoted to SELLER role    // Get array of promotion IDs that were used in this order
    const promotionIds = orderItems
      .filter(item => item.promotionId)
      .map(item => item.promotionId as string)
    
    // Increment promotion usage if any were applied
    if (promotionIds.length > 0) {
      const uniquePromotionIds = [...new Set(promotionIds)]
      for (const promotionId of uniquePromotionIds) {
        await prisma.promotion.update({
          where: { id: promotionId },
          data: { usageCount: { increment: 1 } }
        }).catch(err => console.error(`[Stripe] Failed to increment promotion ${promotionId}:`, err))
      }
      console.log(`[Stripe] Incremented usage for ${uniquePromotionIds.length} promotions`)
    }
    const designerIds = orderItems
      .map((item: StripeOrderItem) => item.designerId)
      .filter((id): id is string => !!id)
    
    if (designerIds.length > 0) {
      await checkAndPromoteDesigners(designerIds)
    }

    console.log(`Order ${orderNumber} created successfully`)
  } catch (error) {
    void error
    console.error('Error handling checkout completion:', error)
  }
}

async function handlePaymentSucceeded(paymentIntent: unknown) {
  const pi = paymentIntent as StripePaymentIntent
  try {
    // Update order status if needed
    await prisma.order.updateMany({
      where: {
        stripePaymentIntentId: pi.id
      },
      data: {
        status: 'COMPLETED'
      }
    })

    console.log(`Payment ${pi.id} succeeded`)
  } catch (error) {
    void error
    console.error('Error handling payment success:', error)
  }
}

/**
 * Handle commission payment completion via Stripe
 */
async function handleCommissionPaymentCompleted(session: StripeCheckoutSession) {
  try {
    const metadata = session.metadata
    if (!metadata) {
      console.error('Commission payment missing metadata')
      return
    }

    const { commissionRequestId, platformFee, designerEarnings, quotedCommissionRate, quotedDesignerTier } = metadata
    
    if (!commissionRequestId) {
      console.error('Commission payment missing commissionRequestId')
      return
    }

    // Determine payment intent ID - use as unique key for idempotency
    let paymentIntentId: string | undefined = undefined
    if (session.payment_intent) {
      if (typeof session.payment_intent === 'string') {
        paymentIntentId = session.payment_intent
      } else if (typeof session.payment_intent === 'object' && 'id' in (session.payment_intent as { id?: string })) {
        paymentIntentId = (session.payment_intent as { id?: string }).id
      }
    }

    if (!paymentIntentId) {
      console.error('Commission payment missing payment intent ID')
      return
    }

    // CRITICAL: Use payment intent ID as unique constraint to prevent duplicate payments
    // This ensures only ONE webhook can succeed for a given payment
    const updateResult = await prisma.commissionRequest.updateMany({
      where: {
        id: commissionRequestId,
        isPaid: false, // Only update if not already paid
        stripePaymentIntentId: null, // Only update if payment intent not yet recorded
      },
      data: {
        status: 'PAID',
        isPaid: true,
        paidAt: new Date(),
        platformFee: parseFloat(platformFee || '0'),
        designerEarnings: parseFloat(designerEarnings || '0'),
        paymentMethod: 'STRIPE',
        paymentReference: paymentIntentId,
        stripePaymentIntentId: paymentIntentId, // Lock this payment intent
      },
    })

    if (updateResult.count === 0) {
      // Payment was already processed or invalid state
      console.log(`Commission ${commissionRequestId} already processed or invalid state, skipping`)
      return
    }

    console.log(`Commission ${commissionRequestId} marked as PAID via Stripe (intent: ${paymentIntentId})`)

    // Fetch updated request for email notification
    const updatedRequest = await prisma.commissionRequest.findUnique({
      where: { id: commissionRequestId },
      include: {
        requester: {
          select: { name: true, displayName: true },
        },
        designer: {
          select: { email: true, name: true, displayName: true },
        },
      },
    })

    // Send email notification to designer
    if (updatedRequest?.designer?.email) {
      const requesterName = updatedRequest.requester?.displayName || 
                           updatedRequest.requester?.name || 
                           'Client'
      
      try {
        await sendPaymentReceivedToDesigner({
          designerEmail: updatedRequest.designer.email,
          designerName: updatedRequest.designer.displayName || updatedRequest.designer.name || 'Designer',
          requesterName,
          title: updatedRequest.title,
          amount: updatedRequest.designerQuote || 0,
          designerEarnings: parseFloat(designerEarnings || '0'),
          commissionId: commissionRequestId,
        })
        console.log(`Payment notification email sent to designer ${updatedRequest.designer.email}`)
      } catch (emailError) {
        console.error('Failed to send payment notification email:', emailError)
      }
    }

  } catch (error) {
    console.error('Error handling commission payment completion:', error)
  }
}

/**
 * Handle Stripe refunds for commission payments
 * When a buyer requests a refund, we need to update the commission request status
 */
async function handleChargeRefunded(charge: unknown) {
  try {
    const c = charge as { id?: string; payment_intent?: string | { id?: string } }
    if (!c?.id) {
      console.error('Refund event missing charge ID')
      return
    }

    // Extract payment intent ID
    let paymentIntentId: string | undefined
    if (c.payment_intent) {
      if (typeof c.payment_intent === 'string') {
        paymentIntentId = c.payment_intent
      } else if (typeof c.payment_intent === 'object' && 'id' in (c.payment_intent as { id?: string })) {
        paymentIntentId = (c.payment_intent as { id?: string }).id
      }
    }

    if (!paymentIntentId) {
      console.error('Refund event missing payment intent ID')
      return
    }

    // Find the commission request by payment intent
    const commissionRequest = await prisma.commissionRequest.findFirst({
      where: {
        stripePaymentIntentId: paymentIntentId,
      },
      include: {
        requester: { select: { email: true, name: true, displayName: true } },
        designer: { select: { email: true, name: true, displayName: true } },
      },
    })

    if (!commissionRequest) {
      console.warn(`Refund for unknown payment intent: ${paymentIntentId}`)
      return
    }

    // Update commission request to REFUNDED status
    const _updatedRequest = await prisma.commissionRequest.update({
      where: { id: commissionRequest.id },
      data: {
        status: 'REFUNDED',
        isPaid: false, // Mark as no longer paid
        platformFee: 0,
        designerEarnings: 0,
      },
    })

    console.log(`Commission ${commissionRequest.id} marked as REFUNDED via Stripe (charge: ${c.id})`)

    // Notify designer about refund
    if (commissionRequest.designer?.email) {
      try {
        await sendPaymentReceivedToDesigner({
          designerEmail: commissionRequest.designer.email,
          designerName: commissionRequest.designer.displayName || commissionRequest.designer.name || 'Designer',
          requesterName: commissionRequest.requester?.displayName || commissionRequest.requester?.name || 'Client',
          title: commissionRequest.title,
          amount: 0,
          designerEarnings: 0,
          commissionId: commissionRequest.id,
        })
        console.log(`Refund notification sent to designer ${commissionRequest.designer.email}`)
      } catch (emailError) {
        console.error('Failed to send refund notification:', emailError)
      }
    }

    // Notify requester (buyer)
    if (commissionRequest.requester?.email) {
      console.log(`Refund processed for requester ${commissionRequest.requester.email}`)
    }
  } catch (error) {
    console.error('Error handling charge refunded:', error)
  }
}

/**
 * Handle Pro subscription creation
 */
async function handleSubscriptionCreated(subscription: unknown, stripe: ReturnType<typeof getStripe>) {
  try {
    const sub = subscription as {
      id?: string
      customer?: string
      metadata?: { userId?: string; billingPeriod?: string; tier?: string }
      current_period_end?: number
    }

    if (!sub.id || !sub.customer) {
      console.log('[Pro Subscription] Missing subscription or customer ID')
      return
    }

    const userId = sub.metadata?.userId
    if (!userId) {
      console.log('[Pro Subscription] Missing userId in metadata')
      return
    }

    const billingPeriod = sub.metadata?.billingPeriod === 'YEARLY' ? 'YEARLY' : 'MONTHLY'
    const tier = sub.metadata?.tier || 'PRO' // Default to PRO if not specified
    const expiresAt = sub.current_period_end ? new Date(sub.current_period_end * 1000) : new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)

    // Check if already activated (idempotency)
    const existing = await prisma.proSubscription.findUnique({
      where: { userId }
    }).catch(() => null)
    
    if (existing?.status === 'ACTIVE') {
      console.log(`[Pro Subscription] Already activated for user ${userId}, skipping`)
      return
    }

    // Activate Pro subscription
    const result = await activateProSubscription(
      userId,
      billingPeriod,
      0, // Amount will be set by webhook
      sub.id
    )

    if (result.success) {
      console.log(`[Pro Subscription] Activated for user ${userId} via Stripe: ${sub.id} (tier: ${tier})`)
      
      // Update user's subscription tier
      await prisma.user.update({
        where: { id: userId },
        data: {
          subscriptionTier: tier,
          subscriptionPrice: tier === 'STARTER' ? 4.99 : tier === 'VIP' ? 14.99 : 9.99,
          billingCycle: billingPeriod
        }
      }).catch(() => null)
      
      // Retrieve customer email for logging
      try {
        const customer = await stripe.customers.retrieve(sub.customer as string)
        if ('email' in customer && customer.email) {
          console.log(`[Pro Subscription] Customer email: ${customer.email}`)
          
          // Send confirmation email
          const seller = await prisma.user.findUnique({
            where: { id: userId },
            select: { email: true, displayName: true, name: true }
          })
          
          if (seller?.email) {
            try {
              const sellerName = seller.displayName || seller.name || 'Seller'
              const expiresDate = new Date(expiresAt).toLocaleDateString()
              
              // Get tier benefits
              let tierBenefits = ''
              if (tier === 'STARTER') {
                tierBenefits = '<li>1% commission discount on all sales</li>'
              } else if (tier === 'PRO') {
                tierBenefits = '<li>+1 tier boost above your natural tier</li><li>6 featured listings</li><li>1% commission discount on all sales</li>'
              } else if (tier === 'VIP') {
                tierBenefits = '<li>+1 tier boost above your natural tier</li><li>10 featured listings</li><li>2% commission discount on all sales</li><li>Priority support</li>'
              }
              
              await sendEmail({
                to: seller.email,
                subject: `${tier} Subscription Activated`,
                html: `
                  <h2>Welcome to ${tier} Subscription!</h2>
                  <p>Hi ${sellerName},</p>
                  <p>Your ${tier} subscription has been successfully activated!</p>
                  <p><strong>Plan:</strong> ${billingPeriod === 'YEARLY' ? 'Yearly' : 'Monthly'}</p>
                  <p><strong>Expires:</strong> ${expiresDate}</p>
                  <p><strong>Benefits:</strong></p>
                  <ul>
                    ${tierBenefits}
                  </ul>
                  <p>Thank you for upgrading!</p>
                `
              })
              console.log(`${tier} subscription confirmation sent to ${seller.email}`)
            } catch (emailError) {
              console.error('Failed to send Stripe subscription confirmation email:', emailError)
            }
          }
        }
      } catch (customerError) {
        console.error('[Pro Subscription] Error retrieving customer:', customerError)
      }
    } else {
      console.error(`[Pro Subscription] Failed to activate: ${result.message}`)
    }
  } catch (error) {
    console.error('[Pro Subscription] Error handling subscription created:', error)
  }
}

/**
 * Handle Pro subscription updates (e.g., billing period changed)
 */
async function handleSubscriptionUpdated(subscription: unknown) {
  try {
    const sub = subscription as {
      id?: string
      customer?: string
      metadata?: { userId?: string }
      current_period_end?: number
      status?: string
    }

    if (!sub.id) return

    const userId = sub.metadata?.userId
    if (!userId) return

    // Update expiration if period end changed
    if (sub.current_period_end) {
      await prisma.proSubscription.update({
        where: { userId },
        data: {
          expiresAt: new Date(sub.current_period_end * 1000),
          status: sub.status === 'active' ? 'ACTIVE' : sub.status === 'canceled' ? 'CANCELLED' : 'EXPIRED'
        }
      })
      console.log(`[Pro Subscription] Updated for user ${userId}`)
    }
  } catch (error) {
    console.error('[Pro Subscription] Error handling subscription updated:', error)
  }
}

/**
 * Handle Pro subscription cancellation
 */
async function handleSubscriptionDeleted(subscription: unknown) {
  try {
    const sub = subscription as {
      metadata?: { userId?: string }
    }

    const userId = sub.metadata?.userId
    if (!userId) return

    // Mark subscription as cancelled
    await prisma.proSubscription.update({
      where: { userId },
      data: {
        status: 'CANCELLED',
        cancelledAt: new Date()
      }
    })

    // Deactivate Pro subscription in user
    await prisma.user.update({
      where: { id: userId },
      data: { proSubscriptionActive: false }
    })

    console.log(`[Pro Subscription] Cancelled for user ${userId}`)
  } catch (error) {
    console.error('[Pro Subscription] Error handling subscription deleted:', error)
  }
}

/**
 * Handle recurring invoice payment success (monthly/yearly renewals)
 */
async function handleInvoicePaymentSucceeded(invoice: unknown) {
  try {
    const inv = invoice as {
      subscription?: string
      metadata?: { userId?: string; type?: string }
    }

    if (inv.metadata?.type !== 'pro_subscription') return

    const userId = inv.metadata?.userId
    if (!userId) return

    // Mark renewal in subscription record
    const sub = await prisma.proSubscription.findUnique({
      where: { userId }
    })

    if (sub) {
      console.log(`[Pro Subscription] Renewal payment received for user ${userId}`)
      // Subscription is already active, just log the renewal
    }
  } catch (error) {
    console.error('[Pro Subscription] Error handling invoice payment:', error)
  }
}

'use client'

import { useState, useEffect, Suspense } from 'react'
import { useSearchParams, useRouter } from 'next/navigation'
import Link from 'next/link'
import { CheckCircle, AlertCircle, Loader2, Mail, RefreshCw } from 'lucide-react'

function VerifyEmailContent() {
  const searchParams = useSearchParams()
  const router = useRouter()
  const token = searchParams.get('token')

  const [status, setStatus] = useState<'loading' | 'success' | 'error' | 'no-token'>('loading')
  const [message, setMessage] = useState('')
  const [resending, setResending] = useState(false)
  const [resendSuccess, setResendSuccess] = useState(false)

  useEffect(() => {
    if (!token) {
      setStatus('no-token')
      return
    }

    verifyEmail()
  }, [token])

  const verifyEmail = async () => {
    try {
      const response = await fetch('/api/auth/verify-email', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token }),
      })

      const data = await response.json()

      if (response.ok) {
        setStatus('success')
        setMessage(data.message || 'Your email has been verified successfully!')
        // Redirect to signin after 3 seconds
        setTimeout(() => {
          router.push('/auth/signin')
        }, 3000)
      } else {
        setStatus('error')
        setMessage(data.message || 'Failed to verify email')
      }
    } catch {
      setStatus('error')
      setMessage('An error occurred while verifying your email')
    }
  }

  const handleResendVerification = async () => {
    setResending(true)
    setResendSuccess(false)

    try {
      const response = await fetch('/api/auth/send-verification', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      })

      if (response.ok) {
        setResendSuccess(true)
      }
    } catch {
      // Silent fail - user can try again
    } finally {
      setResending(false)
    }
  }

  if (status === 'loading') {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center py-12 px-4 sm:px-6 lg:px-8">
        <div className="max-w-md w-full space-y-8 text-center">
          <div className="mx-auto w-16 h-16 bg-indigo-100 rounded-full flex items-center justify-center">
            <Loader2 className="w-8 h-8 text-indigo-600 animate-spin" />
          </div>
          <h2 className="text-2xl font-bold text-gray-900">Verifying your email...</h2>
          <p className="text-sm text-gray-600">Please wait while we verify your email address.</p>
        </div>
      </div>
    )
  }

  if (status === 'success') {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center py-12 px-4 sm:px-6 lg:px-8">
        <div className="max-w-md w-full space-y-8">
          <div className="text-center">
            <div className="mx-auto w-16 h-16 bg-green-100 rounded-full flex items-center justify-center">
              <CheckCircle className="w-8 h-8 text-green-600" />
            </div>
            <h2 className="mt-6 text-3xl font-bold text-gray-900">Email Verified!</h2>
            <p className="mt-2 text-sm text-gray-600">{message}</p>
            <p className="mt-2 text-sm text-gray-500">Redirecting you to sign in...</p>
          </div>

          <Link
            href="/auth/signin"
            className="w-full flex justify-center py-2 px-4 border border-transparent rounded-lg shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700"
          >
            Continue to Sign In
          </Link>
        </div>
      </div>
    )
  }

  if (status === 'no-token') {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center py-12 px-4 sm:px-6 lg:px-8">
        <div className="max-w-md w-full space-y-8">
          <div className="text-center">
            <div className="mx-auto w-16 h-16 bg-yellow-100 rounded-full flex items-center justify-center">
              <Mail className="w-8 h-8 text-yellow-600" />
            </div>
            <h2 className="mt-6 text-3xl font-bold text-gray-900">Verify Your Email</h2>
            <p className="mt-2 text-sm text-gray-600">
              Please check your email for a verification link, or request a new one below.
            </p>
          </div>

          {resendSuccess && (
            <div className="bg-green-50 border border-green-200 rounded-lg p-4 flex items-start gap-3">
              <CheckCircle className="w-5 h-5 text-green-500 flex-shrink-0 mt-0.5" />
              <p className="text-sm text-green-700">
                Verification email sent! Please check your inbox.
              </p>
            </div>
          )}

          <div className="space-y-3">
            <button
              onClick={handleResendVerification}
              disabled={resending}
              className="w-full flex justify-center items-center py-2 px-4 border border-gray-300 rounded-lg shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 disabled:opacity-50"
            >
              {resending ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Sending...
                </>
              ) : (
                <>
                  <RefreshCw className="w-4 h-4 mr-2" />
                  Resend Verification Email
                </>
              )}
            </button>
            <Link
              href="/auth/signin"
              className="w-full flex justify-center py-2 px-4 border border-transparent rounded-lg shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700"
            >
              Back to Sign In
            </Link>
          </div>
        </div>
      </div>
    )
  }

  // Error state
  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-md w-full space-y-8">
        <div className="text-center">
          <div className="mx-auto w-16 h-16 bg-red-100 rounded-full flex items-center justify-center">
            <AlertCircle className="w-8 h-8 text-red-600" />
          </div>
          <h2 className="mt-6 text-3xl font-bold text-gray-900">Verification Failed</h2>
          <p className="mt-2 text-sm text-gray-600">{message}</p>
        </div>

        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
          <p className="text-sm text-yellow-700">
            <strong>Common reasons:</strong>
            <br />
            ΓÇó The link has expired (valid for 24 hours)
            <br />
            ΓÇó The link has already been used
            <br />
            ΓÇó The link was copied incorrectly
          </p>
        </div>

        {resendSuccess && (
          <div className="bg-green-50 border border-green-200 rounded-lg p-4 flex items-start gap-3">
            <CheckCircle className="w-5 h-5 text-green-500 flex-shrink-0 mt-0.5" />
            <p className="text-sm text-green-700">
              New verification email sent! Please check your inbox.
            </p>
          </div>
        )}

        <div className="space-y-3">
          <button
            onClick={handleResendVerification}
            disabled={resending}
            className="w-full flex justify-center items-center py-2 px-4 border border-gray-300 rounded-lg shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 disabled:opacity-50"
          >
            {resending ? (
              <>
                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                Sending...
              </>
            ) : (
              <>
                <RefreshCw className="w-4 h-4 mr-2" />
                Request New Verification Email
              </>
            )}
          </button>
          <Link
            href="/auth/signin"
            className="w-full flex justify-center py-2 px-4 border border-transparent rounded-lg shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700"
          >
            Back to Sign In
          </Link>
        </div>
      </div>
    </div>
  )
}

export default function VerifyEmailPage() {
  return (
    <Suspense fallback={
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-indigo-600" />
      </div>
    }>
      <VerifyEmailContent />
    </Suspense>
  )
}

'use client';

import { useState, useEffect } from 'react';
import { useSession } from 'next-auth/react';
import { useRouter, useParams } from 'next/navigation';
import Image from 'next/image';
import Link from 'next/link';
import toast from 'react-hot-toast';
import {
  Star,
  Heart,
  Share2,
  ShoppingCart,
  Truck,
  Shield,
  RefreshCw,
  ChevronLeft,
  ChevronRight,
  Check,
  Minus,
  Plus,
  Play,
  User,
  MessageSquare,
