interface Media {
  id: string;
  url: string;
  type: 'IMAGE' | 'VIDEO';
  isPrimary: boolean;
}

interface Variant {
  id: string;
  size: string;
  color: string;
  colorHex: string;
  quantity: number;
  priceAdjustment: number;
}

interface Review {
  id: string;
  rating: number;
  title: string;
  comment: string;
  fitFeedback: string;
  user: { name: string; image: string };
  createdAt: string;
}

interface Product {
  id: string;
  title: string;
  slug: string;
  description: string;
  basePrice: number;
  salePrice: number | null;
  brand: string;
  material: string;
  careInstructions: string;
  condition: string;
  gender: string;
  style: string;
  occasion: string;
  tags: string[];
  category: { name: string; slug: string };
  thumbnailUrl: string;
  media: Media[];
  variants: Variant[];
  seller: { id: string; name: string; image: string };
  avgRating: number | null;
  reviewCount: number;
  favoriteCount: number;
  reviews: Review[];
}

interface RelatedProduct {
  id: string;
  title: string;
  slug: string;
  basePrice: number;
  salePrice: number | null;
  thumbnailUrl: string;
}

export default function ProductDetailPage() {
  const { data: session } = useSession();
  const router = useRouter();
  const params = useParams();
  const slug = params.slug as string;

  const [loading, setLoading] = useState(true);
  const [product, setProduct] = useState<Product | null>(null);
  const [relatedProducts, setRelatedProducts] = useState<RelatedProduct[]>([]);
  const [selectedMedia, setSelectedMedia] = useState(0);
  const [selectedSize, setSelectedSize] = useState('');
  const [selectedColor, setSelectedColor] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [addingToCart, setAddingToCart] = useState(false);
  const [isFavorite, setIsFavorite] = useState(false);
  const [isFeatured, setIsFeatured] = useState(false);
  const [featuringProduct, setFeaturingProduct] = useState(false);
  const [showReviewForm, setShowReviewForm] = useState(false);
  const [submitReviewLoading, setSubmitReviewLoading] = useState(false);
  const [reviewRating, setReviewRating] = useState(5);
  const [reviewTitle, setReviewTitle] = useState('');
  const [reviewComment, setReviewComment] = useState('');
  const [reviewFit, setReviewFit] = useState<'RUNS_SMALL' | 'TRUE_TO_SIZE' | 'RUNS_LARGE' | ''>('');
  const [userReview, setUserReview] = useState<any>(null);
  const [editingReview, setEditingReview] = useState(false);
  const [deleteConfirm, setDeleteConfirm] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (slug) {
      fetchProduct();
    }
  }, [slug]);

  useEffect(() => {
    if (product && session?.user?.id) {
      fetchUserReview();
    }
  }, [product?.id, session?.user?.id]);

  const fetchUserReview = async () => {
    if (!product) return;
    try {
      const response = await fetch(`/api/boutique/reviews?productId=${product.id}`);
      if (response.ok) {
        const data = await response.json();
        if (data.userReview) {
          setUserReview(data.userReview);
          setReviewRating(data.userReview.rating);
          setReviewTitle(data.userReview.title || '');
          setReviewComment(data.userReview.comment || '');
          setReviewFit(data.userReview.fitRating || '');
        }
      }
    } catch (error) {
      console.error('Failed to fetch user review:', error);
    }
  };

  const fetchProduct = async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await fetch(`/api/boutique/shop/${slug}`);
      
      if (!response.ok) {
        if (response.status === 404) {
          setError('This product is no longer available for purchase.');
        } else {
          setError('Failed to load product details. Please try again later.');
        }
        return;
      }
      
      const data = await response.json();
      console.log('Product data:', data);

      if (data.success && data.product) {
        setProduct(data.product);
        setRelatedProducts(data.relatedProducts || []);
        
        // Set default selections
        const sizes = [...new Set(data.product.variants.map((v: Variant) => v.size).filter(Boolean))];
        const colors = [...new Set(data.product.variants.map((v: Variant) => v.color).filter(Boolean))];
        if (sizes.length > 0) setSelectedSize(sizes[0] as string);
        if (colors.length > 0) setSelectedColor(colors[0] as string);
      } else {
        setError('Failed to load product details. Please try again later.');
      }
    } catch (error) {
      console.error('Failed to fetch product:', error);
      setError('Failed to load product details. Please try again later.');
    } finally {
      setLoading(false);
    }
  };

  const getAvailableVariant = () => {
    if (!product) return null;
    return product.variants.find(v => 
      (!selectedSize || v.size === selectedSize) && 
      (!selectedColor || v.color === selectedColor) &&
      v.quantity > 0
    );
  };

  const getPrice = () => {
    if (!product) return 0;
    const variant = getAvailableVariant();
    const basePrice = product.salePrice || product.basePrice;
    const adjustment = variant?.priceAdjustment || 0;
    return basePrice + adjustment;
  };

  const getMaxQuantity = () => {
    const variant = getAvailableVariant();
    return variant?.quantity || 0;
  };

  const addToCart = async () => {
    if (!session) {
      router.push('/auth/signin');
      return;
    }

    const variant = getAvailableVariant();
    if (!variant) return;

    setAddingToCart(true);
    try {
      const response = await fetch('/api/boutique/cart', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          productId: product!.id,
          variantId: variant.id,
          quantity,
        }),
      });

      const data = await response.json();
      if (data.success) {
        toast.success('Added to cart!');
        setQuantity(1);
      } else {
        toast.error(data.message || 'Failed to add to cart');
      }
    } catch (error) {
      console.error('Failed to add to cart:', error);
      toast.error('Failed to add to cart');
    } finally {
      setAddingToCart(false);
    }
  };

  const toggleFavorite = async () => {
    if (!session) {
      router.push('/auth/signin');
      return;
    }
    // Toggle favorite using API
    try {
      if (!product) {
        toast.error('Product not found');
        return;
      }
      const method = isFavorite ? 'DELETE' : 'POST';
      const res = await fetch(`/api/boutique/favorites?productId=${product.id}`, {
        method,
        headers: { 'Content-Type': 'application/json' },
      });
      
      if (!res.ok) throw new Error('Failed to update favorite');
      setIsFavorite(!isFavorite);
      toast.success(isFavorite ? 'Removed from favorites' : 'Added to favorites');
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Failed to update favorite');
    }
  };

  const toggleFeatured = async () => {
    if (!session?.user?.id) {
      router.push('/auth/signin');
      return;
    }
    if (!product || session.user.id !== product.seller.id) {
      toast.error('Only the seller can feature this product');
      return;
    }

    setFeaturingProduct(true);
    try {
      if (isFeatured) {
        // DELETE - pass productId as query param
        const response = await fetch(`/api/seller/featured-boutique-products?productId=${product.id}`, {
          method: 'DELETE'
        });

        if (response.ok) {
          setIsFeatured(false);
          toast.success('Removed from featured');
        } else {
          const error = await response.json();
          toast.error(error.error || 'Failed to remove from featured');
        }
      } else {
        // POST - pass productId in body
        const response = await fetch('/api/seller/featured-boutique-products', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ productId: product.id }),
        });

        if (response.ok) {
          setIsFeatured(true);
          toast.success('Added to featured items!');
        } else {
          const error = await response.json();
          toast.error(error.error || 'Failed to add to featured');
        }
      }
    } catch (error) {
      console.error('Failed to toggle featured:', error);
      toast.error('Failed to update featured status');
    } finally {
      setFeaturingProduct(false);
    }
  };

  const submitReview = async () => {
    if (!session) {
      router.push('/auth/signin');
      return;
    }

    if (!reviewRating || !reviewComment.trim()) {
      toast.error('Please provide a rating and comment');
      return;
    }

    try {
      setSubmitReviewLoading(true);
      const method = userReview ? 'PATCH' : 'POST';
      const url = userReview 
        ? `/api/boutique/reviews/${userReview.id}`
        : '/api/boutique/reviews';

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          productId: product!.id,
          rating: reviewRating,
          title: reviewTitle.trim(),
          comment: reviewComment.trim(),
          fitRating: reviewFit || null,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        toast.error(data.error || 'Failed to submit review');
        return;
      }

      toast.success(userReview ? 'Review updated successfully!' : 'Review submitted successfully!');
      setUserReview(data);
      setShowReviewForm(false);
      setEditingReview(false);
      
      // Refresh product data
      fetchProduct();
    } catch (error) {
      console.error('Failed to submit review:', error);
      toast.error('Failed to submit review');
    } finally {
      setSubmitReviewLoading(false);
    }
  };

  const deleteReview = async () => {
    if (!userReview) return;

    try {
      setSubmitReviewLoading(true);
      const response = await fetch(`/api/boutique/reviews/${userReview.id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        const data = await response.json();
        toast.error(data.error || 'Failed to delete review');
        return;
      }

      toast.success('Review deleted successfully');
      setUserReview(null);
      setDeleteConfirm(false);
      setReviewRating(5);
      setReviewTitle('');
      setReviewComment('');
      setReviewFit('');
      
      // Refresh product data
      fetchProduct();
    } catch (error) {
      console.error('Failed to delete review:', error);
      toast.error('Failed to delete review');
    } finally {
      setSubmitReviewLoading(false);
    }
  };


  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600"></div>
      </div>
    );
  }

  if (!product) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center gap-4">
        <p className="text-gray-600">Product not found</p>
        <Link href="/boutique" className="text-purple-600 hover:text-purple-700">
          Back to Boutique
        </Link>
      </div>
    );
  }

  const availableSizes = [...new Set(product.variants.map(v => v.size).filter(Boolean))];
  const availableColors = [...new Set(product.variants.map(v => ({ color: v.color, hex: v.colorHex })).filter(c => c.color))];
  const images = product.media.filter(m => m.type === 'IMAGE');
  const videos = product.media.filter(m => m.type === 'VIDEO');
  const allMedia = [...images, ...videos];
  const variant = getAvailableVariant();
  const isInStock = variant && variant.quantity > 0;

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Breadcrumb */}
      <div className="bg-white border-b">
        <div className="max-w-7xl mx-auto px-3 sm:px-4 py-1.5 sm:py-3">
          <nav className="flex items-center gap-1.5 sm:gap-2 text-[9px] sm:text-sm text-black">
            <Link href="/boutique" className="hover:text-purple-600">Boutique</Link>
            <span>/</span>
            <Link href={`/boutique?category=${product.category.slug}`} className="hover:text-purple-600">
              {product.category.name}
            </Link>
            <span>/</span>
            <span className="text-black truncate">{product.title}</span>
          </nav>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-3 sm:px-4 py-4 sm:py-8">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 sm:gap-8">
          {/* Media Gallery */}
          <div>
            {/* Main Image */}
            <div className="relative aspect-[3/4] bg-gray-100 rounded-xl sm:rounded-2xl overflow-hidden mb-2 sm:mb-4">
              {allMedia[selectedMedia]?.type === 'VIDEO' ? (
                <video
                  src={allMedia[selectedMedia]?.url}
                  controls
                  className="w-full h-full object-contain"
                />
              ) : allMedia[selectedMedia]?.url ? (
                <Image
                  src={allMedia[selectedMedia].url}
                  alt={product.title}
                  fill
                  className="object-contain"
                />
              ) : product.thumbnailUrl ? (
                <Image
                  src={product.thumbnailUrl}
                  alt={product.title}
                  fill
                  className="object-contain"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-gray-400">
                  No image available
                </div>
              )}

              {/* Navigation Arrows */}
              {allMedia.length > 1 && (
                <>
                  <button
                    onClick={() => setSelectedMedia(i => (i - 1 + allMedia.length) % allMedia.length)}
                    className="absolute left-4 top-1/2 -translate-y-1/2 p-2 bg-white/80 rounded-full shadow-md hover:bg-white"
                    aria-label="Previous image"
                  >
                    <ChevronLeft className="w-5 h-5" />
                  </button>
                  <button
                    onClick={() => setSelectedMedia(i => (i + 1) % allMedia.length)}
                    className="absolute right-4 top-1/2 -translate-y-1/2 p-2 bg-white/80 rounded-full shadow-md hover:bg-white"
                    aria-label="Next image"
                  >
                    <ChevronRight className="w-5 h-5" />
                  </button>
                </>
              )}
            </div>

            {/* Thumbnails */}
            {allMedia.length > 1 && (
              <div className="flex gap-1 sm:gap-2 overflow-x-auto pb-1 sm:pb-2">
                {allMedia.map((media, index) => (
                  <button
                    key={media.id}
                    onClick={() => setSelectedMedia(index)}
                    className={`w-14 h-14 sm:w-20 sm:h-20 flex-shrink-0 rounded-lg overflow-hidden border-2 ${
                      selectedMedia === index ? 'border-purple-600' : 'border-transparent'
                    }`}
                    aria-label={`View ${media.type === 'VIDEO' ? 'video' : 'image'} ${index + 1}`}
                  >
                    {media.type === 'VIDEO' ? (
                      <div className="w-full h-full bg-gray-900 flex items-center justify-center">
                        <Play className="w-6 h-6 text-white" />
                      </div>
                    ) : media.url ? (
                      <Image
                        src={media.url}
                        alt={`Thumbnail ${index + 1}`}
                        width={80}
                        height={80}
                        className="object-cover w-full h-full"
                      />
                    ) : (
                      <div className="w-full h-full bg-gray-200 flex items-center justify-center text-gray-400">
                        ΓÇö
                      </div>
                    )}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Product Info */}
          <div>
            {/* Title & Price */}
            <div className="mb-4 sm:mb-6">
              <p className="text-[9px] sm:text-sm text-purple-600 font-semibold mb-0.5 sm:mb-1">{product.category.name}</p>
              <h1 className="text-lg sm:text-3xl font-bold text-black mb-1 sm:mb-2">{product.title}</h1>
              
              {product.brand && (
                <p className="text-[9px] sm:text-base text-black mb-1 sm:mb-2">by {product.brand}</p>
              )}

              {/* Rating */}
              {product.reviewCount > 0 && (
                <div className="flex items-center gap-1.5 sm:gap-2 mb-2 sm:mb-4">
                  <div className="flex">
                    {[1, 2, 3, 4, 5].map(i => (
                      <Star
                        key={i}
                        className={`w-3.5 h-3.5 sm:w-5 sm:h-5 ${
                          i <= (product.avgRating || 0)
                            ? 'text-yellow-400 fill-yellow-400'
                            : 'text-gray-300'
                        }`}
                      />
                    ))}
                  </div>
                  <span className="text-[8px] sm:text-base text-black">{product.avgRating?.toFixed(1)}</span>
                  <span className="text-gray-400">ΓÇó</span>
                  <a href="#reviews" className="text-purple-600 hover:underline text-[8px] sm:text-sm">
                    {product.reviewCount} reviews
                  </a>
                </div>
              )}

              {/* Price */}
              <div className="flex items-center gap-2 sm:gap-3">
                <span className="text-2xl sm:text-3xl font-bold text-purple-600">
                  Γéª{getPrice().toLocaleString()}
                </span>
                {product.salePrice && (
                  <span className="text-lg sm:text-xl text-gray-400 line-through">
                    Γéª{product.basePrice.toLocaleString()}
                  </span>
                )}
                {product.salePrice && (
                  <span className="px-1.5 sm:px-2 py-0.5 sm:py-1 bg-red-100 text-red-600 text-[8px] sm:text-sm font-medium rounded">
                    {Math.round((1 - product.salePrice / product.basePrice) * 100)}% OFF
                  </span>
                )}
              </div>
            </div>

            {/* Size Selection */}
            {availableSizes.length > 0 && (
              <div className="mb-4 sm:mb-6">
                <h3 className="font-semibold text-black mb-2 sm:mb-3 text-[11px] sm:text-base">Size</h3>
                <div className="flex flex-wrap gap-1.5 sm:gap-2">
                  {availableSizes.map(size => {
                    const hasStock = product.variants.some(v => v.size === size && v.quantity > 0);
                    return (
                      <button
                        key={size}
                        onClick={() => setSelectedSize(size)}
                        disabled={!hasStock}
                        className={`px-2.5 sm:px-4 py-1.5 sm:py-2 border rounded-lg transition-colors text-[9px] sm:text-base ${
                          selectedSize === size
                            ? 'border-purple-600 bg-purple-50 text-purple-600'
                            : hasStock
                              ? 'border-gray-200 hover:border-gray-300 text-black'
                              : 'border-gray-100 text-gray-300 cursor-not-allowed'
                        }`}
                      >
                        {size}
                      </button>
                    );
                  })}
                </div>
              </div>
            )}

            {/* Color Selection */}
            {availableColors.length > 0 && (
              <div className="mb-4 sm:mb-6">
                <h3 className="font-semibold text-black mb-2 sm:mb-3 text-[11px] sm:text-base">
                  Color: <span className="font-normal text-black">{selectedColor}</span>
                </h3>
                <div className="flex flex-wrap gap-2 sm:gap-3">
                  {availableColors.map((c, i) => {
                    const swatchClass = `color-swatch-${i}`
                    return (
                      <div key={i} className="inline-flex">
                        <button
                          onClick={() => setSelectedColor(c.color)}
                          className={`w-8 h-8 sm:w-10 sm:h-10 rounded-full border-2 transition-all ${
                            selectedColor === c.color
                              ? 'border-purple-600 ring-2 ring-purple-200'
                              : 'border-gray-200'
                          } ${swatchClass}`}
                          aria-label={`Select color ${c.color}`}
                          title={c.color}
                        >
                          {selectedColor === c.color && (
                            <Check className={`w-4 h-4 sm:w-5 sm:h-5 mx-auto ${
                              c.hex === '#FFFFFF' || c.hex === '#FFF' ? 'text-gray-900' : 'text-white'
                            }`} />
                          )}
                        </button>
                        <style jsx>{`
                          .${swatchClass} {
                            background:${c.hex || '#ccc'};
                          }
                        `}</style>
                      </div>
                    )
                  })}
                </div>
              </div>
            )}

            {/* Quantity */}
            <div className="mb-4 sm:mb-6">
              <h3 className="font-semibold text-black mb-2 sm:mb-3 text-[11px] sm:text-base">Quantity</h3>
              <div className="flex items-center gap-2 sm:gap-4">
                <div className="flex items-center border border-gray-200 rounded-lg">
                  <button
                    onClick={() => setQuantity(q => Math.max(1, q - 1))}
                    className="p-1 sm:p-2 hover:bg-gray-50"
                    disabled={quantity <= 1}
                    aria-label="Decrease quantity"
                  >
                    <Minus className="w-4 h-4 sm:w-5 sm:h-5 text-black" />
                  </button>
                  <span className="w-8 sm:w-12 text-center font-medium text-black text-sm">{quantity}</span>
                  <button
                    onClick={() => setQuantity(q => Math.min(getMaxQuantity(), q + 1))}
                    className="p-1 sm:p-2 hover:bg-gray-50"
                    disabled={quantity >= getMaxQuantity()}
                    aria-label="Increase quantity"
                  >
                    <Plus className="w-4 h-4 sm:w-5 sm:h-5 text-black" />
                  </button>
                </div>
                <span className="text-[8px] sm:text-sm text-black">
                  {getMaxQuantity()} available
                </span>
              </div>
            </div>

            {/* Add to Cart & Wishlist */}
            <div className="flex gap-2 sm:gap-4 mb-8 sm:mb-12 mt-4 sm:mt-6 sticky bottom-0 sm:relative bg-white py-3 sm:py-0 border-t sm:border-0 z-10">
              <button
                onClick={addToCart}
                disabled={!isInStock || addingToCart}
                className="flex-1 py-3 sm:py-4 bg-purple-600 text-white font-bold rounded-lg sm:rounded-xl hover:bg-purple-700 disabled:bg-gray-300 disabled:cursor-not-allowed flex items-center justify-center gap-2 text-base sm:text-lg"
              >
                <ShoppingCart className="w-5 h-5 sm:w-6 sm:h-6" />
                {addingToCart ? 'Adding...' : isInStock ? 'Add to Cart' : 'Out of Stock'}
              </button>
              <button
                onClick={toggleFavorite}
                className={`p-2 sm:p-3 border rounded-lg sm:rounded-xl hover:bg-gray-50 ${
                  isFavorite ? 'border-red-200 bg-red-50' : 'border-gray-200'
                }`}
                aria-label={isFavorite ? 'Remove from favorites' : 'Add to favorites'}
              >
                <Heart className={`w-5 h-5 sm:w-6 sm:h-6 ${isFavorite ? 'text-red-500 fill-red-500' : 'text-black'}`} />
              </button>
              {/* Feature Button - Only show for seller */}
              {session?.user?.id === product?.seller.id && (
                <button
                  onClick={toggleFeatured}
                  disabled={featuringProduct}
                  className={`p-2 sm:p-3 border rounded-lg sm:rounded-xl hover:bg-gray-50 transition-colors disabled:opacity-50 ${
                    isFeatured ? 'border-yellow-300 bg-yellow-50' : 'border-gray-200'
                  }`}
                  aria-label={isFeatured ? 'Remove from featured' : 'Add to featured'}
                  title={isFeatured ? 'Remove from featured items' : 'Add to featured items'}
                >
                  <Star className={`w-5 h-5 sm:w-6 sm:h-6 ${isFeatured ? 'text-yellow-500 fill-yellow-500' : 'text-black'}`} />
                </button>
              )}
              <button className="p-2 sm:p-3 border border-gray-200 rounded-lg sm:rounded-xl hover:bg-gray-50" aria-label="Share product">
                <Share2 className="w-5 h-5 sm:w-6 sm:h-6 text-black" />
              </button>
            </div>

            {/* Trust Badges */}
            <div className="grid grid-cols-3 gap-2 sm:gap-4 p-2 sm:p-4 bg-gray-50 rounded-lg sm:rounded-xl mb-6 sm:mb-8">
              <div className="text-center">
                <Shield className="w-6 h-6 sm:w-8 sm:h-8 text-purple-600 mx-auto mb-1 sm:mb-2" />
                <p className="text-[7px] sm:text-xs text-black">Verified Product</p>
              </div>
              <div className="text-center">
                <Truck className="w-6 h-6 sm:w-8 sm:h-8 text-purple-600 mx-auto mb-1 sm:mb-2" />
                <p className="text-[7px] sm:text-xs text-black">Fast Delivery</p>
              </div>
              <div className="text-center">
                <RefreshCw className="w-6 h-6 sm:w-8 sm:h-8 text-purple-600 mx-auto mb-1 sm:mb-2" />
                <p className="text-[7px] sm:text-xs text-black">Easy Returns</p>
              </div>
            </div>

            {/* Description */}
            <div className="border-t pt-4 sm:pt-6">
              <h3 className="font-semibold text-black mb-2 sm:mb-3 text-[11px] sm:text-base">Description</h3>
              <p className="text-black whitespace-pre-line text-[9px] sm:text-base break-words overflow-hidden w-full">{product.description}</p>

              {/* Details */}
              <div className="grid grid-cols-2 gap-2 sm:gap-4 mt-3 sm:mt-4">
                {product.material && (
                  <div>
                    <span className="text-[8px] sm:text-sm text-black">Material</span>
                    <p className="font-medium text-[9px] sm:text-base text-black">{product.material}</p>
                  </div>
                )}
                {product.condition && (
                  <div>
                    <span className="text-[8px] sm:text-sm font-medium text-black">Condition</span>
                    <p className="font-semibold text-[9px] sm:text-base text-black">{product.condition}</p>
                  </div>
                )}
                {product.style && (
                  <div>
                    <span className="text-[8px] sm:text-sm font-medium text-black">Style</span>
                    <p className="font-semibold text-[9px] sm:text-base text-black">{product.style}</p>
                  </div>
                )}
                {product.occasion && (
                  <div>
                    <span className="text-[8px] sm:text-sm font-medium text-black">Occasion</span>
                    <p className="font-semibold text-[9px] sm:text-base text-black">{product.occasion}</p>
                  </div>
                )}
              </div>

              {product.careInstructions && (
                <div className="mt-3 sm:mt-4">
                  <span className="text-[8px] sm:text-sm font-medium text-black">Care Instructions</span>
                  <p className="font-semibold text-[9px] sm:text-base text-black">{product.careInstructions}</p>
                </div>
              )}

              {/* Tags */}
              {product.tags.length > 0 && (
                <div className="flex flex-wrap gap-1 sm:gap-2 mt-3 sm:mt-4">
                  {product.tags.map(tag => (
                    <span key={tag} className="px-2 sm:px-3 py-0.5 sm:py-1 bg-purple-100 text-purple-700 text-[8px] sm:text-sm rounded-full font-medium">
                      {tag}
                    </span>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Reviews Section */}
        <div id="reviews" className="mt-8 sm:mt-12 pt-4 sm:pt-8 border-t">
          <div className="flex items-center justify-between mb-4 sm:mb-6">
            <h2 className="text-lg sm:text-2xl font-bold text-black">
              Customer Reviews ({product.reviewCount})
            </h2>
            {session ? (
              !userReview ? (
                <button
                  onClick={() => {
                    setShowReviewForm(!showReviewForm);
                    setEditingReview(false);
                  }}
                  className="px-3 sm:px-4 py-1.5 sm:py-2 bg-purple-600 text-white text-xs sm:text-sm rounded-lg hover:bg-purple-700 font-medium"
                >
                  {showReviewForm ? 'Cancel' : 'Write a Review'}
                </button>
              ) : (
                <div className="flex gap-2">
                  <button
                    onClick={() => {
                      setEditingReview(!editingReview);
                      setShowReviewForm(!showReviewForm);
                    }}
                    className="px-3 sm:px-4 py-1.5 sm:py-2 bg-blue-600 text-white text-xs sm:text-sm rounded-lg hover:bg-blue-700 font-medium"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => setDeleteConfirm(true)}
                    className="px-3 sm:px-4 py-1.5 sm:py-2 bg-red-600 text-white text-xs sm:text-sm rounded-lg hover:bg-red-700 font-medium"
                  >
                    Delete
                  </button>
                </div>
              )
            ) : (
              <Link
                href="/auth/signin"
                className="px-3 sm:px-4 py-1.5 sm:py-2 bg-purple-600 text-white text-xs sm:text-sm rounded-lg hover:bg-purple-700 font-medium"
              >
                Sign In to Review
              </Link>
            )}
          </div>

          {/* Delete Confirmation */}
          {deleteConfirm && (
            <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
              <div className="bg-white rounded-lg max-w-sm w-full p-6">
                <h3 className="text-lg font-bold text-black mb-3">Delete Review?</h3>
                <p className="text-gray-700 text-sm mb-6">
                  Are you sure you want to delete your review? This action cannot be undone.
                </p>
                <div className="flex gap-3">
                  <button
                    onClick={() => setDeleteConfirm(false)}
                    className="flex-1 px-4 py-2 border border-gray-300 text-black font-medium rounded-lg hover:bg-gray-50"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={deleteReview}
                    disabled={submitReviewLoading}
                    className="flex-1 px-4 py-2 bg-red-600 text-white font-medium rounded-lg hover:bg-red-700 disabled:opacity-50"
                  >
                    {submitReviewLoading ? 'Deleting...' : 'Delete'}
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* Review Form */}
          {showReviewForm && session && (
            <div className="bg-white p-4 sm:p-6 rounded-lg sm:rounded-xl border border-purple-200 mb-6 sm:mb-8">
              <h3 className="font-semibold text-black text-sm sm:text-base mb-3 sm:mb-4">
                {editingReview ? 'Edit Your Review' : 'Share Your Experience'}
              </h3>
              
              <div className="space-y-3 sm:space-y-4">
                {/* Rating */}
                <div>
                  <label className="block text-xs sm:text-sm font-medium text-black mb-2">Rating</label>
                  <div className="flex gap-2">
                    {[1, 2, 3, 4, 5].map(i => (
                      <button
                        key={i}
                        onClick={() => setReviewRating(i)}
                        className="transition-transform hover:scale-110"
                        aria-label={`Rate ${i} star${i > 1 ? 's' : ''}`}
                      >
                        <Star
                          className={`w-6 h-6 sm:w-8 sm:h-8 ${
                            i <= reviewRating
                              ? 'fill-yellow-400 text-yellow-400'
                              : 'text-gray-300'
                          }`}
                        />
                      </button>
                    ))}
                  </div>
                </div>

                {/* Title */}
                <div>
                  <label htmlFor="reviewTitle" className="block text-xs sm:text-sm font-medium text-black mb-1">
                    Review Title (Optional)
                  </label>
                  <input
                    id="reviewTitle"
                    type="text"
                    value={reviewTitle}
                    onChange={(e) => setReviewTitle(e.target.value)}
                    placeholder="e.g., Excellent quality and fit!"
                    maxLength={100}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm text-black focus:outline-none focus:ring-2 focus:ring-purple-500"
                  />
                </div>

                {/* Comment */}
                <div>
                  <label htmlFor="reviewComment" className="block text-xs sm:text-sm font-medium text-black mb-1">
                    Your Review <span className="text-red-500">*</span>
                  </label>
                  <textarea
                    id="reviewComment"
                    value={reviewComment}
                    onChange={(e) => setReviewComment(e.target.value)}
                    placeholder="Share details about the product quality, fit, delivery, and more..."
                    rows={3}
                    maxLength={500}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm text-black focus:outline-none focus:ring-2 focus:ring-purple-500 resize-none"
                  />
                  <p className="text-xs text-gray-500 mt-1">{reviewComment.length}/500 characters</p>
                </div>

                {/* Fit Feedback */}
                <div>
                  <label htmlFor="reviewFit" className="block text-xs sm:text-sm font-medium text-black mb-1">
                    How does it fit?
                  </label>
                  <select
                    id="reviewFit"
                    value={reviewFit}
                    onChange={(e) => setReviewFit(e.target.value as 'RUNS_SMALL' | 'TRUE_TO_SIZE' | 'RUNS_LARGE' | '')}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm text-black focus:outline-none focus:ring-2 focus:ring-purple-500"
                  >
                    <option value="">Select fit (optional)</option>
                    <option value="RUNS_SMALL">Runs Small</option>
                    <option value="TRUE_TO_SIZE">True to Size</option>
                    <option value="RUNS_LARGE">Runs Large</option>
                  </select>
                </div>

                {/* Submit */}
                <div className="flex gap-2 pt-2">
                  <button
                    onClick={submitReview}
                    disabled={submitReviewLoading || !reviewComment.trim()}
                    className="flex-1 px-4 py-2 bg-purple-600 text-white text-sm font-medium rounded-lg hover:bg-purple-700 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {submitReviewLoading ? (editingReview ? 'Updating...' : 'Submitting...') : (editingReview ? 'Update Review' : 'Submit Review')}
                  </button>
                  <button
                    onClick={() => {
                      setShowReviewForm(false);
                      setEditingReview(false);
                    }}
                    className="px-4 py-2 border border-gray-300 text-black text-sm font-medium rounded-lg hover:bg-gray-50"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            </div>
          )}

          {product.reviews.length > 0 ? (
            <div className="space-y-4 sm:space-y-6">
              {product.reviews.map(review => (
                <div key={review.id} className="bg-white p-3 sm:p-6 rounded-lg sm:rounded-xl border border-gray-200">
                  <div className="flex items-start justify-between mb-2 sm:mb-3">
                    <div className="flex items-center gap-2 sm:gap-3">
                      <div className="w-8 sm:w-10 h-8 sm:h-10 bg-gray-200 rounded-full flex items-center justify-center flex-shrink-0">
                        {review.user.image ? (
                          <Image
                            src={review.user.image}
                            alt={review.user.name}
                            width={40}
                            height={40}
                            className="rounded-full"
                          />
                        ) : (
                          <User className="w-4 h-4 sm:w-5 sm:h-5 text-black" />
                        )}
                      </div>
                      <div>
                        <p className="font-semibold text-black text-[9px] sm:text-base">{review.user.name}</p>
                        <div className="flex">
                          {[1, 2, 3, 4, 5].map(i => (
                            <Star
                              key={i}
                              className={`w-3 h-3 sm:w-4 sm:h-4 ${
                                i <= review.rating ? 'text-yellow-400 fill-yellow-400' : 'text-gray-300'
                              }`}
                            />
                          ))}
                        </div>
                      </div>
                    </div>
                    <span className="text-[7px] sm:text-sm text-black">
                      {new Date(review.createdAt).toLocaleDateString()}
                    </span>
                  </div>
                  
                  {review.title && (
                    <h4 className="font-semibold text-black mb-1 sm:mb-2 text-[10px] sm:text-base">{review.title}</h4>
                  )}
                  <p className="text-black text-[9px] sm:text-base">{review.comment}</p>
                  
                  {review.fitFeedback && (
                    <div className="mt-2 sm:mt-3 px-2 sm:px-3 py-1 sm:py-2 bg-purple-100 rounded-lg inline-block">
                      <span className="text-[8px] sm:text-sm text-purple-700 font-medium">Fit: {review.fitFeedback}</span>
                    </div>
                  )}
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-8 sm:py-12 bg-white rounded-lg sm:rounded-xl border border-gray-200">
              <MessageSquare className="w-8 sm:w-12 h-8 sm:h-12 text-gray-300 mx-auto mb-2 sm:mb-3" />
              <p className="text-black text-[9px] sm:text-base">No reviews yet. Be the first to review!</p>
            </div>
          )}
        </div>

        {/* Related Products */}
        {relatedProducts.length > 0 && (
          <div className="mt-8 sm:mt-12 pt-4 sm:pt-8 border-t">
            <h2 className="text-lg sm:text-2xl font-bold text-black mb-4 sm:mb-6">You May Also Like</h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 sm:gap-6">
              {relatedProducts.map(p => (
                <Link
                  key={p.id}
                  href={`/boutique/${p.slug}`}
                  className="bg-white rounded-lg sm:rounded-xl overflow-hidden shadow-sm hover:shadow-md transition-shadow"
                >
                  <div className="aspect-[3/4] bg-gray-100 relative">
                    {p.thumbnailUrl && (
                      <Image
                        src={p.thumbnailUrl}
                        alt={p.title}
                        fill
                        className="object-cover"
                      />
                    )}
                  </div>
                  <div className="p-3">
                    <h3 className="font-medium text-gray-900 line-clamp-1">{p.title}</h3>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-purple-600 font-bold">
                        Γéª{(p.salePrice || p.basePrice).toLocaleString()}
                      </span>
                      {p.salePrice && (
                        <span className="text-sm text-gray-400 line-through">
                          Γéª{p.basePrice.toLocaleString()}
                        </span>
                      )}
                    </div>
                  </div>
                </Link>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useSession } from 'next-auth/react';
import Link from 'next/link';
import Image from 'next/image';
import { 
  Package, 
  ArrowLeft, 
  Truck,
  MapPin,
  CreditCard,
  Tag,
  AlertTriangle,
  Loader2,
  CheckCircle,
  Phone,
  User,
  Building,
  Info,
} from 'lucide-react';
import toast from 'react-hot-toast';

interface CartItem {
  id: string;
  quantity: number;
  product: {
    id: string;
    title: string;
    slug: string;
    basePrice: number;
    salePrice: number | null;
    thumbnailUrl: string | null;
    fulfillmentMethod: string;
  };
  variant: {
    size: string;
    color: string;
    colorHex: string | null;
    priceAdjustment: number;
  } | null;
  price: number;
  isSellerDirect: boolean;
}

interface Cart {
  items: CartItem[];
  subtotal: number;
  itemCount: number;
}

interface ShippingAddress {
  name: string;
  phone: string;
  street: string;
  city: string;
  state: string;
  country: string;
}

const NIGERIAN_STATES = [
  'Abia', 'Adamawa', 'Akwa Ibom', 'Anambra', 'Bauchi', 'Bayelsa', 'Benue', 'Borno',
  'Cross River', 'Delta', 'Ebonyi', 'Edo', 'Ekiti', 'Enugu', 'FCT', 'Gombe', 
  'Imo', 'Jigawa', 'Kaduna', 'Kano', 'Katsina', 'Kebbi', 'Kogi', 'Kwara',
  'Lagos', 'Nasarawa', 'Niger', 'Ogun', 'Ondo', 'Osun', 'Oyo', 'Plateau',
  'Rivers', 'Sokoto', 'Taraba', 'Yobe', 'Zamfara'
];

export default function BoutiqueCheckoutPage() {
  const { data: session, status } = useSession();
  const router = useRouter();
  
  const [cart, setCart] = useState<Cart | null>(null);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [shippingEstimate, setShippingEstimate] = useState<number | null>(null);
  const [shippingInfo, setShippingInfo] = useState<{
    cost: number;
    carrier: string;
    estimatedDays: number;
    notes?: string;
  } | null>(null);
  const [paymentProcessor, setPaymentProcessor] = useState<'PAYSTACK' | 'STRIPE' | 'FLUTTERWAVE' | null>(null);
  const [buyerCountry, setBuyerCountry] = useState<string>('NG');
  const [couponCode, setCouponCode] = useState('');
  const [appliedCoupon, setAppliedCoupon] = useState<{ code: string; discount: number } | null>(null);
  
  const [address, setAddress] = useState<ShippingAddress>({
    name: '',
    phone: '',
    street: '',
    city: '',
    state: '',
    country: 'Nigeria',
  });

  const [errors, setErrors] = useState<Partial<ShippingAddress>>({});

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/auth/signin?callbackUrl=/boutique/checkout');
    } else if (status === 'authenticated') {
      fetchCart();
      // Pre-fill name if available
      if (session?.user?.name) {
        setAddress(prev => ({ ...prev, name: session.user.name || '' }));
      }
    }
  }, [status, router, session]);

  const fetchCart = async () => {
    try {
      const response = await fetch('/api/boutique/cart');
      const data = await response.json();
      if (data.success) {
        if (data.cart.items.length === 0) {
          toast.error('Your cart is empty');
          router.push('/boutique/cart');
          return;
        }
        setCart(data.cart);
      } else {
        toast.error(data.message || 'Failed to load cart');
      }
    } catch (error) {
      console.error('Error fetching cart:', error);
      toast.error('Failed to load cart');
    } finally {
      setLoading(false);
    }
  };

  const validateAddress = (): boolean => {
    const newErrors: Partial<ShippingAddress> = {};
    
    if (!address.name.trim()) newErrors.name = 'Name is required';
    if (!address.phone.trim()) newErrors.phone = 'Phone number is required';
    else if (!/^[0-9+\-\s]{10,15}$/.test(address.phone.replace(/\s/g, ''))) {
      newErrors.phone = 'Invalid phone number';
    }
    if (!address.street.trim()) newErrors.street = 'Street address is required';
    if (!address.city.trim()) newErrors.city = 'City is required';
    if (!address.state) newErrors.state = 'State is required';
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const estimateShipping = async () => {
    if (!address.state) return;
    
    try {
      const response = await fetch('/api/boutique/shipping/estimate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          state: address.state,
          fulfillmentMethod: 'ADMIN_STOCK',
          weight: 0.5,
        }),
      });
      
      const data = await response.json();
      if (data.success) {
        setShippingEstimate(data.shipping.cost);
        setShippingInfo({
          cost: data.shipping.cost,
          carrier: data.shipping.carrier || 'Standard Shipping',
          estimatedDays: data.shipping.estimatedDays || 3,
          notes: data.shipping.notes,
        });
        setPaymentProcessor(data.buyer?.paymentProcessor || 'PAYSTACK');
        setBuyerCountry(data.buyer?.country || 'NG');
      }
    } catch (error) {
      console.error('Error estimating shipping:', error);
    }
  };

  useEffect(() => {
    if (address.state) {
      estimateShipping();
    }
  }, [address.state]);

  const applyCoupon = async () => {
    if (!couponCode.trim()) return;
    
    try {
      const response = await fetch('/api/boutique/coupons/validate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code: couponCode, subtotal: cart?.subtotal || 0 }),
      });
      
      const data = await response.json();
      if (data.success && data.valid) {
        setAppliedCoupon({ code: couponCode.toUpperCase(), discount: data.discount });
        toast.success(`Coupon applied! You save ${formatPrice(data.discount)}`);
      } else {
        toast.error(data.message || 'Invalid coupon code');
      }
    } catch (error) {
      console.error('Error applying coupon:', error);
      toast.error('Failed to apply coupon');
    }
  };

  const handleSubmit = async () => {
    if (!validateAddress()) {
      toast.error('Please fill in all required fields');
      return;
    }
    
    setSubmitting(true);
    
    try {
      const response = await fetch('/api/boutique/checkout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          shippingAddress: address,
          paymentMethod: 'paystack',
          buyerCountry,
          couponCode: appliedCoupon?.code,
        }),
      });
      
      const data = await response.json();
      
      if (data.success) {
        // Redirect to Paystack payment page
        if (data.paymentUrl) {
          window.location.href = data.paymentUrl;
        } else {
          toast.error('Payment initialization failed');
          setSubmitting(false);
        }
      } else {
        toast.error(data.message || 'Checkout failed');
        setSubmitting(false);
      }
    } catch (error) {
      console.error('Checkout error:', error);
      toast.error('An error occurred during checkout');
      setSubmitting(false);
    }
  };

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat('en-NG', {
      style: 'currency',
      currency: 'NGN',
      minimumFractionDigits: 0,
    }).format(price).replace(/[\n\r\t\s]+/g, '');
  };

  if (status === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin h-8 w-8 border-4 border-purple-500 border-t-transparent rounded-full"></div>
      </div>
    );
  }

  if (!session || !cart) return null;

  const subtotal = cart.subtotal;
  const shipping = shippingEstimate || 0;
  const discount = appliedCoupon?.discount || 0;
  const total = subtotal + shipping - discount;

  return (
    <div className="min-h-screen bg-gray-50 py-4 sm:py-8">
      <div className="w-full max-w-6xl mx-auto px-2 sm:px-4 overflow-hidden">
        {/* Header */}
        <div className="flex items-center gap-2 sm:gap-4 mb-3 sm:mb-8">
          <Link 
            href="/boutique/cart" 
            className="p-1.5 sm:p-2 hover:bg-gray-100 rounded-lg transition"
          >
            <ArrowLeft className="w-4 h-4 sm:w-5 sm:h-5 text-gray-600" />
          </Link>
          <div>
            <h1 className="text-lg sm:text-2xl font-bold text-black flex items-center gap-1 sm:gap-2">
              <Package className="w-5 h-5 sm:w-6 sm:h-6 text-purple-600" />
              Checkout
            </h1>
            <p className="text-[9px] sm:text-sm text-black">
              Complete your purchase
            </p>
          </div>
        </div>

        {/* Physical Items Notice */}
        <div className="bg-purple-50 border border-purple-200 rounded-lg p-2 sm:p-4 mb-3 sm:mb-6">
          <div className="flex items-start gap-2 sm:gap-3">
            <Truck className="w-4 h-4 sm:w-5 sm:h-5 text-purple-600 mt-0.5 flex-shrink-0" />
            <div>
              <h3 className="font-medium text-purple-900 text-[11px] sm:text-base">Physical Items Shipping</h3>
              <p className="text-[9px] sm:text-sm text-purple-700">
                Items will be shipped to your address. Provide accurate information.
              </p>
            </div>
          </div>
        </div>

        <div className="w-full grid lg:grid-cols-3 gap-3 sm:gap-6 min-w-0">
          {/* Shipping Form */}
          <div className="lg:col-span-2 space-y-3 sm:space-y-6 min-w-0">
            {/* Shipping Address */}
            <div className="bg-white rounded-lg shadow-sm p-3 sm:p-6">
              <h2 className="text-sm sm:text-lg font-semibold text-black mb-2 sm:mb-4 flex items-center gap-1 sm:gap-2">
                <MapPin className="w-4 h-4 sm:w-5 sm:h-5 text-purple-600" />
                Shipping Address
              </h2>
              
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 sm:gap-4">
                <div className="sm:col-span-2">
                  <label className="block text-xs sm:text-sm font-medium text-black mb-0.5 sm:mb-1">
                    <User className="w-3 h-3 sm:w-4 sm:h-4 inline mr-1" />
                    Full Name *
                  </label>
                  <input
                    type="text"
                    value={address.name}
                    onChange={(e) => setAddress({ ...address, name: e.target.value })}
                    className={`w-full px-2 sm:px-4 py-1.5 sm:py-2 border rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent text-[11px] sm:text-base text-gray-900 ${
                      errors.name ? 'border-red-500' : 'border-gray-300'
                    }`}
                    placeholder="Full name"
                  />
                  {errors.name && <p className="text-red-500 text-[8px] sm:text-xs mt-0.5">{errors.name}</p>}
                </div>
                
                <div className="sm:col-span-2">
                  <label className="block text-xs sm:text-sm font-medium text-black mb-0.5 sm:mb-1">
                    <Phone className="w-3 h-3 sm:w-4 sm:h-4 inline mr-1" />
                    Phone Number *
                  </label>
                  <input
                    type="tel"
                    value={address.phone}
                    onChange={(e) => setAddress({ ...address, phone: e.target.value })}
                    className={`w-full px-2 sm:px-4 py-1.5 sm:py-2 border rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent text-[11px] sm:text-base text-gray-900 ${
                      errors.phone ? 'border-red-500' : 'border-gray-300'
                    }`}
                    placeholder="08012345678"
                  />
                  {errors.phone && <p className="text-red-500 text-[8px] sm:text-xs mt-0.5">{errors.phone}</p>}
                </div>
                
                <div className="sm:col-span-2">
                  <label className="block text-xs sm:text-sm font-medium text-black mb-0.5 sm:mb-1">
                    <Building className="w-3 h-3 sm:w-4 sm:h-4 inline mr-1" />
                    Street Address *
                  </label>
                  <input
                    type="text"
                    value={address.street}
                    onChange={(e) => setAddress({ ...address, street: e.target.value })}
                    className={`w-full px-2 sm:px-4 py-1.5 sm:py-2 border rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent text-[11px] sm:text-base text-gray-900 ${
                      errors.street ? 'border-red-500' : 'border-gray-300'
                    }`}
                    placeholder="House number, street"
                  />
                  {errors.street && <p className="text-red-500 text-[8px] sm:text-xs mt-0.5">{errors.street}</p>}
                </div>
                
                <div>
                  <label className="block text-xs sm:text-sm font-medium text-black mb-0.5 sm:mb-1">
                    City *
                  </label>
                  <input
                    type="text"
                    value={address.city}
                    onChange={(e) => setAddress({ ...address, city: e.target.value })}
                    className={`w-full px-2 sm:px-4 py-1.5 sm:py-2 border rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent text-[11px] sm:text-base text-gray-900 ${
                      errors.city ? 'border-red-500' : 'border-gray-300'
                    }`}
                    placeholder="Ikeja"
                  />
                  {errors.city && <p className="text-red-500 text-[8px] sm:text-xs mt-0.5">{errors.city}</p>}
                </div>
                
                <div>
                  <label htmlFor="addressState" className="block text-xs sm:text-sm font-medium text-black mb-0.5 sm:mb-1">
                    State *
                  </label>
                  <select
                    id="addressState"
                    value={address.state}
                    onChange={(e) => setAddress({ ...address, state: e.target.value })}
                    className={`w-full px-2 sm:px-4 py-1.5 sm:py-2 border rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent text-[11px] sm:text-base text-gray-900 ${
                      errors.state ? 'border-red-500' : 'border-gray-300'
                    }`}
                  >
                    <option value="">Select state</option>
                    {NIGERIAN_STATES.map(state => (
                      <option key={state} value={state}>{state}</option>
                    ))}
                  </select>
                  {errors.state && <p className="text-red-500 text-xs mt-1">{errors.state}</p>}
                </div>
              </div>
            </div>

            {/* Coupon Code */}
            <div className="bg-white rounded-lg shadow-sm p-3 sm:p-6">
              <h2 className="text-sm sm:text-lg font-semibold text-black mb-2 sm:mb-4 flex items-center gap-1 sm:gap-2">
                <Tag className="w-4 h-4 sm:w-5 sm:h-5 text-purple-600" />
                Discount Code
              </h2>
              
              <div className="flex gap-1 sm:gap-2">
                <input
                  type="text"
                  value={couponCode}
                  onChange={(e) => setCouponCode(e.target.value.toUpperCase())}
                  disabled={!!appliedCoupon}
                  className="flex-1 px-2 sm:px-4 py-1.5 sm:py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent disabled:bg-gray-100 text-[11px] sm:text-base text-gray-900"
                  placeholder="Code"
                />
                {appliedCoupon ? (
                  <button
                    onClick={() => {
                      setAppliedCoupon(null);
                      setCouponCode('');
                    }}
                    className="px-2 sm:px-4 py-1.5 sm:py-2 border border-gray-300 rounded-lg hover:bg-gray-50 text-[11px] sm:text-base"
                  >
                    Remove
                  </button>
                ) : (
                  <button
                    onClick={applyCoupon}
                    className="px-3 sm:px-6 py-1.5 sm:py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition text-[11px] sm:text-base"
                  >
                    Apply
                  </button>
                )}
              </div>
              
              {appliedCoupon && (
                <div className="mt-2 sm:mt-3 flex items-center gap-1 sm:gap-2 text-green-600">
                  <CheckCircle className="w-3 h-3 sm:w-4 sm:h-4" />
                  <span className="text-[9px] sm:text-sm">
                    "{appliedCoupon.code}" applied!
                  </span>
                </div>
              )}
            </div>

            {/* Order Items Preview */}
            <div className="bg-white rounded-lg shadow-sm p-3 sm:p-6">
              <h2 className="text-sm sm:text-lg font-semibold text-black mb-2 sm:mb-4">
                Items ({cart.itemCount})
              </h2>
              
              <div className="space-y-2 sm:space-y-3">
                {cart.items.map((item) => (
                  <div key={item.id} className="flex items-center gap-3 py-2 border-b last:border-0">
                    <div className="w-12 h-12 relative rounded overflow-hidden bg-gray-100 shrink-0">
                      {item.product.thumbnailUrl ? (
                        <Image
                          src={item.product.thumbnailUrl}
                          alt={item.product.title}
                          fill
                          className="object-cover"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center">
                          <Package className="w-5 h-5 text-gray-300" />
                        </div>
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="font-medium text-gray-900 text-sm line-clamp-1">
                        {item.product.title}
                      </p>
                      {item.variant && (
                        <p className="text-[8px] sm:text-xs text-black">
                          {item.variant.size} / {item.variant.color} ├ù {item.quantity}
                        </p>
                      )}
                    </div>
                    <span className="font-medium text-black text-sm">
                      {formatPrice(item.price * item.quantity)}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Order Summary */}
          <div className="lg:col-span-1 w-full min-w-0">
            <div className="bg-white rounded-lg shadow-sm p-3 sm:p-6 lg:sticky lg:top-20 w-full box-border">
              <h2 className="text-sm sm:text-lg font-semibold text-black mb-2 sm:mb-4">
                Order Summary
              </h2>
              
              <div className="space-y-1.5 sm:space-y-3 text-[9px] sm:text-sm">
                <div className="flex justify-between gap-2">
                  <span className="text-black">Subtotal</span>
                  <span className="font-bold text-black">{formatPrice(subtotal)}</span>
                </div>
                
                {/* Shipping Breakdown */}
                <div className="pt-2 border-t">
                  <div className="flex justify-between gap-2 mb-1">
                    <span className="text-black">Shipping</span>
                    {address.state ? (
                      shippingEstimate !== null ? (
                        <span className="font-bold text-black">{formatPrice(shipping)}</span>
                      ) : (
                        <span className="text-[8px] sm:text-xs text-gray-400">Calculating...</span>
                      )
                    ) : (
                      <span className="text-[8px] sm:text-xs text-gray-400">Select state</span>
                    )}
                  </div>
                  {shippingInfo && (
                    <div className="text-[7px] sm:text-xs text-gray-600 space-y-0.5">
                      <p>Carrier: <span className="font-medium">{shippingInfo.carrier}</span></p>
                      <p>Delivery: <span className="font-medium">{shippingInfo.estimatedDays} days</span></p>
                      {shippingInfo.notes && <p className="text-gray-500">{shippingInfo.notes}</p>}
                    </div>
                  )}
                </div>
                
                {appliedCoupon && (
                  <div className="flex justify-between gap-2 text-green-600">
                    <span>Discount</span>
                    <span className="font-bold text-black">-{formatPrice(discount)}</span>
                  </div>
                )}
                
                <div className="border-t pt-1.5 sm:pt-3 flex justify-between text-xs sm:text-base">
                  <span className="font-semibold text-black">Total</span>
                  <span className="font-bold text-black">
                    {address.state && shippingEstimate !== null
                      ? formatPrice(total)
                      : `${formatPrice(subtotal - discount)}+`
                    }
                  </span>
                </div>
              </div>

              {/* Payment Processor Info */}
              <div className="mt-3 sm:mt-6 p-2 sm:p-3 bg-gradient-to-r from-purple-50 to-blue-50 rounded-lg border border-purple-100">
                <div className="space-y-1.5">
                  {/* Processor */}
                  <div className="flex items-center gap-2">
                    <CreditCard className="w-4 h-4 text-purple-600" />
                    <div>
                      <p className="text-[7px] sm:text-xs uppercase tracking-wide font-semibold text-purple-600">Payment Method</p>
                      <p className="text-sm font-bold text-black">
                        {paymentProcessor === 'PAYSTACK' && 'Paystack (Cards, Bank, USSD)'}
                        {paymentProcessor === 'STRIPE' && 'Stripe (Cards)'}
                        {paymentProcessor === 'FLUTTERWAVE' && 'Flutterwave (Cards, Bank)'}
                        {!paymentProcessor && 'Detecting...'}
                      </p>
                    </div>
                  </div>
                  
                  {/* Buyer Location */}
                  <div className="flex items-center gap-2 text-[8px] sm:text-xs text-gray-600">
                    <MapPin className="w-3 h-3" />
                    <span>Shipping to: <span className="font-medium text-black">{address.state || 'Select state'}</span></span>
                  </div>
                  
                  {/* Security Badge */}
                  <div className="flex items-center gap-1 text-[7px] sm:text-xs text-green-700">
                    <CheckCircle className="w-3 h-3" />
                    <span>Secure & Encrypted</span>
                  </div>
                </div>
              </div>

              <button
                onClick={handleSubmit}
                disabled={submitting || !address.state}
                className="w-full mt-3 sm:mt-6 bg-purple-600 text-white py-2 sm:py-3 rounded-lg font-medium hover:bg-purple-700 transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-1 sm:gap-2 text-[11px] sm:text-base"
              >
                {submitting ? (
                  <>
                    <Loader2 className="w-4 h-4 sm:w-5 sm:h-5 animate-spin" />
                    <span>Processing...</span>
                  </>
                ) : (
                  <>
                    <CreditCard className="w-4 h-4 sm:w-5 sm:h-5" />
                    <span>Pay {address.state && shippingEstimate !== null 
                      ? formatPrice(total)
                      : formatPrice(subtotal - discount)
                    }</span>
                  </>
                )}
              </button>

              {!address.state && (
                <div className="mt-2 sm:mt-3 flex items-start gap-1 sm:gap-2 text-[8px] sm:text-xs text-amber-600">
                  <AlertTriangle className="w-3 h-3 sm:w-4 sm:h-4 shrink-0 mt-0.5" />
                  <span>Select state to calculate shipping</span>
                </div>
              )}

              <div className="border-t mt-3 sm:mt-6 pt-2 sm:pt-4">
                <Link
                  href="/boutique/cart"
                  className="text-[10px] sm:text-sm text-purple-600 hover:text-purple-700 flex items-center justify-center gap-1"
                >
                  <ArrowLeft className="w-3 h-3 sm:w-4 sm:h-4" />
                  Back
                </Link>
              </div>

              {/* Security Note */}
              <div className="mt-3 sm:mt-4 p-2 sm:p-3 bg-green-50 rounded-lg">
                <div className="flex items-start gap-1 sm:gap-2 text-[8px] sm:text-xs text-green-700">
                  <Info className="w-3 h-3 sm:w-4 sm:h-4 shrink-0 mt-0.5" />
                  <span>
                    Secured by Paystack. Card details not stored.
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import Image from 'next/image'
import Link from 'next/link'
import { Heart, Trash2, ShoppingCart, Star, ChevronLeft, ChevronRight, Package } from 'lucide-react'

interface Favorite {
  id: string
  createdAt: string
  product: {
    id: string
    title: string
    slug: string
    basePrice: number
    salePrice: number | null
    thumbnailUrl: string | null
    status: string
    avgRating: number | null
    seller: {
      id: string
      name: string
    }
  }
}

export default function BoutiqueFavoritesPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [favorites, setFavorites] = useState<Favorite[]>([])
  const [loading, setLoading] = useState(true)
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [removingId, setRemovingId] = useState<string | null>(null)

  useEffect(() => {
    if (status === 'loading') return
    if (!session) {
      router.push('/auth/signin?callbackUrl=/boutique/favorites')
      return
    }
    fetchFavorites()
  }, [session, status, page])

  const fetchFavorites = async () => {
    setLoading(true)
    try {
      const res = await fetch(`/api/boutique/favorites?page=${page}&limit=12`)
      if (res.ok) {
        const data = await res.json()
        setFavorites(data.favorites || [])
        setTotalPages(data.totalPages || 1)
      }
    } catch (error) {
      console.error('Failed to fetch favorites:', error)
    } finally {
      setLoading(false)
    }
  }

  const removeFavorite = async (productId: string) => {
    setRemovingId(productId)
    try {
      const res = await fetch(`/api/boutique/favorites?productId=${productId}`, {
        method: 'DELETE',
      })
      if (res.ok) {
        setFavorites(favorites.filter(f => f.product.id !== productId))
      }
    } catch (error) {
      console.error('Failed to remove favorite:', error)
    } finally {
      setRemovingId(null)
    }
  }

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-NG', {
      style: 'currency',
      currency: 'NGN',
      minimumFractionDigits: 0,
    }).format(amount).replace(/[\n\r\t\s]+/g, '')
  }

  if (status === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600"></div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="mb-8">
          <Link href="/boutique" className="text-purple-600 hover:text-purple-700 flex items-center gap-1 mb-4">
            <ChevronLeft className="w-4 h-4" />
            Back to Boutique
          </Link>
          <div className="flex items-center gap-3">
            <Heart className="w-8 h-8 text-purple-600 fill-purple-600" />
            <div>
              <h1 className="text-3xl font-bold text-gray-900">My Favorites</h1>
              <p className="text-gray-600">{favorites.length} saved items</p>
            </div>
          </div>
        </div>

        {/* Favorites Grid */}
        {favorites.length === 0 ? (
          <div className="bg-white rounded-2xl shadow-sm p-12 text-center">
            <Heart className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <h3 className="text-xl font-semibold text-gray-900 mb-2">No favorites yet</h3>
            <p className="text-gray-500 mb-6">
              Start exploring and save items you love!
            </p>
            <Link
              href="/boutique"
              className="inline-flex items-center gap-2 bg-purple-600 text-white px-6 py-3 rounded-xl font-semibold hover:bg-purple-700 transition"
            >
              <Package className="w-5 h-5" />
              Browse Boutique
            </Link>
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {favorites.map((favorite) => (
                <div
                  key={favorite.id}
                  className="bg-white rounded-xl shadow-sm overflow-hidden group hover:shadow-lg transition"
                >
                  {/* Product Image */}
                  <Link href={`/boutique/${favorite.product.slug}`}>
                    <div className="relative aspect-[3/4] bg-gray-100">
                      <Image
                        src={favorite.product.thumbnailUrl || '/images/placeholder.png'}
                        alt={favorite.product.title}
                        fill
                        className="object-cover group-hover:scale-105 transition duration-300"
                      />
                      {favorite.product.salePrice && (
                        <span className="absolute top-3 left-3 bg-red-500 text-white text-xs font-bold px-2 py-1 rounded">
                          SALE
                        </span>
                      )}
                    </div>
                  </Link>

                  {/* Product Info */}
                  <div className="p-4">
                    <Link href={`/boutique/${favorite.product.slug}`}>
                      <h3 className="font-medium text-gray-900 mb-1 truncate hover:text-purple-600">
                        {favorite.product.title}
                      </h3>
                    </Link>
                    <p className="text-sm text-gray-500 mb-2">
                      by {favorite.product.seller.name}
                    </p>

                    {/* Rating */}
                    {favorite.product.avgRating && (
                      <div className="flex items-center gap-1 mb-2">
                        <Star className="w-4 h-4 text-yellow-400 fill-yellow-400" />
                        <span className="text-sm text-gray-600">
                          {favorite.product.avgRating.toFixed(1)}
                        </span>
                      </div>
                    )}

                    {/* Price */}
                    <div className="flex items-center justify-between mb-3">
                      <div>
                        {favorite.product.salePrice ? (
                          <>
                            <span className="text-lg font-bold text-purple-600">
                              {formatCurrency(favorite.product.salePrice)}
                            </span>
                            <span className="text-sm text-gray-400 line-through ml-2">
                              {formatCurrency(favorite.product.basePrice)}
                            </span>
                          </>
                        ) : (
                          <span className="text-lg font-bold text-gray-900">
                            {formatCurrency(favorite.product.basePrice)}
                          </span>
                        )}
                      </div>
                    </div>

                    {/* Actions */}
                    <div className="flex gap-2">
                      <Link
                        href={`/boutique/${favorite.product.slug}`}
                        className="flex-1 bg-purple-600 text-white py-2 px-4 rounded-lg text-sm font-medium text-center hover:bg-purple-700 transition flex items-center justify-center gap-1"
                      >
                        <ShoppingCart className="w-4 h-4" />
                        View
                      </Link>
                      <button
                        onClick={() => removeFavorite(favorite.product.id)}
                        disabled={removingId === favorite.product.id}
                        className="p-2 border border-gray-200 rounded-lg hover:bg-red-50 hover:border-red-200 hover:text-red-600 transition disabled:opacity-50"
                        title="Remove from favorites"
                      >
                        <Trash2 className="w-5 h-5" />
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>

            {/* Pagination */}
            {totalPages > 1 && (
              <div className="mt-8 flex items-center justify-center gap-4">
                <button
                  onClick={() => setPage(p => Math.max(1, p - 1))}
                  disabled={page === 1}
                  className="px-4 py-2 border rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-1"
                >
                  <ChevronLeft className="w-4 h-4" />
                  Previous
                </button>
                <span className="text-gray-600">
                  Page {page} of {totalPages}
                </span>
                <button
                  onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                  disabled={page === totalPages}
                  className="px-4 py-2 border rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-1"
                >
                  Next
                  <ChevronRight className="w-4 h-4" />
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  )
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter, useParams } from 'next/navigation';
import { useSession } from 'next-auth/react';
import Link from 'next/link';
import Image from 'next/image';
import { 
  Package, 
  ArrowLeft, 
  Truck,
  CheckCircle,
  XCircle,
  MapPin,
  Phone,
  User,
  ExternalLink,
  Copy,
  AlertCircle,
  RotateCcw,
  Star,
} from 'lucide-react';
import toast from 'react-hot-toast';

interface OrderItem {
  id: string;
  quantity: number;
  price: number;
  finalPrice: number;
  variantSnapshot: { size?: string; color?: string; colorHex?: string } | null;
  product: {
    id: string;
    title: string;
    slug: string;
    thumbnailUrl: string | null;
  };
}

interface Order {
  id: string;
  orderNumber: string;
  status: string;
  total: number;
  subtotal: number;
  shippingCost: number;
  discount: number;
  platformFee: number;
  trackingNumber: string | null;
  trackingUrl: string | null;
  shippingAddress: {
    name: string;
    phone: string;
    street: string;
    city: string;
    state: string;
    country: string;
  };
  createdAt: string;
  paidAt: string | null;
  shippedAt: string | null;
  deliveredAt: string | null;
  completedAt: string | null;
  items: OrderItem[];
  seller: {
    id: string;
    name: string | null;
    displayName: string | null;
    image: string | null;
  };
  boutiqueReturn: { id: string; status: string } | null;
  boutiqueRefund: { id: string; status: string; amount: number } | null;
}

const STATUS_STEPS = [
  { key: 'PAID', label: 'Order Placed', icon: CheckCircle },
  { key: 'PROCESSING', label: 'Processing', icon: Package },
  { key: 'SHIPPED', label: 'Shipped', icon: Truck },
  { key: 'DELIVERED', label: 'Delivered', icon: MapPin },
  { key: 'COMPLETED', label: 'Completed', icon: CheckCircle },
];

const STATUS_ORDER = ['PENDING_PAYMENT', 'PAID', 'PROCESSING', 'SHIPPED', 'DELIVERED', 'COMPLETED'];

const getReturnWindowInfo = (deliveredAt: string | null) => {
  if (!deliveredAt) return { daysRemaining: 0, isOpen: false };
  
  const delivered = new Date(deliveredAt).getTime();
  const now = Date.now();
  const daysSinceDelivery = Math.floor((now - delivered) / (1000 * 60 * 60 * 24));
  const daysRemaining = Math.max(0, 7 - daysSinceDelivery);
  
  return {
    daysRemaining,
    isOpen: daysRemaining > 0,
  };
};

export default function BoutiqueOrderDetailPage() {
  const { data: session, status: authStatus } = useSession();
  const router = useRouter();
  const params = useParams();
  const orderId = params.orderId as string;
  
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(true);
  const [confirming, setConfirming] = useState(false);
  const [showReturnModal, setShowReturnModal] = useState(false);
  const [returnReason, setReturnReason] = useState('');
  const [returnDescription, setReturnDescription] = useState('');
  const [selectedItemId, setSelectedItemId] = useState('');

  useEffect(() => {
    if (authStatus === 'unauthenticated') {
      router.push('/auth/signin');
    } else if (authStatus === 'authenticated' && orderId) {
      fetchOrder();
    }
  }, [authStatus, router, orderId]);

  const confirmDelivery = async () => {
    setConfirming(true);
    try {
      const response = await fetch(`/api/boutique/orders/${orderId}/confirm`, {
        method: 'POST',
      });
      const data = await response.json();
      if (data.success) {
        toast.success('Order confirmed! Thank you for your purchase.');
        fetchOrder();
      } else {
        toast.error(data.message || 'Failed to confirm delivery');
      }
    } catch (_error) {
      toast.error('Failed to confirm delivery');
    } finally {
      setConfirming(false);
    }
  };

  const submitReturnRequest = async () => {
    if (!returnReason || !selectedItemId || !returnDescription.trim()) {
      toast.error('Please select an item, provide a reason, and add a description');
      return;
    }
    setConfirming(true);
    try {
      const response = await fetch('/api/boutique/returns', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          orderItemId: selectedItemId,
          reason: returnReason,
          description: returnDescription,
        }),
      });
      const data = await response.json();
      if (data.success) {
        toast.success('Return request submitted!');
        setShowReturnModal(false);
        fetchOrder();
      } else {
        toast.error(data.message || 'Failed to submit return request');
      }
    } catch (_error) {
      toast.error('Failed to submit return request');
    } finally {
      setConfirming(false);
    }
  };

  const fetchOrder = async () => {
    try {
      const response = await fetch(`/api/boutique/orders/${orderId}`);
      const data = await response.json();
      
      if (data.success) {
        setOrder(data.order);
      } else {
        toast.error(data.message || 'Order not found');
        router.push('/boutique/orders');
      }
    } catch (error) {
      console.error('Error fetching order:', error);
      toast.error('Failed to load order');
    } finally {
      setLoading(false);
    }
  };

  const copyToClipboard = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    toast.success(`${label} copied!`);
  };

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat('en-NG', {
      style: 'currency',
      currency: 'NGN',
      minimumFractionDigits: 0,
    }).format(price);
  };

  const formatDate = (dateString: string | null) => {
    if (!dateString) return '-';
    return new Date(dateString).toLocaleDateString('en-NG', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const getStatusIndex = (status: string) => {
    const idx = STATUS_ORDER.indexOf(status);
    return idx >= 0 ? idx : 0;
  };

  if (authStatus === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin h-8 w-8 border-4 border-purple-500 border-t-transparent rounded-full"></div>
      </div>
    );
  }

  if (!session || !order) return null;

  const currentStatusIndex = getStatusIndex(order.status);
  const isCancelled = order.status === 'CANCELLED' || order.status === 'REFUNDED';

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-4xl mx-auto px-4">
        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <Link 
            href="/boutique/orders" 
            className="p-2 hover:bg-gray-100 rounded-lg transition"
          >
            <ArrowLeft className="w-5 h-5 text-gray-600" />
          </Link>
          <div>
            <h1 className="text-2xl font-bold text-gray-900">Order Details</h1>
            <p className="text-sm text-gray-500 font-mono">#{order.orderNumber}</p>
          </div>
        </div>

        {/* Status Banner */}
        {isCancelled ? (
          <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6">
            <div className="flex items-center gap-3">
              <XCircle className="w-6 h-6 text-red-600" />
              <div>
                <h3 className="font-medium text-red-900">
                  Order {order.status === 'REFUNDED' ? 'Refunded' : 'Cancelled'}
                </h3>
                {order.boutiqueRefund && (
                  <p className="text-sm text-red-700">
                    Refund amount: {formatPrice(order.boutiqueRefund.amount)}
                  </p>
                )}
              </div>
            </div>
          </div>
        ) : (
          <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
            <h2 className="text-lg font-semibold text-gray-900 mb-4">Order Status</h2>
            <div className="relative">
              <div className="flex justify-between">
                {STATUS_STEPS.map((step, _idx) => {
                  const isCompleted = currentStatusIndex >= STATUS_ORDER.indexOf(step.key);
                  const isCurrent = order.status === step.key;
                  const Icon = step.icon;
                  
                  return (
                    <div key={step.key} className="flex flex-col items-center flex-1">
                      <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                        isCompleted 
                          ? 'bg-purple-600 text-white' 
                          : 'bg-gray-200 text-gray-400'
                      } ${isCurrent ? 'ring-4 ring-purple-100' : ''}`}>
                        <Icon className="w-5 h-5" />
                      </div>
                      <span className={`mt-2 text-xs text-center ${
                        isCompleted ? 'text-purple-600 font-medium' : 'text-gray-400'
                      }`}>
                        {step.label}
                      </span>
                    </div>
                  );
                })}
              </div>
              {/* Progress Line */}
              <div className="absolute top-5 left-0 right-0 h-0.5 bg-gray-200 -z-10" style={{ marginLeft: '5%', marginRight: '5%' }}>
                <div 
                  className="h-full bg-purple-600 transition-all"
                  style={{ width: `${Math.min(currentStatusIndex / (STATUS_STEPS.length - 1) * 100, 100)}%` }}
                />
              </div>
            </div>
          </div>
        )}

        {/* Tracking Info */}
        {order.trackingNumber && (
          <div className="bg-purple-50 border border-purple-200 rounded-lg p-4 mb-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <Truck className="w-5 h-5 text-purple-600" />
                <div>
                  <h3 className="font-medium text-purple-900">Tracking Number</h3>
                  <p className="font-mono text-purple-700">{order.trackingNumber}</p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => copyToClipboard(order.trackingNumber!, 'Tracking number')}
                  className="p-2 hover:bg-purple-100 rounded-lg transition"
                  aria-label="Copy tracking number"
                >
                  <Copy className="w-4 h-4 text-purple-600" />
                </button>
                {order.trackingUrl && (
                  <a
                    href={order.trackingUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="p-2 hover:bg-purple-100 rounded-lg transition"
                    aria-label="Track shipment on carrier website"
                  >
                    <ExternalLink className="w-4 h-4 text-purple-600" />
                  </a>
                )}
              </div>
            </div>
          </div>
        )}

        <div className="grid md:grid-cols-2 gap-6">
          {/* Order Items */}
          <div className="bg-white rounded-lg shadow-sm p-6">
            <h2 className="text-lg font-semibold text-gray-900 mb-4">
              Items ({order.items.length})
            </h2>
            <div className="space-y-4">
              {order.items.map((item) => (
                <div key={item.id} className="flex gap-4">
                  <Link href={`/boutique/${item.product.slug}`}>
                    <div className="w-20 h-20 rounded-lg overflow-hidden bg-gray-100 relative shrink-0">
                      {item.product.thumbnailUrl ? (
                        <Image
                          src={item.product.thumbnailUrl}
                          alt={item.product.title}
                          fill
                          className="object-cover"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center">
                          <Package className="w-8 h-8 text-gray-300" />
                        </div>
                      )}
                    </div>
                  </Link>
                  <div className="flex-1 min-w-0">
                    <Link 
                      href={`/boutique/${item.product.slug}`}
                      className="font-medium text-gray-900 hover:text-purple-600 line-clamp-1"
                    >
                      {item.product.title}
                    </Link>
                    {item.variantSnapshot && (
                      <p className="text-sm text-gray-900">
                        {item.variantSnapshot.size && `Size: ${item.variantSnapshot.size}`}
                        {item.variantSnapshot.size && item.variantSnapshot.color && ' ΓÇó '}
                        {item.variantSnapshot.color && `Color: ${item.variantSnapshot.color}`}
                      </p>
                    )}
                    <p className="text-sm text-gray-900">Qty: {item.quantity}</p>
                    <p className="font-medium text-gray-900 mt-1">
                      {formatPrice(item.finalPrice)}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Order Summary */}
          <div className="space-y-6">
            {/* Pricing */}
            <div className="bg-white rounded-lg shadow-sm p-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">Order Summary</h2>
              <div className="space-y-2 text-sm">
                <div className="flex justify-between">
                  <span className="text-gray-900">Subtotal</span>
                  <span className="text-gray-900">{formatPrice(order.subtotal)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-900">Shipping</span>
                  <span className="text-gray-900">{formatPrice(order.shippingCost)}</span>
                </div>
                {order.discount > 0 && (
                  <div className="flex justify-between text-green-600">
                    <span>Discount</span>
                    <span>-{formatPrice(order.discount)}</span>
                  </div>
                )}
                <div className="border-t pt-2 flex justify-between font-semibold text-base">
                  <span>Total</span>
                  <span className="text-purple-600">{formatPrice(order.total)}</span>
                </div>
              </div>
            </div>

            {/* Shipping Address */}
            <div className="bg-white rounded-lg shadow-sm p-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">Shipping Address</h2>
              <div className="space-y-2 text-sm">
                <div className="flex items-center gap-2">
                  <User className="w-4 h-4 text-gray-900" />
                  <span className="text-gray-900">{order.shippingAddress.name}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Phone className="w-4 h-4 text-gray-900" />
                  <span className="text-gray-900">{order.shippingAddress.phone}</span>
                </div>
                <div className="flex items-start gap-2">
                  <MapPin className="w-4 h-4 text-gray-900 mt-0.5" />
                  <span className="text-gray-900">
                    {order.shippingAddress.street}<br />
                    {order.shippingAddress.city}, {order.shippingAddress.state}<br />
                    {order.shippingAddress.country}
                  </span>
                </div>
              </div>
            </div>

            {/* Timeline */}
            <div className="bg-white rounded-lg shadow-sm p-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">Timeline</h2>
              <div className="space-y-3 text-sm">
                <div className="flex justify-between">
                  <span className="text-gray-900">Order Placed</span>
                  <span className="text-gray-900">{formatDate(order.createdAt)}</span>
                </div>
                {order.paidAt && (
                  <div className="flex justify-between">
                    <span className="text-gray-900">Payment Confirmed</span>
                    <span className="text-gray-900">{formatDate(order.paidAt)}</span>
                  </div>
                )}
                {order.shippedAt && (
                  <div className="flex justify-between">
                    <span className="text-gray-900">Shipped</span>
                    <span className="text-gray-900">{formatDate(order.shippedAt)}</span>
                  </div>
                )}
                {order.deliveredAt && (
                  <div className="flex justify-between">
                    <span className="text-gray-900">Delivered</span>
                    <span className="text-gray-900">{formatDate(order.deliveredAt)}</span>
                  </div>
                )}
                {order.completedAt && (
                  <div className="flex justify-between">
                    <span className="text-gray-900">Completed</span>
                    <span className="text-gray-900">{formatDate(order.completedAt)}</span>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Help Section */}
        <div className="mt-6 bg-amber-50 border border-amber-200 rounded-lg p-4">
          <div className="flex items-start gap-3">
            <AlertCircle className="w-5 h-5 text-amber-600 mt-0.5" />
            <div>
              <h3 className="font-medium text-amber-900">Need Help?</h3>
              <p className="text-sm text-amber-700 mt-1">
                If you have any issues with your order, please{' '}
                <Link href="/contact" className="underline">contact our support team</Link>.
              </p>
            </div>
          </div>
        </div>

        {/* Action Buttons - Confirm Delivery / Request Return */}
        {!isCancelled && (
          <div className="mt-6 flex flex-col sm:flex-row gap-3">
            {/* Confirm Delivery - Only show when DELIVERED status */}
            {order.status === 'DELIVERED' && (
              <button
                onClick={confirmDelivery}
                disabled={confirming}
                className="flex-1 flex items-center justify-center gap-2 bg-green-600 text-white py-3 px-6 rounded-lg hover:bg-green-700 disabled:opacity-50 font-medium"
              >
                <CheckCircle className="w-5 h-5" />
                {confirming ? 'Confirming...' : 'Confirm Delivery'}
              </button>
            )}

            {/* Request Return - Show for DELIVERED or COMPLETED orders */}
            {(order.status === 'DELIVERED' || order.status === 'COMPLETED') && !order.boutiqueReturn && (() => {
              const returnWindow = getReturnWindowInfo(order.deliveredAt);
              return returnWindow.isOpen ? (
                <button
                  onClick={() => setShowReturnModal(true)}
                  className="flex-1 flex flex-col items-center justify-center gap-1 border-2 border-amber-300 bg-amber-50 text-amber-900 py-3 px-6 rounded-lg hover:bg-amber-100 font-medium"
                >
                  <div className="flex items-center gap-2">
                    <RotateCcw className="w-5 h-5" />
                    Request Return
                  </div>
                  <span className="text-xs font-normal">
                    {returnWindow.daysRemaining} day{returnWindow.daysRemaining !== 1 ? 's' : ''} remaining
                  </span>
                </button>
              ) : (
                <div className="flex-1 flex flex-col items-center justify-center gap-1 border-2 border-gray-200 bg-gray-50 text-gray-500 py-3 px-6 rounded-lg font-medium cursor-not-allowed">
                  <div className="flex items-center gap-2">
                    <RotateCcw className="w-5 h-5" />
                    Return window closed
                  </div>
                  <span className="text-xs font-normal">
                    (7 days from delivery)
                  </span>
                </div>
              );
            })()}

            {/* Leave Review - Show for COMPLETED orders */}
            {order.status === 'COMPLETED' && (
              <Link
                href={`/boutique/${order.items[0]?.product.slug}#reviews`}
                className="flex-1 flex items-center justify-center gap-2 bg-purple-600 text-white py-3 px-6 rounded-lg hover:bg-purple-700 font-medium"
              >
                <Star className="w-5 h-5" />
                Leave a Review
              </Link>
            )}
          </div>
        )}

        {/* Return Status Banner */}
        {order.boutiqueReturn && (
          <div className="mt-6 bg-blue-50 border border-blue-200 rounded-lg p-4">
            <div className="flex items-center gap-3">
              <RotateCcw className="w-5 h-5 text-blue-600" />
              <div>
                <h3 className="font-medium text-blue-900">Return Request</h3>
                <p className="text-sm text-blue-700">
                  Status: {order.boutiqueReturn.status.replace(/_/g, ' ')}
                </p>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Return Request Modal */}
      {showReturnModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-md w-full p-6">
            <h2 className="text-xl font-bold text-gray-900 mb-4">Request Return</h2>
            
            <div className="space-y-4">
              <div>
                <label htmlFor="returnItemSelect" className="block text-sm font-medium text-gray-700 mb-1">
                  Select Item
                </label>
                <select
                  id="returnItemSelect"
                  value={selectedItemId}
                  onChange={(e) => setSelectedItemId(e.target.value)}
                  className="w-full border rounded-lg px-3 py-2 text-gray-900"
                >
                  <option value="" className="text-gray-900">Choose an item...</option>
                  {order.items.map((item) => (
                    <option key={item.id} value={item.id} className="text-gray-900">
                      {item.product.title} (Qty: {item.quantity})
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label htmlFor="returnReasonSelect" className="block text-sm font-medium text-gray-700 mb-1">
                  Reason for Return
                </label>
                <select
                  id="returnReasonSelect"
                  value={returnReason}
                  onChange={(e) => setReturnReason(e.target.value)}
                  className="w-full border rounded-lg px-3 py-2 text-gray-900"
                >
                  <option value="" className="text-gray-900">Select a reason...</option>
                  <option value="WRONG_SIZE" className="text-gray-900">Wrong Size</option>
                  <option value="DEFECTIVE" className="text-gray-900">Defective/Damaged</option>
                  <option value="NOT_AS_DESCRIBED" className="text-gray-900">Not as Described</option>
                  <option value="WRONG_ITEM" className="text-gray-900">Wrong Item Received</option>
                  <option value="CHANGED_MIND" className="text-gray-900">Changed My Mind</option>
                  <option value="OTHER" className="text-gray-900">Other</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Description <span className="text-red-500">*</span>
                </label>
                <textarea
                  value={returnDescription}
                  onChange={(e) => setReturnDescription(e.target.value)}
                  rows={3}
                  className="w-full border rounded-lg px-3 py-2 text-gray-900"
                  placeholder="Provide details about your return request..."
                />
              </div>
            </div>

            <div className="flex gap-3 mt-6">
              <button
                onClick={() => setShowReturnModal(false)}
                className="flex-1 border border-gray-300 text-gray-700 py-2 rounded-lg hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                onClick={submitReturnRequest}
                disabled={confirming || !returnReason || !selectedItemId || !returnDescription.trim()}
                className="flex-1 bg-purple-600 text-white py-2 rounded-lg hover:bg-purple-700 disabled:opacity-50"
              >
                {confirming ? 'Submitting...' : 'Submit Request'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useSession } from 'next-auth/react';
import Link from 'next/link';
import Image from 'next/image';
import { 
  Package, 
  ArrowLeft, 
  Truck,
  CheckCircle,
  Clock,
  XCircle,
  ChevronRight,
  ShoppingBag,
  Filter,
} from 'lucide-react';

interface OrderItem {
  id: string;
  quantity: number;
  price: number;
  finalPrice: number;
  variantSnapshot: { size?: string; color?: string } | null;
  product: {
    id: string;
    title: string;
    slug: string;
    thumbnailUrl: string | null;
  };
}

interface Order {
  id: string;
  orderNumber: string;
  status: string;
  total: number;
  subtotal: number;
  shippingCost: number;
  discount: number;
  trackingNumber: string | null;
  trackingUrl: string | null;
  createdAt: string;
  shippedAt: string | null;
  deliveredAt: string | null;
  items: OrderItem[];
  seller: {
    name: string | null;
    displayName: string | null;
  };
}

const STATUS_CONFIG: Record<string, { label: string; color: string; icon: typeof Clock }> = {
  PENDING_PAYMENT: { label: 'Pending Payment', color: 'text-yellow-600 bg-yellow-50', icon: Clock },
  PAID: { label: 'Paid', color: 'text-blue-600 bg-blue-50', icon: CheckCircle },
  PROCESSING: { label: 'Processing', color: 'text-indigo-600 bg-indigo-50', icon: Package },
  SHIPPED: { label: 'Shipped', color: 'text-purple-600 bg-purple-50', icon: Truck },
  DELIVERED: { label: 'Delivered', color: 'text-green-600 bg-green-50', icon: CheckCircle },
  COMPLETED: { label: 'Completed', color: 'text-green-600 bg-green-50', icon: CheckCircle },
  CANCELLED: { label: 'Cancelled', color: 'text-red-600 bg-red-50', icon: XCircle },
  REFUNDED: { label: 'Refunded', color: 'text-gray-600 bg-gray-50', icon: XCircle },
};

export default function BoutiqueOrdersPage() {
  const { data: session, status: authStatus } = useSession();
  const router = useRouter();
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState('');
  const [expandedOrderId, setExpandedOrderId] = useState<string | null>(null);
  const [pagination, setPagination] = useState({ page: 1, totalPages: 1, total: 0 });

  useEffect(() => {
    if (authStatus === 'unauthenticated') {
      router.push('/auth/signin?callbackUrl=/boutique/orders');
    } else if (authStatus === 'authenticated') {
      fetchOrders();
    }
  }, [authStatus, router, statusFilter]);

  const fetchOrders = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (statusFilter) params.set('status', statusFilter);
      
      const response = await fetch(`/api/boutique/orders?${params.toString()}`);
      const data = await response.json();
      
      if (data.success) {
        setOrders(data.orders);
        setPagination(data.pagination);
      }
    } catch (error) {
      console.error('Error fetching orders:', error);
    } finally {
      setLoading(false);
    }
  };

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat('en-NG', {
      style: 'currency',
      currency: 'NGN',
      minimumFractionDigits: 0,
    }).format(price);
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-NG', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  };

  if (authStatus === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin h-8 w-8 border-4 border-purple-500 border-t-transparent rounded-full"></div>
      </div>
    );
  }

  if (!session) return null;

  return (
    <div className="min-h-screen bg-gray-50 py-3 sm:py-6">
      <div className="max-w-4xl mx-auto px-3 sm:px-4">
        {/* Header */}
        <div className="flex items-center gap-2 sm:gap-3 mb-3 sm:mb-5">
          <Link 
            href="/boutique" 
            className="p-1 sm:p-1.5 hover:bg-gray-100 rounded-lg transition flex-shrink-0"
          >
            <ArrowLeft className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-gray-600" />
          </Link>
          <div className="min-w-0">
            <h1 className="text-sm sm:text-lg font-bold text-gray-900 flex items-center gap-1 sm:gap-2">
              <Package className="w-4 h-4 sm:w-5 sm:h-5 text-purple-600 flex-shrink-0" />
              <span className="truncate">My Boutique Orders</span>
            </h1>
            <p className="text-[8px] sm:text-xs text-gray-500 mt-0.5">
              Track your physical item orders
            </p>
          </div>
        </div>

        {/* Filter */}
        <div className="bg-white rounded shadow-sm p-2 sm:p-3 mb-3 sm:mb-4">
          <div className="flex items-center gap-1.5 sm:gap-3">
            <Filter className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-gray-400 flex-shrink-0" />
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="flex-1 px-2 sm:px-3 py-1 sm:py-1.5 border border-gray-200 rounded text-[9px] sm:text-xs text-gray-900"
              aria-label="Filter orders by status"
            >
              <option value="">All Orders</option>
              <option value="PAID">Paid</option>
              <option value="PROCESSING">Processing</option>
              <option value="SHIPPED">Shipped</option>
              <option value="DELIVERED">Delivered</option>
              <option value="COMPLETED">Completed</option>
              <option value="CANCELLED">Cancelled</option>
            </select>
            <span className="text-[8px] sm:text-xs text-gray-500 flex-shrink-0 whitespace-nowrap">
              {pagination.total} order{pagination.total !== 1 ? 's' : ''}
            </span>
          </div>
        </div>

        {orders.length === 0 ? (
          <div className="bg-white rounded shadow-sm p-6 sm:p-8 text-center">
            <ShoppingBag className="w-10 h-10 sm:w-12 sm:h-12 text-gray-300 mx-auto mb-2 sm:mb-3" />
            <h2 className="text-sm sm:text-base font-semibold text-gray-900 mb-1">No orders yet</h2>
            <p className="text-[8px] sm:text-xs text-gray-500 mb-3 sm:mb-4">Start shopping in our boutique</p>
            <Link
              href="/boutique"
              className="inline-flex items-center gap-1.5 bg-purple-600 text-white px-3 sm:px-4 py-1.5 sm:py-2 rounded hover:bg-purple-700 transition text-[9px] sm:text-xs font-medium"
            >
              <Package className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
              Browse Boutique
            </Link>
          </div>
        ) : (
          <div className="space-y-1.5 sm:space-y-2">
            {orders.map((order) => {
              const statusConfig = STATUS_CONFIG[order.status] || STATUS_CONFIG.PROCESSING;
              const StatusIcon = statusConfig.icon;
              const isExpanded = expandedOrderId === order.id;
              
              return (
                <div
                  key={order.id}
                  className="bg-white rounded shadow-sm overflow-hidden"
                >
                  {/* Order Header - Clickable to expand */}
                  <button
                    onClick={() => setExpandedOrderId(isExpanded ? null : order.id)}
                    className="w-full p-2 sm:p-3 flex items-center justify-between gap-1.5 hover:bg-gray-50 transition"
                  >
                    <div className="flex-1 min-w-0 text-left">
                      <span className="font-mono text-[9px] sm:text-xs text-gray-500">
                        #{order.orderNumber}
                      </span>
                      <div className="flex flex-wrap items-center gap-1 sm:gap-1.5 mt-0.5">
                        <span className="text-[8px] sm:text-xs text-gray-500">{formatDate(order.createdAt)}</span>
                        <span className="font-semibold text-[9px] sm:text-xs text-purple-600">{formatPrice(order.total)}</span>
                      </div>
                    </div>
                    <div className="flex items-center gap-1 sm:gap-1.5 flex-shrink-0">
                      <span className={`inline-flex items-center gap-0.5 px-1 sm:px-1.5 py-0.5 rounded-full text-[7px] sm:text-[10px] font-medium ${statusConfig.color}`}>
                        <StatusIcon className="w-2 h-2 sm:w-2.5 sm:h-2.5" />
                        <span className="hidden sm:inline">{statusConfig.label}</span>
                      </span>
                      <ChevronRight className={`w-3.5 h-3.5 sm:w-4 sm:h-4 text-gray-400 transition-transform flex-shrink-0 ${isExpanded ? 'rotate-90' : ''}`} />
                    </div>
                  </button>
                  
                  {/* Expanded Content */}
                  {isExpanded && (
                    <div className="px-2 sm:px-3 pb-2 sm:pb-3 border-t border-gray-100">
                      {/* Product Items */}
                      <p className="text-[8px] sm:text-[9px] text-gray-500 pt-1.5 mb-1.5">Click an item to view details:</p>
                      <div className="space-y-1.5">
                        {order.items.map((item) => (
                          <Link 
                            key={item.id} 
                            href={`/boutique/products/${item.product.slug}`}
                            className="flex items-start gap-1.5 sm:gap-2 bg-gray-50 rounded p-1.5 hover:bg-gray-100 hover:shadow-sm transition-all"
                          >
                            <div className="w-10 h-10 sm:w-12 sm:h-12 rounded overflow-hidden bg-gray-100 relative flex-shrink-0">
                              {item.product.thumbnailUrl ? (
                                <Image
                                  src={item.product.thumbnailUrl}
                                  alt={item.product.title}
                                  fill
                                  className="object-cover"
                                />
                              ) : (
                                <div className="w-full h-full flex items-center justify-center">
                                  <Package className="w-4 h-4 text-gray-300" />
                                </div>
                              )}
                            </div>
                            <div className="flex-1 min-w-0">
                              <p className="text-[9px] sm:text-xs font-medium text-gray-900 line-clamp-2">{item.product.title}</p>
                              {item.variantSnapshot && (
                                <p className="text-[8px] sm:text-[9px] text-gray-500 mt-0.5">
                                  {item.variantSnapshot.size && `Size: ${item.variantSnapshot.size}`}
                                  {item.variantSnapshot.size && item.variantSnapshot.color && ' ΓÇó '}
                                  {item.variantSnapshot.color && `Color: ${item.variantSnapshot.color}`}
                                </p>
                              )}
                              <p className="text-[8px] sm:text-[9px] text-gray-500">Qty: {item.quantity}</p>
                            </div>
                            <div className="flex items-center gap-0.5 flex-shrink-0">
                              <p className="font-semibold text-[9px] sm:text-xs text-gray-900">{formatPrice(item.finalPrice)}</p>
                              <ChevronRight className="w-3 h-3 text-gray-400" />
                            </div>
                          </Link>
                        ))}
                      </div>
                      
                      {/* Seller & Tracking */}
                      <div className="flex flex-wrap items-center justify-between gap-1.5 pt-1.5 border-t border-gray-100">
                        <p className="text-[8px] sm:text-[9px] text-gray-500">
                          From {order.seller.displayName || order.seller.name || 'Seller'}
                        </p>
                        {order.trackingNumber && (
                          <div className="flex items-center gap-0.5 text-[8px] sm:text-[9px]">
                            <Truck className="w-2.5 h-2.5 sm:w-3 sm:h-3 text-purple-600" />
                            <span className="text-gray-600">Track:</span>
                            <span className="font-mono text-purple-600">{order.trackingNumber}</span>
                          </div>
                        )}
                      </div>
                      
                      {/* View Details Link */}
                      <Link
                        href={`/boutique/orders/${order.orderNumber}`}
                        className="mt-1.5 sm:mt-2 w-full flex items-center justify-center gap-0.5 px-2 sm:px-3 py-1 sm:py-1.5 bg-purple-600 text-white rounded hover:bg-purple-700 transition text-[9px] sm:text-xs font-medium"
                      >
                        View Details
                        <ChevronRight className="w-2.5 h-2.5 sm:w-3 sm:h-3" />
                      </Link>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, Suspense } from 'react';
import { CategorySidebar } from '@/components/ui/CategorySidebar';
import { useSearchParams } from 'next/navigation';
import Image from 'next/image';
import Link from 'next/link';
import {
  Search,
  Filter,
  ChevronLeft,
  ChevronRight,
  Star,
  Heart,
  ShoppingBag,
  Grid3X3,
  LayoutGrid,
  X,
  Rocket,
} from 'lucide-react';
import { 
  GENDER_OPTIONS, 
  STYLES, 
  PRODUCT_CONDITION,
  FULFILLMENT_METHOD,
} from '@/lib/boutique/constants';
import '@/app/color-swatch.css';

interface Product {
  id: string;
  title: string;
  slug: string;
  basePrice: number;
  salePrice: number | null;
  thumbnailUrl: string;
  category: { name: string; slug: string };
  brand: string;
  seller: { name: string };
  reviewCount: number;
  avgRating: number | null;
  availableSizes: string[];
  availableColors: { color: string; hex: string }[];
  fulfillmentMethod?: string;
  sellerShippingTime?: string;
}

interface Category {
  id: string;
  name: string;
  slug: string;
  children?: Category[];
}

const SORT_OPTIONS = [
  { value: 'newest', label: 'Newest' },
  { value: 'popular', label: 'Popular' },
  { value: 'price_low', label: 'Price: Low to High' },
  { value: 'price_high', label: 'Price: High to Low' },
];

// Loading fallback for Suspense
function BoutiqueLoading() {
  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center">
      <div className="animate-spin h-8 w-8 border-4 border-purple-600 border-t-transparent rounded-full"></div>
    </div>
  );
}

function BoutiqueShopContent() {
  const searchParams = useSearchParams();

  const [loading, setLoading] = useState(true);
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [pagination, setPagination] = useState({ page: 1, totalPages: 1, total: 0 });
  const [showFilters, setShowFilters] = useState(false);
  const [showCategorySidebar, setShowCategorySidebar] = useState(false);
  const [expandedParentCategory, setExpandedParentCategory] = useState<string | null>(null);
  const [categoryOnSidebarOpen, setCategoryOnSidebarOpen] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'large'>('grid');

  // Filters
  const [searchQuery, setSearchQuery] = useState(searchParams.get('search') || '');
  const [selectedCategory, setSelectedCategory] = useState<string | null>(searchParams.get('category') || null);
  const [selectedGender, setSelectedGender] = useState(searchParams.get('gender') || '');
  const [selectedStyle, setSelectedStyle] = useState(searchParams.get('style') || '');
  const [selectedCondition, setSelectedCondition] = useState(searchParams.get('condition') || '');
  const [minPrice, setMinPrice] = useState(searchParams.get('minPrice') || '');
  const [maxPrice, setMaxPrice] = useState(searchParams.get('maxPrice') || '');
  const [sortBy, setSortBy] = useState(searchParams.get('sort') || 'newest');
  const [page, setPage] = useState(parseInt(searchParams.get('page') || '1'));

  useEffect(() => {
    fetchCategories();
  }, []);

  useEffect(() => {
    fetchProducts();
  }, [page, sortBy, selectedCategory, selectedGender, selectedStyle, selectedCondition, minPrice, maxPrice]);

  const fetchCategories = async () => {
    try {
      // Fetch categories with parent-child relationships
      const response = await fetch('/api/boutique/categories');
      const data = await response.json();
      if (data.success) {
        setCategories(data.categories);
      }
    } catch (error) {
      console.error('Failed to fetch categories:', error);
    }
  };

  const fetchProducts = async () => {
    try {
      setLoading(true);
      
      const params = new URLSearchParams();
      params.set('page', page.toString());
      params.set('sort', sortBy);
      if (searchQuery) params.set('search', searchQuery);
      if (selectedCategory) params.set('category', selectedCategory);
      if (selectedGender) params.set('gender', selectedGender);
      if (selectedStyle) params.set('style', selectedStyle);
      if (selectedCondition) params.set('condition', selectedCondition);
      if (minPrice) params.set('minPrice', minPrice);
      if (maxPrice) params.set('maxPrice', maxPrice);

      const response = await fetch(`/api/boutique/shop?${params.toString()}`);
      const data = await response.json();

      if (data.success) {
        setProducts(data.products);
        setPagination(data.pagination);
      }
    } catch (error) {
      console.error('Failed to fetch products:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    setPage(1);
    fetchProducts();
  };

  const clearFilters = () => {
    setSelectedCategory(null);
    setSelectedGender('');
    setSelectedStyle('');
    setSelectedCondition('');
    setMinPrice('');
    setMaxPrice('');
    setPage(1);
    setExpandedParentCategory(null);
    setCategoryOnSidebarOpen(null);
  };

  const hasActiveFilters = selectedCategory || selectedGender || selectedStyle || selectedCondition || minPrice || maxPrice;


  return (
    <div className="min-h-screen bg-gray-50">
      {/* Hero Banner */}
      <div className="bg-gradient-to-r from-purple-600 to-pink-600 text-white">
        <div className="max-w-7xl mx-auto px-3 sm:px-4 py-6 sm:py-12">
          <h1 className="text-xl sm:text-4xl font-bold mb-1 sm:mb-2">Fashion Boutique</h1>
          <p className="text-purple-100 text-xs sm:text-lg">Verified fashion items, ready to ship</p>
        </div>
      </div>

      {/* Search & Filters Bar */}
      <div className="bg-white border-b sticky top-0 z-20">
        <div className="max-w-7xl mx-auto px-3 sm:px-4 py-2.5 sm:py-4">
          <div className="flex flex-col md:flex-row items-center gap-2 sm:gap-4">
            {/* Search */}
            <form onSubmit={handleSearch} className="flex-1 w-full">
              <div className="relative">
                <Search className="absolute left-2.5 sm:left-3 top-1/2 -translate-y-1/2 w-4 h-4 sm:w-5 sm:h-5 text-gray-400" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search dresses, bags, shoes..."
                  className="w-full pl-8 sm:pl-10 pr-3 sm:pr-4 py-1.5 sm:py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-500 text-gray-900 text-xs sm:text-sm"
                />
              </div>
            </form>

            {/* Sort & View */}
            <div className="flex items-center gap-1 sm:gap-3 w-full md:w-auto">
              <button
                onClick={() => setShowFilters(!showFilters)}
                className={`flex items-center gap-1 sm:gap-2 px-1.5 sm:px-4 py-1.5 sm:py-2 border rounded-lg text-[10px] sm:text-sm ${
                  hasActiveFilters ? 'border-purple-500 text-purple-600 bg-purple-50' : 'border-gray-200 text-gray-900'
                }`}
              >
                <Filter className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                Filters
                {hasActiveFilters && (
                  <span className="w-4 h-4 sm:w-5 sm:h-5 bg-purple-600 text-white text-[10px] sm:text-xs rounded-full flex items-center justify-center">
                    !
                  </span>
                )}
              </button>

              {/* Categories Button (Mobile) */}
              <button
                onClick={() => {
                  setCategoryOnSidebarOpen(selectedCategory);
                  setShowCategorySidebar(!showCategorySidebar);
                }}
                className={`lg:hidden flex items-center gap-1 px-2 sm:px-3 py-1.5 border rounded-lg text-[10px] sm:text-xs transition-all ${
                  selectedCategory 
                    ? 'border-purple-500 text-purple-600 bg-purple-50' 
                    : 'border-gray-200 text-gray-900 hover:border-purple-500'
                }`}
              >
                <span className="font-semibold truncate max-w-[80px] sm:max-w-[120px]">
                  {selectedCategory 
                    ? (() => {
                        // Find the selected category name
                        for (const parent of categories) {
                          if (parent.slug === selectedCategory) return parent.name;
                          if (parent.children) {
                            for (const child of parent.children) {
                              if (child.slug === selectedCategory) return child.name;
                            }
                          }
                        }
                        return 'Categories';
                      })()
                    : 'Categories'
                  }
                </span>
              </button>

              <select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value)}
                className="px-1.5 sm:px-3 py-1.5 sm:py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-500 text-gray-900 text-[11px] sm:text-sm"
                aria-label="Sort products by"
              >
                {SORT_OPTIONS.map(opt => (
                  <option key={opt.value} value={opt.value} className="text-gray-900">{opt.label}</option>
                ))}
              </select>

              <div className="hidden md:flex items-center gap-1 border border-gray-200 rounded-lg p-1">
                <button
                  onClick={() => setViewMode('grid')}
                  className={`p-1.5 rounded ${viewMode === 'grid' ? 'bg-gray-100' : ''}`}
                  aria-label="Grid view"
                >
                  <Grid3X3 className="w-4 h-4" />
                </button>
                <button
                  onClick={() => setViewMode('large')}
                  className={`p-1.5 rounded ${viewMode === 'large' ? 'bg-gray-100' : ''}`}
                  aria-label="Large view"
                >
                  <LayoutGrid className="w-4 h-4" />
                </button>
              </div>
            </div>
          </div>

          {/* Filters Panel */}
          {showFilters && (
            <div className="mt-3 sm:mt-4 pt-3 sm:pt-4 border-t grid grid-cols-2 md:grid-cols-6 gap-2 sm:gap-4">
              <select
                value={selectedCategory || ''}
                onChange={(e) => { setSelectedCategory(e.target.value || null); setPage(1); }}
                className="px-2 sm:px-3 py-1.5 sm:py-2 border border-gray-200 rounded-lg text-xs sm:text-sm text-gray-900"
                aria-label="Filter by category"
              >
                <option value="" className="text-gray-900">All Categories</option>
                {categories.map(cat => (
                  <option key={cat.id} value={cat.slug} className="text-gray-900">
                    {cat.name}
                  </option>
                ))}
              </select>

              <select
                value={selectedGender}
                onChange={(e) => { setSelectedGender(e.target.value); setPage(1); }}
                className="px-2 sm:px-3 py-1.5 sm:py-2 border border-gray-200 rounded-lg text-xs sm:text-sm text-gray-900"
                aria-label="Filter by gender"
              >
                <option value="" className="text-gray-900">All Genders</option>
                {GENDER_OPTIONS.map(g => (
                  <option key={g} value={g} className="text-gray-900">{g}</option>
                ))}
              </select>

              <select
                value={selectedStyle}
                onChange={(e) => { setSelectedStyle(e.target.value); setPage(1); }}
                className="px-2 sm:px-3 py-1.5 sm:py-2 border border-gray-200 rounded-lg text-xs sm:text-sm text-gray-900"
                aria-label="Filter by style"
              >
                <option value="" className="text-gray-900">All Styles</option>
                {STYLES.map(s => (
                  <option key={s} value={s} className="text-gray-900">{s}</option>
                ))}
              </select>

              <select
                value={selectedCondition}
                onChange={(e) => { setSelectedCondition(e.target.value); setPage(1); }}
                className="px-2 sm:px-3 py-1.5 sm:py-2 border border-gray-200 rounded-lg text-xs sm:text-sm text-gray-900"
                aria-label="Filter by condition"
              >
                <option value="" className="text-gray-900">All Conditions</option>
                {Object.entries(PRODUCT_CONDITION).map(([key, label]) => (
                  <option key={key} value={key} className="text-gray-900">{label}</option>
                ))}
              </select>

              <div className="flex gap-1.5 sm:gap-2">
                <input
                  type="number"
                  placeholder="Min Γéª"
                  value={minPrice}
                  onChange={(e) => setMinPrice(e.target.value)}
                  className="w-full px-2 sm:px-3 py-1.5 sm:py-2 border border-gray-200 rounded-lg text-xs sm:text-sm text-gray-900"
                />
                <input
                  type="number"
                  placeholder="Max Γéª"
                  value={maxPrice}
                  onChange={(e) => setMaxPrice(e.target.value)}
                  className="w-full px-2 sm:px-3 py-1.5 sm:py-2 border border-gray-200 rounded-lg text-xs sm:text-sm text-gray-900"
                />
              </div>

              {hasActiveFilters && (
                <button
                  onClick={clearFilters}
                  className="flex items-center justify-center gap-1 text-xs sm:text-sm text-purple-600 hover:text-purple-700"
                >
                  <X className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                  Clear All
                </button>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Products Grid with Sidebar */}
      <div className="max-w-7xl mx-auto px-3 sm:px-4 py-4 sm:py-8 flex flex-col lg:flex-row gap-4 sm:gap-6 relative">
        {/* Sidebar - Left overlay on mobile, visible on desktop */}
        {showCategorySidebar && (
          <div 
            className="fixed inset-0 bg-black/40 z-30 lg:hidden" 
            onClick={() => {
              // If a parent is expanded and no child was selected (selected category unchanged from sidebar open), select the parent
              if (expandedParentCategory && selectedCategory === categoryOnSidebarOpen) {
                setSelectedCategory(expandedParentCategory);
                setPage(1);
              }
              setShowCategorySidebar(false);
              setExpandedParentCategory(null);
              setCategoryOnSidebarOpen(null);
            }} 
          />
        )}
        
        <div className={`${
          showCategorySidebar 
            ? 'fixed left-0 top-0 h-full w-80 z-40 lg:relative lg:inset-auto lg:top-auto lg:h-auto lg:w-56 shadow-2xl lg:shadow-sm' 
            : 'hidden lg:block'
        } flex-shrink-0 overflow-y-auto lg:overflow-visible`}>
          <CategorySidebar
            categories={categories}
            selected={selectedCategory}
            onSelect={slug => {
              setSelectedCategory(slug);
              setPage(1);
              setShowCategorySidebar(false);
              setExpandedParentCategory(null);
              setCategoryOnSidebarOpen(null);
            }}
            onParentExpanded={(parentSlug) => {
              setExpandedParentCategory(parentSlug);
            }}
            isOverlay={showCategorySidebar}
          />
        </div>

        {/* Products Area */}
        <div className="flex-1">
          {loading ? (
            <div className="flex items-center justify-center py-12 sm:py-20">
              <div className="animate-spin rounded-full h-8 w-8 sm:h-12 sm:w-12 border-b-2 border-purple-600"></div>
            </div>
          ) : products.length === 0 ? (
            <div className="text-center py-12 sm:py-20">
              <ShoppingBag className="w-10 h-10 sm:w-16 sm:h-16 text-gray-300 mx-auto mb-3 sm:mb-4" />
              <h3 className="text-base sm:text-xl font-semibold text-gray-900">No Products Found</h3>
              <p className="text-xs sm:text-base text-gray-500 mt-1 sm:mt-2">Try adjusting your filters or search terms</p>
              {hasActiveFilters && (
                <button
                  onClick={clearFilters}
                  className="mt-3 sm:mt-4 px-3 sm:px-4 py-1.5 sm:py-2 bg-purple-600 text-white rounded-lg text-sm"
                >
                  Clear Filters
                </button>
              )}
            </div>
          ) : (
            <>
              <p className="text-xs sm:text-sm text-gray-500 mb-2 sm:mb-4">
                Showing {products.length} of {pagination.total} products
              </p>

              <div className={`grid gap-2 sm:gap-3 ${
                viewMode === 'grid' 
                  ? 'grid-cols-2 md:grid-cols-3 lg:grid-cols-4' 
                  : 'grid-cols-1 md:grid-cols-2'
              }`}>
                {products.map(product => (
                  <Link
                    key={product.id}
                    href={`/boutique/${product.slug}`}
                    className="bg-white rounded-lg overflow-hidden shadow-sm hover:shadow-md transition-shadow group"
                  >
                    {/* Image */}
                    <div className={`relative ${viewMode === 'grid' ? 'aspect-square' : 'aspect-[4/3]'} bg-gray-100`}>
                      {product.thumbnailUrl ? (
                        <Image
                          src={product.thumbnailUrl}
                          alt={product.title}
                          fill
                          className="object-cover group-hover:scale-105 transition-transform duration-300"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center">
                          <ShoppingBag className="w-8 h-8 sm:w-12 sm:h-12 text-gray-300" />
                        </div>
                      )}
                      
                      {/* Sale Badge */}
                      {product.salePrice && (
                        <div className="absolute top-1.5 sm:top-3 left-1.5 sm:left-3 bg-red-500 text-white text-[10px] sm:text-xs font-bold px-1.5 sm:px-2 py-0.5 sm:py-1 rounded">
                          SALE
                        </div>
                      )}

                      {/* Wishlist Button */}
                      <button
                        onClick={(e) => { e.preventDefault(); }}
                        className="absolute top-1.5 sm:top-3 right-1.5 sm:right-3 p-1.5 sm:p-2 bg-white rounded-full shadow-md opacity-0 group-hover:opacity-100 transition-opacity"
                        aria-label="Add to wishlist"
                      >
                        <Heart className="w-3 h-3 sm:w-4 sm:h-4 text-gray-600" />
                      </button>

                      {/* Available Colors */}
                      {product.availableColors.length > 0 && (
                        <div className="absolute bottom-1.5 sm:bottom-3 left-1.5 sm:left-3 flex gap-0.5 sm:gap-1">
                          {product.availableColors.slice(0, 4).map((c, i) => (
                            <div
                              key={i}
                              className="w-3 h-3 sm:w-4 sm:h-4 rounded-full border-2 border-white shadow color-swatch"
                              data-color={c.hex || '#ccc'}
                              title={c.color}
                            />
                          ))}
                          {product.availableColors.length > 4 && (
                            <div className="w-3 h-3 sm:w-4 sm:h-4 rounded-full bg-gray-200 border-2 border-white shadow flex items-center justify-center text-[6px] sm:text-[8px] text-gray-600">
                              +{product.availableColors.length - 4}
                            </div>
                          )}
                        </div>
                      )}
                    </div>

                    {/* Info */}
                    <div className="p-2 sm:p-3">
                      <p className="text-[10px] sm:text-xs text-gray-500 mb-0.5">{product.category.name}</p>
                      <h3 className="font-semibold text-xs sm:text-sm text-gray-900 line-clamp-2 mb-1 sm:mb-2">{product.title}</h3>
                      
                      {/* Fulfillment Badge */}
                      {product.fulfillmentMethod === FULFILLMENT_METHOD.SELLER_DIRECT && (
                        <div className="flex items-center gap-1 mb-1 sm:mb-2">
                          <span className="inline-flex items-center gap-0.5 sm:gap-1 px-1 sm:px-2 py-0.5 rounded-full text-[10px] sm:text-xs font-medium bg-purple-100 text-purple-700">
                            <Rocket className="w-2.5 h-2.5 sm:w-3 sm:h-3" />
                            Seller Direct
                          </span>
                          {product.sellerShippingTime && (
                            <span className="text-[10px] sm:text-xs text-gray-500">
                              ΓÇó {product.sellerShippingTime}
                            </span>
                          )}
                        </div>
                      )}
                      
                      {/* Price */}
                      <div className="flex items-center gap-1 sm:gap-2">
                        <span className="text-sm sm:text-lg font-bold text-purple-600">
                          Γéª{(product.salePrice || product.basePrice).toLocaleString()}
                        </span>
                        {product.salePrice && (
                          <span className="text-[10px] sm:text-sm text-gray-400 line-through">
                            Γéª{product.basePrice.toLocaleString()}
                          </span>
                        )}
                      </div>

                      {/* Rating */}
                      {product.reviewCount > 0 && (
                        <div className="flex items-center gap-0.5 sm:gap-1 mt-1 sm:mt-2">
                          <Star className="w-3 h-3 sm:w-4 sm:h-4 text-yellow-400 fill-yellow-400" />
                          <span className="text-[10px] sm:text-sm text-gray-600">
                            {product.avgRating?.toFixed(1)} ({product.reviewCount})
                          </span>
                        </div>
                      )}

                      {/* Sizes */}
                      {product.availableSizes.length > 0 && (
                        <p className="text-[10px] sm:text-xs text-gray-500 mt-1 sm:mt-2">
                          Sizes: {product.availableSizes.slice(0, 4).join(', ')}
                          {product.availableSizes.length > 4 && '...'}
                        </p>
                      )}

                      {/* Add to Cart Button */}
                      <button
                        onClick={(e) => {
                          e.preventDefault();
                          window.location.href = `/boutique/${product.slug}`;
                        }}
                        className="w-full mt-2 sm:mt-3 py-1.5 sm:py-2 bg-purple-600 hover:bg-purple-700 text-white font-semibold rounded-lg text-[11px] sm:text-sm flex items-center justify-center gap-1 sm:gap-2"
                      >
                        <ShoppingBag className="w-3 h-3 sm:w-4 sm:h-4" />
                        Add to Cart
                      </button>
                    </div>
                  </Link>
                ))}
              </div>

              {/* Pagination */}
              {pagination.totalPages > 1 && (
                <div className="flex items-center justify-center gap-2 sm:gap-4 mt-6 sm:mt-12">
                  <button
                    onClick={() => setPage(p => Math.max(1, p - 1))}
                    disabled={page === 1}
                    className="flex items-center gap-0.5 sm:gap-1 px-2 sm:px-4 py-1.5 sm:py-2 border rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed text-xs sm:text-sm"
                  >
                    <ChevronLeft className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                    <span className="hidden sm:inline">Previous</span>
                  </button>
                  
                  <div className="flex items-center gap-1 sm:gap-2">
                    {Array.from({ length: Math.min(5, pagination.totalPages) }, (_, i) => {
                      let pageNum;
                      if (pagination.totalPages <= 5) {
                        pageNum = i + 1;
                      } else if (page <= 3) {
                        pageNum = i + 1;
                      } else if (page >= pagination.totalPages - 2) {
                        pageNum = pagination.totalPages - 4 + i;
                      } else {
                        pageNum = page - 2 + i;
                      }
                      
                      return (
                        <button
                          key={pageNum}
                          onClick={() => setPage(pageNum)}
                          className={`w-7 h-7 sm:w-10 sm:h-10 rounded-lg text-xs sm:text-sm ${
                            page === pageNum
                              ? 'bg-purple-600 text-white'
                              : 'hover:bg-gray-100'
                          }`}
                        >
                          {pageNum}
                        </button>
                      );
                    })}
                  </div>

                  <button
                    onClick={() => setPage(p => Math.min(pagination.totalPages, p + 1))}
                    disabled={page === pagination.totalPages}
                    className="flex items-center gap-0.5 sm:gap-1 px-2 sm:px-4 py-1.5 sm:py-2 border rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed text-xs sm:text-sm"
                  >
                    <span className="hidden sm:inline">Next</span>
                    <ChevronRight className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                  </button>
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

// Wrap content in Suspense for useSearchParams
export default function BoutiqueShopPage() {
  return (
    <Suspense fallback={<BoutiqueLoading />}>
      <BoutiqueShopContent />
    </Suspense>
  );
}

'use client'

import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useEffect, useState, useCallback } from 'react'
import _Link from 'next/link'
import _Image from 'next/image'
import { Plus, AlertCircle, Upload, X, _CheckCircle } from 'lucide-react'

interface ReturnRequest {
  id: string
  orderId: string
  orderNumber: string
  status: 'INITIATED' | 'APPROVED' | 'SHIPPED_BACK' | 'RECEIVED' | 'REFUNDED' | 'REJECTED'
  reason: 'DEFECTIVE' | 'NOT_AS_DESCRIBED' | 'WRONG_SIZE' | 'CHANGED_MIND' | 'DAMAGED' | 'OTHER'
  refundAmount: number
  product: {
    id: string
    title: string
    image: string
    price: number
  }
  seller: {
    id: string
    name: string
    email: string
  }
  createdAt: string
  updatedAt: string
  approvedAt: string | null
  refundedAt: string | null
  shippingLabel: string | null
  trackingNumber: string | null
  notes: string
}

export default function BoutiqueReturnsPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [returns, setReturns] = useState<ReturnRequest[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<string>('all')
  const [showForm, setShowForm] = useState(false)
  const [selectedReturn, setSelectedReturn] = useState<ReturnRequest | null>(null)

  // Return form states
  const [selectedOrder, setSelectedOrder] = useState('')
  const [returnReason, setReturnReason] = useState('')
  const [returnNotes, setReturnNotes] = useState('')
  const [evidence, setEvidence] = useState<File[]>([])

  const fetchReturns = useCallback(async () => {
    try {
      setLoading(true)
      const response = await fetch(`/api/buyer/returns/boutique?status=${filter}`)
      if (response.ok) {
        const data = await response.json()
        setReturns(data.returns || [])
      }
    } catch (error) {
      console.error('Failed to fetch returns:', error)
    } finally {
      setLoading(false)
    }
  }, [filter])

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (status !== 'authenticated') return

    fetchReturns()
  }, [status, router, fetchReturns])

  const handleSubmitReturn = async () => {
    if (!selectedOrder || !returnReason) {
      alert('Please select an order and reason')
      return
    }

    try {
      const formData = new FormData()
      formData.append('orderId', selectedOrder)
      formData.append('reason', returnReason)
      formData.append('notes', returnNotes)
      evidence.forEach(file => {
        formData.append('evidence', file)
      })

      const response = await fetch('/api/buyer/returns/boutique', {
        method: 'POST',
        body: formData,
      })

      if (response.ok) {
        setShowForm(false)
        setSelectedOrder('')
        setReturnReason('')
        setReturnNotes('')
        setEvidence([])
        await fetchReturns()
      }
    } catch (error) {
      console.error('Failed to submit return:', error)
    }
  }

  const handleAddEvidence = (files: FileList | null) => {
    if (files) {
      setEvidence([...evidence, ...Array.from(files)])
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'INITIATED': return 'bg-yellow-100 text-yellow-800'
      case 'APPROVED': return 'bg-green-100 text-green-800'
      case 'SHIPPED_BACK': return 'bg-blue-100 text-blue-800'
      case 'RECEIVED': return 'bg-indigo-100 text-indigo-800'
      case 'REFUNDED': return 'bg-green-100 text-green-800'
      case 'REJECTED': return 'bg-red-100 text-red-800'
      default: return 'bg-gray-100 text-gray-800'
    }
  }

  if (loading) {
    return <div className="p-8 text-center">Loading returns...</div>
  }

  const filteredReturns = returns.filter(r => filter === 'all' || r.status === filter)

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 md:p-8">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-3 mb-4 sm:mb-6">
          <div className="flex-1">
            <h1 className="text-lg sm:text-2xl md:text-3xl font-bold text-gray-900">Product Returns</h1>
            <p className="text-xs text-gray-600 mt-0.5">Manage returns and refunds</p>
          </div>
          <button
            onClick={() => setShowForm(!showForm)}
            className="inline-flex items-center gap-2 px-2.5 py-1.5 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition text-xs whitespace-nowrap"
            aria-label="Request product return"
          >
            <Plus className="w-4 h-4" />
            Request Return
          </button>
        </div>

        {/* Return Form */}
        {showForm && (
          <div className="bg-white rounded-lg shadow-sm p-4 mb-4">
            <h2 className="text-base font-semibold text-gray-900 mb-3">Request a Return</h2>
            <div className="space-y-3">
              <div>
                <label className="block text-xs font-medium text-gray-900 mb-1">Select Order *</label>
                <select
                  value={selectedOrder}
                  onChange={(e) => setSelectedOrder(e.target.value)}
                  aria-label="Select order to return"
                  className="w-full px-3 py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                >
                  <option value="">Choose an order...</option>
                  {/* Replace with actual orders */}
                </select>
              </div>

              <div>
                <label className="block text-xs font-medium text-gray-900 mb-1">Reason *</label>
                <select
                  value={returnReason}
                  onChange={(e) => setReturnReason(e.target.value)}
                  aria-label="Select return reason"
                  className="w-full px-3 py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                >
                  <option value="">Select reason...</option>
                  <option value="DEFECTIVE">Defective Item</option>
                  <option value="NOT_AS_DESCRIBED">Not as Described</option>
                  <option value="WRONG_SIZE">Wrong Size</option>
                  <option value="DAMAGED">Damaged in Shipping</option>
                  <option value="CHANGED_MIND">Changed Mind</option>
                  <option value="OTHER">Other</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-medium text-gray-900 mb-1">Description</label>
                <textarea
                  value={returnNotes}
                  onChange={(e) => setReturnNotes(e.target.value)}
                  placeholder="Describe the issue..."
                  aria-label="Return description"
                  className="w-full px-3 py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                  rows={2}
                />
              </div>

              <div>
                <label className="block text-xs font-medium text-gray-900 mb-1">Upload Evidence (Photos)</label>
                <div className="border-2 border-dashed border-gray-300 rounded-lg p-3 text-center">
                  <input
                    type="file"
                    multiple
                    accept="image/*"
                    onChange={(e) => handleAddEvidence(e.target.files)}
                    className="hidden"
                    id="evidence-upload"
                    aria-label="Upload evidence photos"
                  />
                  <label htmlFor="evidence-upload" className="cursor-pointer">
                    <Upload className="w-6 h-6 text-gray-400 mx-auto mb-1" />
                    <p className="text-xs text-gray-600">Click to upload</p>
                  </label>
                </div>
                {evidence.length > 0 && (
                  <div className="mt-2 space-y-1">
                    {evidence.map((file, idx) => (
                      <div key={idx} className="flex items-center justify-between p-1.5 bg-gray-50 rounded-lg">
                        <span className="text-xs text-gray-700 truncate">{file.name}</span>
                        <button
                          onClick={() => setEvidence(evidence.filter((_, i) => i !== idx))}
                          className="text-red-600 hover:text-red-700"
                          aria-label={`Remove ${file.name}`}
                        >
                          <X className="w-3 h-3" />
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              <div className="flex gap-2 justify-end pt-2">
                <button
                  onClick={() => setShowForm(false)}
                  className="px-2.5 py-1.5 text-xs border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
                  aria-label="Cancel return request"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSubmitReturn}
                  className="px-2.5 py-1.5 text-xs bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
                  aria-label="Submit return request"
                >
                  Submit
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Filter */}
        <div className="bg-white rounded-lg shadow-sm p-2 mb-3">
          <select
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            aria-label="Filter returns by status"
            className="px-3 py-1.5 text-xs border border-gray-300 rounded-lg text-black bg-white"
          >
            <option value="all">All Returns</option>
            <option value="INITIATED">Pending Approval</option>
            <option value="APPROVED">Approved</option>
            <option value="SHIPPED_BACK">Shipped Back</option>
            <option value="REFUNDED">Refunded</option>
            <option value="REJECTED">Rejected</option>
          </select>
        </div>

        {/* Returns List */}
        {filteredReturns.length === 0 ? (
          <div className="bg-white rounded-lg shadow-sm p-12 text-center">
            <AlertCircle className="w-12 h-12 text-gray-300 mx-auto mb-4" />
            <p className="text-gray-500">No returns found</p>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredReturns.map((ret) => (
              <div key={ret.id} className="bg-white rounded-lg shadow-sm p-4 sm:p-6 hover:shadow-md transition">
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-4">
                  <div className="flex gap-4">
                    <div className="w-20 h-20 bg-gray-200 rounded-lg flex-shrink-0" />
                    <div className="flex-1 min-w-0">
                      <h3 className="font-semibold text-gray-900 line-clamp-1">{ret.product.title}</h3>
                      <p className="text-sm text-gray-600 mt-1">{ret.seller.name}</p>
                      <p className="text-xs text-gray-500 mt-1">Order: {ret.orderNumber}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-4">
                    <div className="text-right">
                      <p className="text-sm text-gray-600">Refund</p>
                      <p className="text-lg font-bold text-green-600">${ret.refundAmount.toFixed(2)}</p>
                    </div>
                    <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(ret.status)}`}>
                      {ret.status.replace(/_/g, ' ')}
                    </span>
                  </div>
                </div>

                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 p-3 bg-gray-50 rounded-lg">
                  <div>
                    <p className="text-xs text-gray-600">Reason</p>
                    <p className="text-sm font-medium text-gray-900">{ret.reason.replace(/_/g, ' ')}</p>
                  </div>
                  <div>
                    <p className="text-xs text-gray-600">Requested</p>
                    <p className="text-sm font-medium text-gray-900">{new Date(ret.createdAt).toLocaleDateString()}</p>
                  </div>
                  <div>
                    <p className="text-xs text-gray-600">Status</p>
                    <p className="text-sm font-medium text-gray-900">{ret.status.replace(/_/g, ' ')}</p>
                  </div>
                  {ret.trackingNumber && (
                    <div>
                      <p className="text-xs text-gray-600">Tracking</p>
                      <p className="text-sm font-medium text-gray-900">{ret.trackingNumber}</p>
                    </div>
                  )}
                </div>

                <button
                  onClick={() => setSelectedReturn(ret)}
                  className="mt-4 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition text-sm"
                >
                  View Details
                </button>
              </div>
            ))}
          </div>
        )}

        {/* Stats */}
        {returns.length > 0 && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-8">
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-indigo-600">{returns.length}</p>
              <p className="text-xs text-gray-600 mt-1">Total Returns</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-yellow-600">{returns.filter(r => r.status === 'INITIATED').length}</p>
              <p className="text-xs text-gray-600 mt-1">Pending</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-green-600">{returns.filter(r => r.status === 'REFUNDED').length}</p>
              <p className="text-xs text-gray-600 mt-1">Refunded</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-red-600">${returns.filter(r => r.status === 'REFUNDED').reduce((sum, r) => sum + r.refundAmount, 0).toFixed(2)}</p>
              <p className="text-xs text-gray-600 mt-1">Total Refunded</p>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useEffect, useState } from 'react'
import Image from 'next/image'
import Link from 'next/link'
import { ArrowLeft, Package, Truck, CheckCircle, Clock, ExternalLink } from 'lucide-react'
import { useCurrency } from '@/components/CurrencyProvider'

interface BoutiqueOrderItem {
  id: string
  quantity: number
  price: number
  product: {
    id: string
    title: string
    thumbnailUrl: string | null
  }
  seller: {
    id: string
    displayName: string | null
    name: string | null
  }
}

interface BoutiqueOrder {
  id: string
  orderNumber: string
  status: 'PENDING' | 'VERIFIED' | 'LIVE' | 'SHIPPED' | 'DELIVERED' | 'CANCELLED'
  totalAmount: number
  createdAt: string
  shippedAt: string | null
  deliveredAt: string | null
  trackingNumber: string | null
  trackingUrl: string | null
  items: BoutiqueOrderItem[]
}

export default function BoutiqueOrdersPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const { formatPrice } = useCurrency()
  const [orders, setOrders] = useState<BoutiqueOrder[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<string>('all')

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (status !== 'authenticated') return

    fetchOrders()
  }, [status, router])

  const fetchOrders = async () => {
    try {
      setLoading(true)
      const response = await fetch('/api/buyer/boutique-orders')
      if (response.ok) {
        const data = await response.json()
        setOrders(data.orders || [])
      }
    } catch (error) {
      console.error('Failed to fetch orders:', error)
    } finally {
      setLoading(false)
    }
  }

  const filteredOrders = orders.filter(order => {
    return filter === 'all' || order.status === filter
  })

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'PENDING': return 'bg-yellow-100 text-yellow-800'
      case 'VERIFIED': return 'bg-blue-100 text-blue-800'
      case 'LIVE': return 'bg-indigo-100 text-indigo-800'
      case 'SHIPPED': return 'bg-cyan-100 text-cyan-800'
      case 'DELIVERED': return 'bg-green-100 text-green-800'
      case 'CANCELLED': return 'bg-red-100 text-red-800'
      default: return 'bg-gray-100 text-gray-800'
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'PENDING': return <Clock className="w-4 h-4" />
      case 'SHIPPED': return <Truck className="w-4 h-4" />
      case 'DELIVERED': return <CheckCircle className="w-4 h-4" />
      default: return <Package className="w-4 h-4" />
    }
  }

  const getStatusDescription = (status: string) => {
    switch (status) {
      case 'PENDING': return 'Awaiting verification'
      case 'VERIFIED': return 'Ready to ship'
      case 'LIVE': return 'In marketplace'
      case 'SHIPPED': return 'On the way to you'
      case 'DELIVERED': return 'Delivered'
      case 'CANCELLED': return 'Order cancelled'
      default: return status
    }
  }

  if (status === 'loading' || loading) {
    return <div className="p-8 text-center">Loading your boutique orders...</div>
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 md:p-8">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <button
            onClick={() => router.back()}
            className="p-2 hover:bg-gray-200 rounded-lg transition"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">My Boutique Orders</h1>
            <p className="text-gray-600">Track your physical product purchases</p>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-sm p-4 mb-6">
          <select
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            className="px-4 py-2 border border-gray-300 rounded-lg text-black bg-white"
          >
            <option value="all">All Orders</option>
            <option value="PENDING">Pending</option>
            <option value="VERIFIED">Verified</option>
            <option value="SHIPPED">Shipped</option>
            <option value="DELIVERED">Delivered</option>
            <option value="CANCELLED">Cancelled</option>
          </select>
        </div>

        {/* Orders List */}
        {filteredOrders.length === 0 ? (
          <div className="bg-white rounded-lg shadow-sm p-12 text-center">
            <Package className="w-12 h-12 text-gray-300 mx-auto mb-4" />
            <p className="text-gray-500 mb-4">No boutique orders yet</p>
            <Link
              href="/shop/physical"
              className="inline-block px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition"
            >
              Shop Now
            </Link>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredOrders.map((order) => (
              <div key={order.id} className="bg-white rounded-lg shadow-sm overflow-hidden hover:shadow-md transition">
                {/* Order Header */}
                <div className="p-4 sm:p-6 border-b border-gray-200">
                  <div className="flex items-start justify-between mb-4">
                    <div>
                      <h3 className="text-lg font-semibold text-gray-900">Order {order.orderNumber}</h3>
                      <p className="text-sm text-gray-600 mt-1">
                        Placed on {new Date(order.createdAt).toLocaleDateString()}
                      </p>
                    </div>
                    <span className={`inline-flex items-center gap-1 px-3 py-1 rounded-full text-sm font-medium ${getStatusColor(order.status)}`}>
                      {getStatusIcon(order.status)}
                      {getStatusDescription(order.status)}
                    </span>
                  </div>

                  {/* Tracking Info */}
                  {order.trackingNumber && (
                    <div className="flex items-center gap-2 text-sm text-gray-600">
                      <Truck className="w-4 h-4" />
                      Tracking: {order.trackingNumber}
                      {order.trackingUrl && (
                        <a
                          href={order.trackingUrl}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-indigo-600 hover:text-indigo-800 ml-2"
                        >
                          <ExternalLink className="w-4 h-4" />
                        </a>
                      )}
                    </div>
                  )}

                  {order.shippedAt && (
                    <p className="text-xs text-gray-500 mt-2">Shipped on {new Date(order.shippedAt).toLocaleDateString()}</p>
                  )}
                </div>

                {/* Order Items */}
                <div className="divide-y divide-gray-200">
                  {order.items.map((item) => (
                    <div key={item.id} className="p-4 sm:p-6 flex gap-4">
                      {item.product.thumbnailUrl && (
                        <div className="w-20 h-20 relative flex-shrink-0">
                          <Image
                            src={item.product.thumbnailUrl}
                            alt={item.product.title}
                            fill
                            className="object-cover rounded-lg"
                          />
                        </div>
                      )}
                      <div className="flex-1 min-w-0">
                        <h4 className="font-medium text-gray-900">{item.product.title}</h4>
                        <p className="text-sm text-gray-600 mt-1">
                          By {item.seller.displayName || item.seller.name}
                        </p>
                        <div className="flex items-center justify-between mt-2">
                          <span className="text-sm text-gray-600">Qty: {item.quantity}</span>
                          <span className="font-semibold text-indigo-600">{formatPrice(item.price)}</span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>

                {/* Order Footer */}
                <div className="bg-gray-50 p-4 sm:p-6 flex items-center justify-between">
                  <div>
                    <p className="text-sm text-gray-600">Total Amount</p>
                    <p className="text-2xl font-bold text-gray-900">${order.totalAmount.toFixed(2)}</p>
                  </div>
                  <Link
                    href={`/orders/${order.id}`}
                    className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition"
                  >
                    View Details
                    <ExternalLink className="w-4 h-4" />
                  </Link>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Stats */}
        {orders.length > 0 && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-8">
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-indigo-600">{orders.length}</p>
              <p className="text-xs text-gray-600 mt-1">Total Orders</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-cyan-600">{orders.filter(o => o.status === 'SHIPPED').length}</p>
              <p className="text-xs text-gray-600 mt-1">In Transit</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-green-600">{orders.filter(o => o.status === 'DELIVERED').length}</p>
              <p className="text-xs text-gray-600 mt-1">Delivered</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-gray-600">${orders.reduce((sum, o) => sum + o.totalAmount, 0).toFixed(2)}</p>
              <p className="text-xs text-gray-600 mt-1">Total Spent</p>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useEffect, useState } from 'react'
import Image from 'next/image'
import Link from 'next/link'
import { ArrowLeft, Package, _Truck, _XCircle, _Clock, MessageSquare, ExternalLink } from 'lucide-react'
import { useCurrency } from '@/components/CurrencyProvider'

interface ReturnItem {
  id: string
  orderId: string
  orderNumber: string
  status: 'INITIATED' | 'APPROVED' | 'SHIPPED_BACK' | 'RECEIVED' | 'REFUNDED' | 'REJECTED'
  reason: string
  refundAmount: number
  createdAt: string
  approvedAt: string | null
  refundedAt: string | null
  product: {
    title: string
    thumbnailUrl: string | null
  }
  seller: {
    name: string
  }
}

export default function BuyerReturnsPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const { formatPrice } = useCurrency()
  const [returns, setReturns] = useState<ReturnItem[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<string>('all')

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (status !== 'authenticated') return

    fetchReturns()
  }, [status, router])

  const fetchReturns = async () => {
    try {
      setLoading(true)
      const response = await fetch('/api/buyer/returns')
      if (response.ok) {
        const data = await response.json()
        setReturns(data.returns || [])
      }
    } catch (error) {
      console.error('Failed to fetch returns:', error)
    } finally {
      setLoading(false)
    }
  }

  const filteredReturns = returns.filter(r => {
    return filter === 'all' || r.status === filter
  })

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'INITIATED': return 'bg-yellow-100 text-yellow-800'
      case 'APPROVED': return 'bg-blue-100 text-blue-800'
      case 'SHIPPED_BACK': return 'bg-cyan-100 text-cyan-800'
      case 'RECEIVED': return 'bg-indigo-100 text-indigo-800'
      case 'REFUNDED': return 'bg-green-100 text-green-800'
      case 'REJECTED': return 'bg-red-100 text-red-800'
      default: return 'bg-gray-100 text-gray-800'
    }
  }

  const getStatusDescription = (status: string) => {
    switch (status) {
      case 'INITIATED': return 'Return request submitted'
      case 'APPROVED': return 'Return approved - awaiting shipment'
      case 'SHIPPED_BACK': return 'Item shipped back to seller'
      case 'RECEIVED': return 'Item received by seller'
      case 'REFUNDED': return 'Refund processed'
      case 'REJECTED': return 'Return request denied'
      default: return status
    }
  }

  if (status === 'loading' || loading) {
    return <div className="p-8 text-center">Loading your returns...</div>
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 md:p-8">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <button
            onClick={() => router.back()}
            className="p-2 hover:bg-gray-200 rounded-lg transition"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">My Returns</h1>
            <p className="text-gray-600">Track items you've returned for refund</p>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-sm p-4 mb-6">
          <select
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            className="px-4 py-2 border border-gray-300 rounded-lg text-black bg-white"
          >
            <option value="all">All Returns</option>
            <option value="INITIATED">Initiated</option>
            <option value="APPROVED">Approved</option>
            <option value="SHIPPED_BACK">Shipped Back</option>
            <option value="RECEIVED">Received</option>
            <option value="REFUNDED">Refunded Γ£ô</option>
            <option value="REJECTED">Rejected Γ£ù</option>
          </select>
        </div>

        {/* Returns List */}
        {filteredReturns.length === 0 ? (
          <div className="bg-white rounded-lg shadow-sm p-12 text-center">
            <Package className="w-12 h-12 text-gray-300 mx-auto mb-4" />
            <p className="text-gray-500 mb-4">No returns found</p>
            <Link
              href="/orders"
              className="inline-block px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition"
            >
              View Orders
            </Link>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredReturns.map((returnItem) => (
              <div key={returnItem.id} className="bg-white rounded-lg shadow-sm overflow-hidden hover:shadow-md transition">
                {/* Return Header */}
                <div className="p-4 sm:p-6 border-b border-gray-200">
                  <div className="flex items-start justify-between mb-3 sm:mb-4">
                    <div>
                      <h3 className="font-semibold text-gray-900">Order {returnItem.orderNumber}</h3>
                      <p className="text-sm text-gray-600 mt-1">
                        Initiated {new Date(returnItem.createdAt).toLocaleDateString()}
                      </p>
                    </div>
                    <span className={`inline-flex items-center gap-1 px-3 py-1 rounded-full text-sm font-medium ${getStatusColor(returnItem.status)}`}>
                      {getStatusDescription(returnItem.status)}
                    </span>
                  </div>

                  {/* Progress Timeline */}
                  <div className="flex items-center gap-2 text-xs sm:text-sm text-gray-600">
                    <span className={`w-2 h-2 rounded-full ${['INITIATED', 'APPROVED', 'SHIPPED_BACK', 'RECEIVED', 'REFUNDED'].includes(returnItem.status) ? 'bg-blue-600' : 'bg-gray-300'}`} />
                    <span>Step 1: Initiated</span>
                    <span className={`w-2 h-2 rounded-full ${['APPROVED', 'SHIPPED_BACK', 'RECEIVED', 'REFUNDED'].includes(returnItem.status) ? 'bg-blue-600' : 'bg-gray-300'}`} />
                    <span>Step 2: Approved</span>
                    <span className={`w-2 h-2 rounded-full ${['SHIPPED_BACK', 'RECEIVED', 'REFUNDED'].includes(returnItem.status) ? 'bg-blue-600' : 'bg-gray-300'}`} />
                    <span>Step 3: Refund</span>
                  </div>
                </div>

                {/* Product Info */}
                <div className="p-4 sm:p-6 border-b border-gray-200 flex gap-4">
                  {returnItem.product.thumbnailUrl && (
                    <div className="w-20 h-20 relative flex-shrink-0">
                      <Image
                        src={returnItem.product.thumbnailUrl}
                        alt={returnItem.product.title}
                        fill
                        className="object-cover rounded-lg"
                      />
                    </div>
                  )}
                  <div className="flex-1 min-w-0">
                    <h4 className="font-medium text-gray-900 text-sm sm:text-base">{returnItem.product.title}</h4>
                    <p className="text-xs sm:text-sm text-gray-600 mt-1">By {returnItem.seller.name}</p>
                    <div className="mt-2">
                      <p className="text-xs text-gray-600">Reason for return:</p>
                      <p className="text-sm text-gray-900">{returnItem.reason}</p>
                    </div>
                  </div>
                </div>

                {/* Refund Amount & Actions */}
                <div className="bg-gray-50 p-4 sm:p-6 flex items-center justify-between">
                  <div>
                    <p className="text-sm text-gray-600">Refund Amount</p>
                    <p className="text-2xl font-bold text-green-600">{formatPrice(returnItem.refundAmount)}</p>
                  </div>
                  <div className="flex gap-2">
                    <Link
                      href={`/orders/${returnItem.orderId}`}
                      className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition text-sm"
                    >
                      View Order
                      <ExternalLink className="w-4 h-4" />
                    </Link>
                    <button className="inline-flex items-center gap-2 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition text-sm">
                      <MessageSquare className="w-4 h-4" />
                      Contact Seller
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Stats */}
        {returns.length > 0 && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-8">
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-indigo-600">{returns.length}</p>
              <p className="text-xs text-gray-600 mt-1">Total Returns</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-yellow-600">{returns.filter(r => r.status === 'INITIATED').length}</p>
              <p className="text-xs text-gray-600 mt-1">Pending Approval</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-green-600">{returns.filter(r => r.status === 'REFUNDED').length}</p>
              <p className="text-xs text-gray-600 mt-1">Refunded</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-red-600">{formatPrice(returns.reduce((sum, r) => sum + r.refundAmount, 0))}</p>
              <p className="text-xs text-gray-600 mt-1">Total Refunded</p>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { useSession } from 'next-auth/react'
import { Trash2, Plus, Minus, ShoppingBag, ArrowRight, X, AlertCircle, Package, Download, Truck } from 'lucide-react'
import Image from 'next/image'
import Link from 'next/link'
import { useCurrency } from '@/components/CurrencyProvider'

interface CartItem {
  id: string
  quantity: number
  purchaseType: 'REGULAR' | 'OWNERSHIP' | 'POD'
  // POD-specific fields
  podProductId?: string
  podProductName?: string
  podProvider?: string
  podPrice?: number
  // A/B Price Test fields
  priceTestVariant?: 'A' | 'B'
  priceTestPrice?: number
  // Promotion fields
  promotionId?: string | null
  promotionType?: 'DISCOUNT' | 'BUNDLE' | 'FLASH_SALE' | null
  promotionPrice?: number
  discountAmount?: number
  design: {
    id: string
    title: string
    price: number
    imageUrl: string
    thumbnailUrl: string | null
    designer: {
      id: string
      name: string | null
    }
  }
}

interface ShippingAddress {
  fullName: string
  addressLine1: string
  addressLine2?: string
  city: string
  state: string
  postalCode: string
  country: string
  phone: string
}

export default function CartPage() {
  const { data: session } = useSession()
  const router = useRouter()
  const [cartItems, setCartItems] = useState<CartItem[]>([])
  const [loading, setLoading] = useState(true)
  const [updating, setUpdating] = useState<string | null>(null)
  const [checkingOut, setCheckingOut] = useState(false)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)
  const [paymentMethod, setPaymentMethod] = useState<'stripe' | 'paystack' | 'flutterwave'>('paystack')
  const [countryCode, setCountryCode] = useState('NG')
  const [showShippingForm, setShowShippingForm] = useState(false)
  const [shippingAddress, setShippingAddress] = useState<ShippingAddress>({
    fullName: '',
    addressLine1: '',
    addressLine2: '',
    city: '',
    state: '',
    postalCode: '',
    country: 'NG',
    phone: ''
  })

  useEffect(() => {
    if (session) {
      fetchCart()
    } else {
      setLoading(false)
    }
  }, [session])

  const fetchCart = async () => {
    try {
      setLoading(true)
      const response = await fetch('/api/cart')
      if (response.ok) {
        const data = await response.json()
        setCartItems(data.items)
      } else if (response.status === 401) {
        setErrorMessage('Please sign in to view your cart.')
      }
    } catch (error) {
      console.error('Failed to fetch cart:', error)
    } finally {
      setLoading(false)
    }
  }

  const removeFromCart = async (itemId: string) => {
    try {
      setUpdating(itemId)
      const response = await fetch(`/api/cart?itemId=${itemId}`, {
        method: 'DELETE'
      })
      
      if (response.ok) {
        setCartItems(items => items.filter(item => item.id !== itemId))
      }
    } catch (error) {
      console.error('Failed to remove item:', error)
    } finally {
      setUpdating(null)
    }
  }

  const updateQuantity = async (itemId: string, newQuantity: number) => {
    if (newQuantity < 1) {
      removeFromCart(itemId)
      return
    }

    try {
      setUpdating(itemId)
      // For now, just update locally since we don't have update endpoint
      setCartItems(items => 
        items.map(item => 
          item.id === itemId ? { ...item, quantity: newQuantity } : item
        )
      )
    } catch (error) {
      console.error('Failed to update quantity:', error)
    } finally {
      setUpdating(null)
    }
  }

  const handleCheckout = async () => {
    // Check if POD items exist and shipping form is needed
    const hasPOD = cartItems.some(item => item.purchaseType === 'POD')
    
    if (hasPOD && !showShippingForm) {
      setShowShippingForm(true)
      return
    }
    
    // Validate shipping address if POD items exist
    if (hasPOD) {
      const required = ['fullName', 'addressLine1', 'city', 'state', 'postalCode', 'country', 'phone'] as const
      const missing = required.filter(field => !shippingAddress[field])
      if (missing.length > 0) {
        setErrorMessage(`Please fill in: ${missing.join(', ')}`)
        return
      }
    }
    
    try {
      setCheckingOut(true)
      setErrorMessage(null)
      
      const response = await fetch('/api/checkout', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          cartItems: cartItems.map(item => ({
            designId: item.design.id,
            quantity: item.quantity,
            purchaseType: item.purchaseType,
            // Include POD-specific fields
            ...(item.purchaseType === 'POD' ? {
              podProductId: item.podProductId,
              podProductName: item.podProductName,
              podProvider: item.podProvider,
              podPrice: item.podPrice
            } : {}),
            // Include A/B test variant if present
            ...(item.priceTestVariant ? {
              variant: item.priceTestVariant,
              testPrice: item.priceTestPrice
            } : {})
          })),
          paymentMethod,
          countryCode,
          // Include shipping address for POD orders
          ...(hasPOD ? { shippingAddress } : {})
        })
      })

      if (response.ok) {
        const data = await response.json()
        
        if (data.url) {
          window.location.href = data.url
        }
      } else {
        const error = await response.json()
        // If Stripe is not activated, automatically try Paystack
        if (paymentMethod === 'stripe' && error.message?.includes('Stripe not activated')) {
          setErrorMessage('Stripe not activated. Switching to Paystack...')
          setPaymentMethod('paystack')
          // Retry with Paystack after a brief delay
          setTimeout(() => {
            setErrorMessage(null)
          }, 2000)
          return
        }
        setErrorMessage(error.message || 'Checkout failed. Please try again.')
      }
    } catch (error) {
      console.error('Checkout error:', error)
      setErrorMessage('Checkout failed. Please try again.')
    } finally {
      setCheckingOut(false)
    }
  }

  const { formatPrice } = useCurrency()

  const calculateTotal = () => {
    return cartItems.reduce((sum, item) => {
      // Use the same logic as getItemPrice
      const itemPrice = getItemPrice(item)
      return sum + (itemPrice * item.quantity)
    }, 0)
  }
  
  // Check if cart has any POD items (requires shipping)
  const hasPODItems = cartItems.some(item => item.purchaseType === 'POD')
  const hasDigitalItems = cartItems.some(item => item.purchaseType !== 'POD')
  
  // Helper to get item price
  const getItemPrice = (item: CartItem) => {
    // POD items use podPrice
    if (item.purchaseType === 'POD' && item.podPrice) {
      return item.podPrice
    }
    // Promotion prices take priority
    if (item.promotionPrice !== undefined) {
      return item.promotionPrice
    }
    // A/B test items use the stored test price
    if (item.priceTestVariant && item.priceTestPrice) {
      return item.priceTestPrice
    }
    // Default to design price
    return item.design.price
  }
  
  // Helper to check if item has a promotion applied
  const hasPromotion = (item: CartItem) => {
    return item.promotionId !== null && item.promotionId !== undefined && item.promotionPrice !== undefined
  }

  // Helper to check if item has test price
  const hasTestPrice = (item: CartItem) => {
    return item.priceTestVariant === 'B' && item.priceTestPrice && item.priceTestPrice !== item.design.price
  }
  
  // Helper to get item type badge
  const getItemTypeBadge = (item: CartItem) => {
    if (item.purchaseType === 'POD') {
      return (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-orange-100 text-orange-800">
          <Package className="h-3 w-3" />
          Physical Product
        </span>
      )
    }
    if (item.purchaseType === 'OWNERSHIP') {
      return (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-purple-100 text-purple-800">
          Ownership Rights
        </span>
      )
    }
    return (
      <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
        <Download className="h-3 w-3" />
        Digital Download
      </span>
    )
  }

  // const calculatePlatformFee = (total: number) => {
  //   return total * 0.05 // 5% platform fee (deducted from sellers, not added to buyers)
  // }

  if (!session || errorMessage === 'Please sign in to view your cart.') {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <ShoppingBag className="h-16 w-16 text-gray-400 mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-gray-900 mb-4">Sign In Required</h1>
          <p className="text-gray-600 mb-6">Please sign in to view your cart</p>
          <button 
            onClick={() => router.push('/api/auth/signin')}
            className="bg-indigo-600 text-white px-6 py-2 rounded-lg hover:bg-indigo-700"
          >
            Sign In
          </button>
        </div>
      </div>
    )
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin h-8 w-8 border-2 border-indigo-600 border-t-transparent rounded-full" />
      </div>
    )
  }

  const total = calculateTotal()
  // const platformFee = calculatePlatformFee(total)

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="bg-white rounded-lg shadow-sm">
          <div className="px-4 py-3 sm:px-6 sm:py-4 border-b border-gray-200">
            <h1 className="text-lg sm:text-2xl font-bold text-gray-900 flex items-center gap-2">
              <ShoppingBag className="h-5 sm:h-6 w-5 sm:w-6" />
              <span>Shopping Cart</span>
              <span className="text-black">({cartItems.length})</span>
            </h1>
          </div>

          {/* Error Message */}
          {errorMessage && (
            <div className="mx-6 mt-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-center justify-between">
              <div className="flex items-center">
                <AlertCircle className="h-5 w-5 text-red-600 mr-3" />
                <span className="text-red-800 font-medium">{errorMessage}</span>
              </div>
              <button
                onClick={() => setErrorMessage(null)}
                className="text-red-600 hover:text-red-800"
                aria-label="Close error message"
              >
                <X className="h-4 w-4" />
              </button>
            </div>
          )}

          {cartItems.length === 0 ? (
            <div className="p-12 text-center">
              <ShoppingBag className="h-16 w-16 text-gray-400 mx-auto mb-4" />
              <h3 className="text-lg font-semibold text-gray-900 mb-2">Your cart is empty</h3>
              <p className="text-gray-600 mb-6">Start shopping to add items to your cart</p>
              <Link 
                href="/designs"
                className="inline-flex items-center px-6 py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
              >
                Browse Designs
                <ArrowRight className="ml-2 h-4 w-4" />
              </Link>
            </div>
          ) : (
            <div className="p-4 sm:p-6">
              <div className="space-y-3 sm:space-y-4 mb-6 sm:mb-8">
                {/* POD Items Notice */}
                {hasPODItems && (
                  <div className="p-4 bg-orange-50 border border-orange-200 rounded-lg flex items-start gap-3">
                    <Truck className="h-5 w-5 text-orange-600 flex-shrink-0 mt-0.5" />
                    <div>
