'use client';

import { useEffect, useState, Suspense } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import Link from 'next/link';

function CommissionPaymentSuccessContent() {
  const searchParams = useSearchParams();
  const _router = useRouter();
  const requestId = searchParams.get('request_id');
  const reference = searchParams.get('reference');
  
  const [verifying, setVerifying] = useState(true);
  const [_verified, setVerified] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [commission, setCommission] = useState<any>(null);

  useEffect(() => {
    const verifyPayment = async () => {
      if (!requestId) {
        setError('Missing request information');
        setVerifying(false);
        return;
      }

      try {
        // Verify and confirm the payment
        const response = await fetch('/api/commission-requests/confirm-payment', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ requestId, reference }),
        });

        const data = await response.json();

        if (response.ok) {
          setVerified(true);
          setCommission(data.commissionRequest);
        } else {
          // Payment might already be verified via webhook
          // Try to fetch the commission status
          const statusResponse = await fetch(`/api/commission-requests/${requestId}`);
          const statusData = await statusResponse.json();
          
          if (statusData.isPaid) {
            setVerified(true);
            setCommission(statusData);
          } else {
            setError(data.error || 'Payment verification failed');
          }
        }
      } catch (_err) {
        setError('Failed to verify payment. Please contact support if the issue persists.');
      } finally {
        setVerifying(false);
      }
    };

    verifyPayment();
  }, [requestId, reference]);

  if (verifying) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-pink-500 mx-auto mb-4"></div>
          <h2 className="text-xl font-semibold text-gray-900">Verifying your payment...</h2>
          <p className="text-gray-500 mt-2">Please wait while we confirm your transaction</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="max-w-md mx-auto bg-white rounded-lg shadow-lg p-8 text-center">
          <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8 text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </div>
          <h1 className="text-2xl font-bold text-gray-900 mb-2">Payment Issue</h1>
          <p className="text-gray-600 mb-6">{error}</p>
          <div className="space-y-3">
            {requestId && (
              <Link
                href={`/commission-payment/${requestId}`}
                className="block w-full py-2 px-4 bg-pink-600 text-white rounded-lg hover:bg-pink-700 transition"
              >
                Try Again
              </Link>
            )}
            <Link
              href="/commissions"
              className="block w-full py-2 px-4 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition"
            >
              View My Commissions
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center py-12 px-4">
      <div className="max-w-md mx-auto bg-white rounded-lg shadow-lg p-8 text-center">
        <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
          <svg className="w-8 h-8 text-green-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
          </svg>
        </div>
        
        <h1 className="text-2xl font-bold text-gray-900 mb-2">Payment Successful!</h1>
        <p className="text-gray-600 mb-6">
          Your commission payment has been confirmed. The designer has been notified and will begin work soon.
        </p>

        {commission && (
          <div className="bg-gray-50 rounded-lg p-4 mb-6 text-left">
            <h3 className="font-semibold text-gray-900 mb-2">{commission.title}</h3>
            <p className="text-sm text-gray-600 mb-2">
              Designer: {commission.designerName}
            </p>
            {commission.designerDeadline && (
              <p className="text-sm text-gray-600">
                Expected by: {new Date(commission.designerDeadline).toLocaleDateString()}
              </p>
            )}
            <div className="mt-3 pt-3 border-t border-gray-200">
              <p className="text-sm font-medium text-gray-900">
                Amount Paid: ${commission.designerQuote?.toLocaleString()}
              </p>
            </div>
          </div>
        )}

        <div className="space-y-3">
          <Link
            href="/commissions"
            className="block w-full py-2 px-4 bg-pink-600 text-white rounded-lg hover:bg-pink-700 transition"
          >
            View My Commissions
          </Link>
          <Link
            href="/designs"
            className="block w-full py-2 px-4 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition"
          >
            Continue Shopping
          </Link>
        </div>

        <div className="mt-6 pt-6 border-t border-gray-200">
          <p className="text-xs text-gray-500">
            You will receive an email confirmation with details about your commission.
            If you have any questions, please contact our support team.
          </p>
        </div>
      </div>
    </div>
  );
}

export default function CommissionPaymentSuccessPage() {
  return (
    <Suspense fallback={
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="w-8 h-8 border-4 border-purple-600 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-gray-500">Loading...</p>
        </div>
      </div>
    }>
      <CommissionPaymentSuccessContent />
    </Suspense>
  );
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useParams } from 'next/navigation'
import Link from 'next/link'
import Image from 'next/image'
import { ArrowLeft, Download, Eye, Truck, CheckCircle, Clock, Package } from 'lucide-react'
import { useCurrency } from '@/components/CurrencyProvider'

interface OrderItem {
  id: string
  quantity: number
  price: number
  purchaseType: 'REGULAR' | 'OWNERSHIP' | 'POD'
  design: {
    id: string
    title: string
    imageUrl: string
    thumbnailUrl?: string
    designer: {
      name: string | null
    }
  }
  downloadUrl?: string
}

interface Order {
  id: string
  orderNumber: string
  status: string
  orderType: 'DIGITAL' | 'POD'
  totalAmount: number
  createdAt: string
  paidAt?: string
  paymentMethod?: string
  trackingNumber?: string
  trackingUrl?: string
  items: OrderItem[]
}

export default function OrderDetailsPage() {
  const { data: session, status: authStatus } = useSession()
  const router = useRouter()
  const params = useParams()
  const { formatPrice } = useCurrency()
  const orderNumber = params.orderNumber as string

  const [order, setOrder] = useState<Order | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  useEffect(() => {
    if (authStatus === 'loading') return
    if (!session) {
      router.push('/auth/signin')
      return
    }
    fetchOrder()
  }, [session, authStatus, router])

  const fetchOrder = async () => {
    try {
      setLoading(true)
      const response = await fetch(`/api/orders/${orderNumber}`)
      if (!response.ok) {
        setError('Order not found')
        return
      }
      const data = await response.json()
      setOrder(data)
    } catch (err) {
      setError('Failed to load order details')
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
      </div>
    )
  }

  if (error || !order) {
    return (
      <div className="min-h-screen bg-gray-50 px-4 py-8">
        <div className="max-w-2xl mx-auto">
          <button
            onClick={() => router.back()}
            className="inline-flex items-center gap-2 text-indigo-600 hover:text-indigo-800 mb-6"
          >
            <ArrowLeft className="w-4 h-4" />
            Back
          </button>
          <div className="bg-white rounded-lg shadow-sm p-8 text-center">
            <h2 className="text-xl font-semibold text-gray-900 mb-2">{error || 'Order not found'}</h2>
            <Link href="/orders" className="text-indigo-600 hover:text-indigo-800">
              View all orders
            </Link>
          </div>
        </div>
      </div>
    )
  }

  const statusConfig: Record<string, { icon: React.ElementType; color: string }> = {
    PENDING: { icon: Clock, color: 'bg-yellow-100 text-yellow-800' },
    COMPLETED: { icon: CheckCircle, color: 'bg-green-100 text-green-800' },
    PAID: { icon: CheckCircle, color: 'bg-green-100 text-green-800' },
    SHIPPED: { icon: Truck, color: 'bg-blue-100 text-blue-800' },
  }

  const config = statusConfig[order.status] || { icon: Package, color: 'bg-gray-100 text-gray-800' }
  const StatusIcon = config.icon

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-2xl mx-auto px-4 py-8">
        {/* Back Button */}
        <button
          onClick={() => router.back()}
          className="inline-flex items-center gap-2 text-indigo-600 hover:text-indigo-800 mb-6"
        >
          <ArrowLeft className="w-4 h-4" />
          Back
        </button>

        {/* Order Header */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-4">
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Order #{order.orderNumber}</h1>
              <p className="text-sm text-gray-500 mt-1">
                Placed on {new Date(order.createdAt).toLocaleDateString()}
              </p>
            </div>
            <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-lg ${config.color} font-medium`}>
              <StatusIcon className="w-5 h-5" />
              {order.status}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4 pt-4 border-t border-gray-200">
            <div>
              <p className="text-sm text-gray-600">Order Type</p>
              <p className="font-semibold text-gray-900">{order.orderType === 'POD' ? 'Print-on-Demand' : 'Digital'}</p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Total Amount</p>
              <p className="font-semibold text-gray-900">${order.totalAmount.toFixed(2)}</p>
            </div>
            {order.paymentMethod && (
              <div>
                <p className="text-sm text-gray-600">Payment Method</p>
                <p className="font-semibold text-gray-900">{order.paymentMethod}</p>
              </div>
            )}
            {order.paidAt && (
              <div>
                <p className="text-sm text-gray-600">Paid At</p>
                <p className="font-semibold text-gray-900">{new Date(order.paidAt).toLocaleDateString()}</p>
              </div>
            )}
          </div>
        </div>

        {/* Order Items */}
        <div className="bg-white rounded-lg shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-gray-200 bg-gray-50">
            <h2 className="font-semibold text-gray-900">Items in this order</h2>
          </div>
          <div className="divide-y">
            {order.items.map((item) => (
              <div key={item.id} className="p-6 hover:bg-gray-50 transition-colors">
                <div className="flex gap-4">
                  {/* Item Image */}
                  <div className="w-20 h-20 rounded-lg overflow-hidden bg-gray-100 flex-shrink-0 relative">
                    <Image
                      src={item.design.thumbnailUrl || item.design.imageUrl}
                      alt={item.design.title}
                      fill
                      className="object-cover"
                    />
                  </div>

                  {/* Item Details */}
                  <div className="flex-1">
                    <Link
                      href={`/designs/${item.design.id}`}
                      className="text-lg font-semibold text-gray-900 hover:text-indigo-600 block mb-1"
                    >
                      {item.design.title}
                    </Link>
                    <p className="text-sm text-gray-600 mb-3">by {item.design.designer.name || 'Unknown'}</p>
                    <div className="flex items-center gap-3">
                      <span className="text-sm text-gray-600">
                        Quantity: <span className="font-semibold">{item.quantity}</span>
                      </span>
                      <span className="text-sm text-gray-600">
                        Price: <span className="font-semibold">{formatPrice(item.price)}</span>
                      </span>
                    </div>
                  </div>

                  {/* Download Button */}
                  {order.orderType === 'DIGITAL' && (order.status === 'PAID' || order.status === 'COMPLETED') && item.downloadUrl && (
                    <div className="flex items-center">
                      <a
                        href={item.downloadUrl}
                        download
                        className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-medium"
                      >
                        <Download className="w-4 h-4" />
                        Download
                      </a>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Tracking Info */}
        {order.orderType === 'POD' && order.trackingNumber && (
          <div className="bg-white rounded-lg shadow-sm p-6 mt-6">
            <h2 className="font-semibold text-gray-900 mb-4 flex items-center gap-2">
              <Truck className="w-5 h-5" />
              Tracking Information
            </h2>
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Tracking Number</p>
                <p className="font-semibold text-gray-900">{order.trackingNumber}</p>
              </div>
              {order.trackingUrl && (
                <a
                  href={order.trackingUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
                >
                  <Eye className="w-4 h-4" />
                  Track Package
                </a>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import Image from 'next/image'
import toast from 'react-hot-toast'
import { useCurrency } from '@/components/CurrencyProvider'
import {
  Package,
  Download,
  Search,
  Filter,
  Calendar,
  ChevronLeft,
  ChevronRight,
  Loader2,
  ShoppingBag,
  ExternalLink,
  Clock,
  CheckCircle,
  XCircle,
  Truck,
} from 'lucide-react'
import { downloadFilesAsZip } from '@/lib/downloadUtils'

interface OrderItem {
  id: string
  quantity: number
  price: number
  purchaseType: 'REGULAR' | 'OWNERSHIP' | 'POD'
  podProductId?: string
  podProductName?: string
  design: {
    id: string
    title: string
    imageUrl: string
    thumbnailUrl?: string
    category: string
    designer: {
      id: string
      name: string | null
    }
    mediaFiles?: Array<{
      id: string
      fileUrl: string
      fileName: string
      fileType: string
      mimeType: string
    }>
  }
}

interface Order {
  id: string
  orderNumber: string
  status: string
  orderType: 'DIGITAL' | 'POD'
  totalAmount: number
  createdAt: string
  paidAt?: string
  paymentMethod?: string
  podProvider?: string
  podStatus?: string
  trackingNumber?: string
  trackingUrl?: string
  estimatedDelivery?: string
  items: OrderItem[]
}

const STATUS_CONFIG: Record<string, { label: string; color: string; icon: React.ElementType }> = {
  PENDING: { label: 'Pending', color: 'bg-yellow-100 text-yellow-800', icon: Clock },
  PAID: { label: 'Paid', color: 'bg-green-100 text-green-800', icon: CheckCircle },
  COMPLETED: { label: 'Completed', color: 'bg-emerald-100 text-emerald-800', icon: CheckCircle },
  CANCELLED: { label: 'Cancelled', color: 'bg-red-100 text-red-800', icon: XCircle },
  REFUNDED: { label: 'Refunded', color: 'bg-gray-100 text-gray-800', icon: XCircle },
  PROCESSING: { label: 'Processing', color: 'bg-blue-100 text-blue-800', icon: Package },
  SHIPPED: { label: 'Shipped', color: 'bg-purple-100 text-purple-800', icon: Truck },
  DELIVERED: { label: 'Delivered', color: 'bg-emerald-100 text-emerald-800', icon: CheckCircle },
}

export default function OrdersPage() {
  const { data: session, status: authStatus } = useSession()
  const router = useRouter()
  const { formatPrice } = useCurrency()

  const [orders, setOrders] = useState<Order[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [statusFilter, setStatusFilter] = useState('all')
  const [typeFilter, setTypeFilter] = useState<'all' | 'DIGITAL' | 'POD'>('all')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [downloadingOrderId, setDownloadingOrderId] = useState<string | null>(null)
  const [expandedOrderId, setExpandedOrderId] = useState<string | null>(null)

  const handleDownloadAllFiles = async (order: Order) => {
    setDownloadingOrderId(order.id)
    
    try {
      const files: Array<{ url: string; name: string; folder?: string }> = []
      
      // Collect all files from all items in the order, organized by design
      order.items.forEach((item) => {
        if (item.design.mediaFiles && item.design.mediaFiles.length > 0) {
          item.design.mediaFiles.forEach((media) => {
            files.push({
              url: media.fileUrl,
              name: media.fileName || `${item.design.title}-${media.id}`,
              folder: item.design.title // Create subfolder for each design
            })
          })
        }
      })

      if (files.length === 0) {
        toast.error('No files available for download')
        setDownloadingOrderId(null)
        return
      }

      await downloadFilesAsZip(files, `Order-${order.orderNumber}`)
      toast.success(`Downloaded ${files.length} file(s) from ${order.items.length} design(s)`)
    } catch (error) {
      console.error('Download error:', error)
      toast.error('Failed to download files. Please try again.')
    } finally {
      setDownloadingOrderId(null)
    }
  }

  useEffect(() => {
    if (authStatus === 'loading') return
    if (!session) {
      router.push('/auth/signin')
      return
    }
    fetchOrders()
  }, [session, authStatus, router, page, statusFilter, typeFilter])

  const fetchOrders = async () => {
    try {
      setLoading(true)
      const params = new URLSearchParams({
        page: page.toString(),
        limit: '10',
      })
      if (statusFilter !== 'all') params.append('status', statusFilter)
      if (typeFilter !== 'all') params.append('type', typeFilter)

      const response = await fetch(`/api/profile/orders?${params}`)
      if (response.ok) {
        const data = await response.json()
        setOrders(data.orders || [])
        setTotalPages(data.totalPages || 1)
      }
    } catch (error) {
      console.error('Failed to fetch orders:', error)
    } finally {
      setLoading(false)
    }
  }

  const filteredOrders = orders.filter(order => {
    if (!searchQuery) return true
    const query = searchQuery.toLowerCase()
    return (
      order.orderNumber.toLowerCase().includes(query) ||
      order.items.some(item => item.design.title.toLowerCase().includes(query))
    )
  })

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    const dateStr = date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    })
    const timeStr = date.toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: true,
    })
    return `${dateStr} at ${timeStr}`
  }

  if (authStatus === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-indigo-600" />
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-6xl mx-auto px-3 sm:px-6 lg:px-8 py-4 sm:py-8">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between mb-4 sm:mb-8">
          <div>
            <h1 className="text-lg sm:text-2xl font-bold text-gray-900 flex items-center gap-2">
              <ShoppingBag className="w-5 h-5 sm:w-6 sm:h-6" />
              My Orders
            </h1>
            <p className="text-xs sm:text-sm text-gray-600 mt-1">View and manage your digital purchases</p>
          </div>
          <Link
            href="/boutique/orders"
            className="mt-4 sm:mt-0 inline-flex items-center gap-2 text-sm text-purple-600 hover:text-purple-800"
          >
            <Package className="w-4 h-4" />
            View Boutique Orders
            <ExternalLink className="w-3 h-3" />
          </Link>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-sm p-3 sm:p-4 mb-4 sm:mb-6">
          <div className="flex flex-col gap-2 sm:gap-4">
            {/* Search */}
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                placeholder="Search orders..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-8 pr-3 py-1.5 sm:py-2 text-sm border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 text-gray-900"
              />
            </div>

            {/* Status Filter */}
            <div className="flex items-center gap-2">
              <Filter className="w-4 h-4 text-gray-400" />
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="px-3 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 text-gray-900"
                aria-label="Filter by order status"
              >
                <option value="all">All Status</option>
                <option value="PENDING">Pending</option>
                <option value="PAID">Paid</option>
                <option value="COMPLETED">Completed</option>
                <option value="CANCELLED">Cancelled</option>
              </select>
            </div>

            {/* Type Filter */}
            <select
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value as 'all' | 'DIGITAL' | 'POD')}
              className="px-3 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 text-gray-900"
              aria-label="Filter by order type"
            >
              <option value="all">All Types</option>
              <option value="DIGITAL">Digital Downloads</option>
              <option value="POD">Print-on-Demand</option>
            </select>
          </div>
        </div>

        {/* Orders List */}
        {filteredOrders.length === 0 ? (
          <div className="bg-white rounded-xl shadow-sm p-12 text-center">
            <ShoppingBag className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">No orders found</h3>
            <p className="text-gray-500 mb-6">
              {searchQuery || statusFilter !== 'all' || typeFilter !== 'all'
                ? 'Try adjusting your filters'
                : "You haven't made any purchases yet"}
            </p>
            <Link
              href="/designs"
              className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
            >
              Browse Designs
            </Link>
          </div>
        ) : (
          <div className="space-y-2">
            {filteredOrders.map((order) => {
              const statusConfig = STATUS_CONFIG[order.status] || STATUS_CONFIG.PENDING
              const StatusIcon = statusConfig.icon

              return (
                <div key={order.id} className="bg-white rounded shadow-sm overflow-hidden">
                  {/* Order Header */}
                  <button
                    onClick={() => setExpandedOrderId(expandedOrderId === order.id ? null : order.id)}
                    className="w-full px-2.5 sm:px-4 py-2 sm:py-3 border-b border-gray-100 flex items-center gap-2 sm:gap-3 justify-between hover:bg-gray-50 transition-colors"
                  >
                    <div className="flex-1 min-w-0 text-left">
                      <p className="text-[10px] sm:text-sm font-medium text-gray-900 break-words">Order #{order.orderNumber}</p>
                      <div className="flex flex-wrap items-center gap-1.5 sm:gap-2 text-[9px] sm:text-xs text-gray-600 mt-0.5">
                        <span className="flex items-center gap-0.5">
                          <Calendar className="w-2.5 h-2.5" />
                          {formatDate(order.createdAt)}
                        </span>
                        <span className={`px-1.5 py-0.5 rounded text-[9px] sm:text-[10px] font-medium ${
                          order.orderType === 'POD' ? 'bg-purple-100 text-purple-800' : 'bg-blue-100 text-blue-800'
                        }`}>
                          {order.orderType === 'POD' ? 'POD' : 'Digital'}
                        </span>
                      </div>
                    </div>

                    <div className="flex items-center gap-1 sm:gap-2 flex-shrink-0">
                      <div className="flex flex-col items-end gap-1">
                        <span className={`inline-flex items-center gap-0.5 px-2 py-0.5 rounded-full text-[9px] sm:text-xs font-medium ${statusConfig.color}`}>
                          <StatusIcon className="w-2.5 h-2.5" />
                          <span className="hidden sm:inline">{statusConfig.label}</span>
                        </span>
                        <span className="font-semibold text-[10px] sm:text-sm text-gray-900">
                          {formatPrice(order.totalAmount)}
                        </span>
                      </div>
                      <ChevronRight className={`w-4 h-4 sm:w-5 sm:h-5 text-gray-400 transition-transform flex-shrink-0 ${expandedOrderId === order.id ? 'rotate-90' : ''}`} />
                    </div>
                  </button>

                  {/* Order Items - Show only when expanded */}
                  {expandedOrderId === order.id && (
                  <div className="px-2.5 sm:px-4 py-2 sm:py-3 bg-gray-50">
                    <div className="space-y-2 sm:space-y-3">
                      {order.items.map((item) => (
                        <div key={item.id} className="flex items-start gap-2 sm:gap-3">
                          <div className="w-10 h-10 sm:w-14 sm:h-14 rounded overflow-hidden bg-gray-100 relative flex-shrink-0">

                            <Image
                              src={item.design.thumbnailUrl || item.design.imageUrl}
                              alt={item.design.title}
                              fill
                              className="object-cover"
                            />
                          </div>
                          <div className="flex-1 min-w-0">
                            <Link
                              href={`/designs/${item.design.id}`}
                              className="text-[10px] sm:text-xs font-medium text-gray-900 hover:text-indigo-600 truncate block"
                            >
                              {item.design.title}
                            </Link>
                            <p className="text-[9px] sm:text-[10px] text-gray-500 truncate">
                              by {item.design.designer.name || 'Unknown'}
                            </p>
                            <div className="flex flex-wrap items-center gap-1 mt-1">
                              <span className={`text-[9px] sm:text-[10px] px-1.5 py-0.5 rounded font-medium ${
                                item.purchaseType === 'OWNERSHIP'
                                  ? 'bg-amber-100 text-amber-800'
                                  : item.purchaseType === 'POD'
                                  ? 'bg-purple-100 text-purple-800'
                                  : 'bg-gray-100 text-gray-600'
                              }`}>
                                {item.purchaseType === 'OWNERSHIP' ? 'Ownership' : item.purchaseType === 'POD' ? 'POD' : 'License'}
                              </span>
                              {item.podProductName && (
                                <span className="text-[9px] sm:text-[10px] text-gray-500">{item.podProductName}</span>
                              )}
                            </div>
                          </div>
                          <div className="text-right flex-shrink-0">
                            <p className="font-semibold text-[10px] sm:text-xs text-gray-900">{formatPrice(item.price)}</p>
                            <p className="text-[9px] sm:text-[10px] text-gray-500">Qty: {item.quantity}</p>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                  )}

                  {/* Order Actions - Only show when expanded */}
                  {expandedOrderId === order.id && (
                  <div className="px-2.5 sm:px-4 py-1.5 sm:py-2 bg-gray-50 border-t border-gray-100 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
                    {/* POD Tracking */}
                    {order.orderType === 'POD' && order.trackingNumber && (
                      <div className="flex items-center gap-0.5 text-[9px] sm:text-xs text-gray-600">
                        <Truck className="w-2.5 h-2.5" />
                        <span>Tracking: {order.trackingNumber}</span>
                        {order.trackingUrl && (
                          <a
                            href={order.trackingUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="text-indigo-600 hover:text-indigo-800"
                            aria-label="Track shipment"
                          >
                            <ExternalLink className="w-2.5 h-2.5" />
                          </a>
                        )}
                      </div>
                    )}

                    <div className="flex items-center gap-1 sm:gap-2 ml-auto">
                      {order.orderType === 'DIGITAL' && (order.status === 'PAID' || order.status === 'COMPLETED') && (
                        <button
                          onClick={() => handleDownloadAllFiles(order)}
                          disabled={downloadingOrderId === order.id}
                          className="inline-flex items-center gap-1 px-2 sm:px-3 py-1 sm:py-1.5 text-[9px] sm:text-xs text-white bg-indigo-600 rounded hover:bg-indigo-700 disabled:bg-gray-400 disabled:cursor-not-allowed font-medium"
                        >
                          {downloadingOrderId === order.id ? (
                            <>
                              <Loader2 className="w-3 h-3 sm:w-4 sm:h-4 animate-spin" />
                              <span className="hidden sm:inline">Downloading...</span>
                            </>
                          ) : (
                            <>
                              <Download className="w-3 h-3 sm:w-4 sm:h-4" />
                              <span className="hidden sm:inline">Download</span>
                            </>
                          )}
                        </button>
                      )}
                    </div>
                  </div>
                  )}
                </div>
              )
            })}
          </div>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="flex items-center justify-center gap-2 mt-8">
            <button
              onClick={() => setPage(p => Math.max(1, p - 1))}
              disabled={page === 1}
              className="p-2 rounded-lg border border-gray-300 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
              aria-label="Previous page"
            >
              <ChevronLeft className="w-5 h-5" />
            </button>
            <span className="px-4 py-2 text-sm text-gray-600">
              Page {page} of {totalPages}
            </span>
            <button
              onClick={() => setPage(p => Math.min(totalPages, p + 1))}
              disabled={page === totalPages}
              className="p-2 rounded-lg border border-gray-300 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
              aria-label="Next page"
            >
              <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useEffect, useState, useCallback } from 'react'
import Link from 'next/link'
import { Plus, AlertCircle, CheckCircle, Clock, MessageSquare, ArrowLeft } from 'lucide-react'

interface Appeal {
  id: string
  originalDisputeNumber: string
  status: 'SUBMITTED' | 'UNDER_REVIEW' | 'APPROVED' | 'DENIED'
  reason: string
  notes: string | null
  submittedAt: string
  reviewedAt: string | null
  adminResponse: string | null
  admin?: { name: string | null; email: string | null } | null
}

export default function SellerAppealsPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [appeals, setAppeals] = useState<Appeal[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<string>('all')
  const [showForm, setShowForm] = useState(false)
  const [selectedAppeal, setSelectedAppeal] = useState<Appeal | null>(null)

  // Form states
  const [disputeNumber, setDisputeNumber] = useState('')
  const [appealReason, setAppealReason] = useState('')
  const [appealNotes, setAppealNotes] = useState('')

  const fetchAppeals = useCallback(async () => {
    try {
      setLoading(true)
      const response = await fetch(`/api/seller/appeals?status=${filter}`)
      if (response.ok) {
        const data = await response.json()
        setAppeals(data.appeals || [])
      }
    } catch (error) {
      console.error('Failed to fetch appeals:', error)
    } finally {
      setLoading(false)
    }
  }, [filter])

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (status !== 'authenticated') return

    fetchAppeals()
  }, [status, router, fetchAppeals])

  const handleSubmitAppeal = async () => {
    if (!disputeNumber || !appealReason) {
      alert('Please fill in all required fields')
      return
    }

    try {
      const response = await fetch('/api/seller/appeals', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          originalDisputeNumber: disputeNumber,
          reason: appealReason,
          notes: appealNotes,
        }),
      })

      if (response.ok) {
        setShowForm(false)
        setDisputeNumber('')
        setAppealReason('')
        setAppealNotes('')
        await fetchAppeals()
      }
    } catch (error) {
      console.error('Failed to submit appeal:', error)
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'SUBMITTED': return 'bg-blue-100 text-blue-800'
      case 'UNDER_REVIEW': return 'bg-yellow-100 text-yellow-800'
      case 'APPROVED': return 'bg-green-100 text-green-800'
      case 'DENIED': return 'bg-red-100 text-red-800'
      default: return 'bg-gray-100 text-gray-800'
    }
  }

  if (loading) {
    return <div className="p-8 text-center">Loading appeals...</div>
  }

  const filteredAppeals = appeals.filter(a => filter === 'all' || a.status === filter)

  return (
    <div className="min-h-screen bg-gray-50 p-2 sm:p-4 md:p-8">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-4 mb-4 sm:mb-6 md:mb-8">
          <Link href="/seller/disputes" className="p-1.5 hover:bg-gray-200 rounded-lg transition shrink-0">
            <ArrowLeft className="w-4 h-4 sm:w-5 sm:h-5" />
          </Link>
          <div className="flex-1 min-w-0">
            <h1 className="text-lg sm:text-2xl md:text-3xl font-bold text-gray-900">Dispute Appeals</h1>
            <p className="text-xs sm:text-sm text-gray-600 mt-0.5 sm:mt-1">Appeal dispute decisions</p>
          </div>
          <button
            onClick={() => setShowForm(!showForm)}
            className="inline-flex items-center gap-1.5 sm:gap-2 px-2.5 sm:px-4 py-1.5 sm:py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition text-xs sm:text-sm whitespace-nowrap shrink-0"
          >
            <Plus className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
            <span className="hidden sm:inline">File Appeal</span>
            <span className="sm:hidden">Appeal</span>
          </button>
        </div>

        {/* Appeal Form */}
        {showForm && (
          <div className="bg-white rounded-lg shadow-sm p-3 sm:p-4 md:p-6 mb-4 sm:mb-6">
            <h2 className="text-sm sm:text-base md:text-lg font-semibold text-gray-900 mb-3 sm:mb-4">File an Appeal</h2>
            <div className="space-y-2 sm:space-y-3">
              <div>
                <label className="block text-xs font-medium text-gray-900 mb-0.5 sm:mb-1">Dispute Number *</label>
                <input
                  type="text"
                  value={disputeNumber}
                  onChange={(e) => setDisputeNumber(e.target.value)}
                  placeholder="e.g., DISP-001234"
                  aria-label="Dispute number"
                  className="w-full px-2 sm:px-3 py-1 sm:py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                />
              </div>

              <div>
                <label className="block text-xs font-medium text-gray-900 mb-0.5 sm:mb-1">Appeal Reason *</label>
                <select
                  value={appealReason}
                  onChange={(e) => setAppealReason(e.target.value)}
                  aria-label="Select appeal reason"
                  className="w-full px-2 sm:px-3 py-1 sm:py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                >
                  <option value="">Select reason...</option>
                  <option value="NEW_EVIDENCE">New Evidence Available</option>
                  <option value="PROCEDURAL_ERROR">Procedural Error</option>
                  <option value="INCORRECT_RULING">Incorrect Ruling</option>
                  <option value="SETTLEMENT_REACHED">Settlement Reached</option>
                  <option value="OTHER">Other Reason</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-medium text-gray-900 mb-0.5 sm:mb-1">Appeal Details</label>
                <textarea
                  value={appealNotes}
                  onChange={(e) => setAppealNotes(e.target.value)}
                  placeholder="Explain why you are appealing..."
                  aria-label="Appeal details"
                  className="w-full px-2 sm:px-3 py-1 sm:py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                  rows={3}
                />
              </div>

              <div className="flex gap-1.5 sm:gap-2 justify-end pt-1 sm:pt-2">
                <button
                  onClick={() => setShowForm(false)}
                  className="px-2 sm:px-2.5 py-1 sm:py-1.5 text-xs border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition"
                  aria-label="Cancel appeal"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSubmitAppeal}
                  className="px-2 sm:px-2.5 py-1 sm:py-1.5 text-xs bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition"
                  aria-label="Submit appeal"
                >
                  Submit
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Filter */}
        <div className="bg-white rounded-lg shadow-sm p-2 sm:p-3 md:p-4 mb-4 sm:mb-6">
          <select
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            className="w-full sm:w-auto px-2 sm:px-3 py-1 sm:py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs sm:text-sm"
          >
            <option value="all">All Appeals</option>
            <option value="SUBMITTED">Submitted</option>
            <option value="UNDER_REVIEW">Under Review</option>
            <option value="APPROVED">Approved</option>
            <option value="DENIED">Denied</option>
          </select>
        </div>

        {/* Appeals List */}
        {filteredAppeals.length === 0 ? (
          <div className="bg-white rounded-lg shadow-sm p-6 sm:p-8 md:p-12 text-center">
            <AlertCircle className="w-8 h-8 sm:w-10 sm:h-10 md:w-12 md:h-12 text-gray-300 mx-auto mb-2 sm:mb-4" />
            <p className="text-xs sm:text-sm text-gray-500">No appeals found</p>
          </div>
        ) : (
          <div className="space-y-2 sm:space-y-3 md:space-y-4">
            {filteredAppeals.map((appeal) => (
              <div key={appeal.id} className="bg-white rounded-lg shadow-sm p-2.5 sm:p-4 md:p-6 hover:shadow-md transition">
                <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-2 sm:gap-4 mb-3 sm:mb-4">
                  <div className="min-w-0 flex-1">
                    <h3 className="font-semibold text-xs sm:text-sm md:text-base text-gray-900 truncate">Dispute {appeal.originalDisputeNumber}</h3>
                    <p className="text-xs text-gray-600 mt-0.5 sm:mt-1 line-clamp-2">{appeal.reason.replace(/_/g, ' ')}</p>
                  </div>
                  <div className="flex items-center gap-1 sm:gap-2 shrink-0">
                    <span className={`inline-flex items-center px-2 sm:px-3 py-0.5 sm:py-1 rounded-full text-xs font-medium whitespace-nowrap ${getStatusColor(appeal.status)}`}>
                      {appeal.status === 'SUBMITTED' && <Clock className="w-2.5 h-2.5 sm:w-3 sm:h-3 mr-0.5 sm:mr-1" />}
                      {appeal.status === 'APPROVED' && <CheckCircle className="w-2.5 h-2.5 sm:w-3 sm:h-3 mr-0.5 sm:mr-1" />}
                      <span className="hidden sm:inline">{appeal.status.replace(/_/g, ' ')}</span>
                      <span className="sm:hidden">{appeal.status.charAt(0)}{appeal.status.slice(1).replace(/_/g, '')}</span>
                    </span>
                  </div>
                </div>

                <div className="grid grid-cols-2 sm:grid-cols-3 gap-1.5 sm:gap-3 p-2 sm:p-3 bg-gray-50 rounded-lg mb-3 sm:mb-4">
                  <div>
                    <p className="text-xs text-gray-600">Submitted</p>
                    <p className="text-xs sm:text-sm font-medium text-gray-900">{new Date(appeal.submittedAt).toLocaleDateString()}</p>
                  </div>
                  <div>
                    <p className="text-xs text-gray-600">Status</p>
                    <p className="text-xs sm:text-sm font-medium text-gray-900 truncate">{appeal.status.replace(/_/g, ' ')}</p>
                  </div>
                  {appeal.reviewedAt && (
                    <div>
                      <p className="text-xs text-gray-600">Reviewed</p>
                      <p className="text-xs sm:text-sm font-medium text-gray-900">{new Date(appeal.reviewedAt).toLocaleDateString()}</p>
                    </div>
                  )}
                </div>

                {appeal.adminResponse && (
                  <div className="mb-3 sm:mb-4 p-2 sm:p-3 bg-blue-50 border border-blue-200 rounded-lg">
                    <p className="text-xs text-blue-600 font-semibold mb-0.5 sm:mb-1">Admin Response</p>
                    <p className="text-xs sm:text-sm text-blue-900 line-clamp-3">{appeal.adminResponse}</p>
                  </div>
                )}

                <button
                  onClick={() => setSelectedAppeal(appeal)}
                  className="w-full sm:w-auto px-3 sm:px-4 py-1.5 sm:py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition text-xs sm:text-sm flex items-center justify-center sm:justify-start gap-1 sm:gap-2"
                  title="View appeal details"
                  aria-label="View appeal details"
                >
                  <MessageSquare className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                  View Details
                </button>
              </div>
            ))}
          </div>
        )}

        {/* Stats */}
        {appeals.length > 0 && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-2 sm:gap-3 md:gap-4 mt-4 sm:mt-6 md:mt-8">
            <div className="bg-white rounded-lg p-2 sm:p-3 md:p-4 text-center shadow-sm">
              <p className="text-xl sm:text-2xl font-bold text-indigo-600">{appeals.length}</p>
              <p className="text-xs text-gray-600 mt-0.5 sm:mt-1">
                <span className="hidden sm:inline">Total Appeals</span>
                <span className="sm:hidden">Appeals</span>
              </p>
            </div>
            <div className="bg-white rounded-lg p-2 sm:p-3 md:p-4 text-center shadow-sm">
              <p className="text-xl sm:text-2xl font-bold text-yellow-600">{appeals.filter(a => a.status === 'SUBMITTED' || a.status === 'UNDER_REVIEW').length}</p>
              <p className="text-xs text-gray-600 mt-0.5 sm:mt-1">
                <span className="hidden sm:inline">Pending Review</span>
                <span className="sm:hidden">Pending</span>
              </p>
            </div>
            <div className="bg-white rounded-lg p-2 sm:p-3 md:p-4 text-center shadow-sm">
              <p className="text-xl sm:text-2xl font-bold text-green-600">{appeals.filter(a => a.status === 'APPROVED').length}</p>
              <p className="text-xs text-gray-600 mt-0.5 sm:mt-1">Approved</p>
            </div>
            <div className="bg-white rounded-lg p-2 sm:p-3 md:p-4 text-center shadow-sm">
              <p className="text-xl sm:text-2xl font-bold text-red-600">{appeals.filter(a => a.status === 'DENIED').length}</p>
              <p className="text-xs text-gray-600 mt-0.5 sm:mt-1">Denied</p>
            </div>
          </div>
        )}

        {/* Details Modal */}
        {selectedAppeal && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto">
              <div className="sticky top-0 bg-white border-b p-3 sm:p-4 flex items-center justify-between">
                <h2 className="text-base sm:text-lg font-semibold text-gray-900">Appeal Details</h2>
                <button
                  onClick={() => setSelectedAppeal(null)}
                  className="p-1 hover:bg-gray-100 rounded-lg transition"
                  aria-label="Close"
                >
                  Γ£ò
                </button>
              </div>

              <div className="p-3 sm:p-4 md:p-6 space-y-4">
                {/* Header */}
                <div>
                  <h3 className="text-sm sm:text-base font-semibold text-gray-900">Dispute {selectedAppeal.originalDisputeNumber}</h3>
                  <div className="mt-2 flex items-center gap-2">
                    <span className={`inline-flex items-center px-2 sm:px-3 py-0.5 sm:py-1 rounded-full text-xs font-medium ${getStatusColor(selectedAppeal.status)}`}>
                      {selectedAppeal.status.replace(/_/g, ' ')}
                    </span>
                  </div>
                </div>

                {/* Appeal Reason */}
                <div className="border-t pt-4">
                  <p className="text-xs font-semibold text-gray-600 mb-2">Appeal Reason</p>
                  <p className="text-sm text-gray-900">{selectedAppeal.reason.replace(/_/g, ' ')}</p>
                </div>

                {/* Appeal Notes */}
                {selectedAppeal.notes && (
                  <div className="border-t pt-4">
                    <p className="text-xs font-semibold text-gray-600 mb-2">Appeal Details</p>
                    <p className="text-sm text-gray-900 whitespace-pre-wrap">{selectedAppeal.notes}</p>
                  </div>
                )}

                {/* Timeline */}
                <div className="border-t pt-4">
                  <p className="text-xs font-semibold text-gray-600 mb-3">Timeline</p>
                  <div className="space-y-2 text-sm">
                    <div className="flex justify-between">
                      <span className="text-gray-600">Submitted:</span>
                      <span className="font-medium text-gray-900">{new Date(selectedAppeal.submittedAt).toLocaleString()}</span>
                    </div>
                    {selectedAppeal.reviewedAt && (
                      <div className="flex justify-between">
                        <span className="text-gray-600">Reviewed:</span>
                        <span className="font-medium text-gray-900">{new Date(selectedAppeal.reviewedAt).toLocaleString()}</span>
                      </div>
                    )}
                  </div>
                </div>

                {/* Admin Response */}
                {selectedAppeal.adminResponse && (
                  <div className="border-t pt-4">
                    <p className="text-xs font-semibold text-gray-600 mb-2">Admin Response</p>
                    <div className="p-3 bg-blue-50 border border-blue-200 rounded-lg">
                      <p className="text-sm text-blue-900 whitespace-pre-wrap">{selectedAppeal.adminResponse}</p>
                    </div>
                    {selectedAppeal.admin && (
                      <p className="text-xs text-gray-600 mt-2">
                        Reviewed by: <span className="font-medium">{selectedAppeal.admin.name || selectedAppeal.admin.email}</span>
                      </p>
                    )}
                  </div>
                )}

                {/* Close Button */}
                <div className="border-t pt-4">
                  <button
                    onClick={() => setSelectedAppeal(null)}
                    className="w-full px-3 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition text-sm font-medium"
                  >
                    Close
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useEffect, useState } from 'react'
import _Image from 'next/image'
import Link from 'next/link'
import { ArrowLeft, Package, Clock, CheckCircle, XCircle, _Filter, ExternalLink } from 'lucide-react'

interface BoutiqueOrder {
  id: string
  orderNumber: string
  status: 'PENDING' | 'SHIPPED_TO_ADMIN' | 'RECEIVED_BY_ADMIN' | 'VERIFICATION_PASSED' | 'LIVE' | 'CANCELLED' | 'DISPUTE'
  totalAmount: number
  createdAt: string
  product: {
    id: string
    title: string
    thumbnailUrl: string | null
  }
  customer: {
    name: string | null
    email: string | null
  }
  quantity: number
}

export default function BoutiqueOrdersPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [orders, setOrders] = useState<BoutiqueOrder[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<string>('all')
  const [searchQuery, setSearchQuery] = useState('')

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (status !== 'authenticated') return

    fetchOrders()
  }, [status, router])

  const fetchOrders = async () => {
    try {
      setLoading(true)
      const response = await fetch('/api/seller/boutique-orders')
      if (response.ok) {
        const data = await response.json()
        setOrders(data.orders || [])
      }
    } catch (error) {
      console.error('Failed to fetch boutique orders:', error)
    } finally {
      setLoading(false)
    }
  }

  const filteredOrders = orders.filter(order => {
    const matchesFilter = filter === 'all' || order.status === filter
    const matchesSearch = order.orderNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
      order.product.title.toLowerCase().includes(searchQuery.toLowerCase())
    return matchesFilter && matchesSearch
  })

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'PENDING': return 'bg-yellow-100 text-yellow-800'
      case 'SHIPPED_TO_ADMIN': return 'bg-blue-100 text-blue-800'
      case 'RECEIVED_BY_ADMIN': return 'bg-indigo-100 text-indigo-800'
      case 'VERIFICATION_PASSED': return 'bg-green-100 text-green-800'
      case 'LIVE': return 'bg-emerald-100 text-emerald-800'
      case 'CANCELLED': return 'bg-red-100 text-red-800'
      case 'DISPUTE': return 'bg-orange-100 text-orange-800'
      default: return 'bg-gray-100 text-gray-800'
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'PENDING': return <Clock className="w-4 h-4" />
      case 'LIVE': return <CheckCircle className="w-4 h-4" />
      case 'CANCELLED': return <XCircle className="w-4 h-4" />
      default: return <Package className="w-4 h-4" />
    }
  }

  if (status === 'loading' || loading) {
    return <div className="p-8 text-center">Loading boutique orders...</div>
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 md:p-8">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <button
            onClick={() => router.back()}
            className="p-2 hover:bg-gray-200 rounded-lg transition"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Boutique Orders</h1>
            <p className="text-gray-600">Track orders placed by customers for your boutique products</p>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-sm p-4 mb-6">
          <div className="flex flex-col sm:flex-row gap-4">
            <input
              type="text"
              placeholder="Search by order # or product..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="flex-1 px-4 py-2 border border-gray-300 rounded-lg text-black"
            />
            <select
              value={filter}
              onChange={(e) => setFilter(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg text-black bg-white"
            >
              <option value="all">All Status</option>
              <option value="PENDING">Pending</option>
              <option value="SHIPPED_TO_ADMIN">Shipped to Admin</option>
              <option value="RECEIVED_BY_ADMIN">Received by Admin</option>
              <option value="VERIFICATION_PASSED">Verified</option>
              <option value="LIVE">Live</option>
              <option value="CANCELLED">Cancelled</option>
              <option value="DISPUTE">Dispute</option>
            </select>
          </div>
        </div>

        {/* Orders Table */}
        {filteredOrders.length === 0 ? (
          <div className="bg-white rounded-lg shadow-sm p-12 text-center">
            <Package className="w-12 h-12 text-gray-300 mx-auto mb-4" />
            <p className="text-gray-500">No boutique orders found</p>
          </div>
        ) : (
          <div className="bg-white rounded-lg shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Order</th>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Product</th>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Customer</th>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Qty</th>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Amount</th>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Status</th>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Date</th>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {filteredOrders.map((order) => (
                    <tr key={order.id} className="hover:bg-gray-50 transition">
                      <td className="px-4 py-3 text-sm font-medium text-gray-900">{order.orderNumber}</td>
                      <td className="px-4 py-3 text-sm text-gray-600">{order.product.title}</td>
                      <td className="px-4 py-3 text-sm text-gray-600">{order.customer.name}</td>
                      <td className="px-4 py-3 text-sm text-gray-600">{order.quantity}</td>
                      <td className="px-4 py-3 text-sm font-semibold text-indigo-600">${order.totalAmount.toFixed(2)}</td>
                      <td className="px-4 py-3">
                        <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium ${getStatusColor(order.status)}`}>
                          {getStatusIcon(order.status)}
                          {order.status.replace(/_/g, ' ')}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-sm text-gray-600">{new Date(order.createdAt).toLocaleDateString()}</td>
                      <td className="px-4 py-3">
                        <Link
                          href={`/seller/boutique-orders/${order.id}`}
                          className="inline-flex items-center gap-1 text-indigo-600 hover:text-indigo-800 transition"
                        >
                          <ExternalLink className="w-4 h-4" />
                          View
                        </Link>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Summary Stats */}
        {orders.length > 0 && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-8">
            <div className="bg-white rounded-lg p-4 text-center">
              <p className="text-2xl font-bold text-indigo-600">{orders.length}</p>
              <p className="text-xs text-gray-600 mt-1">Total Orders</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center">
              <p className="text-2xl font-bold text-yellow-600">{orders.filter(o => o.status === 'PENDING').length}</p>
              <p className="text-xs text-gray-600 mt-1">Pending</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center">
              <p className="text-2xl font-bold text-green-600">{orders.filter(o => o.status === 'LIVE').length}</p>
              <p className="text-xs text-gray-600 mt-1">Live</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center">
              <p className="text-2xl font-bold text-red-600">{orders.filter(o => o.status === 'CANCELLED').length}</p>
              <p className="text-xs text-gray-600 mt-1">Cancelled</p>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useEffect, useState } from 'react'
import Link from 'next/link'
import { ArrowLeft, Truck, Clock, CheckCircle, XCircle, AlertCircle, ExternalLink } from 'lucide-react'

interface Shipment {
  id: string
  shipmentNumber: string
  status: 'PENDING' | 'SHIPPED' | 'RECEIVED_BY_ADMIN' | 'VERIFICATION_PASSED' | 'VERIFICATION_FAILED' | 'DISPUTED'
  productCount: number
  itemsExpected: number
  itemsReceived: number | null
  itemsMissing: number | null
  itemsDamaged: number | null
  hasDiscrepancy: boolean
  createdAt: string
  shippedAt: string | null
  receivedAt: string | null
  trackingNumber: string | null
  notes: string | null
}

export default function BoutiqueShipmentsPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [shipments, setShipments] = useState<Shipment[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<string>('all')

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (status !== 'authenticated') return

    fetchShipments()
  }, [status, router])

  const fetchShipments = async () => {
    try {
      setLoading(true)
      const response = await fetch('/api/seller/boutique-shipments')
      if (response.ok) {
        const data = await response.json()
        setShipments(data.shipments || [])
      }
    } catch (error) {
      console.error('Failed to fetch shipments:', error)
    } finally {
      setLoading(false)
    }
  }

  const filteredShipments = shipments.filter(shipment => {
    return filter === 'all' || shipment.status === filter
  })

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'PENDING': return 'bg-yellow-100 text-yellow-800'
      case 'SHIPPED': return 'bg-blue-100 text-blue-800'
      case 'RECEIVED_BY_ADMIN': return 'bg-indigo-100 text-indigo-800'
      case 'VERIFICATION_PASSED': return 'bg-green-100 text-green-800'
      case 'VERIFICATION_FAILED': return 'bg-red-100 text-red-800'
      case 'DISPUTED': return 'bg-orange-100 text-orange-800'
      default: return 'bg-gray-100 text-gray-800'
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'PENDING': return <Clock className="w-4 h-4" />
      case 'SHIPPED': return <Truck className="w-4 h-4" />
      case 'VERIFICATION_PASSED': return <CheckCircle className="w-4 h-4" />
      case 'VERIFICATION_FAILED': return <XCircle className="w-4 h-4" />
      case 'DISPUTED': return <AlertCircle className="w-4 h-4" />
      default: return <Truck className="w-4 h-4" />
    }
  }

  if (status === 'loading' || loading) {
    return <div className="p-8 text-center">Loading shipments...</div>
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 md:p-8">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <button
            onClick={() => router.back()}
            className="p-2 hover:bg-gray-200 rounded-lg transition"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Warehouse Shipments</h1>
            <p className="text-gray-600">Track your shipments to the admin warehouse</p>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-sm p-4 mb-6">
          <select
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            className="px-4 py-2 border border-gray-300 rounded-lg text-black bg-white"
          >
            <option value="all">All Status</option>
            <option value="PENDING">Pending</option>
            <option value="SHIPPED">Shipped</option>
            <option value="RECEIVED_BY_ADMIN">Received by Admin</option>
            <option value="VERIFICATION_PASSED">Verified Γ£ô</option>
            <option value="VERIFICATION_FAILED">Verification Failed</option>
            <option value="DISPUTED">Disputed</option>
          </select>
        </div>

        {/* Shipments Table */}
        {filteredShipments.length === 0 ? (
          <div className="bg-white rounded-lg shadow-sm p-12 text-center">
            <Truck className="w-12 h-12 text-gray-300 mx-auto mb-4" />
            <p className="text-gray-500">No shipments found</p>
          </div>
        ) : (
          <div className="bg-white rounded-lg shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Shipment</th>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Tracking</th>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Items</th>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Verification</th>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Status</th>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Shipped</th>
                    <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {filteredShipments.map((shipment) => (
                    <tr key={shipment.id} className="hover:bg-gray-50 transition">
                      <td className="px-4 py-3 text-sm font-medium text-gray-900">{shipment.shipmentNumber}</td>
                      <td className="px-4 py-3 text-sm text-gray-600">{shipment.trackingNumber || 'Pending'}</td>
                      <td className="px-4 py-3 text-sm text-gray-600">
                        <span className="font-semibold">{shipment.itemsExpected}</span> expected
                        {shipment.itemsReceived !== null && (
                          <span> / <span className={shipment.itemsReceived === shipment.itemsExpected ? 'text-green-600' : 'text-orange-600'}>{shipment.itemsReceived}</span> received</span>
                        )}
                      </td>
                      <td className="px-4 py-3 text-sm">
                        {shipment.hasDiscrepancy && (
                          <span className="inline-flex items-center gap-1 px-2 py-1 bg-orange-100 text-orange-800 rounded text-xs">
                            <AlertCircle className="w-3 h-3" />
                            Discrepancy
                          </span>
                        )}
                        {!shipment.hasDiscrepancy && shipment.status === 'VERIFICATION_PASSED' && (
                          <span className="text-green-600 text-xs font-semibold">Γ£ô Passed</span>
                        )}
                      </td>
                      <td className="px-4 py-3">
                        <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium ${getStatusColor(shipment.status)}`}>
                          {getStatusIcon(shipment.status)}
                          {shipment.status.replace(/_/g, ' ')}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-sm text-gray-600">
                        {shipment.shippedAt ? new Date(shipment.shippedAt).toLocaleDateString() : 'Not shipped'}
                      </td>
                      <td className="px-4 py-3">
                        <Link
                          href={`/seller/boutique-shipments/${shipment.id}`}
                          className="inline-flex items-center gap-1 text-indigo-600 hover:text-indigo-800 transition"
                        >
                          <ExternalLink className="w-4 h-4" />
                          Details
                        </Link>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Summary Stats */}
        {shipments.length > 0 && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-8">
            <div className="bg-white rounded-lg p-4 text-center">
              <p className="text-2xl font-bold text-indigo-600">{shipments.length}</p>
              <p className="text-xs text-gray-600 mt-1">Total Shipments</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center">
              <p className="text-2xl font-bold text-blue-600">{shipments.filter(s => s.status === 'SHIPPED').length}</p>
              <p className="text-xs text-gray-600 mt-1">In Transit</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center">
              <p className="text-2xl font-bold text-green-600">{shipments.filter(s => s.status === 'VERIFICATION_PASSED').length}</p>
              <p className="text-xs text-gray-600 mt-1">Verified</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center">
              <p className="text-2xl font-bold text-orange-600">{shipments.filter(s => s.hasDiscrepancy).length}</p>
              <p className="text-xs text-gray-600 mt-1">Discrepancies</p>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useSession } from 'next-auth/react';
import Link from 'next/link';
import Image from 'next/image';
import { 
  Package, 
  ArrowLeft, 
  DollarSign,
  Clock,
  CheckCircle,
  TrendingUp,
  Wallet,
  ArrowUpRight,
} from 'lucide-react';

interface Payout {
  id: string;
  amount: number;
  status: string;
  reference: string;
  createdAt: string;
  paidAt: string | null;
}

interface Order {
  id: string;
  orderNumber: string;
  status: string;
  total: number;
  sellerPayout: number;
  platformFee: number;
  createdAt: string;
  completedAt: string | null;
  items: Array<{
    quantity: number;
    product: { title: string; thumbnailUrl: string | null };
  }>;
}

interface EarningsData {
  summary: {
    totalEarnings: number;
    periodEarnings: number;
    pendingEarnings: number;
    availableBalance: number;
    totalPaidOut: number;
  };
  payouts: Payout[];
  recentOrders: Order[];
  ordersByStatus: Array<{ status: string; count: number; earnings: number }>;
  period: number;
}

export default function SellerBoutiqueEarningsPage() {
  const { data: session, status: authStatus } = useSession();
  const router = useRouter();
  const [data, setData] = useState<EarningsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [period, setPeriod] = useState('30');

  useEffect(() => {
    if (authStatus === 'unauthenticated') {
      router.push('/auth/signin?callbackUrl=/seller/boutique/earnings');
    } else if (authStatus === 'authenticated') {
      fetchEarnings();
    }
  }, [authStatus, router, period]);

  const fetchEarnings = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/boutique/seller/earnings?period=${period}`);
      const result = await response.json();
      
      if (result.success) {
        setData(result);
      }
    } catch (error) {
      console.error('Error fetching earnings:', error);
    } finally {
      setLoading(false);
    }
  };

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat('en-NG', {
      style: 'currency',
      currency: 'NGN',
      minimumFractionDigits: 0,
    }).format(price);
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-NG', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    });
  };

  if (authStatus === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin h-8 w-8 border-4 border-purple-500 border-t-transparent rounded-full"></div>
      </div>
    );
  }

  if (!session || !data) return null;

  return (
    <div className="min-h-screen bg-gray-50 py-4 sm:py-8">
      <div className="max-w-6xl mx-auto px-3 sm:px-4">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 sm:gap-0 mb-4 sm:mb-8">
          <div className="flex items-center gap-2 sm:gap-4">
            <Link 
              href="/seller/boutique" 
              className="p-1.5 sm:p-2 hover:bg-gray-100 rounded-lg transition"
            >
              <ArrowLeft className="w-4 h-4 sm:w-5 sm:h-5 text-gray-600" />
            </Link>
            <div>
              <h1 className="text-lg sm:text-2xl font-bold text-gray-900 flex items-center gap-1.5 sm:gap-2">
                <Wallet className="w-5 h-5 sm:w-6 sm:h-6 text-purple-600" />
                Boutique Earnings
              </h1>
              <p className="text-[10px] sm:text-sm text-gray-500">
                Track your physical product sales and payouts
              </p>
            </div>
          </div>
          <select
            value={period}
            onChange={(e) => setPeriod(e.target.value)}
            className="px-3 sm:px-4 py-1.5 sm:py-2 border border-gray-200 rounded-lg bg-white text-gray-900 text-xs sm:text-sm"
            aria-label="Select earnings period"
          >
            <option value="7">Last 7 days</option>
            <option value="30">Last 30 days</option>
            <option value="90">Last 90 days</option>
            <option value="365">Last year</option>
          </select>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-2 sm:gap-4 mb-4 sm:mb-8">
          <div className="bg-white rounded-lg sm:rounded-xl shadow-sm p-3 sm:p-6">
            <div className="flex items-center justify-between mb-2 sm:mb-3">
              <div className="w-8 h-8 sm:w-10 sm:h-10 bg-purple-100 rounded-lg flex items-center justify-center">
                <TrendingUp className="w-4 h-4 sm:w-5 sm:h-5 text-purple-600" />
              </div>
              <span className="text-[10px] sm:text-xs text-green-600 font-medium flex items-center gap-0.5 sm:gap-1">
                <ArrowUpRight className="w-2.5 h-2.5 sm:w-3 sm:h-3" />
                Period
              </span>
            </div>
            <p className="text-sm sm:text-2xl font-bold text-gray-900">
              {formatPrice(data.summary.periodEarnings)}
            </p>
            <p className="text-[10px] sm:text-sm text-gray-500">Last {data.period} days</p>
          </div>

          <div className="bg-white rounded-lg sm:rounded-xl shadow-sm p-3 sm:p-6">
            <div className="flex items-center justify-between mb-2 sm:mb-3">
              <div className="w-8 h-8 sm:w-10 sm:h-10 bg-green-100 rounded-lg flex items-center justify-center">
                <DollarSign className="w-4 h-4 sm:w-5 sm:h-5 text-green-600" />
              </div>
            </div>
            <p className="text-sm sm:text-2xl font-bold text-gray-900">
              {formatPrice(data.summary.totalEarnings)}
            </p>
            <p className="text-[10px] sm:text-sm text-gray-500">Total Earnings</p>
          </div>

          <div className="bg-white rounded-lg sm:rounded-xl shadow-sm p-3 sm:p-6">
            <div className="flex items-center justify-between mb-2 sm:mb-3">
              <div className="w-8 h-8 sm:w-10 sm:h-10 bg-yellow-100 rounded-lg flex items-center justify-center">
                <Clock className="w-4 h-4 sm:w-5 sm:h-5 text-yellow-600" />
              </div>
            </div>
            <p className="text-sm sm:text-2xl font-bold text-gray-900">
              {formatPrice(data.summary.pendingEarnings)}
            </p>
            <p className="text-[10px] sm:text-sm text-gray-500">Pending</p>
          </div>

          <div className="bg-white rounded-lg sm:rounded-xl shadow-sm p-3 sm:p-6">
            <div className="flex items-center justify-between mb-2 sm:mb-3">
              <div className="w-8 h-8 sm:w-10 sm:h-10 bg-indigo-100 rounded-lg flex items-center justify-center">
                <Wallet className="w-4 h-4 sm:w-5 sm:h-5 text-indigo-600" />
              </div>
            </div>
            <p className="text-sm sm:text-2xl font-bold text-gray-900">
              {formatPrice(data.summary.availableBalance)}
            </p>
            <p className="text-[10px] sm:text-sm text-gray-500">Available</p>
          </div>
        </div>

        <div className="grid lg:grid-cols-2 gap-4 sm:gap-8">
          {/* Recent Orders */}
          <div className="bg-white rounded-lg sm:rounded-xl shadow-sm p-4 sm:p-6">
            <div className="flex items-center justify-between mb-3 sm:mb-4">
              <h2 className="text-sm sm:text-lg font-semibold text-gray-900">Recent Sales</h2>
              <Link href="/seller/boutique/orders" className="text-xs sm:text-sm text-purple-600 hover:text-purple-700">
                View all
              </Link>
            </div>
            
            {data.recentOrders.length === 0 ? (
              <div className="text-center py-6 sm:py-8 text-gray-500">
                <Package className="w-8 h-8 sm:w-12 sm:h-12 mx-auto mb-2 opacity-50" />
                <p className="text-xs sm:text-sm">No sales yet</p>
              </div>
            ) : (
              <div className="space-y-2 sm:space-y-3">
                {data.recentOrders.slice(0, 8).map((order) => (
                  <Link
                    key={order.id}
                    href={`/seller/boutique/orders?order=${order.orderNumber}`}
                    className="flex items-center gap-2 sm:gap-3 p-2 sm:p-3 rounded-lg hover:bg-gray-50 transition"
                  >
                    <div className="w-8 h-8 sm:w-10 sm:h-10 rounded-lg overflow-hidden bg-gray-100 relative shrink-0">
                      {order.items[0]?.product.thumbnailUrl ? (
                        <Image
                          src={order.items[0].product.thumbnailUrl}
                          alt=""
                          fill
                          className="object-cover"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center">
                          <Package className="w-4 h-4 sm:w-5 sm:h-5 text-gray-300" />
                        </div>
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-xs sm:text-sm font-medium text-gray-900 truncate">
                        #{order.orderNumber}
                      </p>
                      <p className="text-[10px] sm:text-xs text-gray-500">{formatDate(order.createdAt)}</p>
                    </div>
                    <div className="text-right">
                      <p className="font-semibold text-green-600 text-xs sm:text-sm">
                        +{formatPrice(order.sellerPayout)}
                      </p>
                      <span className={`text-[10px] sm:text-xs px-1.5 sm:px-2 py-0.5 rounded-full ${
                        order.status === 'COMPLETED' ? 'bg-green-100 text-green-700' :
                        order.status === 'DELIVERED' ? 'bg-blue-100 text-blue-700' :
                        order.status === 'SHIPPED' ? 'bg-purple-100 text-purple-700' :
                        'bg-yellow-100 text-yellow-700'
                      }`}>
                        {order.status}
                      </span>
                    </div>
                  </Link>
                ))}
              </div>
            )}
          </div>

          {/* Payout History */}
          <div className="bg-white rounded-lg sm:rounded-xl shadow-sm p-4 sm:p-6">
            <div className="flex items-center justify-between mb-3 sm:mb-4">
              <h2 className="text-sm sm:text-lg font-semibold text-gray-900">Payout History</h2>
              <span className="text-[10px] sm:text-sm text-gray-500">
                Total: {formatPrice(data.summary.totalPaidOut)}
              </span>
            </div>
            
            {data.payouts.length === 0 ? (
              <div className="text-center py-6 sm:py-8 text-gray-500">
                <Wallet className="w-8 h-8 sm:w-12 sm:h-12 mx-auto mb-2 opacity-50" />
                <p className="text-xs sm:text-sm">No payouts yet</p>
                <p className="text-[10px] sm:text-xs mt-1">Payouts are processed automatically</p>
              </div>
            ) : (
              <div className="space-y-2 sm:space-y-3">
                {data.payouts.map((payout) => (
                  <div
                    key={payout.id}
                    className="flex items-center gap-2 sm:gap-3 p-2 sm:p-3 rounded-lg bg-gray-50"
                  >
                    <div className={`w-8 h-8 sm:w-10 sm:h-10 rounded-full flex items-center justify-center ${
                      payout.status === 'COMPLETED' ? 'bg-green-100' : 'bg-yellow-100'
                    }`}>
                      {payout.status === 'COMPLETED' ? (
                        <CheckCircle className="w-4 h-4 sm:w-5 sm:h-5 text-green-600" />
                      ) : (
                        <Clock className="w-4 h-4 sm:w-5 sm:h-5 text-yellow-600" />
                      )}
                    </div>
                    <div className="flex-1">
                      <p className="text-xs sm:text-sm font-medium text-gray-900">
                        {formatPrice(payout.amount)}
                      </p>
                      <p className="text-[10px] sm:text-xs text-gray-500">
                        {payout.status === 'COMPLETED' && payout.paidAt
                          ? `Paid ${formatDate(payout.paidAt)}`
                          : `Pending ΓÇó ${formatDate(payout.createdAt)}`
                        }
                      </p>
                    </div>
                    <span className="text-[10px] sm:text-xs font-mono text-gray-400 hidden xs:block">
                      {payout.reference.slice(0, 12)}...
                    </span>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Earnings by Status */}
        <div className="mt-4 sm:mt-8 bg-white rounded-lg sm:rounded-xl shadow-sm p-4 sm:p-6">
          <h2 className="text-sm sm:text-lg font-semibold text-gray-900 mb-3 sm:mb-4">Earnings by Order Status</h2>
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-2 sm:gap-4">
            {data.ordersByStatus.map((stat) => (
              <div key={stat.status} className="p-2 sm:p-4 bg-gray-50 rounded-lg">
                <p className="text-[10px] sm:text-xs text-gray-500 uppercase">{stat.status}</p>
                <p className="text-sm sm:text-lg font-bold text-gray-900">{stat.count}</p>
                <p className="text-xs sm:text-sm text-green-600">{formatPrice(stat.earnings)}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

'use client'

import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useEffect, useState, useCallback } from 'react'
import Image from 'next/image'
import Link from 'next/link'
import toast from 'react-hot-toast'
import { useCurrency } from '@/components/CurrencyProvider'
import { SubscriptionRequiredModal } from '@/components/SubscriptionRequiredModal'
import { FeaturedItemsConfirmationModal } from '@/components/FeaturedItemsConfirmationModal'
import { 
  ArrowLeft,
  Search,
  Filter,
  _Trash2,
  Star,
  BarChart3,
  TrendingUp,
  CheckCircle2,
  GripVertical,
  Copy,
  Plus
} from 'lucide-react'

interface BoutiqueProduct {
  id: string
  title: string
  thumbnailUrl: string | null
  basePrice: number
  salePrice: number | null
  status: string
  currentStock: number
  totalSales: number
  totalRevenue: number
  createdAt: string
  seller: {
    name: string
  }
  _count?: {
    reviews: number
  }
  avgRating?: number
  featured?: boolean
  addedByAdmin?: boolean
}

function _formatDate(dateString: string): string {
  return new Date(dateString).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  })
}

export default function SellerBoutiqueFeaturedPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const { formatPrice } = useCurrency()
  const [products, setProducts] = useState<BoutiqueProduct[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [sortBy, setSortBy] = useState('newest')
  const [showFeaturedOnly, setShowFeaturedOnly] = useState(false)
  const [togglingFeatured, setTogglingFeatured] = useState<string | null>(null)
  const [subscriptionModal, setSubscriptionModal] = useState<{
    isOpen: boolean
    currentTier?: string
    current?: number
    max?: number
    errorCode?: 'NO_FEATURED_ACCESS' | 'TIER_LIMIT_REACHED'
  }>({ isOpen: false })
  const [featuredConfirmation, setFeaturedConfirmation] = useState<{
    isOpen: boolean
    productId: string | null
    productTitle: string | null
    subscriptionTier: string | null
    maxFeatured: number
    currentFeatured: number
    remainingSlots: number
  }>({
    isOpen: false,
    productId: null,
    productTitle: null,
    subscriptionTier: null,
    maxFeatured: 0,
    currentFeatured: 0,
    remainingSlots: 0
  })
  const [selectedProducts, setSelectedProducts] = useState<Set<string>>(new Set())
  const [draggingId, setDraggingId] = useState<string | null>(null)
  const [topProducts, setTopProducts] = useState<BoutiqueProduct[]>([])
  const [featuredAnalytics, setFeaturedAnalytics] = useState<{
    featuredTotal: number
    nonFeaturedTotal: number
    featuredPercentage: number
  }>({ featuredTotal: 0, nonFeaturedTotal: 0, featuredPercentage: 0 })

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/auth/signin')
    }
  }, [status, router])

  const fetchProducts = useCallback(async () => {
    try {
      setLoading(true)
      const response = await fetch('/api/boutique/seller/products')
      if (!response.ok) throw new Error('Failed to fetch products')
      
      const data = await response.json()
      if (!data.products) throw new Error('Invalid response format')
      
      // Separate LIVE featured and non-featured
      const allLive = (data.products as BoutiqueProduct[]).filter(p => p.status === 'LIVE')
      const featured = allLive.filter(p => p.featured)
      const nonFeatured = allLive.filter(p => !p.featured)
      
      // Calculate featured analytics
      const featuredRevenue = featured.reduce((sum, p) => sum + (p.totalRevenue || 0), 0)
      const nonFeaturedRevenue = nonFeatured.reduce((sum, p) => sum + (p.totalRevenue || 0), 0)
      const totalRevenue = featuredRevenue + nonFeaturedRevenue
      
      setFeaturedAnalytics({
        featuredTotal: Math.round((featuredRevenue / (totalRevenue || 1)) * 100),
        nonFeaturedTotal: Math.round((nonFeaturedRevenue / (totalRevenue || 1)) * 100),
        featuredPercentage: featured.length > 0 ? Math.round((featuredRevenue / featured.length) / (nonFeaturedRevenue / Math.max(nonFeatured.length, 1))) : 0
      })
      
      // Find top 3 selling products (non-featured)
      const topThree = nonFeatured
        .sort((a, b) => b.totalSales - a.totalSales)
        .slice(0, 3)
      
      setTopProducts(topThree)
      
      let filtered = allLive
      
      if (showFeaturedOnly) {
        filtered = filtered.filter(p => p.featured)
      }
      
      if (searchQuery) {
        const q = searchQuery.toLowerCase()
        filtered = filtered.filter(p => 
          p.title.toLowerCase().includes(q)
        )
      }
      
      // Sort
      filtered.sort((a, b) => {
        switch (sortBy) {
          case 'newest':
            return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
          case 'oldest':
            return new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
          case 'price-high':
            return (b.salePrice || b.basePrice) - (a.salePrice || a.basePrice)
          case 'price-low':
            return (a.salePrice || a.basePrice) - (b.salePrice || b.basePrice)
          case 'sales':
            return b.totalSales - a.totalSales
          default:
            return 0
        }
      })
      
      setProducts(filtered)
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Failed to load products'
      toast.error(message)
      console.error('Error fetching products:', error)
    } finally {
      setLoading(false)
    }
  }, [searchQuery, sortBy, showFeaturedOnly])

  useEffect(() => {
    fetchProducts()
  }, [fetchProducts])

  const handleToggleFeatured = async (productId: string, productTitle: string) => {
    try {
      setTogglingFeatured(productId)
      const product = products.find(p => p.id === productId)
      
      if (product?.featured) {
        // Remove from featured
        const res = await fetch(`/api/seller/featured-boutique-products?productId=${productId}`, {
          method: 'DELETE'
        })
        
        if (!res.ok) {
          const error = await res.json()
          throw new Error(error.error || 'Failed to remove from featured')
        }
        
        toast.success('Removed from featured')
        setProducts(products.map(p => 
          p.id === productId ? { ...p, featured: false } : p
        ))
      } else {
        // Add to featured - show confirmation
        const res = await fetch('/api/seller/featured-boutique-products')
        if (!res.ok) throw new Error('Failed to fetch featured info')
        
        const data = await res.json()
        setFeaturedConfirmation({
          isOpen: true,
          productId,
          productTitle,
          subscriptionTier: data.subscriptionTier,
          maxFeatured: data.maxFeatured,
          currentFeatured: data.currentFeatured,
          remainingSlots: data.remainingSlots
        })
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Failed to update featured status'
      
      if (message.includes('TIER_LIMIT_REACHED')) {
        setSubscriptionModal({
          isOpen: true,
          errorCode: 'TIER_LIMIT_REACHED',
          current: (error as any)?.current,
          max: (error as any)?.max,
          currentTier: (error as any)?.currentTier
        })
      } else if (message.includes('NO_FEATURED_ACCESS')) {
        setSubscriptionModal({
          isOpen: true,
          errorCode: 'NO_FEATURED_ACCESS'
        })
      } else {
        toast.error(message)
      }
    } finally {
      setTogglingFeatured(null)
    }
  }

  const handleConfirmFeatured = async () => {
    const { productId } = featuredConfirmation
    if (!productId) return
    
    try {
      const res = await fetch('/api/seller/featured-boutique-products', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ productId })
      })
      
      if (!res.ok) {
        const error = await res.json()
        if (error.error?.includes('TIER_LIMIT_REACHED')) {
          setSubscriptionModal({
            isOpen: true,
            errorCode: 'TIER_LIMIT_REACHED',
            current: error.current,
            max: error.max,
            currentTier: error.currentTier
          })
        } else if (error.error?.includes('NO_FEATURED_ACCESS')) {
          setSubscriptionModal({
            isOpen: true,
            errorCode: 'NO_FEATURED_ACCESS'
          })
        } else {
          throw new Error(error.error || 'Failed to add to featured')
        }
      } else {
        toast.success('Product added to featured!')
        setProducts(products.map(p =>
          p.id === productId ? { ...p, featured: true } : p
        ))
        setFeaturedConfirmation({ isOpen: false, productId: null, productTitle: null, subscriptionTier: null, maxFeatured: 0, currentFeatured: 0, remainingSlots: 0 })
      }
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Failed to add to featured')
    }
  }

  const handleBulkToggleFeatured = async () => {
    const selectedArray = Array.from(selectedProducts)
    if (selectedArray.length === 0) return
    
    try {
      const featured = products.filter(p => selectedArray.includes(p.id) && p.featured)
      const notFeatured = products.filter(p => selectedArray.includes(p.id) && !p.featured)
      
      // Remove from featured
      for (const productId of featured.map(p => p.id)) {
        const res = await fetch(`/api/seller/featured-boutique-products?productId=${productId}`, {
          method: 'DELETE'
        })
        if (!res.ok) throw new Error('Failed to remove from featured')
      }
      
      // Add to featured
      for (const productId of notFeatured.map(p => p.id)) {
        const res = await fetch('/api/seller/featured-boutique-products', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ productId })
        })
        if (!res.ok) throw new Error('Failed to add to featured')
      }
      
      toast.success(`Updated ${selectedArray.length} products`)
      setSelectedProducts(new Set())
      fetchProducts()
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Failed to update products')
    }
  }

  const handleDragStart = (productId: string) => {
    setDraggingId(productId)
  }

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
  }

  const handleDrop = async (dropProductId: string) => {
    if (!draggingId || draggingId === dropProductId) {
      setDraggingId(null)
      return
    }
    
    const draggedIndex = products.findIndex(p => p.id === draggingId)
    const targetIndex = products.findIndex(p => p.id === dropProductId)
    
    if (draggedIndex === -1 || targetIndex === -1) return
    
    // Reorder locally
    const newProducts = [...products]
    const [removed] = newProducts.splice(draggedIndex, 1)
    newProducts.splice(targetIndex, 0, removed)
    setProducts(newProducts)
    
    // Update position on backend
    try {
      const res = await fetch(`/api/seller/featured-boutique-products?id=${draggingId}&position=${targetIndex}`, {
        method: 'PATCH'
      })
      if (!res.ok) throw new Error('Failed to update position')
      toast.success('Product order updated')
    } catch (_error) {
      toast.error('Failed to save order')
      fetchProducts() // Revert
    }
    
    setDraggingId(null)
  }

  const addTopProductToFeatured = (productId: string) => {
    const product = topProducts.find(p => p.id === productId)
    if (!product) return
    
    setFeaturedConfirmation({
      isOpen: true,
      productId,
      productTitle: product.title,
      subscriptionTier: 'STANDARD',
      maxFeatured: 3,
      currentFeatured: products.filter(p => p.featured).length,
      remainingSlots: 3 - products.filter(p => p.featured).length
    })
  }

  const toggleProductSelection = (productId: string) => {
    const newSelected = new Set(selectedProducts)
    if (newSelected.has(productId)) {
      newSelected.delete(productId)
    } else {
      newSelected.add(productId)
    }
    setSelectedProducts(newSelected)
  }

  const _toggleSelectAll = () => {
    if (selectedProducts.size === products.length) {
      setSelectedProducts(new Set())
    } else {
      setSelectedProducts(new Set(products.map(p => p.id)))
    }
  }

  if (status === 'loading') {
    return (
      <div className="min-h-screen bg-gradient-to-br from-purple-50 to-blue-50 p-4 md:p-8">
        <div className="max-w-7xl mx-auto">
          <div className="animate-pulse space-y-4">
            <div className="h-8 bg-gray-200 rounded w-1/4"></div>
            <div className="h-64 bg-gray-200 rounded"></div>
          </div>
        </div>
      </div>
    )
  }

  const filteredProducts = showFeaturedOnly 
    ? products.filter(p => p.featured)
    : products

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 to-blue-50 p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <Link href="/seller/boutique">
            <button className="p-2 hover:bg-white rounded-lg transition-colors">
              <ArrowLeft size={20} />
            </button>
          </Link>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Featured Boutique Products</h1>
            <p className="text-gray-600 mt-1">Feature your best boutique products to increase visibility</p>
          </div>
        </div>

        {/* Controls */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {/* Search */}
            <div className="relative">
              <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
              <input
                type="text"
                placeholder="Search products..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-purple-500"
              />
            </div>

            {/* Sort */}
            <div className="flex gap-2">
              <Filter size={18} className="text-gray-400 mt-2" />
              <select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value)}
                className="flex-1 px-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-purple-500"
              >
                <option value="newest">Newest First</option>
                <option value="oldest">Oldest First</option>
                <option value="price-high">Price: High to Low</option>
                <option value="price-low">Price: Low to High</option>
                <option value="sales">Most Sales</option>
              </select>
            </div>

            {/* Filter Toggle */}
            <button
              onClick={() => setShowFeaturedOnly(!showFeaturedOnly)}
              className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                showFeaturedOnly
                  ? 'bg-purple-100 text-purple-700 border border-purple-300'
                  : 'bg-gray-100 text-gray-700 border border-gray-300 hover:bg-gray-200'
              }`}
            >
              <Star size={18} className="inline mr-2" />
              {showFeaturedOnly ? 'Featured Only' : 'Show All'}
            </button>
          </div>
        </div>

        {/* Featured Analytics */}
        {products.length > 0 && (
          <div className="bg-white rounded-lg shadow-sm p-6 mb-8">
            <h2 className="text-lg font-semibold text-gray-900 mb-4 flex items-center gap-2">
              <BarChart3 size={20} className="text-purple-600" />
              Featured Performance
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="bg-gradient-to-br from-purple-50 to-purple-100 rounded-lg p-4 border border-purple-200">
                <div className="text-sm text-purple-700 font-medium mb-1">Featured Products Revenue</div>
                <div className="text-2xl font-bold text-purple-900">{featuredAnalytics.featuredTotal}%</div>
                <div className="text-xs text-purple-600 mt-2">of total revenue</div>
              </div>
              <div className="bg-gradient-to-br from-gray-50 to-gray-100 rounded-lg p-4 border border-gray-200">
                <div className="text-sm text-gray-700 font-medium mb-1">Non-Featured Products Revenue</div>
                <div className="text-2xl font-bold text-gray-900">{featuredAnalytics.nonFeaturedTotal}%</div>
                <div className="text-xs text-gray-600 mt-2">of total revenue</div>
              </div>
              <div className="bg-gradient-to-br from-green-50 to-green-100 rounded-lg p-4 border border-green-200">
                <div className="text-sm text-green-700 font-medium mb-1">Average Per Featured Product</div>
                <div className="text-2xl font-bold text-green-900">{featuredAnalytics.featuredPercentage}x</div>
                <div className="text-xs text-green-600 mt-2">vs non-featured</div>
              </div>
            </div>
          </div>
        )}

        {/* Auto-Suggest Top Products */}
        {topProducts.length > 0 && (
          <div className="bg-gradient-to-r from-blue-50 to-cyan-50 rounded-lg shadow-sm p-6 mb-8 border border-blue-200">
            <h2 className="text-lg font-semibold text-gray-900 mb-4 flex items-center gap-2">
              <TrendingUp size={20} className="text-blue-600" />
              Your Top Selling Products
            </h2>
            <p className="text-sm text-gray-600 mb-4">These products are selling well. Feature them to boost visibility even further.</p>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {topProducts.map((product) => (
                <div key={product.id} className="bg-white rounded-lg p-4 border border-blue-100 hover:border-blue-300 transition-colors">
                  <div className="flex gap-3 mb-3">
                    {product.thumbnailUrl && (
                      <div className="relative w-16 h-16 flex-shrink-0">
                        <Image
                          src={product.thumbnailUrl}
                          alt={product.title}
                          fill
                          className="object-cover rounded"
                        />
                      </div>
                    )}
                    <div className="flex-1 min-w-0">
                      <h3 className="font-semibold text-gray-900 text-sm line-clamp-2">{product.title}</h3>
                      <div className="text-purple-600 font-bold text-sm mt-1">{product.totalSales} sales</div>
                    </div>
                  </div>
                  {!product.featured && (
                    <button
                      onClick={() => addTopProductToFeatured(product.id)}
                      className="w-full bg-blue-600 hover:bg-blue-700 text-white px-3 py-2 rounded font-medium text-sm transition-colors flex items-center justify-center gap-2"
                    >
                      <Copy size={14} />
                      Feature This
                    </button>
                  )}
                  {product.featured && (
                    <div className="flex items-center gap-2 text-green-600 text-sm font-medium">
                      <CheckCircle2 size={16} fill="currentColor" />
                      Already Featured
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Products Grid */}
        {loading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {[...Array(6)].map((_, i) => (
              <div key={i} className="bg-white rounded-lg shadow-sm p-4 animate-pulse">
                <div className="bg-gray-200 h-48 rounded-lg mb-4"></div>
                <div className="h-4 bg-gray-200 rounded mb-2"></div>
                <div className="h-4 bg-gray-200 rounded w-2/3"></div>
              </div>
            ))}
          </div>
        ) : filteredProducts.length === 0 ? (
          <div className="bg-white rounded-lg shadow-sm p-12 text-center">
            <BarChart3 size={48} className="mx-auto text-gray-300 mb-4" />
            <h3 className="text-xl font-semibold text-gray-900 mb-2">
              {showFeaturedOnly ? 'No featured products yet' : 'No live products'}
            </h3>
            <p className="text-gray-600 mb-4">
              {showFeaturedOnly 
                ? 'Feature your best products to showcase them here.'
                : 'Make sure your products are approved and LIVE to feature them.'}
            </p>
            <Link href="/seller/boutique">
              <button className="inline-flex items-center gap-2 bg-purple-600 hover:bg-purple-700 text-white px-6 py-2 rounded-lg font-medium transition-colors">
                <Plus size={18} />
                Go to Boutique Products
              </button>
            </Link>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredProducts.map((product) => (
              <div
                key={product.id}
                draggable={product.featured}
                onDragStart={() => handleDragStart(product.id)}
                onDragOver={handleDragOver}
                onDrop={() => handleDrop(product.id)}
                className={`bg-white rounded-lg shadow-sm overflow-hidden hover:shadow-md transition-shadow cursor-move relative ${
                  draggingId === product.id ? 'opacity-50' : ''
                } ${
                  selectedProducts.has(product.id) ? 'ring-2 ring-purple-500' : ''
                }`}
              >
                {/* Checkbox & Drag Handle */}
                <div className="absolute top-2 left-2 flex gap-2 z-10">
                  <input
                    type="checkbox"
                    checked={selectedProducts.has(product.id)}
                    onChange={() => toggleProductSelection(product.id)}
                    className="w-5 h-5 rounded cursor-pointer"
                  />
                  {product.featured && (
                    <div className="bg-white/90 backdrop-blur p-1.5 rounded text-gray-600 hover:text-gray-900">
                      <GripVertical size={18} />
                    </div>
                  )}
                </div>

                {/* Image */}
                <div className="relative h-48 bg-gray-100 overflow-hidden group">
                  {product.thumbnailUrl && (
                    <Image
                      src={product.thumbnailUrl}
                      alt={product.title}
                      fill
                      className="object-cover group-hover:scale-105 transition-transform"
                    />
                  )}
                  {product.featured && (
                    <div className="absolute top-2 right-2 bg-purple-600 text-white px-3 py-1 rounded-full text-sm font-semibold flex items-center gap-1">
                      <Star size={14} fill="currentColor" />
                      Featured
                    </div>
                  )}
                </div>

                {/* Content */}
                <div className="p-4">
                  <h3 className="font-semibold text-gray-900 mb-1 line-clamp-2">{product.title}</h3>
                  
                  {/* Price */}
                  <div className="text-lg font-bold text-purple-600 mb-3">
                    {formatPrice(product.salePrice || product.basePrice)}
                  </div>

                  {/* Stats */}
                  <div className="grid grid-cols-3 gap-2 text-xs text-gray-600 mb-4 pb-4 border-b border-gray-100">
                    <div>
                      <div className="font-semibold text-gray-900">{product.totalSales || 0}</div>
                      <div>Sales</div>
                    </div>
                    <div>
                      <div className="font-semibold text-gray-900">{formatPrice(product.totalRevenue || 0)}</div>
                      <div>Revenue</div>
                    </div>
                    <div>
                      <div className="font-semibold text-gray-900">{product.avgRating?.toFixed(1) || 'N/A'}</div>
                      <div>Rating</div>
                    </div>
                  </div>

                  {/* Actions */}
                  <button
                    onClick={() => handleToggleFeatured(product.id, product.title)}
                    disabled={togglingFeatured === product.id}
                    className={`w-full py-2 px-3 rounded-lg font-medium transition-colors flex items-center justify-center gap-2 ${
                      product.featured
                        ? 'bg-purple-100 hover:bg-purple-200 text-purple-700 disabled:bg-gray-100 disabled:text-gray-400'
                        : 'bg-gray-100 hover:bg-gray-200 text-gray-700 disabled:bg-gray-50 disabled:text-gray-400'
                    }`}
                  >
                    <Star size={16} fill={product.featured ? 'currentColor' : 'none'} />
                    {togglingFeatured === product.id
                      ? 'Updating...'
                      : product.featured
                      ? 'Remove from Featured'
                      : 'Add to Featured'}
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Bulk Actions Toolbar */}
        {selectedProducts.size > 0 && (
          <div className="fixed bottom-4 right-4 bg-white rounded-lg shadow-lg p-4 border border-gray-200 z-40 flex items-center gap-4">
            <span className="text-sm font-semibold text-gray-700">{selectedProducts.size} selected</span>
            <button
              onClick={() => setSelectedProducts(new Set())}
              className="text-sm text-gray-600 hover:text-gray-900 underline"
            >
              Clear
            </button>
            <button
              onClick={handleBulkToggleFeatured}
              className="px-4 py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-lg font-medium text-sm transition-colors flex items-center gap-2"
            >
              <Star size={16} />
              Toggle Featured
            </button>
          </div>
        )}
      </div>

      {/* Modals */}
      <SubscriptionRequiredModal
        isOpen={subscriptionModal.isOpen}
        onClose={() => setSubscriptionModal({ isOpen: false })}
        errorCode={subscriptionModal.errorCode}
        current={subscriptionModal.current}
        max={subscriptionModal.max}
        currentTier={subscriptionModal.currentTier}
        itemType="PRODUCT"
      />

      <FeaturedItemsConfirmationModal
        isOpen={featuredConfirmation.isOpen}
        onClose={() => setFeaturedConfirmation({ isOpen: false, productId: null, productTitle: null, subscriptionTier: null, maxFeatured: 0, currentFeatured: 0, remainingSlots: 0 })}
        onConfirm={handleConfirmFeatured}
        itemTitle={featuredConfirmation.productTitle || ''}
        itemType="PRODUCT"
        subscriptionTier={featuredConfirmation.subscriptionTier}
        maxFeatured={featuredConfirmation.maxFeatured}
        currentFeatured={featuredConfirmation.currentFeatured}
        remainingSlots={featuredConfirmation.remainingSlots}
      />
    </div>
  )
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { useSession } from 'next-auth/react';
import { useRouter } from 'next/navigation';
import Image from 'next/image';
import {
  Package,
  Clock,
  Truck,
  CheckCircle,
  AlertTriangle,
  XCircle,
  Rocket,
  Timer,
  Copy,
} from 'lucide-react';
import { 
  SHIPPING_CARRIERS,
} from '@/lib/boutique/constants';

interface OrderItem {
  id: string;
  quantity: number;
  product: { title: string; thumbnailUrl: string };
  variant: { size: string; color: string } | null;
}

interface Order {
  id: string;
  orderNumber: string;
  status: string;
  fulfillmentMethod: string;
  total: number;
  currency: string;
  createdAt: string;
  sellerShipDeadline: string | null;
  shippedAt: string | null;
  trackingNumber: string | null;
  carrier: string | null;
  isSellerDirect: boolean;
  isOverdue: boolean;
  hoursUntilDeadline: number | null;
  buyer: { name: string; email: string };
  product: { id: string; title: string; slug: string; thumbnailUrl: string };
  items: OrderItem[];
  shippingAddress: {
    name: string;
    street: string;
    city: string;
    state: string;
    phone: string;
  };
}

interface Counts {
  pendingPayment: number;
  paymentFailed: number;
  pendingConfirmation: number;
  awaitingShipment: number;
  shipped: number;
  completed: number;
  total: number;
}

const STATUS_CONFIG: Record<string, { label: string; color: string; bgColor: string; icon: React.ElementType }> = {
  PENDING_PAYMENT: { label: 'Awaiting Payment', color: 'text-gray-700', bgColor: 'bg-gray-50', icon: Clock },
  PAYMENT_FAILED: { label: 'Payment Failed', color: 'text-red-700', bgColor: 'bg-red-50', icon: XCircle },
  PAID: { label: 'New Order', color: 'text-blue-700', bgColor: 'bg-blue-50', icon: Package },
  AWAITING_SELLER_CONFIRMATION: { label: 'Awaiting Confirmation', color: 'text-yellow-700', bgColor: 'bg-yellow-50', icon: Clock },
  PROCESSING: { label: 'Processing', color: 'text-purple-700', bgColor: 'bg-purple-50', icon: Package },
  SHIPPED: { label: 'Shipped', color: 'text-indigo-700', bgColor: 'bg-indigo-50', icon: Truck },
  DELIVERED: { label: 'Delivered', color: 'text-green-700', bgColor: 'bg-green-50', icon: CheckCircle },
  COMPLETED: { label: 'Completed', color: 'text-emerald-700', bgColor: 'bg-emerald-50', icon: CheckCircle },
  CANCELLED: { label: 'Cancelled', color: 'text-red-700', bgColor: 'bg-red-50', icon: XCircle },
};

const TABS = [
  { key: 'all', label: 'All Orders' },
  { key: 'awaiting-payment', label: 'Awaiting Payment' },
  { key: 'pending', label: 'Needs Action' },
  { key: 'processing', label: 'To Ship' },
  { key: 'shipped', label: 'Shipped' },
  { key: 'completed', label: 'Completed' },
];

export default function SellerOrdersPage() {
  const { data: session, status: authStatus } = useSession();
  const router = useRouter();

  const [loading, setLoading] = useState(true);
  const [orders, setOrders] = useState<Order[]>([]);
  const [counts, setCounts] = useState<Counts | null>(null);
  const [activeTab, setActiveTab] = useState('all');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [actionLoading, setActionLoading] = useState(false);
  const [showShipModal, setShowShipModal] = useState(false);
  const [trackingNumber, setTrackingNumber] = useState('');
  const [carrier, setCarrier] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [minPrice, setMinPrice] = useState('');
  const [maxPrice, setMaxPrice] = useState('');
  const searchTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (authStatus === 'unauthenticated') {
      router.push('/auth/signin');
    }
  }, [authStatus, router]);

  useEffect(() => {
    if (session?.user) {
      fetchOrders(true); // Initial load - show loading state
    }
  }, [session, activeTab]);

  // Debounced search effect
  useEffect(() => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      if (session?.user) {
        fetchOrders();
      }
    }, 500); // Wait 500ms after user stops typing

    return () => {
      if (searchTimeoutRef.current) {
        clearTimeout(searchTimeoutRef.current);
      }
    };
  }, [searchQuery, minPrice, maxPrice, session?.user]);

  const _handleSearch = () => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }
    if (session?.user) {
      fetchOrders();
    }
  };

  const fetchOrders = async (isInitialLoad = false) => {
    try {
      // Only show loading state for initial page load, not for search/filter updates
      if (isInitialLoad) {
        setLoading(true);
      }
      let statusParam = '';
      
      switch (activeTab) {
        case 'awaiting-payment':
          statusParam = '&status=PENDING_PAYMENT&status=PAYMENT_FAILED';
          break;
        case 'pending':
          statusParam = '&status=PAID&status=AWAITING_SELLER_CONFIRMATION';
          break;
        case 'processing':
          statusParam = '&status=PROCESSING';
          break;
        case 'shipped':
          statusParam = '&status=SHIPPED';
          break;
        case 'completed':
          statusParam = '&status=COMPLETED';
          break;
      }

      const params = new URLSearchParams();
      
      if (statusParam) {
        const statusParts = statusParam.split('&').filter(p => p.startsWith('status='));
        statusParts.forEach(part => {
          const status = part.replace('status=', '');
          params.append('status', status);
        });
      }

      if (searchQuery) {
        params.append('search', searchQuery);
      }

      if (minPrice) {
        params.append('minPrice', minPrice);
      }

      if (maxPrice) {
        params.append('maxPrice', maxPrice);
      }

      const response = await fetch(`/api/boutique/seller/orders?${params.toString()}`);
      const data = await response.json();

      if (data.success) {
        setOrders(data.orders);
        setCounts(data.counts);
      }
    } catch (error) {
      console.error('Failed to fetch orders:', error);
    } finally {
      // Only hide loading if it was an initial load
      if (isInitialLoad) {
        setLoading(false);
      }
    }
  };

  const handleAction = async (orderId: string, action: string) => {
    setActionLoading(true);
    try {
      const body: Record<string, string> = { orderId, action };
      
      if (action === 'ship') {
        if (!trackingNumber.trim()) {
          alert('Please enter a tracking number');
          return;
        }
        body.trackingNumber = trackingNumber;
        body.carrier = carrier || 'OTHER';
      }

      const response = await fetch('/api/boutique/seller/orders', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });

      const data = await response.json();

      if (data.success) {
        alert(data.message);
        setShowShipModal(false);
        setTrackingNumber('');
        setCarrier('');
        setSelectedOrder(null);
        fetchOrders();
      } else {
        alert(data.message || 'Action failed');
      }
    } catch (error) {
      console.error('Action failed:', error);
      alert('Failed to perform action');
    } finally {
      setActionLoading(false);
    }
  };

  const getTabCount = (key: string): number => {
    if (!counts) return 0;
    switch (key) {
      case 'awaiting-payment': return counts.pendingPayment + counts.paymentFailed;
      case 'pending': return counts.pendingConfirmation;
      case 'processing': return counts.awaitingShipment;
      case 'shipped': return counts.shipped;
      case 'completed': return counts.completed;
      case 'all': return counts.total;
      default: return 0;
    }
  };

  if (authStatus === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-20">
      {/* Header */}
      <div className="bg-white border-b">
        <div className="max-w-6xl mx-auto px-3 sm:px-4 py-4 sm:py-6">
          <h1 className="text-xl sm:text-2xl font-bold text-gray-900">My Orders</h1>
          <p className="text-gray-500 mt-0.5 sm:mt-1 text-xs sm:text-base">Manage your boutique orders</p>
        </div>
      </div>

      {/* Urgent Orders Banner */}
      {orders.some(o => o.isOverdue || (o.hoursUntilDeadline && o.hoursUntilDeadline < 12)) && (
        <div className="bg-red-50 border-b border-red-200">
          <div className="max-w-6xl mx-auto px-3 sm:px-4 py-2 sm:py-3">
            <div className="flex items-center gap-2 sm:gap-3 text-red-800">
              <AlertTriangle className="w-4 h-4 sm:w-5 sm:h-5" />
              <span className="text-xs sm:text-sm font-medium">
                You have orders that need immediate attention!
              </span>
            </div>
          </div>
        </div>
      )}

      {/* Tabs */}
      <div className="bg-white border-b sticky top-0 z-10">
        <div className="max-w-6xl mx-auto px-3 sm:px-4">
          <div className="flex overflow-x-auto gap-1 py-2 -mx-1 px-1">
            {TABS.map(tab => (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={`px-2 sm:px-4 py-1.5 sm:py-2 rounded-lg whitespace-nowrap text-xs sm:text-sm font-medium flex items-center gap-1 sm:gap-2 transition-colors ${
                  activeTab === tab.key
                    ? 'bg-purple-100 text-purple-700'
                    : 'text-gray-600 hover:bg-gray-100'
                }`}
              >
                <span className="hidden xs:inline">{tab.label}</span>
                <span className="xs:hidden">{tab.key === 'all' ? 'All' : tab.key === 'pending' ? 'Action' : tab.key === 'processing' ? 'Ship' : tab.key}</span>
                <span className={`px-1.5 sm:px-2 py-0.5 rounded-full text-[10px] sm:text-xs ${
                  activeTab === tab.key ? 'bg-purple-200' : 'bg-gray-200'
                }`}>
                  {getTabCount(tab.key)}
                </span>
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-3 sm:px-4 py-4 sm:py-6">
        {/* Search and Filters */}
        <div className="bg-white rounded-xl shadow-sm p-3 sm:p-4 mb-4 sm:mb-6">
          <div className="space-y-3 sm:space-y-4">
            {/* Search Input */}
            <div className="relative">
              <input
                type="text"
                placeholder="Search by Order ID, Buyer name, or Product name..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full px-3 sm:px-4 py-2 pl-9 sm:pl-10 border border-gray-200 rounded-lg text-xs sm:text-sm text-black focus:outline-none focus:ring-2 focus:ring-purple-500"
              />
              <svg className="absolute left-2.5 sm:left-3 top-2.5 sm:top-3 w-4 h-4 sm:w-5 sm:h-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </div>

              {/* Price Range Filter */}
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 sm:gap-3">
                <div>
                  <label className="text-[10px] sm:text-xs text-gray-600 font-medium block mb-1">Min Price (Γéª)</label>
                  <input
                    type="number"
                    placeholder="0"
                    value={minPrice}
                    onChange={(e) => setMinPrice(e.target.value)}
                    className="w-full px-2 sm:px-3 py-1.5 border border-gray-200 rounded-lg text-xs sm:text-sm text-black focus:outline-none focus:ring-2 focus:ring-purple-500"
                  />
                </div>
                <div>
                  <label className="text-[10px] sm:text-xs text-gray-600 font-medium block mb-1">Max Price (Γéª)</label>
                  <input
                    type="number"
                    placeholder="Γê₧"
                    value={maxPrice}
                    onChange={(e) => setMaxPrice(e.target.value)}
                    className="w-full px-2 sm:px-3 py-1.5 border border-gray-200 rounded-lg text-xs sm:text-sm text-black focus:outline-none focus:ring-2 focus:ring-purple-500"
                  />
                </div>
                <div className="flex items-end">
                  <button
                    type="button"
                    onClick={() => {
                      setSearchQuery('');
                      setMinPrice('');
                      setMaxPrice('');
                    }}
                    className="w-full px-2 sm:px-3 py-1.5 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-lg text-[10px] sm:text-xs font-medium transition-colors"
                  >
                    Clear
                  </button>
                </div>
              </div>
            </div>
        </div>

        {/* Orders List */}
        {orders.length === 0 ? (
          <div className="bg-white rounded-xl p-8 sm:p-12 text-center">
            <Package className="w-12 h-12 sm:w-16 sm:h-16 text-gray-300 mx-auto mb-3 sm:mb-4" />
            <h3 className="text-base sm:text-lg font-semibold text-gray-900">No Orders</h3>
            <p className="text-sm text-gray-500 mt-1">No orders in this category</p>
          </div>
        ) : (
          <div className="space-y-3 sm:space-y-4">
            {orders.map(order => {
              const status = STATUS_CONFIG[order.status] || STATUS_CONFIG.PAID;
              const StatusIcon = status.icon;
              
              return (
                <div
                  key={order.id}
                  className={`bg-white rounded-xl overflow-hidden shadow-sm ${
                    order.isOverdue ? 'ring-2 ring-red-500' : ''
                  }`}
                >
                  {/* Order Header */}
                  <div className="p-3 sm:p-4 border-b flex flex-col sm:flex-row sm:items-center justify-between gap-2 sm:gap-0">
                    <div className="flex items-center gap-2 sm:gap-4">
                      <div className={`p-1.5 sm:p-2 rounded-lg ${status.bgColor}`}>
                        <StatusIcon className={`w-4 h-4 sm:w-5 sm:h-5 ${status.color}`} />
                      </div>
                      <div>
                        <div className="flex items-center gap-1 sm:gap-2 flex-wrap">
                          <span className="font-semibold text-gray-900 text-sm sm:text-base">#{order.orderNumber}</span>
                          {order.isSellerDirect && (
                            <span className="inline-flex items-center gap-0.5 sm:gap-1 px-1.5 sm:px-2 py-0.5 rounded-full text-[10px] sm:text-xs font-medium bg-purple-100 text-purple-700">
                              <Rocket className="w-2.5 h-2.5 sm:w-3 sm:h-3" />
                              <span className="hidden xs:inline">Direct Ship</span>
                              <span className="xs:hidden">Direct</span>
                            </span>
                          )}
                        </div>
                        <p className="text-[10px] sm:text-sm text-gray-500">
                          {new Date(order.createdAt).toLocaleDateString()} ΓÇó {order.buyer.name}
                        </p>
                      </div>
                    </div>
                    <div className="text-left sm:text-right flex items-center sm:block gap-2 mt-1 sm:mt-0">
                      <span className={`inline-block px-2 sm:px-3 py-0.5 sm:py-1 rounded-full text-[10px] sm:text-sm font-medium ${status.bgColor} ${status.color}`}>
                        {status.label}
                      </span>
                      <p className="text-sm sm:text-lg font-bold text-purple-600 sm:mt-1">
                        Γéª{order.total.toLocaleString()}
                      </p>
                    </div>
                  </div>

                  {/* Deadline Warning */}
                  {order.isSellerDirect && order.status === 'PROCESSING' && (
                    <div className={`px-3 sm:px-4 py-1.5 sm:py-2 flex items-center gap-1.5 sm:gap-2 text-[10px] sm:text-sm ${
                      order.isOverdue 
                        ? 'bg-red-50 text-red-800' 
                        : order.hoursUntilDeadline && order.hoursUntilDeadline < 12 
                          ? 'bg-yellow-50 text-yellow-800'
                          : 'bg-blue-50 text-blue-800'
                    }`}>
                      <Timer className="w-3 h-3 sm:w-4 sm:h-4" />
                      {order.isOverdue ? (
                        <span className="font-medium">ΓÜá∩╕Å OVERDUE! Ship immediately</span>
                      ) : (
                        <span>
                          <span className="hidden xs:inline">Ship deadline: </span>{order.hoursUntilDeadline?.toFixed(0)}h left
                        </span>
                      )}
                    </div>
                  )}

                  {/* Order Items */}
                  <div className="p-3 sm:p-4">
                    <div className="flex items-start gap-2 sm:gap-4">
                      {order.product.thumbnailUrl && (
                        <Image
                          src={order.product.thumbnailUrl}
                          alt={order.product.title}
                          width={80}
                          height={80}
                          className="rounded-lg object-cover w-16 h-16 sm:w-20 sm:h-20"
                        />
                      )}
                      <div className="flex-1 min-w-0">
                        <h4 className="font-medium text-gray-900 text-sm sm:text-base truncate">{order.product.title}</h4>
                        {order.items.map(item => (
                          <p key={item.id} className="text-[10px] sm:text-sm text-gray-500">
                            {item.variant?.size && `Size: ${item.variant.size}`}
                            {item.variant?.size && item.variant?.color && ' ΓÇó '}
                            {item.variant?.color && `Color: ${item.variant.color}`}
                            {' ΓÇó Qty: '}{item.quantity}
                          </p>
                        ))}
                      </div>
                    </div>
                  </div>

                  {/* Shipping Address */}
                  <div className="px-3 sm:px-4 py-2 sm:py-3 bg-gray-50 border-t">
                    <p className="text-[9px] sm:text-sm font-medium text-gray-700">Ship to:</p>
                    <p className="text-[9px] sm:text-sm text-gray-600">
                      {order.shippingAddress?.name} ΓÇó {order.shippingAddress?.street}, {order.shippingAddress?.city}, {order.shippingAddress?.state}
                    </p>
                  </div>

                  {/* Tracking Info (if shipped) */}
                  {order.trackingNumber && (
                    <div className="px-3 sm:px-4 py-2 sm:py-3 bg-green-50 border-t flex items-center justify-between">
                      <div>
                        <p className="text-[10px] sm:text-sm font-medium text-green-800">Tracking:</p>
                        <p className="text-[10px] sm:text-sm text-green-700 font-mono">{order.trackingNumber}</p>
                      </div>
                      <button
                        onClick={() => navigator.clipboard.writeText(order.trackingNumber!)}
                        className="p-1.5 sm:p-2 hover:bg-green-100 rounded-lg"
                        aria-label="Copy tracking number"
                      >
                        <Copy className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-green-700" />
                      </button>
                    </div>
                  )}

                  {/* Actions */}
                  {order.isSellerDirect && ['PAID', 'AWAITING_SELLER_CONFIRMATION', 'PROCESSING'].includes(order.status) && (
                    <div className="p-3 sm:p-4 border-t bg-gray-50 flex items-center justify-between gap-2">
                      <button
                        onClick={() => handleAction(order.id, 'cancel')}
                        disabled={actionLoading}
                        className="px-2 sm:px-4 py-1.5 sm:py-2 text-red-600 hover:bg-red-50 rounded-lg text-[10px] sm:text-sm"
                      >
                        Cancel
                      </button>
                      <div className="flex gap-1.5 sm:gap-2">
                        {(order.status === 'PAID' || order.status === 'AWAITING_SELLER_CONFIRMATION') && (
                          <button
                            onClick={() => handleAction(order.id, 'confirm')}
                            disabled={actionLoading}
                            className="px-2 sm:px-4 py-1.5 sm:py-2 bg-blue-600 text-white rounded-lg text-[10px] sm:text-sm hover:bg-blue-700"
                          >
                            Confirm
                          </button>
                        )}
                        {order.status === 'PROCESSING' && (
                          <button
                            onClick={() => {
                              setSelectedOrder(order);
                              setShowShipModal(true);
                            }}
                            disabled={actionLoading}
                            className="px-2 sm:px-4 py-1.5 sm:py-2 bg-purple-600 text-white rounded-lg text-[10px] sm:text-sm hover:bg-purple-700"
                          >
                            <span className="hidden xs:inline">Mark as </span>Shipped
                          </button>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Ship Modal */}
      {showShipModal && selectedOrder && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-3 sm:p-4">
          <div className="bg-white rounded-xl max-w-md w-full p-4 sm:p-6">
            <h3 className="text-base sm:text-lg font-bold text-gray-900 mb-3 sm:mb-4">
              Mark Order as Shipped
            </h3>
            <p className="text-xs sm:text-sm text-gray-600 mb-3 sm:mb-4">
              Order #{selectedOrder.orderNumber} for {selectedOrder.buyer.name}
            </p>

            <div className="space-y-3 sm:space-y-4">
              <div>
                <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">
                  Tracking Number *
                </label>
                <input
                  type="text"
                  value={trackingNumber}
                  onChange={(e) => setTrackingNumber(e.target.value)}
                  placeholder="Enter tracking number"
                  className="w-full px-3 sm:px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 text-sm"
                />
              </div>

              <div>
                <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">
                  Shipping Carrier
                </label>
                <select
                  value={carrier}
                  onChange={(e) => setCarrier(e.target.value)}
                  className="w-full px-3 sm:px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 text-sm"
                  aria-label="Select shipping carrier"
                >
                  <option value="">Select carrier</option>
                  {SHIPPING_CARRIERS.map(c => (
                    <option key={c.code} value={c.code}>{c.name}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="flex gap-2 sm:gap-3 mt-4 sm:mt-6">
              <button
                onClick={() => {
                  setShowShipModal(false);
                  setTrackingNumber('');
                  setCarrier('');
                }}
                className="flex-1 px-3 sm:px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 text-sm"
              >
                Cancel
              </button>
              <button
                onClick={() => handleAction(selectedOrder.id, 'ship')}
                disabled={actionLoading || !trackingNumber.trim()}
                className="flex-1 px-3 sm:px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 disabled:opacity-50 text-sm"
              >
                {actionLoading ? 'Processing...' : 'Confirm'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useSession } from 'next-auth/react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import Image from 'next/image';
import { Package, Calendar, TrendingDown, ArrowLeft, ChevronDown, _X } from 'lucide-react';

interface Variant {
  id: string;
  size: string | null;
  color: string | null;
  quantity: number;
  soldOutAt: string | null;
}

interface MediaFile {
  id: string;
  url: string;
  type: 'IMAGE' | 'VIDEO';
  isPrimary: boolean;
}

interface OutOfStockProduct {
  id: string;
  title: string;
  slug: string;
  basePrice: number;
  salePrice: number | null;
  originalQuantity: number;
  currentStock: number;
  outOfStockAt: string;
  createdAt: string;
  imageUrl: string | null;
  media: MediaFile[];
  totalOrders: number;
  variants: Variant[];
}

export default function SellerOutOfStockPage() {
  const { data: session, status } = useSession();
  const router = useRouter();
  const [products, setProducts] = useState<OutOfStockProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [selectedProduct, setSelectedProduct] = useState<OutOfStockProduct | null>(null);
  const [expandedProducts, setExpandedProducts] = useState<Set<string>>(new Set());

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/auth/signin');
    }
  }, [status, router]);

  useEffect(() => {
    if (status === 'authenticated') {
      fetchProducts();
    }
  }, [page, status]);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await fetch(`/api/boutique/seller/out-of-stock?page=${page}&limit=20`);
      
      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.message || 'Failed to fetch out-of-stock products');
      }

      const data = await response.json();
      setProducts(data.products);
      setTotalPages(data.pagination.totalPages);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to fetch products';
      setError(message);
      setProducts([]);
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString: string | null) => {
    if (!dateString) return 'Not recorded';
    const date = new Date(dateString);
    // Check if it's epoch time (Jan 1, 1970)
    if (date.getFullYear() === 1970) return 'Not recorded';
    return date.toLocaleDateString('en-US', { 
      year: 'numeric', 
      month: 'short', 
      day: 'numeric' 
    });
  };

  const getDaysSinceLaunch = (createdAt: string) => {
    const launch = new Date(createdAt);
    const today = new Date();
    const diff = today.getTime() - launch.getTime();
    return Math.floor(diff / (1000 * 60 * 60 * 24));
  };

  const toggleExpanded = (productId: string) => {
    const newExpanded = new Set(expandedProducts);
    if (newExpanded.has(productId)) {
      newExpanded.delete(productId);
    } else {
      newExpanded.add(productId);
    }
    setExpandedProducts(newExpanded);
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="w-12 h-12 border-4 border-purple-200 border-t-purple-600 rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-gray-600">Loading sold-out products...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-4xl mx-auto px-4 py-8">
        {/* Header */}
        <div className="mb-8">
          <Link href="/seller/boutique" className="flex items-center gap-2 text-purple-600 hover:text-purple-700 mb-4">
            <ArrowLeft className="w-4 h-4" />
            Back to Products
          </Link>
          <h1 className="text-3xl font-bold text-gray-900 mb-2">Sold Out Products</h1>
          <p className="text-gray-600">Track your products that have sold out completely</p>
        </div>

        {error && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6 text-red-700">
            {error}
          </div>
        )}

        {products.length === 0 ? (
          <div className="bg-white rounded-lg shadow p-12 text-center">
            <TrendingDown className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <h3 className="text-xl font-semibold text-gray-900 mb-2">No Sold Out Products</h3>
            <p className="text-gray-600">Great! None of your products have sold out yet.</p>
          </div>
        ) : (
          <div className="space-y-4">
            {products.map((product) => (
              <div key={product.id} className="bg-white rounded-lg shadow hover:shadow-lg transition-shadow">
                <div className="p-6 flex flex-col sm:flex-row gap-4">
                  {/* Image */}
                  <div className="w-full sm:w-24 h-24 bg-gray-100 rounded-lg flex-shrink-0 overflow-hidden">
                    {product.imageUrl ? (
                      <Image
                        src={product.imageUrl}
                        alt={product.title}
                        width={96}
                        height={96}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center">
                        <Package className="w-8 h-8 text-gray-300" />
                      </div>
                    )}
                  </div>

                  {/* Content */}
                  <div className="flex-1">
                    <div className="flex items-start justify-between mb-3">
                      <div>
                        <h3 className="font-semibold text-gray-900 text-lg">{product.title}</h3>
                        <p className="text-sm text-gray-500">Γéª{product.basePrice.toLocaleString()}</p>
                      </div>
                      <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full bg-red-100 text-red-700 text-sm font-medium">
                        <TrendingDown className="w-4 h-4" />
                        Sold Out
                      </span>
                    </div>

                    {/* Summary Stats */}
                    <div className="grid grid-cols-3 gap-3 mb-4">
                      <div className="bg-gray-50 p-2 rounded-lg">
                        <p className="text-xs text-gray-600">Original Stock</p>
                        <p className="text-lg font-bold text-gray-900">{product.originalQuantity || 'N/A'}</p>
                      </div>
                      <div className="bg-gray-50 p-2 rounded-lg">
                        <p className="text-xs text-gray-600">Total Orders</p>
                        <p className="text-lg font-bold text-gray-900">{product.totalOrders}</p>
                      </div>
                      <div className="bg-gray-50 p-2 rounded-lg">
                        <p className="text-xs text-gray-600">Days to Sell</p>
                        <p className="text-lg font-bold text-gray-900">{getDaysSinceLaunch(product.createdAt)}</p>
                      </div>
                    </div>

                    {/* Expand Details Button */}
                    <button
                      onClick={() => toggleExpanded(product.id)}
                      className="flex items-center gap-2 text-purple-600 hover:text-purple-700 font-medium text-sm"
                    >
                      {expandedProducts.has(product.id) ? (
                        <>
                          <ChevronDown className="w-4 h-4 rotate-180" />
                          Hide Details
                        </>
                      ) : (
                        <>
                          <ChevronDown className="w-4 h-4" />
                          View Details
                        </>
                      )}
                    </button>

                    {/* Expanded Details */}
                    {expandedProducts.has(product.id) && (
                      <div className="mt-4 pt-4 border-t border-gray-200 space-y-4">
                        {/* Dates Section */}
                        <div className="bg-gradient-to-r from-blue-50 to-indigo-50 p-3 rounded-lg">
                          <p className="text-sm font-semibold text-gray-900 mb-2 flex items-center gap-2">
                            <Calendar className="w-4 h-4" />
                            Timeline
                          </p>
                          <div className="space-y-2 text-sm">
                            <div className="flex justify-between">
                              <span className="text-gray-600">Listed:</span>
                              <span className="font-medium text-gray-900">{formatDate(product.createdAt)}</span>
                            </div>
                            <div className="flex justify-between">
                              <span className="text-gray-600">Sold Out:</span>
                              <span className="font-medium text-gray-900">{formatDate(product.outOfStockAt)}</span>
                            </div>
                          </div>
                        </div>

                        {/* Variants Section */}
                        {product.variants.length > 0 && (
                          <div className="bg-gradient-to-r from-amber-50 to-orange-50 p-3 rounded-lg">
                            <p className="text-sm font-semibold text-gray-900 mb-3">Variants Sold Out ({product.variants.length})</p>
                            <div className="space-y-2">
                              {product.variants.map((variant) => (
                                <div
                                  key={variant.id}
                                  className="bg-white p-2 rounded border border-gray-200 flex justify-between items-start text-sm"
                                >
                                  <div>
                                    <span className="font-medium text-gray-900">
                                      {variant.size && <span>{variant.size}</span>}
                                      {variant.size && variant.color && <span> ΓÇó </span>}
                                      {variant.color && <span>{variant.color}</span>}
                                      {!variant.size && !variant.color && <span>No variant info</span>}
                                    </span>
                                    {variant.quantity !== undefined && (
                                      <p className="text-xs text-gray-500 mt-0.5">Qty: {variant.quantity}</p>
                                    )}
                                  </div>
                                  <span className="text-xs text-gray-500 whitespace-nowrap ml-2">
                                    {formatDate(variant.soldOutAt)}
                                  </span>
                                </div>
                              ))}
                            </div>
                          </div>
                        )}

                        {/* Media Files Section */}
                        {product.media.length > 0 && (
                          <div className="bg-gradient-to-r from-purple-50 to-pink-50 p-3 rounded-lg">
                            <p className="text-sm font-semibold text-gray-900 mb-3">Product Files ({product.media.length})</p>
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                              {product.media.map((file) => (
                                <a
                                  key={file.id}
                                  href={file.url}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  className="bg-white p-2 rounded border border-gray-200 hover:border-purple-400 hover:bg-purple-50 transition text-sm flex items-center gap-2"
                                >
                                  <div className="flex-1 min-w-0">
                                    {file.type === 'VIDEO' ? (
                                      <div className="text-xs">
                                        <p className="font-medium text-gray-900 truncate">≡ƒÄÑ Video</p>
                                        <p className="text-gray-500 truncate">{file.url.split('/').pop()}</p>
                                      </div>
                                    ) : (
                                      <div className="text-xs">
                                        <p className="font-medium text-gray-900 truncate">≡ƒû╝∩╕Å Image</p>
                                        <p className="text-gray-500 truncate">{file.url.split('/').pop()}</p>
                                      </div>
                                    )}
                                  </div>
                                  {file.isPrimary && (
                                    <span className="text-xs bg-purple-100 text-purple-700 px-2 py-0.5 rounded-full whitespace-nowrap">Primary</span>
                                  )}
                                </a>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="mt-8 flex justify-center items-center gap-4">
            <button
              onClick={() => setPage(p => Math.max(1, p - 1))}
              disabled={page === 1}
              className="px-4 py-2 rounded-lg border border-gray-300 text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Previous
            </button>
            <span className="text-gray-600">
              Page {page} of {totalPages}
            </span>
            <button
              onClick={() => setPage(p => Math.min(totalPages, p + 1))}
              disabled={page === totalPages}
              className="px-4 py-2 rounded-lg bg-purple-600 text-white hover:bg-purple-700 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Next
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { useSession } from 'next-auth/react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { ArrowLeft, AlertTriangle, Calendar, Truck, AlertCircle, Play, X } from 'lucide-react';
import Image from 'next/image';
import toast from 'react-hot-toast';
import { useCurrency } from '@/components/CurrencyProvider';

interface ProductMedia {
  id: string;
  url: string;
  type: string; // 'IMAGE' or 'VIDEO'
  order: number;
  sortOrder: number;
}

interface RejectedProduct {
  id: string;
  title: string;
  basePrice: number;
  category?: { name: string };
  brand?: string;
  material?: string;
  condition: string;
  description: string;
  createdAt: string;
  rejectionReason?: string;
  media: ProductMedia[];
  shipment?: {
    id: string;
    status: string;
    courier?: string;
    trackingNumber?: string;
    disputeNotes: string | null;
    itemsMissing?: number;
    itemsDamaged?: number;
  };
}

export default function SellerRejectedProductsPage() {
  const { status: authStatus } = useSession();
  const router = useRouter();
  const { formatPrice } = useCurrency();
  const [products, setProducts] = useState<RejectedProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [selectedMediaUrl, setSelectedMediaUrl] = useState<string | null>(null);
  const [selectedMediaType, setSelectedMediaType] = useState<'image' | 'video' | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [minPrice, setMinPrice] = useState('');
  const [maxPrice, setMaxPrice] = useState('');
  const searchTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (authStatus === 'unauthenticated') {
      router.push('/auth/signin');
      return
    }
  }, [authStatus, router]);

  useEffect(() => {
    fetchRejectedProducts(true); // Initial load - show loading state
  }, []);

  // Debounced search effect
  useEffect(() => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      fetchRejectedProducts(false);
    }, 500); // Wait 500ms after user stops typing

    return () => {
      if (searchTimeoutRef.current) {
        clearTimeout(searchTimeoutRef.current);
      }
    };
  }, [searchQuery, minPrice, maxPrice]);

  const fetchRejectedProducts = async (isInitialLoad = false) => {
    try {
      // Only show loading state for initial page load, not for search/filter updates
      if (isInitialLoad) {
        setLoading(true);
      }

      const params = new URLSearchParams();
      params.append('status', 'REJECTED');

      if (searchQuery) {
        params.append('search', searchQuery);
      }

      if (minPrice) {
        params.append('minPrice', minPrice);
      }

      if (maxPrice) {
        params.append('maxPrice', maxPrice);
      }

      const res = await fetch(`/api/boutique/seller/products?${params.toString()}`);
      const data = await res.json();

      if (data.success) {
        // Fetch additional details for each product
        const productsWithDetails = await Promise.all(
          data.products.map(async (product: RejectedProduct) => {
            try {
              const detailRes = await fetch(`/api/boutique/seller/products/${product.id}/rejection-details`);
              const detailData = await detailRes.json();
              return {
                ...product,
                shipment: detailData.shipment,
                category: product.category,
                brand: product.brand,
                material: product.material,
                condition: product.condition,
                description: product.description,
                media: product.media || [],
              };
            } catch (error) {
              console.error('Failed to fetch rejection details:', error);
              return {
                ...product,
                media: product.media || [],
              };
            }
          })
        );

        setProducts(productsWithDetails);
      } else {
        toast.error('Failed to load rejected products');
      }
    } catch (error) {
      console.error('Failed to fetch rejected products:', error);
      toast.error('Failed to load rejected products');
    } finally {
      setLoading(false);
    }
  };

  const parseReturnDate = (disputeNotes: string | null | undefined): string | null => {
    if (!disputeNotes) return null;
    const match = disputeNotes.match(/Return scheduled for (\d{4}-\d{2}-\d{2})/);
    return match ? match[1] : null;
  };

  const parseReason = (disputeNotes: string | null | undefined): string | null => {
    if (!disputeNotes) return null;
    const match = disputeNotes.match(/Reason: (.+)$/m);
    return match ? match[1] : null;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Loading rejected products...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 p-3 sm:p-4">
      <div className="max-w-5xl mx-auto">
        {/* Header */}
        <div className="flex items-center gap-4 mb-4">
          <Link
            href="/seller/boutique"
            className="p-2 hover:bg-gray-200 rounded-lg transition"
          >
            <ArrowLeft className="w-5 h-5 text-gray-600" />
          </Link>
          <div>
            <h1 className="text-lg sm:text-2xl font-bold text-gray-900">Rejected Products</h1>
            <p className="text-gray-600 text-xs sm:text-sm mt-0.5">Review rejection reasons and scheduled returns</p>
          </div>
        </div>

        {/* Search and Filters */}
        <div className="bg-white rounded-xl shadow-sm p-3 sm:p-4 mb-3 sm:mb-4">
          <div className="space-y-2 sm:space-y-3">
            {/* Search Input */}
            <div className="relative">
              <input
                type="text"
                placeholder="Search by product name or ID..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full px-3 sm:px-4 py-1.5 sm:py-2 pl-9 sm:pl-10 border border-gray-200 rounded-lg text-xs sm:text-sm text-black focus:outline-none focus:ring-2 focus:ring-purple-500"
              />
              <svg className="absolute left-2.5 sm:left-3 top-2 sm:top-2.5 w-4 h-4 sm:w-5 sm:h-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>

            {/* Price Range Filter */}
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 sm:gap-3">
              <div>
                <label className="text-[10px] sm:text-xs text-gray-600 font-medium block mb-1">Min Price ($)</label>
                <input
                  type="number"
                  placeholder="0"
                  value={minPrice}
                  onChange={(e) => setMinPrice(e.target.value)}
                  className="w-full px-2 sm:px-3 py-1.5 border border-gray-200 rounded-lg text-xs sm:text-sm text-black focus:outline-none focus:ring-2 focus:ring-purple-500"
                />
              </div>
              <div>
                <label className="text-[10px] sm:text-xs text-gray-600 font-medium block mb-1">Max Price ($)</label>
                <input
                  type="number"
                  placeholder="Γê₧"
                  value={maxPrice}
                  onChange={(e) => setMaxPrice(e.target.value)}
                  className="w-full px-2 sm:px-3 py-1.5 border border-gray-200 rounded-lg text-xs sm:text-sm text-black focus:outline-none focus:ring-2 focus:ring-purple-500"
                />
              </div>
              <div className="flex items-end">
                <button
                  type="button"
                  onClick={() => {
                    setSearchQuery('');
                    setMinPrice('');
                    setMaxPrice('');
                  }}
                  className="w-full px-2 sm:px-3 py-1.5 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-lg text-[10px] sm:text-xs font-medium transition-colors"
                >
                  Clear
                </button>
              </div>
            </div>
          </div>
        </div>

        {products.length === 0 ? (
          <div className="bg-white rounded-xl p-6 sm:p-8 text-center">
            <AlertCircle className="w-10 h-10 sm:w-12 sm:h-12 text-gray-400 mx-auto mb-3" />
            <p className="text-xs sm:text-sm text-gray-600 mb-3">No rejected products</p>
            <Link
              href="/seller/boutique"
              className="inline-block px-3 sm:px-4 py-1.5 sm:py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 text-xs sm:text-sm"
            >
              View All Products
            </Link>
          </div>
        ) : (
          <div className="space-y-4">
            {products.map((product) => {
              const returnDate = parseReturnDate(product.shipment?.disputeNotes);
              const reason = parseReason(product.shipment?.disputeNotes);
              const isExpanded = expandedId === product.id;

              return (
                <div key={product.id} className="bg-white rounded-xl shadow hover:shadow-md transition">
                  {/* Product Header */}
                  <button
                    onClick={() => setExpandedId(isExpanded ? null : product.id)}
                    className="w-full p-2 sm:p-3 text-left hover:bg-gray-50 transition"
                  >
                    <div className="flex items-start gap-3">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <AlertTriangle className="w-4 h-4 text-red-600" />
                          <h3 className="font-semibold text-xs sm:text-sm text-gray-900 line-clamp-2">{product.title}</h3>
                        </div>
                        <p className="text-[10px] sm:text-xs text-gray-600">
                          Rejected on {new Date(product.createdAt).toLocaleDateString()}
                        </p>
                      </div>
                      <div className="text-right">
                        <p className="font-semibold text-xs sm:text-sm text-gray-900">{formatPrice(product.basePrice)}</p>
                        <span className="inline-block mt-1 px-2 py-0.5 bg-red-100 text-red-700 text-[10px] font-medium rounded-full">
                          REJECTED
                        </span>
                      </div>
                    </div>
                  </button>

                  {/* Expanded Details */}
                  {isExpanded && (
                    <div className="border-t px-3 sm:px-4 py-3 sm:py-4 bg-gray-50 space-y-3">
                      {/* Email Notification */}
                      <div className="bg-blue-50 border border-blue-200 rounded-lg p-3">
                        <h4 className="font-semibold text-xs sm:text-sm text-blue-900 mb-1">≡ƒôº Email Notification</h4>
                        <p className="text-blue-800 text-[10px] sm:text-xs">
                          An email has been sent to your registered email address with details about this rejection, the scheduled return pickup date, and instructions on what to do next.
                        </p>
                      </div>

                      {/* Product Details Section */}
                      <div className="bg-white border border-gray-200 rounded-lg p-3">
                        <h4 className="font-semibold text-xs sm:text-sm text-gray-900 mb-2">≡ƒôª Product Information</h4>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 sm:gap-3 text-[10px] sm:text-xs">
                          <div>
                            <span className="text-gray-600">Product ID</span>
                            <p className="font-mono text-gray-900 bg-gray-50 p-1.5 rounded mt-0.5 text-[9px] sm:text-[10px]">{product.id}</p>
                          </div>
                          <div>
                            <span className="text-gray-600">Product Name</span>
                            <p className="font-semibold text-gray-900 mt-0.5">{product.title}</p>
                          </div>
                          <div>
                            <span className="text-gray-600">Base Price</span>
                            <p className="text-gray-900 mt-0.5">{formatPrice(product.basePrice)}</p>
                          </div>
                          <div>
                            <span className="text-gray-600">Category</span>
                            <p className="text-gray-900 mt-0.5">{product.category?.name || 'Not specified'}</p>
                          </div>
                          {product.brand && (
                            <div>
                              <span className="text-gray-600">Brand</span>
                              <p className="text-gray-900 mt-0.5">{product.brand}</p>
                            </div>
                          )}
                          {product.material && (
                            <div>
                              <span className="text-gray-600">Material</span>
                              <p className="text-gray-900 mt-0.5">{product.material}</p>
                            </div>
                          )}
                          <div>
                            <span className="text-gray-600">Condition</span>
                            <p className="text-gray-900 mt-0.5">{product.condition || 'New'}</p>
                          </div>
                          <div>
                            <span className="text-gray-600">Submitted Date</span>
                            <p className="text-gray-900 mt-0.5">{new Date(product.createdAt).toLocaleDateString()}</p>
                          </div>
                        </div>
                        
                        {product.description && (
                          <div className="mt-2 pt-2 border-t">
                            <span className="text-gray-600 text-[10px] sm:text-xs">Description</span>
                            <p className="text-gray-700 text-[10px] sm:text-xs mt-1 whitespace-pre-wrap">{product.description}</p>
                          </div>
                        )}
                      </div>

                      {/* Product Media Gallery */}
                      {product.media && product.media.length > 0 && (
                        <div className="bg-white border border-gray-200 rounded-lg p-3">
                          <h4 className="font-semibold text-xs sm:text-sm text-gray-900 mb-2">≡ƒû╝∩╕Å Product Files & Media</h4>
                          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2">
                            {product.media.map((media) => (
                              <button
                                key={media.id}
                                onClick={() => {
                                  setSelectedMediaUrl(media.url);
                                  setSelectedMediaType(media.type.toLowerCase() as 'image' | 'video');
                                }}
                                className="relative group cursor-pointer rounded-lg overflow-hidden bg-gray-100 hover:shadow-lg transition"
                              >
                                {media.type === 'IMAGE' ? (
                                  <div className="relative w-full aspect-square">
                                    <Image
                                      src={media.url}
                                      alt="Product media"
                                      fill
                                      className="object-cover group-hover:scale-110 transition duration-300"
                                    />
                                  </div>
                                ) : (
                                  <div className="relative w-full aspect-video bg-gray-800 flex items-center justify-center">
                                    <Play className="w-8 h-8 text-white fill-white" />
                                  </div>
                                )}
                                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition"></div>
                              </button>
                            ))}
                          </div>
                        </div>
                      )}

                      {/* Fullscreen Media Viewer */}
                      {selectedMediaUrl && (
                        <div className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center p-4" onClick={() => {
                          setSelectedMediaUrl(null);
                          setSelectedMediaType(null);
                        }}>
                          <div className="relative w-full max-w-4xl" onClick={(e) => e.stopPropagation()}>
                            <button
                              onClick={() => {
                                setSelectedMediaUrl(null);
                                setSelectedMediaType(null);
                              }}
                              className="absolute -top-10 right-0 text-white hover:text-gray-300 p-2"
                              aria-label="Close fullscreen media viewer"
                            >
                              <X className="w-6 h-6" />
                            </button>
                            {selectedMediaType === 'image' ? (
                              <div className="relative w-full aspect-auto">
                                <Image
                                  src={selectedMediaUrl}
                                  alt="Full size preview"
                                  width={1200}
                                  height={800}
                                  className="w-full h-auto rounded-lg"
                                />
                              </div>
                            ) : (
                              <video
                                src={selectedMediaUrl}
                                controls
                                autoPlay
                                className="w-full h-auto rounded-lg bg-black"
                              />
                            )}
                          </div>
                        </div>
                      )}

                      {/* Rejection Reason */}
                      {reason && (
                        <div className="bg-red-50 border border-red-200 rounded-lg p-3">
                          <h4 className="font-semibold text-xs sm:text-sm text-red-900 mb-1">Γ¥î Rejection Reason</h4>
                          <p className="text-red-800 text-[10px] sm:text-xs">{reason}</p>
                        </div>
                      )}

                      {/* Discrepancy Info */}
                      {(product.shipment?.itemsMissing !== undefined || product.shipment?.itemsDamaged !== undefined) && (
                        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-3">
                          <h4 className="font-semibold text-xs sm:text-sm text-yellow-900 mb-2">ΓÜá∩╕Å Discrepancy Details</h4>
                          <div className="space-y-2">
                            {product.shipment?.itemsMissing !== undefined && (
                              <div className="flex justify-between items-center text-[10px] sm:text-xs">
                                <span className="text-yellow-800">Missing Items:</span>
                                <span className="font-semibold text-yellow-900 px-2 py-0.5 bg-yellow-100 rounded text-[10px] sm:text-xs">{product.shipment.itemsMissing}</span>
                              </div>
                            )}
                            {product.shipment?.itemsDamaged !== undefined && (
                              <div className="flex justify-between items-center text-[10px] sm:text-xs">
                                <span className="text-yellow-800">Damaged Items:</span>
                                <span className="font-semibold text-yellow-900 px-2 py-0.5 bg-yellow-100 rounded text-[10px] sm:text-xs">{product.shipment.itemsDamaged}</span>
                              </div>
                            )}
                            <p className="text-yellow-800 text-[10px] sm:text-xs pt-1.5 border-t border-yellow-200">
                              These discrepancies were detected during verification. Your product is being returned due to these issues.
                            </p>
                          </div>
                        </div>
                      )}

                      {/* Shipment Info */}
                      {product.shipment && (
                        <div className="bg-purple-50 border border-purple-200 rounded-lg p-3">
                          <h4 className="font-semibold text-xs sm:text-sm text-purple-900 mb-2">≡ƒÜÜ Shipment Information</h4>
                          <div className="space-y-1 text-[10px] sm:text-xs">
                            <div className="flex justify-between">
                              <span className="text-purple-800">Shipment ID:</span>
                              <span className="font-mono text-[9px] sm:text-[10px] bg-white px-1.5 py-0.5 rounded">{product.shipment.id}</span>
                            </div>
                            {product.shipment.courier && (
                              <div className="flex justify-between">
                                <span className="text-purple-800">Courier:</span>
                                <span className="text-purple-900">{product.shipment.courier}</span>
                              </div>
                            )}
                            {product.shipment.trackingNumber && (
                              <div className="flex justify-between">
                                <span className="text-purple-800">Tracking Number:</span>
                                <span className="font-mono text-[9px] sm:text-[10px] bg-white px-1.5 py-0.5 rounded">{product.shipment.trackingNumber}</span>
                              </div>
                            )}
                            <div className="flex justify-between">
                              <span className="text-purple-800">Status:</span>
                              <span className="font-semibold text-purple-900">{product.shipment.status}</span>
                            </div>
                          </div>
                        </div>
                      )}

                      {/* Return Status */}
                      {product.shipment?.status === 'RETURN_SCHEDULED' && returnDate && (
                        <div className="bg-blue-50 border border-blue-200 rounded-lg p-3">
                          <div className="flex items-start gap-2">
                            <Truck className="w-4 h-4 text-blue-600 flex-shrink-0 mt-0.5" />
                            <div>
                              <h4 className="font-semibold text-xs sm:text-sm text-blue-900 mb-1">≡ƒôà Return Scheduled</h4>
                              <div className="flex items-center gap-2 text-blue-800 text-[10px] sm:text-xs mb-1">
                                <Calendar className="w-4 h-4" />
                                <span>Pickup Date: <span className="font-semibold">{new Date(returnDate).toLocaleDateString()}</span></span>
                              </div>
                              <p className="text-blue-800 text-[10px] sm:text-xs">
                                Our courier will collect the item from your warehouse on this date. Please ensure the product is properly packaged and ready for return.
                              </p>
                            </div>
                          </div>
                        </div>
                      )}

                      {/* Return & Next Steps */}
                      <div className="bg-white border border-gray-200 rounded-lg p-3">
                        <h4 className="font-semibold text-xs sm:text-sm text-gray-900 mb-2">≡ƒôï Return & Next Steps</h4>
                        <p className="text-[10px] sm:text-xs text-gray-700 mb-2">
                          Your product failed verification and is being returned to you. You cannot edit these products - they must be shipped back entirely.
                        </p>
                        <ol className="space-y-1 text-[10px] sm:text-xs text-gray-700">
                          {product.shipment?.status === 'RETURN_SCHEDULED' ? (
                            <>
                              <li className="flex gap-2">
                                <span className="font-semibold text-gray-900 flex-shrink-0">1.</span>
                                <span>Prepare your product for return shipment</span>
                              </li>
                              <li className="flex gap-2">
                                <span className="font-semibold text-gray-900 flex-shrink-0">2.</span>
                                <span>Ensure it's packaged securely on the scheduled pickup date</span>
                              </li>
                              <li className="flex gap-2">
                                <span className="font-semibold text-gray-900 flex-shrink-0">3.</span>
                                <span>Our courier will collect it and provide a tracking number</span>
                              </li>
                              <li className="flex gap-2">
                                <span className="font-semibold text-gray-900 flex-shrink-0">4.</span>
                                <span>Once we receive and verify it, your product status will be updated</span>
                              </li>
                            </>
                          ) : (
                            <>
                              <li className="flex gap-2">
                                <span className="font-semibold text-gray-900 flex-shrink-0">1.</span>
                                <span>Contact admin to schedule a return pickup</span>
                              </li>
                              <li className="flex gap-2">
                                <span className="font-semibold text-gray-900 flex-shrink-0">2.</span>
                                <span>Prepare the entire shipment for return to us</span>
                              </li>
                              <li className="flex gap-2">
                                <span className="font-semibold text-gray-900 flex-shrink-0">3.</span>
                                <span>We'll arrange pickup once you confirm readiness</span>
                              </li>
                            </>
                          )}
                        </ol>
                      </div>

                      {/* Support Contact Info */}
                      <div className="bg-orange-50 border border-orange-200 rounded-lg p-3">
                        <h4 className="font-semibold text-xs sm:text-sm text-orange-900 mb-1">≡ƒåÿ Contacting Support</h4>
                        <p className="text-orange-800 text-[10px] sm:text-xs mb-2">
                          If you need to contact our support team about this rejection or return, please have the following information ready:
                        </p>
                        <ul className="space-y-1 text-[10px] sm:text-xs text-orange-800">
                          <li className="flex items-center gap-2">
                            <span className="font-semibold">Product ID:</span>
                            <span className="font-mono text-[9px] sm:text-[10px] bg-white px-1.5 py-0.5 rounded">{product.id}</span>
                          </li>
                          {product.shipment?.id && (
                            <li className="flex items-center gap-2">
                              <span className="font-semibold">Shipment ID:</span>
                              <span className="font-mono text-[9px] sm:text-[10px] bg-white px-1.5 py-0.5 rounded">{product.shipment.id}</span>
                            </li>
                          )}
                          <li className="flex items-center gap-2">
                            <span className="font-semibold">Rejection Date:</span>
                            <span className="bg-white px-1.5 py-0.5 rounded">{new Date(product.createdAt).toLocaleDateString()}</span>
                          </li>
                        </ul>
                      </div>

                      {/* Actions */}
                      <div className="flex flex-col sm:flex-row gap-2 sm:gap-3">
                        <Link
                          href="/seller/boutique/shipments"
                          className="flex-1 px-3 py-1.5 sm:py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition font-medium text-center text-xs sm:text-sm"
                        >
                          View Shipments
                        </Link>
                        <Link
                          href="/contact"
                          className="flex-1 px-3 py-1.5 sm:py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition font-medium text-center text-xs sm:text-sm"
                        >
                          Contact Support
                        </Link>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { useSession } from 'next-auth/react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { ArrowLeft, CheckCircle, ChevronDown } from 'lucide-react';
import Image from 'next/image';
import toast from 'react-hot-toast';

interface ReturnedProduct {
  id: string;
  title: string;
  basePrice: number;
  thumbnailUrl?: string;
  status: string;
  rejectionReason?: string;
  createdAt: string;
  media: Array<{ id: string; url: string; type: string }>;
  category?: { name: string };
  brand?: string;
  material?: string;
  condition: string;
  description: string;
}

export default function SellerReturnedProductsPage() {
  const { status: authStatus } = useSession();
  const router = useRouter();
  const [products, setProducts] = useState<ReturnedProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [minPrice, setMinPrice] = useState('');
  const [maxPrice, setMaxPrice] = useState('');
  const searchTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (authStatus === 'unauthenticated') {
      router.push('/auth/signin');
      return;
    }
  }, [authStatus, router]);

  useEffect(() => {
    fetchReturnedProducts(true); // Initial load - show loading state
  }, []);

  // Debounced search effect
  useEffect(() => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      fetchReturnedProducts(false);
    }, 500); // Wait 500ms after user stops typing

    return () => {
      if (searchTimeoutRef.current) {
        clearTimeout(searchTimeoutRef.current);
      }
    };
  }, [searchQuery, minPrice, maxPrice]);

  const fetchReturnedProducts = async (isInitialLoad = false) => {
    try {
      // Only show loading state for initial page load, not for search/filter updates
      if (isInitialLoad) {
        setLoading(true);
      }

      const params = new URLSearchParams();
      params.append('status', 'RETURNED_TO_SELLER');

      if (searchQuery) {
        params.append('search', searchQuery);
      }

      if (minPrice) {
        params.append('minPrice', minPrice);
      }

      if (maxPrice) {
        params.append('maxPrice', maxPrice);
      }

      const res = await fetch(`/api/boutique/seller/products?${params.toString()}`);
      const data = await res.json();

      if (data.success) {
        setProducts(data.products || []);
      } else {
        toast.error('Failed to load returned products');
      }
    } catch (error) {
      console.error('Failed to fetch returned products:', error);
      toast.error('Failed to load returned products');
    } finally {
      // Only hide loading if it was an initial load
      if (isInitialLoad) {
        setLoading(false);
      }
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Loading returned products...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6">
      <div className="max-w-5xl mx-auto">
        {/* Header */}
        <div className="flex items-center gap-4 mb-6">
          <Link
            href="/seller/boutique"
            className="p-2 hover:bg-gray-200 rounded-lg transition"
          >
            <ArrowLeft className="w-5 h-5 text-gray-600" />
          </Link>
          <div>
            <h1 className="text-2xl sm:text-3xl font-bold text-gray-900">Returned Products</h1>
            <p className="text-gray-600 text-sm mt-1">Products that have been marked as returned by admin</p>
          </div>
        </div>

        {/* Search and Filters */}
        <div className="bg-white rounded-xl shadow-sm p-3 sm:p-4 mb-4 sm:mb-6">
          <div className="space-y-3 sm:space-y-4">
            {/* Search Input */}
            <div className="relative">
              <input
                type="text"
                placeholder="Search by product name or ID..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full px-3 sm:px-4 py-2 pl-9 sm:pl-10 border border-gray-200 rounded-lg text-xs sm:text-sm text-black focus:outline-none focus:ring-2 focus:ring-purple-500"
              />
              <svg className="absolute left-2.5 sm:left-3 top-2.5 sm:top-3 w-4 h-4 sm:w-5 sm:h-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>

            {/* Price Range Filter */}
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 sm:gap-3">
              <div>
                <label className="text-[10px] sm:text-xs text-gray-600 font-medium block mb-1">Min Price (Γéª)</label>
                <input
                  type="number"
                  placeholder="0"
                  value={minPrice}
                  onChange={(e) => setMinPrice(e.target.value)}
                  className="w-full px-2 sm:px-3 py-1.5 border border-gray-200 rounded-lg text-xs sm:text-sm text-black focus:outline-none focus:ring-2 focus:ring-purple-500"
                />
              </div>
              <div>
                <label className="text-[10px] sm:text-xs text-gray-600 font-medium block mb-1">Max Price (Γéª)</label>
                <input
                  type="number"
                  placeholder="Γê₧"
                  value={maxPrice}
                  onChange={(e) => setMaxPrice(e.target.value)}
                  className="w-full px-2 sm:px-3 py-1.5 border border-gray-200 rounded-lg text-xs sm:text-sm text-black focus:outline-none focus:ring-2 focus:ring-purple-500"
                />
              </div>
              <div className="flex items-end">
                <button
                  type="button"
                  onClick={() => {
                    setSearchQuery('');
                    setMinPrice('');
                    setMaxPrice('');
                  }}
                  className="w-full px-2 sm:px-3 py-1.5 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-lg text-[10px] sm:text-xs font-medium transition-colors"
                >
                  Clear
                </button>
              </div>
            </div>
          </div>
        </div>

        {products.length === 0 ? (
          <div className="bg-white rounded-xl p-8 text-center">
            <CheckCircle className="w-12 h-12 text-green-400 mx-auto mb-4" />
            <p className="text-gray-600 mb-4">No returned products yet</p>
            <p className="text-gray-500 text-sm mb-4">
              When admin confirms receipt and marks your products as returned, they'll appear here.
            </p>
            <Link
              href="/seller/boutique"
              className="inline-block px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700"
            >
              Back to Dashboard
            </Link>
          </div>
        ) : (
          <div className="space-y-4">
            {products.map((product) => (
              <div key={product.id} className="bg-white rounded-xl shadow hover:shadow-md transition">
                {/* Product Header - Clickable */}
                <button
                  onClick={() => setExpandedId(expandedId === product.id ? null : product.id)}
                  className="w-full p-4 sm:p-6 text-left hover:bg-gray-50 transition flex items-start gap-4 justify-between"
                >
                  <div className="flex items-start gap-4 flex-1 min-w-0">
                    {/* Product Image */}
                    {product.media && product.media.length > 0 && (
                      <div className="w-16 h-16 rounded-lg overflow-hidden bg-gray-200 flex-shrink-0">
                        <Image
                          src={product.media[0].url}
                          alt={product.title}
                          width={64}
                          height={64}
                          className="w-full h-full object-cover"
                        />
                      </div>
                    )}

                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-2">
                        <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0" />
                        <h3 className="font-semibold text-gray-900 line-clamp-2">{product.title}</h3>
                      </div>
                      <p className="text-sm text-gray-600">
                        Returned on {new Date(product.createdAt).toLocaleDateString()} ΓÇó Γéª{product.basePrice.toLocaleString()}
                      </p>
                      <span className="inline-block mt-2 px-3 py-1 bg-green-100 text-green-700 text-xs font-medium rounded-full">
                        RETURNED
                      </span>
                    </div>
                  </div>
                  <ChevronDown 
                    className={`w-5 h-5 text-gray-400 flex-shrink-0 mt-1 transition-transform ${expandedId === product.id ? 'rotate-180' : ''}`}
                  />
                </button>

                {/* Expanded Details */}
                {expandedId === product.id && (
                  <div className="border-t px-4 sm:px-6 py-4 sm:py-6 bg-gray-50 space-y-4">
                    {/* Product Details */}
                    <div className="bg-white border border-gray-200 rounded-lg p-4">
                      <h4 className="font-semibold text-gray-900 mb-4">≡ƒôª Product Information</h4>
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 text-sm">
                        <div>
                          <span className="text-gray-600">Product ID</span>
                          <p className="font-mono text-gray-900 bg-gray-50 p-2 rounded mt-1">{product.id}</p>
                        </div>
                        <div>
                          <span className="text-gray-600">Base Price</span>
                          <p className="text-gray-900 mt-1">Γéª{product.basePrice.toLocaleString()}</p>
                        </div>
                        {product.brand && (
                          <div>
                            <span className="text-gray-600">Brand</span>
                            <p className="text-gray-900 mt-1">{product.brand}</p>
                          </div>
                        )}
                        {product.material && (
                          <div>
                            <span className="text-gray-600">Material</span>
                            <p className="text-gray-900 mt-1">{product.material}</p>
                          </div>
                        )}
                        <div>
                          <span className="text-gray-600">Condition</span>
                          <p className="text-gray-900 mt-1">{product.condition || 'New'}</p>
                        </div>
                        <div>
                          <span className="text-gray-600">Category</span>
                          <p className="text-gray-900 mt-1">{product.category?.name || 'Not specified'}</p>
                        </div>
                      </div>

                      {product.description && (
                        <div className="mt-4 pt-4 border-t">
                          <span className="text-gray-600 text-sm">Description</span>
                          <p className="text-gray-700 mt-2 whitespace-pre-wrap">{product.description}</p>
                        </div>
                      )}
                    </div>

                    {/* Rejection Reason */}
                    {product.rejectionReason && (
                      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
                        <h4 className="font-semibold text-yellow-900 mb-2">ΓÜá∩╕Å Original Rejection Reason</h4>
                        <p className="text-yellow-800 text-sm">{product.rejectionReason}</p>
                      </div>
                    )}

                    {/* Return Status */}
                    <div className="bg-green-50 border border-green-200 rounded-lg p-4">
                      <div className="flex items-start gap-3">
                        <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0 mt-0.5" />
                        <div>
                          <h4 className="font-semibold text-green-900 mb-2">Γ£ô Product Returned</h4>
                          <p className="text-green-800 text-sm">
                            Your product has been confirmed as returned by our admin team on{' '}
                            <strong>{new Date(product.createdAt).toLocaleDateString()}</strong>.
                          </p>
                          <p className="text-green-800 text-sm mt-2">
                            You can now collect it from the return location specified in your rejection email.
                          </p>
                        </div>
                      </div>
                    </div>

                    {/* What Happens Next */}
                    <div className="bg-white border border-gray-200 rounded-lg p-4">
                      <h4 className="font-semibold text-gray-900 mb-3">≡ƒôï What Happens Next</h4>
                      <ol className="space-y-2 text-sm text-gray-700">
                        <li className="flex gap-2">
                          <span className="font-semibold text-gray-900 flex-shrink-0">1.</span>
                          <span>Collect your product from the return location specified in your rejection email</span>
                        </li>
                        <li className="flex gap-2">
                          <span className="font-semibold text-gray-900 flex-shrink-0">2.</span>
                          <span>Inspect the product to ensure all items are accounted for</span>
                        </li>
                        <li className="flex gap-2">
                          <span className="font-semibold text-gray-900 flex-shrink-0">3.</span>
                          <span>You can resubmit the product if issues have been resolved, or</span>
                        </li>
                        <li className="flex gap-2">
                          <span className="font-semibold text-gray-900 flex-shrink-0">4.</span>
                          <span>Contact support if you need clarification on the rejection</span>
                        </li>
                      </ol>
                    </div>

                    {/* Product Media Gallery */}
                    {product.media && product.media.length > 0 && (
                      <div className="bg-white border border-gray-200 rounded-lg p-4">
                        <h4 className="font-semibold text-gray-900 mb-3">≡ƒû╝∩╕Å Product Media</h4>
                        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
                          {product.media.map((media) => (
                            <div key={media.id} className="rounded-lg overflow-hidden bg-gray-100">
                              {media.type === 'IMAGE' ? (
                                <div className="relative w-full aspect-square">
                                  <Image
                                    src={media.url}
                                    alt="Product media"
                                    fill
                                    className="object-cover"
                                  />
                                </div>
                              ) : (
                                <div className="relative w-full aspect-video bg-gray-800 flex items-center justify-center">
                                  <span className="text-white text-xs">Video</span>
                                </div>
                              )}
                            </div>
                          ))}
                        </div>
                      </div>
                    )}

                    {/* Support Info */}
                    <div className="bg-orange-50 border border-orange-200 rounded-lg p-4">
                      <h4 className="font-semibold text-orange-900 mb-2">≡ƒåÿ Need Help?</h4>
                      <p className="text-orange-800 text-sm mb-3">
                        If you have questions about why your product was rejected or need assistance with resubmission, please contact our support team.
                      </p>
                      <div className="space-y-1 text-sm text-orange-800">
                        <p><strong>Product ID:</strong> <span className="font-mono">{product.id}</span></p>
                        <p><strong>Reference Date:</strong> {new Date(product.createdAt).toLocaleDateString()}</p>
                      </div>
                    </div>

                    {/* Actions */}
                    <div className="flex flex-col sm:flex-row gap-3">
                      <Link
                        href="/contact"
                        className="flex-1 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition font-medium text-center"
                      >
                        Contact Support
                      </Link>
                      <Link
                        href="/seller/boutique"
                        className="flex-1 px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition font-medium text-center"
                      >
                        Back to Boutique
                      </Link>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import toast from 'react-hot-toast'
import { AlertCircle, Clock, CheckCircle, XCircle, RefreshCw } from 'lucide-react'

interface Return {
  id: string
  orderItemId: string
  reason: string
  status: string
  requestedAt: string
  resolvedAt?: string | null
  refundAmount: number
}

export default function SellerReturnsPage() {
  const { data: session } = useSession()
  const [returns, setReturns] = useState<Return[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<string>('all')

  useEffect(() => {
    fetchReturns()
  }, [filter])

  const fetchReturns = async () => {
    try {
      setLoading(true)
      // Fetch returns from API
      const res = await fetch(`/api/boutique/seller/returns?status=${filter}`)
      if (!res.ok) throw new Error('Failed to load returns')
      
      const data = await res.json()
      setReturns(data.returns || [])
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to load returns'
      toast.error(message)
    } finally {
      setLoading(false)
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'PENDING':
        return <Clock className="w-4 h-4 sm:w-5 sm:h-5 text-yellow-600" />
      case 'APPROVED':
        return <CheckCircle className="w-4 h-4 sm:w-5 sm:h-5 text-green-600" />
      case 'REJECTED':
        return <XCircle className="w-4 h-4 sm:w-5 sm:h-5 text-red-600" />
      default:
        return <RefreshCw className="w-4 h-4 sm:w-5 sm:h-5 text-gray-600" />
    }
  }

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'PENDING':
        return 'bg-yellow-100 text-yellow-800'
      case 'APPROVED':
        return 'bg-green-100 text-green-800'
      case 'REJECTED':
        return 'bg-red-100 text-red-800'
      default:
        return 'bg-gray-100 text-gray-800'
    }
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-6xl mx-auto px-3 sm:px-4 md:px-6 py-4 sm:py-6 md:py-8">
        {/* Header */}
        <div className="mb-4 sm:mb-6 md:mb-8">
          <h1 className="text-xl sm:text-2xl md:text-3xl font-bold text-gray-900">
            Product Returns
          </h1>
          <p className="text-xs sm:text-sm md:text-base text-gray-600 mt-1 sm:mt-2">
            Track and manage returns from your boutique products
          </p>
        </div>

        {/* Info Banner */}
        {!session?.user?.id && (
          <div className="mb-4 sm:mb-6 bg-blue-50 border border-blue-200 rounded-lg p-3 sm:p-4 flex gap-2 sm:gap-3">
            <AlertCircle className="w-4 h-4 sm:w-5 sm:h-5 text-blue-600 flex-shrink-0 mt-0.5" />
            <div>
              <h3 className="font-semibold text-sm sm:text-base text-blue-900">
                Loading...
              </h3>
              <p className="text-xs sm:text-sm text-blue-800 mt-1">
                Please wait while we fetch your returns.
              </p>
            </div>
          </div>
        )}

        {/* Filter Buttons */}
        <div className="mb-4 sm:mb-6 flex flex-wrap gap-2">
          {['all', 'PENDING', 'APPROVED', 'REJECTED'].map((status) => (
            <button
              key={status}
              onClick={() => setFilter(status)}
              className={`px-3 sm:px-4 py-1.5 sm:py-2 rounded-lg text-xs sm:text-sm font-medium transition ${
                filter === status
                  ? 'bg-blue-600 text-white'
                  : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
              }`}
            >
              {status === 'all' ? 'All' : status}
            </button>
          ))}
        </div>

        {/* Returns List */}
        {loading ? (
          <div className="bg-white rounded-lg border border-gray-200 p-6 sm:p-8 text-center">
            <RefreshCw className="w-8 h-8 animate-spin mx-auto text-gray-400 mb-3" />
            <p className="text-sm sm:text-base text-gray-600">Loading returns...</p>
          </div>
        ) : returns.length === 0 ? (
          <div className="bg-white rounded-lg border border-gray-200 p-6 sm:p-8 text-center">
            <AlertCircle className="w-8 h-8 sm:w-10 sm:h-10 mx-auto text-gray-400 mb-3" />
            <p className="text-sm sm:text-base font-medium text-gray-900">No returns found</p>
            <p className="text-xs sm:text-sm text-gray-600 mt-1">
              You don't have any returns to display
            </p>
          </div>
        ) : (
          <div className="space-y-3 sm:space-y-4">
            {returns.map((ret) => (
              <div
                key={ret.id}
                className="bg-white rounded-lg border border-gray-200 p-3 sm:p-4 md:p-6 hover:shadow-md transition"
              >
                <div className="flex items-start gap-2 sm:gap-3">
                  {getStatusIcon(ret.status)}
                  <div className="flex-1 min-w-0">
                    <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
                      <div>
                        <p className="text-xs sm:text-sm font-medium text-gray-900 break-words">
                          Order Item: {ret.orderItemId}
                        </p>
                        <p className="text-xs sm:text-sm text-gray-600 mt-0.5">
                          Reason: {ret.reason}
                        </p>
                      </div>
                      <span
                        className={`inline-flex items-center px-2 sm:px-2.5 py-0.5 sm:py-1 rounded-full text-xs font-medium whitespace-nowrap ${getStatusBadge(
                          ret.status,
                        )}`}
                      >
                        {ret.status}
                      </span>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 mt-2 sm:mt-3 text-xs sm:text-sm">
                      <div>
                        <p className="text-gray-600">Requested</p>
                        <p className="text-gray-900 font-medium">
                          {new Date(ret.requestedAt).toLocaleDateString()}
                        </p>
                      </div>
                      <div>
                        <p className="text-gray-600">Refund Amount</p>
                        <p className="text-gray-900 font-medium">
                          Γéª{(ret.refundAmount || 0).toLocaleString()}
                        </p>
                      </div>
                      {ret.resolvedAt && (
                        <div>
                          <p className="text-gray-600">Resolved</p>
                          <p className="text-gray-900 font-medium">
                            {new Date(ret.resolvedAt).toLocaleDateString()}
                          </p>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import Image from 'next/image'
import Link from 'next/link'
import { useCurrency } from '@/components/CurrencyProvider'
import { Package, Truck, Clock, CheckCircle, AlertTriangle, ChevronRight, Plus, Search } from 'lucide-react'

interface Product {
  id: string
  title: string
  thumbnailUrl: string | null
  status: string
  submittedAt: string | null
  basePrice: number
}

interface Shipment {
  id: string
  status: string
  courier: string
  trackingNumber: string
  estimatedArrival: string | null
  createdAt: string
  receivedAt: string | null
}

interface ProductWithShipment extends Product {
  shipment?: Shipment | null
}

const STATUS_CONFIG: Record<string, { label: string; color: string; bgColor: string; icon: React.ElementType }> = {
  DRAFT: { label: 'Draft', color: 'text-gray-700', bgColor: 'bg-gray-100', icon: Clock },
  PENDING_CONTENT_REVIEW: { label: 'Awaiting Review', color: 'text-yellow-700', bgColor: 'bg-yellow-50', icon: Clock },
  CONTENT_APPROVED: { label: 'Ship to Warehouse', color: 'text-blue-700', bgColor: 'bg-blue-50', icon: Truck },
  SHIPPED_TO_ADMIN: { label: 'In Transit', color: 'text-purple-700', bgColor: 'bg-purple-50', icon: Truck },
  RECEIVED_BY_ADMIN: { label: 'At Warehouse', color: 'text-indigo-700', bgColor: 'bg-indigo-50', icon: Package },
  VERIFICATION_PASSED: { label: 'Verified', color: 'text-green-700', bgColor: 'bg-green-50', icon: CheckCircle },
  LIVE: { label: 'Live', color: 'text-green-700', bgColor: 'bg-green-100', icon: CheckCircle },
  REJECTED: { label: 'Rejected', color: 'text-red-700', bgColor: 'bg-red-50', icon: AlertTriangle },
  CANCELLED: { label: 'Cancelled', color: 'text-gray-700', bgColor: 'bg-gray-100', icon: AlertTriangle },
}

export default function SellerShipmentIndexPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const { formatPrice } = useCurrency()
  const [products, setProducts] = useState<ProductWithShipment[]>([])
  const [loading, setLoading] = useState(true)
  const [statusFilter, setStatusFilter] = useState('CONTENT_APPROVED')
  const [searchQuery, setSearchQuery] = useState('')

  useEffect(() => {
    if (status === 'loading') return
    if (!session) {
      router.push('/auth/signin')
      return
    }
    fetchProducts()
  }, [session, status, statusFilter])

  const fetchProducts = async () => {
    setLoading(true)
    try {
      // Fetch products that need shipping or are in transit
      const res = await fetch(`/api/boutique/seller/products?status=${statusFilter}`)
      if (res.ok) {
        const data = await res.json()
        setProducts(data.products || [])
      }
    } catch (error) {
      console.error('Failed to fetch products:', error)
    } finally {
      setLoading(false)
    }
  }

  const formatDate = (date: string) => {
    return new Date(date).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    })
  }

  const filteredProducts = products.filter(p => 
    p.title.toLowerCase().includes(searchQuery.toLowerCase())
  )

  // Count products by status that need shipping action
  const needsShipping = products.filter(p => p.status === 'CONTENT_APPROVED').length
  const inTransit = products.filter(p => p.status === 'SHIPPED_TO_ADMIN').length

  if (status === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600"></div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 py-4 sm:py-8">
      <div className="max-w-6xl mx-auto px-3 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="mb-4 sm:mb-8">
          <Link href="/seller/boutique" className="text-purple-600 hover:text-purple-700 flex items-center gap-1 mb-2 sm:mb-4 text-xs sm:text-sm">
            <ChevronRight className="w-3 h-3 sm:w-4 sm:h-4 rotate-180" />
            Back to Products
          </Link>
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-xl sm:text-3xl font-bold text-gray-900">Ship to Warehouse</h1>
              <p className="text-gray-600 mt-1 text-xs sm:text-base">
                Manage shipments of your approved products
              </p>
            </div>
          </div>
        </div>

        {/* Status Summary Cards */}
        <div className="grid grid-cols-2 gap-2 sm:gap-4 mb-4 sm:mb-6">
          <div 
            onClick={() => setStatusFilter('CONTENT_APPROVED')}
            className={`p-3 sm:p-4 rounded-lg sm:rounded-xl cursor-pointer transition ${
              statusFilter === 'CONTENT_APPROVED' 
                ? 'bg-blue-100 border-2 border-blue-500' 
                : 'bg-white border-2 border-transparent hover:border-blue-200'
            }`}
          >
            <div className="flex items-center gap-2 sm:gap-3">
              <div className="p-1.5 sm:p-2 bg-blue-500 rounded-lg">
                <Truck className="w-4 h-4 sm:w-6 sm:h-6 text-white" />
              </div>
              <div>
                <p className="text-lg sm:text-2xl font-bold text-gray-900">{needsShipping}</p>
                <p className="text-[10px] sm:text-sm text-gray-600">Ready to Ship</p>
              </div>
            </div>
          </div>

          <div 
            onClick={() => setStatusFilter('SHIPPED_TO_ADMIN')}
            className={`p-3 sm:p-4 rounded-lg sm:rounded-xl cursor-pointer transition ${
              statusFilter === 'SHIPPED_TO_ADMIN' 
                ? 'bg-purple-100 border-2 border-purple-500' 
                : 'bg-white border-2 border-transparent hover:border-purple-200'
            }`}
          >
            <div className="flex items-center gap-2 sm:gap-3">
              <div className="p-1.5 sm:p-2 bg-purple-500 rounded-lg">
                <Package className="w-4 h-4 sm:w-6 sm:h-6 text-white" />
              </div>
              <div>
                <p className="text-lg sm:text-2xl font-bold text-gray-900">{inTransit}</p>
                <p className="text-[10px] sm:text-sm text-gray-600">In Transit</p>
              </div>
            </div>
          </div>
        </div>

        {/* Search */}
        <div className="bg-white rounded-lg sm:rounded-xl shadow-sm p-3 sm:p-4 mb-4 sm:mb-6">
          <div className="relative">
            <Search className="absolute left-2.5 sm:left-3 top-1/2 -translate-y-1/2 w-4 h-4 sm:w-5 sm:h-5 text-gray-400" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search products..."
              className="w-full pl-8 sm:pl-10 pr-3 sm:pr-4 py-2 border rounded-lg text-gray-900 focus:ring-2 focus:ring-purple-500 focus:border-transparent text-sm"
            />
          </div>
        </div>

        {/* Products List */}
        {filteredProducts.length === 0 ? (
          <div className="bg-white rounded-xl sm:rounded-2xl shadow-sm p-6 sm:p-12 text-center">
            <Package className="w-10 h-10 sm:w-16 sm:h-16 text-gray-300 mx-auto mb-3 sm:mb-4" />
            <h3 className="text-base sm:text-xl font-semibold text-gray-900 mb-2">
              {statusFilter === 'CONTENT_APPROVED' 
                ? 'No products ready to ship' 
                : 'No products in transit'}
            </h3>
            <p className="text-xs sm:text-base text-gray-500 mb-4 sm:mb-6">
              {statusFilter === 'CONTENT_APPROVED'
                ? 'Products will appear here after admin content approval'
                : 'Products you ship will appear here until received'}
            </p>
            <Link
              href="/seller/boutique/upload"
              className="inline-flex items-center gap-1.5 sm:gap-2 bg-purple-600 text-white px-4 sm:px-6 py-2 sm:py-3 rounded-lg sm:rounded-xl font-semibold hover:bg-purple-700 transition text-sm"
            >
              <Plus className="w-4 h-4 sm:w-5 sm:h-5" />
              <span className="hidden xs:inline">Upload New</span> Product
            </Link>
          </div>
        ) : (
          <div className="space-y-3 sm:space-y-4">
            {filteredProducts.map((product) => {
              const statusConfig = STATUS_CONFIG[product.status] || STATUS_CONFIG.DRAFT
              const StatusIcon = statusConfig.icon
              
              return (
                <div
                  key={product.id}
                  className="bg-white rounded-lg sm:rounded-xl shadow-sm overflow-hidden hover:shadow-md transition"
                >
                  <div className="p-3 sm:p-4 flex gap-3 sm:gap-4">
                    {/* Product Image */}
                    <div className="w-16 h-16 sm:w-24 sm:h-24 rounded-lg overflow-hidden bg-gray-100 flex-shrink-0">
                      <Image
                        src={product.thumbnailUrl || '/images/placeholder.png'}
                        alt={product.title}
                        width={96}
                        height={96}
                        className="w-full h-full object-cover"
                      />
                    </div>

                    {/* Product Info */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between gap-2 sm:gap-4">
                        <div>
                          <h3 className="font-semibold text-gray-900 truncate text-sm sm:text-base">
                            {product.title}
                          </h3>
                          <p className="text-purple-600 font-medium text-xs sm:text-sm">
                            {formatPrice(product.basePrice)}
                          </p>
                        </div>
                        <span className={`inline-flex items-center gap-0.5 sm:gap-1 px-1.5 sm:px-2.5 py-0.5 sm:py-1 rounded-full text-[10px] sm:text-xs font-medium ${statusConfig.bgColor} ${statusConfig.color}`}>
                          <StatusIcon className="w-2.5 h-2.5 sm:w-3 sm:h-3" />
                          <span className="hidden xs:inline">{statusConfig.label}</span>
                        </span>
                      </div>

                      {/* Shipment Info */}
                      {product.shipment && (
                        <div className="mt-2 p-2 bg-gray-50 rounded-lg text-xs sm:text-sm">
                          <div className="flex flex-wrap items-center gap-2 sm:gap-4 text-gray-600">
                            <span><strong>Courier:</strong> {product.shipment.courier}</span>
                            <span className="hidden sm:inline"><strong>Tracking:</strong> {product.shipment.trackingNumber}</span>
                            {product.shipment.estimatedArrival && (
                              <span className="hidden md:inline"><strong>ETA:</strong> {formatDate(product.shipment.estimatedArrival)}</span>
                            )}
                          </div>
                        </div>
                      )}

                      {/* Action */}
                      <div className="mt-2 sm:mt-3">
                        {product.status === 'CONTENT_APPROVED' ? (
                          <Link
