          <h3 className="font-semibold text-purple-900 mb-2 sm:mb-3 text-sm sm:text-base">Shipping Guidelines</h3>
          <ul className="space-y-1.5 sm:space-y-2 text-xs sm:text-sm text-purple-700">
            <li className="flex items-start gap-1.5 sm:gap-2">
              <span className="w-4 h-4 sm:w-5 sm:h-5 bg-purple-200 rounded-full flex items-center justify-center flex-shrink-0 text-[10px] sm:text-xs font-bold text-purple-800">1</span>
              <span>Package your item securely to prevent damage</span>
            </li>
            <li className="flex items-start gap-1.5 sm:gap-2">
              <span className="w-4 h-4 sm:w-5 sm:h-5 bg-purple-200 rounded-full flex items-center justify-center flex-shrink-0 text-[10px] sm:text-xs font-bold text-purple-800">2</span>
              <span>Use a reliable courier with tracking</span>
            </li>
            <li className="flex items-start gap-1.5 sm:gap-2">
              <span className="w-4 h-4 sm:w-5 sm:h-5 bg-purple-200 rounded-full flex items-center justify-center flex-shrink-0 text-[10px] sm:text-xs font-bold text-purple-800">3</span>
              <span>Ship within 7 days to avoid cancellation</span>
            </li>
            <li className="flex items-start gap-1.5 sm:gap-2">
              <span className="w-4 h-4 sm:w-5 sm:h-5 bg-purple-200 rounded-full flex items-center justify-center flex-shrink-0 text-[10px] sm:text-xs font-bold text-purple-800">4</span>
              <span>Enter tracking details once shipped</span>
            </li>
          </ul>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState, useCallback } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import toast from 'react-hot-toast'
import { ChevronDown, Search, AlertCircle, Clock, TrendingDown } from 'lucide-react'
import Image from 'next/image'

interface Product {
  id: string
  title: string
  basePrice: number
  currentStock?: number
  thumbnailUrl?: string
  receivedByAdminAt: string | null
  daysInWarehouse: number
  inMonth5: boolean
  canRepost: boolean
  cycleInfo: {
    daysInCurrentCycle: number
    displayDays: string
    daysRemaining: number
  }
  pendingRepost?: {
    id: string
    units: number
    reason: string
    originalStock: number
    notes?: string
    createdAt: string
  } | null
}

export default function WarehouseExpirationPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [products, setProducts] = useState<Product[]>([])
  const [filteredProducts, setFilteredProducts] = useState<Product[]>([])
  const [loading, setLoading] = useState(true)
  const [searchTerm, setSearchTerm] = useState('')
  const [expandedId, setExpandedId] = useState<string | null>(null)
  const [repostingId, setRepostingId] = useState<string | null>(null)
  const [showRepostModal, setShowRepostModal] = useState(false)
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null)
  const [repostReason, setRepostReason] = useState('')
  const [repostNotes, setRepostNotes] = useState('')

  // Fetch products
  const fetchProducts = useCallback(async () => {
    try {
      setLoading(true)
      console.log('≡ƒöì Fetching warehouse products...')
      const response = await fetch('/api/boutique/seller/warehouse-expiration', {
        credentials: 'include'
      })
      console.log(`≡ƒôè API Response status: ${response.status}`)
      
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}))
        console.error('Γ¥î API Error:', errorData)
        throw new Error(errorData.error || `Failed to fetch (${response.status})`)
      }
      
      const data = await response.json()
      console.log(`Γ£à Got ${data.products?.length || 0} products`, data)
      setProducts(data.products || [])
    } catch (error) {
      console.error('Error fetching products:', error)
      const errorMsg = error instanceof Error ? error.message : 'Failed to load products'
      toast.error(errorMsg)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    console.log(`≡ƒôì Session status changed: ${status}`)
    if (status === 'unauthenticated') {
      console.log('≡ƒÜ¬ Redirecting to login (unauthenticated)')
      router.push('/login')
      return
    }
    if (status === 'authenticated') {
      console.log('Γ£à User authenticated, fetching products')
      fetchProducts()
    } else {
      console.log(`ΓÅ│ Waiting for auth... status=${status}`)
    }
  }, [status, fetchProducts, router])

  // Search & filter
  useEffect(() => {
    let filtered = products
    
    if (searchTerm) {
      filtered = products.filter(p =>
        p.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.id.includes(searchTerm)
      )
    }
    
    // Sort: Month 5 products first, then by days in warehouse
    filtered.sort((a, b) => {
      if (a.inMonth5 && !b.inMonth5) return -1
      if (!a.inMonth5 && b.inMonth5) return 1
      return b.daysInWarehouse - a.daysInWarehouse
    })
    
    setFilteredProducts(filtered)
  }, [searchTerm, products])

  const handleRepostClick = (product: Product) => {
    if (!product.canRepost) {
      toast.error('Product is not eligible for reposting yet')
      return
    }
    setSelectedProduct(product)
    setShowRepostModal(true)
  }

  const handleSubmitRepost = async () => {
    if (!selectedProduct || !repostReason) {
      toast.error('Please select a reason for reposting')
      return
    }

    try {
      setRepostingId(selectedProduct.id)
      const response = await fetch(`/api/boutique/seller/warehouse-expiration/${selectedProduct.id}/repost`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          reason: repostReason,
          notes: repostNotes,
        })
      })

      const data = await response.json()
      if (!response.ok) throw new Error(data.error || 'Failed to submit repost request')

      toast.success('Repost request submitted! Admin will review it shortly.')
      setShowRepostModal(false)
      setRepostReason('')
      setRepostNotes('')
      setSelectedProduct(null)
      await fetchProducts()
    } catch (error) {
      console.error('Error submitting repost:', error)
      toast.error(error instanceof Error ? error.message : 'Failed to submit repost request')
    } finally {
      setRepostingId(null)
    }
  }

  const notificationCount = products.filter(p => p.inMonth5).length

  if (status === 'loading' || loading) {
    return <div className="p-8 text-center">Loading...</div>
  }

  return (
    <div className="min-h-screen bg-gray-50 p-3 sm:p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-6 sm:mb-8">
          <h1 className="text-xl sm:text-2xl md:text-3xl font-bold text-gray-900 mb-2">
            Warehouse Inventory
          </h1>
          <p className="text-xs sm:text-sm text-gray-600">
            Manage products in storage. Products entering Month 5 (120+ days) need attention.
          </p>
        </div>

        {/* Alert if products need attention */}
        {notificationCount > 0 && (
          <div className="mb-4 sm:mb-6 p-3 sm:p-4 bg-orange-50 border border-orange-200 rounded-lg flex items-start gap-2 sm:gap-3">
            <AlertCircle className="w-4 h-4 sm:w-5 sm:h-5 text-orange-600 flex-shrink-0 mt-0.5" />
            <div>
              <p className="text-xs sm:text-sm font-semibold text-orange-900">
                {notificationCount} product{notificationCount !== 1 ? 's' : ''} need attention
              </p>
              <p className="text-xs text-orange-700 mt-1">
                These products have been in the warehouse for 120+ days. You can reduce the price or repost them to reset the countdown.
              </p>
            </div>
          </div>
        )}

        {/* Search */}
        <div className="mb-4 sm:mb-6">
          <div className="relative">
            <Search className="absolute left-2.5 sm:left-3 top-2.5 sm:top-3 w-4 h-4 sm:w-5 sm:h-5 text-gray-400" />
            <input
              type="text"
              placeholder="Search by product name or ID..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-8 sm:pl-10 pr-3 sm:pr-4 py-2 text-sm border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
            />
          </div>
        </div>

        {/* Products List */}
        {filteredProducts.length === 0 ? (
          <div className="text-center py-12">
            <Clock className="w-12 h-12 text-gray-400 mx-auto mb-4" />
            <p className="text-gray-500">No products in warehouse</p>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredProducts.map((product) => (
              <div
                key={product.id}
                className={`border rounded-lg overflow-hidden transition-all ${
                  product.inMonth5
                    ? 'border-orange-300 bg-orange-50'
                    : 'border-gray-200 bg-white'
                }`}
              >
                {/* Card Header */}
                <button
                  onClick={() => setExpandedId(expandedId === product.id ? null : product.id)}
                  className="w-full p-2.5 sm:p-3 md:p-4 flex items-start gap-2 sm:gap-3 md:gap-4 hover:bg-gray-50 transition-colors"
                >
                  {/* Thumbnail */}
                  {product.thumbnailUrl && (
                    <div className="w-12 h-12 sm:w-16 sm:h-16 flex-shrink-0 bg-gray-200 rounded">
                      <Image
                        src={product.thumbnailUrl}
                        alt={product.title}
                        width={64}
                        height={64}
                        className="w-full h-full object-cover rounded"
                      />
                    </div>
                  )}

                  {/* Info */}
                  <div className="flex-1 text-left min-w-0">
                    <div className="flex items-start justify-between gap-2 sm:gap-3 md:gap-4">
                      <div className="min-w-0 flex-1">
                        <h3 className="font-semibold text-sm sm:text-base text-gray-900 line-clamp-2">
                          {product.title}
                        </h3>
                        <p className="text-xs sm:text-sm text-gray-600 mt-0.5 sm:mt-1 line-clamp-1">
                          Γéª{product.basePrice.toLocaleString()} ΓÇó {product.currentStock || 0} units
                        </p>
                      </div>
                      <ChevronDown
                        className={`w-4 h-4 sm:w-5 sm:h-5 text-gray-400 flex-shrink-0 mt-0.5 transition-transform`}
                        style={{ transform: expandedId === product.id ? 'rotate(180deg)' : '' }}
                      />
                    </div>

                    {/* Status Badges */}
                    <div className="flex items-center gap-1.5 sm:gap-2 mt-2 sm:mt-3 flex-wrap">
                      <span className="inline-flex items-center gap-1 text-xs px-2 py-1 bg-gray-100 text-gray-700 rounded whitespace-nowrap">
                        <Clock className="w-3 h-3" />
                        {product.cycleInfo.displayDays} days
                      </span>
                      {product.inMonth5 && (
                        <span className="inline-flex items-center gap-1 text-xs px-2 py-1 bg-orange-100 text-orange-700 rounded font-semibold whitespace-nowrap">
                          <AlertCircle className="w-3 h-3" />
                          Month 5
                        </span>
                      )}
                      {product.daysInWarehouse >= 173 && !product.inMonth5 && (
                        <span className="inline-flex items-center gap-1 text-xs px-2 py-1 bg-red-100 text-red-700 rounded font-semibold whitespace-nowrap">
                          <TrendingDown className="w-3 h-3" />
                          Expiring Soon
                        </span>
                      )}
                    </div>
                  </div>
                </button>

                {/* Expanded Content */}
                {expandedId === product.id && (
                  <div className="border-t border-gray-200 p-3 sm:p-4 bg-white space-y-3 sm:space-y-4">
                    {/* Timeline */}
                    <div>
                      <h4 className="font-semibold text-xs sm:text-sm text-gray-900 mb-2 sm:mb-3">Storage Timeline</h4>
                      <div className="space-y-1.5 sm:space-y-2">
                        <div className="flex justify-between text-xs sm:text-sm">
                          <span className="text-gray-600">Days in warehouse:</span>
                          <span className="font-semibold text-gray-900">{product.daysInWarehouse}</span>
                        </div>
                        <div className="flex justify-between text-xs sm:text-sm">
                          <span className="text-gray-600">Current cycle progress:</span>
                          <span className="font-semibold text-gray-900">{product.cycleInfo.daysInCurrentCycle}/180</span>
                        </div>
                        <div className="flex justify-between text-xs sm:text-sm">
                          <span className="text-gray-600">Days remaining:</span>
                          <span className="font-semibold text-orange-600">{product.cycleInfo.daysRemaining}</span>
                        </div>
                        <div className="w-full bg-gray-200 rounded-full h-2 mt-2 sm:mt-3">
                          <div
                            className="bg-orange-500 h-2 rounded-full transition-all"
                            style={{
                              width: `${Math.min(100, (product.cycleInfo.daysInCurrentCycle / 180) * 100)}%`
                            }}
                          />
                        </div>
                      </div>
                    </div>

                    {/* Stock Info */}
                    <div>
                      <h4 className="font-semibold text-xs sm:text-sm text-gray-900 mb-1 sm:mb-2">Current Stock</h4>
                      <p className="text-xs sm:text-sm text-gray-600">
                        {product.currentStock || 0} units in warehouse
                      </p>
                      {product.inMonth5 && (
                        <p className="text-xs text-orange-600 mt-2">
                          ΓÜá∩╕Å Each repost costs 1 unit (recurring every 180 days if not sold)
                        </p>
                      )}
                    </div>

                    {/* Actions */}
                    {product.inMonth5 && (
                      <div className="pt-3 sm:pt-4 border-t border-gray-200 space-y-2.5 sm:space-y-3">
                        {product.pendingRepost ? (
                          <div className="p-3 sm:p-4 bg-blue-50 border border-blue-200 rounded-lg space-y-2">
                            <p className="text-xs sm:text-sm font-semibold text-blue-900">
                              Γ£ô Repost request pending approval
                            </p>
                            <p className="text-xs text-blue-700">
                              Submitted: {new Date(product.pendingRepost.createdAt).toLocaleDateString()} at {new Date(product.pendingRepost.createdAt).toLocaleTimeString()}
                            </p>
                            {product.pendingRepost.notes && (
                              <p className="text-xs text-blue-700">
                                Reason: {product.pendingRepost.reason}
                              </p>
                            )}
                            <p className="text-xs text-blue-600 pt-2 border-t border-blue-200">
                              Admin will review and approve your repost request shortly.
                            </p>
                          </div>
                        ) : (
                          <>
                            <button
                              onClick={() => handleRepostClick(product)}
                              disabled={repostingId === product.id}
                              className="w-full px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 disabled:opacity-50 transition-colors text-xs sm:text-sm font-semibold"
                            >
                              {repostingId === product.id ? 'Submitting...' : 'Repost to Keep Selling'}
                            </button>
                            <p className="text-xs text-gray-500">
                              Reposting will deduct 1 unit from stock and reset the 180-day countdown.
                            </p>
                          </>
                        )}
                      </div>
                    )}

                    {product.daysInWarehouse >= 173 && !product.inMonth5 && (
                      <div className="pt-3 sm:pt-4 border-t border-gray-200 p-2.5 sm:p-3 md:p-4 bg-red-50 rounded">
                        <p className="text-xs sm:text-sm font-semibold text-red-900">
                          ΓÜá∩╕Å Stock deduction in {product.cycleInfo.daysRemaining} days
                        </p>
                        <p className="text-xs text-red-700 mt-1">
                          If not sold by then, 1 unit will be deducted from your stock.
                        </p>
                      </div>
                    )}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Repost Modal */}
      {showRepostModal && selectedProduct && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-3 sm:p-4">
          <div className="bg-white rounded-lg max-w-md w-full p-4 sm:p-6">
            <h3 className="text-base sm:text-lg font-semibold text-gray-900 mb-3 sm:mb-4">
              Repost: {selectedProduct.title}
            </h3>

            <div className="space-y-3 sm:space-y-4 mb-4 sm:mb-6">
              {/* Reason Dropdown */}
              <div>
                <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1.5 sm:mb-2">
                  Why are you reposting? *
                </label>
                <select
                  value={repostReason}
                  onChange={(e) => setRepostReason(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-xs sm:text-sm"
                >
                  <option value="">Select a reason...</option>
                  <option value="Price adjustment">Price adjustment</option>
                  <option value="Seasonal promotion">Seasonal promotion</option>
                  <option value="Inventory management">Inventory management</option>
                  <option value="Product improvement">Product improvement</option>
                  <option value="Market response">Market response</option>
                  <option value="Other">Other</option>
                </select>
              </div>

              {/* Notes */}
              <div>
                <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1.5 sm:mb-2">
                  Additional notes (optional)
                </label>
                <textarea
                  value={repostNotes}
                  onChange={(e) => setRepostNotes(e.target.value)}
                  placeholder="Let admin know if there's anything special..."
                  rows={2}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-xs sm:text-sm"
                />
              </div>

              {/* Info Box */}
              <div className="p-2.5 sm:p-3 bg-blue-50 border border-blue-200 rounded">
                <p className="text-xs text-blue-900">
                  <strong>What happens:</strong> Reposting will reduce your stock by 1 unit and reset the 180-day countdown. Your product will stay LIVE.
                </p>
              </div>
            </div>

            {/* Actions */}
            <div className="flex gap-2 sm:gap-3">
              <button
                onClick={() => {
                  setShowRepostModal(false)
                  setRepostReason('')
                  setRepostNotes('')
                }}
                className="flex-1 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors text-xs sm:text-sm font-medium"
              >
                Cancel
              </button>
              <button
                onClick={handleSubmitRepost}
                disabled={!repostReason || repostingId === selectedProduct.id}
                className="flex-1 px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 disabled:opacity-50 transition-colors text-xs sm:text-sm font-medium"
              >
                {repostingId === selectedProduct.id ? 'Submitting...' : 'Submit Repost'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useEffect, useState, useCallback, useMemo, useRef } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import toast from 'react-hot-toast'
import {
  Search,
  _AlertCircle,
  Package,
  _TrendingDown,
  Filter,
  Calendar,
  Eye,
} from 'lucide-react'
import Image from 'next/image'
import Link from 'next/link'
import { WarehouseReturnModal } from '@/components/boutique/warehouse-return-modal'
import { _getDaysInWarehouse } from '@/lib/boutique/warehouse'

interface Product {
  id: string
  title: string
  slug: string
  basePrice: number | null
  salePrice: number | null
  displayPrice: number | null
  currency: string
  currentStock: number | null
  originalStock: number | null
  thumbnailUrl: string | null
  status: string
  fullReturnEnabled: boolean
  returnStatus: string | null
  warehouseReceivedAt: string | null
  warehouseExpiresAt: string | null
  shipmentWarehouseAddress: any
  daysInWarehouse: number
  daysInCurrentCycle: number
  storageCycle: number
  daysUntilExpiry: number | null
  condition: string
  isLowStock: boolean
  isInMonth5: boolean
  totalSold: number
  salesHistory: Array<{
    quantity: number
    variantInfo: string
    soldAt: string
    price: number
  }>
}

export default function SellerWarehouseInventoryPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [products, setProducts] = useState<Product[]>([])
  const [filteredProducts, setFilteredProducts] = useState<Product[]>([])
  const [loading, setLoading] = useState(true)
  const [expandedId, setExpandedId] = useState<string | null>(null)
  const [salesHistoryPage, setSalesHistoryPage] = useState(0)
  const SALES_HISTORY_PAGE_SIZE = 10
  
  // Debounce timer for search
  const searchDebounceTimer = useRef<NodeJS.Timeout | null>(null)
  const abortController = useRef<AbortController | null>(null)

  // Filters
  const [searchTerm, setSearchTerm] = useState('')
  const [stockStatus, setStockStatus] = useState<'all' | 'in_stock' | 'out_of_stock'>('all')
  const [productStatus, setProductStatus] = useState<'all' | 'LIVE' | 'OUT_OF_STOCK' | 'RETURNED'>('all')
  const [dateFrom, setDateFrom] = useState('')
  const [dateTo, setDateTo] = useState('')

  const fetchProducts = useCallback(async () => {
    try {
      setLoading(true)
      const params = new URLSearchParams()

      if (searchTerm) params.append('search', searchTerm)
      if (stockStatus !== 'all') params.append('stockStatus', stockStatus)
      if (productStatus !== 'all') params.append('status', productStatus)
      if (dateFrom) params.append('dateFrom', dateFrom)
      if (dateTo) params.append('dateTo', dateTo)

      // Cancel previous request if pending
      if (abortController.current) {
        abortController.current.abort()
      }
      abortController.current = new AbortController()

      const response = await fetch(`/api/boutique/seller/warehouse-inventory?${params}`, {
        signal: abortController.current.signal
      })

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}))
        throw new Error(errorData.error || `Failed to fetch (${response.status})`)
      }

      const data = await response.json().catch((err) => {
        console.error('Failed to parse response JSON:', err)
        return {}
      })
      if (!data.products || !Array.isArray(data.products)) {
        console.warn('Invalid response format, expected array of products')
        setProducts([])
      } else {
        setProducts(data.products)
      }
    } catch (error) {
      // Don't show error if request was aborted (user changed filters)
      if (error instanceof Error && error.name === 'AbortError') {
        return
      }
      console.error('Error fetching products:', error)
      const errorMessage = error instanceof Error ? error.message : 'Failed to load warehouse inventory'
      toast.error(errorMessage)
    } finally {
      setLoading(false)
    }
  }, [searchTerm, stockStatus, productStatus, dateFrom, dateTo])

  const handleProductRefresh = useCallback(() => {
    fetchProducts()
  }, [fetchProducts])

  // Memoize expanded product to avoid repeated finds
  const expandedProduct = useMemo(
    () => expandedId ? filteredProducts.find((p) => p.id === expandedId) : null,
    [expandedId, filteredProducts]
  )

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (status === 'authenticated') {
      setSalesHistoryPage(0)
      
      // Debounce search requests - wait 300ms before fetching
      if (searchDebounceTimer.current) {
        clearTimeout(searchDebounceTimer.current)
      }
      
      searchDebounceTimer.current = setTimeout(() => {
        fetchProducts()
      }, searchTerm ? 300 : 0)  // Only debounce if searching
      
      return () => {
        if (searchDebounceTimer.current) {
          clearTimeout(searchDebounceTimer.current)
        }
      }
    }
  }, [status, router, fetchProducts, searchTerm, stockStatus, productStatus, dateFrom, dateTo])

  // Apply client-side filtering
  useEffect(() => {
    let filtered = products

    if (searchTerm) {
      filtered = filtered.filter(
        (p) =>
          p.title.toLowerCase().includes(searchTerm.toLowerCase())
          // Don't search by ID - UUID search is inefficient and not user-friendly
      )
    }

    setFilteredProducts(filtered)
    
    // Reset expanded product if it's not in filtered list anymore
    if (expandedId && !filtered.some(p => p.id === expandedId)) {
      setExpandedId(null)
      setSalesHistoryPage(0)
    }
  }, [products, searchTerm, expandedId])

  // Memoize stats to avoid recalculation on every render
  const stats = useMemo(
    () => ({
      lowStockCount: products.filter((p) => p.isLowStock).length,
      inMonth5Count: products.filter((p) => p.isInMonth5).length,
      outOfStockCount: products.filter((p) => p.status === 'OUT_OF_STOCK' || p.currentStock === 0 || p.currentStock === null).length,
    }),
    [products]
  )

  return (
    <div className="min-h-screen bg-gray-50 p-2 sm:p-3 md:p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-4 sm:mb-6">
          <h1 className="text-xl sm:text-2xl md:text-3xl font-bold text-gray-900">Warehouse Inventory</h1>
          <p className="text-xs sm:text-sm text-gray-600 mt-1">
            Complete audit trail of all products in the warehouse, including live, out of stock, and returned items
          </p>
        </div>

        {/* Quick Stats */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-2 sm:gap-3 md:gap-4 mb-4 sm:mb-6">
          <div className="bg-white rounded-lg shadow-sm p-3 sm:p-4 border-l-4 border-blue-500">
            <p className="text-gray-600 text-xs sm:text-sm">Total Products</p>
            <p className="text-xl sm:text-3xl font-bold text-gray-900 mt-1">
              {products.length}
            </p>
          </div>

          <div className="bg-white rounded-lg shadow-sm p-3 sm:p-4 border-l-4 border-yellow-500">
            <p className="text-gray-600 text-xs sm:text-sm">Low Stock (&le;5 units)</p>
            <p className="text-xl sm:text-3xl font-bold text-yellow-600 mt-1">
              {stats.lowStockCount}
            </p>
          </div>

          <div className="bg-white rounded-lg shadow-sm p-3 sm:p-4 border-l-4 border-orange-500">
            <p className="text-gray-600 text-xs sm:text-sm">In Month 5</p>
            <p className="text-xl sm:text-3xl font-bold text-orange-600 mt-1">
              {stats.inMonth5Count}
            </p>
          </div>

          <div className="bg-white rounded-lg shadow-sm p-3 sm:p-4 border-l-4 border-red-500">
            <p className="text-gray-600 text-xs sm:text-sm">Out of Stock</p>
            <p className="text-xl sm:text-3xl font-bold text-red-600 mt-1">
              {stats.outOfStockCount}
            </p>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-sm p-3 sm:p-4 md:p-6 mb-4 sm:mb-6">
          <h2 className="font-bold text-sm sm:text-base text-gray-900 mb-3 sm:mb-4 flex items-center justify-between gap-2">
            <span className="flex items-center gap-2">
              <Filter size={16} />
              Filters
            </span>
            {(searchTerm || productStatus !== 'all' || stockStatus !== 'all' || dateFrom || dateTo) && (
              <button
                onClick={() => {
                  setSearchTerm('')
                  setProductStatus('all')
                  setStockStatus('all')
                  setDateFrom('')
                  setDateTo('')
                }}
                className="text-xs text-primary hover:text-primary-dark font-medium"
              >
                Reset
              </button>
            )}
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-5 gap-2 sm:gap-3">
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-2.5 text-gray-400" size={16} />
              <input
                type="text"
                placeholder="Search..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-3 py-2 text-sm border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              />
            </div>

            {/* Product Status */}
            <select
              value={productStatus}
              onChange={(e) =>
                setProductStatus(
                  e.target.value as 'all' | 'LIVE' | 'OUT_OF_STOCK' | 'RETURNED'
                )
              }
              className="px-3 py-2 text-sm border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent bg-white cursor-pointer"
            >
              <option value="all">All Status</option>
              <option value="LIVE">Live</option>
              <option value="OUT_OF_STOCK">Out of Stock</option>
              <option value="RETURNED">Returned</option>
            </select>

            {/* Stock Status */}
            <select
              value={stockStatus}
              onChange={(e) =>
                setStockStatus(
                  e.target.value as 'all' | 'in_stock' | 'out_of_stock'
                )
              }
              className="px-3 py-2 text-sm border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent bg-white cursor-pointer"
            >
              <option value="all">All Stock Levels</option>
              <option value="in_stock">In Stock</option>
              <option value="out_of_stock">Out of Stock</option>
            </select>

            {/* Date From */}
            <div className="relative">
              <Calendar className="absolute left-3 top-2.5 text-gray-400" size={16} />
              <input
                type="date"
                value={dateFrom}
                onChange={(e) => setDateFrom(e.target.value)}
                className="w-full pl-10 pr-3 py-2 text-sm border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              />
            </div>

            {/* Date To */}
            <div className="relative">
              <Calendar className="absolute left-3 top-2.5 text-gray-400" size={16} />
              <input
                type="date"
                value={dateTo}
                onChange={(e) => setDateTo(e.target.value)}
                className="w-full pl-10 pr-3 py-2 text-sm border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              />
            </div>
          </div>
        </div>

        {/* Products Table */}
        {filteredProducts.length === 0 ? (
          <div className="bg-white rounded-lg shadow-sm p-6 sm:p-8 md:p-12 text-center">
            <Package className="mx-auto text-gray-400 mb-3 sm:mb-4" size={36} />
            <p className="text-gray-600 text-sm sm:text-base">
              {products.length === 0
                ? 'No products in warehouse yet'
                : 'No products match your filters'}
            </p>
          </div>
        ) : (
          <div className="bg-white rounded-lg shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-600 uppercase">
                      Product
                    </th>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-600 uppercase">
                      Status
                    </th>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-600 uppercase">
                      Stock
                    </th>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-600 uppercase">
                      Price
                    </th>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-600 uppercase">
                      Days In
                    </th>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-600 uppercase">
                      Until
                    </th>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-600 uppercase hidden md:table-cell">
                      Location
                    </th>
                    <th className="px-2 sm:px-3 py-2 text-left text-[10px] sm:text-xs font-medium text-gray-600 uppercase">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {filteredProducts.map((product) => (
                    <tr
                      key={product.id}
                      className={`hover:bg-gray-50 transition text-[9px] sm:text-xs ${
                        product.isInMonth5 ? 'bg-orange-50' : ''
                      }`}
                    >
                      <td className="px-2 sm:px-3 py-2 sm:py-3">
                        <div className="flex items-center gap-2">
                          {product.thumbnailUrl && (
                            <div className="relative w-8 h-8 flex-shrink-0">
                              <Image
                                src={product.thumbnailUrl}
                                alt={product.title}
                                fill
                                className="object-cover rounded"
                              />
                            </div>
                          )}
                          <div>
                            <p className="font-medium text-gray-900 line-clamp-1">
                              {product.title}
                            </p>
                            <p className="text-xs text-gray-500">{product.id.substring(0, 8)}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-2 sm:px-3 py-2 sm:py-3">
                        {product.returnStatus ? (
                          <>
                            {product.returnStatus === 'AWAITING_ADMIN_APPROVAL' && (
                              <span className="px-2 py-1 bg-orange-100 text-orange-700 text-[9px] rounded font-medium">
                                Awaiting Admin Approval for Return
                              </span>
                            )}
                            {product.returnStatus === 'RETURN_APPROVED' && (
                              <span className="px-2 py-1 bg-blue-100 text-blue-700 text-[9px] rounded font-medium">
                                Return Approved
                              </span>
                            )}
                            {product.returnStatus === 'RETURN_IN_TRANSIT' && (
                              <span className="px-2 py-1 bg-purple-100 text-purple-700 text-[9px] rounded font-medium">
                                Return in Transit
                              </span>
                            )}
                            {product.returnStatus === 'RETURN_RECEIVED' && (
                              <span className="px-2 py-1 bg-indigo-100 text-indigo-700 text-[9px] rounded font-medium">
                                Return Received
                              </span>
                            )}
                          </>
                        ) : (
                          <>
                            {product.status === 'LIVE' && (
                              <span className="px-2 py-1 bg-green-100 text-green-700 text-[9px] rounded font-medium">
                                Live
                              </span>
                            )}
                            {product.status === 'IN_RETURN' && (
                              <span className="px-2 py-1 bg-orange-100 text-orange-700 text-[9px] rounded font-medium">
                                In Return
                              </span>
                            )}
                            {product.status === 'SHIPPED_BACK' && (
                              <span className="px-2 py-1 bg-purple-100 text-purple-700 text-[9px] rounded font-medium">
                                Shipped Back
                              </span>
                            )}
                            {product.status === 'OUT_OF_STOCK' && (
                              <span className="px-2 py-1 bg-red-100 text-red-700 text-[9px] rounded font-medium">
                                Out of Stock
                              </span>
                            )}
                            {product.status === 'RETURNED' && (
                              <span className="px-2 py-1 bg-gray-100 text-gray-700 text-[9px] rounded font-medium">
                                Returned
                              </span>
                            )}
                          </>
                        )}
                      </td>
                      <td className="px-2 sm:px-3 py-2 sm:py-3">
                        <div className="flex items-center gap-2">
                          {product.currentStock === 0 || product.currentStock === null ? (
                            <span className="px-2 py-1 bg-red-100 text-red-700 text-[9px] rounded font-medium">
                              Out
                            </span>
                          ) : product.isLowStock ? (
                            <span className="px-2 py-1 bg-yellow-100 text-yellow-700 text-[9px] rounded font-medium">
                              {product.currentStock}
                            </span>
                          ) : (
                            <span className="text-gray-900 font-medium text-[9px] sm:text-xs">
                              {product.currentStock}
                            </span>
                          )}
                        </div>
                      </td>
                      <td className="px-2 sm:px-3 py-2 sm:py-3">
                        <p className="font-medium text-gray-900 text-[9px] sm:text-xs">
                          {product.displayPrice !== null ? `${product.displayPrice.toLocaleString()} ${product.currency}` : 'N/A'}
                        </p>
                      </td>
                      <td className="px-2 sm:px-3 py-2 sm:py-3">
                        <span className="text-[9px] sm:text-xs text-gray-600">
                          {product.warehouseReceivedAt ? (
                            <>
                              {product.daysInCurrentCycle}/{181}
                              {product.storageCycle > 1 && <span className="ml-1 text-gray-500">(C{product.storageCycle})</span>}
                            </>
                          ) : (
                            'ΓÇö'
                          )}
                        </span>
                      </td>
                      <td className="px-2 sm:px-3 py-2 sm:py-3">
                        <span
                          className={`font-medium text-[9px] sm:text-xs ${
                            product.warehouseExpiresAt && product.daysUntilExpiry !== null && product.daysUntilExpiry <= 30
                              ? 'text-red-600'
                              : product.warehouseExpiresAt && product.daysUntilExpiry !== null && product.daysUntilExpiry <= 60
                              ? 'text-orange-600'
                              : product.warehouseExpiresAt && product.daysUntilExpiry !== null && product.daysUntilExpiry < 0
                              ? 'text-red-600'
                              : 'text-green-600'
                          }`}
                        >
                          {product.warehouseExpiresAt && product.daysUntilExpiry !== null 
                            ? product.daysUntilExpiry < 0 
                              ? 'Expired'
                              : `${product.daysUntilExpiry}d`
                            : 'ΓÇö'}
                        </span>
                      </td>
                      <td className="px-2 sm:px-3 py-2 sm:py-3">
                        <p className="text-[9px] sm:text-xs text-gray-600">
                          {product.shipmentWarehouseAddress && typeof product.shipmentWarehouseAddress === 'object'
                            ? (() => {
                                const addr = product.shipmentWarehouseAddress as Record<string, any>
                                return `${addr.city || ''}, ${addr.state || ''}`.trim() || 'N/A'
                              })()
                            : 'N/A'}
                        </p>
                      </td>
                      <td className="px-2 sm:px-3 py-2 sm:py-3">
                        <button
                          onClick={() => {
                            setExpandedId(product.id)
                            setSalesHistoryPage(0)
                          }}
                          className="text-[9px] sm:text-xs text-primary hover:text-primary-dark font-medium"
                        >
                          View
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Expanded Details Modal */}
            {expandedId && expandedProduct && (
              <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
                <div className="bg-white rounded-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                  <div className="sticky top-0 bg-white border-b border-gray-200 p-3 sm:p-4 md:p-6 flex items-center justify-between">
                    <h3 className="font-bold text-gray-900 text-sm sm:text-base md:text-lg">
                      Details for {expandedProduct.title}
                    </h3>
                    <button
                      onClick={() => {
                        setExpandedId(null)
                        setSalesHistoryPage(0)
                      }}
                      className="p-1 hover:bg-gray-100 rounded text-gray-500 hover:text-gray-700"
                      aria-label="Close details"
                    >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
                  </div>

                  <div className="p-3 sm:p-4 md:p-6">
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2 sm:gap-3 mb-4">
                      <div className="bg-gray-50 rounded p-2">
                        <p className="text-xs font-medium text-gray-600 uppercase">
                          Condition
                        </p>
                        <p className="text-gray-900 mt-1 text-xs sm:text-sm break-words">
                          {expandedProduct.condition || 'Not specified'}
                        </p>
                      </div>
                      <div className="bg-gray-50 rounded p-2">
                        <p className="text-xs font-medium text-gray-600 uppercase">
                          Location
                        </p>
                        <p className="text-gray-900 mt-1 text-xs sm:text-sm break-words">
                          {expandedProduct.shipmentWarehouseAddress && typeof expandedProduct.shipmentWarehouseAddress === 'object'
                            ? (() => {
                                const addr = expandedProduct.shipmentWarehouseAddress as Record<string, any>
                                return `${addr.city || ''} ${addr.state || ''}`.trim() || 'N/A'
                              })()
                            : 'N/A'}
                        </p>
                      </div>
                      <div className="bg-gray-50 rounded p-2">
                        <p className="text-xs font-medium text-gray-600 uppercase">
                          Received
                        </p>
                        <p className="text-gray-900 mt-1 text-xs sm:text-sm break-words">
                          {expandedProduct.warehouseReceivedAt
                            ? (() => {
                                const date = new Date(expandedProduct.warehouseReceivedAt)
                                return !isNaN(date.getTime()) ? date.toLocaleDateString('en-US', {month: 'short', day: 'numeric'}) : 'Invalid date'
                              })()
                            : 'N/A'}
                        </p>
                      </div>
                      <div className="bg-gray-50 rounded p-2">
                        <p className="text-xs font-medium text-gray-600 uppercase">
                          Status
                        </p>
                        <p className="text-gray-900 mt-1 text-xs sm:text-sm">
                          {expandedProduct.returnStatus ? (
                            (() => {
                              if (expandedProduct.returnStatus === 'AWAITING_ADMIN_APPROVAL') return <span className="text-orange-600 font-medium">Awaiting Admin Approval</span>;
                              if (expandedProduct.returnStatus === 'RETURN_APPROVED') return <span className="text-blue-600 font-medium">Return Approved</span>;
                              if (expandedProduct.returnStatus === 'RETURN_IN_TRANSIT') return <span className="text-purple-600 font-medium">Return in Transit</span>;
                              if (expandedProduct.returnStatus === 'RETURN_RECEIVED') return <span className="text-indigo-600 font-medium">Return Received</span>;
                              return 'Unknown';
                            })()
                          ) : (
                            (() => {
                              if (expandedProduct.status === 'LIVE') return <span className="text-green-600 font-medium">Live</span>;
                              if (expandedProduct.status === 'IN_RETURN') return <span className="text-orange-600 font-medium">In Return</span>;
                              if (expandedProduct.status === 'SHIPPED_BACK') return <span className="text-purple-600 font-medium">Shipped Back</span>;
                              if (expandedProduct.status === 'OUT_OF_STOCK') return <span className="text-red-600 font-medium">Out of Stock</span>;
                              if (expandedProduct.status === 'RETURNED') return <span className="text-gray-600 font-medium">Returned</span>;
                              return 'Unknown';
                            })()
                          )}
                        </p>
                      </div>
                    </div>

                    <Link
                      href={
                        // Internal seller product details for:
                        // - Return-related statuses (IN_RETURN, RETURNED, SHIPPED_BACK)
                        // - Out of stock products
                        // - Products in warehouse but not yet LIVE (RECEIVED_BY_ADMIN, VERIFICATION_PASSED, etc.)
                        ['IN_RETURN', 'RETURNED', 'SHIPPED_BACK', 'RETURN_REQUESTED', 'RETURN_SHIPPED', 'RETURNED_TO_SELLER', 'RECEIVED_BY_ADMIN', 'VERIFICATION_PASSED', 'CONTENT_APPROVED', 'SHIPPED_TO_ADMIN', 'PENDING_CONTENT_REVIEW', 'DRAFT'].includes(expandedProduct.status)
                          ? `/seller/boutique/product-details/${expandedProduct.id}`
                          : expandedProduct.status === 'OUT_OF_STOCK'
                          ? `/seller/boutique/product-details/out-of-stock/${expandedProduct.id}`
                          : // Only go to public boutique for LIVE products (use slug if available, fallback to ID)
                            `/boutique/${expandedProduct.slug || expandedProduct.id}`
                      }
                      className="text-primary-600 hover:text-primary-700 font-medium text-xs sm:text-sm flex items-center gap-1 mb-3"
                    >
                      <Eye size={14} />
                      View Product
                    </Link>

                    {/* Sales History */}
                    <div className="mt-3 border-t pt-3">
                      <h4 className="font-bold text-gray-900 mb-2 text-xs sm:text-sm">
                        Sales History
                        <span className="ml-2 text-xs font-normal text-gray-600">
                          ({expandedProduct.totalSold || 0} unit{(expandedProduct.totalSold || 0) !== 1 ? 's' : ''} sold)
                        </span>
                      </h4>
                      
                      {(expandedProduct.salesHistory && Array.isArray(expandedProduct.salesHistory) && expandedProduct.salesHistory.length > 0) ? (
                        <div className="overflow-x-auto">
                          <table className="w-full text-xs sm:text-sm">
                            <thead>
                              <tr className="border-b border-gray-300">
                                <th className="px-2 py-1 sm:px-3 sm:py-2 text-left text-xs font-medium text-gray-600 uppercase">Date</th>
                                <th className="px-2 py-1 sm:px-3 sm:py-2 text-left text-xs font-medium text-gray-600 uppercase">Qty</th>
                                <th className="px-2 py-1 sm:px-3 sm:py-2 text-left text-xs font-medium text-gray-600 uppercase hidden sm:table-cell">Variant</th>
                                <th className="px-2 py-1 sm:px-3 sm:py-2 text-left text-xs font-medium text-gray-600 uppercase">Price</th>
                              </tr>
                            </thead>
                            <tbody>
                              {(expandedProduct.salesHistory || [])
                                .slice(salesHistoryPage * SALES_HISTORY_PAGE_SIZE, (salesHistoryPage + 1) * SALES_HISTORY_PAGE_SIZE)
                                .map((sale: any, idx: number) => {
                                  const saleDate = sale?.soldAt ? new Date(sale.soldAt) : null
                                  const isValidDate = saleDate && !isNaN(saleDate.getTime())
                                  return (
                                <tr key={idx} className="border-b border-gray-200 hover:bg-gray-50 transition">
                        <td className="px-2 py-1 sm:px-3 sm:py-2 text-gray-900 text-xs">
                          {isValidDate ? saleDate!.toLocaleDateString('en-US', {month: 'short', day: 'numeric'}) : 'N/A'}
                        </td>
                        <td className="px-2 py-1 sm:px-3 sm:py-2 font-medium text-gray-900 text-xs sm:text-sm">{sale?.quantity || 0}</td>
                        <td className="px-2 py-1 sm:px-3 sm:py-2 text-gray-700 text-xs hidden sm:table-cell">{sale?.variantInfo || 'Std'}</td>
                        <td className="px-2 py-1 sm:px-3 sm:py-2 text-gray-900 text-xs sm:text-sm">Γéª{((sale?.price || 0)).toLocaleString()}</td>
                                </tr>
                                  )
                                })}
                            </tbody>
                          </table>
                          {(expandedProduct.salesHistory || []).length > SALES_HISTORY_PAGE_SIZE && (
                            <div className="flex items-center justify-between p-2 border-t text-xs">
                              <span className="text-gray-600">
                                Page {salesHistoryPage + 1} of {Math.ceil((expandedProduct.salesHistory || []).length / SALES_HISTORY_PAGE_SIZE)}
                              </span>
                              <div className="flex gap-1">
                                <button
                                  onClick={() => setSalesHistoryPage(Math.max(0, salesHistoryPage - 1))}
                                  disabled={salesHistoryPage === 0}
                                  className="px-2 py-1 border rounded hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                  Prev
                                </button>
                                <button
                                  onClick={() => setSalesHistoryPage(salesHistoryPage + 1)}
                                  disabled={(salesHistoryPage + 1) * SALES_HISTORY_PAGE_SIZE >= (expandedProduct.salesHistory || []).length}
                                  className="px-2 py-1 border rounded hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                  Next
                                </button>
                              </div>
                            </div>
                          )}
                        </div>
                      ) : (
                        <p className="text-gray-500 text-xs sm:text-sm py-2">No sales yet</p>
                      )}
                    </div>

                    {/* Return from Warehouse Button */}
                    {expandedProduct.warehouseReceivedAt && expandedProduct.status !== 'OUT_OF_STOCK' && (
                      <div className="mt-4 pt-4 border-t">
                        {expandedProduct.fullReturnEnabled || ['AWAITING_ADMIN_APPROVAL', 'RETURN_APPROVED', 'RETURN_IN_TRANSIT', 'RETURN_RECEIVED'].includes(expandedProduct.returnStatus || '') ? (
                          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                            <div className="flex items-start gap-3">
                              <div className="text-xl">Γ£ô</div>
                              <div>
                                <p className="text-sm font-semibold text-blue-900">
                                  {expandedProduct.returnStatus === 'AWAITING_ADMIN_APPROVAL'
                                    ? 'Return Pending Admin Review'
                                    : expandedProduct.returnStatus === 'RETURN_APPROVED'
                                    ? 'Return Approved'
                                    : expandedProduct.returnStatus === 'RETURN_IN_TRANSIT'
                                    ? 'Return in Transit'
                                    : expandedProduct.returnStatus === 'RETURN_RECEIVED'
                                    ? 'Return Received'
                                    : 'Return in Progress'}
                                </p>
                                <p className="text-xs text-blue-700 mt-1.5">
                                  {expandedProduct.returnStatus === 'AWAITING_ADMIN_APPROVAL'
                                    ? 'Your return request is pending admin review. You will be notified when a decision is made.'
                                    : expandedProduct.returnStatus === 'RETURN_APPROVED'
                                    ? 'Your return has been approved by admin. Please prepare the product for shipment.'
                                    : expandedProduct.returnStatus === 'RETURN_IN_TRANSIT'
                                    ? 'Your return is in transit. We will confirm receipt shortly.'
                                    : expandedProduct.returnStatus === 'RETURN_RECEIVED'
                                    ? 'Your return has been received and is being processed.'
                                    : 'Your return request is being processed. You cannot submit another return request at this time.'}
                                </p>
                              </div>
                            </div>
                          </div>
                        ) : (
                          <>
                            <WarehouseReturnModal
                              productId={expandedProduct?.id || ''}
                              productTitle={expandedProduct?.title || ''}
                              daysInWarehouse={expandedProduct?.daysInWarehouse || 0}
                              onSuccess={handleProductRefresh}
                            />
                            <p className="text-xs text-gray-500 mt-2">
                              Request to return this product from the warehouse. Admin fee applies based on storage duration.
                            </p>
                          </>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter, useParams } from 'next/navigation'
import { useSession } from 'next-auth/react'
import {
  Save,
  ArrowLeft,
  Loader2,
  DollarSign,
  Tag,
  Type,
  FileText,
  AlertCircle,
  CheckCircle,
  Eye,
  Lock,
} from 'lucide-react'
import Image from 'next/image'
import Link from 'next/link'

interface MediaFile {
  id: string
  url: string
  fileType: 'IMAGE' | 'VIDEO'
  accessType: 'FREE' | 'PREMIUM'
  isPrimary: boolean
}

interface Design {
  id: string
  title: string
  description: string | null
  price: number
  ownershipPrice: number | null
  category: string
  tags: string | null
  buyingTypes: string
  isActive: boolean
  imageUrl: string
  thumbnailUrl: string | null
  mediaFiles: MediaFile[]
}

export default function EditDesignPage() {
  const { data: session, status: authStatus } = useSession()
  const router = useRouter()
  const params = useParams()
  const designId = params.id as string

  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [design, setDesign] = useState<Design | null>(null)
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null)

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    price: '',
    ownershipPrice: '',
    category: '',
    tags: '',
    buyingTypes: 'REGULAR',
    isActive: true,
  })

  const categories = [
    'Fashion Illustrations',
    'Digital Designs',
    'Pattern Designs',
    'Sketches',
    'Technical Drawings',
    'Concept Art',
  ]

  useEffect(() => {
    if (authStatus === 'loading') return
    if (!session) {
      router.push('/auth/signin')
      return
    }
    fetchDesign()
  }, [session, authStatus, router, designId])

  const fetchDesign = async () => {
    try {
      const response = await fetch(`/api/designs/${designId}`)
      if (response.ok) {
        const data = await response.json()
        // Verify ownership
        if (data.design.designer.id !== session?.user?.id && session?.user?.role !== 'ADMIN') {
          router.push('/seller/designs')
          return
        }
        setDesign(data.design)
        setFormData({
          title: data.design.title || '',
          description: data.design.description || '',
          price: data.design.price?.toString() || '',
          ownershipPrice: data.design.ownershipPrice?.toString() || '',
          category: data.design.category || 'Fashion Illustrations',
          tags: data.design.tags || '',
          buyingTypes: data.design.buyingTypes || 'REGULAR',
          isActive: data.design.isActive,
        })
      } else if (response.status === 404) {
        setMessage({ type: 'error', text: 'Design not found' })
      } else {
        setMessage({ type: 'error', text: 'Failed to load design' })
      }
    } catch (error) {
      console.error('Failed to fetch design:', error)
      setMessage({ type: 'error', text: 'Failed to load design' })
    } finally {
      setLoading(false)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setSaving(true)
    setMessage(null)

    try {
      const response = await fetch(`/api/designs/${designId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: formData.title,
          description: formData.description || null,
          price: parseFloat(formData.price),
          ownershipPrice: formData.ownershipPrice ? parseFloat(formData.ownershipPrice) : null,
          category: formData.category,
          tags: formData.tags || null,
          buyingTypes: formData.buyingTypes,
          isActive: formData.isActive,
        }),
      })

      const data = await response.json()

      if (response.ok) {
        setMessage({ type: 'success', text: 'Design updated successfully!' })
        // Refresh design data
        fetchDesign()
      } else {
        setMessage({ type: 'error', text: data.message || 'Failed to update design' })
      }
    } catch (error) {
      console.error('Failed to update design:', error)
      setMessage({ type: 'error', text: 'An error occurred while saving' })
    } finally {
      setSaving(false)
    }
  }

  if (authStatus === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-indigo-600" />
      </div>
    )
  }

  if (!design) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <AlertCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-gray-900 mb-2">Design Not Found</h1>
          <p className="text-gray-600 mb-6">This design doesn&apos;t exist or you don&apos;t have permission to edit it.</p>
          <Link
            href="/seller/designs"
            className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
          >
            <ArrowLeft className="w-4 h-4" />
            Back to My Designs
          </Link>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <Link
            href="/seller/designs"
            className="inline-flex items-center text-sm text-gray-500 hover:text-gray-700 mb-4"
          >
            <ArrowLeft className="w-4 h-4 mr-1" />
            Back to My Designs
          </Link>
          <h1 className="text-2xl font-bold text-gray-900">Edit Design</h1>
          <p className="text-gray-600 mt-1">Update your design details and settings</p>
        </div>

        {/* Message */}
        {message && (
          <div
            className={`mb-6 p-4 rounded-lg flex items-start gap-3 ${
              message.type === 'success'
                ? 'bg-green-50 border border-green-200'
                : 'bg-red-50 border border-red-200'
            }`}
          >
            {message.type === 'success' ? (
              <CheckCircle className="w-5 h-5 text-green-500 flex-shrink-0" />
            ) : (
              <AlertCircle className="w-5 h-5 text-red-500 flex-shrink-0" />
            )}
            <p className={`text-sm ${message.type === 'success' ? 'text-green-700' : 'text-red-700'}`}>
              {message.text}
            </p>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Preview */}
          <div className="lg:col-span-1">
            <div className="bg-white rounded-xl shadow-sm p-6 sticky top-6">
              <h3 className="font-medium text-gray-900 mb-4">Preview</h3>
              <div className="aspect-square rounded-lg overflow-hidden bg-gray-100 relative mb-4">
                <Image
                  src={design.thumbnailUrl || design.imageUrl}
                  alt={design.title}
                  fill
                  className="object-cover"
                />
              </div>
              <div className="space-y-2 text-sm">
                <p className="text-gray-500">
                  Status:{' '}
                  <span className={`font-medium ${formData.isActive ? 'text-green-600' : 'text-gray-600'}`}>
                    {formData.isActive ? 'Active' : 'Inactive'}
                  </span>
                </p>
                <p className="text-gray-500">
                  Media Files: <span className="font-medium text-gray-900">{design.mediaFiles?.length || 1}</span>
                </p>
              </div>
              <div className="mt-4 pt-4 border-t">
                <Link
                  href={`/designs/${design.id}`}
                  target="_blank"
                  className="inline-flex items-center gap-2 text-sm text-indigo-600 hover:text-indigo-800"
                >
                  <Eye className="w-4 h-4" />
                  View Live Page
                </Link>
              </div>
            </div>
          </div>

          {/* Form */}
          <div className="lg:col-span-2">
            <form onSubmit={handleSubmit} className="bg-white rounded-xl shadow-sm p-6 space-y-6">
              {/* Title */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  <Type className="w-4 h-4 inline mr-1" />
                  Title *
                </label>
                <input
                  type="text"
                  value={formData.title}
                  onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                  required
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 text-gray-900"
                  placeholder="Enter design title"
                />
              </div>

              {/* Description */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  <FileText className="w-4 h-4 inline mr-1" />
                  Description
                </label>
                <textarea
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  rows={4}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 text-gray-900"
                  placeholder="Describe your design..."
                />
              </div>

              {/* Category */}
              <div>
                <label htmlFor="designCategory" className="block text-sm font-medium text-gray-700 mb-1">
                  <Tag className="w-4 h-4 inline mr-1" />
                  Category *
                </label>
                <select
                  id="designCategory"
                  value={formData.category}
                  onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                  required
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 text-gray-900"
                >
                  {categories.map((cat) => (
                    <option key={cat} value={cat}>
                      {cat}
                    </option>
                  ))}
                </select>
              </div>

              {/* Tags */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Tags
                </label>
                <input
                  type="text"
                  value={formData.tags}
                  onChange={(e) => setFormData({ ...formData, tags: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 text-gray-900"
                  placeholder="fashion, illustration, modern (comma separated)"
                />
              </div>

              {/* Pricing */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    <DollarSign className="w-4 h-4 inline mr-1" />
                    Price (USD) *
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    value={formData.price}
                    onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                    required
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 text-gray-900"
                    placeholder="0.00"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    <Lock className="w-4 h-4 inline mr-1" />
                    Ownership Price (USD)
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    value={formData.ownershipPrice}
                    onChange={(e) => setFormData({ ...formData, ownershipPrice: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 text-gray-900"
                    placeholder="Optional - for exclusive ownership"
                  />
                </div>
              </div>

              {/* Buying Types */}
              <div>
                <label htmlFor="buyingTypes" className="block text-sm font-medium text-gray-700 mb-1">
                  Purchase Options
                </label>
                <select
                  id="buyingTypes"
                  value={formData.buyingTypes}
                  onChange={(e) => setFormData({ ...formData, buyingTypes: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 text-gray-900"
                >
                  <option value="REGULAR">Regular License Only</option>
                  <option value="OWNERSHIP">Ownership Only (Exclusive)</option>
                  <option value="BOTH">Both Regular & Ownership</option>
                </select>
              </div>

              {/* Active Status */}
              <div className="flex items-center justify-between p-4 bg-gray-50 rounded-lg">
                <div>
                  <p className="font-medium text-gray-900">Design Active</p>
                  <p className="text-sm text-gray-500">When inactive, this design won&apos;t appear in search or shop</p>
                </div>
                <label className="relative inline-flex items-center cursor-pointer">
                  <input
                    type="checkbox"
                    checked={formData.isActive}
                    onChange={(e) => setFormData({ ...formData, isActive: e.target.checked })}
                    className="sr-only peer"
                    aria-label="Toggle design active status"
                  />
                  <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-indigo-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-indigo-600"></div>
                </label>
              </div>

              {/* Submit */}
              <div className="flex items-center justify-end gap-3 pt-4 border-t">
                <Link
                  href="/seller/designs"
                  className="px-4 py-2 text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50"
                >
                  Cancel
                </Link>
                <button
                  type="submit"
                  disabled={saving}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50"
                >
                  {saving ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin" />
                      Saving...
                    </>
                  ) : (
                    <>
                      <Save className="w-4 h-4" />
                      Save Changes
                    </>
                  )}
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useEffect, useState } from 'react'
import Link from 'next/link'
import { ArrowLeft, AlertCircle, MessageSquare, Clock, CheckCircle, _XCircle, ExternalLink } from 'lucide-react'
import { useCurrency } from '@/components/CurrencyProvider'

interface Dispute {
  id: string
  disputeNumber: string
  status: 'OPEN' | 'BUYER_APPEAL' | 'SELLER_RESPONSE' | 'AWAITING_DECISION' | 'RESOLVED' | 'CLOSED'
  severity: 'LOW' | 'MEDIUM' | 'HIGH'
  reason: string
  amount: number
  createdAt: string
  updatedAt: string
  buyer: {
    name: string
    email: string
  }
  seller: {
    name: string
    email: string
  }
  order: {
    id: string
    orderNumber: string
  }
  messages: Array<{
    id: string
    author: 'BUYER' | 'SELLER' | 'ADMIN'
    content: string
    createdAt: string
  }>
  resolution: {
    type: 'REFUND' | 'REPLACEMENT' | 'PARTIAL_REFUND' | 'NO_ACTION' | null
    amount: number | null
    notes: string | null
  } | null
}

export default function SellerDisputesPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const { formatPrice } = useCurrency()
  const [disputes, setDisputes] = useState<Dispute[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<string>('open')
  const [searchQuery, setSearchQuery] = useState('')

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (status !== 'authenticated') return

    fetchDisputes()
  }, [status, router])

  const fetchDisputes = async () => {
    try {
      setLoading(true)
      const response = await fetch('/api/seller/disputes')
      if (response.ok) {
        const data = await response.json()
        setDisputes(data.disputes || [])
      }
    } catch (error) {
      console.error('Failed to fetch disputes:', error)
    } finally {
      setLoading(false)
    }
  }

  const filteredDisputes = disputes.filter(d => {
    const statusMatch = filter === 'all' || d.status === filter
    const searchMatch = 
      d.disputeNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
      d.buyer.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      d.order.orderNumber.toLowerCase().includes(searchQuery.toLowerCase())
    return statusMatch && searchMatch
  })

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'OPEN': return 'bg-red-100 text-red-800'
      case 'BUYER_APPEAL': return 'bg-yellow-100 text-yellow-800'
      case 'SELLER_RESPONSE': return 'bg-blue-100 text-blue-800'
      case 'AWAITING_DECISION': return 'bg-purple-100 text-purple-800'
      case 'RESOLVED': return 'bg-green-100 text-green-800'
      case 'CLOSED': return 'bg-gray-100 text-gray-800'
      default: return 'bg-gray-100 text-gray-800'
    }
  }

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'HIGH': return 'bg-red-100 text-red-800'
      case 'MEDIUM': return 'bg-orange-100 text-orange-800'
      case 'LOW': return 'bg-yellow-100 text-yellow-800'
      default: return 'bg-gray-100 text-gray-800'
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'RESOLVED': return <CheckCircle className="w-4 h-4" />
      case 'CLOSED': return <CheckCircle className="w-4 h-4" />
      case 'OPEN': return <AlertCircle className="w-4 h-4" />
      default: return <Clock className="w-4 h-4" />
    }
  }

  if (status === 'loading' || loading) {
    return <div className="p-8 text-center">Loading disputes...</div>
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 md:p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <button
            onClick={() => router.back()}
            className="p-2 hover:bg-gray-200 rounded-lg transition"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Dispute Center</h1>
            <p className="text-gray-600">Manage disputes with buyers</p>
          </div>
        </div>

        {/* Search & Filters */}
        <div className="bg-white rounded-lg shadow-sm p-4 mb-6">
          <div className="flex flex-col sm:flex-row gap-4">
            <input
              type="text"
              placeholder="Search by dispute #, buyer, or order..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="flex-1 px-4 py-2 border border-gray-300 rounded-lg text-black"
            />
            <select
              value={filter}
              onChange={(e) => setFilter(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg text-black bg-white"
            >
              <option value="open">Open</option>
              <option value="all">All Status</option>
              <option value="OPEN">Active Disputes</option>
              <option value="BUYER_APPEAL">Buyer Appeal</option>
              <option value="SELLER_RESPONSE">Awaiting Response</option>
              <option value="AWAITING_DECISION">Awaiting Decision</option>
              <option value="RESOLVED">Resolved</option>
              <option value="CLOSED">Closed</option>
            </select>
          </div>
        </div>

        {/* Disputes List */}
        {filteredDisputes.length === 0 ? (
          <div className="bg-white rounded-lg shadow-sm p-12 text-center">
            <AlertCircle className="w-12 h-12 text-gray-300 mx-auto mb-4" />
            <p className="text-gray-500">No disputes found</p>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredDisputes.map((dispute) => (
              <div key={dispute.id} className="bg-white rounded-lg shadow-sm overflow-hidden hover:shadow-md transition">
                <div className="p-4 sm:p-6">
                  <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between mb-4">
                    <div>
                      <h3 className="font-semibold text-gray-900">Dispute {dispute.disputeNumber}</h3>
                      <p className="text-sm text-gray-600 mt-1">Order {dispute.order.orderNumber}</p>
                    </div>
                    <div className="flex gap-2 mt-3 sm:mt-0">
                      <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium ${getStatusColor(dispute.status)}`}>
                        {getStatusIcon(dispute.status)}
                        {dispute.status.replace(/_/g, ' ')}
                      </span>
                      <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium ${getSeverityColor(dispute.severity)}`}>
                        {dispute.severity} Priority
                      </span>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 sm:gap-4 mb-4 pb-4 border-b border-gray-200">
                    <div>
                      <p className="text-xs text-gray-600">Disputed Amount</p>
                      <p className="font-bold text-lg text-red-600">{formatPrice(dispute.amount)}</p>
                    </div>
                    <div>
                      <p className="text-xs text-gray-600">Buyer</p>
                      <p className="font-medium text-gray-900 text-sm">{dispute.buyer.name}</p>
                    </div>
                    <div>
                      <p className="text-xs text-gray-600">Date</p>
                      <p className="font-medium text-gray-900 text-sm">{new Date(dispute.createdAt).toLocaleDateString()}</p>
                    </div>
                  </div>

                  <div className="mb-4">
                    <p className="text-sm font-medium text-gray-900 mb-2">Reason:</p>
                    <p className="text-sm text-gray-700">{dispute.reason}</p>
                  </div>

                  {dispute.resolution && (
                    <div className="mb-4 p-3 bg-green-50 border border-green-200 rounded-lg">
                      <p className="text-xs text-gray-600 mb-1">Resolution:</p>
                      <p className="text-sm font-medium text-gray-900">{dispute.resolution.type}</p>
                      {dispute.resolution.amount && (
                        <p className="text-sm text-gray-600 mt-1">Amount: {formatPrice(dispute.resolution.amount)}</p>
                      )}
                    </div>
                  )}

                  <div className="flex gap-2">
                    <Link
                      href={`/seller/disputes/${dispute.id}`}
                      className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition text-sm"
                    >
                      View Details
                      <ExternalLink className="w-4 h-4" />
                    </Link>
                    <button className="inline-flex items-center gap-2 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition text-sm">
                      <MessageSquare className="w-4 h-4" />
                      Message
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Stats */}
        {disputes.length > 0 && (
          <div className="grid grid-cols-2 md:grid-cols-5 gap-4 mt-8">
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-indigo-600">{disputes.length}</p>
              <p className="text-xs text-gray-600 mt-1">Total Disputes</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-red-600">{disputes.filter(d => d.status === 'OPEN').length}</p>
              <p className="text-xs text-gray-600 mt-1">Open</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-yellow-600">{disputes.filter(d => ['BUYER_APPEAL', 'SELLER_RESPONSE'].includes(d.status)).length}</p>
              <p className="text-xs text-gray-600 mt-1">In Progress</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-green-600">{disputes.filter(d => d.status === 'RESOLVED').length}</p>
              <p className="text-xs text-gray-600 mt-1">Resolved</p>
            </div>
            <div className="bg-white rounded-lg p-4 text-center shadow-sm">
              <p className="text-2xl font-bold text-purple-600">{formatPrice(disputes.filter(d => d.status === 'OPEN').reduce((sum, d) => sum + d.amount, 0))}</p>
              <p className="text-xs text-gray-600 mt-1">At Risk</p>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import toast from 'react-hot-toast'
import { useCurrency } from '@/components/CurrencyProvider'
import {
  Star,
  Trash2,
  Image as ImageIcon,
  ShoppingBag,
  DollarSign,
  AlertCircle,
  Lock,
  _ArrowUp,
  _ArrowDown,
} from 'lucide-react'

interface FeaturedItem {
  id: string
  itemType: 'DESIGN' | 'BOUTIQUE_PRODUCT'
  itemId: string
  title: string
  imageUrl?: string
  price: number
  totalSales?: number
  position: number
  addedAt: string
}

export default function SellerFeaturedItemsPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const { formatPrice } = useCurrency()

  const [designs, setDesigns] = useState<FeaturedItem[]>([])
  const [products, setProducts] = useState<FeaturedItem[]>([])
  const [loading, setLoading] = useState(true)
  const [maxFeatured, setMaxFeatured] = useState(0)
  const [remainingSlots, setRemainingSlots] = useState(0)
  const [subscriptionTier, setSubscriptionTier] = useState<string | null>(null)
  const [deletingId, setDeletingId] = useState<string | null>(null)
  const [updatingPositionId, setUpdatingPositionId] = useState<string | null>(null)
  const [editingPositions, setEditingPositions] = useState<Record<string, number>>({})

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/auth/signin')
    } else if (status === 'authenticated') {
      fetchFeaturedItems()
    }
  }, [status, router])

  const fetchFeaturedItems = async () => {
    try {
      setLoading(true)
      let designsData = null
      let productsData = null
      let hasError = false

      // Get featured designs
      const designRes = await fetch('/api/seller/featured-designs')
      if (designRes.ok) {
        const json = await designRes.json()
        if (json.items && Array.isArray(json.items)) {
          designsData = json
          setDesigns(json.items)
          setMaxFeatured(json.maxFeatured || 0)
          setSubscriptionTier(json.subscriptionTier || null)
        }
      } else {
        toast.error('Failed to load featured designs')
        hasError = true
      }

      // Get featured boutique products
      const productRes = await fetch('/api/seller/featured-boutique-products')
      if (productRes.ok) {
        const json = await productRes.json()
        if (json.items && Array.isArray(json.items)) {
          productsData = json
          setProducts(json.items)
        }
      } else {
        toast.error('Failed to load featured products')
        hasError = true
      }

      // Calculate total remaining slots only if we have both data
      if (designsData && designsData.maxFeatured !== undefined && productsData && Array.isArray(productsData.items)) {
        const designCount = designsData.currentFeaturedCount ?? designsData.items?.length ?? 0
        const productCount = productsData.currentFeaturedCount ?? productsData.items?.length ?? 0
        const totalCurrently = designCount + productCount
        const maxAllowed = designsData.maxFeatured ?? 0
        setRemainingSlots(Math.max(0, maxAllowed - totalCurrently))
      }
    } catch (error) {
      console.error('Error fetching featured items:', error)
      toast.error('Failed to load featured items')
    } finally {
      setLoading(false)
    }
  }

  const handleRemove = async (id: string, itemType: 'DESIGN' | 'BOUTIQUE_PRODUCT') => {
    if (!window.confirm('Remove from featured?')) return

    try {
      setDeletingId(id)
      const endpoint = itemType === 'DESIGN' ? '/api/seller/featured-designs' : '/api/seller/featured-boutique-products'
      const res = await fetch(`${endpoint}?id=${id}`, {
        method: 'DELETE'
      })

      if (!res.ok) throw new Error('Failed to remove')

      toast.success('Item removed from featured')
      fetchFeaturedItems()
    } catch (error) {
      console.error('Error removing item:', error)
      toast.error('Failed to remove item')
    } finally {
      setDeletingId(null)
    }
  }

  const handleUpdatePosition = async (id: string, itemType: 'DESIGN' | 'BOUTIQUE_PRODUCT', newPosition: number) => {
    // Validate position
    if (newPosition < 1 || !Number.isInteger(newPosition)) {
      toast.error('Position must be a positive number')
      return
    }

    if (newPosition > maxFeatured) {
      toast.error(`Position cannot exceed ${maxFeatured}`)
      return
    }
    
    try {
      setUpdatingPositionId(id)
      const endpoint = itemType === 'DESIGN' ? '/api/seller/featured-designs' : '/api/seller/featured-boutique-products'
      const res = await fetch(`${endpoint}?id=${id}&position=${newPosition}`, {
        method: 'PATCH'
      })

      if (!res.ok) {
        const error = await res.json().catch(() => ({}))
        throw new Error(error.error || 'Failed to update position')
      }

      toast.success('Position updated')
      setEditingPositions(prev => {
        const newEditing = { ...prev }
        delete newEditing[id]
        return newEditing
      })
      fetchFeaturedItems()
    } catch (error) {
      console.error('Error updating position:', error)
      const message = error instanceof Error ? error.message : 'Failed to update position'
      toast.error(message)
    } finally {
      setUpdatingPositionId(null)
    }
  }

  const getTierInfo = () => {
    switch (subscriptionTier) {
      case 'STARTER':
        return { name: 'Starter', color: 'bg-blue-100 text-blue-900', max: 2 }
      case 'PRO':
        return { name: 'Pro', color: 'bg-purple-100 text-purple-900', max: 6 }
      case 'VIP':
        return { name: 'VIP', color: 'bg-amber-100 text-amber-900', max: 10 }
      default:
        return { name: 'Free', color: 'bg-gray-100 text-gray-900', max: 0 }
    }
  }

  const tierInfo = getTierInfo()
  const totalFeatured = designs.length + products.length
  const canAddMore = totalFeatured < maxFeatured

  if (status === 'loading') return <div className="p-4 sm:p-8 text-center"><div className="inline-block">Loading...</div></div>
  if (status === 'unauthenticated') return null

  return (
    <div className="min-h-screen bg-gray-50 p-2 sm:p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-3 sm:mb-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
            <div>
              <h1 className="text-xl sm:text-2xl md:text-3xl font-bold text-gray-900 flex items-center gap-1 sm:gap-2">
                <Star className="h-5 w-5 sm:h-6 sm:w-6 md:h-8 md:w-8 text-yellow-500" />
                Featured Items
              </h1>
              <p className="text-xs sm:text-sm text-gray-600 mt-0.5 sm:mt-1">Manage your featured designs and products</p>
            </div>
            <div className={`rounded-lg p-2.5 sm:p-3 md:p-4 whitespace-nowrap ${tierInfo.color}`}>
              <div className="text-xs sm:text-sm font-medium">Your Plan: {tierInfo.name}</div>
              <div className="text-lg sm:text-xl md:text-2xl font-bold">{totalFeatured}/{maxFeatured}</div>
              <div className="text-[10px] sm:text-xs mt-0.5 sm:mt-1">Featured Items</div>
            </div>
          </div>
        </div>

        {/* Subscription Info */}
        {maxFeatured === 0 && (
          <div className="mb-3 sm:mb-6 bg-blue-50 border border-blue-200 rounded-lg p-2.5 sm:p-4 flex items-start gap-2 sm:gap-3">
            <AlertCircle className="h-4 w-4 sm:h-5 sm:w-5 text-blue-600 mt-0.5 flex-shrink-0" />
            <div>
              <h3 className="text-sm sm:text-base font-medium text-blue-900">No Featured Items Available</h3>
              <p className="text-xs sm:text-sm text-blue-800 mt-1">
                Your current plan doesn't include featured items. Upgrade to Pro or VIP to feature up to 10 items on your storefront.
              </p>
              <button
                onClick={() => router.push('/seller/upgrade')}
                className="mt-1 sm:mt-2 text-xs sm:text-sm font-medium text-blue-600 hover:text-blue-700 underline"
              >
                View upgrade plans ΓåÆ
              </button>
            </div>
          </div>
        )}

        {/* Featured Designs */}
        <div className="bg-white rounded-lg shadow mb-3 sm:mb-6">
          <div className="px-3 sm:px-4 md:px-6 py-2.5 sm:py-3 md:py-4 border-b border-gray-200 flex items-center justify-between">
            <div>
              <h2 className="text-base sm:text-lg font-semibold text-gray-900 flex items-center gap-1.5 sm:gap-2">
                <ImageIcon className="h-4 w-4 sm:h-5 sm:w-5 text-purple-600" />
                Featured Designs
              </h2>
              <p className="text-xs sm:text-sm text-gray-600 mt-0.5 sm:mt-1">{designs.length} designs featured</p>
            </div>
          </div>

          {designs.length === 0 ? (
            <div className="p-4 sm:p-8 md:p-12 text-center">
              <ImageIcon className="h-10 w-10 sm:h-12 sm:w-12 md:h-16 md:w-16 mx-auto mb-2 sm:mb-4 opacity-20" />
              <h3 className="text-sm sm:text-base md:text-lg font-semibold text-gray-900 mb-1.5 sm:mb-2">No Featured Designs Yet</h3>
              <p className="text-xs sm:text-sm text-gray-600 mb-3 sm:mb-6">Start featuring your designs to boost visibility on your storefront</p>
              {canAddMore && (
                <button
                  onClick={() => router.push('/seller/designs/featured')}
                  className="inline-flex items-center gap-1.5 px-3 sm:px-6 py-1.5 sm:py-2 bg-purple-600 text-white rounded-lg text-xs sm:text-sm font-medium hover:bg-purple-700 transition"
                >
                  Manage Featured Designs ΓåÆ
                </button>
              )}
              {!canAddMore && (
                <button
                  onClick={() => router.push('/seller/upgrade')}
                  className="inline-flex items-center gap-1.5 px-3 sm:px-6 py-1.5 sm:py-2 bg-gray-400 text-white rounded-lg text-xs sm:text-sm font-medium cursor-not-allowed opacity-60"
                  disabled
                >
                  <Lock className="h-3.5 w-3.5 sm:h-4 sm:w-4" />
                  Upgrade to Feature
                </button>
              )}
            </div>
          ) : (
            <div className="divide-y divide-gray-200">
              {designs.map((design) => (
                <div key={design.id} className="p-2 sm:p-3 md:p-4 hover:bg-gray-50 flex items-center justify-between gap-2 sm:gap-3">
                  <div className="flex items-center gap-2 sm:gap-3 flex-1 min-w-0">
                    {/* Position Badge */}
                    <div className="w-6 h-6 sm:w-7 sm:h-7 md:w-8 md:h-8 rounded-full bg-purple-100 text-purple-700 flex items-center justify-center font-semibold text-xs sm:text-sm flex-shrink-0">
                      {design.position}
                    </div>
                    {design.imageUrl ? (
                      <img
                        src={design.imageUrl}
                        alt={design.title}
                        className="h-8 w-8 sm:h-10 sm:w-10 md:h-12 md:w-12 rounded object-cover"
                      />
                    ) : (
                      <div className="h-8 w-8 sm:h-10 sm:w-10 md:h-12 md:w-12 rounded bg-gray-200 flex items-center justify-center flex-shrink-0">
                        <ImageIcon className="h-4 w-4 sm:h-5 sm:w-5 text-gray-400" />
                      </div>
                    )}
                    <div className="flex-1 min-w-0">
                      <div className="text-xs sm:text-sm font-medium text-gray-900 truncate">{design.title}</div>
                      <div className="text-xs text-gray-600">
                        {formatPrice(typeof design.price === 'number' ? design.price : 0)} ΓÇó {typeof design.totalSales === 'number' ? design.totalSales : 0} sales
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-0.5 sm:gap-1 flex-shrink-0">
                    {editingPositions[design.id] !== undefined ? (
                      <div className="flex items-center gap-0.5 sm:gap-1">
                        <input
                          type="number"
                          min="1"
                          max={maxFeatured}
                          placeholder="Pos"
                          aria-label="Edit position"
                          value={editingPositions[design.id]}
                          onChange={(e) => {
                            const val = parseInt(e.target.value, 10)
                            if (!isNaN(val)) {
                              setEditingPositions(prev => ({ ...prev, [design.id]: val }))
                            }
                          }}
                          className="w-10 px-1.5 py-0.5 border border-gray-300 rounded text-xs"
                        />
                        <button
                          onClick={() => handleUpdatePosition(design.id, 'DESIGN', editingPositions[design.id])}
                          disabled={updatingPositionId === design.id}
                          className="px-1.5 py-0.5 bg-blue-600 text-white rounded text-xs hover:bg-blue-700 disabled:opacity-50"
                        >
                          Save
                        </button>
                        <button
                          onClick={() => setEditingPositions(prev => { const newEditing = { ...prev }; delete newEditing[design.id]; return newEditing })}
                          className="px-1.5 py-0.5 bg-gray-300 text-gray-700 rounded text-xs hover:bg-gray-400"
                        >
                          Cancel
                        </button>
                      </div>
                    ) : (
                      <>
                        <button
                          onClick={() => setEditingPositions(prev => ({ ...prev, [design.id]: design.position }))}
                          className="p-1 hover:bg-gray-200 rounded text-gray-600 text-xs"
                          title="Edit position"
                        >
                          Reorder
                        </button>
                        <button
                          onClick={() => handleRemove(design.id, 'DESIGN')}
                          disabled={deletingId === design.id}
                          title="Remove from featured"
                          aria-label="Remove from featured"
                          className="p-1 hover:bg-red-50 rounded text-red-600 disabled:opacity-50"
                        >
                          <Trash2 className="h-3.5 w-3.5 sm:h-4 sm:w-4" />
                        </button>
                      </>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Featured Boutique Products */}
        <div className="bg-white rounded-lg shadow">
          <div className="px-3 sm:px-4 md:px-6 py-2.5 sm:py-3 md:py-4 border-b border-gray-200 flex items-center justify-between">
            <div>
              <h2 className="text-base sm:text-lg font-semibold text-gray-900 flex items-center gap-1.5 sm:gap-2">
                <ShoppingBag className="h-4 w-4 sm:h-5 sm:w-5 text-green-600" />
                Featured Products
              </h2>
              <p className="text-xs sm:text-sm text-gray-600 mt-0.5 sm:mt-1">{products.length} products featured</p>
            </div>
          </div>

          {products.length === 0 ? (
            <div className="p-4 sm:p-8 md:p-12 text-center">
              <ShoppingBag className="h-10 w-10 sm:h-12 sm:w-12 md:h-16 md:w-16 mx-auto mb-2 sm:mb-4 opacity-20" />
              <h3 className="text-sm sm:text-base md:text-lg font-semibold text-gray-900 mb-1.5 sm:mb-2">No Featured Products Yet</h3>
              <p className="text-xs sm:text-sm text-gray-600 mb-3 sm:mb-6">Start featuring your products to increase sales and visibility</p>
              {canAddMore && (
                <button
                  onClick={() => router.push('/seller/boutique/featured')}
                  className="inline-flex items-center gap-1.5 px-3 sm:px-6 py-1.5 sm:py-2 bg-green-600 text-white rounded-lg text-xs sm:text-sm font-medium hover:bg-green-700 transition"
                >
                  Manage Featured Products ΓåÆ
                </button>
              )}
              {!canAddMore && (
                <button
                  onClick={() => router.push('/seller/upgrade')}
                  className="inline-flex items-center gap-1.5 px-3 sm:px-6 py-1.5 sm:py-2 bg-gray-400 text-white rounded-lg text-xs sm:text-sm font-medium cursor-not-allowed opacity-60"
                  disabled
                >
                  <Lock className="h-3.5 w-3.5 sm:h-4 sm:w-4" />
                  Upgrade to Feature
                </button>
              )}
            </div>
          ) : (
            <div className="divide-y divide-gray-200">
              {products.map((product) => (
                <div key={product.id} className="p-2 sm:p-3 md:p-4 hover:bg-gray-50 flex items-center justify-between gap-2 sm:gap-3">
                  <div className="flex items-center gap-2 sm:gap-3 flex-1 min-w-0">
                    {/* Position Badge */}
                    <div className="w-6 h-6 sm:w-7 sm:h-7 md:w-8 md:h-8 rounded-full bg-green-100 text-green-700 flex items-center justify-center font-semibold text-xs sm:text-sm flex-shrink-0">
                      {product.position}
                    </div>
                    {product.imageUrl ? (
                      <img
                        src={product.imageUrl}
                        alt={product.title}
                        className="h-8 w-8 sm:h-10 sm:w-10 md:h-12 md:w-12 rounded object-cover"
                      />
                    ) : (
                      <div className="h-8 w-8 sm:h-10 sm:w-10 md:h-12 md:w-12 rounded bg-gray-200 flex items-center justify-center flex-shrink-0">
                        <ShoppingBag className="h-4 w-4 sm:h-5 sm:w-5 text-gray-400" />
                      </div>
                    )}
                    <div className="flex-1 min-w-0">
                      <div className="text-xs sm:text-sm font-medium text-gray-900 truncate">{product.title}</div>
                      <div className="text-xs text-gray-600 flex items-center gap-0.5">
                        <DollarSign className="h-2.5 w-2.5 sm:h-3 sm:w-3" />
                        {(typeof product.price === 'number' ? product.price : 0).toFixed(2)}
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-0.5 sm:gap-1 flex-shrink-0">
                    {editingPositions[product.id] !== undefined ? (
                      <div className="flex items-center gap-0.5 sm:gap-1">
                        <input
                          type="number"
                          min="1"
                          max={maxFeatured}
                          placeholder="Pos"
                          aria-label="Edit position"
                          value={editingPositions[product.id]}
                          onChange={(e) => {
                            const val = parseInt(e.target.value, 10)
                            if (!isNaN(val)) {
                              setEditingPositions(prev => ({ ...prev, [product.id]: val }))
                            }
                          }}
                          className="w-10 px-1.5 py-0.5 border border-gray-300 rounded text-xs"
                        />
                        <button
                          onClick={() => handleUpdatePosition(product.id, 'BOUTIQUE_PRODUCT', editingPositions[product.id])}
                          disabled={updatingPositionId === product.id}
                          className="px-1.5 py-0.5 bg-blue-600 text-white rounded text-xs hover:bg-blue-700 disabled:opacity-50"
                        >
                          Save
                        </button>
                        <button
                          onClick={() => setEditingPositions(prev => { const newEditing = { ...prev }; delete newEditing[product.id]; return newEditing })}
                          className="px-1.5 py-0.5 bg-gray-300 text-gray-700 rounded text-xs hover:bg-gray-400"
                        >
                          Cancel
                        </button>
                      </div>
                    ) : (
                      <>
                        <button
                          onClick={() => setEditingPositions(prev => ({ ...prev, [product.id]: product.position }))}
                          className="p-1 hover:bg-gray-200 rounded text-gray-600 text-xs"
                          title="Edit position"
                        >
                          Reorder
                        </button>
                        <button
                          onClick={() => handleRemove(product.id, 'BOUTIQUE_PRODUCT')}
                          disabled={deletingId === product.id}
                          title="Remove from featured"
                          aria-label="Remove from featured"
                          className="p-1 hover:bg-red-50 rounded text-red-600 disabled:opacity-50"
                        >
                          <Trash2 className="h-3.5 w-3.5 sm:h-4 sm:w-4" />
                        </button>
                      </>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Tier Comparison */}
        {maxFeatured > 0 && (
          <div className="mt-4 sm:mt-6 md:mt-8 bg-gradient-to-r from-purple-50 to-blue-50 rounded-lg p-3 sm:p-4 md:p-6 border border-purple-200">
            <h3 className="text-sm sm:text-base font-semibold text-gray-900 mb-2.5 sm:mb-4">Featured Items Limit by Plan</h3>
            <div className="grid grid-cols-3 gap-2 sm:gap-3 md:gap-4">
              <div className="bg-white rounded p-2 sm:p-3">
                <div className="text-xs sm:text-sm font-medium text-gray-700">Starter</div>
                <div className="text-lg sm:text-xl md:text-2xl font-bold text-gray-900 mt-0.5 sm:mt-1">0</div>
                <div className="text-xs text-gray-600 mt-0.5 sm:mt-1">items</div>
              </div>
              <div className="bg-white rounded p-2 sm:p-3 border-2 border-purple-600">
                <div className="text-xs sm:text-sm font-medium text-gray-700">Pro</div>
                <div className="text-lg sm:text-xl md:text-2xl font-bold text-purple-600 mt-0.5 sm:mt-1">6</div>
                <div className="text-xs text-gray-600 mt-0.5 sm:mt-1">items</div>
              </div>
              <div className="bg-white rounded p-2 sm:p-3">
                <div className="text-xs sm:text-sm font-medium text-gray-700">VIP</div>
                <div className="text-lg sm:text-xl md:text-2xl font-bold text-amber-600 mt-0.5 sm:mt-1">10</div>
                <div className="text-xs text-gray-600 mt-0.5 sm:mt-1">items</div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { useCurrency } from '@/components/CurrencyProvider'
import {
  Tag,
  Plus,
  Loader2,
  ArrowLeft,
  Calendar,
  Percent,
  DollarSign,
  Package,
  Trash2,
  Eye,
  EyeOff,
  Clock,
  CheckCircle,
  XCircle,
  AlertCircle,
} from 'lucide-react'

interface Promotion {
  id: string
  type: 'DISCOUNT' | 'BUNDLE' | 'FLASH_SALE'
  name: string
  description: string | null
  discountType: 'PERCENTAGE' | 'FIXED'
  discountValue: number
  bundlePrice: number | null
  designIds: string[]
  productIds?: string[]
  startDate: string
  endDate: string
  maxUsage: number | null
  usageCount: number
  isActive: boolean
  createdAt: string
  designs?: Array<{ id: string; title: string; thumbnailUrl?: string; price: number }>
  products?: Array<{ id: string; title: string; thumbnailUrl?: string; basePrice: number }>
}

export default function SellerPromotionsPage() {
  const { data: session, status: authStatus } = useSession()
  const router = useRouter()
  const { formatPrice } = useCurrency()
  const [loading, setLoading] = useState(true)
  const [promotions, setPromotions] = useState<Promotion[]>([])
  const [designs, setDesigns] = useState<any[]>([])
  const [filter, setFilter] = useState<'all' | 'active' | 'expired'>('all')
  const [showCreateModal, setShowCreateModal] = useState(false)
  const [creating, setCreating] = useState(false)
  const [expandedPromotionId, setExpandedPromotionId] = useState<string | null>(null)
  const [error, setError] = useState('')
  const [success, setSuccess] = useState('')
  const [promotedDesignIds, setPromotedDesignIds] = useState<string[]>([])
  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null)
  const [designPromotionMap, setDesignPromotionMap] = useState<Record<string, {
    promotionId: string
    promotionName: string
    promotionType: string
  }> | null>(null)
  const [conflictingPromotions, setConflictingPromotions] = useState<Array<{
    id: string
    name: string
    type: string
  }> | null>(null)

  const [newPromotion, setNewPromotion] = useState<{
    type: 'DISCOUNT' | 'BUNDLE' | 'FLASH_SALE'
    name: string
    description: string
    discountType: 'PERCENTAGE' | 'FIXED'
    discountValue: number
    bundlePrice: number | null
    designIds: string[]
    productIds: string[]
    startDate: string
    endDate: string
    maxUsage: number | null
  }>({
    type: 'DISCOUNT',
    name: '',
    description: '',
    discountType: 'PERCENTAGE',
    discountValue: 10,
    bundlePrice: null,
    designIds: [],
    productIds: [],
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    maxUsage: null as number | null,
  })

  const [itemType, setItemType] = useState<'designs' | 'products'>('designs')

  useEffect(() => {
    if (authStatus === 'loading') return
    if (!session) {
      router.push('/auth/signin')
      return
    }
    fetchPromotions()
    fetchDesigns()
  }, [session, authStatus, router, filter])

  const fetchDesigns = async () => {
    try {
      const response = await fetch('/api/seller/designs')
      if (response.ok) {
        const data = await response.json()
        setDesigns(data.designs || [])
      }
    } catch (error) {
      console.error('Failed to fetch designs:', error)
    }

    // Fetch designs that already have active promotions
    try {
      const response = await fetch('/api/seller/promotions/active-designs')
      if (response.ok) {
        const data = await response.json()
        setDesignPromotionMap(data.designPromos || {})
        setPromotedDesignIds(Object.keys(data.designPromos || {}))
      }
    } catch (error) {
      console.error('Failed to fetch promoted designs:', error)
    }
  }

  const fetchPromotions = async () => {
    setLoading(true)
    try {
      const response = await fetch(`/api/seller/promotions?status=${filter}`)
      if (response.ok) {
        const data = await response.json()
        setPromotions(data.promotions || [])
      }
    } catch (error) {
      console.error('Failed to fetch promotions:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleCreatePromotion = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')

    // Client-side validation
    if (!newPromotion.name.trim()) {
      setError('Promotion name is required')
      return
    }

    if (newPromotion.discountValue <= 0) {
      setError('Discount value must be greater than 0')
      return
    }

    if (newPromotion.discountType === 'PERCENTAGE' && newPromotion.discountValue > 100) {
      setError('Percentage discount cannot exceed 100%')
      return
    }

    if (newPromotion.type === 'BUNDLE') {
      const hasItems = (itemType === 'designs' && newPromotion.designIds.length > 0) ||
                       (itemType === 'products' && newPromotion.productIds.length > 0);
      if (!hasItems) {
        const itemName = itemType === 'designs' ? 'design' : 'product';
        setError(`Bundle promotion must include at least one ${itemName}`)
        return
      }

      if (!newPromotion.bundlePrice || newPromotion.bundlePrice <= 0) {
        setError('Bundle price must be greater than 0')
        return
      }
    }

    const startDate = new Date(newPromotion.startDate)
    const endDate = new Date(newPromotion.endDate)

    if (endDate <= startDate) {
      setError('End date must be after start date')
      return
    }

    if (newPromotion.maxUsage !== null && newPromotion.maxUsage < 1) {
      setError('Maximum usage must be at least 1')
      return
    }

    setCreating(true)

    try {
      const response = await fetch('/api/seller/promotions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newPromotion),
      })

      if (response.ok) {
        setSuccess('Promotion created successfully!')
        setShowCreateModal(false)
        setItemType('designs')
        setNewPromotion({
          type: 'DISCOUNT',
          name: '',
          description: '',
          discountType: 'PERCENTAGE',
          discountValue: 10,
          bundlePrice: null,
          designIds: [],
          productIds: [],
          startDate: new Date().toISOString().split('T')[0],
          endDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
          maxUsage: null,
        })
        fetchPromotions()
        setTimeout(() => setSuccess(''), 3000)
      } else {
        const data = await response.json()
        
        // Format conflict error with details
        if (response.status === 409 && data.conflictingDesigns) {
          setConflictingPromotions(data.existingPromotions || [])
          const conflictDetails = Object.entries(data.conflictingDesigns)
            .map(([_, promo]) => `ΓÇó ${promo}`)
            .join('\n')
          setError(`${data.error}\n\n${conflictDetails}`)
        } else {
          setConflictingPromotions(null)
          setError(data.error || 'Failed to create promotion')
        }
      }
    } catch (error) {
      console.error('Failed to create promotion:', error)
      setError('An error occurred')
    } finally {
      setCreating(false)
    }
  }

  const handleToggleActive = async (promotionId: string, isActive: boolean) => {
    try {
      const response = await fetch(`/api/seller/promotions/${promotionId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ isActive: !isActive }),
      })

      if (response.ok) {
        fetchPromotions()
      }
    } catch (error) {
      console.error('Failed to toggle promotion:', error)
    }
  }

  const handleDeletePromotion = async (promotionId: string) => {
    try {
      const response = await fetch(`/api/seller/promotions/${promotionId}`, {
        method: 'DELETE',
      })

      if (response.ok) {
        setSuccess('Promotion deleted')
        setDeleteConfirmId(null)
        fetchPromotions()
        setTimeout(() => setSuccess(''), 3000)
      }
    } catch (error) {
      console.error('Failed to delete promotion:', error)
    }
  }

  const getStatusBadge = (promotion: Promotion) => {
    const now = new Date()
    const endDate = new Date(promotion.endDate)
    const startDate = new Date(promotion.startDate)

    if (!promotion.isActive) {
      return (
        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-gray-100 text-gray-700">
          <EyeOff className="w-3 h-3 mr-1" />
          Inactive
        </span>
      )
    }

    if (now < startDate) {
      return (
        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-blue-100 text-blue-700">
          <Clock className="w-3 h-3 mr-1" />
          Scheduled
        </span>
      )
    }

    if (now > endDate) {
      return (
        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-red-100 text-red-700">
          <XCircle className="w-3 h-3 mr-1" />
          Expired
        </span>
      )
    }

    return (
      <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-700">
        <CheckCircle className="w-3 h-3 mr-1" />
        Active
      </span>
    )
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    })
  }

  if (authStatus === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-indigo-600" />
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-6xl mx-auto px-3 sm:px-6 lg:px-8 py-3 sm:py-4 md:py-8">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 sm:gap-4 mb-4 sm:mb-6 md:mb-8">
          <div>
            <Link
              href="/seller/dashboard"
              className="inline-flex items-center text-xs sm:text-sm text-gray-500 hover:text-gray-700 mb-1 sm:mb-2"
            >
              <ArrowLeft className="w-3 h-3 sm:w-4 sm:h-4 mr-1" />
              Back to Dashboard
            </Link>
            <h1 className="text-lg sm:text-xl md:text-2xl font-bold text-gray-900">Promotions</h1>
            <p className="text-xs sm:text-sm text-gray-600 mt-0.5 sm:mt-1">Create and manage discounts for your designs</p>
          </div>
          <button
            onClick={() => setShowCreateModal(true)}
            className="inline-flex items-center gap-1 sm:gap-2 px-3 sm:px-4 py-1.5 sm:py-2 text-xs sm:text-sm bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
          >
            <Plus className="w-3 h-3 sm:w-4 sm:h-4" />
            Create Promotion
          </button>
        </div>

        {/* Messages */}
        {success && (
          <div className="mb-3 sm:mb-4 md:mb-6 p-2 sm:p-3 md:p-4 bg-green-50 border border-green-200 rounded-lg flex items-center gap-2 text-xs sm:text-sm text-green-700">
            <CheckCircle className="w-4 h-4 sm:w-5 sm:h-5 flex-shrink-0" />
            {success}
          </div>
        )}

        {error && (
          <div className="mb-3 sm:mb-4 md:mb-6 p-2 sm:p-3 md:p-4 bg-red-50 border border-red-200 rounded-lg text-xs sm:text-sm text-red-700">
            <div className="flex gap-2">
              <AlertCircle className="w-4 h-4 sm:w-5 sm:h-5 flex-shrink-0 mt-0.5" />
              <div className="flex-1">
                <p className="font-medium whitespace-pre-wrap">{error}</p>
                {conflictingPromotions && conflictingPromotions.length > 0 && (
                  <div className="mt-3 space-y-2">
                    <p className="font-medium text-red-800">To resolve this, deactivate:</p>
                    {conflictingPromotions.map(promo => (
                      <button
                        key={promo.id}
                        onClick={() => {
                          setError('')
                          setConflictingPromotions(null)
                          // Scroll to the promotion in the list
                          const element = document.getElementById(`promotion-${promo.id}`)
                          if (element) {
                            element.scrollIntoView({ behavior: 'smooth', block: 'center' })
                            element.classList.add('ring-2', 'ring-yellow-400')
                            setTimeout(() => element.classList.remove('ring-2', 'ring-yellow-400'), 2000)
                          }
                        }}
                        className="block w-full text-left px-2 py-1 bg-red-100 hover:bg-red-200 rounded transition-colors font-medium"
                      >
                        ΓåÆ {promo.name} ({promo.type})
                      </button>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {/* Stats Summary */}
        {promotions.length > 0 && (
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-4 mb-4 sm:mb-6">
            <div className="bg-white rounded-lg p-3 sm:p-4 text-center">
              <p className="text-2xl sm:text-3xl font-bold text-gray-900">{promotions.length}</p>
              <p className="text-xs sm:text-sm text-gray-600 mt-1">Total Promotions</p>
            </div>
            <div className="bg-white rounded-lg p-3 sm:p-4 text-center">
              <p className="text-2xl sm:text-3xl font-bold text-green-600">{promotions.filter(p => p.isActive && new Date(p.endDate) > new Date()).length}</p>
              <p className="text-xs sm:text-sm text-gray-600 mt-1">Active Now</p>
            </div>
            <div className="bg-white rounded-lg p-3 sm:p-4 text-center">
              <p className="text-2xl sm:text-3xl font-bold text-orange-600">{promotions.filter(p => new Date(p.startDate) > new Date()).length}</p>
              <p className="text-xs sm:text-sm text-gray-600 mt-1">Scheduled</p>
            </div>
            <div className="bg-white rounded-lg p-3 sm:p-4 text-center">
              <p className="text-2xl sm:text-3xl font-bold text-gray-400">{promotions.filter(p => new Date(p.endDate) <= new Date()).length}</p>
              <p className="text-xs sm:text-sm text-gray-600 mt-1">Expired</p>
            </div>
          </div>
        )}

        {/* Filter Tabs */}
        <div className="flex gap-1 sm:gap-2 mb-4 sm:mb-5 md:mb-6">
          {(['all', 'active', 'expired'] as const).map((status) => (
            <button
              key={status}
              onClick={() => setFilter(status)}
              className={`px-2 sm:px-4 py-1 sm:py-2 rounded-lg text-xs sm:text-sm font-medium transition-colors ${
                filter === status
                  ? 'bg-indigo-600 text-white'
                  : 'bg-white text-gray-700 hover:bg-gray-50 border border-gray-200'
              }`}
            >
              {status.charAt(0).toUpperCase() + status.slice(1)}
            </button>
          ))}
        </div>

        {/* Promotions List */}
        {promotions.length === 0 ? (
          <div className="bg-white rounded-xl shadow-sm p-6 sm:p-8 md:p-12 text-center">
            <Tag className="w-10 h-10 sm:w-12 sm:h-12 md:w-16 md:h-16 text-gray-300 mx-auto mb-2 sm:mb-3 md:mb-4" />
            <h3 className="text-base sm:text-lg font-medium text-gray-900 mb-1 sm:mb-2">No Promotions Yet</h3>
            <p className="text-xs sm:text-sm text-gray-500 mb-3 sm:mb-4 md:mb-6">
              Create your first promotion to attract more buyers
            </p>
            <button
              onClick={() => setShowCreateModal(true)}
              className="inline-flex items-center gap-1 sm:gap-2 px-3 sm:px-4 py-1.5 sm:py-2 text-xs sm:text-sm bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
            >
              <Plus className="w-3 h-3 sm:w-4 sm:h-4" />
              Create Promotion
            </button>
          </div>
        ) : (
          <div className="grid gap-3 sm:gap-4">
            {promotions.map((promotion) => (
              <div
                id={`promotion-${promotion.id}`}
                key={promotion.id}
                className="bg-white rounded-xl shadow-sm p-3 sm:p-4 md:p-6 hover:shadow-md transition-shadow"
              >
                <div className="flex items-start justify-between gap-2">
                  <div className="flex items-start gap-2 sm:gap-3 md:gap-4 min-w-0">
                    <div className={`w-10 h-10 sm:w-12 sm:h-12 rounded-lg flex items-center justify-center flex-shrink-0 ${
                      promotion.type === 'DISCOUNT'
                        ? 'bg-green-100'
                        : promotion.type === 'BUNDLE'
                        ? 'bg-purple-100'
                        : 'bg-orange-100'
                    }`}>
                      {promotion.type === 'DISCOUNT' ? (
                        <Percent className={`w-5 h-5 sm:w-6 sm:h-6 ${
                          promotion.type === 'DISCOUNT' ? 'text-green-600' : ''
                        }`} />
                      ) : promotion.type === 'BUNDLE' ? (
                        <Package className="w-5 h-5 sm:w-6 sm:h-6 text-purple-600" />
                      ) : (
                        <Clock className="w-5 h-5 sm:w-6 sm:h-6 text-orange-600" />
                      )}
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2 flex-wrap">
                        <h3 className="font-semibold text-xs sm:text-sm md:text-base text-gray-900">{promotion.name}</h3>
                        <div className="flex-shrink-0">{getStatusBadge(promotion)}</div>
                      </div>
                      {promotion.description && (
                        <p className="text-xs sm:text-sm text-gray-500 mt-0.5 sm:mt-1 line-clamp-1">{promotion.description}</p>
                      )}
                      <div className="flex items-center gap-2 sm:gap-3 md:gap-4 mt-1 sm:mt-2 text-xs sm:text-sm text-gray-600 flex-wrap">
                        <span className="flex items-center gap-1 flex-shrink-0">
                          {promotion.discountType === 'PERCENTAGE' ? (
                            <Percent className="w-3 h-3 sm:w-4 sm:h-4" />
                          ) : (
                            <DollarSign className="w-3 h-3 sm:w-4 sm:h-4" />
                          )}
                          {promotion.discountType === 'PERCENTAGE'
                            ? `${promotion.discountValue}% off`
                            : `$${promotion.discountValue} off`}
                        </span>
                        <span className="flex items-center gap-1 flex-shrink-0">
                          <Calendar className="w-3 h-3 sm:w-4 sm:h-4" />
                          <span className="hidden sm:inline">{formatDate(promotion.startDate)} - {formatDate(promotion.endDate)}</span>
                          <span className="sm:hidden text-xs">{new Date(promotion.startDate).toLocaleDateString('en-US', {month:'short', day:'numeric'})}</span>
                        </span>
                        {promotion.maxUsage && (
                          <span className="text-xs">
                            {promotion.usageCount}/{promotion.maxUsage} used
                          </span>
                        )}
                      </div>
                      {(promotion.type === 'BUNDLE' || promotion.type === 'FLASH_SALE' || promotion.type === 'DISCOUNT') && promotion.designIds.length > 0 && (
                        <button
                          onClick={() => setExpandedPromotionId(expandedPromotionId === promotion.id ? null : promotion.id)}
                          className="text-xs sm:text-sm text-indigo-600 hover:text-indigo-700 font-medium mt-2 transition-colors"
                        >
                          {expandedPromotionId === promotion.id
                            ? 'Γû╝ Hide designs'
                            : `Γû╢ View ${promotion.designIds.length} design${promotion.designIds.length !== 1 ? 's' : ''}`}
                        </button>
                      )}
                      {promotion.type === 'DISCOUNT' && promotion.designIds.length === 0 && (
                        <p className="text-xs text-gray-500 mt-2">Applies to all designs</p>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-1 flex-shrink-0">
                    <button
                      onClick={() => handleToggleActive(promotion.id, promotion.isActive)}
                      className={`p-1 sm:p-2 rounded-lg transition-colors ${
                        promotion.isActive
                          ? 'text-green-600 hover:bg-green-50'
                          : 'text-gray-400 hover:bg-gray-50'
                      }`}
                      title={promotion.isActive ? 'Deactivate' : 'Activate'}
                    >
                      {promotion.isActive ? <Eye className="w-4 h-4 sm:w-5 sm:h-5" /> : <EyeOff className="w-4 h-4 sm:w-5 sm:h-5" />}
                    </button>
                    <button
                      onClick={() => setDeleteConfirmId(promotion.id)}
                      className="p-1 sm:p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                      title="Delete"
                    >
                      <Trash2 className="w-4 h-4 sm:w-5 sm:h-5" />
                    </button>
                  </div>
                </div>
                {expandedPromotionId === promotion.id && (promotion.type === 'BUNDLE' || promotion.type === 'FLASH_SALE' || promotion.type === 'DISCOUNT') && (
                  <div className="mt-4 pt-4 border-t border-gray-200">
                    {promotion.designIds && promotion.designIds.length > 0 && (
                      <div>
                        <p className="text-xs sm:text-sm font-medium text-gray-700 mb-3">Designs included in this promotion:</p>
                        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2 sm:gap-3">
                          {(promotion.designs || [])
                            .map(design => (
                              <Link
                                key={design.id}
                                href={`/seller/designs/${design.id}`}
                                className="group relative bg-gray-100 rounded-lg overflow-hidden hover:shadow-md transition-shadow cursor-pointer"
                              >
                                <div className="aspect-square bg-gray-200 flex items-center justify-center overflow-hidden relative">
                                  {design.thumbnailUrl ? (
                                    <img
                                      src={design.thumbnailUrl}
                                      alt={design.title}
                                      className="w-full h-full object-cover group-hover:scale-105 transition-transform"
                                    />
                                  ) : (
                                    <div className="flex items-center justify-center w-full h-full text-gray-400 text-xs text-center px-2">
                                      No image
                                    </div>
                                  )}
                                  <div className="absolute inset-0 bg-black/0 group-hover:bg-black/30 transition-colors flex items-center justify-center">
                                    <span className="text-white text-xs font-medium opacity-0 group-hover:opacity-100 transition-opacity">View Design</span>
                                  </div>
                                </div>
                                <p className="text-xs sm:text-sm font-medium text-gray-900 mt-1 line-clamp-2">{design.title}</p>
                                <p className="text-xs text-gray-500">{formatPrice(design.price)}</p>
                              </Link>
                            ))}
                        </div>
                      </div>
                    )}
                    {promotion.productIds && promotion.productIds.length > 0 && (
                      <div>
                        <p className="text-xs sm:text-sm font-medium text-gray-700 mb-3">Products included in this promotion:</p>
                        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2 sm:gap-3">
                          {(promotion.products || [])
                            .map(product => (
                              <Link
                                key={product.id}
                                href={`/seller/boutique/${product.id}`}
                                className="group relative bg-gray-100 rounded-lg overflow-hidden hover:shadow-md transition-shadow cursor-pointer"
                              >
                                <div className="aspect-square bg-gray-200 flex items-center justify-center overflow-hidden relative">
                                  {product.thumbnailUrl ? (
                                    <img
                                      src={product.thumbnailUrl}
                                      alt={product.title}
                                      className="w-full h-full object-cover group-hover:scale-105 transition-transform"
                                    />
                                  ) : (
                                    <div className="flex items-center justify-center w-full h-full text-gray-400 text-xs text-center px-2">
                                      No image
                                    </div>
                                  )}
                                  <div className="absolute inset-0 bg-black/0 group-hover:bg-black/30 transition-colors flex items-center justify-center">
                                    <span className="text-white text-xs font-medium opacity-0 group-hover:opacity-100 transition-opacity">View Product</span>
                                  </div>
                                </div>
                                <p className="text-xs sm:text-sm font-medium text-gray-900 mt-1 line-clamp-2">{product.title}</p>
                                <p className="text-xs text-gray-500">{formatPrice(product.basePrice)}</p>
                              </Link>
                            ))}
                        </div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}

        {/* Create Modal */}
        {showCreateModal && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-3 sm:p-4">
            <div className="bg-white rounded-xl max-w-lg w-full max-h-[90vh] overflow-y-auto">
              <div className="p-3 sm:p-4 md:p-6 border-b border-gray-200">
                <h2 className="text-lg sm:text-xl font-semibold text-gray-900">Create Promotion</h2>
              </div>
              <form onSubmit={handleCreatePromotion} className="p-3 sm:p-4 md:p-6 space-y-3 sm:space-y-4">
                <div>
                  <label htmlFor="promotionType" className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">
                    Promotion Type
                  </label>
                  <select
                    id="promotionType"
                    value={newPromotion.type}
                    onChange={(e) =>
                      setNewPromotion({ ...newPromotion, type: e.target.value as 'DISCOUNT' | 'BUNDLE' | 'FLASH_SALE' })
                    }
                    className="w-full px-2 sm:px-3 py-1 sm:py-2 text-xs sm:text-sm text-black border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
                  >
                    <option value="DISCOUNT">Discount</option>
                    <option value="BUNDLE">Bundle</option>
                    <option value="FLASH_SALE">Flash Sale</option>
                  </select>
                </div>

                <div>
                  <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-2">Apply To *</label>
                  <div className="flex gap-3">
                    <label className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="radio"
                        checked={itemType === 'designs'}
                        onChange={() => {
                          setItemType('designs')
                          setNewPromotion({ ...newPromotion, designIds: [], productIds: [] })
                        }}
                        className="w-4 h-4 text-indigo-600"
                      />
                      <span className="text-xs sm:text-sm text-gray-700">Designs</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="radio"
                        checked={itemType === 'products'}
                        onChange={() => {
                          setItemType('products')
                          setNewPromotion({ ...newPromotion, designIds: [], productIds: [] })
                        }}
                        className="w-4 h-4 text-indigo-600"
                      />
                      <span className="text-xs sm:text-sm text-gray-700">Boutique Products</span>
                    </label>
                  </div>
                </div>

                <div>
                  <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">Name *</label>
                  <input
                    type="text"
                    value={newPromotion.name}
                    onChange={(e) => setNewPromotion({ ...newPromotion, name: e.target.value })}
                    required
                    className="w-full px-2 sm:px-3 py-1 sm:py-2 text-xs sm:text-sm text-black border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
                    placeholder="Summer Sale"
                  />
                </div>

                {itemType === 'designs' && (newPromotion.type === 'BUNDLE' || newPromotion.type === 'DISCOUNT' || newPromotion.type === 'FLASH_SALE') && (
                  <div>
                    <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">
                      Select Designs {newPromotion.type === 'BUNDLE' ? '*' : '(Optional - leave empty to apply to all)'}
                    </label>
                    {promotedDesignIds.length > 0 && (
                      <p className="text-xs text-amber-600 mb-2 p-2 bg-amber-50 rounded">
                        Γä╣∩╕Å Some designs already have active promotions and cannot be added
                      </p>
                    )}
                    <div className="max-h-40 overflow-y-auto border border-gray-300 rounded-lg p-2">
                      {designs.length === 0 ? (
                        <p className="text-xs text-gray-500">No designs available</p>
                      ) : (
                        designs.map((design) => {
                          const isPromoted = promotedDesignIds.includes(design.id)
                          const promotionInfo = isPromoted ? designPromotionMap?.[design.id] : null
                          return (
                            <label 
                              key={design.id} 
                              className={`flex items-center gap-2 py-1 text-xs sm:text-sm cursor-pointer hover:bg-gray-50 ${
                                isPromoted ? 'opacity-50 cursor-not-allowed' : ''
                              }`}
                              title={promotionInfo ? `Promotion: ${promotionInfo.promotionName}` : ''}
                            >
                              <input
                                type="checkbox"
                                checked={newPromotion.designIds.includes(design.id)}
                                disabled={isPromoted}
                                onChange={(e) => {
                                  if (e.target.checked) {
                                    setNewPromotion({
                                      ...newPromotion,
                                      designIds: [...newPromotion.designIds, design.id],
                                    })
                                  } else {
                                    setNewPromotion({
                                      ...newPromotion,
                                      designIds: newPromotion.designIds.filter((id) => id !== design.id),
                                    })
                                  }
                                }}
                                className="w-4 h-4 rounded border-gray-300 text-indigo-600 disabled:opacity-50"
                              />
                              <div className="flex-1">
                                <span className={`${isPromoted ? 'text-gray-500' : 'text-gray-700'}`}>
                                  {design.title}
                                </span>
                                {isPromoted && promotionInfo && (
                                  <div className="text-xs text-amber-600 font-medium ml-1">
                                    {promotionInfo.promotionName} ({promotionInfo.promotionType})
                                  </div>
                                )}
                              </div>
                            </label>
                          )
                        })
                      )}
                    </div>
                  </div>
                )}

                {itemType === 'products' && (newPromotion.type === 'BUNDLE' || newPromotion.type === 'DISCOUNT' || newPromotion.type === 'FLASH_SALE') && (
                  <div>
                    <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">
                      Select Boutique Products {newPromotion.type === 'BUNDLE' ? '*' : '(Optional - leave empty to apply to all)'}
                    </label>
                    <p className="text-xs text-blue-600 mb-2 p-2 bg-blue-50 rounded">
                      Γä╣∩╕Å Products will be fetched from your available boutique inventory
                    </p>
                    <div className="max-h-40 overflow-y-auto border border-gray-300 rounded-lg p-2 text-gray-500 text-xs">
                      <p>Products list will be populated when you save the promotion</p>
                      <p className="mt-2">For now, enter product IDs directly or manage them after creation.</p>
                    </div>
                  </div>
                )}

                <div>
                  <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">Description</label>
                  <textarea
                    value={newPromotion.description}
                    onChange={(e) => setNewPromotion({ ...newPromotion, description: e.target.value })}
                    rows={2}
                    className="w-full px-2 sm:px-3 py-1 sm:py-2 text-xs sm:text-sm text-black border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
                    placeholder="Optional description"
                  />
                </div>

                <div className="grid grid-cols-2 gap-2 sm:gap-4">
                  <div>
                    <label htmlFor="discountType" className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">
                      Discount Type
                    </label>
                    <select
                      id="discountType"
                      value={newPromotion.discountType}
                      onChange={(e) =>
                        setNewPromotion({
                          ...newPromotion,
                          discountType: e.target.value as 'PERCENTAGE' | 'FIXED',
                        })
                      }
                      className="w-full px-2 sm:px-3 py-1 sm:py-2 text-xs sm:text-sm text-black border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
                    >
                      <option value="PERCENTAGE">Percentage</option>
                      <option value="FIXED">Fixed Amount</option>
                    </select>
                  </div>
                  <div>
                    <label htmlFor="discountValue" className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">
                      {newPromotion.discountType === 'PERCENTAGE' ? 'Discount %' : 'Discount $'}
                    </label>
                    <input
                      id="discountValue"
                      type="number"
                      min="1"
                      max={newPromotion.discountType === 'PERCENTAGE' ? 100 : undefined}
                      value={newPromotion.discountValue}
                      onChange={(e) =>
                        setNewPromotion({ ...newPromotion, discountValue: parseInt(e.target.value) || 0 })
                      }
                      required
                      className="w-full px-2 sm:px-3 py-1 sm:py-2 text-xs sm:text-sm text-black border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
                    />
                  </div>
                </div>

                {newPromotion.type === 'BUNDLE' && (
                  <div>
                    <label htmlFor="bundlePrice" className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">
                      Bundle Price ($) *
                    </label>
                    <input
                      id="bundlePrice"
                      type="number"
                      min="0"
                      step="0.01"
                      value={newPromotion.bundlePrice || 0}
                      onChange={(e) =>
                        setNewPromotion({
                          ...newPromotion,
                          bundlePrice: e.target.value ? parseFloat(e.target.value) : 0,
                        })
                      }
                      required={newPromotion.type === 'BUNDLE'}
                      className="w-full px-2 sm:px-3 py-1 sm:py-2 text-xs sm:text-sm text-black border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
                      placeholder="29.99"
                    />
                  </div>
                )}

                <div className="grid grid-cols-2 gap-2 sm:gap-4">
                  <div>
                    <label htmlFor="startDate" className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">Start Date</label>
                    <input
                      id="startDate"
                      type="date"
                      value={newPromotion.startDate}
                      onChange={(e) => setNewPromotion({ ...newPromotion, startDate: e.target.value })}
                      required
                      className="w-full px-2 sm:px-3 py-1 sm:py-2 text-xs sm:text-sm text-black border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
                    />
                  </div>
                  <div>
                    <label htmlFor="endDate" className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">End Date</label>
                    <input
                      id="endDate"
                      type="date"
                      value={newPromotion.endDate}
                      onChange={(e) => setNewPromotion({ ...newPromotion, endDate: e.target.value })}
                      required
                      className="w-full px-2 sm:px-3 py-1 sm:py-2 text-xs sm:text-sm text-black border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
                    />
                  </div>
                </div>

                <div>
                  <label htmlFor="maxUsage" className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">
                    Max Usage (Optional)
                  </label>
                  <input
                    id="maxUsage"
                    type="number"
                    min="1"
                    value={newPromotion.maxUsage || ''}
                    onChange={(e) =>
                      setNewPromotion({
                        ...newPromotion,
                        maxUsage: e.target.value ? parseInt(e.target.value) : null,
                      })
                    }
                    className="w-full px-2 sm:px-3 py-1 sm:py-2 text-xs sm:text-sm text-black border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
                    placeholder="Unlimited"
                  />
                </div>

                <div className="flex justify-end gap-2 sm:gap-3 pt-3 sm:pt-4">
                  <button
                    type="button"
                    onClick={() => setShowCreateModal(false)}
                    className="px-3 sm:px-4 py-1 sm:py-2 text-xs sm:text-sm text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    disabled={creating}
                    className="inline-flex items-center gap-1 sm:gap-2 px-3 sm:px-4 py-1 sm:py-2 text-xs sm:text-sm bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50"
                  >
                    {creating ? (
                      <>
                        <Loader2 className="w-3 h-3 sm:w-4 sm:h-4 animate-spin" />
                        <span className="hidden sm:inline">Creating...</span>
                        <span className="sm:hidden">...</span>
                      </>
                    ) : (
                      <>
                        <Plus className="w-3 h-3 sm:w-4 sm:h-4" />
                        <span className="hidden sm:inline">Create Promotion</span>
                        <span className="sm:hidden">Create</span>
                      </>
                    )}
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* Delete Confirmation Modal */}
        {deleteConfirmId && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-3 sm:p-4">
            <div className="bg-white rounded-xl max-w-sm w-full">
              <div className="p-4 sm:p-6 border-b border-gray-200">
                <h3 className="text-lg sm:text-xl font-semibold text-gray-900 flex items-center gap-2">
                  <AlertCircle className="w-5 h-5 text-red-500" />
                  Delete Promotion?
                </h3>
              </div>
              <div className="p-4 sm:p-6">
                <p className="text-sm text-gray-600 mb-4">
                  Are you sure you want to delete this promotion? This action cannot be undone.
                </p>
                <div className="flex gap-3">
                  <button
                    onClick={() => setDeleteConfirmId(null)}
                    className="flex-1 px-3 sm:px-4 py-2 text-xs sm:text-sm font-medium text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={() => {
                      if (deleteConfirmId) {
                        handleDeletePromotion(deleteConfirmId);
                      }
                    }}
                    className="flex-1 px-3 sm:px-4 py-2 text-xs sm:text-sm font-medium text-white bg-red-600 rounded-lg hover:bg-red-700 transition-colors"
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import {
  ArrowLeft,
  Loader2,
  CreditCard,
  Bell,
  Shield,
  Save,
  CheckCircle,
  AlertCircle,
  Building,
  User,
  RefreshCw,
  Globe,
  Languages,
} from 'lucide-react'
import { useCurrency } from '@/components/CurrencyProvider'
import { useLanguage } from '@/contexts/LanguageContext'

interface BankAccount {
  bankName: string
  accountNumber: string
  accountName: string
  bankCode: string
  isVerified: boolean
}

interface SellerSettings {
  emailNotifications: boolean
  orderNotifications: boolean
  payoutNotifications: boolean
  bankAccount: BankAccount | null
}

export default function SellerSettingsPage() {
  const { data: session, status: authStatus } = useSession()
  const router = useRouter()
  const { currency, setCurrency, currencies } = useCurrency()
  const { locale, setLocale, supportedLocales, currentLocaleConfig } = useLanguage()
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [settings, setSettings] = useState<SellerSettings>({
    emailNotifications: true,
    orderNotifications: true,
    payoutNotifications: true,
    bankAccount: null,
  })
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null)

  // Bank account form
  const [showBankForm, setShowBankForm] = useState(false)
  const [banks, setBanks] = useState<{ code: string; name: string }[]>([])
  const [bankForm, setBankForm] = useState({
    bankCode: '',
    accountNumber: '',
    accountName: '',
  })
  const [verifying, setVerifying] = useState(false)
  const [verified, setVerified] = useState(false)

  useEffect(() => {
    if (authStatus === 'loading') return
    if (!session) {
      router.push('/auth/signin')
      return
    }
    fetchSettings()
    fetchBanks()
  }, [session, authStatus, router])

  const fetchSettings = async () => {
    try {
      const response = await fetch('/api/seller/account')
      if (response.ok) {
        const data = await response.json()
        setSettings({
          emailNotifications: data.emailNotifications ?? true,
          orderNotifications: data.orderNotifications ?? true,
          payoutNotifications: data.payoutNotifications ?? true,
          bankAccount: data.bankAccount || null,
        })
      }
    } catch (error) {
      console.error('Failed to fetch settings:', error)
    } finally {
      setLoading(false)
    }
  }

  const fetchBanks = async () => {
    try {
      const response = await fetch('/api/seller/banks')
      if (response.ok) {
        const data = await response.json()
        setBanks(data.banks || [])
      }
    } catch (error) {
      console.error('Failed to fetch banks:', error)
    }
  }

  const handleSaveNotifications = async () => {
    setSaving(true)
    setMessage(null)

    try {
      const response = await fetch('/api/seller/account', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          emailNotifications: settings.emailNotifications,
          orderNotifications: settings.orderNotifications,
          payoutNotifications: settings.payoutNotifications,
        }),
      })

      if (response.ok) {
        setMessage({ type: 'success', text: 'Settings saved successfully!' })
      } else {
        setMessage({ type: 'error', text: 'Failed to save settings' })
      }
    } catch (error) {
      console.error('Failed to save settings:', error)
      setMessage({ type: 'error', text: 'An error occurred' })
    } finally {
      setSaving(false)
      setTimeout(() => setMessage(null), 3000)
    }
  }

  const handleVerifyAccount = async () => {
    if (!bankForm.bankCode || !bankForm.accountNumber) return

    setVerifying(true)
    setVerified(false)

    try {
      const response = await fetch('/api/seller/verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          bankCode: bankForm.bankCode,
          accountNumber: bankForm.accountNumber,
        }),
      })

      if (response.ok) {
        const data = await response.json()
        setBankForm((prev) => ({ ...prev, accountName: data.accountName }))
        setVerified(true)
      } else {
        const data = await response.json()
        setMessage({ type: 'error', text: data.message || 'Failed to verify account' })
      }
    } catch (error) {
      console.error('Failed to verify account:', error)
      setMessage({ type: 'error', text: 'Failed to verify account' })
    } finally {
      setVerifying(false)
    }
  }

  const handleSaveBankAccount = async () => {
    if (!verified || !bankForm.accountName) {
      setMessage({ type: 'error', text: 'Please verify your account first' })
      return
    }

    setSaving(true)
    setMessage(null)

    try {
      const selectedBank = banks.find((b) => b.code === bankForm.bankCode)
      const response = await fetch('/api/seller/account', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          bankAccount: {
            bankCode: bankForm.bankCode,
            bankName: selectedBank?.name || '',
            accountNumber: bankForm.accountNumber,
            accountName: bankForm.accountName,
            isVerified: true,
          },
        }),
      })

      if (response.ok) {
        setMessage({ type: 'success', text: 'Bank account saved successfully!' })
        setShowBankForm(false)
        fetchSettings()
      } else {
        setMessage({ type: 'error', text: 'Failed to save bank account' })
      }
    } catch (error) {
      console.error('Failed to save bank account:', error)
      setMessage({ type: 'error', text: 'An error occurred' })
    } finally {
      setSaving(false)
    }
  }

  if (authStatus === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-indigo-600" />
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-3xl mx-auto px-3 sm:px-4 md:px-6 py-3 sm:py-4 md:py-8">
        {/* Header */}
        <div className="mb-4 sm:mb-6 md:mb-8">
          <Link
            href="/seller/dashboard"
            className="inline-flex items-center text-xs sm:text-sm text-gray-500 hover:text-gray-700 mb-2"
          >
            <ArrowLeft className="w-3 h-3 sm:w-4 sm:h-4 mr-1" />
            Back to Dashboard
          </Link>
          <h1 className="text-lg sm:text-xl md:text-2xl font-bold text-gray-900">Seller Settings</h1>
          <p className="text-xs sm:text-sm text-gray-600 mt-0.5 sm:mt-1">Manage your payout settings and preferences</p>
        </div>

        {/* Message */}
        {message && (
          <div
            className={`mb-3 sm:mb-4 md:mb-6 p-2.5 sm:p-3 md:p-4 rounded-lg flex items-center gap-2 text-xs sm:text-sm ${
              message.type === 'success'
                ? 'bg-green-50 border border-green-200 text-green-700'
                : 'bg-red-50 border border-red-200 text-red-700'
            }`}
          >
            {message.type === 'success' ? (
              <CheckCircle className="w-4 h-4 sm:w-5 sm:h-5 flex-shrink-0" />
            ) : (
              <AlertCircle className="w-4 h-4 sm:w-5 sm:h-5 flex-shrink-0" />
            )}
            {message.text}
          </div>
        )}

        {/* Bank Account Section */}
        <div id="bank" className="bg-white rounded-lg sm:rounded-xl shadow-sm p-3 sm:p-4 md:p-6 mb-3 sm:mb-4 md:mb-6">
          <div className="flex items-center gap-2 sm:gap-3 mb-3 sm:mb-4 md:mb-6">
            <div className="w-8 h-8 sm:w-10 sm:h-10 bg-green-100 rounded-lg flex items-center justify-center flex-shrink-0">
              <CreditCard className="w-4 h-4 sm:w-5 sm:h-5 text-green-600" />
            </div>
            <div>
              <h2 className="text-sm sm:text-base md:text-lg font-semibold text-gray-900">Bank Account</h2>
              <p className="text-xs sm:text-sm text-gray-500">Your payout destination</p>
            </div>
          </div>

          {settings.bankAccount ? (
            <div className="bg-gray-50 rounded-lg p-2.5 sm:p-3 md:p-4">
              <div className="flex items-center justify-between mb-2 sm:mb-3">
                <div className="flex items-center gap-2 min-w-0">
                  <Building className="w-4 h-4 sm:w-5 sm:h-5 text-gray-400 flex-shrink-0" />
                  <span className="font-medium text-xs sm:text-sm text-gray-900 truncate">{settings.bankAccount.bankName}</span>
                </div>
                {settings.bankAccount.isVerified && (
                  <span className="inline-flex items-center px-2 py-0.5 sm:px-2 sm:py-1 rounded-full text-[10px] sm:text-xs font-medium bg-green-100 text-green-700 flex-shrink-0">
                    <CheckCircle className="w-2.5 h-2.5 sm:w-3 sm:h-3 mr-0.5 sm:mr-1" />
                    <span className="hidden sm:inline">Verified</span>
                    <span className="sm:hidden">OK</span>
                  </span>
                )}
              </div>
              <div className="space-y-0.5 sm:space-y-1 text-xs sm:text-sm text-gray-600">
                <p>
                  <span className="text-gray-400">Account Name:</span> {settings.bankAccount.accountName}
                </p>
                <p>
                  <span className="text-gray-400">Account #:</span> ****
                  {settings.bankAccount.accountNumber.slice(-4)}
                </p>
              </div>
              <button
                onClick={() => setShowBankForm(true)}
                className="mt-2 sm:mt-3 text-xs sm:text-sm text-indigo-600 hover:text-indigo-800 font-medium"
              >
                Update Bank Account
              </button>
            </div>
          ) : (
            <div className="text-center py-4 sm:py-6">
              <CreditCard className="w-8 h-8 sm:w-12 sm:h-12 text-gray-300 mx-auto mb-2 sm:mb-3" />
              <p className="text-xs sm:text-sm text-gray-500 mb-2 sm:mb-3">No bank account added yet</p>
              <button
                onClick={() => setShowBankForm(true)}
                className="inline-flex items-center gap-1 sm:gap-2 px-3 sm:px-4 py-1.5 sm:py-2 bg-indigo-600 text-white text-xs sm:text-sm rounded-lg hover:bg-indigo-700"
              >
                Add Bank Account
              </button>
            </div>
          )}

          {/* Bank Form */}
          {showBankForm && (
            <div className="mt-3 sm:mt-4 md:mt-6 pt-3 sm:pt-4 md:pt-6 border-t border-gray-200">
              <h3 className="font-medium text-xs sm:text-sm md:text-base text-gray-900 mb-2 sm:mb-3 md:mb-4">
                {settings.bankAccount ? 'Update' : 'Add'} Bank Account
              </h3>
              <div className="space-y-2.5 sm:space-y-3 md:space-y-4">
                <div>
                  <label htmlFor="bankCode" className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">Bank</label>
                  <select
                    id="bankCode"
                    value={bankForm.bankCode}
                    onChange={(e) => {
                      setBankForm({ ...bankForm, bankCode: e.target.value, accountName: '' })
                      setVerified(false)
                    }}
                    className="w-full px-2.5 sm:px-3 py-1.5 sm:py-2 border border-gray-300 rounded-lg text-xs sm:text-sm focus:ring-indigo-500 focus:border-indigo-500"
                  >
                    <option value="">Select a bank</option>
                    {banks.map((bank) => (
                      <option key={bank.code} value={bank.code}>
                        {bank.name}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">
                    Account Number
                  </label>
                  <div className="flex gap-1.5 sm:gap-2">
                    <input
                      type="text"
                      value={bankForm.accountNumber}
                      onChange={(e) => {
                        setBankForm({ ...bankForm, accountNumber: e.target.value, accountName: '' })
                        setVerified(false)
                      }}
                      maxLength={10}
                      className="flex-1 px-2.5 sm:px-3 py-1.5 sm:py-2 border border-gray-300 rounded-lg text-xs sm:text-sm focus:ring-indigo-500 focus:border-indigo-500"
                      placeholder="10-digit account"
                    />
                    <button
                      onClick={handleVerifyAccount}
                      disabled={verifying || !bankForm.bankCode || bankForm.accountNumber.length < 10}
                      className="px-2.5 sm:px-4 py-1.5 sm:py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 disabled:opacity-50 disabled:cursor-not-allowed text-xs sm:text-sm"
                    >
                      {verifying ? (
                        <Loader2 className="w-4 h-4 sm:w-5 sm:h-5 animate-spin" />
                      ) : (
                        <RefreshCw className="w-4 h-4 sm:w-5 sm:h-5" />
                      )}
                    </button>
                  </div>
                </div>

                {bankForm.accountName && (
                  <div className="bg-green-50 border border-green-200 rounded-lg p-2 sm:p-2.5 md:p-3">
                    <div className="flex items-center gap-1.5 sm:gap-2 text-green-700 text-xs sm:text-sm">
                      <User className="w-4 h-4 sm:w-5 sm:h-5 flex-shrink-0" />
                      <span className="font-medium">{bankForm.accountName}</span>
                    </div>
                  </div>
                )}

                <div className="flex gap-2 sm:gap-3">
                  <button
                    onClick={() => {
                      setShowBankForm(false)
                      setBankForm({ bankCode: '', accountNumber: '', accountName: '' })
                      setVerified(false)
                    }}
                    className="px-3 sm:px-4 py-1.5 sm:py-2 text-xs sm:text-sm text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleSaveBankAccount}
                    disabled={!verified || saving}
                    className="flex-1 inline-flex items-center justify-center gap-1 sm:gap-2 px-3 sm:px-4 py-1.5 sm:py-2 bg-indigo-600 text-white text-xs sm:text-sm rounded-lg hover:bg-indigo-700 disabled:opacity-50"
                  >
                    {saving ? (
                      <>
                        <Loader2 className="w-3 h-3 sm:w-4 sm:h-4 animate-spin" />
                        <span className="hidden sm:inline">Saving...</span>
                      </>
                    ) : (
                      <>
                        <Save className="w-3 h-3 sm:w-4 sm:h-4" />
                        <span className="hidden sm:inline">Save Bank Account</span>
                        <span className="sm:hidden">Save</span>
                      </>
                    )}
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Notifications Section */}
        <div className="bg-white rounded-lg sm:rounded-xl shadow-sm p-3 sm:p-4 md:p-6 mb-3 sm:mb-4 md:mb-6">
          <div className="flex items-center gap-2 sm:gap-3 mb-3 sm:mb-4 md:mb-6">
            <div className="w-8 h-8 sm:w-10 sm:h-10 bg-blue-100 rounded-lg flex items-center justify-center flex-shrink-0">
              <Bell className="w-4 h-4 sm:w-5 sm:h-5 text-blue-600" />
            </div>
            <div>
              <h2 className="text-sm sm:text-base md:text-lg font-semibold text-gray-900">Notifications</h2>
              <p className="text-xs sm:text-sm text-gray-500">Manage your notification preferences</p>
            </div>
          </div>

          <div className="space-y-2 sm:space-y-3 md:space-y-4">
            <label className="flex items-center justify-between p-2 sm:p-3 bg-gray-50 rounded-lg cursor-pointer hover:bg-gray-100 transition-colors">
              <div>
                <p className="font-medium text-xs sm:text-sm text-gray-900">Email Notifications</p>
                <p className="text-[10px] sm:text-xs text-gray-500">Receive updates via email</p>
              </div>
              <input
                type="checkbox"
                checked={settings.emailNotifications}
                onChange={(e) =>
                  setSettings({ ...settings, emailNotifications: e.target.checked })
                }
                className="w-4 h-4 sm:w-5 sm:h-5 text-indigo-600 rounded focus:ring-indigo-500 flex-shrink-0"
              />
            </label>

            <label className="flex items-center justify-between p-2 sm:p-3 bg-gray-50 rounded-lg cursor-pointer hover:bg-gray-100 transition-colors">
              <div>
                <p className="font-medium text-xs sm:text-sm text-gray-900">Order Notifications</p>
                <p className="text-[10px] sm:text-xs text-gray-500">Get notified when you receive orders</p>
              </div>
              <input
                type="checkbox"
                checked={settings.orderNotifications}
                onChange={(e) =>
                  setSettings({ ...settings, orderNotifications: e.target.checked })
                }
                className="w-4 h-4 sm:w-5 sm:h-5 text-indigo-600 rounded focus:ring-indigo-500 flex-shrink-0"
              />
            </label>

            <label className="flex items-center justify-between p-2 sm:p-3 bg-gray-50 rounded-lg cursor-pointer hover:bg-gray-100 transition-colors">
              <div>
                <p className="font-medium text-xs sm:text-sm text-gray-900">Payout Notifications</p>
                <p className="text-[10px] sm:text-xs text-gray-500">Get notified about payout status</p>
              </div>
              <input
                type="checkbox"
                checked={settings.payoutNotifications}
                onChange={(e) =>
                  setSettings({ ...settings, payoutNotifications: e.target.checked })
                }
                className="w-4 h-4 sm:w-5 sm:h-5 text-indigo-600 rounded focus:ring-indigo-500 flex-shrink-0"
              />
            </label>
          </div>

          <button
            onClick={handleSaveNotifications}
            disabled={saving}
            className="mt-3 sm:mt-4 md:mt-6 inline-flex items-center gap-1 sm:gap-2 px-3 sm:px-4 py-1.5 sm:py-2 bg-indigo-600 text-white text-xs sm:text-sm rounded-lg hover:bg-indigo-700 disabled:opacity-50"
          >
            {saving ? (
              <>
                <Loader2 className="w-3 h-3 sm:w-4 sm:h-4 animate-spin" />
                <span className="hidden sm:inline">Saving...</span>
              </>
            ) : (
              <>
                <Save className="w-3 h-3 sm:w-4 sm:h-4" />
                <span className="hidden sm:inline">Save Preferences</span>
                <span className="sm:hidden">Save</span>
              </>
            )}
          </button>
        </div>

        {/* Currency & Language Section */}
        <div className="bg-white rounded-lg sm:rounded-xl shadow-sm p-3 sm:p-4 md:p-6 mb-3 sm:mb-4 md:mb-6">
          <div className="flex items-center gap-2 sm:gap-3 mb-3 sm:mb-4 md:mb-6">
            <div className="w-8 h-8 sm:w-10 sm:h-10 bg-blue-100 rounded-lg flex items-center justify-center flex-shrink-0">
              <Globe className="w-4 h-4 sm:w-5 sm:h-5 text-blue-600" />
            </div>
            <div>
              <h2 className="text-sm sm:text-base md:text-lg font-semibold text-gray-900">Display Preferences</h2>
              <p className="text-xs sm:text-sm text-gray-500">Customize how prices and content are displayed</p>
            </div>
          </div>

          <div className="space-y-3 sm:space-y-4">
            {/* Currency Selector */}
            <div>
              <label htmlFor="displayCurrency" className="block text-xs sm:text-sm font-medium text-gray-700 mb-1.5 sm:mb-2">
                Display Currency
              </label>
              <select
                id="displayCurrency"
                value={currency}
                onChange={(e) => {
                  setCurrency(e.target.value)
                  setMessage({ type: 'success', text: 'Currency preference saved!' })
                  setTimeout(() => setMessage(null), 3000)
                }}
                className="w-full px-2.5 sm:px-3 py-1.5 sm:py-2 border border-gray-300 rounded-lg text-xs sm:text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-gray-900"
              >
                {currencies.map((curr) => (
                  <option key={curr.code} value={curr.code}>
                    {curr.flag} {curr.code} - {curr.name}
                  </option>
                ))}
              </select>
              <p className="text-[10px] sm:text-xs text-gray-500 mt-1">
                All prices will be displayed in your selected currency. Actual payments are processed in the original currency.
              </p>
            </div>

            {/* Language Selector */}
            <div className="pt-3 sm:pt-4 border-t border-gray-200">
              <label htmlFor="displayLanguage" className="block text-xs sm:text-sm font-medium text-gray-700 mb-1.5 sm:mb-2">
                <Languages className="w-3 h-3 sm:w-4 sm:h-4 inline mr-1" />
                Language
              </label>
              <select
                id="displayLanguage"
                value={locale}
                onChange={(e) => {
                  setLocale(e.target.value as typeof locale)
                  setMessage({ type: 'success', text: 'Language preference saved!' })
                  setTimeout(() => setMessage(null), 3000)
                }}
                className="w-full px-2.5 sm:px-3 py-1.5 sm:py-2 border border-gray-300 rounded-lg text-xs sm:text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-gray-900"
              >
                {supportedLocales.map((lang) => (
                  <option key={lang.code} value={lang.code}>
                    {lang.flag} {lang.nativeName} ({lang.name})
                  </option>
                ))}
              </select>
              <p className="text-[10px] sm:text-xs text-gray-500 mt-1">
                Interface text will be displayed in your selected language where available.
              </p>
            </div>
          </div>
        </div>

        {/* Security Section */}
        <div className="bg-white rounded-lg sm:rounded-xl shadow-sm p-3 sm:p-4 md:p-6">
          <div className="flex items-center gap-2 sm:gap-3 mb-3 sm:mb-4 md:mb-6">
            <div className="w-8 h-8 sm:w-10 sm:h-10 bg-purple-100 rounded-lg flex items-center justify-center flex-shrink-0">
              <Shield className="w-4 h-4 sm:w-5 sm:h-5 text-purple-600" />
            </div>
            <div>
              <h2 className="text-sm sm:text-base md:text-lg font-semibold text-gray-900">Account Security</h2>
              <p className="text-xs sm:text-sm text-gray-500">Manage your account security</p>
            </div>
          </div>

          <div className="space-y-2 sm:space-y-3">
            <Link
              href="/profile/settings"
              className="block p-2 sm:p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors"
            >
              <p className="font-medium text-xs sm:text-sm text-gray-900">Change Password</p>
              <p className="text-[10px] sm:text-xs text-gray-500">Update your account password</p>
            </Link>

            <Link
              href="/profile/edit"
              className="block p-2 sm:p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors"
            >
              <p className="font-medium text-xs sm:text-sm text-gray-900">Edit Profile</p>
              <p className="text-[10px] sm:text-xs text-gray-500">Update your profile information</p>
            </Link>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useEffect, useState, useCallback } from 'react'
import Link from 'next/link'
import { Save, AlertCircle, CheckCircle, FileText, ArrowLeft } from 'lucide-react'

interface TaxInfo {
  country: string
  taxIdType: 'SSN' | 'EIN' | 'VAT' | 'OTHER'
  taxId: string
  businessName: string
  businessAddress: string
  isVerified: boolean
  verificationStatus: 'PENDING' | 'VERIFIED' | 'REJECTED'
  documents: Array<{
    id: string
    type: 'W9' | '1099' | 'VAT_CERT' | 'OTHER'
    uploadedAt: string
    verified: boolean
  }>
}

export default function SellerTaxInfoPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [taxInfo, setTaxInfo] = useState<TaxInfo | null>(null)
  const [loading, setLoading] = useState(true)
  const [editMode, setEditMode] = useState(false)
  const [saving, setSaving] = useState(false)

  // Form states
  const [country, setCountry] = useState('US')
  const [taxIdType, setTaxIdType] = useState<'SSN' | 'EIN' | 'VAT' | 'OTHER'>('SSN')
  const [taxId, setTaxId] = useState('')
  const [businessName, setBusinessName] = useState('')
  const [businessAddress, setBusinessAddress] = useState('')

  const fetchTaxInfo = useCallback(async () => {
    try {
      setLoading(true)
      const response = await fetch('/api/seller/tax-info')
      if (response.ok) {
        const data = await response.json()
        setTaxInfo(data.taxInfo)
        setCountry(data.taxInfo?.country || 'US')
        setTaxIdType(data.taxInfo?.taxIdType || 'SSN')
        setTaxId(data.taxInfo?.taxId || '')
        setBusinessName(data.taxInfo?.businessName || '')
        setBusinessAddress(data.taxInfo?.businessAddress || '')
      }
    } catch (error) {
      console.error('Failed to fetch tax info:', error)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (status !== 'authenticated') return

    fetchTaxInfo()
  }, [status, router, fetchTaxInfo])

  const handleSave = async () => {
    if (!taxId || !businessName) {
      alert('Please fill in all required fields')
      return
    }

    try {
      setSaving(true)
      const response = await fetch('/api/seller/tax-info', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          country,
          taxIdType,
          taxId,
          businessName,
          businessAddress,
        }),
      })

      if (response.ok) {
        await fetchTaxInfo()
        setEditMode(false)
      }
    } catch (error) {
      console.error('Failed to save tax info:', error)
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return <div className="p-8 text-center">Loading tax information...</div>
  }

  const getTaxIdLabel = (type: string) => {
    switch (type) {
      case 'SSN': return 'Social Security Number'
      case 'EIN': return 'Employer Identification Number'
      case 'VAT': return 'VAT Number'
      default: return 'Tax ID'
    }
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 md:p-8">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <Link href="/seller/dashboard" className="p-2 hover:bg-gray-200 rounded-lg transition">
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Tax Information</h1>
            <p className="text-gray-600 mt-1">Manage your tax details for payouts</p>
          </div>
        </div>

        {/* Info Banner */}
        <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-6">
          <p className="text-sm text-blue-900 flex items-start gap-2">
            <AlertCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />
            <span>This information is required for accurate payment processing and tax reporting. Your data is encrypted and securely stored.</span>
          </p>
        </div>

        {/* Tax Info Card */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-semibold text-gray-900">Tax Details</h2>
            {!editMode && (
              <button
                onClick={() => setEditMode(true)}
                className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition text-sm"
              >
                Edit
              </button>
            )}
          </div>

          {taxInfo?.isVerified && (
            <div className="mb-6 p-4 bg-green-50 border border-green-200 rounded-lg flex items-center gap-2">
              <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0" />
              <span className="text-sm text-green-800">Tax information verified</span>
            </div>
          )}

          {taxInfo?.verificationStatus === 'PENDING' && (
            <div className="mb-6 p-4 bg-yellow-50 border border-yellow-200 rounded-lg flex items-center gap-2">
              <AlertCircle className="w-5 h-5 text-yellow-600 flex-shrink-0" />
              <span className="text-sm text-yellow-800">Verification in progress</span>
            </div>
          )}

          {taxInfo?.verificationStatus === 'REJECTED' && (
            <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg">
              <p className="text-sm text-red-800 flex items-center gap-2">
                <AlertCircle className="w-5 h-5 flex-shrink-0" />
                Tax information rejected. Please verify and resubmit.
              </p>
            </div>
          )}

          <div className="space-y-4">
            {editMode ? (
              <>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 sm:gap-3">
                  <div>
                    <label className="block text-xs font-medium text-gray-900 mb-1">Country *</label>
                    <select
                      value={country}
                      onChange={(e) => setCountry(e.target.value)}
                      aria-label="Select country"
                      className="w-full px-3 py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                    >
                      <option value="US">United States</option>
                      <option value="CA">Canada</option>
                      <option value="UK">United Kingdom</option>
                      <option value="AU">Australia</option>
                      <option value="OTHER">Other</option>
                    </select>
                  </div>

                  <div>
                    <label className="block text-xs font-medium text-gray-900 mb-1">Tax ID Type *</label>
                    <select
                      value={taxIdType}
                      onChange={(e) => setTaxIdType(e.target.value as 'SSN' | 'EIN' | 'VAT' | 'OTHER')}
                      aria-label="Select tax ID type"
                      className="w-full px-3 py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                    >
                      <option value="SSN">Social Security Number</option>
                      <option value="EIN">Employer ID Number</option>
                      <option value="VAT">VAT Number</option>
                      <option value="OTHER">Other</option>
                    </select>
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-medium text-gray-900 mb-1">{getTaxIdLabel(taxIdType)} *</label>
                  <input
                    type="text"
                    value={taxId}
                    onChange={(e) => setTaxId(e.target.value)}
                    placeholder="e.g., 12-3456789"
                    aria-label="Tax ID"
                    className="w-full px-3 py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                  />
                </div>

                <div>
                  <label className="block text-xs font-medium text-gray-900 mb-1">Business/Legal Name *</label>
                  <input
                    type="text"
                    value={businessName}
                    onChange={(e) => setBusinessName(e.target.value)}
                    aria-label="Business name"
                    className="w-full px-3 py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                  />
                </div>

                <div>
                  <label className="block text-xs font-medium text-gray-900 mb-1">Business Address</label>
                  <textarea
                    value={businessAddress}
                    onChange={(e) => setBusinessAddress(e.target.value)}
                    aria-label="Business address"
                    className="w-full px-3 py-1.5 border border-gray-300 rounded-lg text-black bg-white text-xs"
                    rows={2}
                  />
                </div>

                <div className="flex gap-2 justify-end pt-2 border-t border-gray-200 mt-2">
                  <button
                    onClick={() => setEditMode(false)}
                    className="px-2.5 py-1.5 text-xs border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
                    aria-label="Cancel editing"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleSave}
                    disabled={saving}
                    className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition disabled:opacity-50 flex items-center gap-2"
                  >
                    <Save className="w-4 h-4" />
                    Save Changes
                  </button>
                </div>
              </>
            ) : (
              <>
                <div>
                  <p className="text-sm text-gray-600 mb-1">Country</p>
                  <p className="text-lg font-semibold text-gray-900">{country}</p>
                </div>

                <div>
                  <p className="text-sm text-gray-600 mb-1">{getTaxIdLabel(taxIdType)}</p>
                  <p className="text-lg font-semibold text-gray-900">{taxId ? taxId.replace(/\d(?=\d{4})/g, '*') : 'Not set'}</p>
                </div>

                <div>
                  <p className="text-sm text-gray-600 mb-1">Business/Legal Name</p>
                  <p className="text-lg font-semibold text-gray-900">{businessName || 'Not set'}</p>
                </div>

                {businessAddress && (
                  <div>
                    <p className="text-sm text-gray-600 mb-1">Business Address</p>
                    <p className="text-gray-900 whitespace-pre-line">{businessAddress}</p>
                  </div>
                )}
              </>
            )}
          </div>
        </div>

        {/* Tax Documents */}
        {taxInfo?.documents && taxInfo.documents.length > 0 && (
          <div className="bg-white rounded-lg shadow-sm p-6">
            <h2 className="text-xl font-semibold text-gray-900 mb-4 flex items-center gap-2">
              <FileText className="w-5 h-5" />
              Tax Documents
            </h2>

            <div className="space-y-3">
              {taxInfo.documents.map((doc) => (
                <div key={doc.id} className="flex items-center justify-between p-4 bg-gray-50 rounded-lg border border-gray-200">
                  <div className="flex items-center gap-3">
                    <FileText className="w-5 h-5 text-gray-400" />
                    <div>
                      <p className="font-medium text-gray-900">{doc.type}</p>
                      <p className="text-xs text-gray-600">{new Date(doc.uploadedAt).toLocaleDateString()}</p>
                    </div>
                  </div>
                  {doc.verified && (
                    <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
                      <CheckCircle className="w-3 h-3" />
                      Verified
                    </span>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Help */}
        <div className="bg-indigo-50 rounded-lg p-6 mt-6 border border-indigo-200">
          <h3 className="font-semibold text-indigo-900 mb-2">Need Help?</h3>
          <p className="text-sm text-indigo-800 mb-4">
            Visit our tax documentation guide to learn about required forms and how to complete your tax information.
          </p>
          <a
            href="/help/tax-info"
            className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition text-sm"
          >
            View Guide
          </a>
        </div>
      </div>
    </div>
  )
}

