                      Verification Code
                    </label>
                    <input
                      type="text"
                      maxLength={6}
                      placeholder="000000"
                      value={trialActivation.verificationCode}
                      onChange={(e) => setTrialActivation(prev => ({
                        ...prev,
                        verificationCode: e.target.value.replace(/\D/g, '').slice(0, 6)
                      }))}
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg text-center text-2xl tracking-widest font-mono bg-white text-black placeholder-gray-400"
                    />
                    <p className="text-xs text-gray-500 mt-2">
                      Enter the 6-digit code sent to your account
                    </p>
                  </div>

                  <button
                    onClick={handleTrialActivationVerify}
                    disabled={trialActivation.loading || trialActivation.verificationCode.length !== 6}
                    className="w-full py-3 bg-green-600 text-white rounded-lg font-medium hover:bg-green-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {trialActivation.loading ? 'Activating trial...' : 'Activate Trial'}
                  </button>

                  <button
                    onClick={() => setTrialActivation(prev => ({ ...prev, step: 'none', verificationCode: '' }))}
                    className="w-full py-2 bg-gray-100 text-gray-700 rounded-lg font-medium hover:bg-gray-200"
                  >
                    Cancel
                  </button>

                  <p className="text-xs text-gray-500 text-center">
                    Didn't get the code? Check your spam folder or contact support.
                  </p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useSearchParams } from 'next/navigation'
import { useState, useEffect } from 'react'
import Image from 'next/image'
import Link from 'next/link'
import { ShoppingBag, Star, Heart, _Filter, Grid, List, _ChevronDown } from 'lucide-react'
import { convertFromUSD } from '@/lib/currency'

interface Product {
  id: string
  title: string
  slug?: string | null
  basePrice: number
  thumbnailUrl: string | null
  imageUrl: string
  category?: {
    name: string
  } | null
  seller?: {
    name: string
    displayName: string | null
    isVerified: boolean
  } | null
  _count?: {
    reviews: number
    favorites: number
  }
  averageRating?: number | null
}

export default function ShopPhysicalContent() {
  const _searchParams = useSearchParams()
  const [products, setProducts] = useState<Product[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid')
  const [sortBy, setSortBy] = useState('newest')
  const [filterCategory, setFilterCategory] = useState('all')
  const [priceRange, setPriceRange] = useState({ min: 0, max: 1000 })
  const [maxPrice, setMaxPrice] = useState(1000)
  const [categories, setCategories] = useState<string[]>([])
  const [preferredCurrency, setPreferredCurrency] = useState('USD')
  const [exchangeRates, setExchangeRates] = useState<Record<string, number>>({ USD: 1, NGN: 1600, EUR: 0.92, GBP: 0.79 })

  useEffect(() => {
    fetchCurrencySettings()
    fetchProducts()
  }, [])

  const fetchCurrencySettings = async () => {
    try {
      const [prefsRes, ratesRes] = await Promise.all([
        fetch('/api/preferences'),
        fetch('/api/currency/rates')
      ])

      if (prefsRes.ok) {
        const prefsData = await prefsRes.json()
        setPreferredCurrency(prefsData.currency || 'USD')
      }

      if (ratesRes.ok) {
        const ratesData = await ratesRes.json()
        setExchangeRates(ratesData.rates)
      }
    } catch (err) {
      console.error('Failed to fetch currency settings:', err)
    }
  }

  const formatPrice = (priceUSD: number) => {
    let convertedAmount = priceUSD
    
    if (preferredCurrency !== 'USD' && exchangeRates[preferredCurrency]) {
      convertedAmount = convertFromUSD(priceUSD, preferredCurrency, exchangeRates)
    }
    
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: preferredCurrency
    }).format(convertedAmount)
  }

  const fetchProducts = async () => {
    try {
      setLoading(true)
      setError(null)
      const response = await fetch('/api/boutique/products?status=LIVE&limit=100')
      if (!response.ok) {
        throw new Error('Failed to load boutique products')
      }
      const data = await response.json()
      if (data.products && Array.isArray(data.products)) {
        setProducts(data.products)
        // Calculate max price from products
        const prices = data.products.map((p: any) => p.basePrice || 0)
        const calculatedMax = Math.max(...prices, 1000)
        setMaxPrice(Math.round(calculatedMax))
        setPriceRange({ min: 0, max: calculatedMax })
        
        // Extract unique categories
        const uniqueCats = [...new Set(data.products.map((p: any) => p.category?.name).filter(Boolean))]
        setCategories(uniqueCats as string[])
      } else {
        setProducts([])
        setCategories([])
        setMaxPrice(1000)
        setPriceRange({ min: 0, max: 1000 })
      }
    } catch (err) {
      console.error('Error fetching boutique products:', err)
      setError(err instanceof Error ? err.message : 'Failed to load products')
      setProducts([])
      setCategories([])
      setMaxPrice(1000)
      setPriceRange({ min: 0, max: 1000 })
    } finally {
      setLoading(false)
    }
  }

  const filteredProducts = products.filter(p => {
    const categoryMatch = filterCategory === 'all' || p.category?.name === filterCategory
    const priceMatch = p.basePrice >= priceRange.min && p.basePrice <= priceRange.max
    return categoryMatch && priceMatch
  })

  const sortedProducts = [...filteredProducts].sort((a, b) => {
    switch (sortBy) {
      case 'price-low': return a.basePrice - b.basePrice
      case 'price-high': return b.basePrice - a.basePrice
      case 'popular': return (b._count?.favorites ?? 0) - (a._count?.favorites ?? 0)
      case 'rating': return (b.averageRating ?? 0) - (a.averageRating ?? 0)
      default: return 0
    }
  })

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Hero Banner */}
      <div className="bg-gradient-to-r from-purple-600 to-indigo-600 text-white py-4 sm:py-6 md:py-8">
        <div className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8">
          <h1 className="text-xl sm:text-2xl md:text-3xl font-bold mb-1.5 sm:mb-2">Shop Boutique</h1>
          <p className="text-xs sm:text-sm text-purple-100 max-w-2xl line-clamp-2">
            Discover unique, handmade fashion items from talented designers. Support independent creators and find one-of-a-kind pieces.
          </p>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 py-3 sm:py-4">
        {/* Controls */}
        <div className="bg-white rounded-lg shadow-sm p-2.5 sm:p-4 mb-3 sm:mb-4">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 mb-2.5">
            <div className="text-xs text-gray-600">
              Showing {sortedProducts.length} items
            </div>
            <div className="flex items-center gap-1.5 sm:gap-2">
              <select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value)}
                className="px-2 py-1.5 border border-gray-300 rounded-lg text-[11px] sm:text-xs text-black bg-white"
              >
                <option value="newest">Newest</option>
                <option value="price-low">Price Γåæ</option>
                <option value="price-high">Price Γåô</option>
                <option value="popular">Popular</option>
                <option value="rating">Rating</option>
              </select>
              <div className="flex border border-gray-300 rounded-lg overflow-hidden">
                <button
                  onClick={() => setViewMode('grid')}
                  className={`p-1 ${viewMode === 'grid' ? 'bg-gray-100' : 'hover:bg-gray-50'}`}
                  title="Grid view"
                >
                  <Grid className="w-3.5 h-3.5" />
                </button>
                <button
                  onClick={() => setViewMode('list')}
                  className={`p-1 ${viewMode === 'list' ? 'bg-gray-100' : 'hover:bg-gray-50'}`}
                  title="List view"
                >
                  <List className="w-3.5 h-3.5" />
                </button>
              </div>
            </div>
          </div>

          {/* Filter Controls */}
          <div className="flex flex-col sm:flex-row gap-2 sm:gap-3">
            <select
              value={filterCategory}
              onChange={(e) => setFilterCategory(e.target.value)}
              className="px-2 py-1.5 border border-gray-300 rounded-lg text-[11px] sm:text-xs text-black bg-white"
            >
              <option value="all">All Categories</option>
              {categories.map(cat => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
            <div className="flex items-center gap-1.5">
              <input
                type="range"
                min="0"
                max={maxPrice}
                value={priceRange.max}
                onChange={(e) => {
                  const newMax = parseInt(e.target.value, 10);
                  if (!isNaN(newMax)) {
                    setPriceRange({ ...priceRange, max: newMax });
                  }
                }}
                className="flex-1"
              />
              <span className="text-[11px] sm:text-xs text-gray-600 whitespace-nowrap">Max: ${priceRange.max}</span>
            </div>
          </div>
        </div>

        {/* Error State */}
        {error && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-2.5 mb-3 text-red-700 text-xs sm:text-sm">
            {error}
          </div>
        )}

        {/* Products Grid/List */}
        {loading ? (
          <div className="text-center py-8">
            <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
            <p className="text-gray-500 mt-2 text-xs">Loading products...</p>
          </div>
        ) : sortedProducts.length === 0 ? (
          <div className="text-center py-8 bg-white rounded-lg">
            <ShoppingBag className="w-8 h-8 text-gray-300 mx-auto mb-2" />
            <p className="text-gray-500 text-xs">{products.length === 0 ? 'No products available' : 'No products found'}</p>
          </div>
        ) : viewMode === 'grid' ? (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-2 sm:gap-3 md:gap-4">
            {sortedProducts.map(product => (
              <Link
                key={product.id}
                href={`/boutique/${product.slug || product.id}`}
                className="group bg-white rounded-lg shadow-sm overflow-hidden hover:shadow-md transition"
              >
                <div className="aspect-square relative overflow-hidden bg-gray-200">
                  <Image
                    src={product.thumbnailUrl || product.imageUrl}
                    alt={product.title}
                    fill
                    className="object-cover group-hover:scale-105 transition-transform"
                  />
                  <button
                    onClick={(e) => {
                      e.preventDefault()
                      e.stopPropagation()
                    }}
                    className="absolute top-1 right-1 p-1.5 bg-white rounded-full shadow-sm hover:shadow-md transition opacity-0 group-hover:opacity-100"
                    title="Add to wishlist"
                  >
                    <Heart className="w-3.5 h-3.5 text-red-500" />
                  </button>
                </div>
                  <div className="p-1.5 sm:p-2.5">
                  <h3 className="font-medium text-gray-900 truncate text-[10px] sm:text-xs">{product.title}</h3>
                  <p className="text-[9px] text-gray-600 mt-0.5 truncate">{product.category?.name ?? 'Uncategorized'}</p>
                  <div className="flex items-center gap-0.5 mt-1">
                    {[...Array(5)].map((_, i) => (
                      <Star
                        key={i}
                        className={`w-2.5 h-2.5 ${i < Math.round(product.averageRating ?? 0) ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300'}`}
                      />
                    ))}
                    <span className="text-[8px] text-gray-600 ml-0.5">({product._count?.reviews ?? 0})</span>
                  </div>
                  <div className="flex items-center justify-between mt-1.5 sm:mt-2">
                    <span className="font-bold text-indigo-600 text-[10px] sm:text-xs">{formatPrice(product.basePrice)}</span>
                    <span className="text-[8px] text-gray-600 truncate ml-1">{(product.seller?.displayName || product.seller?.name || 'Unknown').slice(0, 8)}</span>
                  </div>
                </div>
              </Link>
            ))}
          </div>
        ) : (
          <div className="space-y-2 sm:space-y-2.5">
            {sortedProducts.map(product => (
              <Link
                key={product.id}
                href={`/boutique/${product.slug || product.id}`}
                className="flex gap-2 sm:gap-3 bg-white rounded-lg shadow-sm p-2.5 sm:p-3 hover:shadow-md transition"
              >
                <div className="w-20 h-20 sm:w-24 sm:h-24 relative flex-shrink-0 rounded-lg overflow-hidden">
                  <Image
                    src={product.thumbnailUrl || product.imageUrl}
                    alt={product.title}
                    fill
                    className="object-cover"
                  />
                </div>
                <div className="flex-1 flex flex-col justify-between min-w-0">
                  <div>
                    <h3 className="font-semibold text-gray-900 text-[11px] sm:text-sm line-clamp-1">{product.title}</h3>
                    <p className="text-[9px] sm:text-xs text-gray-600 mt-0.5 line-clamp-1">{product.category?.name ?? 'Uncategorized'} ┬╖ {(product.seller?.displayName || product.seller?.name || 'Unknown').slice(0, 12)}</p>
                    <div className="flex items-center gap-1.5 mt-1.5">
                      <div className="flex items-center gap-0.5">
                        {[...Array(5)].map((_, i) => (
                          <Star
                            key={i}
                            className={`w-2.5 h-2.5 ${i < Math.round(product.averageRating ?? 0) ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300'}`}
                          />
                        ))}
                      </div>
                      <span className="text-[8px] text-gray-600">({product._count?.reviews ?? 0})</span>
                    </div>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="font-bold text-sm sm:text-base text-indigo-600">{formatPrice(product.basePrice)}</span>
                    <button className="p-1 hover:bg-gray-100 rounded-lg transition" title="Add to wishlist">
                      <Heart className="w-4 h-4 text-gray-400" />
                    </button>
                  </div>
                </div>
              </Link>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { useRouter } from 'next/navigation'
import { useSession } from 'next-auth/react'
import { Upload, Image as ImageIcon, DollarSign, Tag, Type, FileText, CheckCircle, X, Plus, Trash2, Eye, Lock, Package, Palette, ExternalLink } from 'lucide-react'
import _Image from 'next/image'
import Link from 'next/link'
import SignaturePad from '@/components/SignaturePad'

interface MediaFile {
  id: string
  file: File | null
  preview: string | null
  accessType: 'FREE' | 'PREMIUM'
  fileType: 'IMAGE' | 'VIDEO'
  displayName: string | null
}

interface FeatureStatus {
  acceptsCommissions: boolean
  acceptsPOD: boolean
}

export default function EnhancedUploadPage() {
  const { data: session } = useSession()
  const router = useRouter()
  const titleInputRef = useRef<HTMLInputElement>(null)
  const [isUploading, setIsUploading] = useState(false)
  const [successMessage, setSuccessMessage] = useState<string | null>(null)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)
  const [bankAccountRequired, setBankAccountRequired] = useState(false)
  const [bankAccountNeedsVerification, setBankAccountNeedsVerification] = useState(false)
  const [featureStatus, setFeatureStatus] = useState<FeatureStatus>({ acceptsCommissions: false, acceptsPOD: false })
  const [mediaFiles, setMediaFiles] = useState<MediaFile[]>([
    { id: '1', file: null, preview: null, accessType: 'PREMIUM', fileType: 'IMAGE', displayName: null }
  ])
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    price: '',
    ownershipPrice: '',
    category: 'Fashion Illustrations',
    tags: '',
    buyingTypes: 'REGULAR',
    currency: 'USD'
  })
  const [ownershipData, setOwnershipData] = useState({
    sellerFullName: '',
    sellerUsername: '',
    sellerSignature: '',
    previewFile: null as File | null,
    previewDescription: ''
  })
  const [ownershipDocumentCreated, setOwnershipDocumentCreated] = useState(false)

  const categories = [
    'Fashion Illustrations',
    'Digital Designs', 
    'Pattern Designs',
    'Sketches',
    'Technical Drawings',
    'Concept Art'
  ]

  // Check bank account status when component loads
  useEffect(() => {
    if (session?.user?.id) {
      checkBankAccountStatus()
      fetchFeatureStatus()
    }
  }, [session])

  const checkBankAccountStatus = async () => {
    try {
      const response = await fetch('/api/seller/account')
      if (response.ok) {
        const data = await response.json()
        if (!data.sellerAccount) {
          setBankAccountRequired(true)
        } else if (!data.sellerAccount.isVerified) {
          setBankAccountNeedsVerification(true)
        }
      } else if (response.status === 404) {
        setBankAccountRequired(true)
      }
    } catch (error) {
      console.error('Error checking bank account status:', error)
    }
  }

  const fetchFeatureStatus = async () => {
    try {
      // Fetch commission settings
      const commissionRes = await fetch('/api/seller/commission-settings')
      // Fetch POD settings
      const podRes = await fetch('/api/seller/pod-settings')
      
      let commissionStatus = false
      let podStatus = false
      
      if (commissionRes.ok) {
        const data = await commissionRes.json()
        commissionStatus = data.acceptsCommissions ?? false
      }
      
      if (podRes.ok) {
        const data = await podRes.json()
        podStatus = data.acceptsPOD ?? false
      }
      
      setFeatureStatus({
        acceptsCommissions: commissionStatus,
        acceptsPOD: podStatus
      })
    } catch (error) {
      console.error('Error fetching feature status:', error)
    }
  }

  const addMediaSection = () => {
    const newId = (mediaFiles.length + 1).toString()
    setMediaFiles([...mediaFiles, {
      id: newId,
      file: null,
      preview: null,
      accessType: 'PREMIUM',
      fileType: 'IMAGE',
      displayName: null
    }])
  }

  const removeMediaSection = (id: string) => {
    if (mediaFiles.length > 1) {
      setMediaFiles(mediaFiles.filter(media => media.id !== id))
    }
  }

  const handleFileChange = (id: string, file: File) => {
    const fileType = file.type.startsWith('video/') ? 'VIDEO' : 'IMAGE'
    const reader = new FileReader()
    
    reader.onload = (e) => {
      setMediaFiles(mediaFiles.map(media => 
        media.id === id 
          ? { ...media, file, preview: e.target?.result as string, fileType, displayName: file.name }
          : media
      ))
    }
    reader.readAsDataURL(file)
  }

  const updateMediaAccessType = (id: string, accessType: 'FREE' | 'PREMIUM') => {
    setMediaFiles(mediaFiles.map(media => 
      media.id === id ? { ...media, accessType } : media
    ))
  }

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault()
    if (!session) {
      setErrorMessage('Please sign in to upload designs')
      setSuccessMessage(null)
      return
    }

    // Validate title is not empty
    if (!formData.title.trim()) {
      setErrorMessage('Please enter a design title')
      setSuccessMessage(null)
      titleInputRef.current?.focus()
      titleInputRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' })
      return
    }

    // Validate at least one file is uploaded
    const filesWithContent = mediaFiles.filter(media => media.file)
    if (filesWithContent.length === 0) {
      setErrorMessage('Please upload at least one media file')
      setSuccessMessage(null)
      return
    }

    // Validate ownership fields if ownership is selected
    if (formData.buyingTypes === 'OWNERSHIP' || formData.buyingTypes === 'BOTH') {
      if (!ownershipData.sellerFullName.trim()) {
        setErrorMessage('Please enter your full legal name for ownership transfer')
        setSuccessMessage(null)
        return
      }
      if (!ownershipData.sellerSignature.trim()) {
        setErrorMessage('Please provide your signature for the ownership agreement')
        setSuccessMessage(null)
        return
      }
      if (!ownershipData.previewFile) {
        setErrorMessage('Preview file is required for ownership sales. Upload an image or video for the 7-day escrow period.')
        setSuccessMessage(null)
        return
      }
    }

    setIsUploading(true)
    
    try {
      const uploadFormData = new FormData()
      uploadFormData.append('title', formData.title)
      uploadFormData.append('description', formData.description)
      uploadFormData.append('price', formData.price)
      uploadFormData.append('ownershipPrice', formData.ownershipPrice)
      uploadFormData.append('category', formData.category)
      uploadFormData.append('tags', formData.tags)
      uploadFormData.append('buyingTypes', formData.buyingTypes)
      uploadFormData.append('currency', formData.currency)

      // Add media files with metadata
      filesWithContent.forEach((media, index) => {
        if (media.file) {
          uploadFormData.append(`files`, media.file)
          uploadFormData.append(`fileMetadata`, JSON.stringify({
            accessType: media.accessType,
            fileType: media.fileType,
            sortOrder: index,
            displayName: media.displayName || media.file.name
          }))
        }
      })

      const response = await fetch('/api/designs/upload-multi', {
        method: 'POST',
        body: uploadFormData
      })

      if (response.ok) {
        const result = await response.json()
        
        // Submit ownership document if ownership is selected
        if (formData.buyingTypes === 'OWNERSHIP' || formData.buyingTypes === 'BOTH') {
          try {
            const ownershipRes = await fetch('/api/ownership-documents', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                designId: result.id,
                sellerFullName: ownershipData.sellerFullName,
                sellerUsername: ownershipData.sellerUsername,
                sellerSignature: ownershipData.sellerSignature
              })
            })
            if (ownershipRes.ok) {
              setOwnershipDocumentCreated(true)
              
              // Upload preview file if provided
              if (ownershipData.previewFile) {
                try {
                  const ownershipData_result = await ownershipRes.json()
                  const documentId = ownershipData_result.document?.id || ownershipData_result.id
                  
                  if (documentId) {
                    const previewFormData = new FormData()
                    previewFormData.append('file', ownershipData.previewFile)
                    previewFormData.append('documentId', documentId)
                    previewFormData.append('description', ownershipData.previewDescription || '')
                    
                    await fetch('/api/ownership-documents/preview', {
                      method: 'POST',
                      body: previewFormData
                    })
                  }
                } catch (error) {
                  console.error('Preview file upload error:', error)
                  // Don't fail if preview upload fails
                }
              }
            }
          } catch (error) {
            console.error('Ownership document submission error:', error)
            // Don't fail the upload if ownership document fails
          }
        }
        
        setSuccessMessage('Design uploaded successfully! It will be visible once approved.')
        setErrorMessage(null)
        // Redirect after showing success message
        setTimeout(() => {
          router.push(`/designs/${result.id}`)
        }, 2000)
      } else {
        const error = await response.json()
        
        // Handle bank account requirement
        if (error.requiresBankAccount) {
          setBankAccountRequired(true)
          setErrorMessage(null)
        } else if (error.requiresVerification) {
          setBankAccountNeedsVerification(true)
          setErrorMessage(null)
        } else {
          setErrorMessage(`Upload failed: ${error.message}`)
        }
        setSuccessMessage(null)
      }
    } catch (error) {
      console.error('Upload error:', error)
      setErrorMessage('Upload failed. Please try again.')
      setSuccessMessage(null)
    } finally {
      setIsUploading(false)
    }
  }

  if (!session) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <h1 className="text-2xl font-bold text-gray-900 mb-4">Sign In Required</h1>
          <p className="text-gray-600 mb-6">Please sign in to upload your designs</p>
          <button 
            onClick={() => router.push('/api/auth/signin')}
            className="bg-indigo-700 text-white px-6 py-2 rounded-lg hover:bg-indigo-800 font-medium"
          >
            Sign In
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 py-4 sm:py-8">
      <div className="max-w-6xl mx-auto px-3 sm:px-6 lg:px-8">
        <div className="bg-white rounded-lg shadow-sm">
          <div className="px-3 sm:px-6 py-3 sm:py-4 border-b border-gray-200">
            <h1 className="text-base sm:text-xl lg:text-2xl font-bold text-gray-900 flex items-center gap-1.5">
              <Upload className="h-4 sm:h-5 w-4 sm:w-5" />
              Upload New Design
            </h1>
            <p className="text-xs sm:text-sm text-gray-600 mt-0.5 sm:mt-1">Share your fashion designs with multiple media files</p>
          </div>

          {/* Success Message */}
          {successMessage && (
            <div className="mx-3 sm:mx-6 mt-3 sm:mt-6 p-2.5 sm:p-4 bg-green-50 border border-green-200 rounded-lg flex items-center justify-between">
              <div className="flex items-center">
                <CheckCircle className="h-4 sm:h-5 w-4 sm:w-5 text-green-600 mr-2 sm:mr-3 flex-shrink-0" />
                <span className="text-xs sm:text-sm text-green-800 font-medium">{successMessage}</span>
              </div>
              <button
                onClick={() => setSuccessMessage(null)}
                className="text-green-600 hover:text-green-800 ml-2 flex-shrink-0"
                aria-label="Close success message"
              >
                <X className="h-3 sm:h-4 w-3 sm:w-4" />
              </button>
            </div>
          )}

          {/* Error Message */}
          {errorMessage && (
            <div className="mx-3 sm:mx-6 mt-3 sm:mt-6 p-2.5 sm:p-4 bg-red-50 border border-red-200 rounded-lg flex items-center justify-between">
              <div className="flex items-center">
                <X className="h-4 sm:h-5 w-4 sm:w-5 text-red-600 mr-2 sm:mr-3 flex-shrink-0" />
                <span className="text-xs sm:text-sm text-red-800 font-medium">{errorMessage}</span>
              </div>
              <button
                onClick={() => setErrorMessage(null)}
                className="text-red-600 hover:text-red-800 ml-2 flex-shrink-0"
                aria-label="Close error message"
              >
                <X className="h-3 sm:h-4 w-3 sm:w-4" />
              </button>
            </div>
          )}

          {/* Bank Account Required Message */}
          {bankAccountRequired && (
            <div className="mx-3 sm:mx-6 mt-3 sm:mt-6 p-3 sm:p-6 bg-yellow-50 border border-yellow-200 rounded-lg">
              <div className="flex items-start gap-2 sm:gap-3">
                <DollarSign className="h-4 sm:h-6 w-4 sm:w-6 text-yellow-600 mt-0.5 sm:mt-1 flex-shrink-0" />
                <div className="flex-1 min-w-0">
                  <h3 className="text-sm sm:text-base text-yellow-800 font-semibold mb-1.5 sm:mb-2">Bank Account Required</h3>
                  <p className="text-xs sm:text-sm text-yellow-700 mb-2.5 sm:mb-4 leading-tight">
                    To upload designs and receive payments, you need to add your bank account details first. 
                    This ensures you can receive your earnings when customers purchase your designs.
                  </p>
                  <div className="flex gap-2 sm:gap-3">
                    <button
                      onClick={() => router.push('/profile?tab=account&action=add-bank#bank-account')}
                      className="bg-yellow-600 text-white px-3 sm:px-4 py-1.5 sm:py-2 rounded-lg hover:bg-yellow-700 font-medium transition-colors text-xs sm:text-sm"
                    >
                      Add Bank Account
                    </button>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Bank Account Verification Required Message */}
          {bankAccountNeedsVerification && (
            <div className="mx-3 sm:mx-6 mt-3 sm:mt-6 p-3 sm:p-6 bg-blue-50 border border-blue-200 rounded-lg">
              <div className="flex items-start gap-2 sm:gap-3">
                <CheckCircle className="h-4 sm:h-6 w-4 sm:w-6 text-blue-600 mt-0.5 sm:mt-1 flex-shrink-0" />
                <div className="flex-1 min-w-0">
                  <h3 className="text-sm sm:text-base text-blue-800 font-semibold mb-1.5 sm:mb-2">Bank Account Verification Required</h3>
                  <p className="text-xs sm:text-sm text-blue-700 mb-2.5 sm:mb-4 leading-tight">
                    Your bank account has been added but needs to be verified before you can upload designs. 
                    Verification enables automatic payments with our split payment system.
                  </p>
                  <div className="flex gap-2 sm:gap-3">
                    <button
                      onClick={() => router.push('/profile#bank-verification')}
                      className="bg-blue-600 text-white px-3 sm:px-4 py-1.5 sm:py-2 rounded-lg hover:bg-blue-700 font-medium transition-colors text-xs sm:text-sm"
                    >
                      Verify Account
                    </button>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Feature Availability Notifications */}
          <div className="mx-3 sm:mx-6 mt-3 sm:mt-6 grid grid-cols-1 sm:grid-cols-2 gap-3">
            {/* Commission Availability */}
            <div className={`p-3 rounded-lg border ${
              featureStatus.acceptsCommissions 
                ? 'bg-purple-50 border-purple-200' 
                : 'bg-gray-50 border-gray-200'
            }`}>
              <div className="flex items-start gap-2">
                <Palette className={`h-4 w-4 mt-0.5 flex-shrink-0 ${
                  featureStatus.acceptsCommissions ? 'text-purple-600' : 'text-gray-400'
                }`} />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-xs font-semibold text-gray-900">Commissions</span>
                    <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-medium ${
                      featureStatus.acceptsCommissions 
                        ? 'bg-green-100 text-green-700' 
                        : 'bg-gray-200 text-gray-600'
                    }`}>
                      {featureStatus.acceptsCommissions ? 'ON' : 'OFF'}
                    </span>
                  </div>
                  <p className="text-[10px] sm:text-xs text-gray-600 mb-2">
                    {featureStatus.acceptsCommissions 
                      ? 'Buyers can request custom work based on your designs.' 
                      : 'Enable to receive custom design requests from buyers.'}
                  </p>
                  <Link
                    href="/seller/commission-settings"
                    className="inline-flex items-center gap-1 text-[10px] sm:text-xs text-purple-600 hover:text-purple-800 font-medium"
                  >
                    {featureStatus.acceptsCommissions ? 'Manage' : 'Enable'} Commissions
                    <ExternalLink className="h-2.5 w-2.5" />
                  </Link>
                </div>
              </div>
            </div>

            {/* POD Availability */}
            <div className={`p-3 rounded-lg border ${
              featureStatus.acceptsPOD 
                ? 'bg-orange-50 border-orange-200' 
                : 'bg-gray-50 border-gray-200'
            }`}>
              <div className="flex items-start gap-2">
                <Package className={`h-4 w-4 mt-0.5 flex-shrink-0 ${
                  featureStatus.acceptsPOD ? 'text-orange-600' : 'text-gray-400'
                }`} />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-xs font-semibold text-gray-900">Print-on-Demand</span>
                    <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-medium ${
                      featureStatus.acceptsPOD 
                        ? 'bg-green-100 text-green-700' 
                        : 'bg-gray-200 text-gray-600'
                    }`}>
                      {featureStatus.acceptsPOD ? 'ON' : 'OFF'}
                    </span>
                  </div>
                  <p className="text-[10px] sm:text-xs text-gray-600 mb-2">
                    {featureStatus.acceptsPOD 
                      ? 'Buyers can purchase your designs on physical products.' 
                      : 'Enable to sell your designs on t-shirts, mugs & more.'}
                  </p>
                  <Link
                    href="/seller/pod-settings"
                    className="inline-flex items-center gap-1 text-[10px] sm:text-xs text-orange-600 hover:text-orange-800 font-medium"
                  >
                    {featureStatus.acceptsPOD ? 'Manage' : 'Enable'} POD
                    <ExternalLink className="h-2.5 w-2.5" />
                  </Link>
                </div>
              </div>
            </div>
          </div>

          <div className="relative">
            <form onSubmit={handleSubmit} className={`p-3 sm:p-6 ${(bankAccountRequired || bankAccountNeedsVerification) ? 'opacity-50 pointer-events-none' : ''}`}>
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 sm:gap-8">
              {/* Media Files Upload */}
              <div>
                <div className="flex items-center justify-between mb-2.5 sm:mb-4 gap-2">
                  <label className="block text-xs sm:text-sm font-medium text-gray-700 min-w-0">
                    <ImageIcon className="inline h-3 sm:h-4 w-3 sm:w-4 mr-1" />
                    Media Files (Images & Videos)
                  </label>
                  <button
                    type="button"
                    onClick={addMediaSection}
                    className="inline-flex items-center px-2 sm:px-3 py-1 text-xs bg-indigo-100 text-indigo-700 rounded-md hover:bg-indigo-200 flex-shrink-0"
                  >
                    <Plus className="h-2.5 sm:h-3 w-2.5 sm:w-3 mr-0.5 sm:mr-1" />
                    Add File
                  </button>
                </div>

                {/* Seller Recommendation Message */}
                <div className="mb-3 sm:mb-4 p-2.5 sm:p-3 bg-blue-50 border border-blue-200 rounded-lg">
                  <p className="text-xs sm:text-sm text-blue-800">
                    <span className="font-semibold">Recommended:</span> Upload at least 2 pictures of design product in free view
                  </p>
                </div>

                <div className="space-y-3 sm:space-y-4">
                  {mediaFiles.map((media, index) => (
                    <div key={media.id} className="border border-gray-200 rounded-lg p-2.5 sm:p-4">
                      <div className="flex items-center justify-between mb-2 sm:mb-3">
                        <span className="text-xs sm:text-sm font-medium text-gray-700">
                          File {index + 1}
                        </span>
                        {mediaFiles.length > 1 && (
                          <button
                            type="button"
                            onClick={() => removeMediaSection(media.id)}
                            className="text-red-600 hover:text-red-800 p-0.5"
                            aria-label="Remove file section"
                          >
                            <Trash2 className="h-3 sm:h-4 w-3 sm:w-4" />
                          </button>
                        )}
                      </div>

                      {/* File Upload */}
                      <div className="border-2 border-dashed border-gray-300 rounded-lg p-2.5 sm:p-4 text-center hover:border-indigo-500 transition-colors relative mb-2 sm:mb-3">
                        {media.preview ? (
                          <div className="space-y-2">
                            {media.fileType === 'VIDEO' ? (
                              <video 
                                src={media.preview} 
                                className="max-h-32 mx-auto rounded"
                                controls
                              />
                            ) : (
                              <img 
                                src={media.preview || ''} 
                                alt="Preview" 
                                className="max-h-32 mx-auto rounded"
                              />
                            )}
                            <button
                              type="button"
                              onClick={() => {
                                setMediaFiles(mediaFiles.map(m => 
                                  m.id === media.id 
                                    ? { ...m, file: null, preview: null }
                                    : m
                                ))
                              }}
                              className="text-xs sm:text-sm text-indigo-700 hover:text-indigo-900 font-medium"
                            >
                              Change file
                            </button>
                          </div>
                        ) : (
                          <div>
                            <div className="flex justify-center mb-1.5 sm:mb-2">
                              <Upload className="h-5 sm:h-8 w-5 sm:w-8 text-gray-400" />
                            </div>
                            <p className="text-xs sm:text-sm text-gray-600 mb-0.5 sm:mb-1">Click to upload or drag and drop</p>
                            <p className="text-[10px] sm:text-xs text-gray-500">Images: PNG, JPG, GIF | Videos: MP4, MOV, AVI</p>
                          </div>
                        )}
                        <input
                          type="file"
                          accept="image/*,video/*"
                          onChange={(e) => {
                            const file = e.target.files?.[0]
                            if (file) handleFileChange(media.id, file)
                          }}
                          className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                          title="Upload media file"
                        />
                      </div>

                      {/* Access Type Selection */}
                      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
                        <span className="text-xs sm:text-sm text-gray-600 flex-shrink-0">Access Type:</span>
                        <div className="flex space-x-1.5 sm:space-x-2 flex-wrap">
                          <button
                            type="button"
                            onClick={() => updateMediaAccessType(media.id, 'FREE')}
                            className={`inline-flex items-center px-2 sm:px-3 py-1 text-[10px] sm:text-xs rounded whitespace-nowrap ${
                              media.accessType === 'FREE'
                                ? 'bg-green-100 text-green-800'
                                : 'bg-gray-100 text-gray-600 hover:bg-green-50'
                            }`}
                          >
                            <Eye className="h-2.5 sm:h-3 w-2.5 sm:w-3 mr-0.5 sm:mr-1 flex-shrink-0" />
                            Free View
                          </button>
                          <button
                            type="button"
                            onClick={() => updateMediaAccessType(media.id, 'PREMIUM')}
                            className={`inline-flex items-center px-2 sm:px-3 py-1 text-[10px] sm:text-xs rounded whitespace-nowrap ${
                              media.accessType === 'PREMIUM'
                                ? 'bg-purple-100 text-purple-800'
                                : 'bg-gray-100 text-gray-600 hover:bg-purple-50'
                            }`}
                          >
                            <Lock className="h-2.5 sm:h-3 w-2.5 sm:w-3 mr-0.5 sm:mr-1 flex-shrink-0" />
                            Premium
                          </button>
                        </div>
                      </div>

                      {/* Filename Input - Outside upload container */}
                      {media.file && (
                        <div className="mt-2 p-2 sm:p-3 bg-gray-50 rounded-lg border border-gray-200">
                          <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1.5">
                            Filename
                          </label>
                          <input
                            type="text"
                            value={media.displayName || ''}
                            onChange={(e) => setMediaFiles(mediaFiles.map(m =>
                              m.id === media.id
                                ? { ...m, displayName: e.target.value }
                                : m
                            ))}
                            className="w-full text-xs sm:text-sm border border-gray-300 rounded px-2.5 py-1.5 bg-white text-gray-900 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                            placeholder="Enter filename"
                          />
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>

              {/* Form Fields */}
              <div className="space-y-3.5 sm:space-y-6">
                <div>
                  <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1.5 sm:mb-2">
                    <Type className="inline h-3 sm:h-4 w-3 sm:w-4 mr-1" />
                    Title <span className="text-red-500">*</span>
                  </label>
                  <input
                    ref={titleInputRef}
                    type="text"
                    value={formData.title}
                    onChange={(e) => {
                      setFormData({...formData, title: e.target.value})
                      if (e.target.value.trim() && errorMessage?.includes('title')) {
                        setErrorMessage(null)
                      }
                    }}
                    className={`w-full border rounded-lg px-2.5 sm:px-3 py-1.5 sm:py-2 text-xs sm:text-sm focus:ring-2 focus:border-indigo-500 text-black transition-colors ${
                      errorMessage && !formData.title.trim() 
                        ? 'border-red-500 ring-2 ring-red-200 focus:ring-red-500' 
                        : 'border-gray-300 focus:ring-indigo-500'
                    }`}
                    placeholder="Enter design title"
                    required
                  />
                </div>

                <div>
                  <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1.5 sm:mb-2">
                    <FileText className="inline h-3 sm:h-4 w-3 sm:w-4 mr-1" />
                    Description
                  </label>
                  <textarea
                    value={formData.description}
                    onChange={(e) => setFormData({...formData, description: e.target.value})}
                    rows={3}
                    className="w-full border border-gray-300 rounded-lg px-2.5 sm:px-3 py-1.5 sm:py-2 text-xs sm:text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-black"
                    placeholder="Describe your design..."
                  />
                </div>

                <div>
                  <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1.5 sm:mb-2">
                    <DollarSign className="inline h-3 sm:h-4 w-3 sm:w-4 mr-1" />
                    Regular Price
                  </label>
                  <div className="flex gap-2">
                    <select
                      value={formData.currency}
                      onChange={(e) => setFormData({...formData, currency: e.target.value})}
                      className="border border-gray-300 rounded-lg px-2 sm:px-3 py-1.5 sm:py-2 text-xs sm:text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-black bg-gray-50"
                      title="Select currency"
                    >
                      <option value="USD">≡ƒç║≡ƒç╕ USD</option>
                      <option value="NGN">≡ƒç│≡ƒç¼ NGN</option>
                    </select>
                    <input
                      type="number"
                      step={formData.currency === 'NGN' ? '1' : '0.01'}
                      min="0"
                      value={formData.price}
                      onChange={(e) => setFormData({...formData, price: e.target.value})}
                      className="flex-1 border border-gray-300 rounded-lg px-2.5 sm:px-3 py-1.5 sm:py-2 text-xs sm:text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-black"
                      placeholder={formData.currency === 'NGN' ? '0' : '0.00'}
                      required
                    />
                  </div>
                  <p className="text-[10px] sm:text-xs text-gray-500 mt-1">
                    {formData.currency === 'NGN' 
                      ? 'Enter price in Nigerian Naira. It will be converted to USD for international buyers.'
                      : 'Enter price in US Dollars. Nigerian buyers will see the NGN equivalent.'}
                  </p>
                </div>

                <div>
                  <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1.5 sm:mb-2">
                    Buying Options
                  </label>
                  <select
                    value={formData.buyingTypes}
                    onChange={(e) => setFormData({...formData, buyingTypes: e.target.value})}
                    className="w-full border border-gray-300 rounded-lg px-2.5 sm:px-3 py-1.5 sm:py-2 text-xs sm:text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-black"
                    title="Select buying options"
                  >
                    <option value="REGULAR">Regular Only (Multiple buyers allowed)</option>
                    <option value="OWNERSHIP">Ownership Only (Single buyer, exclusive)</option>
                    <option value="BOTH">Both Options Available</option>
                  </select>
                </div>

                {(formData.buyingTypes === 'OWNERSHIP' || formData.buyingTypes === 'BOTH') && (
                  <div>
                    <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1.5 sm:mb-2">
                      <DollarSign className="inline h-3 sm:h-4 w-3 sm:w-4 mr-1" />
                      Ownership Price ({formData.currency})
                    </label>
                    <input
                      type="number"
                      step={formData.currency === 'NGN' ? '1' : '0.01'}
                      min="0"
                      value={formData.ownershipPrice}
                      onChange={(e) => setFormData({...formData, ownershipPrice: e.target.value})}
                      className="w-full border border-gray-300 rounded-lg px-2.5 sm:px-3 py-1.5 sm:py-2 text-xs sm:text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-black"
                      placeholder={formData.currency === 'NGN' ? '0' : '0.00'}
                      required={formData.buyingTypes === 'OWNERSHIP' || formData.buyingTypes === 'BOTH'}
                    />
                    <p className="text-[10px] sm:text-xs text-gray-500 mt-1">
                      Higher price for exclusive ownership and branding rights
                    </p>
                  </div>
                )}

                {(formData.buyingTypes === 'OWNERSHIP' || formData.buyingTypes === 'BOTH') && (
                  <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 sm:p-4 space-y-3">
                    <h3 className="text-sm font-semibold text-blue-900 flex items-center gap-2">
                      <CheckCircle className="h-5 w-5 text-blue-600" />
                      Ownership Transfer Agreement
                    </h3>
                    <p className="text-xs sm:text-sm text-blue-800">
                      By selecting ownership, you're agreeing to transfer exclusive rights to the design buyer. A legally binding contract will be created and both parties will receive a copy.
                    </p>

                    <div className="bg-white border border-blue-300 rounded p-3 max-h-40 overflow-y-auto text-xs sm:text-sm text-gray-700">
                      <p className="font-semibold mb-2">Contract Preview:</p>
                      <p className="mb-2">This Design Ownership Transfer Agreement grants exclusive ownership of the design to the buyer. The designer retains no rights to use, modify, or distribute the design after the transfer is complete.</p>
                      <p className="text-[11px] text-gray-600">Full legal contract will be displayed to buyer before purchase completion.</p>
                    </div>

                    <div className="space-y-2">
                      <div>
                        <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">
                          Full Name <span className="text-red-500">*</span>
                        </label>
                        <input
                          type="text"
                          value={ownershipData.sellerFullName}
                          onChange={(e) => setOwnershipData({...ownershipData, sellerFullName: e.target.value})}
                          className="w-full border border-gray-300 rounded px-2.5 py-1.5 text-xs sm:text-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-black"
                          placeholder="Your full legal name"
                        />
                      </div>

                      <div>
                        <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1">
                          Username (Optional)
                        </label>
                        <input
                          type="text"
                          value={ownershipData.sellerUsername}
                          onChange={(e) => setOwnershipData({...ownershipData, sellerUsername: e.target.value})}
                          className="w-full border border-gray-300 rounded px-2.5 py-1.5 text-xs sm:text-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-black"
                          placeholder="Your platform username (optional)"
                        />
                      </div>

                      <div>
                        <SignaturePad 
                          onSignatureChange={(sig) => setOwnershipData({...ownershipData, sellerSignature: sig})}
                          label="Your Signature"
                        />
                      </div>
                    </div>

                    <div className="space-y-3 border-t border-blue-300 pt-3 mt-3">
                      <h4 className="text-sm font-semibold text-blue-900 flex items-center gap-2">
                        <Eye className="h-4 w-4" />
                        Preview File for Escrow <span className="text-red-500">*</span>
                      </h4>
                      <p className="text-xs text-blue-800">
                        Upload an image or video (max 2 min) that buyers will view during the 7-day escrow period before ownership transfer finalizes.
                      </p>
                      
                      <div>
                        <label className="block text-xs font-medium text-blue-900 mb-1">
                          Preview File (Image or Video) <span className="text-red-500">*</span>
                        </label>
                        <input
                          type="file"
                          accept="image/*,video/*"
                          onChange={(e) => {
                            const file = e.target.files?.[0]
                            if (file) {
                              if (file.type.startsWith('video/') && file.size > 100 * 1024 * 1024) {
                                setErrorMessage('Video must be less than 100MB')
                              } else if (file.type.startsWith('image/') && file.size > 50 * 1024 * 1024) {
                                setErrorMessage('Image must be less than 50MB')
                              } else {
                                setOwnershipData({...ownershipData, previewFile: file})
                                setErrorMessage(null)
                              }
                            }
                          }}
                          className="w-full border border-blue-300 rounded px-2.5 py-1.5 text-xs focus:ring-2 focus:ring-blue-500"
                        />
                        {ownershipData.previewFile && (
                          <p className="text-xs text-blue-700 mt-1">
                            Selected: {ownershipData.previewFile.name}
                          </p>
                        )}
                      </div>

                      <div>
                        <label className="block text-xs font-medium text-blue-900 mb-1">
                          Preview Description (Optional)
                        </label>
                        <textarea
                          value={ownershipData.previewDescription}
                          onChange={(e) => setOwnershipData({...ownershipData, previewDescription: e.target.value})}
                          placeholder="Describe what buyers will see in this preview"
                          className="w-full border border-blue-300 rounded px-2.5 py-1.5 text-xs focus:ring-2 focus:ring-blue-500 text-black resize-none"
                          rows={2}
                        />
                      </div>
                    </div>

                    <div className="bg-blue-100 border border-blue-300 rounded p-2.5 text-xs sm:text-sm text-blue-900">
                      Γ£ô By providing your details above, you agree to the Ownership Transfer Agreement and accept that the buyer will have exclusive rights to this design.
                    </div>
                  </div>
                )}

                <div>
                  <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1.5 sm:mb-2">
                    Category
                  </label>
                  <select
                    value={formData.category}
                    onChange={(e) => setFormData({...formData, category: e.target.value})}
                    className="w-full border border-gray-300 rounded-lg px-2.5 sm:px-3 py-1.5 sm:py-2 text-xs sm:text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-black"
                    title="Select design category"
                  >
                    {categories.map(category => (
                      <option key={category} value={category}>{category}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-xs sm:text-sm font-medium text-gray-700 mb-1.5 sm:mb-2">
                    <Tag className="inline h-3 sm:h-4 w-3 sm:w-4 mr-1" />
                    Tags
                  </label>
                  <input
                    type="text"
                    value={formData.tags}
                    onChange={(e) => setFormData({...formData, tags: e.target.value})}
                    className="w-full border border-gray-300 rounded-lg px-2.5 sm:px-3 py-1.5 sm:py-2 text-xs sm:text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-black"
                    placeholder="e.g. summer,dress,elegant (comma-separated)"
                  />
                </div>
              </div>
            </div>

            <div className="mt-4 sm:mt-8 flex justify-end gap-2.5 sm:gap-4">
              <button
                type="button"
                onClick={() => router.back()}
                className="px-4 sm:px-6 py-1.5 sm:py-2 border border-gray-300 rounded-lg text-xs sm:text-sm text-gray-700 hover:bg-gray-50 transition-colors"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={isUploading}
                className="px-4 sm:px-6 py-1.5 sm:py-2 bg-indigo-700 text-white rounded-lg hover:bg-indigo-800 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-1.5 sm:gap-2 font-medium text-xs sm:text-sm"
              >
                {isUploading ? (
                  <>
                    <div className="animate-spin h-3 sm:h-4 w-3 sm:w-4 border-2 border-white border-t-transparent rounded-full" />
                    Uploading...
                  </>
                ) : (
                  <>
                    <Upload className="h-3 sm:h-4 w-3 sm:w-4" />
                    Upload Design
                  </>
                )}
              </button>
            </div>
          </form>
          </div>
        </div>
      </div>
    </div>
  )
}

import { useState } from 'react'
import { Package } from 'lucide-react'

interface ProductImageProps {
  src: string | null | undefined
  alt: string
  className?: string
  containerClassName?: string
  fallbackClassName?: string
}

export function ProductImage({
  src,
  alt,
  className = 'w-full h-full object-cover',
  containerClassName = 'w-full h-full rounded-lg overflow-hidden bg-gray-200 flex items-center justify-center',
  fallbackClassName = 'w-8 h-8 text-gray-400',
}: ProductImageProps) {
  const [imageError, setImageError] = useState(false)
  const [isLoading, setIsLoading] = useState(!!src)

  // If no src or image failed to load, show fallback
  if (!src || !src.trim() || imageError) {
    return (
      <div className={containerClassName}>
        <Package className={fallbackClassName} />
      </div>
    )
  }

  return (
    <div className={containerClassName}>
      <img
        src={src}
        alt={alt}
        className={className}
        onError={() => setImageError(true)}
        onLoad={() => setIsLoading(false)}
        style={{ display: imageError ? 'none' : 'block' }}
      />
      {isLoading && (
        <div className="absolute inset-0 bg-gray-200 animate-pulse" />
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import Image from 'next/image'
import { X, Upload } from 'lucide-react'

interface ProfileImageModalProps {
  isOpen: boolean
  onClose: () => void
  imageUrl: string | null
  userName: string
  isOwnProfile: boolean
  onImageUpload?: (file: File) => Promise<void>
  isUploading?: boolean
}

export default function ProfileImageModal({
  isOpen,
  onClose,
  imageUrl,
  userName,
  isOwnProfile,
  onImageUpload,
  isUploading = false
}: ProfileImageModalProps) {
  const [uploading, setUploading] = useState(false)

  if (!isOpen) return null

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file || !onImageUpload) return

    try {
      setUploading(true)
      await onImageUpload(file)
    } finally {
      setUploading(false)
    }
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-75 z-50 flex items-center justify-center p-4">
      {/* Modal Container */}
      <div className="bg-white rounded-lg max-w-2xl w-full max-h-[90vh] overflow-hidden flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-200">
          <h2 className="text-lg font-semibold text-black">{userName}'s Profile Picture</h2>
          <button
            onClick={onClose}
            className="text-gray-500 hover:text-gray-700 transition-colors"
            aria-label="Close modal"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Image Container */}
        <div className="flex-1 flex items-center justify-center bg-gray-50 overflow-auto">
          {imageUrl ? (
            <div className="relative w-full h-full flex items-center justify-center">
              <Image
                src={imageUrl}
                alt={`${userName}'s profile`}
                width={600}
                height={600}
                className="max-w-full max-h-full object-contain"
                priority
              />
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center text-gray-400 p-8">
              <div className="w-24 h-24 bg-gradient-to-br from-indigo-400 to-purple-600 rounded-full flex items-center justify-center mb-4">
                <span className="text-4xl">≡ƒæñ</span>
              </div>
              <p className="text-center">No profile picture yet</p>
            </div>
          )}
        </div>

        {/* Footer - Show upload button only for own profile */}
        {isOwnProfile && (
          <div className="p-4 border-t border-gray-200 bg-gray-50 flex gap-2">
            <label className="flex-1">
              <input
                type="file"
                accept="image/*"
                onChange={handleFileSelect}
                disabled={uploading}
                className="hidden"
              />
              <button
                onClick={() => {
                  const fileInput = document.querySelector(
                    'input[type="file"]'
                  ) as HTMLInputElement
                  fileInput?.click()
                }}
                disabled={uploading}
                className="w-full flex items-center justify-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded hover:bg-indigo-700 disabled:opacity-50 transition-colors"
              >
                <Upload className="w-4 h-4" />
                {uploading ? 'Uploading...' : 'Change Picture'}
              </button>
            </label>
            <button
              onClick={onClose}
              className="px-4 py-2 bg-gray-300 text-gray-700 rounded hover:bg-gray-400 transition-colors"
            >
              Close
            </button>
          </div>
        )}

        {/* Footer - Read-only for other users */}
        {!isOwnProfile && (
          <div className="p-4 border-t border-gray-200 bg-gray-50">
            <button
              onClick={onClose}
              className="w-full px-4 py-2 bg-gray-300 text-gray-700 rounded hover:bg-gray-400 transition-colors"
            >
              Close
            </button>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import toast from 'react-hot-toast'
import { useRouter } from 'next/navigation'
import { ChevronRight, ChevronLeft, Upload, CheckCircle, Loader2 } from 'lucide-react'
import _Image from 'next/image'

const STEPS = [
  { number: 1, title: 'Quick Profile', time: '2 mins' },
  { number: 2, title: 'First Product', time: '5 mins' },
  { number: 3, title: 'Photos', time: '5 mins' },
  { number: 4, title: 'Submit', time: '1 min' },
]

const CATEGORIES = [
  'Dresses',
  'Shirts',
  'Pants',
  'Skirts',
  'Accessories',
  'Shoes',
  'Jackets',
  'Other',
]

interface FormData {
  // Step 1
  storeName: string
  category: string
  // Step 2
  productTitle: string
  productDesc: string
  productPrice: string
  // Step 3
  photos: File[]
}

interface FormErrors {
  storeName?: string
  category?: string
  productTitle?: string
  productDesc?: string
  productPrice?: string
  photos?: string
}

export function SellerOnboarding() {
  const router = useRouter()
  const [step, setStep] = useState(1)
  const [loading, setLoading] = useState(false)
  const [formData, setFormData] = useState<FormData>({
    storeName: '',
    category: '',
    productTitle: '',
    productDesc: '',
    productPrice: '',
    photos: [],
  })
  const [errors, setErrors] = useState<FormErrors>({})

  const validateStep = (): boolean => {
    const newErrors: FormErrors = {}

    if (step === 1) {
      if (!formData.storeName.trim()) {
        newErrors.storeName = 'Store name is required'
      }
      if (!formData.category) {
        newErrors.category = 'Category is required'
      }
    } else if (step === 2) {
      if (!formData.productTitle.trim()) {
        newErrors.productTitle = 'Product name is required'
      }
      if (!formData.productDesc.trim()) {
        newErrors.productDesc = 'Product description is required'
      }
      if (!formData.productPrice) {
        newErrors.productPrice = 'Price is required'
      } else if (isNaN(parseFloat(formData.productPrice)) || parseFloat(formData.productPrice) <= 0) {
        newErrors.productPrice = 'Please enter a valid price'
      }
    } else if (step === 3) {
      if (formData.photos.length < 3) {
        newErrors.photos = 'At least 3 photos are required'
      }
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleInputChange = (field: keyof FormData, value: any) => {
    setFormData((prev) => ({ ...prev, [field]: value }))
    // Clear error for this field
    setErrors((prev) => {
      const updated = { ...prev }
      delete updated[field as keyof FormErrors]
      return updated
    })
  }

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || [])
    const newPhotos = [...formData.photos, ...files].slice(0, 10) // Max 10 photos
    handleInputChange('photos', newPhotos)
  }

  const removePhoto = (index: number) => {
    handleInputChange('photos', formData.photos.filter((_, i) => i !== index))
  }

  const handleNext = async () => {
    if (!validateStep()) {
      toast.error('Please fill in all required fields')
      return
    }

    if (step < 4) {
      setStep(step + 1)
    }
  }

  const handleBack = () => {
    if (step > 1) {
      setStep(step - 1)
    }
  }

  const handleSubmit = async () => {
    if (!validateStep()) {
      toast.error('Please complete all fields')
      return
    }

    setLoading(true)

    try {
      // Upload photos first
      const photoUrls: string[] = []

      for (const file of formData.photos) {
        const formDataObj = new FormData()
        formDataObj.append('file', file)
        formDataObj.append('folder', 'boutique-products')

        const uploadRes = await fetch('/api/upload', {
          method: 'POST',
          body: formDataObj,
        })

        if (!uploadRes.ok) {
          throw new Error('Failed to upload photo')
        }

        const uploadData = await uploadRes.json()
        photoUrls.push(uploadData.url)
      }

      // Create seller profile + product
      const response = await fetch('/api/onboarding/quickstart', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          storeName: formData.storeName,
          category: formData.category,
          product: {
            title: formData.productTitle,
            description: formData.productDesc,
            basePrice: parseFloat(formData.productPrice),
            photos: photoUrls,
          },
        }),
      })

      if (!response.ok) {
        const errorData = await response.json()
        throw new Error(errorData.message || 'Failed to create store')
      }

      toast.success('Store created! Admin will review within 24 hours.')
      router.push('/seller/dashboard')
    } catch (error) {
      console.error('Onboarding error:', error)
      toast.error(error instanceof Error ? error.message : 'Failed to create store')
    } finally {
      setLoading(false)
    }
  }

  const progressPercent = (step / 4) * 100

  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-50 to-purple-50 py-8 px-4">
      <div className="max-w-2xl mx-auto">
        {/* Header */}
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold text-gray-900 mb-2">
            Launch Your Store
          </h1>
          <p className="text-gray-600">
            Get your first product live in just 13 minutes
          </p>
        </div>

        {/* Progress */}
        <div className="mb-8">
          <div className="flex justify-between mb-6">
            {STEPS.map((s) => (
              <div key={s.number} className="flex flex-col items-center flex-1">
                <div
                  className={`w-12 h-12 rounded-full flex items-center justify-center font-bold text-lg transition-all ${
                    s.number < step
                      ? 'bg-green-500 text-white'
                      : s.number === step
                      ? 'bg-indigo-600 text-white ring-4 ring-indigo-200'
                      : 'bg-gray-200 text-gray-600'
                  }`}
                >
                  {s.number < step ? (
                    <CheckCircle className="w-6 h-6" />
                  ) : (
                    s.number
                  )}
                </div>
                <div className="text-xs font-medium text-gray-700 mt-2 text-center">
                  {s.title}
                </div>
                <div className="text-xs text-gray-500">{s.time}</div>
              </div>
            ))}
          </div>

          {/* Progress Bar */}
          <div className="w-full bg-gray-200 rounded-full h-2 overflow-hidden">
            <div
              className="bg-gradient-to-r from-indigo-600 to-purple-600 h-2 rounded-full transition-all duration-300"
              style={{ width: `${progressPercent}%` }}
            />
          </div>

          <p className="text-center text-sm text-gray-600 mt-3">
            Step {step} of 4 ΓÇó {13 - step * 3} mins remaining
          </p>
        </div>

        {/* Content Card */}
        <div className="bg-white rounded-2xl shadow-lg p-8 mb-6">
          {/* Step 1: Profile */}
          {step === 1 && (
            <div className="space-y-6 animate-fadeIn">
              <div>
                <h2 className="text-2xl font-bold text-gray-900 mb-2">
                  Let's set up your store
                </h2>
                <p className="text-gray-600">
                  Tell us your name and what you design
                </p>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Store Name *
                </label>
                <input
                  type="text"
                  placeholder="Your name or brand (e.g., 'Zainab's Fashion')"
                  value={formData.storeName}
                  onChange={(e) => handleInputChange('storeName', e.target.value)}
                  className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition ${
                    errors.storeName ? 'border-red-500' : 'border-gray-300'
                  }`}
                />
                {errors.storeName && (
                  <p className="text-red-600 text-sm mt-1">{errors.storeName}</p>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  What do you design? *
                </label>
                <select
                  value={formData.category}
                  onChange={(e) => handleInputChange('category', e.target.value)}
                  className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition ${
                    errors.category ? 'border-red-500' : 'border-gray-300'
                  }`}
                >
                  <option value="">Choose a category...</option>
                  {CATEGORIES.map((cat) => (
                    <option key={cat} value={cat}>
                      {cat}
                    </option>
                  ))}
                </select>
                {errors.category && (
                  <p className="text-red-600 text-sm mt-1">{errors.category}</p>
                )}
              </div>
            </div>
          )}

          {/* Step 2: Product */}
          {step === 2 && (
            <div className="space-y-6 animate-fadeIn">
              <div>
                <h2 className="text-2xl font-bold text-gray-900 mb-2">
                  Add your first product
                </h2>
                <p className="text-gray-600">
                  Tell us about the design you want to sell
                </p>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Product Name *
                </label>
                <input
                  type="text"
                  placeholder="e.g., 'Blue As├╢ke Gown'"
                  value={formData.productTitle}
                  onChange={(e) => handleInputChange('productTitle', e.target.value)}
                  className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition ${
                    errors.productTitle ? 'border-red-500' : 'border-gray-300'
                  }`}
                />
                {errors.productTitle && (
                  <p className="text-red-600 text-sm mt-1">{errors.productTitle}</p>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Description *
                </label>
                <textarea
                  placeholder="Describe your design (colors, materials, style, etc.)"
                  value={formData.productDesc}
                  onChange={(e) => handleInputChange('productDesc', e.target.value)}
                  rows={4}
                  className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition resize-none ${
                    errors.productDesc ? 'border-red-500' : 'border-gray-300'
                  }`}
                />
                {errors.productDesc && (
                  <p className="text-red-600 text-sm mt-1">{errors.productDesc}</p>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Price (Γéª NGN) *
                </label>
                <input
                  type="number"
                  placeholder="5000"
                  min="1"
                  value={formData.productPrice}
                  onChange={(e) => handleInputChange('productPrice', e.target.value)}
                  className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition ${
                    errors.productPrice ? 'border-red-500' : 'border-gray-300'
                  }`}
                />
                {errors.productPrice && (
                  <p className="text-red-600 text-sm mt-1">{errors.productPrice}</p>
                )}
              </div>
            </div>
          )}

          {/* Step 3: Photos */}
          {step === 3 && (
            <div className="space-y-6 animate-fadeIn">
              <div>
                <h2 className="text-2xl font-bold text-gray-900 mb-2">
                  Upload photos (3+)
                </h2>
                <p className="text-gray-600">
                  Show your product from different angles
                </p>
              </div>

              <div className="border-2 border-dashed border-indigo-200 rounded-lg p-8 text-center hover:bg-indigo-50 transition">
                <Upload className="w-8 h-8 text-indigo-600 mx-auto mb-2" />
                <label className="cursor-pointer">
                  <input
                    type="file"
                    multiple
                    accept="image/*"
                    onChange={handlePhotoUpload}
                    className="hidden"
                    disabled={loading}
                  />
                  <p className="text-indigo-600 font-medium">
                    Click to upload photos
                  </p>
                  <p className="text-gray-500 text-sm">
                    or drag and drop
                  </p>
                </label>
              </div>

              {formData.photos.length > 0 && (
                <div>
                  <p className="text-sm font-medium text-gray-700 mb-3">
                    Photos uploaded: {formData.photos.length}/10
                  </p>
                  <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                    {formData.photos.map((photo, idx) => (
                      <div
                        key={idx}
                        className="relative rounded-lg overflow-hidden bg-gray-100 aspect-square group"
                      >
                        <img
                          src={URL.createObjectURL(photo)}
                          alt={`Preview ${idx + 1}`}
                          className="w-full h-full object-cover"
                        />
                        <button
                          onClick={() => removePhoto(idx)}
                          className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center transition"
                        >
                          <span className="text-white text-sm font-bold">Remove</span>
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {errors.photos && (
                <p className="text-red-600 text-sm">{errors.photos}</p>
              )}
            </div>
          )}

          {/* Step 4: Review */}
          {step === 4 && (
            <div className="space-y-6 animate-fadeIn">
              <div>
                <h2 className="text-2xl font-bold text-gray-900 mb-2">
                  Ready to launch?
                </h2>
                <p className="text-gray-600">
                  Review your information before submitting
                </p>
              </div>

              <div className="space-y-4 bg-indigo-50 p-6 rounded-lg border border-indigo-200">
                <div className="flex items-start gap-3">
                  <CheckCircle className="w-5 h-5 text-green-600 mt-0.5 flex-shrink-0" />
                  <div>
                    <p className="font-bold text-gray-900">Store Name</p>
                    <p className="text-gray-700">{formData.storeName}</p>
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <CheckCircle className="w-5 h-5 text-green-600 mt-0.5 flex-shrink-0" />
                  <div>
                    <p className="font-bold text-gray-900">Category</p>
                    <p className="text-gray-700">{formData.category}</p>
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <CheckCircle className="w-5 h-5 text-green-600 mt-0.5 flex-shrink-0" />
                  <div>
                    <p className="font-bold text-gray-900">First Product</p>
                    <p className="text-gray-700">
                      {formData.productTitle} ΓÇó Γéª{parseFloat(formData.productPrice || '0').toLocaleString()}
                    </p>
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <CheckCircle className="w-5 h-5 text-green-600 mt-0.5 flex-shrink-0" />
                  <div>
                    <p className="font-bold text-gray-900">Photos</p>
                    <p className="text-gray-700">{formData.photos.length} uploaded</p>
                  </div>
                </div>
              </div>

              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                <p className="text-sm text-gray-700">
                  Γ£ô Admin will review your product within 24 hours<br />
                  Γ£ô We'll email you updates and next steps<br />
                  Γ£ô You can manage your store anytime
                </p>
              </div>
            </div>
          )}
        </div>

        {/* Navigation Buttons */}
        <div className="flex gap-3">
          {step > 1 && (
            <button
              onClick={handleBack}
              disabled={loading}
              className="flex items-center gap-2 px-6 py-3 border border-gray-300 rounded-lg font-medium text-gray-700 hover:bg-gray-50 transition disabled:opacity-50"
            >
              <ChevronLeft className="w-4 h-4" />
              Back
            </button>
          )}

          <button
            onClick={step === 4 ? handleSubmit : handleNext}
            disabled={loading}
            className="flex-1 flex items-center justify-center gap-2 px-6 py-3 bg-gradient-to-r from-indigo-600 to-purple-600 text-white rounded-lg font-bold hover:opacity-90 transition disabled:opacity-50"
          >
            {loading && step === 4 ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                Creating Store...
              </>
            ) : step === 4 ? (
              <>
                Create Store
                <CheckCircle className="w-4 h-4" />
              </>
            ) : (
              <>
                Next
                <ChevronRight className="w-4 h-4" />
              </>
            )}
          </button>
        </div>
      </div>

      <style jsx>{`
        @keyframes fadeIn {
          from {
            opacity: 0;
            transform: translateY(10px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
        .animate-fadeIn {
          animation: fadeIn 0.3s ease-in-out;
        }
      `}</style>
    </div>
  )
}

'use client';

import { AttributeField } from '@/lib/boutique/product-attributes';

interface ProductAttributesFormProps {
  fields: AttributeField[];
  values: Record<string, any>;
  onChange: (key: string, value: any) => void;
}

export function ProductAttributesForm({
  fields,
  values,
  onChange,
}: ProductAttributesFormProps) {
  if (!fields || fields.length === 0) {
    return null;
  }

  return (
    <>
      {fields.map((field) => (
        <div key={field.key} className="mb-4 sm:mb-6">
          {/* Label */}
          <label className="block text-[10px] sm:text-sm font-medium text-gray-700 mb-1">
            {field.label}
            {field.required && <span className="text-red-500"> *</span>}
          </label>

          {/* Text Input */}
          {field.type === 'text' && (
            <>
              <input
                type="text"
                value={values[field.key] || ''}
                onChange={(e) => onChange(field.key, e.target.value)}
                placeholder={field.placeholder}
                className="w-full px-3 sm:px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-500 text-sm text-gray-900 placeholder:text-gray-400"
              />
            </>
          )}

          {/* Number Input */}
          {field.type === 'number' && (
            <>
              <input
                type="number"
                value={values[field.key] || ''}
                onChange={(e) => onChange(field.key, e.target.value ? parseFloat(e.target.value) : '')}
                placeholder={field.placeholder}
                min={field.min}
                max={field.max}
                className="w-full px-3 sm:px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-500 text-sm text-gray-900 placeholder:text-gray-400"
              />
            </>
          )}

          {/* Select */}
          {field.type === 'select' && field.options && (
            <>
              <select
                value={values[field.key] || ''}
                onChange={(e) => onChange(field.key, e.target.value)}
                className="w-full px-3 sm:px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-500 text-sm text-gray-900"
              >
                <option value="" className="text-gray-900">
                  Select {field.label.toLowerCase()}
                </option>
                {field.options.map((option) => (
                  <option key={option.value} value={option.value} className="text-gray-900">
                    {option.label}
                  </option>
                ))}
              </select>
            </>
          )}

          {/* Multiline Textarea */}
          {field.type === 'multiline' && (
            <>
              <textarea
                value={values[field.key] || ''}
                onChange={(e) => onChange(field.key, e.target.value)}
                placeholder={field.placeholder}
                rows={3}
                className="w-full px-3 sm:px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-500 text-sm text-gray-900 placeholder:text-gray-400 resize-none"
              />
            </>
          )}

          {/* Comma-separated Input */}
          {field.type === 'comma-separated' && (
            <>
              <input
                type="text"
                value={values[field.key] || ''}
                onChange={(e) => onChange(field.key, e.target.value)}
                placeholder={field.placeholder}
                className="w-full px-3 sm:px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-500 text-sm text-gray-900 placeholder:text-gray-400"
              />
            </>
          )}

          {/* Help Text */}
          {field.helpText && (
            <p className="text-[10px] sm:text-xs text-gray-500 mt-1">{field.helpText}</p>
          )}
        </div>
      ))}
    </>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { useSession } from 'next-auth/react';

interface Message {
  id: string;
  senderId: string;
  senderName: string;
  senderRole: 'CLIENT' | 'DESIGNER';
  message: string;
  attachments?: string[];
  timestamp: string;
  readAt?: string;
}

interface ProgressUpdate {
  id?: string;
  message: string;
  photos: string[];
  timestamp: string;
}

interface CommissionMessagesProps {
  commissionId: string;
  commissionStatus: string;
  isDesigner?: boolean;
}

export function CommissionMessages({ 
  commissionId, 
  commissionStatus,
  isDesigner: _isDesigner = false 
}: CommissionMessagesProps) {
  const { data: session } = useSession();
  const [messages, setMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState('');
  const [warning, setWarning] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Statuses where messaging is allowed
  const canMessage = [
    'FORWARDED', 'QUOTED', 'PAID', 'IN_PROGRESS', 
    'DELIVERED', 'REVISION', 'DISPUTED'
  ].includes(commissionStatus);

  // Fetch messages
  useEffect(() => {
    const fetchMessages = async () => {
      try {
        const res = await fetch(`/api/commission-requests/${commissionId}/messages`);
        if (res.ok) {
          const data = await res.json();
          setMessages(data.messages || []);
          
          // Dispatch event to update unread counts (GET marks messages as read)
          window.dispatchEvent(new CustomEvent('messagesRead'));
        }
      } catch {
        console.error('Failed to fetch messages');
      } finally {
        setLoading(false);
      }
    };

    fetchMessages();
    
    // Poll for new messages every 30 seconds
    const interval = setInterval(fetchMessages, 30000);
    return () => clearInterval(interval);
  }, [commissionId]);

  // Scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const sendMessage = async () => {
    if (!newMessage.trim() || sending) return;

    setSending(true);
    setError('');
    setWarning('');

    try {
      const res = await fetch(`/api/commission-requests/${commissionId}/messages`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: newMessage.trim() }),
      });

      if (res.ok) {
        const data = await res.json();
        setMessages(prev => [...prev, data.message]);
        setNewMessage('');
        
        // Show warning if content was filtered
        if (data.warning) {
          setWarning(data.warning);
          // Auto-dismiss warning after 8 seconds
          setTimeout(() => setWarning(''), 8000);
        }
      } else {
        const data = await res.json();
        setError(data.error || 'Failed to send message');
      }
    } catch {
      setError('Failed to send message');
    } finally {
      setSending(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  const formatTime = (timestamp: string) => {
    const date = new Date(timestamp);
    const now = new Date();
    const isToday = date.toDateString() === now.toDateString();
    
    if (isToday) {
      return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    }
    return date.toLocaleDateString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-8">
        <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-pink-500"></div>
      </div>
    );
  }

  return (
    <div className="border rounded-lg bg-gray-50">
      <div className="p-2 sm:p-3 border-b bg-white rounded-t-lg">
        <h4 className="font-medium text-gray-900 flex items-center gap-1.5 sm:gap-2 text-xs sm:text-sm">
          <svg className="w-4 h-4 sm:w-5 sm:h-5 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
          </svg>
          Messages
        </h4>
      </div>

      {/* Messages List */}
      <div className="h-48 sm:h-64 overflow-y-auto p-2 sm:p-3 space-y-2 sm:space-y-3">
        {messages.length === 0 ? (
          <p className="text-gray-500 text-[10px] sm:text-sm text-center py-3 sm:py-4">
            No messages yet. Start the conversation!
          </p>
        ) : (
          messages.map((msg) => {
            const isMyMessage = msg.senderId === session?.user?.id;
            return (
              <div
                key={msg.id}
                className={`flex ${isMyMessage ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-[85%] sm:max-w-[80%] rounded-lg px-2 sm:px-3 py-1.5 sm:py-2 ${
                    isMyMessage
                      ? 'bg-pink-500 text-white'
                      : 'bg-white border text-gray-900'
                  }`}
                >
                  {!isMyMessage && (
                    <p className={`text-[9px] sm:text-xs font-medium mb-0.5 sm:mb-1 ${isMyMessage ? 'text-pink-100' : 'text-gray-500'}`}>
                      {msg.senderName} ({msg.senderRole === 'CLIENT' ? 'Client' : 'Designer'})
                    </p>
                  )}
                  <p className="text-[11px] sm:text-sm whitespace-pre-wrap">{msg.message}</p>
                  <p className={`text-[9px] sm:text-xs mt-0.5 sm:mt-1 ${isMyMessage ? 'text-pink-200' : 'text-gray-400'}`}>
                    {formatTime(msg.timestamp)}
                    {isMyMessage && msg.readAt && ' Γ£ô'}
                  </p>
                </div>
              </div>
            );
          })
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      {canMessage ? (
        <div className="p-2 sm:p-3 border-t bg-white rounded-b-lg">
          {error && (
            <p className="text-red-500 text-[10px] sm:text-xs mb-1.5 sm:mb-2">{error}</p>
          )}
          {warning && (
            <div className="flex items-start gap-1.5 sm:gap-2 p-1.5 sm:p-2 mb-1.5 sm:mb-2 bg-amber-50 border border-amber-200 rounded-lg">
              <svg className="w-3 h-3 sm:w-4 sm:h-4 text-amber-500 flex-shrink-0 mt-0.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
              <p className="text-amber-700 text-[10px] sm:text-xs">{warning}</p>
            </div>
          )}
          <div className="flex gap-1.5 sm:gap-2">
            <textarea
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Type a message..."
              rows={1}
              className="flex-1 px-2 sm:px-3 py-1.5 sm:py-2 border border-gray-300 rounded-lg text-xs sm:text-sm text-gray-900 resize-none focus:ring-2 focus:ring-pink-500 focus:border-transparent"
            />
            <button
              onClick={sendMessage}
              disabled={!newMessage.trim() || sending}
              className="px-2.5 sm:px-4 py-1.5 sm:py-2 bg-pink-500 text-white rounded-lg hover:bg-pink-600 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {sending ? (
                <div className="w-4 h-4 sm:w-5 sm:h-5 border-2 border-white border-t-transparent rounded-full animate-spin" />
              ) : (
                <svg className="w-4 h-4 sm:w-5 sm:h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                </svg>
              )}
            </button>
          </div>
        </div>
      ) : (
        <div className="p-2 sm:p-3 border-t bg-gray-100 rounded-b-lg">
          <p className="text-gray-500 text-[10px] sm:text-sm text-center">
            Messaging is not available for this commission status.
          </p>
        </div>
      )}
    </div>
  );
}

interface ProgressTimelineProps {
  progressUpdates: ProgressUpdate[];
}

export function ProgressTimeline({ progressUpdates }: ProgressTimelineProps) {
  if (!progressUpdates || progressUpdates.length === 0) {
    return null;
  }

  const formatDate = (timestamp: string) => {
    return new Date(timestamp).toLocaleDateString([], {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="border rounded-lg bg-white">
      <div className="p-3 border-b">
        <h4 className="font-medium text-gray-900 flex items-center gap-2">
          <svg className="w-5 h-5 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" />
          </svg>
          Progress Updates
        </h4>
      </div>

      <div className="p-3">
        <div className="relative">
          {/* Timeline line */}
          <div className="absolute left-3 top-0 bottom-0 w-0.5 bg-gray-200" />

          <div className="space-y-4">
            {progressUpdates.map((update, index) => (
              <div key={update.id || index} className="relative pl-8">
                {/* Timeline dot */}
                <div className="absolute left-1.5 top-1.5 w-3 h-3 bg-pink-500 rounded-full border-2 border-white" />

                <div className="bg-gray-50 rounded-lg p-3">
                  <p className="text-sm text-gray-900 whitespace-pre-wrap">{update.message}</p>
                  
                  {/* Progress photos */}
                  {update.photos && update.photos.length > 0 && (
                    <div className="flex flex-wrap gap-2 mt-2">
                      {update.photos.map((photo, photoIdx) => (
                        <a
                          key={photoIdx}
                          href={photo}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="block"
                        >
                          <img
                            src={photo}
                            alt={`Progress ${index + 1} - Photo ${photoIdx + 1}`}
                            className="w-16 h-16 object-cover rounded-lg border hover:opacity-75 transition"
                          />
                        </a>
                      ))}
                    </div>
                  )}
                  
                  <p className="text-xs text-gray-400 mt-2">
                    {formatDate(update.timestamp)}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import Image from 'next/image'
import { useCurrency } from '@/components/CurrencyProvider'

interface Design {
  id: string
  title: string
  description: string | null
  price: number
  imageUrl: string
  category: string
  totalSales: number
  designer: {
    name: string | null
    email: string
    role: string
  }
}

export function FeaturedDesigns() {
  const [designs, setDesigns] = useState<Design[]>([])
  const [loading, setLoading] = useState(true)
  const { formatPrice } = useCurrency()

  useEffect(() => {
    fetchFeaturedDesigns()
  }, [])

  const fetchFeaturedDesigns = async () => {
    try {
      // Fetch from public featured items API for designs only
      const response = await fetch('/api/featured-items?itemType=DESIGN&limit=6')
      if (response.ok) {
        const data = await response.json()
        // Map the API response to Design interface
        setDesigns(data.items?.map((item: any) => ({
          id: item.itemId,
          title: item.title,
          description: null,
          price: item.price || 0,
          imageUrl: item.imageUrl || '',
          category: item.category || 'Design',
          totalSales: item.totalSales || 0,
          designer: {
            name: item.seller?.name,
            email: item.seller?.email || '',
            role: 'seller'
          }
        })) || [])
      } else {
        console.warn('Failed to fetch featured designs, falling back...')
        // Fallback to regular featured designs from old API
        const fallbackResponse = await fetch('/api/designs?featured=true&limit=6')
        if (fallbackResponse.ok) {
          const data = await fallbackResponse.json()
          setDesigns(data.designs?.slice(0, 6) || [])
        }
      }
    } catch (error) {
      console.error('Error fetching featured designs:', error)
      // Fallback to old featured API
      try {
        const response = await fetch('/api/designs?featured=true&limit=6')
        if (response.ok) {
          const data = await response.json()
          setDesigns(data.designs?.slice(0, 6) || [])
        }
      } catch (err) {
        console.error('Error fetching fallback designs:', err)
      }
    } finally {
      setLoading(false)
    }
  }

  if (loading) {
    return (
      <section className="py-5 sm:py-8 lg:py-12 bg-gray-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <h2 className="text-sm sm:text-lg lg:text-2xl font-bold text-gray-900 text-center mb-1 sm:mb-2">Featured Designs</h2>
          <p className="text-[9px] sm:text-xs text-gray-700 text-center mb-3 sm:mb-4 lg:mb-6">Discover trending designs from our community</p>
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-2 sm:gap-3">
            {[1, 2, 3, 4, 5, 6].map((item) => (
              <div key={item} className="bg-white rounded-lg shadow-md overflow-hidden animate-pulse">
                <div className="aspect-square bg-gray-200"></div>
                <div className="p-2 sm:p-3">
                  <div className="h-3 bg-gray-200 rounded mb-1"></div>
                  <div className="h-2 bg-gray-200 rounded mb-1.5 w-1/2"></div>
                  <div className="h-4 bg-gray-200 rounded"></div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>
    )
  }

  return (
    <section className="py-5 sm:py-8 lg:py-12 bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <h2 className="text-sm sm:text-lg lg:text-2xl font-bold text-gray-900 text-center mb-1 sm:mb-2">Featured Designs</h2>
        <p className="text-[9px] sm:text-xs text-gray-700 text-center mb-3 sm:mb-4 lg:mb-6">Discover trending designs from our community</p>
        
        {designs.length === 0 ? (
          <div className="text-center py-4 sm:py-6">
            <div className="text-gray-500 mb-2">
              <svg className="w-10 h-10 sm:w-12 sm:h-12 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
            <h3 className="text-[9px] sm:text-xs font-medium text-gray-900 mb-0.5">No designs available yet</h3>
            <p className="text-[8px] sm:text-[9px] text-gray-600 mb-2 sm:mb-3">Be the first to upload and share your designs!</p>
            <Link href="/upload" className="inline-block bg-indigo-700 hover:bg-indigo-800 text-white px-2 sm:px-4 py-1 sm:py-2 rounded-lg transition-colors font-medium text-[8px] sm:text-xs">
              Upload Design
            </Link>
          </div>
        ) : (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-2 sm:gap-3">
            {designs.map((design) => (
              <div key={design.id} className="bg-white rounded-lg shadow-md overflow-hidden group hover:shadow-lg transition-shadow">
                <div className="aspect-square relative bg-gray-100">
                  {design.imageUrl && design.imageUrl.trim() ? (
                    <Image
                      src={design.imageUrl}
                      alt={design.title}
                      width={400}
                      height={400}
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center bg-gray-200">
                      <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
