import prisma from '@/lib/prisma'

/**
 * Idempotency Key Utilities
 * 
 * Implements idempotent request handling using database storage.
 * Prevents duplicate order creation when requests are retried.
 * 
 * Usage:
 * 1. Extract idempotency key from request header 'Idempotency-Key'
 * 2. Call checkIdempotencyKey() to see if already processed
 * 3. If not, process request and call storeIdempotentResponse()
 */

export const IDEMPOTENCY_KEY_HEADER = 'idempotency-key'

/**
 * Get idempotency key from request headers
 */
export function getIdempotencyKey(headers: Headers): string | null {
  return headers.get(IDEMPOTENCY_KEY_HEADER)
}

/**
 * Check if we've already processed this idempotency key
 * @returns Cached response if exists, null if not found
 */
export async function checkIdempotencyKey(idempotencyKey: string): Promise<any | null> {
  try {
    const record = await prisma.idempotencyKey.findUnique({
      where: { key: idempotencyKey }
    })
    
    if (record) {
      console.log(`[IDEMPOTENCY] Cache hit for key: ${idempotencyKey.substring(0, 8)}...`)
      return record.responseData
    }
    
    return null
  } catch (error) {
    console.error(`[IDEMPOTENCY] Error checking key ${idempotencyKey}:`, error)
    return null
  }
}

/**
 * Store idempotent response for future requests
 * @param idempotencyKey - The idempotency key from request header
 * @param userId - The user ID making the request
 * @param responseData - The response data to cache
 * @param ttlMinutes - Time to live in minutes (default: 1440 = 24 hours)
 */
export async function storeIdempotentResponse(
  idempotencyKey: string,
  userId: string,
  responseData: any,
  ttlMinutes: number = 1440
): Promise<void> {
  try {
    const expiresAt = new Date(Date.now() + ttlMinutes * 60 * 1000)
    
    await prisma.idempotencyKey.upsert({
      where: { key: idempotencyKey },
      create: {
        key: idempotencyKey,
        userId,
        responseData,
        expiresAt
      },
      update: {
        userId,
        responseData,
        expiresAt,
        updatedAt: new Date()
      }
    })
    
    console.log(`[IDEMPOTENCY] Stored response for key: ${idempotencyKey.substring(0, 8)}...`)
  } catch (error) {
    console.error(`[IDEMPOTENCY] Error storing response for key ${idempotencyKey}:`, error)
    // Don't throw - allow request to continue even if caching fails
  }
}

/**
 * Clean up expired idempotency keys (run periodically as cron job)
 */
export async function cleanupExpiredIdempotencyKeys(): Promise<number> {
  try {
    const result = await prisma.idempotencyKey.deleteMany({
      where: {
        expiresAt: { lt: new Date() }
      }
    })
    
    console.log(`[IDEMPOTENCY] Cleaned up ${result.count} expired keys`)
    return result.count
  } catch (error) {
    console.error('[IDEMPOTENCY] Error cleaning up expired keys:', error)
    return 0
  }
}

/**
 * Shared notification polling manager
 * Prevents duplicate API calls when multiple components poll the same endpoints
 * 
 * SSR-safe: Guards against server-side execution where window/setInterval don't exist
 */

type Listener = () => void;

interface CachedData {
  data: unknown;
  timestamp: number;
}

// Check if we're in a browser environment
const isBrowser = typeof window !== 'undefined';

class NotificationManager {
  private listeners: Set<Listener> = new Set();
  private pollingInterval: ReturnType<typeof setInterval> | null = null;
  private messageCache: CachedData | null = null;
  private notificationCache: CachedData | null = null;
  // Pending promises to prevent race conditions on concurrent calls
  private messageFetchPromise: Promise<unknown> | null = null;
  private notificationFetchPromise: Promise<unknown> | null = null;
  private readonly CACHE_TTL = 5000; // 5 seconds cache
  private readonly POLL_INTERVAL = 30000; // 30 seconds

  /**
   * Cleanup resources - used during HMR to prevent memory leaks
   */
  cleanup() {
    this.stopPolling();
    this.listeners.clear();
    this.messageCache = null;
    this.notificationCache = null;
    this.messageFetchPromise = null;
    this.notificationFetchPromise = null;
  }

  /**
   * Subscribe to notification updates
   * Returns unsubscribe function
   */
  subscribe(listener: Listener): () => void {
    // Only allow subscriptions in browser
    if (!isBrowser) {
      return () => {}; // No-op unsubscribe for SSR
    }
    
    this.listeners.add(listener);
    
    // Start polling if this is the first subscriber
    if (this.listeners.size === 1) {
      this.startPolling();
    }
    
    return () => {
      this.listeners.delete(listener);
      // Stop polling if no more subscribers
      if (this.listeners.size === 0) {
        this.stopPolling();
      }
    };
  }

  private startPolling() {
    if (!isBrowser || this.pollingInterval) return;
    
    this.pollingInterval = setInterval(() => {
      this.notifyListeners();
    }, this.POLL_INTERVAL);
  }

  private stopPolling() {
    if (this.pollingInterval) {
      clearInterval(this.pollingInterval);
      this.pollingInterval = null;
    }
  }

  private notifyListeners() {
    // Invalidate caches
    this.messageCache = null;
    this.notificationCache = null;
    
    this.listeners.forEach(listener => listener());
  }

  /**
   * Trigger an immediate refresh (e.g., after reading a message)
   */
  triggerRefresh() {
    this.notifyListeners();
  }

  /**
   * Fetch messages with deduplication
   * Uses pending promise pattern to prevent concurrent duplicate requests
   */
  async fetchMessages(): Promise<unknown> {
    if (!isBrowser) return null;
    
    const now = Date.now();
    
    // Return cached data if still valid
    if (this.messageCache && (now - this.messageCache.timestamp) < this.CACHE_TTL) {
      return this.messageCache.data;
    }
    
    // If there's already a pending request, wait for it instead of making a new one
    if (this.messageFetchPromise) {
      return this.messageFetchPromise;
    }
    
    // Create new fetch promise
    this.messageFetchPromise = (async () => {
      try {
        const res = await fetch('/api/messages/unread-count');
        if (res.ok) {
          const data = await res.json();
          this.messageCache = { data, timestamp: Date.now() };
          return data;
        }
      } catch (error) {
        console.error('Failed to fetch messages:', error);
      } finally {
        // Clear pending promise
        this.messageFetchPromise = null;
      }
      return null;
    })();
    
    return this.messageFetchPromise;
  }

  /**
   * Fetch notifications with deduplication
   * Uses pending promise pattern to prevent concurrent duplicate requests
   */
  async fetchNotifications(limit = 10): Promise<unknown> {
    if (!isBrowser) return null;
    
    const now = Date.now();
    
    // Return cached data if still valid
    if (this.notificationCache && (now - this.notificationCache.timestamp) < this.CACHE_TTL) {
      return this.notificationCache.data;
    }
    
    // If there's already a pending request, wait for it
    if (this.notificationFetchPromise) {
      return this.notificationFetchPromise;
    }
    
    // Create new fetch promise
    this.notificationFetchPromise = (async () => {
      try {
        const res = await fetch(`/api/notifications?limit=${limit}`);
        if (res.ok) {
          const data = await res.json();
          this.notificationCache = { data, timestamp: Date.now() };
          return data;
        }
      } catch (error) {
        console.error('Failed to fetch notifications:', error);
      } finally {
        // Clear pending promise
        this.notificationFetchPromise = null;
      }
      return null;
    })();
    
    return this.notificationFetchPromise;
  }
}

// Singleton instance
export const notificationManager = new NotificationManager();

// HMR cleanup to prevent memory leaks during development
// eslint-disable-next-line @typescript-eslint/no-explicit-any
if (isBrowser && typeof (globalThis as any).module !== 'undefined' && (globalThis as any).module?.hot) {
  (globalThis as any).module.hot.dispose(() => {
    notificationManager.cleanup();
  });
}

// Helper to dispatch refresh event (for backwards compatibility)
export function dispatchMessagesRead() {
  notificationManager.triggerRefresh();
  // Also dispatch legacy event for components not yet migrated
  if (isBrowser) {
    window.dispatchEvent(new CustomEvent('messagesRead'));
  }
}

export function dispatchNotificationUpdate() {
  notificationManager.triggerRefresh();
  if (isBrowser) {
    window.dispatchEvent(new CustomEvent('notificationUpdate'));
  }
}

import prisma from './prisma'
